-- ============================================================
-- Ozbek2d (4/6) — DB kontentinin UZ tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6145 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Qo‘shnining bolasi allaqachon ag‘darilmoqda, menikisi nega hali qimirlamaydi?" kabi taqqoslashlar onalarning eng katta dushmanidir. Unutmang, har bir bola o‘ziga xos va uning rivojlanish jadvali matematik formula emas, shunchaki taxminiy oraliqdir. Biri 3 oyligida, boshqasi 5 oyligida ag‘dariladi; bu ikkinchisi "rivojlanishdan ortda qolganini" anglatmaydi. Taqqoslash sizni stressga soladi, chaqaloq esa tarangligingizni his qiladi. Uning o‘z sur’atini hurmat qiling va kichik yutuqlarini (masalan, boshini tikroq ushlashini) shunchaki nishonlang.') WHERE id = '3aa7065c-48aa-4e3c-a0fe-877781389808';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tanangizni tekshiring: qorin o‘rtasida, kindik chizig‘i bo‘ylab bo‘shliq yoki botiqlikni sezyapsizmi? Bu "Diastaz" (qorin mushaklarining ajralishi) bo‘lishi mumkin. Homiladorlik paytida kengaygan mushaklar hali birlashmagan bo‘lsa, klassik "press" mashqlarini bajarish qat’iyan mumkin emas, chunki bu holatni yanada og‘irlashtirishi mumkin. Avval oddiy nafas mashqlari yoki vakuum mashqini (shifokor ruxsati bilan) bajarib, ichki mushaklarni mustahkamlashingiz kerak. Mashq qilishni boshlashdan oldin diastaz bor-yo‘qligini tekshirish muhim.') WHERE id = '2926fb2b-5ad3-4daf-b451-2b21927c114c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq bilan "kitob o‘qishni" boshlash uchun hech qachon erta emas! U so‘zlarni tushunmasa ham, ovozingiz ohangi, intonatsiyasi va ritmini tinglashni yaxshi ko‘radi. Qalin sahifali, rasmlari ko‘p va yozuvi kam kitoblarni tanlang. Unga rasmlarni ko‘rsatib, "qarang, bu mushuk, u miyovlaydi", deb ayting. Bu odat uning nutqiy rivojlanishini tezlashtiradi va kelajakda kitobga qiziqishini uyg‘otadi. Shuningdek, uni quchog‘ingizga olib kitob o‘qish uyqu oldidan tinchlantiruvchi odatga aylanishi mumkin.') WHERE id = '7f0b6be9-2911-4a47-a448-53c0a1e9d9fe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni qorni bilan yotqizganingizda (tummy time), u qo‘llarini oldinga uzatib, ko‘kragini yerdan ancha ko‘tara olishi kerak. Bu "kobra holati" uning orqa va bo‘yin mushaklari mustahkamlanayotganini ko‘rsatadi. Agar u hali ham qorni bilan yotishni yoqtirmay, yig‘lasa, taslim bo‘lmang. Kuniga 5-10 daqiqalik qisqa mashg‘ulotlarni davom ettiring. Muqobil usul sifatida, uni ko‘kragingiz ustiga yotqizib, o‘zingiz ham yoting; yuzingizni ko‘rish uchun boshini ko‘tarishga ko‘proq intiladi.') WHERE id = 'd283274d-2a11-4684-91a8-ce7b016b2812';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Emizikli onalar orasida "botoks mumkin emas", "sochni bo‘yash mumkin emas" kabi fikrlar keng tarqalgan. Biroq zamonaviy tadqiqotlar soch bo‘yog‘i yoki mahalliy estetik muolajalarning aksariyati ona sutiga o‘tmasligi va chaqaloq uchun xavfsiz ekanini ko‘rsatadi (albatta, ammiaksiz bo‘yoqlar va ishonchli mutaxassislarni tanlash sharti bilan). O‘zingizga g‘amxo‘rlik qilish va chiroyli ko‘rinishni istashingiz onalik vazifalariga zid emas. Baxtli va o‘ziga ishongan ona farzandiga ko‘proq mehr bera oladi.') WHERE id = '989b1bed-bb91-418f-ba9c-66f04eee3377';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi chaqaloqning kulgisi qitiqlashga javoban qahqahaga aylanishi mumkin. Uning qo‘ltiq osti, bo‘yni yoki oyoq kaftlarini muloyimlik bilan qitiqlab, reaksiyasini kuzating. Bu oddiy o‘yin unga o‘z tanasini anglash va sezish qobiliyatini rivojlantirishga yordam beradi. Kulish o‘pka sig‘imini oshiradi va qon aylanishini yaxshilaydi. Uydagi taranglikni kamaytiradigan eng yaxshi dori — chaqaloq qahqahasidir.') WHERE id = '9800dfd4-1a12-46cd-be37-2d51f66e1ad7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning kunduzgi uyqulari qisqarib, lekin soni ko‘paydimi? 3 oylik chaqaloqlar odatda kunduzi 3-4 marta uxlaydi (jami 4-5 soat). Agar u uxlashni istamay, haddan tashqari charchagani uchun yig‘lasa, uni quchog‘ingizda, tebratib yoki aravachada sayr qildirib uxlatishdan tortinmang. "O‘rganib qoladi" degan qo‘rquv bilan uni uyqusiz qoldirish ko‘proq zarar keltiradi. Uyqusiz chaqaloq stress gormoni (kortizol) ishlab chiqaradi, bu esa uning rivojlanishiga salbiy ta’sir qiladi. Asosiy maqsad: Uning uxlashidir, qanday uxlashi esa hozircha ikkinchi darajali.') WHERE id = '1a9dccd0-8134-416f-bb91-5bdf13fc777c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Bugun chaqalog‘ingiz 3 oylik bo‘ldi! Bu katta bosqichdir. Endi "To‘rtinchi trimestr" butunlay yakunlandi. Chaqalog‘ingiz boshini tik tutadi, qo‘llarini birlashtiradi, sizga jilmayadi va balki yon tomonga ag‘darilishga harakat qilayotgandir. U endi o‘ziga xos kichkina shaxs. Bugun uning rivojlanishini baholash uchun pediatr ko‘rigini rejalashtirishingiz mumkin. Ammo eng muhimi, o‘zingizni tabriklang. Siz 90 kundan beri tanaffussiz, kechayu kunduz mehnat qilayotgan qahramonsiz. Bugun o‘zingizga kichik sovg‘a qilishni unutmang!') WHERE id = 'c4888a4d-c53f-4c06-9f8b-73bef82c950b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '4-oyga xush kelibsiz! Endi "To‘rtinchi trimestr" butunlay ortda qoldi. Chaqalog‘ingiz endi shunchaki yeb-uxlaydigan "o‘ram" emas, balki atrofini anglaydigan kichkina inson. Shu oydan boshlab uning uyqu sikllari kattalarnikiga o‘xshay boshlaydi (yuzaki va chuqur uyqu bosqichlari paydo bo‘ladi). Bu o‘zgarish ba’zan uyqu buzilishlariga sabab bo‘lishi mumkin, ammo qo‘rqmang: bu ortga ketish emas, aksincha, rivojlanish belgisidir. Uning miyasi rivojlanmoqda, shunchaki yangi tizimga moslashishga harakat qilyapti.') WHERE id = 'eb18b9d2-6fac-4a33-989e-ff8e3c156809';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizni quchog‘ingizga olganingizda, u tanasini tikroq tutayotgani va boshini erkin boshqarayotganini sezyapsizmi? Bu umurtqa pog‘onasi mustahkamlanayotganini ko‘rsatadi. Endi uni ko‘tarib yurish uchun ergotashuvchining "yuzi olamga qaratilgan" (face out) holatini sinab ko‘rishingiz mumkin (albatta, oyoqlari "M" shaklida bo‘lishi sharti bilan). U atrofni tomosha qilishni yaxshi ko‘radi, ammo ehtiyot bo‘ling: vizual ma’lumotlarning ko‘pligi uni tez charchatishi mumkin. Agar bezovtalansa, darhol yuzini o‘zingizga qarating va tinchlantiring.') WHERE id = '0ffeb288-283a-4150-a4f7-cffdb0482b4c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mening bolam hali ag‘darilmayapti, rivojlanishda kechikyapmizmi?" – degan savol sizga tinchlik bermayotgan bo‘lsa, chuqur nafas oling. Chaqaloqlar odatda 4-6 oy oralig‘ida ag‘darila boshlaydi. Ayrim chaqaloqlar avval qornidan chalqanchasiga, boshqalari esa aksincha ag‘dariladi. Agar chaqalog‘ingiz yonboshiga o‘girilishga urinayotgan bo‘lsa, bu ajoyib boshlanishdir. Unga yordam berish uchun sevimli o‘yinchog‘ini yon tomoniga, qo‘li yetmaydigan masofaga qo‘ying. U o‘yinchoqqa yetish uchun tanasini burishga majbur bo‘ladi. Bu eng yaxshi mashqdir.') WHERE id = '7165cb2d-519b-4d93-9e14-3abc5973a1c2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Sochingiz hali ham to‘kilyaptimi? 4-oy odatda "Tug‘ruqdan keyingi soch to‘kilishi" eng yuqori darajaga yetadigan davrdir. Vannaxonadagi to‘p-to‘p sochlar sizni yig‘latishi mumkin, ammo ishoning, siz kal bo‘lib qolmaysiz. Bu shunchaki homiladorlik paytida "to‘xtab qolgan" soch to‘kilishi endi yuz berayotganidir. Qimmat vitaminlar yoki shampunlar bu jarayonni to‘xtata olmaydi, buning uchun shunchaki vaqt kerak. Sochingizni juda qattiq yig‘maslikka va issiq havo bilan (fen yordamida) ko‘p quritmaslikka harakat qiling. Yangi sochlar ("baby hair") taxminan 6-oydan keyin o‘sa boshlaydi.') WHERE id = 'd0ba1bd8-2d07-4566-8111-997ecbf838c6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bu davrda chaqalog‘ingizning kulgisi endi qahqahaga aylanadi! Uni kuldirish uchun "g‘alati" tovushlar chiqaring, lablaringizni pirpirating yoki qornidan o‘pib, puflang. Kulish diafragmani (nafas olish mushagini) mustahkamlaydi va organizmga ko‘p miqdorda kislorod kirishini ta’minlaydi. Agar u kulish o‘rniga qo‘rqib yig‘lasa (baland ovozdan), demak, asab tizimi hali juda sezgir. Tinchroq o‘yinlarga o‘ting. Har bir chaqaloqning hazilni his qilish qobiliyati turlicha.') WHERE id = '7f993160-1b52-4958-82c0-d5f0cf373852';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Buvilarning sevimli tavsiyasi bo‘lgan "Xodunok" (yurgich) sotib olish haqida o‘ylayapsizmi? Shoshilmang! Zamonaviy ortopedlar va pediatrlar xodunokdan foydalanishni qat’iyan tavsiya etmaydi. Bu moslama chaqaloqning oyoq uchida yurishiga, umurtqa pog‘onasiga erta yuk tushishiga va mustaqil harakat qilishga intilmasligiga (muvozanat saqlashni o‘rganmasligiga) sabab bo‘lishi mumkin. Rivojlanish uchun eng yaxshi joy – pol (gilam yoki mat)dir. U o‘zi emaklashga va tipirchilab harakatlanishga urinsin, bu tabiiy jarayon mushaklarni yanada to‘g‘ri shakllantiradi.') WHERE id = '58105ea4-3801-47f9-97cc-2478fe93cb03';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz qo‘liga tushgan hamma narsani og‘ziga solyaptimi? Bu «oral davr» faollashganidan dalolat beradi. U dunyoni og‘zi bilan «tatib», o‘rganadi. Bu, albatta, tishi chiqayotganini anglatmaydi (garchi milklarida qichishish bo‘lishi mumkin). Unga turli tuzilishdagi tish qashlagichlar bering. Ammo eng muhimi — xavfsizlik: polda yoki stol ustida mayda buyumlar (tugma, tanga, munchoq) qoldirmang. Bu oylarda qo‘l harakatlari chaqqonlashgani sababli bo‘g‘ilib qolish xavfi ortadi. Uyni «chaqaloq nigohi bilan» tekshirib chiqing.') WHERE id = '3d44726d-b011-4c60-a3ce-d4d40cf54d8f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Kechqurun chaqalog‘ingiz sutni rad etayotganini, ko‘krakni olmayotganini yoki yig‘lab emayotganini sezyapsizmi? Bu «soxta sutdan bosh tortish» deb ataladi. Buning sababi sutning kamligi emas, balki chaqaloqning charchagani yoki haddan tashqari ko‘p ta’sirga uchraganidir. Uni tinchlantirish uchun «oq shovqin» (white noise) qo‘ying, xonani qorong‘ilashtiring yoki yurib emizing. Agar u yana rad etsa, majburlamang, 15-20 daqiqa tanaffus qiling, tinchlantiring va yana urinib ko‘ring.') WHERE id = '01937078-adcb-4cc4-9337-fd91b288734f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizning kunduzgi uyqusi qisqargan bo‘lsa (30-45 daqiqa), bu tabiiy. 4-oyda uyqu sikllari o‘zgaradi va chaqaloq bir sikldan boshqasiga o‘tayotganda (yengil uyg‘onish paytida) yana uxlab qola olmaydi. Unga yordam berish uchun uyg‘onishi bilan darhol chiroqni yoqmang; yoniga yoting, ohista «sh-sh» deb tinchlantiring yoki qo‘lingizni ko‘ksiga qo‘yib, yengil bosib turing. Bu «uyquni uzaytirish» usuli (resettling) vaqt o‘tishi bilan unga uyqu sikllarini birlashtirishni o‘rgatadi.') WHERE id = '42ae96e6-578f-4958-b69b-9e931b862da2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Chaqalog‘ingiz bilan birga 100 kunni ortda qoldirdingiz! Ayrim Osiyo madaniyatlarida bu kun alohida nishonlanadi, chunki chaqaloq eng nozik davridan o‘tib oldi, deb hisoblanadi. Ortga nazar soling: o‘sha kichkina, himoyasiz chaqaloq endi sizga jilmayadigan, sizni taniydigan va qo‘llari bilan o‘ynaydigan bir shaxsga aylandi. Siz ham o‘zgardingiz, ulg‘aydingiz va kuchliroq bo‘ldingiz. Bugun o‘zingizga bir finjon qahva quying, galereyangizdagi ilk kunlarda olingan suratlarga qarang va «Men uddaladim!» deng. Siz ajoyibsiz!') WHERE id = '000749db-379b-4eae-a0cc-18c3f43ee041';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz tunda tez-tez uyg‘ona boshladimi? «4-oydagi uyqu regressiyasi»ga xush kelibsiz! Aslida, bu ortga ketish emas, balki chaqaloq miyasi rivojlanishidagi ulkan sakrashdir. Uning uyqu sikllari o‘zgarib, kattalarniki kabi «yuzaki» va «chuqur» uyqu bosqichlariga bo‘linadi. Chaqaloq bir bosqichdan boshqasiga o‘tayotganda (har 45-60 daqiqada) yengil uyg‘onadi va yana uxlab qolishni bilmagani uchun yig‘laydi. Bu vaqtinchalik davr (2-6 hafta davom etishi mumkin). Sabrli bo‘ling, odatdagi usullarni (tebratish, emizish) birdaniga o‘zgartirmang, shunchaki yonida ekaningizni his qildiring.') WHERE id = '70ef5cd6-e529-4523-a7e3-dac3c50ee881';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni qorni bilan yotqizganingizda (tummy time), u endi nafaqat boshini, balki ko‘kragini ham yerdan ko‘tarib, qo‘llarini oldinga uzatgancha «suzishga» urinayotganini ko‘ryapsizmi? Bu uning orqa mushaklari mustahkamlanayotganini ko‘rsatadi. Ayrim chaqaloqlar bu davrda qornidan chalqanchasiga (tasodifan, boshining og‘irligi ta’sirida) ag‘darilishi mumkin. Bu katta quvonch, ammo ayni paytda xavf belgisi hamdir: endi uni divan yoki karavotda yolg‘iz qoldirish qat’iyan mumkin emas! Shu oydan boshlab yiqilish xavfi keskin ortadi.') WHERE id = '71d4a5bb-ec66-43a8-8e47-cf600b05a37e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq emish paytida tez-tez chalg‘ishi sizni xavotirga solyaptimi? U bir-ikki marta emadi-da, keyin boshini burib, xonadagi tovush yoki yorug‘likka qaraydi. Bu holatni "Qiziquvchan chaqaloq sindromi" deb atashadi. U atrofni o‘rganishni xohlaydi, emish esa unga "zerikarli" tuyuladi. Yechim: emizish vaqtida xonani imkon qadar tinch va xira yorug‘ qiling, uni chalg‘itadigan narsalarni (telefon, televizor, yorqin o‘yinchoqlar) olib qo‘ying. Tunda yoki uyqusiragan paytida u yaxshiroq emishini ko‘rasiz.') WHERE id = 'bce582cc-6b95-467c-98a1-35d2509fd4d5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizning so‘lagi oqishi hali ham davom etyaptimi va u qo‘liga tushgan hamma narsani (o‘yinchoq, ko‘rpa, sizning barmog‘ingizni) qattiq kemiryaptimi? Buning sababi — tish milklarining qichishishi. Tish hali ko‘rinmasa ham, milk ostida harakatlanmoqda va bu unga noqulaylik tug‘diradi. Unga sovitilgan (muzlatilgan emas!) tish qashlagich yoki toza, nam mato berib, tish milklarini uqalashiga yordam berishingiz mumkin. Bu og‘riqni kamaytiradi va uni tinchlantiradi.') WHERE id = 'c2f4aabf-8bc7-487e-b896-7f21d18143b1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz siz xonadan chiqqaningizda yig‘laydi-yu, qaytishingiz bilan tinchlanadimi? Tabriklaymiz, bu uning xotirasi rivojlanayotganini va sizni boshqa odamlardan ajrata olishini ko‘rsatadi! U endi "obyektning doimiyligi"ni (biror narsa ko‘zdan g‘oyib bo‘lsa, yo‘q bo‘lib ketmaydi, shunchaki joyi o‘zgaradi) tushuna boshlaydi, ammo bunga hali to‘liq amin emas. U bilan "Ku-ku" (bekinmachoq) o‘yinini o‘ynab, bu qo‘rquvni yengishiga yordam berishingiz mumkin. Yuzingizni qo‘llaringiz bilan berkiting va yana oching — bu oddiy o‘yin unga "onam ketsa ham, yana qaytib keladi" degan tushunchani beradi.') WHERE id = '807256c5-09ac-42f8-a6ba-9c88ea7f39a0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Sutim endi yog‘li emas", "Sutim suvga o‘xshaydi" degan o‘ylarga berilmang. Ona sutining tarkibi chaqaloq ehtiyojlariga qarab doimiy ravishda o‘zgarib turadi. Dastlabki oylardagi quyuq, sarg‘ish sut hozir suyuqroq ko‘rinishi mumkin, ammo bu uning sifatsizligini anglatmaydi. Bu oyda chaqaloqning suvga bo‘lgan ehtiyojini qondirish uchun sut tarkibidagi suv miqdori ortadi (shuning uchun qo‘shimcha suv berishga hojat yo‘q). Tabiat hammasini mukammal tarzda tartibga solgan, tanangizga ishoning.') WHERE id = 'd807fc3e-ee9d-408b-880a-d8041fef08ed';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq chiqaradigan tovushlar ("a-gu", "ba-ba", "qi-qi") shunchaki shovqin emas, bu nutq rivoji uchun mashqdir. U tovush chiqarganida, siz ham unga xuddi shu tovush yoki oddiy so‘zlar bilan javob bering ("Ha, shundaymi? Rostdanmi?"). Tadqiqotlar ota-onasi bilan "navbatma-navbat suhbatlashadigan" chaqaloqlarning IQ darajasi va til qobiliyati kelajakda yuqoriroq bo‘lishini ko‘rsatadi. U bilan katta odam bilan gaplashgandek suhbatlashing. U sizni tushunmasa ham, ohang va muloqot qoidalarini o‘rganadi.') WHERE id = '8c9eeb48-f7d1-4cb1-abda-c8b5acd82625';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni ko‘tarib yurishdan belingiz va qo‘llaringiz og‘riyaptimi? Bu "ona bilagi" (De Quervain tenosinoviti) yoki umurtqa pog‘onasi bilan bog‘liq muammolarga olib kelishi mumkin. Chaqaloqni ko‘tarayotganda belingizni emas, tizzalaringizni bukib (o‘tirib-turish mashqidagi kabi) ko‘taring. Emizayotganda chaqaloqning og‘irligi qo‘lingizga tushmasligi uchun tirsagingiz ostiga albatta yostiq qo‘ying. Shuningdek, ergonomik ryukzak yoki slingdan foydalanish yukni teng taqsimlab, sizga qulaylik yaratishi mumkin. Sog‘lig‘ingizni asrang, chaqalog‘ingizga sog‘lom bo‘lib kerakligingizni unutmang.') WHERE id = '43116043-105f-43ce-b935-0d355f71fac9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning rangli, ovozli va chiroqli o‘yinchoqlarga qiziqishi ortadi. Ammo e’tibor bering: "Haddan tashqari stimulyatsiya" (overstimulation) degan chegara bor. Agar chaqaloq birdan yig‘lay boshlasa, boshini o‘girsa yoki ko‘zlarini yumsa, bu uning "Bo‘ldi! Miyam charchadi!" deyish usulidir. Bunday holatda barcha o‘yinchoqlarni yig‘ishtiring, shovqinni to‘xtating va uni ohista bag‘ringizga bosing. Ba’zan eng yaxshi o‘yinchoq – shunchaki sukunat va ona quchog‘idir.') WHERE id = 'b4ee2099-bc1d-4919-b3ee-ba22dc951100';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Oynaga qaraganingizda hali ham homiladorlikdan qolgan cho‘zilish izlarini (striyalarni) ko‘rib xafa bo‘lasizmi? Unutmang, bu izlar sizning onalik nishoningizdir. Vaqt o‘tishi bilan ular oltin rangdan kumush tusga kirib, asta-sekin oqaradi. Ularni butunlay yo‘qotish qiyin bo‘lsa-da, terini namlantirish va massaj qilish ko‘rinishini yaxshilashi mumkin. Ammo eng muhimi, bu tana bir insonni yaratdi va voyaga yetkazmoqda. O‘zingizga nisbatan shafqatsiz bo‘lmang, siz hozirgi holatingizda ham juda go‘zalsiz.') WHERE id = 'c1675203-e86f-4f0e-b277-4834368fee01';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni chalqancha yotqizganingizda oyoqlarini havoga ko‘tarib ushlashga, hatto og‘ziga olib borishga harakat qiladimi? Bu shunchaki qiziqarli o‘yin emas, balki uning qorin mushaklarini (press) mustahkamlaydigan va o‘z tanasini tanishiga yordam beradigan muhim mashqdir. Bunga to‘sqinlik qilmang, paypoqlarini yeching va oyoq barmoqlari bilan o‘ynashiga imkon bering. Bu harakat umurtqa pog‘onasining pastki qismini cho‘zib, bo‘shashtiradi hamda gaz sanchiqlarini kamaytirishga yordam berishi mumkin.') WHERE id = '5348f17b-ff81-4e2c-b426-336c5630b994';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '4 oylik chaqaloqlarning uyg‘oq qolish oralig‘i (wake window) odatda 1.5 - 2 soatni tashkil qiladi. Agar chaqaloq bundan uzoqroq uyg‘oq qolsa, "haddan tashqari charchash" (overtiredness) holatiga tushadi va uxlab qolishi yanada qiyinlashadi. Soatga qarang: agar oxirgi uyqusidan beri 1.5 soat o‘tgan bo‘lsa va u ko‘zlarini ishqalayotgan bo‘lsa, darhol tinchlantiruvchi uyqu marosimini boshlang. Uyqu vaqtini o‘tkazib yuborish tunda uyg‘onishlar sonini oshirishi mumkin.') WHERE id = '314c334b-e7f8-4072-b418-2d43d8366274';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ba’zan chaqalog‘ingiz ona sutini emayotganda yoki sun’iy aralashma ichayotganda to‘satdan yig‘lab, ovqatlanishdan bosh tortadimi va belini kamondek orqaga qayiradimi? Bu "yashirin reflyuks" belgisi bo‘lishi mumkin. Oshqozon kislotasi qizilo‘ngachga ko‘tarilib, uni achishtiradi. Agar bu holat tez-tez takrorlansa va vazn ortishiga xalaqit bersa, shifokoringiz bilan maslahatlashing. Uyda esa uni ovqatlantirgandan keyin darhol yotqizmang, ovqat oshqozonga yaxshiroq tushishi uchun 15-20 daqiqa tik holatda (yelkangizda) ushlab turing.') WHERE id = '1f5459ab-1bd2-4191-b9fa-6cb6903bc60f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Nega mening bolam hali kulmayapti/ag‘darilmayapti?" deb xavotir olmang. Rivojlanish jadvali musobaqa emas. Ba’zi bolalar "kuzatuvchi" bo‘ladi – ular atrofni xotirjam kuzatadi, keyin esa birdan hamma narsani qila boshlaydi; boshqalari esa "harakatchan" bo‘ladi – doim tipirchilab turadi. Har ikkala holat ham me’yoriy. Chaqaloqni boshqa bolalar bilan (hatto aka-uka yoki opa-singillari bilan ham) taqqoslash sizga faqat stress, unga esa zo‘riqish olib keladi. Uning o‘ziga xos fe’l-atvorini qanday bo‘lsa, shundayligicha qabul qiling va seving.') WHERE id = '6c7ebcbb-cb8d-440f-985f-f7721a4549c7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi chaqaloq o‘z ismini tanib olishi uchun mashqlarni boshlashingiz mumkin. Unga «jonim», «go‘zalim» deb murojaat qilish bilan birga, ismini ham tez-tez ayting. Xonaning boshqa burchagidan ismini chaqirib, siz tomonga o‘giriladimi-yo‘qmi, kuzating. Agar o‘girilib qarasa, katta quvonch bilan munosabat bildiring («Barakalla!»). Bu uning ijtimoiy shaxsi shakllanishidagi ilk qadamdir. U endi bu dunyoda o‘zi alohida bir shaxs ekanini tushuna boshlaydi.') WHERE id = 'e2e55b95-3a42-4c60-9aac-15653d87bc0a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bu davrda onalarning eng katta dushmani — «hamma narsani biladigan qarindoshlar»ning «bola ozg‘in, to‘ymayapti, unga bo‘tqa ber» degan bosimidir. Unutmang: chaqaloqning do‘mboq bo‘lishi uning sog‘lom ekanini anglatmaydi. Asosiy ko‘rsatkichlar — bo‘yining o‘sishi, bosh aylanasi va faolligi. 4-oyda qo‘shimcha ovqat berishni boshlash (tibbiy ko‘rsatma bo‘lmasa) uning ichaklariga ortiqcha yuk tushiradi, allergiya xavfini oshiradi va ona sutini emishini kamaytiradi. «Xo‘p» deb qo‘ya qoling, ammo o‘zingiz bilganingizdek (JSST tavsiyasiga muvofiq) yo‘l tuting.') WHERE id = '79a1bd17-ef80-4f02-a1a6-cec0947ec9fb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz qorni bilan yotganda (tummy time) qo‘llarini yerga tirab, ko‘kragini to‘liq ko‘tara olsa, uning qarshisiga qiziqarli o‘yinchoqni qo‘li yetmaydigan masofada qo‘ying. U o‘yinchoqqa yetish uchun og‘irlik markazini o‘zgartirishga, balki bir qo‘lini yerdan ko‘tarishga harakat qiladi. Bu «muvozanat mashqi» kelajakda emaklashi uchun juda muhim. Agar uddalay olmay, jahli chiqsa, ishtiyoqi so‘nmasligi uchun o‘yinchoqni biroz yaqinlashtiring.') WHERE id = '9069addc-9d36-4d58-8ceb-48b115881ebe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz chiqarayotgan tovushlar endi «a-u» unlilaridan «m-b-p» undoshlariga o‘tyaptimi? «Ma-ma», «Ba-ba» kabi tovushlar tasodifan chiqishi mumkin. Bu uning sizni ongli ravishda chaqirayotganini anglatmaydi (hozircha), u shunchaki lab mushaklarini mashq qilyapti. Ammo siz bunga katta hayajon bilan javob bering: «Ha, men Onaman!». Sizning munosabatingiz uni bu tovushlarni takrorlashga va nutqini rivojlantirishga undaydi.') WHERE id = '124a08e0-8297-466a-ad92-5da9e2b40124';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'To‘rtinchi oyda chaqaloqning uyqu tartibini shakllantirish uchun «Uyqu assotsiatsiyasi»ni (Sleep Associations) yaratishingiz mumkin. Agar u faqat emib yoki tebratilganda uxlashga o‘rgangan bo‘lsa, buni asta-sekin o‘zgartira boshlang. Masalan, uyqusi kelib, mudray boshlaganda (hali to‘liq uxlamasidan) uni yotog‘iga qo‘ying va shunchaki ustiga qo‘lingizni qo‘yib, «sh-sh-sh» deng. Dastlabki kunlarda u norozilik bildiradi, ammo sabrli bo‘lsangiz, o‘zini o‘zi tinchlantirishni (self-soothing) o‘rgana boshlaydi. Bu uzoq davom etadigan jarayon, shoshilmang.') WHERE id = '440c73d7-8d87-4380-afc8-4a3037eff65e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Chaqalog‘ingiz 4 oylik bo‘ldi! Bu — «chaqaloqlik» davrining oltin o‘rtasi. U endi juda kichkina va yordamsiz ham emas, haddan tashqari harakatchan va charchatadigan ham emas. Bu oyda shifokor ko‘rigida uning vazni tug‘ilgandagi vazniga nisbatan taxminan 2 baravar oshganini ko‘rishingiz mumkin (bu o‘rtacha ko‘rsatkich). U endi ranglarni ko‘radi, tovushlarni taniydi va sizni juda yaxshi ko‘radi. Bu davrdan zavqlaning, chunki tez orada tish chiqarish va emaklash sarguzashtlari boshlanadi! Siz ajoyib ish qilyapsiz, Ona!') WHERE id = 'c7fd582a-aa6d-4d77-b362-3fa53514647a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '5-oyga xush kelibsiz! Endi uydagi o‘sha kichkina "tuguncha" yo‘q, uning o‘rnini hamma narsaga qiziqadigan, kuladigan, qichqiradigan va harakatlanadigan o‘ziga xos shaxs egalladi. Bu oyda uning jismoniy rivojlanishi yanada tezlashadi: yumalash, buyumlarni bir qo‘lidan ikkinchisiga o‘tkazish va balki emaklashga ilk urinishlar... Siz faqat xavfsiz muhit yarating (polga gilamcha to‘shang) va chetdan kuzating. Ba’zan aralashmaslik — eng yaxshi yordamdir.') WHERE id = 'ab2e9390-020b-4160-8af0-d640595e2268';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz lablarini burishtirib, "puf-puf" qiladimi (so‘lakli pufakchalar chiqaradimi)? Bu shunchaki ho‘l bo‘lish yoki sizni kuldirish uchun emas! Bu harakat uning nutqi rivojlanishi uchun juda muhim bo‘lgan til, lab va jag‘ mushaklarini mashq qildiradi. Shuningdek, u tovush chiqarish mexanizmini o‘rganadi: "Labimni shunday qilsam, mana bu tovush chiqadi". Unga "Bunday qilish uyat" demang, aksincha, siz ham unga qo‘shilib "puf-puf" qiling. Bu "muloqot" uning uchun dunyodagi eng qiziqarli o‘yindir.') WHERE id = 'ea92481c-f89e-4020-bcda-f62d11c6d1f3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi chaqalog‘ingizning qo‘llari ancha epchil. U o‘yinchoqni bir qo‘li bilan ushlab, keyin ikkinchi qo‘liga o‘tkaza oladimi? Bu "o‘rta chiziqdan o‘tish" (crossing the midline) ko‘nikmasi miya yarimsharlari o‘rtasidagi aloqa kuchayayotganini ko‘rsatadi. Bu ko‘nikmani rivojlantirish uchun unga ikki xil o‘yinchoq bering: birini o‘ng, ikkinchisini chap qo‘liga. Keyin uchinchi o‘yinchoqni taklif qiling. Qarang, qo‘lidagilardan birini tashlab, uchinchisini olarmikan? Bu uning ilk "qaror qabul qilish" lahzasidir.') WHERE id = 'c16f8e30-0e77-4445-93ae-cd9830a7f241';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '5-oyda chaqaloqlar ranglarni, ayniqsa qizil, ko‘k va sariq ranglarni juda aniq ko‘radi. Shu bilan birga, chuqurlikni his qilish qobiliyati (3D ko‘rish) shakllanadi. Endi u o‘yinchoq qanchalik uzoqda ekanini taxmin qila oladi va qo‘lini to‘g‘ri unga uzatadi. Bu davrda uni ko‘zgu qarshisiga qo‘yish yoki rangli to‘plar bilan o‘ynatish ko‘z va qo‘l muvofiqligini yaxshilaydi. Agar hanuz g‘ilaylik (ko‘zlarning ba’zan bir-biriga qarab qolishi) kuzatilsa, bu oyda u kamayishi kerak; davom etsa, shifokorga ko‘rsatgan ma’qul.') WHERE id = '1f034b11-0fbb-48ea-bbf4-278ca6b86b2b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizni boshqa birov (hatto buvisi yoki xolasi) bag‘riga olganida lablarini burishtirib yig‘laydimi? Onalar ko‘pincha bundan uyalib, "bolam odamovi" deb xafa bo‘lishadi. Aslida esa bu uning aql-idroki rivojlanayotganining belgisidir! U endi "yaqin" (siz va dadasi) hamda "begona" (boshqalar) tushunchalarini anglaydi. Bu "begona odamlardan qo‘rqish" (stranger anxiety) rivojlanishning odatiy bosqichidir. Uni majburlab boshqa birovning bag‘riga bermang, avval sizning quchog‘ingizda o‘sha odamga ko‘nikib, o‘zini xavfsiz his qilishiga imkon bering.') WHERE id = 'c6a4085b-3a97-4e0b-b5f5-5b36782649fe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Bola to‘ymayapti, kechalari uyg‘onyapti, keling, unga bo‘tqa (kasha) beramiz" degan takliflar ko‘paydimi? Unutmang, kechasi uyg‘onishiga ko‘pincha ochlik emas, balki uyqu sikllarining o‘zgarishi, tish qichishishi yoki shunchaki sizni sog‘inishi sabab bo‘ladi. 5 oylik chaqaloqning ovqat hazm qilish tizimi hali to‘liq shakllanmagan (fermentlar yetarli emas). Qo‘shimcha ovqatni erta boshlash allergiya xavfini oshiradi va ona suti kamayishiga olib keladi. JSST tavsiyasi o‘zgarmaydi: dastlabki 6 oy — faqat sut. Shoshilmang, qoshiq ushlash uchun hali butun umri oldinda.') WHERE id = 'c26a80c4-409b-4945-b7d2-51c416190946';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq oyoqlarini o‘rganishda davom etmoqda. Agar u oyoq barmoqlarini og‘ziga solib so‘rsa, bunga to‘sqinlik qilmang. Bu harakat uning umurtqa pog‘onasi egiluvchanligini oshiradi, chanoq-son bo‘g‘imlarini ochadi va tana muvozanatini topishga yordam beradi. Ayni paytda bu uning o‘z tanasi chegaralarini anglashidir ("Ana, bu barmoq ham meniki"). Paypoqlarini yeching, oyoqlarini "tatib ko‘rishiga" imkon bering.') WHERE id = '0696d902-62ea-41fb-ac33-42f63be246d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning vazni ancha oshgan (taxminan 6-8 kg bo‘lishi mumkin), uni doimo qo‘lda ko‘tarib yurish esa umurtqa pog‘onangizga jiddiy yuk tushiradi. "Ergonomik ko‘tarib yurish" qoidalariga e’tibor bering: chaqaloqni dumbasidan ushlab, og‘irlikni teng taqsimlang, uni faqat bir tomonda (faqat o‘ng yoki chap yoningizda) ko‘tarib yurishdan saqlaning, chunki bu skoliozga sabab bo‘lishi mumkin. Imkon qadar polda o‘ynashga ustunlik bering. Belingiz sog‘lom bo‘lishi chaqaloqqa g‘amxo‘rlik qila olishingiz uchun juda muhim.') WHERE id = 'd400ec9f-412b-4ad6-988e-58b62c0416fd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq o‘yinchoqni yerga tashlaydi, siz olib berasiz, u yana tashlab kuladimi? Bu joningizga tegishi mumkin, ammo uning uchun bu fizika tajribasi! U "Sabab-Oqibat" bog‘liqligini o‘rganmoqda: "Men buni tashlayman (sabab), onam olib beradi (oqibat) yoki tovush chiqadi". Bu o‘yin unga dunyoni boshqara olayotganini his qildiradi. Asabiylashmang, bu rivojlanish uchun muhimligini eslab, sabr bilan (yoki ipga bog‘langan o‘yinchoqlar yordamida) o‘yinni davom ettiring.') WHERE id = 'fe5f82f2-00a9-4854-b3e5-0b8ebb578153';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning kunduzgi uyqulari asta-sekin tartibga tusha boshlaydi ("Uyquga o‘tish davri"). Avvalgi tartibsiz, qisqa uyqular o‘rnini kuniga 3 mahal (ertalab, tushda, kechga yaqin) uzoqroq uyqu egallashi mumkin. Oxirgi uyqu (kechga yaqin mizg‘ib olish) odatda qisqa bo‘ladi (30-40 daq) va tungi uyquga o‘tishni osonlashtiradi. Agar u hali ham tartibsiz uxlayotgan bo‘lsa, "uyqu oynasi"ni (uyg‘oq qolish vaqtini) kuzatib, juda charchab qolishidan oldin uxlatishga harakat qiling. Uyqu uyquni keltiradi.') WHERE id = '5d110284-d82d-4dbe-8144-2a516161ad7f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz oyoqlarini og‘ziga solib, go‘yo "tatib ko‘ryaptimi"? Bu holat juda kulgili ko‘rinishi mumkin, ammo aslida u umurtqa pog‘onasining egiluvchanligi va tana harakatlarini muvofiqlashtira olayotganini ko‘rsatuvchi ajoyib rivojlanish bosqichidir. U tanasining pastki qismini o‘rganmoqda. Bunga to‘sqinlik qilmang (qulayroq bo‘lishi uchun paypoqlarini yeching). Bu harakat, shuningdek, qorin dam bo‘lishi bilan bog‘liq og‘riqlarni tabiiy ravishda yengillashtirishga yordam beradi.') WHERE id = '66fe21ca-05fd-4c48-95fa-5f031cadebb2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '5-oyda chaqaloqlar qichqirishni, chiyillashni va ovozini balandlatishni yaxshi ko‘radi. Ba’zan bu shovqin quloqni qomatga keltirishi mumkin, ammo xavotir olmang, u sizdan jahli chiqayotgani yo‘q. U shunchaki ovoz paychalarini "sinab ko‘rmoqda": "Qani, qanchalik baland qichqira olarkinman?". Shu tariqa u o‘z ovozini boshqarishni o‘rganadi. Unga pichirlab javob bering; u ham sizga taqlid qilib, ovozini pasaytirishga harakat qiladi. Bu ajoyib o‘yin.') WHERE id = 'd03675dd-580b-4a83-a42a-a1376cb7a774';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Bola o''tira oladimi?" degan savollar boshlangan bo''lsa, shoshilmang. Chaqaloq hali bunga tayyor bo''lmasa, uni yostiqlar orasiga joylab, majburan o''tqazish umurtqa pog''onasiga zarar yetkazishi mumkin. 5-oyda chaqaloqlar "uch tayanchli o''tirish" holatini (qo''llarini oldinga tirab o''tirish) sinab ko''rishlari mumkin, ammo hali muvozanatni to''liq saqlay olmaydilar. Eng yaxshi mashq — polda qorni bilan yotib o''ynash. Bel mushaklari mustahkamlangach, u o''zi ko''tarilib o''tiradi.') WHERE id = 'e21494e3-d1b4-470c-8b69-91bdff0641cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Buvilarning "bir oz sho''rva suvidan ber, ta''mini bilsin" degan maslahati yana kun tartibidami? Shuni bilishingiz kerakki, chaqaloqning ichaklari hali ham "elak" kabi (ichak o''tkazuvchanligi yuqori). Ona suti yoki sun''iy aralashmadan boshqa har qanday ozuqa (hatto suv yoki sharbat ham) bu to''siqdan o''tib, allergiya va ovqat hazm qilish muammolariga sabab bo''lishi mumkin. Uning "ta''mini bilishi" uchun hali vaqti ko''p, hozirgi asosiy maqsad — ichak mikroflorasini asrash. Siz "yomon kelin" emas, "bilimli ona"siz.') WHERE id = '2049b273-04ed-4768-bc4b-392861691428';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning tunda uxlayotganida o''z-o''zidan ag''darilib, yuztuban yotib olishi sizni qo''rqityaptimi? Agar u kunduzi har ikki tomonga (chalqancha holatdan qorniga va qornidan chalqancha holatga) bemalol ag''darila olsa, tunda uni har safar to''g''rilab qo''yish shart emas. Faqat yotog''ida yostiq, ko''rpa va yumshoq o''yinchoqlar yo''qligiga ishonch hosil qiling (bo''g''ilish xavfi bo''lmasligi uchun). U o''ziga qulay holatni tanlaydi. Siz ham xotirjam uxlang.') WHERE id = '75eb58f4-2826-4a4a-8b58-b49e3d0b9d70';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bu oyda chaqaloqning sochlari to''kilib, o''rniga yangilari o''sa boshlashi mumkin ("chaqaloqlik sochlari"ning almashishi). Ba''zan ensasida "kal joy" paydo bo''ladi — bu shunchaki ishqalanish (ko''p yotish) tufayli yuzaga keladi va mutlaqo normal holat. U o''tira va ko''proq harakatlana boshlagach, sochlari bir tekis o''sadi. Bu vitamin yetishmovchiligi emas, xavotir olmang.') WHERE id = 'f63f93ff-407c-4880-934c-4db268020afd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog''ingiz endi mayda narsalarni (masalan, poldagi chang zarrasini yoki kiyimidagi ipni) ko''rib, barmoqlari bilan ushlashga harakat qiladi. Ko''rish qobiliyati shunchalik o''tkirlashganki, u mayda detallarni ham ajrata oladi. Bu davrda xavfsizlik 1-raqamli qoidadir. Tugmalar, tangalar, sirg''alar — barchasini uning qo''li yetmaydigan joyda saqlang. U hali ham dunyoni og''zi orqali o''rganadi va topgan narsasining barchasini og''ziga soladi.') WHERE id = '50867048-47ec-4339-857c-cdebcdc6c314';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Xodunok" (yuritgich) sotib olmoqchimisiz? Yana bir bor o''ylab ko''ring. Ko''plab rivojlangan mamlakatlarda (masalan, Kanadada) bu moslamani sotish taqiqlangan. Sababi: u chaqaloqning oyoq uchida yurishiga (tovonini yerga bosmasligiga), umurtqa pog''onasiga muddatidan oldin yuk tushishiga va eng asosiysi, xavfli joylarga (qaynoq choynak, zinapoya) tez yetib borishiga sabab bo''ladi. Rivojlanish uchun eng yaxshi vosita — pol. Emaklab, mushaklarini mustahkamlashiga imkon bering.') WHERE id = '700936b7-4cd2-492b-9509-98a14c16e71e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tish chiqishi arafasida chaqaloqning immuniteti biroz zaiflashishi mumkin, ammo "tish isitmasi"ni "virusli infeksiya" bilan adashtirmang. Tish chiqayotganda harorat odatda 38 darajadan oshmaydi va burun oqishi, yo‘tal kabi alomatlar kuzatilmaydi. Agar harorat yuqori bo‘lsa va chaqaloq holsizlansa, buni shunchaki tish chiqishiga bog‘lab, xotirjam bo‘lib qolmang, albatta shifokoringizga xabar bering.') WHERE id = 'ec752558-6d74-4751-872c-b47b29cef0cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bu davrda onalarning hayz sikli tiklanishi mumkin (ayrimlarda ertaroq, boshqalarda kechroq). "Emizikli ona hayz ko‘rmaydi" degan fikr — afsona. Hayz boshlanganda sut miqdori biroz kamayishi yoki ta’mi o‘zgarishi mumkin (gormonlar ta’sirida), chaqaloq esa bunga norozilik bildirishi mumkin. Ammo sutning sifati yomonlashmaydi va u "zaharlanib" qolmaydi. Emizishni davom ettiring, bu vaqtinchalik holat.') WHERE id = 'ad62d3cf-28a5-411d-86f8-d16d19e156b2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz qo‘lidagi o‘yinchoqni yerga urishni yoki stolga taqillatishni yoqtiryaptimi? Bu buzg‘unchilik emas, bu uning "ovoz muhandisligi"! U qattiq buyum qattiq yuzaga urilganda qanday ovoz chiqishini kashf etmoqda. Unga xalaqit berish o‘rniga, turli ovozlar chiqaradigan buyumlarni (yog‘och qoshiq, plastik idish, yumshoq o‘yinchoq) bering. "Qarang, bunisi taqillaydi, bunisi esa ovoz chiqarmaydi", deb farqini tushuntiring.') WHERE id = '62ce75ea-f714-4996-ae9c-54a3b27495ac';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uydagi xavfsizlik choralarini ("Babyproofing") kuchaytirishning ayni vaqti. Chaqaloq hali emaklamayotgan bo‘lsa ham, dumalab yoki sudralib elektr rozetkalariga, osilib turgan simlarga yoxud dasturxon chetiga yetib borishi mumkin. Uning balandligiga tushing (yerga yoting) va uyga uning nigohi bilan qarang: polda nimalar xavfli ko‘rinadi? Barcha xavfli buyumlarni olib qo‘ying, chunki baxtsiz hodisalar "kelyapman" deb ogohlantirmaydi.') WHERE id = 'aff088aa-a1cd-4138-acbc-e2c0688efeb6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar chaqaloqning terisida quruq dog‘lar yoki qizarishlar (atopik dermatit/ekzema) paydo bo‘lsa, darhol yegan ovqatlaringizni (parhezingizni) ayblamang. Ko‘pincha bunga oziq-ovqat emas, balki atrof-muhit sabab bo‘ladi: quruq havo, sintetik kiyimlar, kir yuvish kukuni yoki juda issiq suvda cho‘miltirish. Xonadagi namlikni oshiring, chaqaloq terisiga namlantiruvchi kremlarni (emollientlarni) yengil massaj qilib surting va cho‘miltirgandan keyin terisini ishqalamasdan, sochiq bilan ohista bosib quriting.') WHERE id = '572d9eb0-1241-494b-9f36-13d0ee848f80';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Chaqalog‘ingiz 5 oylik bo‘ldi! Yarim yoshga (6 oy) yetishiga juda oz qoldi. Bu oy uning uchun katta o‘tish davridir; endi u his-tuyg‘ularini yanada aniqroq ifodalaydi, xursand bo‘lsa qiyqiradi, biror narsani istamasa itaradi. Siz ham shu 5 oy ichida aql bovar qilmas yo‘lni bosib o‘tdingiz. Uyqusiz tunlar va charchoqqa qaramay, siz uning dunyosining markazisiz. O‘zingizga "katta rahmat" ayting va bu kunni kichik bir tabassum bilan nishonlang!') WHERE id = '7802c1ee-5da4-41a5-a0b7-633ee14ee9a9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Oynaga qaraganingizda o‘zingizni qarovsiz va charchagan his qilasizmi? Onalik ta’tili ba’zan "Sug‘ur kuni"ga (bir kunning qayta-qayta takrorlanishi) o‘xshaydi. Bugun chaqaloqni dadasi yoki buvisiga qoldirib, 1 soatga uydan chiqing. Shunchaki do‘konga borish, parkda yolg‘iz sayr qilish yoki sochingizni kestirish sizga "kislorod niqobi"dek ta’sir qiladi. Siz baxtli bo‘lsangiz, chaqalog‘ingiz ham baxtli bo‘ladi.') WHERE id = '3c6e4f71-0ba2-4930-a133-04552c20e1dd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 5-oyning yarmiga yetdingiz! Endi chaqaloqning vazn olishi dastlabki oylardagidek tez bo‘lmasligi mumkin (oyiga 1 kq o‘rniga 400-500 qr). Bu normal holat, chunki u ko‘proq harakat qilib, energiya sarflaydi. Shifokor kuzatuv jadvalidagi "egri chiziq" yuqoriga qarab borayotgan ekan, xavotirga o‘rin yo‘q. "Sutim kamaydi, bolam ozib ketdi" deb xavotirlanmang, shunchaki uning faolligidan zavqlaning.') WHERE id = '77295e93-c83b-4ff4-8d09-da9b139b8a65';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Siz ovqatlanayotganingizda chaqalog‘ingiz og‘zini ochadimi, sizni diqqat bilan kuzatadimi yoki likopchangizga qo‘l uzatadimi? Bu — "Ovqatga biologik qiziqish". U sizga taqlid qilmoqchi, ammo bu uning albatta ochligini anglatmaydi. Qo‘shimcha ovqat berishni boshlash uchun faqat qiziqishning o‘zi yetarli emas; chaqaloq boshini tik tutishi, tayanchsiz (yoki ozgina yordam bilan) o‘tirishi va eng muhimi, "Til bilan itarish refleksi" (ovqatni tili bilan tashqariga itarishi) yo‘qolgan bo‘lishi kerak. Hozircha unga bo‘sh qoshiq bering, o‘ynasin, ammo ovqat berishga yana biroz sabr qiling.') WHERE id = '7853d6dc-3fa1-4c99-9bee-ffadc85c9246';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz qornida yotganida qo‘l-oyoqlarini havoga ko‘tarib, "Supermen" kabi uchadimi? Bu harakat juda yoqimli ko‘rinsa-da, aslida jiddiy mashqdir. U bel, bo‘yin va son mushaklarini taranglashtirib, kelajakda emaklash va o‘tirish uchun kuch to‘playdi. Bu paytda unga xalaqit bermang, shunchaki oldiga qiziqarli o‘yinchoq qo‘yib, uni ruhlantiring.') WHERE id = 'ee5e432a-11cb-49f0-b780-4af770910a6e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '5-oyda chaqaloqlar ba’zan g‘alati tovushlar — xirillash, yo‘talga taqlid qilish yoki baland ovozda qichqirishlari mumkin. Siz qo‘rqib, shifokorga yugurishga tayyorlanayotganingizda, u sizga jilmayishi mumkin. Bu uning ovoz paychalari bilan o‘tkazayotgan "tajribasi"dir. U qaysi harakat qanday tovush chiqarishini o‘rganmoqda. Agar isitmasi yoki kasallikning boshqa alomatlari bo‘lmasa, shunchaki bu "konsert"dan zavqlaning.') WHERE id = 'b8f6e7f4-fa6c-4da7-b344-5fdbda538ecd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar uyqu vaqtida chaqalog‘ingiz boshini doimo bir tomonga burishini yoki boshining orqa qismi yassilashganini sezsangiz, uyg‘oq paytidagi o‘yinlar yo‘nalishini o‘zgartiring. Agar odatda o‘ng tomondan yaqinlashsangiz, endi chap tomondan gapiring. Beshikning joyini o‘zgartiring, shunda u yorug‘likka yoki sizga qarash uchun boshini boshqa tomonga burishga majbur bo‘ladi. Bu oddiy o‘zgarish bo‘yin mushaklarining bir tekis rivojlanishiga yordam beradi.') WHERE id = 'b66d2212-4a92-4a46-b745-aeb8c99cd2a4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '6-oyning ilk kuniga xush kelibsiz! Endi "qo‘shimcha ovqat" mavzusi uyda eng ko‘p muhokama qilinadigan mavzuga aylanadi. Buvilar shoshiltirishi mumkin, ammo siz JSSTning oltin qoidasini yodda tuting: chaqaloq 6 oylik bo‘lguniga qadar faqat ona suti (yoki sutli aralashma) bilan oziqlanishi kerak. Biroq tayyorgarlikni boshlasa bo‘ladi! Chaqaloq bunga tayyor yoki yo‘qligini tekshiring: u yordamsiz o‘tira oladimi? Boshini tik ushlaydimi? Siz ovqatlanayotganingizda og‘zini chapillatib, qiziqish bildiradimi? Agar javoblar "ha" bo‘lsa, sarguzasht boshlanishiga oz qoldi.') WHERE id = 'c07d39a8-4230-4141-b911-a428b18acb0f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz emizayotganingizda sizni tishlayaptimi? Bu uning milklarida qichishish borligini yoki qorni to‘yib, o‘ynashni istayotganini anglatishi mumkin. Baqirib, uni qo‘rqitmang — bu ko‘krak sutidan bosh tortishiga sabab bo‘lishi mumkin. Xotirjamlik bilan "yo‘q" deng va ko‘krakni og‘zidan chiqaring (jimjilog‘ingizni og‘zining chetiga kiritib, vakuumni bo‘shating). U tishlash emizishni to‘xtatishini tushunsa, buni takrorlamaydi. Sovutilgan tish qashlagichlar tishlashga qarshi eng yaxshi yordamchingizdir.') WHERE id = '1c9ac763-40c0-4c2c-9037-aa4d0926c708';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqni o‘tqazish uchun "yostiq qal’alari"dan foydalanishga shoshilmang. Agar u o‘zi o‘tirishga urinmasa va belini bukib, "C" harfiga o‘xshab qolsa (bukchaygan holat), demak, mushaklari hali tayyor emas. Majburan o‘tqazish umurtqa pog‘onasiga zarar yetkazishi mumkin. Unga polda ko‘proq vaqt o‘tkazishiga imkon bering, shunda o‘zi "Tripod" holatiga (qo‘llarini oldinga tirab) keladi. Tabiiy rivojlanish har doim eng xavfsiz yo‘ldir.') WHERE id = '026af185-68d2-497b-b2e5-6cbcde3b4230';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tish gelidan (gel) foydalanganda juda ehtiyot bo‘ling. Tarkibida "Lidokain" yoki "Benzokain" bo‘lgan gellar chaqaloqlar uchun jiddiy xavf tug‘dirishi mumkin (yutishda qiyinchilik va yurak ritmi bilan bog‘liq muammolar). FDA (AQSH Oziq-ovqat va dori vositalari boshqarmasi) bu moddalarni chaqaloqlar uchun tavsiya etmaydi. Buning o‘rniga tabiiy tarkibli gellar yoki shunchaki sovutilgan rezina o‘yinchoqlardan foydalanish, milklarni nam doka bilan massaj qilish xavfsizroq va samaraliroqdir.') WHERE id = 'd57483e9-dfea-4122-86d2-ac70acfdcbfd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz qorni bilan yotganida qo‘llari bilan polga tiralib, orqaga ("qisqichbaqa kabi") emaklay boshladimi? Bu emaklashning ilk bosqichidir! U oldinga yurishni istaydi, ammo qo‘llari oyoqlaridan kuchliroq bo‘lgani uchun orqaga ketadi. Bu uning jahli chiqishiga sabab bo‘lishi mumkin. Unga yordam berish uchun kaftingizni oyoq tovonlariga tirab turing, shunda u oldinga itarila oladi. Sabrli bo‘ling, tez orada butun uyni zabt etadi.') WHERE id = '1cfdff71-da32-4931-b5cb-94e1a37d4db0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bu oyda chaqaloqning uyqusi yana buzilishi mumkin, ammo bu safar bunga "ajralish xavotiri" (separation anxiety) sabab bo‘lishi mumkin. U sizning xonadan chiqib ketishingizni "meni tashlab ketdi" deb qabul qiladi. Uxlatayotganda yonida biroz ko‘proq qoling, unga teginib turing, ammo darhol quchog‘ingizga olib yurishga shoshilmang (aks holda odatlanib qoladi). U bilan "Ku-ku" (bekinmachoq) o‘ynab, onasi ketganidan keyin yana qaytib kelishini o‘rgating. Bu qo‘rquv vaqtinchalik, ishonch hissi esa doimiydir.') WHERE id = 'bda07f09-37eb-4be3-a16a-4bf2694b38b8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Suv berishni qachon boshlash kerak?" degan savol dolzarb bo‘lib bormoqda. Qo‘shimcha ovqat (qattiq ovqat) berishni boshlagan kuningizdan suv berishni ham boshlashingiz kerak. Hozircha (agar hali qattiq ovqat bermayotgan bo‘lsangiz) suvga ehtiyoj yo‘q, ona suti yoki sun’iy ozuqa yetarli. Hozirdanoq kichkina, suv to‘kilmaydigan "ichimlik idishi" (sipper cup) olib, chaqaloqni unga o‘rgatishingiz mumkin (ichiga suv quymasdan). Uni qo‘lida ushlasin, og‘ziga olib borsin, o‘yinchoqdek o‘ynasin. Shunda vaqti kelganda uni begona ko‘rmaydi.') WHERE id = 'ff09c584-fe70-41cf-951d-eb545f630c39';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning tagligini almashtirish endi kurash musobaqasiga o‘xshab qoldimi? U tinch turmaydi, aylanadi, qochishga urinadi. Bu uning erkin harakatlanishdan zavqlanayotganini anglatadi. Jahlingiz chiqmasin, shunchaki strategik yo‘l tuting: tagligini almashtirayotganda qo‘liga qiziqarli, ilgari ko‘rmagan biror buyumni (masalan, toza krem idishini) bering yoki qo‘shiq aytib, diqqatini chalg‘iting. Ba’zan tagligini tik turganida yoki emaklayotganida almashtirishga majbur bo‘lishingiz mumkin — bu onalik mahoratidir!') WHERE id = '5c0bcce8-2d98-4e33-ab73-d613b0c76c24';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz "Ba-ba", "Da-da", "Ma-ma" bo‘g‘inlarini takrorlayaptimi? Otalar odatda "Dada dedi!" deb quvonishadi, ammo hozircha bu ongli murojaat emas, shunchaki tovushlarni mashq qilishdir (g‘udurlash). Lekin siz bu tovushlarga ma’no bering: "Ha, bu Dada!", "Ha, men Onaman!". Bu so‘zlarni buyumlar yoki odamlar bilan bog‘lashingiz uning miyasida lug‘at shakllanishiga yordam beradi. Tez orada u bu so‘zlarni maqsadli ravishda ishlata boshlaydi.') WHERE id = 'ea83f521-c253-469b-809a-6bfb8bc161b2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '6 oylik (yarim yosh) bo‘lishiga atigi 20 kun qoldi! Qo‘shimcha ovqatlantirish uchun "bolalar ovqatlanish stuli"ni tanladingizmi? Stul tanlashda eng muhim shart: chaqaloqning beli tik turishi va oyoqlari albatta tayanchga (oyoq qo‘ygichga) tiralishi kerak. Oyoqlari havoda osilib qolgan bola bezovta bo‘ladi va diqqatini ovqatlanishga jamlay olmaydi. Stul qimmatbaho brendniki bo‘lishi shart emas, ergonomik va oson tozalanadigan bo‘lsa (chunki juda ko‘p ifloslanadi!), yetarli.') WHERE id = '5376c7fc-e6df-4f63-941d-2e00e5209d33';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqatga tayyorgarlik uchun xarid qilishni boshladingizmi? Avvalo, chaqaloq uchun maxsus qoshiq tanlash muhim. Metall qoshiqlar uning nozik tanglayini shikastlashi, issiqlikni tez o‘tkazib, tilini kuydirishi mumkin. Eng yaxshi tanlov — uchi yumshoq silikonli, kichik va uzun dastali qoshiqlar. "Katta qoshiqda beray, tezroq to‘ysin" degan fikr noto‘g‘ri; qoshiq qanchalik kichik bo‘lsa, uning yutish refleksi shunchalik oson moslashadi. Rangli qoshiqlar uning ovqatga qiziqishini oshiradi.') WHERE id = '1d96ab29-9c6c-4bb8-ba1f-f5f3f11a1dbb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz kechalari to‘satdan yig‘lab uyg‘onib, zo‘rg‘a tinchlanadimi? 6-oy arafasida milkdagi bosim kechalari (yotgan holatda boshga qon oqimi ko‘paygani sababli) kuchliroq seziladi. Undan jahlingiz chiqmasin, uning shunchaki og‘rig‘i bor. Uxlashdan oldin milklarini toza barmog‘ingiz yoki maxsus silikon cho‘tka bilan yengil uqalash qon aylanishini yaxshilaydi. Sabrli bo‘ling, o‘sha kichkina "marvaridlar" ko‘ringanda barcha uyqusiz tunlar unutiladi.') WHERE id = '4bb38a42-9207-48cc-87a0-6e8506859c1d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Pol sovuq, bolani kasal qilib qo‘yasiz" deydigan kattalarga quloq solib, chaqaloqni divan yoki beshikka qamab qo‘ymang. Toza gilam yoki maxsus o‘yin gilamchasi (puzzle mat) chaqaloq uchun eng yaxshi sport zalidir. Sovuqdan xavotirda bo‘lsangiz, shunchaki kiyimini moslang (paypoq yoki paxtali shim kiydiring). U polda qancha ko‘p ag‘darilsa, emaklasa va harakat qilishga urinsa, mushaklari shuncha tez mustahkamlanadi. Harakatsizlik — rivojlanishni sekinlashtiradigan eng katta dushman.') WHERE id = '5ed49a9c-59aa-4f08-b836-cd7056d33992';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq bilan kitob o‘qish uchun uning gapirishini kutmang. Hozir "paypaslab ko‘riladigan" (touch and feel) yoki shitirlaydigan kitoblarni sotib olishning ayni vaqti. U sahifalarni o‘girishga urinadi (buni uddalash mayda motorika uchun ajoyib mashq), rasmlarga qo‘lini uradi va hatto kitobni kemirishi ham mumkin. Bu — "kitobga mehr"ning boshlanishi. Unga hayvonlarni ko‘rsating va ularning ovoziga taqlid qiling ("Sigir qanday ovoz chiqaradi? Muuu!"). Bu oddiy o‘yin uning passiv lug‘at boyligini oshiradi.') WHERE id = 'a556f86c-ce31-4428-944f-44af737aa8ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz o‘tirishga urinayotganda qo‘llarini oldinga qo‘yib (uchburchak/tripod holatida) muvozanatni saqlashga harakat qilyaptimi? Bu juda yaxshi belgi! Ammo uni hali butunlay qarovsiz qoldirmang, chunki u to‘satdan orqaga yoki yon tomonga yiqilishi mumkin. Atrofiga (orqasi va yon tomonlariga) yostiqlar qo‘yib, "xavfsizlik doirasi"ni yarating. Lekin uni yostiqlar orasiga qistirib, harakatsiz qoldirmang; muvozanatni topish uchun o‘z tanasini boshqarishni o‘rgansin.') WHERE id = '75dd1faa-e49b-4521-a298-8ff13485c3cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nega aynan 6 oylikdan qo‘shimcha ovqat berishni boshlaymiz? Sabab faqat oshqozon bilan emas, qon bilan ham bog‘liq. Chaqaloq ona qornida to‘plagan temir zaxirasi (ferritin) taxminan 6-oyda kamayishni boshlaydi va ona sutidagi temir endi uning ortib borayotgan ehtiyojini to‘liq qoplamaydi. Shu sababli dastlabki mahsulotlar odatda temirga boy ovqatlardan (go‘sht, temir bilan boyitilgan bo‘tqalar) tanlanadi. Bu shunchaki "to‘yish" masalasi emas, balki fiziologik zaruratdir.') WHERE id = 'd0ee725f-9b61-4b89-bc59-14a2829f8036';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlantirish stulidagi "xavfsizlik kamari"ga beparvo qaramang. "Bolam hali qimirlamaydi, qayerga ham borardi?" degan fikr — eng katta xato. Chaqaloqlar bir soniya ichida pastga sirg‘alib tushishi yoki o‘rnidan turishga urinishi mumkin. Shuningdek, stulda "oyoq tayanchi" (footrest) bo‘lishi kerak. Oyoqlari havoda osilib qolgan bola yutishda qiynalishi mumkin (bo‘g‘ilish xavfi ortadi). Oyoqlari tayanchga tiralganda tana barqarorroq bo‘ladi va yutish jarayoni xavfsizroq kechadi.') WHERE id = '625e4f6a-1f8a-44b3-838c-95a927b0b1a5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Onam ketdi!" degan qo‘rquv (Separation Anxiety) shu kunlarda kuchayishi mumkin. Xonadan chiqqaningizda yig‘lasa, eshik ortidan u bilan gaplashishda davom eting: "Men shu yerdaman, seni eshityapman, hozir kelaman". Ovozingiz unga tasalli beradi. Shuningdek, "Ku-ku" (Pee-ka-boo) o‘yinini tez-tez o‘ynang. Bu o‘yin unga odamlar ko‘rinmay qolsa ham (yuzlarini berkitsa ham), albatta qaytib kelishini o‘rgatadi. Bu psixologik mashqdir.') WHERE id = '422035de-73c2-492a-bbec-313984910971';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqat berishni boshlaganda suv ichirish ham muhim bo‘ladi. Chaqaloqni hozirdanoq "Suv stakani" (Sippy cup yoki oddiy kichik stakan) bilan tanishtiring. Ichiga juda oz miqdorda (bir qultum) suv quying yoki bo‘sh holda bering. U stakanni ushlashni, og‘ziga olib borishni va "qiya" burchakda tutishni (boshini orqaga egishni) o‘rgansin. So‘rg‘ichli shishadan (butilkadan) farqli ravishda, stakandan ichish og‘iz va tilning butunlay boshqacha muvofiqlashuvini talab qiladi.') WHERE id = '276120aa-1546-4b32-a95c-f7c80f3724d7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ishonasizmi? Yarim yoshga (6 oyga) atigi 10 kun qoldi! Bu juda muhim bosqich. Chaqalog‘ingiz endi deyarli "katta bola" bo‘lishga tayyorlanyapti. Shu kunlarda uni suratga oling, videolarini yozib qo‘ying. Dastlabki oylardagi o‘sha g‘ujanak bo‘lib yotadigan, tinch chaqaloqni hozirgi faol kashfiyotchi bilan solishtiring. Siz unga nafaqat sut, balki ishonch, mehr va jasorat ham berdingiz. So‘nggi 10 kunning zavqini suring, chunki oldinda "dog‘ bo‘lgan fartukchalar" va "qoshiq janglari" davri kutmoqda!') WHERE id = 'eeef4f12-67b6-4638-9c3f-cfa2a5c6b644';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '6-oyning so‘nggi o‘n kunligiga xush kelibsiz! Endi oshxonada qo‘shimcha ovqat uchun tayyorgarlik avjiga chiqqan. Boshlash uchun sabzavot pyurelari (masalan, kabachki, gulkaram) yoki guruch/grechka bo‘tqalari odatda eng xavfsiz tanlovdir. Muhim qoida: Har bir yangi mahsulotni alohida bering va 3 kun kutish qoidasiga rioya qiling. Bu chaqaloqda ushbu mahsulotga allergiya bor-yo‘qligini aniqlashning yagona yo‘lidir. Shoshilmang, dastlabki kunlarda maqsad chaqaloqni to‘ydirish emas, shunchaki uni yangi ta’mlar bilan tanishtirishdir.') WHERE id = 'f895f071-f97f-4fb0-9772-e32eeffab324';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi tayanchsiz o‘tirishga yanada yaqin. Uni yerga o‘tqazganingizda, qo‘llarini ikki yoniga tirab muvozanatini saqlayotganini ko‘rishingiz mumkin. Bu davrda uning atrofiga yumshoq to‘shakchalar yoki yostiqlar qo‘yish muhim, chunki bir soniyaga qarovsiz qolsa, orqaga "qopdek" yiqilishi mumkin. Ammo uni yostiqlar orasiga "ko‘mib" qo‘ymang, o‘z mushaklari yordamida muvozanat saqlashni mashq qilsin. Bel va qorin mushaklari qancha ko‘p ishlasa, u shuncha tez tik o‘tirishni boshlaydi.') WHERE id = '5a9ac2d0-eaf0-4588-afbc-9d21af03e70a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqatga o‘tish davrida bolaning "bo‘g‘ilib qolishi"dan qo‘rqish har bir onaning dahshatli tushidir. Shuni bilishingiz kerakki, chaqaloqlarda "Gag reflex" (o‘qchish refleksi) tilning oldinroq qismida joylashgan; ya’ni bola o‘qchiyotgan bo‘lsa, bu uning bo‘g‘ilib qolganini emas, shunchaki ovqatni tashqariga itarayotganini anglatadi. Haqiqiy bo‘g‘ilish paytida bola ovoz chiqara olmaydi va terisining rangi o‘zgaradi. O‘qchish paytida esa u shunchaki yo‘talib, ovqatni chiqarib tashlaydi. Bu refleksni farqlay olish sizni tinchlantiradi va chaqaloqqa ovqatlanishni o‘rganishda dadillik beradi.') WHERE id = '70a66a9a-563a-4960-829c-3c543e77de0b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi buyumlarni bir qo‘lidan ikkinchisiga bemalol o‘tkaza oladi. Bu miya yarimsharlarining muvofiqlashgan holda ishlayotganini ko‘rsatadi. Ushbu ko‘nikmani rivojlantiradigan o‘yinlarni o‘ynang: Unga bitta o‘yinchoq bering, uni ushlagach, ikkinchi qo‘liga yana bir o‘yinchoq tutqazing. Ko‘raylik-chi, birinchisini tashlab yuborarmikan yoki uni boshqa qo‘liga o‘tkazarmikan? Bu oddiy o‘yin uning nozik motorikasini ham, muammolarni hal qilish qobiliyatini ham rivojlantiradi.') WHERE id = 'ae843217-76c1-4871-8e0d-ffc6c753bdec';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '6-oyda chaqaloqlarning xotirasi ancha mustahkamlanadi. U endi kundalik odatlarni taniydi. Masalan, ko‘krakchasini taqqaningizda ovqatlanishini, sochiqni ko‘rganida cho‘milishini tushunadi. Bu barqarorlik unga ishonch bag‘ishlaydi. Shuning uchun bu odatlarni buzmaslikka harakat qiling. "Hozir nima qilamiz?" deb u bilan gaplashib, har bir qadamingizni tushuntiring. Ovozingiz va harakatlarning izchilligi uning dunyosini yanada xavfsiz va tushunarli qiladi.') WHERE id = '024b161c-2539-4cac-976f-5bf08fd88827';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar ilk tishlari hali chiqmagan bo‘lsa, xavotir olmang; ayrim bolalarda tish chiqishi 1 yoshgacha cho‘zilishi mumkin. Ammo milklar allaqachon shishgan va og‘riqli bo‘lishi mumkin. Chaqaloqning milklarini toza, nam va sovuq doka bilan uqalash unga katta yengillik beradi. Shuningdek, bu oylarda ko‘p so‘lak ajralishi terini ta’sirlantirmasligi uchun og‘iz atrofini quruq tuting va himoya kremlaridan foydalaning.') WHERE id = '5905275f-db82-478c-ba85-c28c03e494ac';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqat berishni boshlaganingizda chaqaloq najasining (taglik ichidagining) rangi, hidi va quyuqligi keskin o‘zgaradi. Bundan qo‘rqmang! Ichaklar ilk bor sutdan boshqa mahsulotni hazm qilishga urinmoqda. Ba’zan sabzavotlar hazm bo‘lmasdan, deyarli o‘z holicha chiqishi mumkin, bu ham normal. Eng muhimi, chaqaloqda kuchli qorin og‘rig‘i yoki qabziyat paydo bo‘lmasin. Agar shunday holat yuz bersa, bergan mahsulotingizni bir necha kunga to‘xtatib, sutga ustunlik bering.') WHERE id = '2175d91f-594f-42b1-b5ca-5375fe51dcff';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning "mayda motorika"sini tekshiring: u endi buyumlarni kafti bilan emas, barmoqlari bilan (hali to‘liq "pinset" usulida bo‘lmasa ham) ushlashga harakat qiladi. Unga ushlashi uchun xavfsiz, turli shakldagi o‘yinchoqlar bering. Bu davrda rezina, mato va yog‘och materiallar o‘rtasidagi farqni his qilish uning sezgi rivoji uchun juda muhim. Unutmang, u hali ham hamma narsani "og‘zi bilan tekshiradi", shuning uchun o‘yinchoqlarning tozaligiga va ularda mayda qismlar yo‘qligiga e’tibor bering.') WHERE id = 'ad5ab394-baf9-4d75-b342-9b228c2343bc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ertaga chaqalog‘ingiz roppa-rosa yarim yoshga (6 oyga) to‘ladi! Bugun qo‘shimcha ovqat tayyorlash uchun zarur bo‘lgan barcha narsalarni (bug‘da pishirgich, blender yoki oddiy elak, plastik idishlar) yana bir bor tekshirib chiqing. Ammo eng muhimi — ruhiy tayyorgarlik. Chaqaloq birinchi qoshiqdagi ovqatni tuflab chiqarishi, yuz-ko‘ziga surtib yuborishi yoki umuman yeyishni istamasligi mumkin. Asabiylashmang va majburlamang. Birinchi oyning maqsadi qornini to‘ydirish emas, balki uni turli ta’mlar bilan tanishtirishdir. Sabringiz bu jarayonning eng muhim tarkibiy qismidir.') WHERE id = '99a11b8e-07bd-49f3-b3dd-d51a0720e2b5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, ajoyib Ona! Bugun chaqalog‘ingiz 6 oylik bo‘ldi! Siz yo‘lning yarmini (birinchi yilning yarmini) muvaffaqiyatli bosib o‘tdingiz. Chaqalog‘ingizning vazni tug‘ilgan paytdagiga nisbatan taxminan ikki baravar oshdi va u atrofdagi olamga to‘liq moslashdi. Bugun u bilan birinchi rasmiy "ovqat bayrami"ni nishonlang. Bir necha qoshiq pyuredan boshlanadigan bu sarguzasht uning ulg‘ayishidagi yangi bosqichdir. O‘zingiz bilan faxrlaning: uyqusiz tunlar va cheksiz mehnatingiz samarasini bugun uning sizga boqib, shirin jilmayishida ko‘rishingiz mumkin!') WHERE id = '6314b77b-4ba8-4969-86b0-43b2ae2976dd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '7-oyga xush kelibsiz! Qo‘shimcha ovqatlar bilan tanishish sarguzashti rasman boshlandi. Dastlabki kunlarda chaqaloq ovqatni tili bilan itarib chiqarayotganini ko‘rsangiz, xavotir olmang; bu uning bir necha oydan beri o‘rganib qolgan emish refleksi bilan bog‘liq tabiiy reaksiya. Unga atigi 1-2 choy qoshiq pyure taklif qiling va majburlamang. Bu bosqichdagi maqsadimiz chaqaloqning qornini to‘ydirish emas, balki uni turli ta’m va teksturalar bilan tanishtirishdir. Ona suti yoki sutli aralashma hali ham uning asosiy energiya manbai hisoblanadi.') WHERE id = '359c78b7-5eb4-4ddd-8230-6dac6d1fbced';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ilk sabzavotlardan so‘ng chaqaloq najasining rangi va hidi o‘zgarishi mutlaqo tabiiy. Agar taglikda pyure deyarli o‘zgarmagan, ya’ni hazm bo‘lmagan holda chiqqanini ko‘rsangiz, qo‘rqmang; chaqaloqning ovqat hazm qilish tizimi yangi mahsulotlarga moslashishga harakat qilmoqda. Asosan terida to‘satdan qizarish, toshma yoki qorin sohasida kuchli dam bo‘lish kuzatilmayotganiga e’tibor bering. Bu belgilar bo‘lmasa, hammasi joyida!') WHERE id = 'e2b1e9c6-06ca-442f-a823-59969208dc77';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqat berishni boshlagan kundan boshlab chaqaloqqa suv ham taklif qila boshlang. Chaqaloqning kunlik suvga ehtiyoji hali ko‘p emas, ammo ovqatdan keyin bir necha qultum suv ichish og‘iz bo‘shlig‘ini tozalaydi va kelajak uchun foydali odatni shakllantiradi. Suvni so‘rg‘ichli shishada emas, kichik piyolada yoki maxsus ichish idishida (sipper cup) berishga harakat qiling. Bu uning pastki jag‘ mushaklari boshqacha tarzda rivojlanishiga yordam beradi.') WHERE id = '0368b56f-7108-4cef-9b22-96d46e080b4f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '3 kun kutish qoidasiga amal qilyapsizmi? Organizmning reaksiyasini kuzatish uchun har bir yangi sabzavot yoki mevani bittadan bering. Masalan, bugun qovoq pyuresini taklif qilsangiz, keyingi 2 kun davomida boshqa yangi mahsulot qo‘shmang. Bu allergiya yuzaga kelsa, "aybdor" mahsulotni darhol aniqlashingizga yordam beradi. Sabrli bo‘ling, chaqaloqning ta’m retseptorlari hozir xuddi laboratoriyadek ishlamoqda!') WHERE id = '6a73b0da-2d2c-48e8-a871-941a5e9014db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz ovqatlanish paytida qoshiqni qo‘lingizdan olishga yoki qo‘llarini pyurega tiqishga urinayaptimi? Unga xalaqit bermang! Chaqaloqlar ovqatni nafaqat ta’mi, balki unga tegish orqali ham o‘rganadilar. Atrofning biroz ifloslanishi tabiiy; bu "ifloslik" uning hissiy rivojlanishi va mustaqil ovqatlanish ko‘nikmalari uchun muhim. Ovqatning teksturasini his qilishiga imkon bering — bu kelajakda "ovqat tanlash" muammosining oldini olishning eng yaxshi usullaridan biridir.') WHERE id = '81644d16-8ba2-4b27-83e5-5d3f50deae69';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqat berish davrida ich qotishi kuzatilishi mumkin. Chaqaloqning ichaklari sutdan boshqa mahsulotlarni hazm qilishga o‘rganmoqda. Agar chaqaloq kuchansa va najasi juda qattiq bo‘lsa, pyuresiga biroz zaytun moyi qo‘shish yoki olxo‘ri pyuresi berish foydali bo‘lishi mumkin. Yetarli miqdorda suv ichirishni unutmang. Muammo uzoq davom etsa, albatta pediatr bilan maslahatlashing, ammo dastlabki kunlarda bunday o‘zgarishlar kuzatilishi tabiiy.') WHERE id = '467b7c20-7f80-4ea7-b9c0-93bd0e277a7e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '6 oydan keyin chaqaloqning xotirasi va diqqat-e’tibori ancha kuchayadi. U endi buyumlarning nomlarini ular bilan bog‘lay boshlaydi. Masalan, «to‘p qayerda?» desangiz, uni ko‘zlari bilan qidiradi. U bilan shunday savol-javob o‘yinlarini o‘ynang. Siz, shuningdek, uning «tovushlar kutubxonasi»siz. U qancha ko‘p so‘z eshitsa, miyasidagi lug‘at zaxirasi shuncha tez boyiydi. Uni katta odamdek tinglang va chiqargan har bir tovushiga mazmunli javob bering.') WHERE id = '5b5665e4-15b0-42d4-8279-20912bd71937';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi tayanchsiz o‘tirishga yanada ishonch bilan harakat qilyaptimi? Son va bel mushaklarini mustahkamlash uchun «polda vaqt o‘tkazish» eng yaxshi mashqdir. Uni qorni bilan yotqizib, oldiga biroz uzoqroqqa qiziqarli o‘yinchoq qo‘ying. U o‘yinchoqqa yetish uchun gavdasini burishga va hatto emaklashga urinishi mumkin. Bu harakatlar tana koordinatsiyasi uchun juda muhim. Unutmang, har bir yiqilish — o‘rganish tajribasi, faqat atrof xavfsiz ekaniga ishonch hosil qiling.') WHERE id = '85f7b4d5-b074-40cb-b8e7-126bfcb368b7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar chaqalog‘ingiz tunda yana tez-tez uyg‘ona boshlagan bo‘lsa, bu tish chiqishi yoki jismoniy faollikning ortishi bilan bog‘liq bo‘lishi mumkin. Chaqaloq kunduzi o‘rgangan harakatlarini (masalan, ag‘darilish yoki emaklashni) hatto uyqusida ham «takrorlaydi». Agar u yig‘lamayotgan bo‘lsa, darhol bag‘ringizga olishga shoshilmang; o‘zini o‘zi tinchlantirib, yana uxlab qolishga harakat qilishiga imkon bering. Shunchaki yonida ekaningizni his qildirishingiz (qo‘lingizni beliga qo‘yishingiz) yetarli bo‘lishi mumkin.') WHERE id = 'aa9eef25-9e2b-4d46-bc09-aebaa1272eaa';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Siz rasman 7-oyga ham kirib keldingiz! Chaqaloqning vazni tug‘ilgandagi vaznidan taxminan ikki baravar ko‘p bo‘lishi kerak (bu o‘rtacha ko‘rsatkich). Agar hali tishlari ko‘rinmagan bo‘lsa, xavotir olmang: suyaklari me’yorida rivojlanayotgan bo‘lsa, tishlari istalgan payt «salom» deyishi mumkin. Bugun unga tayyorlagan sabzavotli pyurega juda oz miqdorda (bir necha tomchi) yuqori sifatli sovuq usulda siqilgan zaytun moyi qo‘shib ko‘ring; bu ham hazm qilishga yordam beradi, ham foydali yog‘ kislotalari bilan miyasini oziqlantiradi.') WHERE id = 'd3b9ca7e-7233-4280-976e-e11828d20cca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar sabzavotlar bilan allaqachon do‘stlashgan bo‘lsangiz, asta-sekin oqsillar olamiga o‘tishimiz mumkin. Go‘sht bilan ilk tanishuv uchun yog‘siz mol go‘shti, kurka yoki quyon go‘shti eng yaxshi tanlovdir. Go‘shtni juda yaxshi pishirib, bir xil mayin pyure holiga keltiring va sabzavotli pyurega qo‘shing. Go‘sht chaqaloqning tez kamayib borayotgan temir zaxirasini to‘ldirish uchun eng muhim oziq-ovqatdir. Dastlabki kunlarda atigi bir choy qoshiq go‘shtli pyure yetarli.') WHERE id = 'd543dbe5-6df1-4d22-a7ce-cbb22da34fc3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi o‘yinchoqni bir qo‘lidan ikkinchisiga o‘tkaza oladimi va bir vaqtning o‘zida ikkala qo‘li bilan harakat qila oladimi? Bu miya yarimsharlarining muvofiqlashgan holda rivojlanayotganidan dalolat beradi. U bilan «ushla-qo‘yib yubor» o‘yinlarini o‘ynang. Masalan, bir qo‘liga o‘yinchoq bering, keyin o‘sha qo‘liga ikkinchi o‘yinchoqni taklif qiling; ko‘raylik-chi, birinchisini boshqa qo‘liga o‘tkazib, yangisini olarmikan? Bu oddiy mashq uning nozik motorikasini ham, muammoni hal qilish ko‘nikmasini ham rivojlantiradi.') WHERE id = 'a8158232-7247-4508-af89-b5e8c2455782';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tuxum sarig‘i bilan tanishtirish vaqti keldi! Tuxumni qattiq qilib pishiring va sarig‘idan atigi no‘xat donasidek qismini ona suti yoki pyure bilan aralashtirib bering. Tuxum sarig‘i miya rivojlanishi uchun muhim bo‘lgan xolin va yog‘ kislotalariga boy. Ehtiyot bo‘ling: tuxum oqi (protein) kuchli allergen bo‘lgani uchun 1 yoshgacha tavsiya etilmaydi. Har safar sarig‘ining miqdorini biroz oshirib, chaqalog‘ingizning reaksiyasini kuzating.') WHERE id = '348776a6-90b7-44de-bed5-439f8ce3ea57';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz emaklash uchun "start" holatiga o‘tyaptimi? U qo‘llari va tizzalariga tayanib, oldinga-orqaga tebranishi mumkin. Bu "tebranish" orqali u muvozanat hissi va mushaklarining kuchini sinab ko‘radi. Buni ko‘rganingizda uni maqtang va ruhlantiring. Emaklashni boshlashi uchun pol sirpanchiq bo‘lmasligiga e’tibor bering (gilam yoki yumshoq mat ideal). Ko‘p o‘tmay u uyning har bir burchagiga yetib boradi!') WHERE id = '075eebcf-bf5d-40ba-b7ae-a5f38e71818b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqatlantirish davrida suv ichish endi tanlov emas, balki zaruratdir. Chaqaloqning buyraklari yangi ovqatlarni qayta ishlayotganda ko‘proq suvga ehtiyoj sezadi. Agar chaqalog‘ingiz suv ichishni istamasa, turli xil ichgichlar (sipper cup) yoki kichik rangli stakanlar bilan uning qiziqishini uyg‘oting. Suvni ovqatdan keyin darhol va kun davomida tez-tez taklif qiling. Unutmang, sharbatlar va kompotlar suvning o‘rnini bosa olmaydi; toza suv eng sog‘lom tanlovdir.') WHERE id = '5ed536ec-a0b5-4447-9d9a-377e3e5da4a3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Ajralish xavotiri" (Separation anxiety) shu kunlarda yaqqolroq namoyon bo‘lishi mumkin. Siz xonadan chiqishingiz bilan chaqalog‘ingizning qattiq yig‘lashi uning "injiq" ekanini emas, sizni yo‘qotishdan qo‘rqayotganini anglatadi. Xonadan chiqayotganda, albatta, unga ovoz bering: "Onang oshxonada, hozir keladi". Ovozingizni uzoqdan eshitishi unga xotirjamlik va ishonch beradi. "Ku-ku" o‘yinini murakkabroq shakllarda o‘ynang; yashirinib, boshqa joydan chiqishingiz unga bu qo‘rquvni yengishga yordam beradi.') WHERE id = '9d97a34c-0a55-4e17-9a40-0912d5c81137';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizning terisida, ayniqsa og‘iz atrofi yoki tanasida to‘satdan qizarish paydo bo‘lsa, so‘nggi 3 kun ichida bergan yangi ovqatlaringizni eslang. Agar allergik reaksiyadan shubhalansangiz, shu ovqatni darhol berishni to‘xtating va 1-2 haftadan keyin yana (oz miqdorda) sinab ko‘ring. Ba’zan organizm shunchaki ovqatning tuzilishiga reaksiya bildiradi, ba’zan esa bu haqiqiy allergiya bo‘lishi mumkin. Shubhali holatlarda pediatr bilan maslahatlashish eng to‘g‘ri yo‘ldir.') WHERE id = 'c73b10f1-26e8-49f8-a842-9fc9eb05c61a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uydagi xavfsizlik darajasini yana bir bor tekshiring. Chaqaloq endi buyumlarga qo‘l uzatadi, ularni tortadi va ta’mini ko‘rishga harakat qiladi. Elektr rozetkalariga himoya qopqoqlarini o‘rnating, o‘tkir burchaklarni yumshating. Eng muhimi: polda yoki gilam ustida hech qanday mayda buyum (tugma, munchoq, batareyka) qolmasligi kerak. Chaqaloqning ko‘rish qobiliyati shunchalik o‘tkirki, hatto siz ko‘rmagan mayda ipni ham topib, og‘ziga solishi mumkin.') WHERE id = 'cb68fae9-cc1f-40fd-8358-d8d8262537c7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Ma-ma", "Ba-ba", "Da-da" kabi bo‘g‘inlarni takrorlash endi yanada ritmik va davomli bo‘ladi (takroriy g‘uldirash). U endi sizning ohangingizga taqlid qilishga urinadi. Siz u bilan gaplashganingizda, u ham sizga "javob" beradi. Bu suhbatlarni davom ettiring! U tovush chiqarganda diqqat bilan tinglang, so‘ng: "Ha, rostdanmi? Keyin nima bo‘ldi?" deb javob bering. Bu uning muloqot qilish istagini kuchaytiradi va nutq markazini faollashtiradi. Siz uning eng yaxshi muloqot sherigisiz.') WHERE id = 'cfd5a392-f80a-4d2d-a1a6-3083e4ec4e6d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Qo‘shimcha ovqatlar ratsioniga donli bo‘tqalarni faolroq kiriting. Agar hali boshlamagan bo‘lsangiz, guruch, grechka va makkajo‘xori unidan tayyorlangan bo‘tqalar eng yaxshi tanlovdir, chunki ular tarkibida glyuten yo‘q. Bo‘tqani juda quyuq qilmang, dastlab uni ona suti yoki sun’iy sut aralashmasi bilan suyultirib bering. Donli mahsulotlar chaqaloqqa uzoq muddatli energiya beradi va uning tunda uzluksizroq uxlashiga yordam berishi mumkin (albatta, agar uyg‘onishiga ochlik sabab bo‘lsa).') WHERE id = 'a9b193a4-5558-4e20-a84e-1718f45d9ce1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz buyumlarni endi kafti bilan emas, barmoqlari bilan ushlay boshladimi ("qisqichsimon ushlash"ga tayyorgarlik)? Bu uning mayda motorikasi rivojida katta sakrashdir. Unga ushlash uchun xavfsiz, juda mayda bo‘lmagan, ammo barmoqlari bilan tuta oladigan o‘yinchoqlar bering. Ehtiyot bo‘ling: bu ko‘nikma uning yerda ko‘rgan eng kichik ip yoki chang zarrasini ham ushlab, og‘ziga solishi mumkinligini anglatadi. Endi uyni toza saqlash va polda mayda buyumlar bo‘lmasligi har qachongidan ham muhim.') WHERE id = 'f62f3f3e-4b0d-4001-8523-9219c3da8c5d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqillik" davri boshlanmoqda! Ovqatlanish vaqtida unga o‘z qoshig‘ini ushlab turishga ruxsat bering. Ha, hamma joy iflos bo‘ladi, pyure chaqaloqning sochiga ham, sizning yuzingizga ham tegadi, ammo bu o‘zini boshqarish ko‘nikmalarini rivojlantirish uchun beqiyos tajribadir. Bir qoshiq uning qo‘lida bo‘lsin, ikkinchi qoshiq bilan esa siz uni ovqatlantiring. Shunda u o‘zini ovqatlanish jarayonining faol ishtirokchisi sifatida his qiladi. Bu kelajakda "ovqat yeyishni istamayman" degan injiqliklarning oldini olishning eng yaxshi usullaridan biridir.') WHERE id = '60871d42-5c1c-446f-a627-a65d4f2f7fcb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar tish chiqish jarayoni hali ham davom etayotgan bo‘lsa, chaqaloqning ishtahasi pasayishi mumkin. Og‘riyotgan milklar bilan qattiq yoki issiq ovqat yeyish unga yoqmasligi mumkin. Bunday kunlarda uni majburlamang, ko‘proq ona suti bering yoki ovqatlarni xona haroratidan biroz salqinroq holda taklif qiling. Sovuq meva pyuresi milklarini tinchlantirishi mumkin. Sabrli bo‘ling, bu noqulaylik vaqtinchalik. Eng muhimi, unda ovqatga nisbatan salbiy hissiyotlar paydo bo‘lmasin.') WHERE id = 'd3067cbe-ce54-41b6-9dd3-9072dfcf2c69';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 7-oyning oxiriga yetib keldingiz! Chaqalog‘ingiz endi o‘z ismini yaxshi taniydi va chaqirganingizda siz tomonga o‘giriladi. U his-tuyg‘ularini yanada aniqroq namoyon etadi: xursand bo‘lsa qichqiradi, o‘yinchog‘ini qo‘lidan olsangiz, noroziligini bildiradi. Bu uning shaxsiyati shakllanayotganidan dalolat beradi. Bugun u bilan birga yerga yotib, shunchaki o‘ynang — u sizning e’tiboringizni hamma narsadan ko‘proq qadrlaydi. Siz ajoyib yo‘lni bosib o‘tdingiz, ona!') WHERE id = 'bd6cd20e-2a94-483e-b4a1-ed0a0a344bf5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqu yana buzilishi mumkin. Bunga ko‘pincha "harakat rivoji" sabab bo‘ladi. Chaqaloq kunduzi o‘rgangan harakatlarini (masalan, tizzalarida turishni) hatto uyqusida ham takrorlashni xohlaydi. Agar u tunda tizzalarida turib tebransa, uni darhol quchog‘ingizga olmang. Xotirjamlik bilan yana yotqizing va belini silang. Unga o‘zini o‘zi tinchlantirishni o‘rganishi uchun imkon bering.') WHERE id = 'e9e1b950-57d8-4d65-82e5-7c7681ec6159';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Chaqalog‘ingiz 200 kunlik bo‘ldi! Bu juda katta marradir. Endi siz "yangi ona" emas, ancha tajribali ota-onasiz. Chaqalog‘ingiz sizga qarab jilmayganida, sizni quchoqlashga uringanida, qilgan barcha mehnatingiz behuda emasligini his qilasiz. Bugun uning uchun alohida "ta’m festivali" uyushtiring — sevimli sabzavotlari va go‘sht aralashmasidan mazali pyure tayyorlang. Siz ajoyibsiz, Onajon!') WHERE id = '8ef38899-1def-4d57-bd7d-f28245d50ca5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '200 kunlik katta marrani ortda qoldirdik, endi esa menyuni biroz rang-barang qilamiz! Agar chaqalog‘ingiz sabzavot va go‘shtli pyurelarga o‘rganib qolgan bo‘lsa, ratsionga mevalarni kiritishning ayni vaqti. Avval olma, nok yoki banandan boshlang. Mevalarni bug‘da pishirib, pyure holiga keltirish (yoki shisha qirg‘ichdan o‘tkazish) hazm qilish uchun osonroq. Ehtiyot bo‘ling: mevalarning shirin ta’mi chaqaloqqa juda yoqib qolishi mumkin. Shu sababli u sabzavotlarni unutib qo‘ymasligi uchun mevani odatda kunning ikkinchi yarmida desert sifatida taklif qilgan ma’qul.') WHERE id = '52048f39-dc3c-4433-994b-496425ac059d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizning o‘tirish ko‘nikmasi endi "Tripod" holatidan (qo‘llarini yerga tirab o‘tirishdan) chiqib, tikroq va erkinroq bo‘lishi kerak. Endi u qo‘llarini yerdan ko‘tarib, o‘yinchoq bilan o‘ynay oladi. Agar u hali ham tez-tez yon tomonga yiqilsa, xavotir olmang; bel mushaklarini mustahkamlashi uchun polda ko‘proq vaqt o‘tkazishiga sharoit yarating. Orqasiga yumshoq yostiqlar qo‘ying, ammo muvozanatni o‘zi topishiga imkon bering. Mustaqil o‘tirish uning uchun dunyoni butunlay boshqa burchakdan ko‘rish demakdir.') WHERE id = '9d5fc99c-ca1a-4324-a7ea-7d36c4768a6e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Sut mahsulotlari bilan tanishish vaqti keldi! Agar shifokoringiz bunga qarshi ko‘rsatma bermagan bo‘lsa, chaqalog‘ingizga uyda tayyorlangan tabiiy qatiq yoki tvorog (donador suzma) taklif qilishingiz mumkin. Qatiq kalsiyga boy bo‘lishi bilan birga, ichak mikroflorasi uchun foydali probiotiklarni ham o‘z ichiga oladi. Birinchi marta berganingizda atigi bir choy qoshiqdan boshlang va teridagi reaksiyalarni kuzating. Unutmang: do‘konlarda sotiladigan mevali va shakarli "bolalar yogurtlari"dan saqlaning, eng foydalisi — uyda o‘zingiz tayyorlagan oddiy qatiq.') WHERE id = '8027ff1e-e9f7-4f2e-9aa6-3293659f2fb7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz buyumlarni bir-biriga urib, tovush chiqarishdan zavqlanyaptimi? Bu uning "Sabab-Oqibat" bog‘lanishini chuqur o‘rganayotganini bildiradi: "Agar men bu ikki o‘yinchoqni bir-biriga ursam (sabab), tovush chiqadi (oqibat)". Unga turli materiallardan (yog‘och, plastmassa, mato) tayyorlangan o‘yinchoqlar bering, shunda u tovushlar va teginishlar o‘rtasidagi farqni anglaydi. Bu oddiy o‘yin uning eshitish qobiliyatini ham, harakat ko‘nikmalarini ham rivojlantiradi. Oshxonadagi plastmassa idishlar va yog‘och qoshiqlar ba’zan eng qimmat o‘yinchoqdan ham qiziqroq bo‘lishi mumkin!') WHERE id = '580f2e78-b4ac-4e71-a08f-98de51b2b255';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '8-oyga xush kelibsiz! Bu oy chaqaloq "mustaqil kashfiyotchi" maqomini oladigan davrdir. U endi emaklab, xonaning bir burchagidan ikkinchisiga tez yetib bora oladi. Agar chaqalog‘ingiz hali emaklamayotgan bo‘lsa, xavotir olmang; ayrim bolalar emaklamasdan, to‘g‘ridan-to‘g‘ri oyoqqa turish va yurishga o‘tadi. Uni rag‘batlantirish uchun sevimli o‘yinchog‘ini biroz uzoqroqqa qo‘ying va unga yetib borishga harakat qilishiga imkon bering. Uning har bir kichik yutug‘i — katta g‘alaba!') WHERE id = 'ecb494cd-7c29-44d1-ad94-78d5bacf0eb8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi pyurelarning tuzilishini asta-sekin o‘zgartirish vaqti keldi. Taomlarni blenderdan o‘tkazish o‘rniga, sanchqi bilan ezishni boshlang. Chaqaloqning tishlari hali chiqmagan bo‘lsa ham, u yumshoq bo‘laklarni milklari bilan ezishni o‘rganishi kerak. Bu chaynash mushaklarini rivojlantiradi va kelajakda nutq qobiliyatiga ijobiy ta’sir ko‘rsatadi. Dastlab qayt qilish refleksi (gag reflex) kuzatilishi mumkin, bu normal holat; shunchaki yonida bo‘ling va uni ruhlantiring.') WHERE id = '2727a145-103d-40b1-93bd-853efdc6e639';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz buyumlarga suyanib oyoqqa turishga urinyaptimi? Divan chetlari, stullar va hatto oyoqlaringiz ham uning uchun tayanch bo‘la oladi. Bu davrda uydagi mebellarning mustahkam va barqaror turishiga e’tibor bering. Yengil stullar yoki burchakli mebellar ag‘darilib ketishi mumkin. Mebellarning o‘tkir burchaklariga maxsus yumshoq himoya vositalarini o‘rnatishning ayni vaqti, chunki oyoqqa turishga urinishlar ko‘pincha kichik yiqilishlar bilan yakunlanadi.') WHERE id = '2b052f0a-26d0-4470-a503-c5a76302b58f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Taomnomasiga baliq qo‘shishni o‘ylayapsizmi? Agar oilada baliqqa kuchli allergiya bo‘lmasa, oq go‘shtli baliqlar (masalan, dengiz okuni yoki suyaksiz oq baliqlar) Omega-3 ning ajoyib manbaidir. Baliqni bug‘da pishiring va ichida zarracha ham suyak qolmaganiga ishonch hosil qilish uchun qo‘lingiz bilan yaxshilab tekshiring. Baliq miya rivoji va ko‘rish qobiliyati uchun juda foydali. Haftada bir marta kichik porsiyadan boshlashingiz mumkin.') WHERE id = '1d9818aa-0e5b-4ba9-aefe-a8e9678137db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Yo‘q" so‘zi bilan tanishuv! Chaqaloq endi ovoz ohangingizdagi o‘zgarishni tushunadi. U xavfli narsaga qo‘l uzatganida jiddiy ohangda "Yo‘q" yoki "Mumkin emas" desangiz, to‘xtab sizga qarashi mumkin. Biroq bu so‘zni juda tez-tez ishlatmang, aks holda u ta’sirini yo‘qotadi. Uni faqat haqiqiy xavf tug‘ilgan paytlarda (masalan, elektr rozetkasiga tekkanda) ishlating. Boshqa holatlarda uning diqqatini qiziqarliroq o‘yinchoqqa yo‘naltirish samaraliroqdir.') WHERE id = 'f3741479-5e2c-4a17-a78f-8627ec0b11aa';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning "pinsetsimon ushlashi" (pincer grasp) yanada takomillashmoqda. Endi u bosh va ko‘rsatkich barmoqlari bilan mayda bo‘laklarni ushlay oladi. Bu ko‘nikmani rivojlantiradigan "qo‘lda yeyiladigan taomlar"ni (finger foods) taklif qiling: yaxshilab pishirilgan yumshoq sabzi tilimlari, banan bo‘laklari yoki pishirilgan qovoq. Bu uning harakat ko‘nikmalarini rivojlantirish bilan birga, mustaqil ovqatlanishni o‘rganishiga ham yordam beradi. Uni doimo nazorat ostida tuting!') WHERE id = '832beb7b-28cb-4a32-9588-55e7154e59b5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tayanchga suyanib yurishga ilk urinishlar! Chaqalog‘ingiz divan yoki stuldan ushlab, yonlama qadam tashlay boshlashi mumkin. Bu "cruising" deb ataladi. Bu bosqichda unga poyabzal kiydirishga shoshilmang; uyda yalangoyoq (yoki sirpanmaydigan paypoqda) harakatlanish oyoq mushaklarining to‘g‘ri shakllanishi va muvozanatni his etishi uchun eng yaxshisidir. Oyoq barmoqlari bilan yerni his qilish uning miyasiga ko‘proq ma’lumot yetkazadi.') WHERE id = '0028192c-1744-4eba-bb7a-f5c3b5d11c54';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning "mayda motorika"sini tekshiring: u endi o‘yinchoqni bir qo‘lidan ikkinchisiga bemalol o‘tkazadi va bosh barmog‘ini boshqa barmoqlariga qarama-qarshi qo‘ya oladi. Bu davrda unga turli shakl va rangdagi "piramida" o‘yinchoqlarini yoki bir-birining ichiga joylanadigan idishlarni bering. Hali halqalarni to‘g‘ri ketma-ketlikda tera olmasa ham, ularni ajratib, qayta yig‘ish uning fazoviy idroki va harakatlar muvofiqligini nihoyatda rivojlantiradi.') WHERE id = 'b139a999-0910-43e1-b5bf-dc2f0d783db4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Menyuni rang-barang qiling: agar hali sinab ko‘rmagan bo‘lsangiz, dukkakli mahsulotlarni (masalan, qizil yasmiqni) bera boshlashingiz mumkin. Yasmiq o‘simlik oqsili va temir manbaidir. Ammo ehtiyot bo‘ling, dukkaklilar qorin dam bo‘lishiga olib kelishi mumkin. Shuning uchun yasmiqni oldindan ivitib, sabzavotli sho‘rvaga juda oz miqdorda qo‘shing. Chaqaloqning ovqat hazm qilish tizimi qanday reaksiya bildirishini kuzating; agar hammasi yaxshi bo‘lsa, bu uning uchun juda to‘yimli tushlik bo‘ladi.') WHERE id = '071fb8f4-fce6-4526-aae9-c60d8797b1ea';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy ko‘nikmalar: chaqalog‘ingiz endi "xayr" (qo‘l silkitish) yoki "barakalla" (qarsak chalish) harakatlarini takrorlay oladi. Siz qarsak chalganingizda u ham sizga taqlid qilsa, bu uning taqlid qilish qobiliyati yaxshi rivojlanganini ko‘rsatadi. Bu harakatlarni o‘yinga aylantiring. Taqlid qilish — o‘rganishning eng qisqa yo‘li. Har bir muvaffaqiyatli harakatidan so‘ng uni jo‘shqinlik bilan maqtang, bu uning o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = '5cd6ae76-cf22-4b82-a5b7-ee78e7b002f5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xavfsizlik bo‘yicha ogohlantirish: chaqaloq endi baland joylarga tirmashishga moyil bo‘ladi. Shkaf tortmalari uning uchun zinapoya vazifasini bajarishi mumkin. Tortmalarga maxsus qulflar o‘rnatishning ayni vaqti. Shuningdek, og‘ir mebellar (kitob javoni, komod) devorga mahkamlanganiga ishonch hosil qiling. Chaqaloq ularni tortib, o‘z ustiga ag‘darib yuborishi mumkin. Xavfsiz uy — erkin kashf etish imkoniyati demakdir.') WHERE id = 'a8f4ab5e-3832-4512-afc4-44fcec1c8a18';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Suv ichish odati: chaqaloqning buyraklari qo‘shimcha ovqatlarni qayta ishlagani sari uning suvga ehtiyoji ortadi. Agar chaqalog‘ingiz suv ichishni rad etsa, unga suvni turli qiziqarli usullarda taklif qiling. Masalan, o‘zingiz suv ichayotganingizda unga ham taklif qiling, chunki u sizga qarab o‘rganadi. Suvni doimo uning qo‘li yetadigan joyda saqlang. Toza suv uning hazmini tartibga soladi va qabziyat xavfini kamaytiradi.') WHERE id = '73e0efe7-8cf6-4415-b315-772133307918';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'E’tibor berdingizmi, chaqalog‘ingiz o‘yinchoqni tashlaganida endi uning qayerga tushganiga qaraydi? Bu "obyekt doimiyligi" (object permanence) tushunchasi to‘liq shakllanganini ko‘rsatadi. U o‘yinchoq ko‘rish maydonidan chiqib ketsa ham yo‘qolib qolmaganini, shunchaki yerga tushganini biladi. Shu sababli sizning xonadan chiqib ketishingizga keskinroq munosabat bildirishi mumkin. Ketayotganingizni va albatta qaytib kelishingizni unga his qildiradigan qisqa "xayrlashuv" odatlarini yarating.') WHERE id = '2f260480-889e-4da7-8269-7ccb344f483a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizning uyqu tartibida o‘zgarish bo‘lishi mumkin. 8-oyda ayrim chaqaloqlar kunduzgi 3-uyqudan (kechga yaqin mizg‘ib olishdan) voz kecha boshlaydi. Bu mutlaqo normal holat. Agar u kunduzi 2 marta uzoqroq uxlasa va kechqurun o‘z vaqtida uyquga ketsa, demak, sizlar yangi tartibga o‘tyapsizlar. Uning uyg‘oq qolish vaqti endi 2.5 - 3 soatgacha uzayishi mumkin. Undagi charchoq belgilarini (qulog‘ini qashish, ko‘zlarini ishqalash) kuzatishda davom eting.') WHERE id = '0800d9fe-eb08-4a4c-84c3-d676b21556f0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutq rivojlanishida yangi bosqich: chaqalog‘ingiz endi "o‘z tilida" uzoq-uzoq gaplar tuzayotganiga e’tibor berdingizmi? Bu "jargon" davridir. U kattalarning gapirish ohangiga taqlid qiladi, savol berayotgandek ovozini ko‘taradi yoki nimanidir tushuntirayotgandek qo‘l harakatlarini qiladi. Uni diqqat bilan tinglang va "Rostdanmi? Juda qiziq!" kabi javoblar bering. Bu uning muloqot qilish ishtiyoqini nihoyatda oshiradi.') WHERE id = '71cabae0-25d9-4b76-b251-aaf1f4412278';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 8-oyning dastlabki o‘n kuni ortda qoldi! Chaqalog‘ingiz endi his-tuyg‘ularini murakkabroq tarzda ifodalaydi: erkalik qiladi, noroziligini bildiradi yoki sizni ko‘rganda xursand bo‘lib chapak chaladi. Bugun u bilan polda "to‘p-to‘p" o‘ynang; to‘pni unga qarab dumalating, u esa uni tutishga yoki sizga qaytarib itarishga harakat qilsin. Bu oddiy o‘yin ham jismoniy, ham ijtimoiy aloqangizni mustahkamlaydi. Siz ajoyib yo‘l ko‘rsatuvchisiz, ona!') WHERE id = '9fdaa957-189e-4f2e-b893-b9625e6dd277';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Sut mahsulotlari bilan tanishishni davom ettiramiz! Agar hali boshlamagan bo‘lsangiz, ratsionga uyda tayyorlangan tvorog (lor) qo‘shishning ayni vaqti. Tvorog kalsiy va oqsilga boy bo‘lib, chaqaloqning suyaklari va tishlari rivojlanishi uchun juda muhimdir. Uni meva pyuresi bilan aralashtirib, yanada mazali qilishingiz mumkin. Unutmang, agar tvorogni do‘kondan sotib olsangiz, albatta shakarsiz, qo‘shimchalarsiz va bolalar uchun mo‘ljallangan turini tanlang.') WHERE id = 'ae94f7bd-20c4-400d-a0b5-4fc94f6e2927';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi o‘z tana a’zolarini taniy boshlaydi. Undan "burning qayerda?", "ko‘zlaring qayerda?" deb so‘rang va o‘z yuzingizda ko‘rsating. Bu oddiy o‘yin uning so‘z boyligini oshiradi hamda o‘zini alohida shaxs sifatida anglashiga yordam beradi. Ko‘zgu qarshisida turib, uning qo‘llari va oyoqlarini ko‘rsatish bu jarayonni yanada qiziqarli qiladi. U endi ko‘zgudagi aks nimani anglatishini tushunishga yaqin.') WHERE id = 'c515c840-71f3-41f7-b139-398b94946105';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '9-oyga xush kelibsiz! Bu oy chaqaloqning "ongli muloqot" davri boshlanadi. Endi u "Ma-ma" yoki "Da-da" deganda shunchaki tovushlarni mashq qilmaydi, balki bevosita sizga yoki dadasiga murojaat qiladi. Sizga qarab bu so‘zlarni aytganida, quvonch bilan javob bering va uni quchoqlang. Sizning bunday ijobiy munosabatingiz unga so‘zlarning kuchi va ma’nosini o‘rgatadi. Endi u til orqali o‘z istaklari va mehrini ifodalashi mumkinligini tushunadi.') WHERE id = 'c35ed773-5541-46b9-a100-13e031ebc738';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Sudralishdan emaklashga (tizza va qo‘llarga tayangan holda harakatlanishga) to‘liq o‘tish! Chaqalog‘ingiz endi qornini yerdan ko‘tarib, to‘rt oyoqlab tez harakatlanadi. Bu harakat uning miya yarimsharlari o‘rtasidagi o‘zaro muvofiqlashuvni takomillashtiradi. Emaklash kelajakda o‘qish va yozish uchun zarur bo‘ladigan ko‘rish-harakat muvofiqligining ham asosidir. Uyning hamma joyini o‘rganishiga imkon bering, faqat harakatlanadigan yo‘llari xavfsiz ekaniga ishonch hosil qiling.') WHERE id = 'eef05a4c-d9ba-43c9-8340-a35c1089e87f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanish xilma-xilligini oshirish: Endi chaqaloq ratsioniga dukkaklilarni (yashil yasmiq, loviya pyuresi) va tvorog bilan aralashtirilgan turli mavsumiy mevalarni bemalolroq qo‘shishingiz mumkin. Bu davrda chaqaloqning temir zaxirasini saqlash uchun qizil go‘sht yoki tuxum sarig‘ini yashil sabzavotlar bilan birga berishga harakat qiling. C vitamini (masalan, sabzavotga siqilgan bir necha tomchi limon sharbati) temirning so‘rilishini yaxshilaydi.') WHERE id = 'c2e87fad-ec56-47c4-9f57-fc56aefe9e8a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Qisqichsimon ushlash" (pincer grasp) endi chinakam mahoratga aylanmoqda. Chaqalog‘ingiz yerda ko‘rgan eng mayda ushoqni ham ikki barmog‘i bilan ushlaydi. Bu ko‘nikmani rivojlantirish uchun unga yumshoq pishirilgan no‘xat donalari yoki mayda tvorog bo‘laklarini taklif qiling. Mustaqil ovqatlanish uning o‘ziga bo‘lgan ishonchini sezilarli darajada oshiradi. Ammo ehtiyot bo‘ling: bu ko‘nikma uning tugma, munchoq kabi xavfli mayda buyumlarni ham osongina og‘ziga solishi mumkinligini anglatadi.') WHERE id = 'afe941be-e174-4b07-9f32-16d62d4cfe8e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi "Yo‘q" so‘zining ma’nosini to‘liq tushunadi. U xavfli ish qilayotganida "Yo‘q" desangiz, to‘xtab sizga qarashi, hatto norozilik bildirib yig‘lashi ham mumkin. Bu uning chegaralarni o‘rganishidagi ilk qadamdir. Biroq uyning hamma joyi "Yo‘q" degan taqiqlarga to‘lib ketmasin. Xavfli buyumlarni olib qo‘ying, shunda u bemalol "Ha" deyish mumkin bo‘lgan o‘yinlar bilan shug‘ullana oladi. Chegaralarni faqat haqiqatan muhim vaziyatlarda belgilang.') WHERE id = 'a85e4f35-e664-455a-b825-3e51d17e5f0d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Obyektning doimiyligi" o‘yini: Chaqalog‘ingiz endi o‘yinchoqni adyol ostiga yashirsangiz ham, u yo‘qolib qolmasligini biladi. O‘yinchoqni qisman yashiring va uni topishiga imkon bering. Bu o‘yin uning xotirasi va mantiqiy fikrlashini mustahkamlaydi. Shu bilan birga, "bekinmachoq" o‘yini uning ayriliqdan xavotirlanishini kamaytirishga yordam beradi; u siz ko‘zdan g‘oyib bo‘lsangiz ham, albatta qaytib kelishingizni tushunadi.') WHERE id = '0a1f58ae-f05c-4b6b-aa75-6ff0b27beddc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz sizga taqlid qilib, telefonda gaplashayotgandek tutyaptimi yoki sochini tarashga urinyaptimi? Bu — "funksional o‘yin" bosqichi. U buyumlar nima maqsadda ishlatilishini tushuna boshlaydi. Unga xavfsiz uy-ro‘zg‘or buyumlarini (plastik taroq, o‘yinchoq telefon, yog‘och qoshiq) berib, taqlid qilish qobiliyatini qo‘llab-quvvatlang. Taqlid qilish chaqaloqning ijtimoiy va intellektual rivojlanishi uchun eng kuchli vositalardan biridir.') WHERE id = '186aab21-e01b-4cb3-9b1b-f1b7cf5f3b0c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqat tuzilishini o‘zgartirish: Agar hali ham taomlarni butunlay pyure holida berayotgan bo‘lsangiz, bugundan boshlab mayda bo‘lakchalar miqdorini oshiring. Ovqatni butunlay ezib yubormang, ichida mayda va yumshoq bo‘laklar qolsin. Bu chaqaloqning chaynash ko‘nikmasini rivojlantiradi va milklarini chiniqtiradi. Agar chaqaloq bo‘laklarni tuflab tashlasa, uni majburlamang, ammo har ovqatlanishda bir necha bo‘lak bilan sinab ko‘rishda davom eting. Sabrli bo‘lsangiz, u tez orada oila dasturxonidagi taomlarga to‘liq moslashadi.') WHERE id = '0b1ada17-b48a-4258-81e3-556f2db2a842';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy muloqot: Chaqalog‘ingiz "bay-bay" deb qo‘l silkitishni yoki "barakalla" deganingizda chapak chalishni o‘rgandimi? Bu imo-ishoralar uning nutq shakllanishidan oldingi muloqot usullaridir. Siz qo‘l silkitsangiz, u ham sizga taqlid qilsa, bu uning sizga bog‘langanini va e’tiborini ko‘rsatadi. Bu harakatlarni qo‘shiqlar bilan birlashtirib, yanada maroqli qiling. Muloqot qilishga ishtiyoqi oshishi uchun uning har bir imo-ishorasiga quvonch bilan javob bering.') WHERE id = '88a30222-647e-4598-aa2c-f27d2f68a4e6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xavfsizlikning yangi bosqichi: Chaqaloq endi hamma narsaga tirmashib chiqishni xohlaydi. Past stollar va divan chetlari uning uchun "cho‘qqi"dir. Uydagi barcha og‘ir buyumlar va mebellarning mustahkam o‘rnatilganini tekshiring. Ayniqsa, elektr simlarini (kabellarni) yashiring, chunki ularni tortish chaqaloq uchun eng qiziqarli mashg‘ulotga aylanishi mumkin. Uyning xavfsizligi sizga xotirjamlik, unga esa atrofni bemalol o‘rganish imkonini beradi.') WHERE id = '42e1e998-0acc-4253-963b-1927f727ffd8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqu va "ajralish xavotiri": Chaqalog‘ingiz tunda uyg‘onib, sizni ko‘rmasa, qattiq yig‘lashi mumkin. Bu davrda unga xotirjamlik va ishonch berish muhim. Yoniga borganingizda chiroqni yoqmasdan, sokin ovozda "onang shu yerda, uxlayver" deb, uni silab qo‘ying. Uni darhol bag‘ringizga olib, xonadan olib chiqishga shoshilmang. Shunchaki yonida ekaningiz va ovozingiz unga yana uxlab qolishi uchun yetarli xotirjamlik beradi.') WHERE id = 'cab92102-e3a5-49d4-bbd8-bdc2525ea7fb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, to‘liq 8 oyni ortda qoldirdik! Chaqalog‘ingizning vazni tug‘ilgandagiga nisbatan taxminan uch baravar oshdi (bu o‘rtacha ko‘rsatkich). U endi juda faol, tovushlarni farqlaydi va oila a’zolarini taniydi. Bugun u bilan polda "to‘p-to‘p" o‘ynang: to‘pni unga qarab dumalating, u esa uni tutishga harakat qilsin. Bu o‘yin ko‘z va qo‘l muvofiqligini hamda navbat bilan harakat qilish (ijtimoiy qoida) ko‘nikmasini rivojlantiradi. Siz ajoyib yo‘lni bosib o‘tdingiz, Onajon!') WHERE id = 'eeeb250d-7860-4dbd-adfd-8f04383dcc0f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar tunda uyg‘onishlar davom etayotgan bo‘lsa, bunga "ayriliq xavotiri" bilan birga tish chiqishi ham sabab bo‘lishi mumkin. Odatda 8-9-oylarda yuqori kesuvchi tishlar "salom" deydi. Tish milklari shishgan va ta’sirchan bo‘lishi mumkin. Uxlashdan oldin toza barmog‘ingiz bilan milklarini yengil massaj qilsangiz, bu uni tinchlantiradi. Sabrli bo‘ling, bu bezovtalik vaqtinchalik, ammo sizning qo‘llab-quvvatlashingiz uning uchun doimiydir.') WHERE id = 'a7e2adf7-fa7d-49f9-b9df-6cb36632b7da';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 230 kunni ortda qoldirdik! Chaqalog‘ingiz endi his-tuyg‘ularingizni juda yaxshi anglaydi. Siz jilmayganingizda u ham quvonadi, jiddiy ohangda gapirganingizda esa to‘xtab, sizga qaraydi. Bugun u bilan yerga yotib, shunchaki "qitiq-qitiq" o‘yinini o‘ynang. Uning qahqahasi barcha charchog‘ingizni tarqatib yuboradi. Siz orangizda ajoyib rishta yaratdingiz, Onajon!') WHERE id = 'd3c12132-2a39-444c-81a2-79aa27f8b6cc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi ratsionga turli don mahsulotlarini (suli, arpa) kiritishingiz mumkin. Agar oilada glyutenga allergiya bo‘lmasa, suli (oat) bo‘tqasi chaqaloq uchun ham to‘yimli, ham tolaga boy nonushta bo‘ladi. Tolali mahsulotlar chaqaloq ichaklari faoliyatini tartibga soladi va qabziyatni bartaraf etadi. Bo‘tqaga biroz ezilgan banan yoki olma pyuresi qo‘shib, ta’mini yanada yoqimli qilishingiz mumkin.') WHERE id = 'f8aaab74-ed0b-4ea9-b26f-011f00ca98cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz buyumlarni bir-birining ichiga solishga yoki ustma-ust taxlashga urinayaptimi? Bu "fazoviy idrok" rivojlanayotganidan dalolat beradi. Unga turli o‘lchamdagi plastik stakanlar yoki bir-birining ichiga kiradigan idishlar bering. U kichik idish katta idish ichiga sig‘ishini kashf qilganida, miyasida yangi neyron aloqalar hosil bo‘ladi. Hozircha minora qurish qiyin bo‘lishi mumkin, ammo siz qurgan minorani buzish uning eng sevimli mashg‘ulotiga aylanadi!') WHERE id = '51ca7794-c77c-4014-b77a-c79e37d35c43';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tanasini tanish: Chaqalog‘ingiz endi "burun", "ko‘z", "og‘iz" deganingizda ularni ko‘rsatishi yoki siz ko‘rsatganingizda jilmayib javob qaytarishi mumkin. Bu uning o‘zini anglashidagi muhim bosqichdir. Cho‘miltirayotganda yoki kiyintirayotganda "endi o‘ng qo‘lingni kiyintiramiz", "endi chap oyog‘ingni yuvamiz" deb tana a’zolarini nomlang. Bu uning nutqi rivojlanishiga ham, tana tuzilishi haqidagi tasavvuri shakllanishiga ham yordam beradi.') WHERE id = '7184c458-15f9-4675-8f4b-a012153962e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Qo‘lda yeyiladigan taomlar" (finger foods) davridagi mahorat: Chaqalog‘ingiz endi ovqatning kichik bo‘laklarini (masalan, pishirilgan sabzi bo‘lagi yoki no‘xat donasini) barmoqlari bilan ushlab, bevosita og‘ziga olib borishda ancha mohir. Bu ko‘nikma unda o‘zini boshqarish va to‘yganini his qilish qobiliyatini rivojlantiradi. Stoliga xavfsiz, yumshoq taomlar qo‘ying va unga mustaqil ovqatlanish imkonini bering. Atrofning iflos bo‘lishi tabiiy, eng muhimi — uning bu ko‘nikmani egallashidir. Har doim yonida bo‘ling va kuzatib turing.') WHERE id = 'b13c96d3-3ebb-4786-a1ba-dda465e426a2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tayanch yordamida turish mahorati: Chaqalog‘ingiz endi hamma joyda — divan chetidan, stul oyog‘idan, hatto tizzalaringizdan ushlab o‘rnidan turadi. Biroq u hali qanday pastga tushishni bilmasligi va tik turgancha yordam so‘rab yig‘lashi mumkin. Unga qanday o‘tirishni ko‘rsating: tizzalarini bukib, sekin yerga tushiring. Bu uning tanasini boshqarish qobiliyati va muvozanat hissini rivojlantiradi.') WHERE id = 'd5785d23-fd09-4663-8877-2740ab81ecbc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqudagi "harakatli uyg‘onishlar": Chaqalog‘ingiz tunda to‘satdan emaklashi yoki uyqusiragan holda o‘rnidan turishga urinishi mumkin. Uning miyasi kunduzi o‘rgangan harakatlarini tunda takrorlaydi. Agar u yig‘lamasa, unga tegmang, o‘zi qulay holatni topib, yana uxlab qolsin. Agar yig‘lasa, xotirjam yoniga boring, chiroqni yoqmasdan uni joyiga yotqizing va taskin beruvchi so‘zlarni ayting. Bu davr vaqtinchalik.') WHERE id = '3ee50fc0-987b-4449-9a9a-aeac43eacebb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tish chiqishi va ovqatlanish: 9-oyda ko‘pincha yuqori yoki pastki yon kurak tishlar chiqadi. Bu davrda chaqaloqning milklari og‘rigani uchun u qattiq ovqatlarni rad etishi mumkin. Uni majburlamang, bir necha kun yumshoqroq va salqin taomlar (masalan, sovuq meva pyuresi yoki yogurt) bering. Tish chiqish jarayoni tugashi bilan ishtahasi qaytadi. Sizning sabr-toqatingiz va mehringiz uning uchun eng yaxshi dori.') WHERE id = '5c734779-7b9a-4eb8-a3df-dadd22df3bb2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 250 kunlik katta yo‘lni bosib o‘tdik! Chaqalog‘ingiz endi yuz ifodalaringizni juda aniq tushunadi. Siz quvonsangiz, u ham kuladi, jiddiy ohangda gapirsangiz, u to‘xtab, sizni kuzatadi. Bugun u bilan yerda "kitob tomosha qilish" vaqtini o‘tkazing. Katta rasmlari bor kitobdan hayvonlarni ko‘rsating va ularning ovozlariga taqlid qiling. U sizga taqlid qilishga urinadi. Siz uning dunyoni kashf etishidagi eng ishonchli yo‘lko‘rsatuvchisiz, Ona!') WHERE id = '4168c3b6-34fd-49a6-b076-88e5415caa27';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Siz allaqachon 9-oyning qoq o‘rtasidasiz! Chaqalog‘ingiz hozir buyumlarga tayanib o‘rnidan turishni yaxshi o‘zlashtirmoqda. Ammo eng muhim ko‘nikma hali oldinda: tik turgan joyidan xavfsiz tarzda yerga o‘tirish. Unga tizzalarini bukib, sekin o‘tirishni ko‘rsating. Agar u chalqancha yiqilsa, baqirib uni qo‘rqitmang; shunchaki yoniga boring va qanday to‘g‘ri harakat qilish kerakligini yana bir bor ko‘rsating. Bu uning tana koordinatsiyasini kuchaytiradi.') WHERE id = '8802254f-c7f7-4ff6-9b20-d9c01f14b494';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning imo-ishoralar orqali muloqoti endi aniq ma’no kasb etmoqda. U xohlagan o‘yinchog‘ini barmog‘i bilan ko‘rsatishi mumkin (pointing). Bu aqliy rivojlanishdagi katta sakrashdir! U o‘z e’tiborini siz bilan bo‘lishishni istaydi. U biror narsani ko‘rsatganida, darhol uning nomini ayting: "Ha, bu to‘p! Sen to‘pni xohlaysanmi?". Bu uning miyasida so‘zlar va buyumlar o‘rtasidagi bog‘liqlikni mustahkamlashga yordam beradi.') WHERE id = '425f3229-dceb-43c5-a7c7-021a098be008';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tish chiqishi paytida milklarning qichishishi va og‘rishi chaqaloqning tungi uyqusiga ta’sir qilishi mumkin. Agar chaqalog‘ingiz uyqusida bezovta bo‘lsa, uning milklarini toza, nam va salqin sochiq bilan ohista massaj qiling. Tish chiqishi davrida ishtahaning pasayishi ham tabiiy; uni majburlamang, ko‘proq suyuqlik va ona suti yoki sun’iy ozuqa taklif qiling. Sizning mehringiz uning uchun eng kuchli og‘riq qoldiruvchidir.') WHERE id = 'c0bb1b1a-709a-4043-a236-fe5cfd9ea7eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 260 kun ortda qoldi! Chaqalog‘ingiz endi o‘z ismini doim taniydi va chaqirganingizda darhol siz tomonga o‘giriladi. U oila a’zolarini boshqalardan aniq ajrata oladi va sizga alohida mehr bilan bog‘langanini ko‘rsatadi. Bugun u bilan polda "kitob o‘qish" vaqtini o‘tkazing: u rasmlarni ko‘rsatsin, siz esa ularning nomini ayting. Siz uning eng ishonchli ustozi va qahramonisiz, Onajon!') WHERE id = '122b28c9-a9e8-422e-9381-d9406e97f79b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi 9-oyning so‘nggi o‘n kunligiga kirdik. Chaqalog‘ingiz tik turganida bir qo‘lini divandan uzib, ikkinchi qo‘li bilan o‘yinchoqqa cho‘zila oladi. Bu uning muvozanatni saqlash qobiliyati qanchalik rivojlanganini ko‘rsatadi. Bu davrda uning atrofida ushlanishi mumkin bo‘lgan mustahkam mebellar borligiga ishonch hosil qiling. U endi o‘z kuchini sinab ko‘rmoqda va tez orada ilk mustaqil qadamini tashlash uchun jasorat to‘playdi.') WHERE id = '4ac0d7bc-e3ee-464a-a0d8-d71c88bce550';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning "mayda motorika"sida yangi yutuq: endi u ikkita buyumni bir-biriga urib, tovush chiqarishni juda yaxshi ko‘radi. Bunda ikkala qo‘l ham muvofiqlashgan holda ishlaydi. Unga ikkita yog‘och kubik yoki plastik idish bering va ularni qanday taqillatishini kuzating. Bu oddiy harakat uning eshitish qobiliyatini ham, harakatlarni rejalashtirishini (motor planning) ham rivojlantiradi. Musiqa ritmlari yordamida bu o‘yinni yanada qiziqarli qilishingiz mumkin.') WHERE id = 'fddb995c-a311-44d6-a424-3f063a465828';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanish ratsionini xilma-xil qiling: agar hali sinab ko‘rmagan bo‘lsangiz, ratsionga tvorog yoki qatiq bilan birga mayda, yumshoq meva bo‘laklarini qo‘shishning ayni vaqti. Chaqalog‘ingizning chaynash harakatlari endi ancha tartibli. Unga ovqatni butunlay ezib emas, kichik bo‘laklar shaklida berish milklarining mustahkamlanishiga va kelajakda oila dasturxonidagi taomlarga to‘liq moslashishiga yordam beradi. Mustaqil ovqatlanishiga imkon yarating, bu uning o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = 'b230cf28-523f-407d-9888-06b6c53bb3a6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy muloqotda "taqlid" davri: chaqalog‘ingiz endi yuz ifodalaringizni, chiqarayotgan tovushlaringizni va hatto aksirishingizni ham taqlid qilishi mumkin. U sizni diqqat bilan kuzatib, o‘rganmoqda. Uning oldida turli harakatlarni bajaring (masalan, tilingizni chiqaring yoki ko‘zingizni pirpirating), ko‘ramiz, u sizni takrorlarmikan? Taqlid qilish ko‘nikmasi uning ijtimoiy moslashuvi va o‘rganish qobiliyatini rivojlantiruvchi eng kuchli vositadir.') WHERE id = '671adb79-58b3-4617-94e4-bb4071a9a5ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda xilma-xillik va yangi teksturalar: Endi pyureni butunlay unutishingiz mumkin. Taomlarni shunchaki sanchqi bilan ezib, chaqaloqqa taklif qiling. Uning milklari yumshoq pishirilgan go‘sht bo‘laklari yoki sabzavotlarni ezish uchun yetarlicha kuchli. Chaynash harakati nafaqat hazm qilish, balki nutq mushaklarining rivojlanishi uchun ham zarur. Agar u ayrim bo‘laklarni tuflab tashlasa, xavotir olmang — u yangi sezgilarga ko‘nikmoqda.') WHERE id = '04975f3b-94a9-41da-8a0a-2994a09d6287';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Stakandan suv ichish odatini mustahkamlang. Endi chaqalog‘ingiz stakanni ikki qo‘li bilan ushlashga harakat qilishi mumkin. Unga kichik plastik yoki silikon stakanda suv bering. Dastlab suvning yarmi ustiga to‘kiladi — bu mutlaqo tabiiy. Ochiq stakandan ichish til va jag‘ning to‘g‘ri rivojlanishi uchun so‘rg‘ichli shishadan (butilkadan) ichishga qaraganda foydaliroq. Bu uning mustaqillik sari tashlagan navbatdagi qadamidir.') WHERE id = '2fd76c93-94cc-41aa-af0c-928b17fbd06d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy o‘yinlar: "Ber-ol" o‘yini endi uning eng sevimli mashg‘ulotlaridan biriga aylanmoqda. Siz undan o‘yinchoqni so‘raganingizda, u uni sizga uzatishi mumkin (ba’zan yana o‘ziga tortib olsa ham!). Bu o‘yin navbat kutish va bo‘lishish tushunchalarining poydevorini yaratadi. Unga "Rahmat" deyishni unutmang. U sizning ijobiy munosabatingizni ko‘rsa, bunday ijtimoiy harakatlarni tez-tez takrorlashga intiladi.') WHERE id = '7c3fd582-3962-47a8-9de8-b81ab68183e7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Pinset ushlashi" (pincer grasp) endi ancha mukammallashgan. Chaqalog‘ingiz yerdagi eng kichik chang zarrasini ham ushlay oladi. Bu ko‘nikmani rivojlantirish uchun unga yaxshilab pishirilgan dukkaklilarni (masalan, no‘xat yoki yasmiq) taklif qilishingiz mumkin. Bu uning diqqatini jamlashiga ham yordam beradi. Ammo unutmang: u topgan har qanday mayda narsani og‘ziga soladi, shuning uchun yerda xavfli kichik buyumlar bo‘lmasligini doimo nazorat qiling.') WHERE id = 'fda4720c-d3a0-4bf6-82ad-06eddb719108';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloqning xotirasi endi bir necha kun oldin sodir bo‘lgan voqealarni eslab qoladigan darajada kuchaygan. U sevimli o‘yinchog‘i qayerga yashirilganini eslay olishi mumkin. U bilan murakkabroq "bekinmachoq" o‘yinlarini o‘ynang. Masalan, o‘yinchoqni biror yopqich ostiga yashiring va uni qanday topishini kuzating. Bu uning mantiqiy fikrlashini hamda buyumlar yo‘qolib qolmasligi, shunchaki yashirilishini tushunishini (obyekt doimiyligi) rivojlantiradi.') WHERE id = '2c349583-ad28-47b1-aaec-34168c563082';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tayanchga suyanib yurish (cruising) yanada tezlashmoqda. Chaqalog‘ingiz divan bo‘ylab bir chetidan ikkinchi chetigacha shoshilib yurishi mumkin. Bu bosqichda unga poyabzal kiydirmang. Yalangoyoq yoki sirpanmaydigan paypoqda harakatlanish oyoq kafti va barmoqlarining to‘g‘ri shakllanishi uchun eng maqbuldir. U pol teksturasini his qilgani sari muvozanatini yaxshiroq saqlaydi.') WHERE id = 'e21e8596-3f21-4200-9b5c-b7f1ca90251a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Obyekt doimiyligi" tushunchasi endi to‘liq shakllangan. Chaqalog‘ingiz biladiki, agar siz o‘yinchoqni cho‘ntagingizga yashirsangiz, u yo‘qolib qolmaydi, shunchaki cho‘ntagingizda turadi. U o‘yinchoqni qidiradi va cho‘ntagingizni tortadi. Bu xotira mashqi uning mantiqiy fikrlashini rivojlantiradi. U bilan "bekinmachoq" o‘yinini murakkabroq shakllarda o‘ynang; bu uning ayriliq xavotirini (separation anxiety) kamaytirishga ham yordam beradi.') WHERE id = '6997dc99-18bc-4bdc-bae3-c34fc9c367dc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Stakandan suv ichish odatini mustahkamlang. Chaqalog‘ingiz stakanni ushlab, og‘ziga olib borishga urinayotganda suv miqdorini boshqarishni o‘rganmoqda. Dastlab suvning yarmi kiyimiga to‘kilishi mumkin, xavotir olmang. Ochiq stakandan ichish til va lab mushaklarining to‘g‘ri rivojlanishi uchun juda muhim. Bu ko‘nikma kelajakda uning nutqi yanada ravon va aniq bo‘lishiga zamin yaratadi. Sabrli bo‘ling, bu o‘rganish jarayonidir.') WHERE id = '85d33873-230f-4ec2-aeb2-c03aab1bc8c9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tayanchga suyanib yurish (cruising) endi ancha tezlashdi. Chaqalog‘ingiz divan bo‘ylab xuddi yugurayotgandek harakatlanadi. Bu bosqichda uydagi xavfsizlik choralarini yana bir bor tekshiring. Mebelning o‘tkir burchaklari, osilib turgan dasturxonlar yoki poldagi elektr simlari endi yanada katta xavf tug‘diradi. Chaqaloq hamma narsani tortib, o‘ziga yaqinlashtirishga urinadi. Xavfsiz muhit uning atrofni o‘rganishga bo‘lgan qiziqishini so‘ndirmasdan rivojlanishiga imkon beradi.') WHERE id = '6cb85c30-34e6-4f9c-a6d7-47b0e62b9c27';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutq rivojlanishidagi "Jargon" davri: chaqalog‘ingiz endi o‘z tilida uzoq-uzoq "hikoyalar" aytadi. Uning so‘zlarini tushunmasangiz ham, u kattalarning gapirish ohangini mukammal taqlid qiladi. Uni diqqat bilan tinglang, savollar bering va "Rostdanmi? Keyin nima bo‘ldi?" deb javob qaytaring. Bu "muloqot" uning o‘zini ifodalash istagini kuchaytiradi va miyasidagi lug‘at boyligini oshiradi.') WHERE id = '56798677-523b-4029-94dd-1e80eef243c7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tish chiqishi paytida milklarning qichishishi va og‘rishi chaqaloqning tungi uyqusiga ta’sir qilishi mumkin. Agar chaqalog‘ingiz uyqusida bezovta bo‘lsa, milklarini toza, nam va salqin sochiq bilan ohista massaj qiling. Tish chiqishi davrida ishtahaning pasayishi ham odatiy holat; uni majburlamang, ko‘proq suyuqlik va ona suti/sun’iy ozuqa taklif qiling. Sizning mehringiz uning uchun eng kuchli og‘riq qoldiruvchi vositadir.') WHERE id = '953f792e-f8bd-44cc-a2d0-c3b8471c1a51';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 9 oyni to‘ldirdik! Chaqalog‘ingiz endi o‘z ismini doim taniydi va chaqirganingizda darhol siz tomonga o‘giriladi. U oila a’zolarini boshqalardan aniq ajratadi va sizga alohida mehr bilan bog‘langanini ko‘rsatadi. Bugun u bilan polda "kitob o‘qish" vaqtini o‘tkazing; u rasmlarni ko‘rsatsin, siz esa ularning nomlarini ayting. Siz uning eng ishonchli ustozi va qahramonisiz, Onajon!') WHERE id = 'b5fee624-3a8a-4073-bf22-e9bf23545a25';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '10-oyga xush kelibsiz! Bu oyni chaqaloqning "mustaqillik deklaratsiyasi" oyi deb atash mumkin. U endi buyumlardan ushlab, oyoqda ancha ishonchli turadi va hatto bir necha soniya tayanchsiz qolishga harakat qiladi. Muvozanatni saqlashga qaratilgan bu kichik urinishlar ilk qadamlarning darakchisidir. Uning uchun keng va xavfsiz joy yarating. Unutmang, har bir yiqilish unga yerning tortish kuchini va o‘z tanasini qanday boshqarishni o‘rgatadi. Shunchaki yonida bo‘ling va uni ruhlantiring.') WHERE id = '162ad9af-c711-43da-b203-5c312cf418b0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq nutqidagi "Ma-ma", "Ba-ba" yoki "Ad-da" kabi so‘zlar endi aniq ma’no kasb eta boshlaydi. Agar u bu so‘zlarni aytganda sizga yoki otasiga qarasa, demak, u so‘zni muayyan inson yoki narsa bilan bog‘lay oladi. Siz ham unga javob berayotganda sodda va tushunarli gaplardan foydalaning. Masalan, u "To‘p" desa, "Ha, bu qizil to‘p", deb uning lug‘at boyligini oshiring. Sizning har bir javobingiz uning miyasida yangi til aloqalarini shakllantiradi.') WHERE id = 'be8f3e1a-5335-4ace-960c-562783ff9dcb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda yangi bosqich: bosh va ko‘rsatkich barmoqlar bilan qisib ushlash (pincer grasp) ko‘nikmasi shu qadar rivojlanganki, chaqalog‘ingiz kichkina no‘xat donasi yoki yumshoq pishirilgan sabzi bo‘lagini bemalol ushlab, og‘ziga olib bora oladi. Unga mustaqil ovqatlanish uchun ko‘proq imkoniyat bering. Bu uning harakat ko‘nikmalarini rivojlantiradi va to‘yganini mustaqil his qilish qobiliyatini kuchaytiradi. Atrof iflos bo‘lishidan qo‘rqmang, bu "ijodiy tartibsizlik" uning rivojlanishi uchun muhim.') WHERE id = '58ffad0f-55f8-47af-b047-3975e8528016';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi sizga taqlid qilishni juda yaxshi o‘zlashtirgan. Siz telefonda gaplashganingizda u ham biror narsani olib qulog‘iga tutadi, sochingizni taraganingizda esa u ham shunga o‘xshash harakat qiladi. Bu "funksional taqlid" davridir. Unga xavfsiz ro‘zg‘or buyumlarini (plastik taroq, o‘yinchoq telefon, yog‘och qoshiq) berib, bu ko‘nikmasini qo‘llab-quvvatlang. U dunyoni sizni kuzatish orqali o‘rganadi, shuning uchun harakatlaringiz bilan unga yaxshi o‘rnak bo‘lishga intiling.') WHERE id = 'a6c8ab18-10f6-4956-855e-8fca749308ef';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Obyektning doimiyligi" o‘yini: chaqalog‘ingiz endi o‘yinchoqni idishga solib, ustini yopganingizda u yo‘q bo‘lib qolmasligini biladi. U bilan murakkabroq bekinmachoq o‘yinlarini o‘ynang. Masalan, o‘yinchoqni ikki xil yopqichdan birining tagiga yashiring va uni qanday topishini kuzating. Bu uning xotirasini hamda diqqatini jamlash qobiliyatini rivojlantiradi. U vazifani uddalaganida, uni zavq bilan maqtang.') WHERE id = '535f32b7-37dd-475b-9f52-55c5a1160920';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tayanch bo‘ylab yurish (cruising) endi to‘liq avtomatik ko‘nikmaga aylangan. Chaqalog‘ingiz divandan ushlab, xonaning bir chetidan ikkinchisiga tez yurib borishi mumkin. Bu bosqichda uydagi xavfsizlikni yana bir bor tekshiring: osilib turgan dasturxonlar, poldagi elektr simlari va o‘tkir burchaklar endi yanada katta xavf tug‘diradi. U hamma narsani tortib, o‘ziga yaqinlashtirishni va yuqoriga tirmashishni xohlaydi. Xavfsiz muhit unga atrofni erkin o‘rganish imkonini beradi.') WHERE id = 'd10583a3-e400-4339-b85b-3d395175b72a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy muloqotdagi yangi ishoralar: Chaqalog‘ingiz endi xohlagan narsasini barmog‘i bilan ko‘rsatadi (pointing). Bu bilish qobiliyati rivojlanishidagi katta sakrashdir. U diqqatini siz bilan bo‘lishishni istaydi. U biror narsani ko‘rsatganida, darhol uning nomini ayting: "Ha, bu qush! Qarang, qush uchyapti". Bu uning so‘z boyligini oshiradi va siz bilan bo‘lgan hissiy rishtasini mustahkamlaydi. Uning qiziqishiga befarq bo‘lmasligingiz juda muhim.') WHERE id = '1c394285-7074-4a0d-ac82-eab79473970a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Stakandan suv ichish ko‘nikmasini rivojlantiring. Chaqalog‘ingiz endi stakanni ikki qo‘li bilan ushlab, muvozanatni saqlashga tobora yaqinlashmoqda. Unga kichik plastik yoki silikon stakanda oz miqdorda suv bering. Suvning to‘kilishi o‘rganish jarayonining bir qismidir. Ochiq stakandan ichish til va lab mushaklarining to‘g‘ri rivojlanishi uchun so‘rg‘ichli butilkadan ko‘ra foydaliroq bo‘lib, kelajakda nutqining yanada ravon bo‘lishiga yordam beradi.') WHERE id = '863feabb-ad16-4aad-8a94-087f99977902';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar tish chiqish jarayoni davom etayotgan bo‘lsa, chaqaloqning uyqusi va ishtahasi yana buzilishi mumkin. 10-oyda odatda yuqori yoki pastki yon kurak tishlar chiqadi. Agar milklarida kuchli qichishish bo‘lsa, unga sovitilgan (ammo muzlatilmagan) tish qashlagich yoki salqin sabzavot bo‘laklarini (nazorat ostida) bering. Bu davrda ko‘proq suyuqlik va ona sutini taklif qilish uning organizmini suyuqlik bilan ta’minlaydi hamda uni tinchlantiradi. Sizning mehringiz eng yaxshi og‘riq qoldiruvchidir.') WHERE id = '22dd56cb-e699-4f81-b502-66f9d54e2b23';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 280 kunni yakunladik! Chaqalog‘ingiz endi ismi har safar aytilganida uni taniydi va aniq munosabat bildiradi. U sevimli o‘yinchog‘i yoki odamini tanlay oladi va o‘z "xarakterini" namoyon eta boshlaydi. Bugun u bilan yerga yotib, shunchaki "taqlid" o‘yinini o‘ynang: u ovoz chiqarsin, siz takrorlang, siz chapak chaling, u takrorlasin. Siz u dunyoni kashf etayotgan paytdagi eng ishonchli panohsiz, Ona!') WHERE id = '71654afe-3791-4e59-a41c-7da09d0ef29c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Siz allaqachon 10-oyning qoq o‘rtasidasiz! Chaqalog‘ingiz endi buyumlarga suyanib o‘rnidan turishni puxta o‘zlashtirdi va hatto bir necha soniyaga qo‘llarini qo‘yib yuborib, mustaqil turishga urinmoqda. Bu uning muvozanat markazi va oyoq mushaklari qanchalik mustahkamlanganini ko‘rsatadi. Uni mustaqil turishga majburlamang, o‘zini tayyor his qilganida bu qadamni tashlashiga imkon bering. Yiqilishdan qo‘rqmasligi uchun atrofi yumshoq yostiqlar bilan o‘ralgan xavfsiz "maydoncha" yarating.') WHERE id = '03d76f01-bcab-4644-9f10-2526c187201c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqaloq nutqidagi yangi bosqich: "Jargon" gaplar! U xuddi sizga nimanidir tushuntirayotgandek, ohangdor va hissiyotga boy uzun "jumlalar" tuzadi. Hali birorta so‘zini tushunmasangiz ham, bu uning kelajakdagi nutqiga poydevor bo‘ladi. Uni diqqat bilan tinglang va "Rostdanmi? Juda qiziq, keyin nima bo‘ldi?" deb javob bering. Bunday suhbatlar uning o‘zini ifoda etish istagini kuchaytiradi va miyasidagi so‘z boyligini tez sur’atda oshiradi.') WHERE id = 'e6d2e0ec-fef4-4fdf-bd36-60be17d3ab5e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda teksturalarga o‘tish jarayonini yakunlang. Endi pyure davri butunlay ortda qolishi kerak. Ovqatlarni shunchaki sanchqi bilan ezib yoki kichik, yumshoq bo‘laklar (finger foods) shaklida taklif qiling. Chaqalog‘ingizning milklarida yumshoq pishirilgan go‘sht yoki sabzavotlarni ezish uchun yetarlicha kuch bor. Bu chaynash ko‘nikmasini mustahkamlaydi va kelajakda ovqat tanlash bilan bog‘liq muammolarning oldini oladi. Sabrli bo‘ling, har bir yangi tekstura — yangi o‘rganish tajribasidir.') WHERE id = '25d3da74-5500-488e-93bc-4e022b9fdf57';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy o‘yinlarda navbat bilan harakat qilish ko‘nikmasi: Chaqalog‘ingiz endi "menga ber", "sizga beraman" o‘yinini yaxshiroq tushunadi. Unga o‘yinchoq uzating, keyin esa "endi koptokni menga ber" deb qaytarib so‘rang. Agar bersa, uni zavq bilan maqtang. Bu o‘yin unda bo‘lishish tushunchasi va o‘zaro muloqot qoidalarining poydevorini yaratadi. Shuningdek, bu uning qo‘l-ko‘z muvofiqligi va buyumni qo‘yib yuborish (release) ko‘nikmasini takomillashtiradi.') WHERE id = '639df12e-60c1-4322-9712-2375f1060042';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Toifalar": Chaqalog‘ingiz endi o‘xshash buyumlarni farqlay boshlaydi. Masalan, turli shakldagi koptoklarning barchasi "koptok" ekanini tushunishga yaqin. Unga turli rang va o‘lchamdagi koptoklar yoki kubiklarni ko‘rsating. Bular uning mavhum tafakkuridagi ilk qadamlardir. U bilan o‘ynayotganda buyumlarning rangi va shaklini ayting: "Bu katta mashina, bu esa kichik mashina".') WHERE id = '4207275f-8c9b-455a-be42-c07fcdc66c91';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Pinset ushlashi" (pincer grasp) ko‘nikmasi endi to‘liq o‘zlashtirilgan. Chaqalog‘ingiz polda ko‘rgan eng kichik ushoqni ham bosh va ko‘rsatkich barmog‘i bilan ushlaydi. Bu ko‘nikmani yanada rivojlantirish uchun unga yaxshilab pishirilgan yasmiq donalari yoki kichik, yumshoq tvorog bo‘laklarini bering. Ehtiyot bo‘ling: bu ko‘nikma u topgan har qanday xavfli mayda buyumni (tugma, munchoq) ham xuddi shunday chaqqonlik bilan og‘ziga solishi mumkinligini anglatadi. Hozir uyni toza saqlash har qachongidan ham muhim.') WHERE id = 'd9053aab-2643-4a33-bd40-377294e7163f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tayanchga suyanib yurish (cruising) shu qadar tezlashdiki, chaqalog‘ingiz divan cheti bo‘ylab deyarli yuguradi. Bu bosqichda uydagi mebellarning mustahkam va barqaror ekaniga yana bir bor e’tibor bering. U tortilib, hamma narsaga chiqishga urinadi. Osilib turgan dasturxonlarni olib qo‘ying, chunki ulardan ushlab turishga urinsa, ustidagi barcha narsalarni o‘zining ustiga ag‘darib yuborishi mumkin. Xavfsiz muhit uning o‘ziga bo‘lgan ishonchini oshiradi va qo‘rqmasdan atrofni o‘rganishiga imkon beradi.') WHERE id = '22ae7b1e-0f5e-4f2c-a0b9-f363eec03221';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'O‘zini anglash: Chaqalog‘ingiz endi ko‘zgudagi aks o‘zi ekanini tushuna boshlaydi. Uning burniga kichik rangli dog‘ qo‘yib, ko‘zguga qaratsangiz, u o‘z yuzidagi dog‘ni artishga harakat qiladi (bu "lab bo‘yog‘i testi" deb ataladi). Bu uning o‘zlikni anglash (self-awareness) qobiliyati rivojlanayotganini ko‘rsatadi. U bilan ko‘zgu qarshisida turib, "bu sening burning, bu esa onangning burni" deb farqlarni ko‘rsating. Bu, shuningdek, tana tuzilishi haqidagi tasavvurni shakllantirish uchun ajoyib mashqdir.') WHERE id = 'aee72c71-4ab2-40ae-a72a-f441c99bcf9d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqu paytida "ajralish xavotiri" yana namoyon bo‘lishi mumkin. Chaqalog‘ingiz uyg‘onib, sizni ko‘rmasa, darhol yig‘lab yuborishi mumkin. Unga xotirjamlik berish uchun yoniga boring, chiroqni yoqmasdan sekin silang va "onang shu yerda, uxlayver" deb pichirlang. Uni darhol bag‘ringizga olib, xonadan olib chiqishga shoshilmang; sizning yonida ekaningizni his qilib, o‘zi yana uxlashga harakat qilsin. Sabr-toqatingiz bu davrni yengilroq o‘tkazishga yordam beradi.') WHERE id = '807f6974-949a-4673-9e12-ca050a097e4d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 290 kunni ortda qoldirdik! Chaqalog‘ingiz endi o‘ziga xos xarakterini namoyon qilmoqda: unga nima yoqadi, nimadan qo‘rqadi, qaysi taomni yaxshi ko‘radi... Bugun u bilan yerga yotib, shunchaki u boshqaradigan o‘yinni o‘ynang. U sizni "yo‘naltirsin", o‘yinchoqni sizga bersin yoki sizga taqlid qilsin. U bilan o‘tkazgan har bir daqiqangiz uning kelajakdagi baxtiga qo‘yilgan poydevordir. Siz ajoyib yo‘lni bosib o‘tdingiz, Ona!') WHERE id = '2489cf6a-6c9a-4826-ac80-afae063dcb86';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '10-oyning so‘nggi o‘n kunligiga xush kelibsiz! Chaqalog‘ingiz bir qo‘lidan ushlaganingizda ishonch bilan qadam tashlayaptimi yoki hali ham tayanchsiz turishga jur’at etmayaptimi? Har ikkala holat ham me’yoriy. Ayrim chaqaloqlar 10-oyda yura boshlaydi, boshqalari esa 15-16 oygacha kutadi. Oyoq mushaklarini mustahkamlash uchun unga polda ko‘proq vaqt o‘tkazish imkonini bering. U o‘z kuchiga ishongan paytda sizni ilk mustaqil qadami bilan hayratda qoldiradi!') WHERE id = '96dedeae-65fd-4082-8b02-077d47cad21d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingizda "obyekt doimiyligi" tushunchasi shu darajada rivojlanganki, u biror buyumni qutiga solib, keyin uni qayta olishdan charchamaydi. Bu "solish va chiqarish" o‘yini uning ham fazoviy idrokini, ham mayda motorikasini rivojlantiradi. Unga turli o‘lchamdagi idishlar va ularning ichiga solishi mumkin bo‘lgan xavfsiz buyumlarni bering. Bu oddiy mashq kelajakda murakkab vazifalarni hal qilish ko‘nikmasining poydevoridir.') WHERE id = 'a8043f3c-dcb0-41ac-858a-58401aab3cc0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutq rivojida yangi sakrash: Chaqalog‘ingiz endi ayrim so‘z yoki tovushlarni muayyan hodisalar bilan bog‘laydi. Masalan, eshik qo‘ng‘irog‘i chalinganda "dada" deyishi yoki och qolganida o‘ziga xos tovush chiqarishi mumkin. Bu ongli nutqning boshlanishidir. Uning har bir ovozli murojaatiga diqqat bilan javob bering: "Ha, eshik taqilladi, kelgan dada ekan!". Sizning bunday "tarjimalaringiz" uning miyasida so‘zlarning ma’nosini yanada mustahkamlaydi.') WHERE id = '7f7f52b6-f75a-4125-9bb5-a72c5365ce29';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda xilma-xillik: Endi chaqalog‘ingiz ratsioniga juda oz miqdorda, yaxshilab pishirilgan butun donli mahsulotlar, yumshoq makaron yoki non mag‘zini qo‘shishingiz mumkin. Bu unga turli tuzilishdagi taomlarni his qilish va chaynash ko‘nikmasini takomillashtirishga yordam beradi. Unutmang, taomlarga hali ham tuz va shakar qo‘shmaymiz. Tabiiy ta’mlar uning ta’m retseptorlari to‘g‘ri shakllanishi uchun eng maqbulidir.') WHERE id = 'b9f43156-8bbe-4d46-a470-47337a11cf3a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zim qilaman!" davri boshlanmoqda. Ovqatlanish paytida chaqalog‘ingiz qoshiqni qo‘lingizdan olishga yoki ovqatni bevosita qo‘llari bilan yeyishga tobora ko‘proq intiladi. Uning mustaqil bo‘lish istagini so‘ndirmang. Qo‘llari iflos, yuz-ko‘zi pyure bo‘lishiga ruxsat bering. Bu jarayon uning o‘ziga bo‘lgan ishonchini oshiradi va ovqat bilan ijobiy munosabat o‘rnatishiga yordam beradi. Sizning sabringiz kelajakda uning ishtahasi yaxshi va mustaqil bola bo‘lishiga zamin yaratadi.') WHERE id = 'b31abab7-200d-4d55-b197-62b606e68100';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy ko‘nikmalar: Chaqalog‘ingiz endi "xayr" (qo‘l silkitish) yoki "bo‘sa yuborish" (havodan o‘pich yuborish) kabi imo-ishoralarni takrorlay oladi. Bu imo-ishoralar uning nutq paydo bo‘lishidan oldingi muloqot shakllaridir. Siz qo‘l silkitganingizda u ham ortingizdan takrorlasa, bu uning sizga bog‘langanini va e’tiborini ko‘rsatadi. Bu harakatlarni qo‘shiqlar bilan uyg‘unlashtirib, yanada qiziqarli qiling. Muloqot qilishga bo‘lgan ishtiyoqi oshishi uchun uning har bir imo-ishorasiga quvonch bilan javob qaytaring.') WHERE id = 'db90e8f1-9d73-4d53-8169-2122571f4a13';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xavfsizlikning yangi bosqichi: Chaqaloq endi baland joylarga tirmashishga moyil. Pastak stollar va divan chetlari uning uchun "cho‘qqi"dir. Uydagi barcha og‘ir buyumlar va mebellarning mustahkam o‘rnatilganini tekshiring. Ayniqsa, elektr simlarini (kabellarni) yashiring, chunki ularni tortish chaqalog‘ingiz uchun eng qiziqarli mashg‘ulotga aylanishi mumkin. Uyning xavfsizligi sizga xotirjamlik, unga esa bemalol o‘rganish uchun keng imkoniyat beradi.') WHERE id = 'cd4b7de4-c97d-44b4-ae4b-d87984914859';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqu va aqliy rivojlanish: Chaqalog‘ingiz tunda uyg‘onib, sizni ko‘rmasa, qattiq yig‘lashi mumkin. Bu davrda unga o‘zini xavfsiz his qilishiga yordam berish muhim. Yoniga borganingizda chiroqni yoqmasdan, sokin ovozda "onang shu yerda, uxlayver" deb, uni silab qo‘ying. Uni darhol bag‘ringizga olib, xonadan olib chiqishga shoshilmang. Shunchaki yonida ekaningiz va ovozingiz unga yana uyquga ketishi uchun yetarli ishonch beradi. Bu "ajralish xavotiri"ning vaqtinchalik bosqichidir.') WHERE id = 'd5f8c50f-64e6-4aba-ad9f-5604b24fb65b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ertaga chaqalog‘ingiz roppa-rosa 300 kunlik bo‘ladi! Shu 10 oy davomida u aql bovar qilmas yo‘lni bosib o‘tdi: yordamsiz chaqaloqdan o‘z fe’l-atvori, istaklari va qobiliyatlariga ega kichik insonga aylandi. Siz ham bu vaqt ichida katta tajriba orttirdingiz. Bugun uning yonida yerga yotib, shunchaki kulishini tomosha qiling. Sizning mehringiz uning rivojlanishidagi eng katta harakatlantiruvchi kuchdir.') WHERE id = '2638511c-740a-477b-ab58-1fbe5fd5c94a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Chaqalog‘ingiz 300 kunlik bo‘ldi! Bu bir yoshga to‘lish sari qolgan so‘nggi katta bosqichdir. Chaqalog‘ingiz endi ismini har gal aytganingizda taniydi, his-tuyg‘ularini aniq namoyon etadi va balki ilk qadamlarini tashlashga tayyorlanayotgandir. Bu kunni u bilan birga o‘ziga xos o‘yin o‘ynab yoki sevimli mevasini berib nishonlang. Siz ajoyib ishni uddaladingiz, Ona! 300 kunlik mehnatingizning samarasi har kuni sizga boqib turgan o‘sha baxtiyor ko‘zlarda aks etadi.') WHERE id = '4dbc6d6a-ae47-4867-ba96-b66058f91a2f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '11-oyga xush kelibsiz! Birinchi tug‘ilgan kuniga atigi ikki oy qoldi. Bu davrda chaqalog‘ingiz "men" va "siz" o‘rtasidagi farqni yaxshiroq anglay boshlaydi. U yuz ifodalaringizga taqlid qilib, hissiy intellektini rivojlantiradi. Siz xafa bo‘lsangiz, u ham jiddiy ko‘rinishi, siz kulsangiz esa qahqaha otishi mumkin. U bilan his-tuyg‘ular haqida gaplashing — bu kelajakda o‘z tuyg‘ularini boshqarishi uchun mustahkam poydevor bo‘ladi.') WHERE id = '9a834d06-30b3-4c6c-92b2-859a3c7000f4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz bir qo‘lidan ushlaganingizda ancha ishonch bilan yuradimi yoki hali ham faqat divan chetidan ushlab yuribdimi? Shu kunlarda u muvozanatni saqlash uchun qo‘llarini ikki tomonga yoyib, mustaqil ravishda bir-ikki qadam tashlashi mumkin. Bunday "muvozanat" harakatlari uning miyasidagi muvozanat markazini (vestibulyar apparatni) mashq qildiradi. Uni shoshiltirmang, o‘ziga to‘liq ishonch hosil qilishiga imkon bering.') WHERE id = 'a31576c9-38ba-4027-9aca-cbc63e6f334a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "istaklarni ifodalash": Chaqalog‘ingiz endi nimani xohlayotganini faqat yig‘lash bilan emas, balki barmog‘i bilan ko‘rsatish va o‘ziga xos tovushlar chiqarish orqali ham sizga tushuntira oladi. U o‘yinchog‘ini ko‘rsatganida: "Ha, siz shu ayiqchani xohlaysizmi?" deb, istagini so‘z bilan tasdiqlang. Bu unda "meni tushunishadi" degan tuyg‘uni shakllantiradi va kelajakda tajovuzkor xatti-harakatlarning (tushunilmaslikdan kelib chiqadigan yig‘ining) oldini olishga yordam beradi.') WHERE id = 'aa86788c-ff14-4450-8f10-2208ffcc316b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda mustaqillik: Endi chaqalog‘ingiz qoshiqni o‘zi ushlab, og‘ziga olib borishni xohlaydi. Ha, ovqatning ko‘p qismi yerga va oldiga tushadi, ammo bu mayda motorika hamda qo‘l-ko‘z muvofiqligi uchun eng muhim mashqlardan biridir. Unga qulay silikon yoki dastasi yo‘g‘on qoshiq bering. Siz ham ayni paytda boshqa qoshiq bilan unga yordam berishingiz mumkin. Bu xuddi "jamoaviy ish"ga o‘xshaydi!') WHERE id = '3159f58c-c8a2-418a-a8bd-3b961ca0266e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hayvonlar tovushlari" davri! Chaqalog‘ingiz endi "it qanday huradi?", "mushuk qanday ovoz chiqaradi?" kabi savollarga o‘z tilida javob bera boshlashi mumkin. Bu uning tovushlarga taqlid qilish qobiliyati eng rivojlangan davrdir. Hayvonlar tasvirlangan kitoblarni tomosha qilib, bu o‘yinlarni davom ettiring. Tovushlarga taqlid qilish nutq apparatini (til va lab mushaklarini) kelajakda murakkab so‘zlarni aytishga tayyorlaydi.') WHERE id = '43246706-501b-4546-a51a-8e59351b53c5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Pinset ushlashi" (pincer grasp) shu qadar takomillashganki, u yerdagi eng ingichka ipni yoki kichkina ushoqni ham osonlik bilan ushlay oladi. Bu ko‘nikmani sinab ko‘rish uchun unga yaxshilab pishirilgan dukkaklilarni (no‘xat, yasmiq) taklif qilishingiz mumkin. Ammo unutmang: topgan har qanday kichik narsani og‘ziga solish odati ham ayni avjida. Uy polining tozaligi va atrofda mayda buyumlar bo‘lmasligi eng muhim xavfsizlik qoidangiz bo‘lib qoladi.') WHERE id = '1053192f-a2a7-43d0-8335-34db00482590';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "jargon" (o‘z tilida gapirish) endi yanada murakkablashadi. U xuddi savol berayotgandek ovozini ko‘taradi yoki nimanidir tushuntirayotgandek qo‘l harakatlarini qiladi. Bu uning nutq ohangini (prosodiyani) o‘rganayotganini ko‘rsatadi. Uni diqqat bilan tinglang va "Ha, shundaymi? Juda qiziq!" deb suhbatni davom ettiring. Sizning bunday qiziqishingiz uning muloqot qilish istagini nihoyatda oshiradi.') WHERE id = '79994c5e-b38e-4456-bddc-86c51746ecdb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Oila dasturxoniga moslashish: Endi chaqalog‘ingiz deyarli barcha taomlarni (tuzsiz va ziravorlarsiz bo‘lishi sharti bilan) siz bilan birga yeyishi mumkin. Unga o‘z qoshig‘i va mustaqil ichishi mumkin bo‘lgan stakanini bering. Mustaqil ovqatlanishiga imkon berish nafaqat motorikasini rivojlantiradi, balki ovqatlanishni ijobiy ijtimoiy faoliyatga ham aylantiradi. Dasturxon atrofida birga o‘tirish uning kelajakdagi ovqatlanish odatlari uchun eng yaxshi namunadir.') WHERE id = '4a48790e-7f13-40fe-9b6e-dd306e1f2a08';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy xotira" va qidirish: Chaqalog‘ingiz endi sevimli o‘yinchog‘i qayerga yashirilganini bir necha daqiqadan keyin ham eslay oladi. U bilan murakkabroq "bekinmachoq" o‘yinlarini o‘ynang. Masalan, o‘yinchoqni biror mato ostiga yashiring va uni qanday topishini kuzating. Bu uning xotirasi va diqqatini jamlash qobiliyatini rivojlantiradi. Muammoni hal qilganida uni zavq bilan maqtang.') WHERE id = 'f29f91f0-dc1e-44f0-842d-ac8ae1283e19';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy ko‘nikmalarda "bo‘lishish" urinishlari: Chaqalog‘ingiz qo‘lidagi o‘yinchoqni sizga "berayotgandek" uzatib, keyin yana tortib olishi mumkin. Bular uning ilk hazillari va ijtimoiy ta’sir o‘tkazishga urinishlaridir! Uning bu "o‘yini"ga kulib va quvonch bilan javob bering. Birga kulish va zavqlanish orangizdagi hissiy rishtani nihoyatda mustahkamlaydi hamda unda hazil tuyg‘usining poydevorini yaratadi.') WHERE id = 'ffe2c8a7-1840-4df7-a9fa-47dc0268105b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Pinset ushlashi" (pincer grasp) endi to‘liq shakllangan. U yerdagi eng ingichka ipni yoki hatto mayda ushoqni ham osonlik bilan ushlay oladi. Bu ko‘nikmani rivojlantirish uchun unga yaxshi pishirilgan dukkaklilar yoki tvorogning mayda bo‘laklarini taklif qiling. Ammo ehtiyot bo‘ling: bunday chaqqonlik uning har qanday xavfli mayda buyumni ham xuddi shu tezlikda og‘ziga solishi mumkinligini anglatadi. Xavfsizlik doimo nazorat ostida bo‘lishi kerak!') WHERE id = 'c1101eea-3caa-455b-a661-c216864cdeb4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Musiqa va ritm: Chaqalog‘ingiz musiqa sadolarini eshitganda tanasini tebratadimi yoki chapak chaladimi? Musiqa ritmini his qilish uning eshitish qobiliyati va tana muvofiqlashuvi rivojlanayotganidan dalolat beradi. U bilan birga raqsga tushing, chapak chaling. Bu nafaqat uning jismoniy faolligini oshiradi, balki estetik didi va ritm tuyg‘usi shakllanishiga ham yordam beradi. Qo‘shiqlar so‘zlarini birga takrorlashga harakat qiling.') WHERE id = '3a1cdf9f-7bc8-427f-b1e3-a23a8f78241b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy o‘yinlarning murakkablashuvi: Chaqalog‘ingiz endi "ber-ol" o‘yinini yangi bosqichga olib chiqmoqda. U o‘yinchoqni sizga berib, darhol qaytarib so‘rashi yoki siz "ber" deganingizda uni ataylab yashirishi mumkin. Bular uning ilk "hazillari"dir. Uning bu hazil tuyg‘usiga kulgi bilan javob bering. Birga kulish va zavqlanish orangizdagi hissiy rishtani nihoyatda mustahkamlaydi.') WHERE id = '3451f734-1652-4c0f-97a4-7d508b0bb860';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uyqu tartibi va uyg‘oq qolish muddati: 11-oyda chaqaloqlarda kunduzgi 2 mahal uyqudan 1 mahal uyquga o‘tish (uyquga o‘tish davri) belgilari kuzatilishi mumkin, ammo hozircha shoshilmang. Aksariyat chaqaloqlar 14-15 oylikkacha kunduzgi 2 mahal uyquga muhtoj bo‘ladi. Agar ertalab uxlashi qiyin bo‘lsa, uyg‘oq qolish muddatini biroz uzaytirib ko‘ring (taxminan 3 - 3.5 soat). Yaxshi dam olgan chaqaloq yangi ko‘nikmalarni ishtiyoq bilan o‘rganadi.') WHERE id = '852db72f-d9a2-475c-b994-d1ab8a6b4f97';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy idrok": Chaqalog‘ingiz endi qutilarning ichiga qarashni, qopqoqlarni ochib-yopishni va buyumlarni bir-birining ichiga joylashni yaxshi ko‘radi. Unga turli o‘lchamdagi plastik idishlar bering. U kichik idish katta idishning ichiga sig‘ishini kashf etganida, miyasida murakkab matematik va mantiqiy bog‘lanishlar shakllanadi. Bu oddiydek ko‘rinsa-da, aslida katta kashfiyotdir.') WHERE id = '114fd473-c44c-4c3b-b5d0-19ac5cbf17e6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 310 kunni yakunladik! Chaqalog‘ingiz endi o‘z xohish-irodasini namoyon qilmoqda: kiyinishni istamasa, oyoqlarini tirab oladi, sevimli taomini ko‘rsa, qarsak chaladi. Bu "shaxsiyat" belgilari ba’zan sizni charchatsa-da, aslida uning sog‘lom ruhiy rivojlanayotganidan dalolat beradi. Bugun u bilan polda o‘tirib, shunchaki uning o‘zi xohlagan o‘yinni o‘ynang. Sizning e’tiboringiz uning uchun dunyodagi eng katta mukofotdir.') WHERE id = '2a98f756-8ee8-4fcc-b117-1adb344f61bd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi qo‘llarini tayanchdan qo‘yib yuborib, bir necha soniya mustaqil tura olyaptimi? Bu uning o‘ziga bo‘lgan ishonchi eng yuqori nuqtaga yetganidan dalolat beradi. U hali yurmasa-da, ana shu muvozanat saqlash lahzalari uning miyasidagi muvozanat markazini (vestibulyar apparatni) takomillashtiradi. Uni maqtang va quchog‘ingizni ochib, siz tomon bir qadam tashlashga undang. Har bir kichik urinish katta qadamning darakchisidir!') WHERE id = '94901ac5-33b9-4db0-bb43-734602fe969c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Yo‘q" so‘zini tushunish va sinab ko‘rish! Chaqalog‘ingiz endi "yo‘q" deganingizda to‘xtab, sizga qaraydi, ammo ba’zan ataylab o‘sha harakatni takrorlaydi. Shu tariqa u chegaralarni va sizning munosabatingizni sinab ko‘radi. Sabrli bo‘ling va qat’iyligingizni saqlang. Xavfli vaziyatlarda sababini jiddiy, ammo xotirjam ohangda tushuntiring. U yuz ifodangiz va ovoz ohangingiz orqali ijtimoiy qoidalarni o‘rganishda davom etadi.') WHERE id = '996a8930-2fe4-4558-a5f9-55c594d11cb6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqudagi "harakatli uyg‘onishlar": Chaqalog‘ingiz uyqusida to‘satdan o‘rnidan turishi yoki uyqusiragan holda emaklashga urinishi mumkin. Uning miyasi kunduzi o‘rgangan harakatlarini tunda takrorlaydi. Agar yig‘lamasa, unga tegmang, o‘zi qulay holatni topib, yana uxlab qolsin. Agar yig‘lasa, sekin yoniga boring, chiroqni yoqmasdan uni joyiga yotqizing va tinchlantiruvchi so‘zlar ayting. Qayta uxlab qolishi uchun yonida ekaningizning o‘zi kifoya.') WHERE id = '8706f5e6-ca0d-4a1d-8941-e5de02cc1dad';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 320 kunni ortda qoldirdik! Birinchi tug‘ilgan kunigacha atigi 45 kun qoldi. Chaqalog‘ingiz endi o‘z fe’l-atvori, tanlovi va istaklarini qat’iy namoyon etmoqda. Bugun u bilan yerga yotib, shunchaki "taqlid" o‘yinini o‘ynang: u tovush chiqarsin, siz takrorlang; siz chapak chaling, u takrorlasin. Siz — u dunyoni kashf etish uchun yo‘lga chiqadigan eng ishonchli qo‘rg‘oni va eng yaqin do‘stisiz, Onajon!') WHERE id = '6671dafc-f72e-46f2-8504-39bf2769162e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Endi 11-oyning so‘nggi o‘n kunligiga kirib boryapmiz. Chaqalog‘ingiz bir qo‘lidan ushlaganingizda ancha ishonch bilan yuradimi yoki hali ham faqat divan chetidan tutib yuribdimi? Shu kunlarda u muvozanatini saqlash uchun qo‘llarini ikki tomonga yoyib, mustaqil ravishda bir-ikki qadam tashlashi mumkin. Bu "muvozanat" harakatlari uning miyasidagi muvozanat markazini (vestibulyar apparatni) mashq qildiradi. Uni shoshiltirmang, o‘ziga bo‘lgan ishonchi to‘liq shakllanishiga imkon bering.') WHERE id = '223de2de-87c5-4289-96a9-08ae91456aa1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz endi buyumlar nima uchun ishlatilishini tushuna boshlaydi (funksional o‘yin). Masalan, taroqni boshiga olib boradi, telefonni qulog‘iga tutadi yoki piyolani og‘ziga olib borib, o‘zini "ichayotgandek" tutadi. Bu aqliy rivojlanishdagi katta sakrashdir! Unga xavfsiz ro‘zg‘or buyumlarini berib, bu taqlid qilish ko‘nikmasini qo‘llab-quvvatlang. U dunyoni sizni kuzatish orqali o‘rganadi, shuning uchun xatti-harakatlaringiz bilan unga yaxshi namuna bo‘lishga harakat qiling.') WHERE id = '1023ea09-5e35-4d01-b1e5-ee2d0049110b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Obyektning doimiyligi" o‘yini: Chaqalog‘ingiz endi o‘yinchoqni biror idishga solib, ustini yopsangiz ham u yo‘qolib qolmasligini biladi. U bilan murakkabroq bekinmachoq o‘yinlarini o‘ynang. Masalan, o‘yinchoqni ikki xil yopqichdan birining ostiga yashiring va uni qanday topishini kuzating. Bu uning ham xotirasini, ham diqqatini jamlash qobiliyatini rivojlantiradi. Vazifani uddalaganida uni jo‘shqinlik bilan maqtang.') WHERE id = '8ef86f1c-b50a-4f76-b6a2-1deccffcaf49';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda mustaqillik: Endi chaqalog‘ingiz qoshiqni butunlay o‘zi ushlab, og‘ziga olib borishni xohlaydi. Ha, ovqatning ko‘p qismi polga va ko‘krakpechga to‘kiladi, ammo bu mayda motorika hamda qo‘l-ko‘z muvofiqligi uchun eng muhim mashqdir. Unga o‘zi uchun qulay bo‘lgan silikon yoki dastasi yo‘g‘on qoshiq bering. Siz ham ayni paytda boshqa qoshiq bilan unga yordam berishingiz mumkin. Bu xuddi "jamoaviy ish"ga o‘xshaydi!') WHERE id = '7871caf2-41cf-4c3f-b2a8-4d60c9c5acd7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '12-oyga xush kelibsiz! Birinchi tug‘ilgan kunigacha atigi 30 kun qoldi. Chaqalog‘ingiz endi butunlay o‘ziga xos bir shaxs. U endi harakatlaringizga shunchaki taqlid qilibgina qolmay, ularning ma’nosini ham tushunadi. Bu oy uning o‘ziga bo‘lgan ishonchini oshirish uchun unga oddiy tanlovlar taklif qiling. Masalan, "bu ko‘ylakni kiyishni xohlaysanmi yoki bunisini?". Bu uning qaror qabul qilish ko‘nikmasiga ilk poydevorni qo‘yadi.') WHERE id = 'fd9ad5fc-02c4-489e-8c2f-e2ab1ee56a7e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Agar chaqalog‘ingiz tayanchsiz yura boshlagan bo‘lsa, uydagi xavfsizlik choralarini "ekstremal" darajaga oshiring. Agar u hali yurmayotgan bo‘lsa, xavotir olmang; ko‘plab sog‘lom chaqaloqlar 15 oygacha yurmasligi mumkin. Yurishni qanchalik erta boshlashi aql-zakovat ko‘rsatkichi emas. Eng muhimi, u oyoqda tura olishi va atrofni o‘rganishga ishtiyoqi bo‘lishidir.') WHERE id = 'e0fb9df8-7033-4ff7-a1b1-5c3d3e6afa83';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "ongli so‘zlar": Chaqalog‘ingiz endi "suv", "ber", "kel" kabi oddiy so‘zlarni o‘rnida ishlatyaptimi? U istagini sizga atigi bitta so‘z yoki ishora bilan tushuntira oladi. Siz uning bu urinishlarini kengaytiring: "Ha, suv ichishni xohlaysanmi? Mana, bu sening ko‘k stakaning". Bu uning miyasida so‘zlar o‘rtasidagi grammatik bog‘lanishlarni shakllantirishga yordam beradi.') WHERE id = 'c5cc511f-2fea-4b22-b8e8-1b77f482261c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda oila dasturxoniga to‘liq qo‘shilish. Chaqalog‘ingiz endi siz bilan bir vaqtda dasturxonga o‘tirib, deyarli bir xil taomlarni yeyishi mumkin. Bu uning ijtimoiylashuvi uchun juda muhim. Unga alohida idish-tovoq bering va mustaqil ovqatlanishi uchun sharoit yarating. Ovqatlanish uning uchun majburiyat emas, balki qiziqarli va mazali mashg‘ulot bo‘lishi kerak.') WHERE id = '8b39909f-51d2-4504-9985-513b605dc042';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Pincet usulida ushlash" (pincer grasp) endi mukammallashgan va mayda motorika murakkabroq o‘yinlarni o‘ynash imkonini beradi. Unga kublarni ustma-ust taxlashni, katta munchoqlarni ipga tizishni (nazorat ostida!) yoki oddiy boshqotirmalarni (puzzle) yig‘ishni ko‘rsating. Bu o‘yinlar diqqatni jamlashni ham, qo‘l-ko‘z muvofiqligini ham nihoyatda yaxshi rivojlantiradi.') WHERE id = 'e3225412-1384-48a0-aa55-7ca8a5ef8659';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy muloqotda "empatiya"ning ilk belgilari. Chaqalog‘ingiz siz xafa bo‘lganingizda yoki yig‘laganingizda yoningizga kelib, sizga tegishi yoki o‘yinchog‘ini berishi mumkin. Bu uning boshqalarning his-tuyg‘ularini tushuna boshlaganini ko‘rsatadi. Uning bu mehribon harakatlariga muhabbat bilan javob bering. Bu kelajakda uning hissiy jihatdan sog‘lom shaxs bo‘lib ulg‘ayishiga yordam beradi.') WHERE id = '31745949-5ef4-444a-8a69-ec5929c0332b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hayvonlar ovozi" davri! Chaqalog‘ingiz endi "it qanday huradi?", "mushuk qanday ovoz chiqaradi?" kabi savollarga o‘z tilida javob bera boshlashi mumkin. Bu uning tovushlarga taqlid qilish qobiliyati eng yuqori darajaga yetganini ko‘rsatadi. Hayvonlar tasvirlangan kitoblarni tomosha qilib, bu o‘yinlarni davom ettiring. Tovushlarga taqlid qilish nutq apparatini (til va lab mushaklarini) kelajakdagi murakkab so‘zlarni aytishga tayyorlaydi.') WHERE id = 'cdc84d0d-886f-4a27-bf41-fd9c5be5503c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Qisqichsimon ushlash" (pincer grasp) shu qadar takomillashganki, u yerdagi eng ingichka ipni yoki hatto mayda ushog‘ni ham osonlik bilan ushlay oladi. Bu ko‘nikmani sinab ko‘rish uchun unga yaxshi pishirilgan dukkaklilarni (no‘xat, yasmiq) taklif qilishingiz mumkin. Ammo unutmang: topgan har qanday mayda narsani og‘ziga solish odati ham ayni avjida. Uy polining tozaligi va atrofda mayda buyumlar bo‘lmasligi eng muhim xavfsizlik qoidangiz bo‘lib qoladi.') WHERE id = '03beae21-c620-431a-a745-a2cb5663e55d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy o‘yinlar murakkablashmoqda: Chaqalog‘ingiz endi "ber-ol" o‘yinini yangi bosqichga olib chiqmoqda. U o‘yinchoqni sizga berib, darhol qaytarib so‘rashi yoki siz "ber" deganingizda uni ataylab yashirishi mumkin. Bular uning ilk "hazillari"dir. Uning bu hazillariga kulib javob bering. Kulish va birgalikda zavqlanish orangizdagi hissiy rishtani nihoyatda mustahkamlaydi.') WHERE id = '3339985d-3305-4eb1-9ee4-eac876362604';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uyqu tartibi va uyg‘oq qolish muddati: 11-oyda chaqaloqlarda kunduzgi 2 mahal uyqudan 1 mahal uyquga o‘tish (nap transition) belgilari paydo bo‘lishi mumkin, ammo hozircha shoshilmang. Aksariyat chaqaloqlar 14-15 oylikkacha kunduzgi 2 mahal uyquga ehtiyoj sezadi. Agar ertalab uxlashi qiyin bo‘lsa, uyg‘oq qolish muddatini biroz uzaytirib ko‘ring (taxminan 3 - 3.5 soat). Yaxshi dam olgan chaqaloq yangi ko‘nikmalarni yanada ishtiyoq bilan o‘rganadi.') WHERE id = 'db42c776-feed-4c94-906a-857e9999bca9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy idrok": Chaqalog‘ingiz endi qutilarning ichiga qarashni, qopqoqlarni ochib-yopishni va buyumlarni bir-birining ichiga joylashni yaxshi ko‘radi. Unga turli o‘lchamdagi plastik idishlarni bering. U kichik idish katta idishning ichiga sig‘ishini kashf etganida, miyasida murakkab matematik va mantiqiy bog‘lanishlar shakllanadi. Bu oddiydek ko‘rinsa-da, aslida katta bir kashfiyotdir.') WHERE id = 'c317d6dc-6305-468b-bef4-37407eacbfe2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 330 kunni ortda qoldirdik! Birinchi tug‘ilgan kunigacha atigi bir oy qoldi. Chaqalog‘ingiz endi o‘z xohish-irodasini namoyon qilmoqda: kiyinishni istamasa, oyoqlarini tirab oladi, sevimli taomini ko‘rsa, qo‘llarini chapak chaladi. Bu "shaxsiyat" belgilari ba’zan sizni charchatsa-da, aslida uning sog‘lom psixologik rivojlanayotganidan dalolat beradi. Siz ajoyib yo‘lni bosib o‘tdingiz, Onajon!') WHERE id = 'c209d7a9-28c5-4bcf-a9ab-ed5e68cd5e38';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy ko‘nikmalardagi "Hazillar": Chaqalog‘ingiz ataylab o‘yinchoqni sizga berib, darhol qaytarib oladimi va bundan kuladimi? Bu unda hazil tuyg‘usi va ijtimoiy ta’sir ko‘rsatish qobiliyati shakllanayotganini bildiradi. Uning bu "o‘yiniga" zavq bilan qo‘shiling. Birgalikda kulish orangizdagi hissiy rishtani mustahkamlaydi va unda sog‘lom o‘ziga ishonchni shakllantiradi.') WHERE id = 'f977f0c6-061a-4189-bf33-4e6656c97984';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "Tanlab yeyish" boshlanishi mumkin. Chaqalog‘ingiz kecha yegan taomini bugun qat’iyan rad etishi mumkin. Bu uning endi o‘z xohish-irodasini namoyon etayotganidan dalolat beradi. Uni majburlamang, ammo yoqtirmagan mahsulotini biroz vaqt o‘tgach, boshqa shaklda yana taklif qiling. Eng muhimi, dasturxon atrofida taranglik yuzaga kelmasin. Ovqatlanish vaqti uning uchun yoqimli odat bo‘lib qolishi kerak.') WHERE id = 'eb15bd6a-93d6-4986-92eb-7294c9a935c2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikadagi "Konstruksiya yaratish" ko‘nikmasi: Chaqalog‘ingiz endi kublarni ustma-ust qo‘yib, kichik "minoralar" yasashga urinadi. Hozircha minora tez qulab tushishi mumkin, ammo bu uning qo‘l-ko‘z muvofiqligi va diqqatini jamlashi uchun ajoyib mashqdir. Unga turli o‘lcham va rangdagi kublarni bering. Qulagan minoraga birgalikda kulib, "Qani, yana bir marta quramiz!" deb uni ruhlantiring.') WHERE id = '7a4a5884-cfbe-4717-937f-7483274cf1dd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy idrok" va xotira: Chaqalog‘ingiz endi sevimli o‘yinchog‘i qayerga yashirilganini biladi va uni topish uchun to‘siqlarni (masalan, yostiqni) chetga suradi. Bu uning muammoni hal qilish qobiliyati rivojlanayotganini ko‘rsatadi. U bilan murakkabroq "bekinmachoq" o‘yinlarini o‘ynang. To‘siqlarni yengib o‘tish uning miyasidagi mantiqiy bog‘lanishlarni mustahkamlaydi.') WHERE id = '87a69c40-9317-47d9-89ca-fad250ba27cf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'O‘zini anglash va mustaqillik: Chaqalog‘ingiz endi kiyinayotganda sizga "yordam berishga" urinadimi? Masalan, paypoq kiydirish uchun oyog‘ini uzatadi yoki qo‘lini ko‘ylak yengiga kiritadi. Bu urinishlarini qo‘llab-quvvatlang va uni maqtang. "Voy, qanday chiroyli kiyindingiz!" deyishingiz uning o‘zini alohida shaxs sifatida anglashiga va mustaqil bo‘lish istagiga katta hissa qo‘shadi.') WHERE id = '82ceaad9-caa0-45d0-ae94-6fb25e59d3dc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tish chiqish davrining yakuniy bosqichlari (ilk yil uchun): 1 yoshga yaqin chaqaloqlarning ko‘pchiligida allaqachon 4-8 ta tish bo‘ladi. Milklar yana shishishi yoki og‘rishi mumkin. Unga chaynash uchun salqin sabzavot bo‘laklarini (sabzi, bodring – albatta nazorat ostida!) bering. Chaynash milklarni massaj qilish bilan birga, jag‘ mushaklarini ham mustahkamlaydi.') WHERE id = '3fe62d47-f929-4c62-b0de-6bc80e34943b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Stakandan suv ichish odati endi to‘liq shakllangan bo‘lishi kerak. So‘rg‘ichli shishadan (butilkadan) asta-sekin voz kechish vaqti keldi. Butilkadan uzoq vaqt foydalanish tishlarning joylashuvi va nutq rivojiga salbiy ta’sir qilishi mumkin. Unga qiziqarli, rang-barang ichish idishlari yoki oddiy ochiq stakan taklif qiling. Mustaqil ichishi unga katta erkinlik hissini beradi.') WHERE id = '38eafb23-62e2-4538-a93f-213f32e35986';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy xotira" va tartib: Chaqalog‘ingiz o‘yinchoqlari qayerda turishini endi biladi. O‘yin tugagach, ularni birgalikda yig‘ishtiring. "Kel, ayiqchani uyiga (qutiga) joylaymiz", deb uni ruhlantiring. Bu unda mas’uliyat hissini shakllantiradi va har bir buyumning o‘z joyi borligini tushunishga yordam beradi. Tartib-intizomga oid odatlar aynan shu oylarda shakllana boshlaydi.') WHERE id = 'c880f2e4-5f85-403c-b1f7-b1634ed3e06b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqu va uyg‘oq qolish davomiyligi: Chaqalog‘ingiz endi kunduzgi uyqulari orasidagi vaqtni uzaytirishi yoki ulardan birini qisqartirishi mumkin. Agar u kunduzi bir marta uxlab ham o‘zini yaxshi his qilsa, kun tartibini shunga moslashtiring. Biroq 1 yoshli bolalarning aksariyati hali ham ikki marta uxlashga ehtiyoj sezadi. Undagi charchoq belgilarini kuzatishda davom eting; yaxshi dam olgan bola baxtliroq va o‘rganishga moyilroq bo‘ladi.') WHERE id = '9898d949-3ccb-4708-a982-1de8127dfcfd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 340 kunni ortda qoldirdik! Birinchi tug‘ilgan kuniga atigi 25 kun qoldi. Chaqalog‘ingiz endi o‘z didi, fe’l-atvori va sevimli o‘yinlariga ega alohida shaxs. Bugun u bilan yerga yotib, shunchaki uning o‘zi tanlagan o‘yinni o‘ynang. Sizning uning dunyosiga kirishingiz u uchun eng katta sovg‘adir. Siz ajoyib bir yilni o‘tkazdingiz, Onajon!') WHERE id = 'c4c0444c-fad1-4344-8a31-c99f7a9878d9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tug‘ilgan kuniga atigi 25 kun qoldi! Agar chaqalog‘ingiz allaqachon mustaqil ravishda bir necha qadam tashlayotgan bo‘lsa, bu uning muvozanat markazi to‘liq shakllanganini ko‘rsatadi. Agar u hali yurmayotgan bo‘lsa, qo‘llaridan ushlab yurishga majburlamang. Bu uning umurtqa pog‘onasiga ortiqcha yuk tushirishi mumkin. Eng yaxshisi, uning qarshisida turib, quchog‘ingizni ochgan holda siz tomonga kelishga undang. Sizning ishonch bilan qarashingiz unga eng katta jasorat bag‘ishlaydi.') WHERE id = '8681364a-206a-4e87-acfa-4a44f4404ec8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "retseptiv til" (tushunish qobiliyati) rivoji: Chaqalog‘ingiz endi oddiy ko‘rsatmalarni tushunadi. "To‘pni menga ber", "Bu yerga kel", "Bosh kiyimingni ol" deganingizda, u buni bajara oladimi? U hali barcha so‘zlarni ayta olmasa-da, miyasida katta lug‘at zaxirasini to‘plagan. U bilan gaplashishda davom eting va har bir harakatingizni so‘z bilan ifodalang. Bu uning kelajakdagi nutqi uchun mustahkam poydevordir.') WHERE id = 'b0d73932-0d82-458c-b55b-ddc718662495';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Yo‘q" so‘zining kuchi: Chaqalog‘ingiz endi sizning "Yo‘q" deyishingizga qarshilik qilishi, hatto yerga yotib olib yig‘lashi mumkin (dastlabki injiqlik xurujlari). Buning sababi — u hali his-tuyg‘ularini boshqarishni bilmaydi. Xotirjam bo‘ling, uning yoniga cho‘kkalab, hislarini ifodalab bering: "Hozir jahling chiqyapti, chunki men o‘yinchoqni bermadim, tushunaman". Sizning bunday xotirjamligingiz unga hissiy barqarorlikni o‘rgatadigan eng yaxshi saboqdir.') WHERE id = '627b69c9-1a97-4379-b790-7b2e4d39bfb2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 350 kunni ortda qoldirdik! Birinchi tug‘ilgan kuniga atigi 15 kun qoldi! Bugun uning dastlabki oylarda tushgan suratlarini tomosha qilib, birgalikda qanchalik katta yo‘lni bosib o‘tganingiz haqida o‘ylang. O‘sha yordamga muhtoj chaqaloq endi o‘z xarakteriga ega shaxsga aylandi. Bu 15 kunni stresssiz, shunchaki u bilan vaqt o‘tkazib, zavq bilan qarshi oling. Siz ajoyib bir yilni o‘tkazdingiz, Onajon!') WHERE id = '8417d81b-7389-4675-845a-7c49bcb07801';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Birinchi tug‘ilgan kuniga atigi 10 kun qoldi! Chaqalog‘ingiz endi kitob sahifalarini (hozircha bir nechtasini birdaniga) varaqlay oladimi? Bu uning nozik motorikasi rivojlanayotgani va kitoblarga qiziqishi ortayotganidan dalolat beradi. Unga katta va rang-barang rasmlari bor kitoblarni o‘qib berishda davom eting. Rasmdagi itga qarab, "Vov-vov qayerda?" deganingizda, uni barmog‘i bilan ko‘rsatishi uning anglash qobiliyati juda yaxshi rivojlanganini ko‘rsatadi.') WHERE id = '3e342e5d-4541-4b82-ae58-b2cc792f784b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Chaqalog‘ingiz musiqa sadolarini eshitganda tanasini tebratib, tizzalarini bukib-yozib "raqs" tushyaptimi? Musiqa ritmini his qilishi uning eshitish qobiliyati va tana harakatlarini muvofiqlashtirishi takomillashayotganini ko‘rsatadi. U bilan birga qarsak chaling, ritmga jo‘r bo‘ling. Bunday quvnoq lahzalar uning miyasida baxt gormonlari ajralishini kuchaytiradi va siz bilan bo‘lgan rishtalarini yanada mustahkamlaydi.') WHERE id = '824b4580-ab45-4cbc-9104-e999a9e050cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Buyumlarning vazifasi" endi to‘liq anglanadi. Chaqalog‘ingiz taroqni ko‘rsa, boshiga olib boradi, oyoq kiyimini ko‘rsa, oyog‘iga tutadi. U endi buyumlar shunchaki o‘yinchoq emasligini, ularning har biri muayyan vazifani bajarishini tushunadi. Unga xavfsiz ro‘zg‘or buyumlari (plastik idishlar, toza cho‘tkalar) bilan o‘ynashga ruxsat bering. Bu uning kundalik hayotga moslashishini tezlashtiradi.') WHERE id = '40fb0a95-63d4-4ada-888b-1faf14ddd19d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "takrorlash" davri. U siz aytgan so‘zlarning oxirgi bo‘g‘inlarini takrorlashga urinishi mumkin. Masalan, siz "olma" desangiz, u "ma" deyishi mumkin. Bu uning nutq apparati uchun faol mashqdir. U bilan doimo aniq va to‘g‘ri talaffuz qilib gaplashing. "Bolalar tilida" (pıppı, miamia va hokazo) gapirish o‘rniga, buyumlarning asl nomlarini aytish uning lug‘at boyligini to‘g‘ri shakllantiradi.') WHERE id = '40321163-794d-42e6-bcde-127caef60c13';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqil ovqatlanish ko‘nikmalari endi barqarorlashishi kerak. Ha, u hali ham qoshiqni teskari ushlashi yoki ovqatning yarmini yerga to‘kib yuborishi mumkin, ammo o‘zi ovqatlanishga urinishi uning o‘ziga bo‘lgan ishonchi uchun hamma narsadan muhimroq. Unga o‘zi uchun qulay bo‘lgan chuqur idish va rezina dastali qoshiq bering. Sabrli bo‘ling, ko‘p o‘tmay u oilaviy dasturxonning eng faol va "mustaqil" a’zosiga aylanadi.') WHERE id = 'd42878d7-1b6d-456a-b198-9e59777aacf0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Ajralish xavotiri" (Separation anxiety) 1 yosh arafasida yana avjiga chiqishi mumkin. Siz xonadan chiqqaningizda uning qattiq yig‘lashi sizga chuqur bog‘langanidan va hali ham "onam ketib, qaytib kelmaydi" deb qo‘rqishidan dalolat beradi. Unga har doim qayerga ketayotganingizni va qachon qaytishingizni ayting (hatto boshqa xonaga o‘tayotgan bo‘lsangiz ham). Sizning rostgo‘yligingiz uning ishonch hissini tiklaydi.') WHERE id = 'bf1abd20-6eb2-41e7-85ec-e1c3f46808a3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikadagi yangi yutuq: "Qopqoqni ochish va yopish". Chaqalog‘ingiz endi qutilarning qopqog‘ini ochish, butilkalarning qopqog‘ini burashga urinish kabi harakatlardan zavqlanadi. Bu bilak va barmoq mushaklarining yuqori darajadagi muvofiqlashuvidan dalolat beradi. Unga turli o‘lchamdagi plastik idishlar bering va ularni bir-birining ichiga joylashtirishiga imkon bering. Bu, shuningdek, uning matematik va mantiqiy tafakkurini rivojlantiradigan ilk mashqdir.') WHERE id = '4e49e60c-de35-4a74-ac4f-e95ac56a3410';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy qoidalarni o‘rganish: Chaqalog‘ingiz endi "xayr" deyish (qo‘l silkitish), "bo‘sa yuborish" yoki "qo‘l berish" kabi imo-ishoralarni ongli ravishda bajaradi. Bular uning jamiyatga kirishi uchun ilk "viza"laridir. Uning bunday ijobiy xatti-harakatlarini doimo quvonch bilan qarshi oling. Sizning munosabatingiz unga qaysi xatti-harakat "yaxshi" ekanini tushunishga yordam beradi.') WHERE id = '21db9180-06af-489e-83b0-28bdcc1730d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ertaga chaqalog‘ingiz roppa-rosa 1 yoshga to‘ladi! Bugun o‘tgan 12 oylik sarguzashtni yodga oling. Ilk tabassum, ilk tish, ilk emaklash... Qanchalik qiyin bo‘lmasin, siz buni uddaladingiz! Chaqalog‘ingiz endi yordamga muhtoj go‘dak emas, o‘z fe’l-atvori va istaklariga ega jajji insondir. Bu kecha uyquga yotayotganda o‘zingizga ham bir "barakalla" deng. Siz ajoyib onasiz!') WHERE id = '74f434ee-a5bf-498f-af06-34cc0939c106';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'TABRIKLAYMIZ! ILK TUG‘ILGAN KUNINGIZ MUBORAK! 🎂 Chaqalog‘ingiz endi rasman 1 yoshda. Bu yil uning ham, sizning ham hayotingizda eng katta o‘zgarishlar yuz bergan yil bo‘ldi. U endi yurish, gapirish va dunyoni zabt etishga tayyor bo‘lgan "Toddler"dir (yurishni boshlagan bola). Bu kunni stresssiz, shunchaki uning kulgisi va sizning mehringiz bilan nishonlang. Yo‘lingiz ochiq, umringiz barakali bo‘lsin!') WHERE id = '56917d9b-b358-4310-b651-30aecbaf8560';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '2-yilga xush kelibsiz! Birinchi tug‘ilgan kun hayajoni ortda qoldi, ammo haqiqiy sarguzasht endi boshlanadi. Chaqalog‘ingiz endi rasman "yurishni boshlagan bola" (toddler) maqomida. Shu oydan boshlab u dunyoni ko‘proq tik turgan holda kashf etishni istaydi. Uning harakatchanligi oshgani sari energiyaga bo‘lgan ehtiyoji ham o‘zgaradi. Ammo unutmang, ona suti yoki sutli aralashma hali ham uning ovqatlanish ratsionining muhim qismi bo‘lib qolishi mumkin.') WHERE id = '165b6f1d-3374-4097-b9a4-8e514ea4fdd0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Yurish ko‘nikmasi mustahkamlanmoqda! Agar chaqalog‘ingiz allaqachon mustaqil qadam tashlayotgan bo‘lsa, uning qadamlari hali biroz "mastona" va oyoqlari keng ochilgan holda ekanini ko‘rasiz. Bu muvozanatni saqlashga yordam beradigan tabiiy mexanizmdir. Uyda imkon qadar uni yalangoyoq yurgizing. Bu oyoq kaftining to‘g‘ri shakllanishi va miyasiga yer yuzasining tuzilishi haqida ko‘proq ma’lumot yetib borishi uchun eng yaxshi usuldir.') WHERE id = 'c278e801-c9bd-49de-b0fb-e7e23f4f7d75';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1 yoshdan keyin bolalarning ishtahasi to‘satdan pasayishi mumkin. Bu "fiziologik anoreksiya" deb ataladi. Sababi oddiy: bolaning o‘sish sur’ati birinchi yilga nisbatan sekinlashadi va unga avvalgidek ko‘p kaloriya kerak bo‘lmaydi. Uni majburlab ovqatlantirishga urinmang. Eng muhimi, siz taklif qilayotgan taomlar sifatli va xilma-xil bo‘lsin. U qancha ovqat yeyishi kerakligini o‘zi boshqarishni o‘rganishi lozim.') WHERE id = 'dd5c13fb-e41c-4d49-a21d-c17c38691c1f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Bir so‘zli gaplar" davri. Chaqalog‘ingiz endi bitta so‘z bilan butun bir fikrni ifodalaydi. Masalan, "Ay-yay" deyishi ham "tashqariga chiqaylik", ham "oyoq kiyimimni kiydiring" degan ma’noni anglatishi mumkin. Siz uning shu bitta so‘zini kengaytirib javob bering: "Ha, hozir oyoq kiyimingni kiyib, hovliga (ay-yay) chiqamiz". Bu uning gap tuzish ko‘nikmasini tezroq rivojlantiradi.') WHERE id = '4f614506-d560-4d40-bad9-c0ba7ee808d8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zim!" davri tobora kuchaymoqda. Chaqalog‘ingiz qo‘lini yuvishga uringanda, zinadan ko‘tarilganda yoki kiyinayotganda yordamingizni rad etishi mumkin. Bu qaysarlik emas, balki mustaqil bo‘lishga urinishdir. Xavf tug‘dirmaydigan vaziyatlarda unga "ruxsat etilgan erkinlik" bering. Biror ishni o‘zi uddalay olishini ko‘rish uning o‘ziga bo‘lgan ishonchini (self-esteem) shakllantiradigan eng muhim omildir.') WHERE id = '884b93ff-cafb-4926-88b8-45e9267f348c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy ko‘nikmalarda "Parallel o‘yin" bosqichi. Agar chaqalog‘ingizni tengdoshlari yoniga olib borsangiz, u boshqa bolalar bilan emas, balki ularning yonida o‘zi alohida o‘ynayotganini ko‘rasiz. Bu 1-2 yoshli bolalar uchun mutlaqo tabiiy holat. Ular hali o‘rtoqlashishni va birga o‘ynashni bilmaydi, ammo bir-birini kuzatib, ko‘p narsani o‘rganadi. Ijtimoiylashishi uchun uni parklar va o‘yin guruhlariga olib borishda davom eting.') WHERE id = 'e23b48b6-63ac-4bcc-9b95-51974a62ac74';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorika mahorati: Chaqalog‘ingiz endi qalam yoki mo‘yqalamni (hozircha kafti bilan) ushlab, qog‘ozga "chizib-qoralashi" mumkin. Bu uning qo‘l va ko‘z muvofiqlashuvida yangi bosqichdir. Unga katta qog‘ozlar va bolalar uchun xavfsiz rangli qalamlar bering. Bu mashg‘ulot uning ijodiy tasavvuriga ham ilk urug‘larni sepadi. Devorlar "san’at asari"ga aylanib qolmasligi uchun uni doimo nazorat qilib turing!') WHERE id = '0b6473c4-31af-4b7f-87fd-2d01229d5be8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uyqu tartibidagi o‘zgarish: 13-oyda ko‘plab bolalar kunduzgi ikki mahal uyqudan bir mahal uyquga o‘tishni xohlaydi. Agar u ertalab uxlashga qiynalsa yoki tushlikdan keyingi uyqusi juda kechiksa, tartibni o‘zgartirish vaqti kelgan bo‘lishi mumkin. Bir mahal uyquga o‘tish bir necha hafta davom etishi mumkin va bu o‘tish davrida u kechqurunlari biroz ko‘proq "bezovta" bo‘lishi mumkin. Sabrli bo‘ling, yangi tartib har ikkingiz uchun ham qulayroq bo‘ladi.') WHERE id = '04380a78-48ac-47f1-b32c-6d6f9bfeb4d4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xavfsizlikdagi "Balandlik" omili. Chaqalog‘ingiz endi stullarga tirmashib, stol ustiga chiqishga urinmoqda. U hali balandlikdan qo‘rqish hissi va xavflarni to‘liq anglamaydi. Deraza qulflarini tekshiring, baland mebellarni devorga mahkamlang. Uning erkin harakatlanishini cheklamasdan, atrof-muhitni "yiqilishdan himoyalangan" holga keltirish sizning asosiy vazifangizdir.') WHERE id = '6948a89f-6493-4c6e-9adb-708a1f0063cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '13-oyning dastlabki o‘n kunini yakunladingiz! Chaqalog‘ingiz endi oddiy ko‘rsatmalarni ("O‘yinchog‘ingni qutiga sol", "Bu yerga kel") ongli ravishda bajara oladi. Bu uning ham nutqiy, ham ijtimoiy rivojlanishidagi katta yutuqdir. Bugun u bilan birga kitob o‘qing va rasmdagi narsalarni topishini so‘rang. Siz bilan mazmunli o‘tkazgan har bir daqiqasi uning rivojlanishi uchun eng katta ko‘makdir.') WHERE id = '702b1e33-f64a-46f4-9e5d-44efebebe748';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz endi "Yo‘q" so‘zining kuchini kashf etdi! Bu davrda u hamma narsaga qarshilik ko‘rsatib, o‘z chegaralarini sinab ko‘radi. Bu o‘jarlik emas, balki uning mustaqil shaxs sifatida shakllanishidir. Siz "Yo‘q" deganingizda, u ataylab o‘sha ishni qilib, munosabatingizni kuzatishi mumkin. Xotirjam bo‘lishga harakat qiling; sizning hissiy barqarorligingiz unga qoidalarni o‘rgatuvchi eng yaxshi yo‘l-yo‘riqdir.') WHERE id = 'e0c32222-756f-4ca9-8533-fb5e6a6bf334';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Yurish mahorati takomillashgani sari u endi orqaga yurishga yoki qadam tashlayotganda qo‘lida o‘yinchoq olib yurishga urinadi. Bu ham jismoniy kuchi, ham miyasining harakatlarni muvofiqlashtirish qobiliyati rivojlanayotganini ko‘rsatadi. Unga tortib yurishi mumkin bo‘lgan g‘ildirakli o‘yinchoqlar bering. Bunday o‘yinlar uning oyoq mushaklarini yanada mustahkamlaydi.') WHERE id = '49b402b9-bb72-400d-ac9d-7af091029dd1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqu paytida "faol harakatlar" kuzatilishi mumkin. Chaqaloq uyqusida ag‘darilishi, joyini o‘zgartirishi yoki to‘satdan o‘tirib olishi mumkin. Uning miyasi kunduzi o‘rgangan barcha yangi harakatlarni uyquda "mashq qiladi". Agar u yig‘lamayotgan bo‘lsa, aralashmang. O‘zi uchun qulay holatni topib, uyqusini davom ettirishiga imkon bering.') WHERE id = '5ccc44b7-6be9-42e8-9051-5aba385dfbb3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 13-oyning yarmiga yetdingiz! Farzandingiz endi oddiy iltimoslarni to‘liq tushunadi va hatto sizga "yordam berishni" xohlaydi (masalan, o‘yinchoqni qutiga solish). Uning bu ishtiyoqini so‘ndirmang, har bir kichik yordami uchun uni zavq bilan maqtang. Sizning qo‘llab-quvvatlashingiz kelajakda uning yanada mas’uliyatli va o‘ziga ishongan inson bo‘lib ulg‘ayishiga yordam beradi. Siz ajoyib onasiz!') WHERE id = '2f2ae51c-beef-4df3-9d10-cb7325ea4331';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz qoshiqdan foydalanishni ancha yaxshi o‘zlashtirdi. Ha, ovqatning bir qismi hali ham yerga to‘kiladi, ammo u bilak harakatlarini endi yaxshiroq boshqara oladi. Unga mustaqil ovqatlanish uchun ko‘proq imkon bering. To‘yganini anglab, ovqatni chetga surishi uning ichki ochlik va to‘qlik signallarini tinglayotganini ko‘rsatadi. Bu kelajakda sog‘lom ovqatlanish odatlarini shakllantirish uchun juda muhim.') WHERE id = '45554d06-2e09-4223-93a8-104614df2f0c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz endi ongli ravishda "yordam berishga" harakat qilmoqda. Masalan, o‘yinchoqlarini qutiga yig‘adi yoki sizga biror narsani uzatadi. Bu uning ijtimoiy mas’uliyat hissining ilk belgilaridir. U har safar biror narsa olib kelganida: "Katta rahmat, menga juda yordam berding", deng. Bunday maqtovlar uning o‘zini kerakli va qobiliyatli his qilishiga yordam beradi.') WHERE id = '5614d8e1-6798-45a7-8bfd-239e88293a49';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Yangi qo‘rquvlarning paydo bo‘lishi: 13-14 oylik bolalar to‘satdan changyutgich ovozidan, qorong‘ilikdan yoki begona odamlardan qo‘rqa boshlashi mumkin. Bu ularning tasavvuri va atrof-muhitni anglash qobiliyati rivojlanayotgani bilan bog‘liq. Uning qo‘rquvi ustidan kulmang, "buning nimasi qo‘rqinchli?" demang. Shunchaki yonida bo‘ling, bag‘ringizga bosing va xavfsiz ekanini his qildiring. Vaqt o‘tishi bilan bu qo‘rquvlar yo‘qoladi.') WHERE id = '320f797a-413e-4747-8432-a77c70f8f1ae';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Qisqichsimon ushlash" qobiliyati shu qadar rivojlanganki, farzandingiz kitob sahifalarini (hozircha qalin sahifalarni) birma-bir varaqlay oladi. Bu uning nozik motorikasini ham, kitobga bo‘lgan qiziqishini ham rivojlantiradi. Unga rang-barang va katta rasmlari bor kitoblarni o‘qib berishda davom eting. Rasmda ko‘rgan buyumining nomini aytishini so‘rab, nutqini rivojlantiring.') WHERE id = '3f0fc8bf-420a-4d0f-acf7-ab2d58fa2a4b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "tanlab yeyish" davri davom etmoqda. Bola kecha yaxshi ko‘rgan ovqatini bugun yerga otishi mumkin. Bu bosqichda "qancha yeyish"ni bolaning o‘ziga qo‘yib bering, siz esa "qachon va nimani" yeyishini belgilang. Dasturxon atrofida majburlash emas, yoqimli muhit yarating. Unutmang, uning oshqozoni hali ham kichkina va hatto bir necha luqma ham unga yetarli bo‘lishi mumkin.') WHERE id = '853086ca-90b3-4556-bd83-70b66fd42f49';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda ilk "qarama-qarshi tushunchalar" paydo bo‘lmoqda. U endi "katta-kichik", "issiq-sovuq" kabi farqlarni ko‘rish va teginish orqali tushuna boshlaydi. O‘ynayotganda "Qara, bu katta to‘p, bunisi esa kichkina" deb taqqoslang. Bunday sodda suhbatlar uning mavhum fikrlash qobiliyatini rivojlantirib, lug‘at boyligini tez kengaytiradi.') WHERE id = '8381dd6a-9188-4a53-b0c0-fe9e5722bee4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Ajralishdan qo‘rqish" (Separation anxiety) bu oylarda yana to‘lqinsimon tarzda qaytishi mumkin. Siz xonadan chiqqaningizda yig‘lashi uning sizga muhtojligidan dalolat beradi. Ketishdan oldin doim "Xayr, men birozdan keyin qaytaman" deng va yashirincha chiqib ketmang. Sizning rostgo‘yligingiz unda "onam ko‘rinmay qolsa ham, albatta qaytib keladi" degan ishonchni mustahkamlaydi.') WHERE id = 'd51eadcf-ced3-43a7-a954-d65ad8f07d93';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorika rivojidagi yangi qadam: qopqoqlarni ochish va yopish. Bo‘sh plastik idishlar va ularning qopqoqlari bola uchun eng qiziqarli "boshqotirma" bo‘lishi mumkin. Qopqoqni joyiga to‘g‘ri o‘rnatish uchun barmoqlari harakati va diqqatini muvofiqlashtirishi uning miyasida yangi neyron aloqalarni hosil qiladi. Unga oshxonadagi shu kabi oddiy buyumlar bilan o‘ynashga ruxsat bering.') WHERE id = '6e7fc713-da58-436a-956b-2725c7ebe15b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi o‘z hislarini jismoniy harakatlar orqali namoyon qila oladi – baqirishi, o‘zini yerga tashlashi yoki sizni quchoqlashi mumkin. Bu uning his-tuyg‘ularini boshqarish qobiliyati hali yetarlicha rivojlanmaganini ko‘rsatadi. U jahli chiqqanida yoniga cho‘kkalab, u bilan bir balandlikda bo‘ling va "Hozir jahling chiqyapti, tushunaman" deb hislarini nomlang. Bu kelajakda uning o‘z his-tuyg‘ularini boshqarishi uchun poydevor yaratadi.') WHERE id = '49f6d0be-6454-4212-a7b3-56294a93638b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tish chiqishi jarayonida (odatda bu davrda oziq tishlar chiqishi mumkin) so‘lak ko‘payishi va milklar og‘rishi kuzatilishi mumkin. Bu uning uyqu va ovqatlanish tartibiga ta’sir qilishi mumkin. Unga maxsus tishlagichlar yoki chaynashi mumkin bo‘lgan salqin meva bo‘laklarini bering. Sizning mehringiz va sabringiz unga bu og‘riqli davrni yengilroq o‘tkazishga yordam beradi.') WHERE id = '48e458f5-c261-485d-bb67-d4e81e9a6931';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi musiqa sadolarini eshitganda tanasini ritmga mos ravishda harakatlantiradi yoki qarsak chaladi. Ritmni his qilish miyaning matematik va til markazlari bilan chambarchas bog‘liq. U bilan birga raqsga tushing, qarsak chaling, turli ritmlarni takrorlang. Bu ham jismoniy faollik, ham orangizdagi hissiy rishtani mustahkamlaydigan qiziqarli mashg‘ulotdir.') WHERE id = '22fc8a33-8e0b-4e79-86f9-460a94db933b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy muloqotda "empatiya"ning ilk belgilari: Siz xafa ko‘ringaningizda yoki oyog‘ingizni biror joyga urib olganingizda, bolangiz yoningizga kelib sizga tegishi, sizni quchoqlashi yoki o‘yinchog‘ini berishi mumkin. Bu uning boshqalarning his-tuyg‘ularini tushuna boshlaganini ko‘rsatadi. Uning bunday mehribon harakatiga "Rahmat, sen juda mehribonsan" deb javob bering. Hamdardlik tuyg‘usining urug‘i aynan shu yoshda qadala boshlaydi.') WHERE id = '993a5a5e-046b-489d-bd9d-9580428e1cdc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy xotira" va izlash: Bolangiz endi sevimli o‘yinchog‘i qayerga yashirilganini biladi. U bilan murakkabroq "bekinmachoq" o‘yinlarini o‘ynang. Masalan, o‘yinchoqni quti ichiga solib, ustini sochiq bilan yoping. Uning to‘siqlarni yengib, o‘yinchoqni topishi muammolarni hal qilish ko‘nikmasini rivojlantiradi. Bunday kichik "g‘alabalar" uning o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = '63dfa4ff-f8c9-4a30-bd0e-f8d086dd0898';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xavfsizlik bo‘yicha eslatma: Bolangiz endi hamma narsaga – divanlar, stullar, javonlarga chiqishni xohlaydi... U hali balandlik va xavf darajasini to‘liq anglamaydi. Og‘ir mebellar devorga mahkamlanganiga va zinapoyalarda himoya to‘siqlari o‘rnatilganiga ishonch hosil qiling. Uning atrofni o‘rganishga bo‘lgan qiziqishini so‘ndirmasdan, xavfsiz muhit yaratish muhim.') WHERE id = 'cc4b37ce-4e2e-4d58-a313-414b2395c5eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "takrorlash" davri. Bolangiz siz aytgan so‘zlarning oxirgi bo‘g‘inlarini takrorlashga urinishi mumkin. Masalan, siz "suv" desangiz, u "uv" yoki "suv" deyishi mumkin. U bilan doimo to‘g‘ri va aniq tilda gaplashing. Bolalarcha so‘zlar o‘rniga buyumlarning haqiqiy nomlarini aytish uning so‘z boyligi to‘g‘ri shakllanishiga yordam beradi.') WHERE id = 'd1034aae-153e-40ef-b35f-875a226037db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 13 oyni to‘ldirdik! Bolangiz endi "toddler" (yura boshlagan bola) sifatida o‘z irodasi, fe’l-atvori va mehrini to‘liq namoyon etmoqda. Bugun u bilan yerga yotib, shunchaki u tanlagan o‘yinni birga o‘ynang. U bilan mazmunli o‘tkazgan har bir lahzangiz uning kelajakdagi baxtiga qo‘yilgan poydevordir. Siz ajoyib onasiz!') WHERE id = '4d58b019-ad51-4763-b775-1cff7a5c244e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '14-oyga xush kelibsiz! Bu oyda farzandingiz ham jismoniy, ham hissiy jihatdan ko‘proq "mustaqillik" talab qiladi. U endi qayerga borishni istayotganini va nimani yeyishni xohlamayotganini qat’iy ko‘rsatadi. Bu uning shaxsiyati rivojlanishidagi muhim bosqichdir. Kun davomida unga kichik tanlovlar bering (masalan, "olma yeysanmi yoki nok?"). Tanlash imkoniyati uning noroziliklarini kamaytiradi va o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = '05712130-29d6-4028-9cd7-1eeae1f8b5f6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz endi buyumlarni bir-birining ustiga taxlashda (kublardan minora qurishda) ancha mohir. Bu shunchaki o‘yin emas: u tortishish kuchi, muvozanat va fazoviy munosabatlarni o‘rganmoqda. Minora qulaganda, u "sabab-oqibat" bog‘liqligini anglaydi. Unga turli o‘lcham va rangdagi kublarni berib, ushbu muhim bilish jarayonini qo‘llab-quvvatlang.') WHERE id = '0c30df46-8b8a-4974-a5d4-fa643bc0045f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "So‘zlar portlashi"ga tayyor bo‘ling! Farzandingiz endi har kuni yangi tovushlar yoki so‘zlarni o‘rganmoqda. U atrofidagi buyumlarni barmog‘i bilan ko‘rsatib, siz ularning nomini aytishingizni kutadi. Siz har bir narsaning nomini aytganingiz sari, uning passiv lug‘at boyligi (tushunadigan so‘zlari) faol lug‘atidan (aytadigan so‘zlari) tezroq kengayadi. U bilan doimo gaplashing — bu uning nutqini rivojlantirishning eng yaxshi usulidir.') WHERE id = '462a5499-02c0-46d8-9b87-781f37471081';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Meniki!" davri boshlanadi. Farzandingiz o‘yinchoqlari yoki buyumlarini boshqalarga berishdan bosh tortishi mumkin. Bu unda "egalik" tushunchasi shakllanayotganining ilk belgisidir. Unga "bo‘lishishing kerak" deb bosim o‘tkazmang, chunki u hali bo‘lishish nimaligini to‘liq tushunmaydi. Buning o‘rniga, navbat bilan o‘ynashni ("hozir sening navbating, keyin dadangniki") ko‘rsatib, unga ijtimoiy qoidalarni o‘rgating.') WHERE id = 'bf0454b9-f968-4795-a96d-a48966050e5d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollik: Farzandingiz endi zinadan ko‘tarilishga urinadi (ko‘pincha emaklab yoki qo‘lingizdan ushlab). Bu uning oyoq mushaklarini ham, harakatlar muvofiqligini ham mustahkamlaydi. Zinada doimo uning yonida bo‘ling va xavfsizlik to‘siqlaridan foydalanishni unutmang. Har bir pog‘onaga ko‘tarilishi uning uchun katta bir "zafar"dir!') WHERE id = '6d0b9b84-0a2e-4b5d-941c-44ac3c78711f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqil ovqatlanishdagi navbatdagi qadam: Farzandingiz endi stakandagi suvni deyarli to‘kmasdan icha oladi. Ochiq stakandan ichish uning lab va til mushaklarini nutqqa tayyorlaydi. Agar hali ham so‘rg‘ichli shishadan foydalanayotgan bo‘lsangiz, undan butunlay voz kechish vaqti keldi. Bu tishlarning to‘g‘ri shakllanishi va tanglay salomatligi uchun juda muhimdir.') WHERE id = '59bb00a9-cd0f-4293-859e-3a1c2a23e167';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «chizmachiz» san’ati! Bola endi qalamni ushlab, qog‘ozda dadil chiziqlar chizmoqda. Bu — uning qo‘l-ko‘z muvofiqligi va yozishga tayyorgarlik ko‘nikmalari rivojlanishining eng dastlabki bosqichi. Unga yo‘g‘on, bolalar uchun xavfsiz qalamlar va katta qog‘ozlar bering. Uning ilk «ijodiy ishlarini» maqtang — bu san’atga bo‘lgan qiziqishini oshiradi.') WHERE id = '32044af7-f666-4ab4-a029-c8309f8e7a1b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvordagi «taqlid» endi murakkablashib bormoqda. U nafaqat sizga, balki ko‘rgan boshqa bolalarga, hatto televizordagi qahramonlarga ham taqlid qilishi mumkin. Siz uyni tozalayotganingizda u ham nimanidir artishni, ovqat tayyorlayotganingizda esa aralashtirishni xohlaydi. Unga o‘yinchoq supurgi yoki plastik idishlar berib, «uy ishlariga» jalb qiling. Bu unda mas’uliyat hissini shakllantiradi.') WHERE id = '0d48495d-8dfc-4d4f-a65f-4e2b54b5955c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyquda «uyqu regressiyasi» (buzilishi) yuz berishi mumkin. Bunga ko‘pincha yangi jismoniy ko‘nikmalar (tezroq yurish, tirmashish) yoki kuchaygan ayriliq xavotiri sabab bo‘ladi. Agar bolangiz tunda uyg‘onib, sizni chaqirsa, xotirjam yoniga boring, uni qo‘lingizga olmasdan tinchlantiring va yana uxlab qolishiga yordam bering. Kun tartibini barqaror saqlash bu vaqtinchalik davrni yengillashtiradi.') WHERE id = '15f626ab-5c76-4c8c-ba7f-675666d5bc7d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 400 kunni ortda qoldirdik! Bu aql bovar qilmas raqam. Farzandingiz endi shunchaki «go‘dak» emas, balki o‘z fikrlari, fe’l-atvori va kulgisi bilan oilangizning teng huquqli va eng faol a’zosidir. Bugun u bilan sevimli bog‘ida sayr qiling va dunyoni naqadar katta qiziqish bilan kashf etayotganini kuzating. Siz uning bu yo‘lidagi eng kuchli tayanch va eng mehribon ustozsiz. Barakalla, Ona!') WHERE id = 'cc5a3ed7-bfca-476b-b299-2377ba4200f3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '400 kunlik katta bosqichni ham ortda qoldirdik! Shu kunlarda bolangiz o‘z kiyimini (masalan, bosh kiyimi yoki paypog‘ini) yechishga urinishi mumkin. Bu — uning o‘ziga xizmat qilish ko‘nikmalaridagi ilk qadamidir. Agar u biror narsani kiyish yoki yechishni xohlasa, unga vaqt bering va shoshiltirmang. Biror ishni o‘zi uddalay olganini ko‘rish uning o‘ziga bo‘lgan ishonchini (self-esteem) har narsadan ko‘ra ko‘proq oshiradi.') WHERE id = 'c405a38b-5463-4f2f-a8fe-555b36296982';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bolangiz endi «funksional o‘yin» bosqichidan «ramziy o‘yin»ning dastlabki belgilariga o‘tmoqda. U o‘yinchoq ayiqchasini «ovqatlantirishi» yoki qo‘g‘irchog‘ini uxlatishi mumkin. Bu uning tasavvuri va hamdardlik tuyg‘usi rivojlanayotganini ko‘rsatadi. Bu o‘yinlarda unga qo‘shiling: «Ayiqcha och qolibdimi? Kel, unga biroz pyure beramiz». Bunday o‘yinlar uning ijtimoiy va bilish qobiliyatlari rivojlanishini tezlashtiradi.') WHERE id = 'a392702d-a437-4a73-9212-0aa4a4ef5685';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Bo‘g‘inlarni birlashtirish": Farzandingiz endi turli bo‘g‘inlarni birlashtirib, o‘z tilida uzun "jumlalar" tuzadi. Uning so‘zlarini to‘liq tushunmasangiz ham, u kattalarning gapirish ohangiga juda yaxshi taqlid qiladi. Uni diqqat bilan tinglang va "Ha, shundaymi? Keyin nima bo‘ldi?" deb javob bering. Bunday "muloqot" uning o‘z fikrini ifodalash istagini kuchaytiradi va miyasidagi so‘z boyligini oshiradi.') WHERE id = '71d396d7-4d37-40f4-a3f7-9c1e6ac427ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda mustaqillik: Farzandingiz endi bolalar uchun xavfsiz sanchqidan foydalanishga intiladi. Yumshoq meva yoki sabzavot bo‘laklarini sanchqiga ilishga urinish uning qo‘l va ko‘z muvofiqligini juda yaxshi rivojlantiradi. Stol biroz iflos bo‘lsa ham, unga bu imkoniyatni bering. Bu uning harakat ko‘nikmalariga ham, ovqatga nisbatan ijobiy munosabatiga ham foyda keltiradi.') WHERE id = '333db3d2-14f1-4e63-a2dd-abc9df47ccf2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Toifalar": Farzandingiz endi bir xil rangdagi yoki bir xil turdagi buyumlarni ajrata boshlaydi. Unga turli to‘plar yoki mashinalarni ko‘rsatib, "Boshqa to‘p qani?" deb so‘rang. U o‘xshashliklarni topa boshlaydi. Bu uning mantiqiy tafakkuri uchun poydevordir. U bilan uydagi buyumlarni rangi yoki o‘lchamiga qarab guruhlash o‘yinini o‘ynang.') WHERE id = 'e2b8df1f-c1e3-4ba1-a168-83dfc3901148';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy ko‘nikmalarda "Yordam berish": Agar farzandingiz sizga taqlid qilib, biror narsani artishni yoki olib kelishni istasa, unga kichik "vazifalar" bering. Masalan, "Iltimos, bu salfetkani menga ber". U sizga yordam berayotganini his qilganda, o‘zini katta va kerakli insondek his qiladi. Bu kelajakda unda mas’uliyat hissi va hamkorlik ruhini shakllantirish uchun juda muhimdir.') WHERE id = 'dec6a9fe-e431-4948-b5e9-cde4811493c1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanish: Farzandingiz endi joyida sakrashga yoki musiqa sadolari ostida tizzalarini bukib raqsga tushishga urinadi. Bu uning muvozanat hissini ham, yirik motorika mushaklarini ham mustahkamlaydi. U bilan birga raqsga tushing, harakatlarini takrorlang. Bu ham jismoniy mashq, ham orangizdagi hissiy rishtani mustahkamlaydigan eng quvnoq mashg‘ulotdir.') WHERE id = 'f2ba7880-c8a0-44c4-9683-adcae62249c7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy idrok" va konstruktorlar: Farzandingiz endi kublarni shunchaki ustma-ust taxlamaydi, balki ulardan "devorlar" yoki oddiy shakllar yasashga harakat qiladi. Unga turli o‘lchamdagi konstruktor bloklarini bering. Bu o‘yinlar uning ijodkorligini ham, muammolarni hal qilish qobiliyatini ham rivojlantiradi. Minora qulaganda kulib, "Qani, yana bir bor urinib ko‘ramiz!" deyishingiz unga muvaffaqiyatsizlikdan qo‘rqmaslikni o‘rgatadi.') WHERE id = '3bcda1a7-5185-49d5-9cff-a4657ec214ad';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tungi uyqudagi "regressiya" yoki qo‘rquvlar: 14-oyda ayrim bolalar qorong‘ilikdan yoki yolg‘iz qolishdan qo‘rqa boshlashi mumkin. Bu uning bilish qobiliyati rivojlanayotgani va atrof-muhitni chuqurroq anglayotgani natijasidir. Uxlashdan oldingi odatlaringizni (ertak o‘qish, alla aytish) o‘zgartirmang. Sizning xotirjam va ishonchli ovozingiz unga "hammasi joyida, sen xavfsizsan" degan xabarni beradi.') WHERE id = 'eff64bbb-3777-4339-9e6a-476beebba20d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 410 kunni ortda qoldirdik! Farzandingiz endi har kuni sizni yangi bir yangilik bilan hayratga soladi — goh yangi so‘z aytadi, goh yangi harakatni o‘rganadi. Bugun u bilan yerga yotib, shunchaki uning o‘zi tanlagan o‘yinni o‘ynang. Sizning uning dunyosiga kirishingiz u uchun eng katta baxtdir. Siz bu yo‘lni sabr va mehr bilan bosib o‘tayotgan ajoyib onasiz!') WHERE id = '21628582-4016-4734-a5cc-d731fc576c16';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz endi "Hayvonlar ovozi" olamiga to‘liq kirib bordi. Unga "It qanday ovoz chiqaradi?" yoki "Mushuk nima deydi?" kabi savollar bering. Bu tovushlarga taqlid qilish nutq apparatini (til va lab mushaklarini) kelajakda murakkab so‘zlarni talaffuz qilishga tayyorlaydi. Hayvonlar tasvirlangan kitoblarni birgalikda ko‘rib, bunday suhbatlarni ko‘paytiring; undan rasmdagi hayvonni topib, uning ovoziga taqlid qilishini so‘rang.') WHERE id = '1ba32438-5f06-49eb-a326-d4e6c5037f1b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqil yurishi endi ancha ishonchli. Farzandingiz hozir turgan joyida aylanishni, orqaga qadam tashlashni yoki yurayotganda egilib, yerdagi o‘yinchoqni olishni o‘rganmoqda. Bu muvozanatni saqlashga qaratilgan murakkab mashqdir. Unga to‘siqlardan (yostiqlar, kichik qutilar) oshib o‘tish vazifasini bering. Bunday jismoniy to‘siqlar uning yirik motorikasini ham, muammolarni hal qilish qobiliyatini ham rivojlantiradi.') WHERE id = '67533bf8-42c4-4684-8990-79465e5ffca9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "Nomlash" bosqichi: Farzandingiz endi tana a’zolarini (burun, ko‘z, og‘iz) ko‘rsata oladi. Uni cho‘miltirayotganda yoki kiyintirayotganda "Endi o‘ng qo‘lingni kiyintiramiz", "Bu sening kichkina burning" deb, har bir narsani ovoz chiqarib ayting. Bu unga o‘z tanasining tuzilishini anglashga va lug‘atidagi so‘zlarni tegishli ko‘rinishlar bilan bog‘lashga yordam beradi.') WHERE id = '616b6164-3d66-4e8e-8eaa-1c418d285de7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Sabab-oqibat" bog‘liqligini ko‘rsatadigan o‘yinlarga ko‘proq e’tibor qarating. Masalan, tugmasi bosilganda ovoz chiqaradigan o‘yinchoqlar yoki qopqog‘i ochilganda ichidan biror narsa chiqadigan qutilar. Farzandingiz uning biror harakati atrof-muhitda o‘zgarish yuz berishiga sabab bo‘lishini tushunadi. Bu kashfiyot unda "dunyoga ta’sir ko‘rsata olish" hissi va o‘ziga bo‘lgan ishonchni shakllantiradi.') WHERE id = '8d3ed7f3-9547-466c-ba26-2f33141101eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bolaning xotirasi endi voqealarni uzoqroq vaqt saqlay oladi. U bir necha soat (hatto bir kun) oldin siz yashirgan o‘yinchoqning joyini eslab, uni topishi mumkin. U bilan "yo‘qolgan buyumni top" o‘yinini o‘ynang. Bu uning xotirasi va ko‘z bilan izlash ko‘nikmasini rivojlantiradi. Topganida uni ishtiyoq bilan maqtang, shunda u muvaffaqiyatga erishishdan zavq oladi.') WHERE id = '41a34496-6a48-46a1-9bab-58d653fd4147';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqil kiyinishga urinishlari ko‘payadi. Bola endi oyoq kiyimini kiyishga, boshiga qalpog‘ini qo‘yishga yoki shimining pochalarini tortishga harakat qiladi. Bu urinishlariga to‘sqinlik qilmang va uni shoshirmang. Hatto kiyimini teskari kiyib olsa ham, "O‘zing uddalading, barakalla!" deb ayting. Bu uning mustaqilligi uchun qo‘yilgan ilk poydevordir.') WHERE id = '114533c6-2065-42b8-8349-baf02171f30b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "So‘z birikmalari"ning dastlabki bosqichi: bola endi ikki so‘zni yonma-yon qo‘llashga urinishi mumkin (masalan, "Dada, xayr" yoki "Suv ber"). Agar u hali so‘zlarni birlashtirmayotgan bo‘lsa, unga namuna ko‘rsating. U "Mashina" desa, siz "Ha, katta mashina" deb uning gapini to‘ldiring. Bu uning miyasida grammatik tuzilmalar shakllanishiga yordam beradi.') WHERE id = '66c20a78-018b-46e0-a413-b9d7d652fd0b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: bola endi qo‘lida biror narsani ushlab yurganda o‘zini ancha ishonchli his qiladi. U bir vaqtning o‘zida ham yurishi, ham o‘yinchog‘ini sizga ko‘rsatishi mumkin. Uning uchun "to‘siqlar yo‘lagi" yarating: yerdagi yostiqlarni aylanib o‘tish yoki past quti ustidan hatlab o‘tish. Bu uning muvozanati va o‘z tanasini boshqarish hissini (propriosepsiyani) mustahkamlaydi.') WHERE id = '9f5b4f9d-6c12-455d-adaa-8991ef34a4ef';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zim tanlayman!" davri. Kiyim yoki ovqat masalasida bolaga ikkita xavfsiz tanlov taklif qiling. Masalan: "Ko‘k paypog‘ingni kiyishni xohlaysanmi yoki qizilini?". Bu usul bolada vaziyatni nazorat qilish hissini shakllantiradi va kelajakda yuzaga kelishi mumkin bo‘lgan "qaysarlik xurujlari"ning oldini olishga yordam beradi. Tanlov qilish — qaror qabul qilish ko‘nikmasining poydevoridir.') WHERE id = '3e2f13ff-1204-4de3-91f9-ba0a61eced52';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorika uchun "Saralash" o‘yinlari. Bola endi kublarni rangi yoki o‘lchamiga qarab ajrata boshlashi mumkin. Unga turli rangdagi idishlarni bering va bir xil rangdagi o‘yinchoqlarni mos idishlarga solishni ko‘rsating. Bu o‘yin uning mantiqiy tafakkuri va ranglarni idrok etish qobiliyatini jadal rivojlantiradi.') WHERE id = '1833bec9-62a3-4273-aaa3-6cb2d5b43918';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda bola endi oila dasturxonidagi deyarli barcha taomlarni (kam tuzli va qo‘shimchalarsiz) yeyishi mumkin. Unga o‘zining kichik sanchqi va qoshig‘i bilan mustaqil ovqatlanish imkonini bering. Ovqatni bevosita qo‘llari bilan his qilishi (uning tuzilishini tushunishi) ovqat tanlash odatini kamaytiradi. Atrofning ifloslanishi odatiy hol, eng muhimi — u mustaqil ovqatlanish ko‘nikmasini egallashidir.') WHERE id = '724fdd08-1982-44c9-81ad-e2e9e494133c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Tizish" ko‘nikmasi: Bola endi yirik munchoqlarni ipga tizishga (albatta, nazorat ostida!) yoki halqalarni piramidaga o‘tkazishga urinadi. Bu harakatlar barmoq mushaklari muvofiqligini yuqori darajada rivojlantiradi. Unga turli rang va shakldagi halqalarni bering, shu bilan birga ranglar va o‘lchamlarni (katta-kichik) ovoz chiqarib ayting.') WHERE id = '9a5df16b-402c-4293-a449-95f97975e102';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Taqlid qilish" endi yanada ongli tus oladi. Siz telefonda gaplashganingizda, u ham qo‘liga biror narsa olib qulog‘iga tutadi; siz sochingizni taraganingizda, u ham shunga o‘xshash harakat qiladi. Bu — bolaning kundalik hayotdagi odatlarni o‘rganish usuli. Unga xavfsiz maishiy buyumlar (plastik taroq, o‘yinchoq telefon) bilan o‘ynashga ruxsat berib, dunyoni tanishiga yordam bering.') WHERE id = 'ffb2b034-66cc-4cea-967c-b8e6e4f363c4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Kitob o‘qish endi interaktiv mashg‘ulotga aylandi. Bola sahifalarni o‘zi varaqlashni xohlaydi va rasmlarda ko‘rgan tanish buyumlariga quvonch bilan munosabat bildiradi. Undan "Qani, mashina qayerda?" deb so‘raganingizda, uni barmog‘i bilan ko‘rsatishi ko‘rish xotirasi va diqqati qanchalik rivojlanganini anglatadi. Har oqshom bir necha daqiqani kitob o‘qishga ajratishni odat qiling.') WHERE id = 'c199a72c-c2fe-4afe-b5cc-41415b0a5808';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xavfsizlik bo‘yicha eslatma: Bola endi yuqoriga chiqishga juda qiziqadi. U stullardan zina sifatida foydalanib, stol ustiga chiqishi mumkin. Uydagi barcha og‘ir mebellar devorga mahkamlanganiga va o‘tkir burchaklar himoyalanganiga ishonch hosil qiling. Siz ham uni xotirjam kuzata olishingiz uchun bolaning erkin harakatlanishi xavfsiz muhitda ta’minlanishi kerak.') WHERE id = '4ee9c2b3-c8ac-4ff5-98d9-426713c0d86e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanishda "Irodani sinash": Bola istagi amalga oshmasa, yig‘lab yoki o‘zini yerga tashlab norozilik bildirishi mumkin. Bu davrda u bilan bahslashishdan ko‘ra, diqqatini boshqa qiziqarli narsaga yo‘naltirish samaraliroq. Xotirjam ohangda "Sen hozir jahling chiqyapti, lekin o‘yinchoqni qaytarish kerak" deb, uning hislarini nomlang. Sizning xotirjamligingiz uning uchun eng yaxshi namunadir.') WHERE id = '3cd65486-2777-46ac-9963-b43596b260f8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Empatiya" kuchayadi. Bola boshqa bolaning yig‘layotganini ko‘rsa, bezovta bo‘lishi yoki oldingizga kelib, sizni quchoqlashi mumkin. Bu uning boshqalarning his-tuyg‘ularini anglay boshlaganini ko‘rsatadi. Uning bu tuyg‘ularini "Ha, do‘sting hozir biroz xafa" kabi jumlalar bilan nomlang. His-tuyg‘ularni tanish — emotsional intellektning ilk bosqichidir.') WHERE id = 'da7ee871-54fe-4caf-9b11-def1fe5482db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "Anjomlardan foydalanish". Bola endi bolalar sanchqisini (plastik/yumshoq) ovqatga sanchishni yaxshiroq uddalaydi. Unga sanchish oson bo‘lgan yumshoq banan yoki pishirilgan sabzi bo‘laklarini bering. Bu mashg‘ulot nafaqat qo‘l harakatlari muvofiqligini rivojlantiradi, balki ovqatlanish jarayonini uning uchun qiziqarli "mahorat sinovi"ga ham aylantiradi.') WHERE id = '451ba512-8b9d-44f7-915a-a7f1ea152f7c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "Pretend play" (o‘zini biror ishni qilayotgandek ko‘rsatib o‘ynash). Bola endi bo‘sh piyoladan "suv ichayotgandek" qilishi yoki o‘yinchoq mashinasini o‘ynatib, "vrr-vrr" degan ovoz chiqarishi mumkin. Bu o‘yinlarda unga qo‘shiling: "Mashina qayerga ketyapti? Do‘konga?". Bu uning ijodkorligini ham, hodisalar o‘rtasidagi mantiqiy bog‘liqlikni anglashini ham rivojlantiradi.') WHERE id = '58538226-5b39-4731-8bc6-1e9881002e44';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Iroda va chegaralar: Bola endi "Mumkin emas" degan so‘zga munosabat bildiradi, ammo ba’zan ataylab o‘sha ishni qilib, sizga qaraydi. Shu tariqa u sabr-toqatingizni va qoidalar o‘zgarmasligini sinab ko‘radi. Xotirjam, ammo qat’iyatli bo‘ling. Bir safar "Mumkin emas" degan narsangizga boshqa safar ruxsat bermang, shunda qoidalar uning ongida aniq shakllanadi.') WHERE id = 'ccb50bdf-5e11-4253-a1c0-79b7eb2fe4d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bolangiz endi orqaga qarab yurishni yoki turgan joyida aylanishni o‘rganib oldi. Bu harakatlar uning muvozanatni his qilish va tana harakatlarini muvofiqlashtirish qobiliyatini yangi bosqichga olib chiqadi. Unga to‘siqlarsiz, keng joyda bu yangi ko‘nikmalarini sinab ko‘rish imkonini yarating. Tanasini boshqarish qobiliyati oshgani sari o‘ziga bo‘lgan ishonchi ham shuncha mustahkamlanadi.') WHERE id = '527b5771-2c14-44f3-9a1f-7d0335d59d5a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "Maqsadni bildiruvchi" so‘zlar: Bola endi nafaqat buyumlarning nomini aytadi, balki istaklarini ham birgina so‘z bilan ifodalaydi. Masalan, sizga qarab "Eshik" deyishi "Tashqariga chiqishni xohlayman" degan ma’noni anglatishi mumkin. Uning bunday murojaatlariga fikrini kengaytirgan holda javob bering: "Ha, sen eshikni ko‘rsatyapsanmi? Kel, hovliga (ad-da) chiqamiz". Bu uning muloqot qilishga bo‘lgan ishtiyoqini oshiradi.') WHERE id = '1b9f532e-6857-454f-9361-0a20bbd28a5f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanish paytida bolangiz endi ko‘proq mustaqillikni talab qiladi va qoshiq bilan idishidan ovqat olishni yaxshiroq uddalaydi. Unga sanchqi bilan olish mumkin bo‘lgan (fork-friendly) kichik bo‘laklarni taklif qiling. Mustaqil ovqatlanish unga to‘yganini anglashga va turli tuzilishdagi taomlarga ko‘proq qiziqish bildirishga yordam beradi.') WHERE id = '369e5ef8-dd84-4005-92a0-3547d1d81f03';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi siz «yo‘q» deganingizda reaksiyangizni sinash uchun o‘sha harakatni ataylab qilishi mumkin. Bu davrda xotirjam va qat’iyatli bo‘lish eng muhim qadamdir. Agar biror narsaga «mumkin emas» degan bo‘lsangiz, buni har safar bir xil ohangda va bir xil tarzda takrorlang. Qoidalarning o‘zgarmasligi bolada xavfsizlik va tartib hissini shakllantiradi.') WHERE id = '3b03f902-43dc-4352-9de9-99e2a04d004c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bolangiz endi shunchalik tez yuradiki, ba’zan yugurishga ham urinadi. Biroq muvozanat markazi hali to‘liq shakllanmagani uchun u tez-tez yiqilishi mumkin. Uning atrofni o‘rganishi uchun ko‘proq tekis va yumshoq joylar (gilam, maysazor) yarating. Yugurayotganda qo‘llarini ikki tomonga yoyib, muvozanatni saqlashga urinishi jismoniy rivojlanishining tabiiy bir qismidir.') WHERE id = 'd5bd999f-15a8-4225-95dc-a3e29ec9bb65';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xotira rivoji: Bola endi buyumlar qayerda turishini eslab qoladi. Masalan, poyabzallar yo‘lakda, o‘yinchoqlar esa qutida ekanini biladi. Undan «Poyabzaling qayerda?» deb so‘raganingizda, o‘sha tomonga qarashi yoki ko‘rsatishi uning idrok qobiliyati rivojlanayotganini bildiradi. O‘yin tugagach, o‘yinchoqlarni birgalikda joyiga yig‘ib, unda tartib-intizom odatini shakllantiring.') WHERE id = '821949a4-99c0-456c-ba4e-1768b6ba56ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Hayvonlar va ularning tovushlarini farqlash». U endi rasmda ko‘rgan hayvonini nafaqat taniydi, balki siz so‘ramasangiz ham uning ovoziga taqlid qilishi mumkin. Kitob o‘qiyotganda «Qara, bu sigir. Sigir qanday ovoz chiqaradi?» deb suhbatni davom ettiring. Bu uning eshitish xotirasini ham, so‘z boyligini ham tez rivojlantiradi.') WHERE id = 'ca9adb43-fa2c-4743-a4c9-e39c4eb29777';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Terish va joylashtirish». Bola endi 5-6 ta kubikni ustma-ust qo‘yib, balandroq minoralar qura oladi. Shuningdek, halqalarni kattasidan kichigiga qarab terishga urinishlari uning fazoviy idrokini rivojlantiradi. Minorani buzishdan qanchalik zavqlanayotganini ko‘ryapsizmi? Bu undagi «men dunyoni o‘zgartira olaman» (sabab-oqibat) hissining eng quvnoq namoyon bo‘lishidir.') WHERE id = 'c50f5774-0c5b-40a4-8f99-e817382c1b20';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Zinadan chiqish endi uning eng sevimli mashg‘ulotiga aylangan. U zinadan emaklab yoki qo‘lingizdan ushlab, tik turgan holda chiqishi mumkin. Bu harakat yirik motorikani mustahkamlaydi, shuningdek, unga balandlikni idrok etishni o‘rgatadi. Zina yonida doimo uning yonida bo‘ling va uydagi himoya to‘siqlari yopiq ekaniga ishonch hosil qiling.') WHERE id = '74e3ddee-b891-4ccd-91d8-7ed95452703e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz endi qog‘ozga "chizib-bo‘yash" paytida ancha dadil chiziqlar chizadi. U aylana shaklidagi harakatlar yoki to‘g‘ri chiziqlar chizishga urinishi mumkin. Unga katta qog‘ozlar va kaftiga qulay joylashadigan yo‘g‘on, zaharli bo‘lmagan qalamlar bering. Bu uning kelajakdagi yozish ko‘nikmalari va qo‘l-ko‘z muvofiqlashuvining eng muhim poydevoridir.') WHERE id = '4d091261-3f36-4fe5-bf63-cb391c17abb5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zim qilaman!" davri: Farzandingiz endi qo‘llarini yuvishga, tishlarini tozalashga (hozircha cho‘tkani shunchaki chaynash orqali) yoki stolni artishga intiladi. Uning gigiyena odatlariga bo‘lgan qiziqishini qo‘llab-quvvatlang. Qo‘li yetishi uchun kichik zinapoyacha (step stool) qo‘ying va harakatlaringizni takrorlashiga imkon bering. Bu unda o‘ziga xizmat qilish ko‘nikmalarini shakllantiradi.') WHERE id = '1d418a62-b096-44ed-98d7-1fbf38ca6e83';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy o‘yinlarda "Taqlid qilish" murakkablashib boradi. Siz uyni supurayotganingizda, u ham biror narsani olib supurishni xohlaydi. Unga bolalar o‘lchamidagi kichik "tozalash anjomlari"ni bering. Uy ishlariga shu tarzda "yordam berishi" unga o‘zini oilaning kerakli a’zosi sifatida his qilish imkonini beradi va unda mas’uliyat hissini rivojlantiradi.') WHERE id = '9c0e73ce-723f-4070-afbc-322de1ae0633';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda "Konstruktorlar": Farzandingiz endi 3-4 ta kubikni (blokni) ustma-ust qo‘yib, "minora" qura oladi. Bu diqqatni jamlashni ham, aniqlikni ham talab qiladi. Minora qulab tushganda xursandchilik bilan munosabat bildiring, shunda u muvaffaqiyatsizlikni o‘yin sifatida qabul qiladi. Bu unda muammolarni hal qilish va qayta urinib ko‘rish ishtiyoqini kuchaytiradi.') WHERE id = '80068b19-aaa1-4996-ba9d-5b3777ebce0c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Musiqa va ritm: Farzandingiz endi turli ritmlarga turlicha harakatlar bilan javob beradi. Tez musiqa yangraganda faolroq harakat qiladi, sokin musiqa paytida esa tebranadi. U bilan birga "ritmni ushlash" o‘yinlarini o‘ynang — qarsak chaling, oyoqlaringizni polga uring. Bu uning eshitish qobiliyatini ham, tana harakatlari muvofiqlashuvini ham nihoyatda yaxshi rivojlantiradi.') WHERE id = '83fcfed7-5b83-4a68-8d79-7654a496f70e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "Mening stakanim". Bola ochiq stakandan suvni deyarli to‘kmasdan ichishga yaqin. Unga bolalar o‘lchamidagi, ag‘darilmaydigan (tagi og‘ir) plastik stakanlar bering. Suvni mustaqil ichishi uning jag‘ mushaklarini nutqqa tayyorlaydi va mustaqillik tuyg‘usini rag‘batlantiradi.') WHERE id = 'cdcb59ac-ce34-4644-9101-dd165efadbd4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men" va "Siz" o‘rtasidagi farqni anglash. Bola ko‘zguda o‘zini ko‘rganida endi unga "boshqa bola" sifatida emas, aynan o‘zi sifatida munosabat bildiradi. Burniga ozgina rang surtib, uni ko‘zguga qaratsangiz, u o‘z burnidagi dog‘ni artishga harakat qiladi. Bu uning o‘zini anglash qobiliyati (self-awareness) rivojlanayotganini ko‘rsatuvchi eng muhim testdir.') WHERE id = 'e44171a6-fe71-458b-9f01-6422077e41b3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hamkorlik": Bola endi sizga biror narsa olib kelishdan, oshxonada yoningizda turib "yordam berishdan" zavqlanadi. Unga kichik va xavfsiz vazifalar bering: "Bu qog‘ozni axlat qutisiga tashlay olasizmi?". U sizga yordam berayotganini his qilganida, o‘zini yanada muhim va qadrli inson deb biladi.') WHERE id = 'd9f30f7c-bdc1-4054-b9fc-312496a93a19';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: Bola endi divandan polga mustaqil tushishni (orqasi bilan sirg‘alib) o‘rganishi mumkin. Unga buni qanday xavfsiz bajarish kerakligini ko‘rsating. Baland joydan mustaqil tushishni o‘rganishi tanasini boshqarish va xavflarni tahlil qilish qobiliyatini oshiradi. Har doim yaqinida turib, uni ehtiyot qiling.') WHERE id = '594432bd-57c7-413f-839d-cbac2143ecbe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy inqirozlar va "Tantrum"lar. Bola hamma narsani o‘zi qilishni xohlab, uddalay olmaganida birdan jahli chiqishi mumkin. Bu uning istaklari bilan jismoniy imkoniyatlari hali to‘liq mos kelmasligidan kelib chiqadigan zo‘riqishdir. Bunday paytlarda uni quchoqlang va xotirjamlik bilan "O‘yinchoqni tuzata olmaganingiz uchun jahlingiz chiqdi, tushunaman", deb uning hissiyotini nomlang.') WHERE id = '52ab2a35-efc6-4dfa-ae8e-dd8d45265cbf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "So‘zlarni takrorlash". Bola endi siz aytgan har bir so‘zdan keyin o‘z tilida nimadir aytishga harakat qiladi. Bu til o‘rganishning eng faol bosqichidir. Uning oldida sodda, qisqa va tushunarli gaplar tuzing. Siz uning eng asosiy nutq namunasidirsiz. Bugun u bilan sevimli ertagini o‘qing va rasmdagi yashirin tafsilotlarni birgalikda topishga harakat qiling.') WHERE id = '36237c33-88c9-45f0-bb2f-74a99cfea0e7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «bo‘lishish qiyinligi». Bu yoshda «meniki» tushunchasi juda kuchli bo‘ladi. Bola o‘yinchog‘ini boshqa bolaga berishni istamasa, bu xudbinlik emas, balki rivojlanish bosqichidir. Uni bo‘lishishga majburlamang, buning o‘rniga «navbat bilan o‘ynash» qoidasini amalda ko‘rsating. Vaqt o‘tishi bilan u bu ijtimoiy qoidani o‘zlashtiradi.') WHERE id = '634d745d-5157-4467-b6ab-326f97a6818e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda «anjomlardan foydalanish». Bola endi bolalar sanchqisini ovqatga (masalan, pishirilgan sabzi yoki kartoshkaga) sanchib, og‘ziga aniqroq olib bora oladi. Bu ko‘nikma nafaqat qo‘l va ko‘z muvofiqligini mustahkamlaydi, balki uning o‘zini mustaqil shaxs sifatida his qilishiga ham yordam beradi.') WHERE id = '3cb1db52-5d88-4edb-a3ab-0984a9450809';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Makonni o‘zlashtirish»: Bola endi tor joylardan o‘tishni, to‘siqlar tagidan emaklab yoki ustidan hatlab o‘tishni o‘rganmoqda. Uyda yostiqlar va qutilardan kichik «to‘siqlar yo‘lagi» yasang. Bu unga o‘z tanasining o‘lchamlarini anglashga (proprioseptiv sezgilarga) va harakatlarini rejalashtirishga yordam beradi.') WHERE id = '2b1c5f94-7b82-40ce-9f0d-d663053b5141';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bog‘liqlik: Bola endi sizga bo‘lgan mehrini yanada aniqroq imo-ishoralar bilan namoyon etadi — kutilmaganda yoningizga kelib, sizni quchoqlaydi yoki boshingizni silaydi. Siz ham unga xuddi shunday mehr bilan javob bering. Bu hissiy almashinuv uning o‘zini xavfsiz va qadrli his qilishi uchun eng muhim ozuqadir.') WHERE id = 'de41f735-eeb7-4ab7-ab3c-cfc2d80548ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '16-oyga qadam qo‘ymoqdamiz! Farzandingiz endi ongli ravishda «Dada», «Ona»dan tashqari 5-10 ta turli so‘zni ayta olishi mumkin. U so‘zlarni hali to‘liq va to‘g‘ri talaffuz qilmasa ham, ularning har biri muayyan ma’noga ega. Uning har bir urinishini qo‘llab-quvvatlang va chala aytgan so‘zini to‘liq gap bilan tasdiqlang. Masalan, u «Ma» desa, siz «Ha, bu mashina», deb javob bering.') WHERE id = 'd807a9a4-6329-44cd-97d5-dae1bf4a8ff6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikdagi yangi bosqich: Bola endi qo‘lidan ushlab turilganda zinadan tik turgan holda ko‘tarila oladi. Bu harakat uning son va tos mushaklarini mustahkamlaydi. Zinapoyada doimo uning yonida bo‘ling va unga yordam bering. Uydagi zinapoya kirishlarida xavfsizlik to‘siqlari (gate) yopiq ekaniga ishonch hosil qilishni unutmang.') WHERE id = '22600f5c-8f2a-4f8d-9f3c-76e5a5fcda2c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni shunchaki yig‘maydi, balki ularni rangiga qarab guruhlay boshlashi ham mumkin. Unga ikki xil rangdagi idish bering va bir xil rangdagi kubiklarni mos idishlarga solishni ko‘rsating. Bu o‘yin uning vizual idroki va mantiqiy tafakkurini jadal rivojlantiradi. Har bir to‘g‘ri tanlovida uni rag‘batlantiring.') WHERE id = 'c99fbd76-3509-452c-bb85-8931e45ac6e6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqil kiyinishga urinishlar aniqroq maqsadga yo‘nala boshlaydi. Bola paypog‘ini tortib yechishi yoki boshiga qalpog‘ini kiyishga urinishi mumkin. Unga bu "o‘ziga xizmat qilish" mashqlari uchun vaqt bering. Shoshirmasdan, biror ishni mustaqil bajarishiga imkon yaratish uning o‘ziga bo‘lgan ishonchini (self-esteem) har narsadan ko‘ra ko‘proq oshiradi.') WHERE id = '2ee741f0-6ac8-462c-a88b-0f41a8cfe7f1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "Xuddi rostdagidek" (Pretend play) o‘yinlar boshlanadi. Bola bo‘sh o‘yinchoq piyoladan suv ichayotgandek qilishi yoki qo‘g‘irchog‘ini "uxlatishi" mumkin. Bular uning abstrakt tafakkurining ilk belgilaridir. Uning o‘yinlariga qo‘shiling va yangi savollar bilan (masalan, "Ayiqning qorni ochdimi?") tasavvurini rag‘batlantiring.') WHERE id = 'b84b66d1-b1ba-4c15-8fdd-579e274e0daa';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy chaqqonlik: Bola endi turgan joyida sakrashga urinadi. Hozircha ikkala oyog‘i bir vaqtda yerdan uzilmasligi mumkin, ammo u tizzalarini bukib-yozib, bu harakatga taqlid qiladi. Bu yirik motorika mushaklari va muvozanat hissini mustahkamlash uchun ajoyib mashqdir. U bilan birga ritmik musiqa ostida raqsga tushing.') WHERE id = 'd53255ec-c9a7-49ab-9a79-7b2313a09598';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Savol-javob" bosqichi. Bola endi "Bu nima?" (yoki o‘z tilida shunga o‘xshash tovush) deb, buyumlarni ko‘rsatadi. Siz sabr bilan hamma narsaning nomini ayting: "Bu qizil mashina", "Bu katta daraxt". Uning qiziqishini javobsiz qoldirmaslik lug‘at boyligining faol oshishiga yordam beradi.') WHERE id = 'd7ddb1ff-3688-4df3-8111-1494d13b6470';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qalamni ushlash". Bola endi qalamni kafti bilan emas, barmoqlari bilan ushlashga yaqinlashadi. Qog‘ozga aniqroq doiralar yoki chiziqlar chizadi. Unga bolalar uchun xavfsiz, yo‘g‘on rangli qalamlar bering va "ijodkorlik" uchun ko‘proq imkoniyat yarating. Bu kelajakdagi yozish ko‘nikmalarining poydevoridir.') WHERE id = '785f6c05-389d-4b59-bf24-09d238f78a91';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Muvozanat va koordinatsiya: bola endi turgan joyida sakrashga urinadi. Hozircha ikkala oyog‘i bir vaqtda yerdan uzilmasligi mumkin, ammo tizzalarini bukib, yuqoriga intilishi uning yirik motorikasi rivojlanayotganidan dalolat beradi. U bilan birga ritmik musiqa ostida raqsga tushing. Bu ham zavqli, ham jismoniy jihatdan juda foydali mashqdir.') WHERE id = '47585bf0-21b2-4948-bcc0-cc0d44631bdd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanishda «Istak va imkoniyat» ziddiyati. Bola biror ishni qilishni xohlab, uddalay olmasa, qichqirishi yoki jahli chiqishi mumkin. Bunday paytlarda xotirjam bo‘ling va uning hislarini ifodalab bering: «Kublar qulab tushgani uchun jahling chiqdi, tushunaman». Sizning bunday tushunishingiz unga his-tuyg‘ularini boshqarishni va qiyinchiliklar qarshisida tushkunlikka tushmaslikni o‘rgatadi.') WHERE id = 'a0a20bce-4839-4117-9368-c41ef5150778';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi tana a’zolarini (qo‘l, oyoq, qorin) shunchaki ko‘rsatibgina qolmay, ularning nomlarini aytishga ham urinadi. Uni kiyintirayotganda «Qorning qani?» deb so‘rang va javob berishi uchun unga vaqt bering. Bu uning o‘z tanasi tuzilishini anglab yetishi va faol lug‘at boyligini oshirishi uchun ajoyib mashqdir.') WHERE id = '9f429553-7b9f-4533-9a8c-fa277c16a3ea';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqillikka intilish kiyinishda ham namoyon bo‘ladi. Bola paypog‘ini tortib yechishi yoki bosh kiyimini kiyishga urinishi mumkin. Uning o‘ziga o‘zi xizmat qilishga qaratilgan bunday urinishlariga to‘sqinlik qilmang. Shoshirmasdan, biror ishni o‘zi uddalashi uchun imkon yaratish uning o‘ziga bo‘lgan ishonchini (self-esteem) har narsadan ko‘ra ko‘proq oshiradi.') WHERE id = 'eb7b56da-4f69-416f-ae1f-039fef91ef94';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «So‘z birikmalari»ning ilk belgilari: bola endi ikkita so‘zni birga ayta oladi (masalan, «Dada, keling» yoki «Suv ber»). Agar u hali so‘zlarni birlashtirmayotgan bo‘lsa, unga namuna ko‘rsating. U «To‘p» desa, siz «Ha, katta to‘p» deb gapni to‘ldiring. Bu uning miyasida grammatik tuzilmalar shakllanishiga yordam beradi.') WHERE id = '6753f0e0-f84e-40f2-a42e-a2fc56030ffe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Kitob sahifalari». Bola endi qalin karton sahifalarni birma-bir varaqlashni yaxshiroq uddalaydi. Unga interaktiv, paypaslab his qilish (touch-and-feel) elementlari bo‘lgan kitoblarni taklif qiling. Sahifani o‘zi varaqlashi unda mustaqillik hissini shakllantiradi, shuningdek, barmoqlarining mayda mushaklarini yozishga tayyorlaydi.') WHERE id = 'ed122971-473f-43f3-a24c-a44303a6f746';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi oddiy ko‘rsatmalarni bajarishdan zavqlanadi. "Iltimos, to‘pni menga olib kel" yoki "Bosh kiyimingni ol" desangiz, u buni bajara oladi. Bu uning retseptiv tili (tushunish qobiliyati) qanchalik rivojlanganini ko‘rsatadi. Unga kichik va yoqimli vazifalar berib, ham nutqini, ham mas’uliyat hissini rivojlantiring.') WHERE id = '44a68c23-5478-40d4-a83c-2dc9f09d429d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Meniki!" tushunchasi yanada kuchayadi. Bola sevimli o‘yinchog‘ini boshqasiga berishni istamasa, qat’iy turib olishi mumkin. Bu uning shaxsiy chegaralarini anglay boshlaganidan dalolat beradi. Uni bo‘lishishga majburlamang, buning o‘rniga o‘yinchoqlardan navbat bilan foydalanishni ("hozir sening navbating, keyin dadangniki") ko‘rsatib, unda ijtimoiy adolat hissini shakllantiring.') WHERE id = '3dc015ff-56bb-4a43-b76e-ffb3ffd6a8c8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorika mahorati: Bola endi konstruktor bloklarini (kublarni) shunchaki ustma-ust taxlamaydi, balki ularni yonma-yon terib, "poyezd" yoki "yo‘l" yasashga harakat qiladi. Bu uning fazoviy idroki yanada murakkab bosqichga o‘tayotganini ko‘rsatadi. Unga turli shakldagi konstruktorlarni berib, ijodkorligini rag‘batlantiring.') WHERE id = '05f48dd1-b441-4a53-83ad-213693a97b1c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "Tanlab yeyish" davri. Bola to‘satdan ayrim taomlarni yeyishdan bosh tortishi mumkin. Bu uning ta’m retseptorlari rivojlanayotgani va o‘z xohish-irodasini namoyon etayotganidan dalolat beradi. Uni majburlamang, ammo rad etgan mahsulotini bir necha kundan keyin boshqa shaklda (masalan, pyure emas, bo‘lak qilib) yana taklif qiling. Dasturxon atrofida ijobiy muhitni saqlang.') WHERE id = '01373d24-e28a-437e-998d-4ae78f2851c2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi qog‘ozga "chizib-yozayotganda" kengroq harakatlar qiladi. U qalamni ishonchliroq ushlaydi va ba’zan ranglarni farqlashga urinadi. Unga bolalar uchun xavfsiz bo‘lgan yo‘g‘on rangli qalamlar va katta rasm qog‘ozlarini bering. Uning bu ilk "san’at asarlari" ham qo‘l-ko‘z muvofiqlashuvi, ham o‘zini ifodalashi uchun beqiyos ahamiyatga ega.') WHERE id = '10f5c993-c3c9-44f8-a870-3ed80a4cfbed';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvordagi "Taqlid" endi kundalik ishlarda ham namoyon bo‘ladi. Siz uyni tozalayotganingizda, u ham nimanidir artishni, siz ovqat tayyorlayotganingizda esa u ham aralashtirishni xohlaydi. Unga kichik chang artadigan latta yoki o‘yinchoq supurgi bering. Bu bolaning o‘zini oilaning kerakli a’zosi sifatida his qilishiga va foydali ko‘nikmalarni egallashiga yordam beradi.') WHERE id = 'd75c2f77-0a11-4bee-830a-88006d025c3c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "qoshiq-sanchqidan foydalanish". Bola endi bolalar sanchqisini ovqatga (masalan, yumshoq pishirilgan sabzavotga) sanchib, og‘ziga aniqroq olib bora oladi. Bu ko‘nikma nafaqat qo‘l va ko‘z muvofiqligini mustahkamlaydi, balki unga o‘zini mustaqil shaxs sifatida his qilishga ham yordam beradi. Stol biroz iflos bo‘lsa ham, unga bu imkoniyatni bering.') WHERE id = '28156e7f-7e18-4b94-927c-a444469bee3e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy xotira" va izlash: Bola bir necha soat oldin qayerga qo‘ygan o‘yinchog‘ingizni eslab, uni topa oladi. U bilan "yo‘qolgan buyumni top" o‘yinini o‘ynang. Bu uning ko‘rish xotirasini ham, diqqatini jamlash qobiliyatini ham rivojlantiradi. Topilgan har bir buyum uning uchun kichik bir "kashfiyot" g‘alabasidir.') WHERE id = '15ff0052-98cf-4d44-8277-9931b5bbd7bd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "empatiya" kuchayadi. Bola boshqa birovning (yoki o‘yinchog‘ining) "og‘riyotganini" ko‘rsa, uni quchoqlashi yoki silashi mumkin. Bu uning boshqalarning his-tuyg‘ularini tushuna boshlaganini ko‘rsatadi. Uning bu tuyg‘ularini "Ha, do‘sting hozir biroz xafa" kabi jumlalar bilan ifodalab, hissiy intellektini rivojlantirishga ko‘maklashing.') WHERE id = '6c93684c-6781-4a11-bb15-1580d5f66d36';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlik: Bola endi turgan joyida aylanishni va orqaga qadam tashlashni o‘rganmoqda. Bu muvozanatni saqlashga qaratilgan murakkab mashqdir. Unga keng va to‘siqlarsiz joyda yangi ko‘nikmalarini sinab ko‘rish imkonini yarating. Tanasini boshqarish qobiliyati oshgani sari yiqilishdan qo‘rqishi kamayadi va harakatlanish doirasi kengayadi.') WHERE id = '33b5778f-3fe2-440a-8f22-62f63b5a956d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "Go‘yoki shunday" (Pretend play) o‘yinlari murakkablashadi. Bola o‘yinchoq mashinasini haydab, "vrr-vrr" deb ovoz chiqarishi yoki bo‘sh likopchadan "ovqat yeyayotgandek" qilishi mumkin. Bu o‘yinlarda unga qo‘shiling va yangi savollar bilan tasavvurini rag‘batlantiring. Bu uning ijodkorligini ham, mantiqiy bog‘lanishlarni tushunishini ham mustahkamlaydi.') WHERE id = 'd2fca029-5edb-4176-b69f-5a506afd4a61';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Iroda va chegaralar: Bola endi "Mumkin emas" degan so‘zga munosabat bildiradi, ammo ba’zan ataylab o‘sha ishni qilib, sizga qaraydi. Shu tariqa u sabringizni va qoidalar o‘zgarmasligini sinab ko‘radi. Xotirjam, ammo qat’iyatli bo‘ling. Qoidalarning izchilligi bolada xavfsizlik va tartib hissini shakllantiradi.') WHERE id = '3e76b053-c97c-4476-b999-951be493bb64';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurni rivojlantirish: "Ovqat pishirish" o‘yini. Bola o‘yinchoq idishlari bilan nimanidir "pishirayotgandek" qilishi mumkin. Uning o‘yiniga qo‘shiling: "Menga ham ozgina ovqat berasanmi?". Bu uning kundalik hayotdagi odatlarni qanchalik sinchkovlik bilan kuzatayotganini va tasavvuri qanday rivojlanayotganini ko‘rsatadi.') WHERE id = '0303ebf1-df3e-4e81-bd4e-6f1dea97c188';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: Bola endi pastroq zinapoyalar yoki divan chetiga mustaqil chiqishga urinadi. Balandlikni idrok etishi rivojlanayotgan bo‘lsa-da, u hali xavflarni to‘liq anglamaydi. Doimo yaqinida bo‘lib, uni ehtiyot qiling va xavfsiz tushish usullarini (masalan, orqasi bilan tushishni) ko‘rsating.') WHERE id = '4a36804a-6409-441e-bfa1-5d47aa7ddf64';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hayvonlar va ularning tovushlarini farqlash". Bola endi rasmda ko‘rgan sigir bilan mushukni bir-biridan ajrata oladi va so‘ramasangiz ham ularning ovoziga taqlid qila oladi. Kitob o‘qiyotganda "Qani, bu yerda mushuk qayerda?" deb so‘raganingizda, uni barmog‘i bilan ko‘rsatishi bolaning ko‘rish xotirasi va diqqati qanchalik kuchayganini bildiradi.') WHERE id = '48266b98-24f4-486a-8c86-5edb343f6455';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar va "Yo‘q". Bola hamma narsani o‘zi qilishni xohlab, uddalay olmaganida birdan jahli chiqishi mumkin. Shunday paytlarda uni quchoqlang va xotirjamlik bilan: "Poyabzalingni kiya olmaganing uchun jahling chiqdi, tushunaman", deb uning hissiyotini nomlang. Sizning bunday xotirjamligingiz unga o‘z hissiyotlarini boshqarishni o‘rgatadigan eng yaxshi namunadir.') WHERE id = 'bd6e2ef7-be9f-49e8-9f5a-73c5aca2c6c7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi o‘z didini namoyon qilmoqda. U kiymoqchi bo‘lgan ko‘ylagini yoki o‘qitmoqchi bo‘lgan kitobini qat’iy tanlashi mumkin. Bu davrda unga "cheklangan tanlov" imkonini bering: "Bugun qizil ko‘ylakni kiymoqchisanmi yoki ko‘kini?". Bu bolada vaziyatni boshqarish hissini shakllantiradi va kelajakdagi o‘jarlik xurujlarining oldini oladi.') WHERE id = 'e2f29ee5-abb0-4ec5-8bfb-7fca6b238c4f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Yugurish mahorati". Bola endi yugurayotganda muvozanatini yaxshiroq saqlaydi va birdan to‘xtay oladi. Bu uning mushak kuchi hamda miya va mushaklar o‘rtasidagi muvofiqlashuv qanchalik takomillashganini ko‘rsatadi. U energiyasini chiqarishi uchun park yoki hovlida to‘siqlarsiz yugurish joylarini topib, sharoit yarating.') WHERE id = '85cc1293-16e0-49cd-904b-171804ae1853';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz endi buyumlarni shunchaki yig‘maydi, balki ularni rangiga qarab guruhlashga ham harakat qiladi. Unga ikki xil rangdagi idish bering va bir xil rangdagi o‘yinchoqlarni mos idishlarga solishni ko‘rsating. Bu o‘yin uning ko‘rish orqali idrok etishi va mantiqiy fikrlashini jadal rivojlantiradi. Har bir to‘g‘ri tanlovida uni rag‘batlantiring, shunda o‘rganishga bo‘lgan qiziqishi ortadi.') WHERE id = '7aebe8cd-a4e5-44f9-8f57-fc363b89129a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Orqaga qadam". Farzandingiz endi orqaga qarab yurishni kashf etdi. Bu murakkab muvozanat mashqi bo‘lib, uning tana harakatlarini muvofiqlashtirish qobiliyati qay darajada rivojlanganini ko‘rsatadi. Unga to‘siqlarsiz va yumshoq joyda bu yangi ko‘nikmasini sinab ko‘rish uchun sharoit yarating. Tanasini boshqarish qobiliyati oshgani sayin, o‘ziga bo‘lgan ishonchi ham shunchalik mustahkamlanadi.') WHERE id = '23d55f43-944e-41ff-a1f0-31e749c5ea5d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Savol va qiziqish". Farzandingiz endi "Bu nima?" (yoki o‘z tilida shunga o‘xshash tovush) deb buyumlarni ko‘rsatadi. Siz sabr bilan hamma narsaning nomini ayting: "Bu qizil mashina", "Bu katta daraxt". Uning qiziqishini javobsiz qoldirmaslik lug‘at boyligining ham passiv, ham faol ravishda kengayishiga yordam beradi.') WHERE id = '741cbef2-ffcd-4b10-9cdf-8e41aa164e28';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hazillar". Farzandingiz ataylab o‘yinchoqni sizga uzatib, darhol qaytarib oladimi va bundan kuladimi? Bu uning hazil tuyg‘usi va ijtimoiy o‘yin ko‘nikmalari shakllanayotganini ko‘rsatadi. Uning bu "o‘yiniga" zavq bilan qo‘shiling. Birgalikda kulish orangizdagi hissiy rishtani mustahkamlaydi va unda o‘ziga nisbatan ijobiy ishonchni shakllantiradi.') WHERE id = '5a726b9c-27a1-4456-85ed-e5c0d76d2484';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Piramida va halqalar". Farzandingiz endi halqalarni kattadan kichikka (yoki aksincha) terishda ancha mohir. Bu harakat uning o‘lcham tushunchasini (katta-kichik) hamda ko‘z va qo‘l harakatlari muvofiqligini rivojlantiradi. Halqalarni terayotganda ranglarning nomini ham aytib boring.') WHERE id = '51378f6a-c746-490d-b2e3-d4da3d093685';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim ichaman". Farzandingiz endi ochiq stakandan suvni deyarli to‘kmasdan ichishni o‘rganib qoldi. Unga bolalar uchun mos o‘lchamdagi, ag‘darilib ketmaydigan (tagi og‘ir) plastik stakanlar bering. Suvni mustaqil ichishi uning lab va til mushaklarini nutqqa tayyorlaydi hamda mustaqillik tuyg‘usini rag‘batlantiradi.') WHERE id = '44c70121-397f-4987-8f6a-6aae583c01e5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "So‘z birikmalari". Bola endi ikki so‘zni birlashtirib, sodda gaplar tuzadi: "Dada, keling", "Olma ber". Agar u hali so‘zlarni birlashtirmayotgan bo‘lsa, aytgan bitta so‘zini kengaytirib takrorlang: "Ha, sen olma xohlaysanmi? Mana, senga mazali olma". Bu uning miyasida grammatik tuzilmalar mustahkamlanishiga yordam beradi.') WHERE id = '3ec1877f-e8dc-4ba3-893d-678bde1927b1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Pazl" davri. Bola endi 2-3 bo‘lakli oddiy pazllarni yig‘ishni yoki shakllarni mos teshiklarga joylashtirishni o‘rganadi. Bu o‘yin uning ko‘rish orqali idrok etishi va muammolarni hal qilish qobiliyatini jadal rivojlantiradi. Uddalay olmasa, xotirjamlik bilan yordam bering va uni ruhlantiring.') WHERE id = 'b4b1a4bc-e49d-4497-b688-464c24f79875';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Parallel o‘yin". Boshqa bolalar bilan birga bo‘lganida, bolangiz ular bilan emas, balki ularning yonida o‘zi alohida o‘ynaydi. Bu 17 oylik davr uchun mutlaqo tabiiy holat. U boshqa bolalarni kuzatib, ko‘p narsani o‘rganadi. Ijtimoiy muhitga moslashishi uchun uni tengdoshlari yoniga olib borishda davom eting.') WHERE id = '0d8b6018-4d34-41fe-ad70-9143e9c2615f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim yuvinaman". Cho‘milayotganda yoki qo‘llarini yuvayotganda bola sovun yoki mochalkani olib, o‘zini yuvishga urinadi. Uning gigiyena odatlariga bo‘lgan qiziqishini qo‘llab-quvvatlang. O‘zini "tozalashi" tana a’zolarini yaxshiroq tanishi va mustaqillik hissini rivojlantirishiga yordam beradi.') WHERE id = '3c2bb527-c368-4b69-94c1-76665087b2b9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xotiraning kuchayishi: "Yo‘qolgan buyumlar". Bola siz yashirgan o‘yinchoqni topish uchun murakkabroq usullardan foydalanadi – yopqichni ko‘taradi, qutining ichiga qaraydi. Bu unda "obyektning doimiyligi" tushunchasi to‘liq shakllanganini ko‘rsatadi. Uyda u bilan kichik "xazina izlash" o‘yinlarini o‘ynab, diqqatini mashq qildiring.') WHERE id = 'd0afa5e2-c732-43e9-af9d-2f3d19c36c4e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvur va "Uy ishlari". Bola o‘yinchoq telefonda "gaplashadi" yoki o‘yinchoq supurgi bilan polni supuradi. U sizning har bir harakatingizni takrorlaydi. Bu taqlid uning dunyoni o‘rganish usulidir. Unga o‘zining kichik "ish qurollari"ni berib, o‘zini muhim his qilishi uchun sharoit yarating.') WHERE id = '9dfb3516-1999-4989-989e-9e6fdb3fb9e5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: "Tirmashib chiqish mahorati". Bola endi zinadan mustaqil ravishda chiqishga (hozircha emaklab yoki qo‘lidan ushlab turilganda) juda intiladi. Balandlikni idrok etishi rivojlangan sari, unga pastga tushishni ham o‘rgatish kerak. Orqasi bilan tushish xavfsizroq ekanini unga doimo amalda ko‘rsating.') WHERE id = '15095e09-193b-4e26-bc2e-4f81de7c413d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 500 kunni qarshi oldik! Farzandingiz endi go‘daklik davridan butunlay chiqib, o‘z xarakteri va irodasiga ega kichkina bolaga aylandi. Bugun u bilan o‘zi yoqtiradigan mashg‘ulotga (masalan, rasm chizish yoki bog‘da sayr qilishga) vaqt ajrating. Sizning sabr-toqatingiz va mehringiz uni shu bosqichga yetaklagan eng katta kuchdir. Barakalla, Ona!') WHERE id = '3427ae53-cf26-4b28-928a-b9787dc9cf32';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "Men" tushunchasini xatti-harakatlari bilan namoyon qilmoqda. Kiyimlarini o‘zi tanlash yoki ovqatni mustaqil yeyish istagi — mustaqillik belgisidir. Unga shunday imkoniyat bering: "Qaysi ko‘ylakni kiyishni xohlaysan?". Kichik tanlovlar berish uning qaror qabul qilish qobiliyatini rivojlantiradi va qaysarlik xurujlarini kamaytiradi.') WHERE id = '1f190c82-9146-4726-b79a-d4e22c530f6d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "To‘siqlarni yengib o‘tish". Bola endi yerdagi o‘yinchoqlar va yostiqlar ustidan hatlab yoki ularni aylanib o‘tishni o‘rganmoqda. Bu murakkab fazoviy idrokdir. Uyda xavfsiz to‘siqlar yaratib, uning muvozanatni saqlash va tanasini boshqarish qobiliyatlarini mashq qildiring.') WHERE id = '0762347b-3e67-4f92-a1cc-28fc730be874';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "So‘zlarning ma’nosi". Bola endi shunchaki takrorlamaydi, balki so‘zlarni muayyan vaziyatlarga mos ravishda ishlatadi. Masalan, siz oyoq kiyimingizni kiyganingizda, u "Ay-da" (tashqariga) deyishi mumkin. Uning bunday murojaatlarini kengaytiring: "Ha, hozir oyoq kiyimimizni kiyib, bog‘ga boramiz". Bu uning miyasida voqealar va so‘zlar o‘rtasidagi bog‘liqlikni mustahkamlaydi.') WHERE id = '32725b0c-885a-420b-8b00-82ddb5c437d8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Dizayn va qurish". Bola endi kublarni shunchaki ustma-ust taxlamaydi, balki ulardan "poyezd" yoki "devor" kabi gorizontal shakllar yasashga urinadi. Bu uning fazoviy tafakkuri yangi bosqichga o‘tganini ko‘rsatadi. Unga turli shakldagi konstruktorlarni berib, tasavvurini qo‘llab-quvvatlang.') WHERE id = 'd22bf585-b849-4796-8341-19d360ee9434';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni shunchaki yig‘maydi, balki ularni rangiga qarab guruhlashga ham urinadi. Unga ikki xil rangdagi idish bering va bir xil rangdagi o‘yinchoqlarni mos idishlarga solishni ko‘rsating. Bu o‘yin uning vizual idroki va mantiqiy tafakkurini jadal rivojlantiradi. Har bir to‘g‘ri tanlovida uni rag‘batlantiring.') WHERE id = 'be0ade15-5544-47ec-9b0f-c9482045c9e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Orqaga qadam". Bola endi orqaga yurishni o‘rganib oldi. Bu murakkab muvozanat mashqi bo‘lib, uning tana koordinatsiyasi qay darajada rivojlanganini ko‘rsatadi. Unga to‘siqlarsiz va yumshoq joyda bu yangi ko‘nikmasini sinab ko‘rish uchun sharoit yarating. Tanasini boshqarish qobiliyati oshgani sari o‘ziga bo‘lgan ishonchi ham mustahkamlanadi.') WHERE id = '4090fd14-b660-4e63-9f79-fd22a575576f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Savol va qiziqish". Bola endi "Bu nima?" deb (yoki o‘z tilida shunga o‘xshash tovush chiqarib) buyumlarni ko‘rsatadi. Siz sabr bilan hamma narsaning nomini ayting: "Bu qizil mashina", "Bu katta daraxt". Uning qiziqishini javobsiz qoldirmaslik lug‘at boyligining ham passiv, ham faol ravishda kengayishiga yordam beradi.') WHERE id = '4d85c160-6a89-4bf6-8f45-da46fe9e61c0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hazillar". Bola o‘yinchoqni ataylab sizga berib, darhol qaytarib oladimi va bundan kuladimi? Bu unda hazil tuyg‘usi va ijtimoiy ta’sir ko‘rsatish qobiliyati shakllanayotganini bildiradi. Uning bu "o‘yiniga" zavq bilan qo‘shiling. Birga kulish orangizdagi hissiy rishtani mustahkamlaydi va unda sog‘lom o‘ziga ishonchni shakllantiradi.') WHERE id = '843dc844-89cf-4311-8b84-968a8aaa47d1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Piramida va halqalar". Bola endi halqalarni kattadan kichikka (yoki aksincha) terishda ancha mohir. Bu harakat uning o‘lcham haqidagi tushunchasini (katta-kichik) hamda qo‘l-ko‘z muvofiqligini rivojlantiradi. Halqalarni terayotganda ularning ranglarini ham aytib boring.') WHERE id = 'da06e49e-5a35-41bf-9d03-b1f30db1e3f3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim ichaman". Bola endi ochiq stakandan suvni deyarli to‘kmasdan ichishga juda yaqin. Unga bolalar uchun mo‘ljallangan, ag‘darilib ketmaydigan (tagi og‘ir) plastik stakanlar bering. Suvni mustaqil ichishi uning lab va til mushaklarini nutqqa tayyorlaydi hamda mustaqillik tuyg‘usini rag‘batlantiradi.') WHERE id = '7672591f-bef4-411a-94a3-365d4ae118a3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Empatiya" belgilari. Bola sizning xafa ekaningizni yoki biror joyingizni urib olganingizni ko‘rsa, yoningizga kelib sizga tegishi, hatto sizni quchoqlashi mumkin. Bu uning boshqalarning his-tuyg‘ularini tushuna boshlaganini ko‘rsatadi. Uning bu tuyg‘ularini "Meni qo‘llab-quvvatlaganing uchun katta rahmat" deb ifodalang. Bu hissiy intellektning asosidir.') WHERE id = '3a9d7d72-ab6c-4777-b054-a56b8986ee74';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tozalik". Bola sizga taqlid qilib qo‘llarini yuvishga, yuzini artishga yoki tishlarini tozalashga (hozircha tish cho‘tkasini shunchaki chaynab) intiladi. Uning mustaqil bo‘lish istagini so‘ndirmang. Qo‘li yetishi uchun oyoqosti kursichasini (step stool) qo‘yib bering va harakatlaringizni takrorlashiga imkon bering. Bu unda o‘ziga xizmat qilish ko‘nikmalarini shakllantiradi.') WHERE id = '090f40d7-6abc-46b1-8914-c34325dbcaa0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xotira va "Fazoviy xotira". Bola endi o‘yinchog‘i qayerga yashirilganini uzoq vaqt eslab qoladi. U bilan uyda kichik "xazina qidirish" o‘yinlarini o‘ynang. Biror buyumni yopqich ostiga yashiring va uni qanday topishini kuzating. Bu o‘yinlar diqqatni jamlashni ham, muammoni hal qilish yo‘lini topishni ham o‘rgatadi.') WHERE id = '0bfe8ad5-dcd4-46e4-af49-e5c2a87c763e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "Go‘yoki" o‘yini (Pretend play). Bola endi bo‘sh piyoladan "choy ichayotgandek" qilishi yoki qo‘g‘irchog‘iga "ovqat berishi" mumkin. Bu o‘yinlarda unga qo‘shiling. Bunday o‘yinlar bolaning ijodkorligini ham, kundalik hayotdagi odatlarni tushunishini ham tezroq rivojlantiradi.') WHERE id = '9a097c94-eb06-4b23-b839-a6859f4ee3f2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: "Tirmashib chiqish va tushish". Bola endi past zina yoki divan chetiga mustaqil ravishda tirmashib chiqishga harakat qiladi. Balandlikni idrok etishi rivojlanayotgan bo‘lsa-da, u xavflarni hali to‘liq anglamaydi. Unga har doim orqasi bilan tushish xavfsizroq ekanini ko‘rsating. Sizning nazoratingiz ostida bunday mashqlarni bajarishi uning tanasini boshqarish qobiliyatini mustahkamlaydi.') WHERE id = '0f9b9189-8ffa-4276-919f-031f8673dbe8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar va "Yo‘q". Bola endi "Mumkin emas" degan so‘zga munosabat bildiradi, ammo ba’zan ataylab o‘sha harakatni bajarib, sizga qaraydi. Shu tariqa u sabringizni va qoidalarning o‘zgarmasligini sinab ko‘radi. Xotirjam, ammo qat’iyatli bo‘ling. Qoidalarning doimiyligi bolada xavfsizlik va tartib hissini shakllantiradi.') WHERE id = '3fbc8bef-6814-4548-b448-0883b201e56d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurni rivojlantirish: "Ovqat pishirish" o‘yini. Bola o‘yinchoq idishlarda nimadir "pishirayotgandek" o‘ynashi mumkin. Siz ham uning o‘yiniga qo‘shiling: "Menga ham ozgina ovqat berasanmi?". Bu uning kundalik hayotdagi odatlarni qanchalik sinchiklab kuzatayotganini va tasavvuri qanday rivojlanayotganini ko‘rsatadi.') WHERE id = '54cd9ab8-e1d5-4a0e-ab3a-58d28bf66df0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: Bola endi past pog‘onalarga yoki divan chetiga mustaqil chiqishga urinadi. Balandlikni idrok etishi rivojlanayotgan bo‘lsa-da, u xavflarni hali to‘liq anglamaydi. Doimo yaqinida bo‘lib, uni ehtiyotlang va xavfsiz tushish usullarini (masalan, orqasi bilan) ko‘rsating.') WHERE id = 'b93116ed-f9b5-4701-8c1f-2fc127b8352c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hayvonlar va ularning tovushlarini farqlash". Bola endi rasmda ko‘rgan sigir bilan mushukni bir-biridan ajratadi va so‘ramasangiz ham ularning ovoziga taqlid qila oladi. Kitob o‘qiyotganda "Bu yerda mushuk qani?" deb so‘raganingizda uni barmog‘i bilan ko‘rsatishi ko‘rish xotirasi mustahkamlanayotganidan dalolat beradi.') WHERE id = 'dcd3b6fa-3aa2-4a2f-98c6-4125a36e33d1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar va "Yo‘q". Bola hamma narsani o‘zi qilishni xohlab, uddalay olmaganida to‘satdan jahli chiqishi mumkin. Bunday paytda uni quchoqlab, xotirjam ohangda "Poyabzalingni kiya olmaganing uchun jahling chiqdi, sizni tushunaman" deb uning hissiyotini nomlashingiz mumkin. Sizning bunday xotirjamligingiz unga o‘z hissiyotlarini boshqarishni o‘rgatadigan eng yaxshi namunadir.') WHERE id = '352efc53-2735-4313-8ef5-1cd93238bca8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '18-oyga, ya’ni bir yarim yoshga tomon ilk qadamni tashlayapmiz! Bola endi yugurayotganda muvozanatini yaxshiroq saqlaydi va istagan paytida to‘xtay oladi. Bu ham jismoniy kuch, ham miya va mushaklar muvofiqlashuvidagi katta rivojlanishdir. U energiyasini sog‘lom tarzda sarflashi uchun park yoki hovlida to‘siqlarsiz yugurish mumkin bo‘lgan joylarni toping.') WHERE id = '20741f1b-1447-4efb-94f4-6f3a4844a16e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "So‘z birikmalari" tez rivojlanmoqda. Bola endi ikkita so‘zni yonma-yon qo‘llab, murakkab istaklarini bildiradi: "Dada, keling", "Olma ber", "To‘p qani?". Agar u hali so‘zlarni birlashtirmayotgan bo‘lsa, xavotir olmang; siz u aytgan alohida so‘zlarni gapga aylantirib javob bering: "Ha, to‘pni xohlaysanmi? Mana, sening qizil to‘ping".') WHERE id = '81c4a684-a911-49c4-a9d7-1699f6fa7902';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "pazl" (boshqotirma) davri. Bola endi 2-3 qismli oddiy pazllarni yig‘ishni yoki geometrik shakllarni mos bo‘shliqlarga joylashtirishni o‘rganmoqda. Bu o‘yin uning vizual idrokini ham, muammolarni hal qilish qobiliyatini ham yuqori darajada rivojlantiradi. Eplay olmasa, unga xotirjamlik bilan yordam beruvchi ishora bering va ruhlantiring.') WHERE id = 'f29daf62-95a9-439b-9639-5474aad5c6b0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Parallel o‘yin" hali ham ustunlik qiladi. Boshqa bolalar bilan birga bo‘lganida, bolangiz ular bilan emas, balki ularning yonida o‘zi mustaqil o‘ynaydi. Bu 18 oygacha bo‘lgan bolalar uchun mutlaqo tabiiy holat. U boshqa bolalarni kuzatish orqali ko‘p narsani o‘rganadi. Ijtimoiy muhitga moslashishi uchun uni tengdoshlari davrasiga olib borishda davom eting.') WHERE id = 'b30c9be9-ec87-4316-9f1a-0e4dee84bd75';
