UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Savol va qiziqish". Bola endi "Bu nima?" (yoki o‘z tilida shunga o‘xshash tovush) deb buyumlarni ko‘rsatadi. Siz sabr bilan har bir narsaning nomini ayting: "Bu qizil mashina", "Bu katta daraxt". Uning qiziqishini javobsiz qoldirmaslik so‘z boyligining ham passiv, ham faol ravishda oshishiga yordam beradi.') WHERE id = '428ddabc-76ae-4dd9-8955-566bc3b0021c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hazillar". Bola ataylab o‘yinchoqni sizga uzatib, darhol qaytarib oladimi va bundan kuladimi? Bu unda hazil tuyg‘usi va ijtimoiy o‘yin ko‘nikmasi shakllanayotganini ko‘rsatadi. Uning bu "o‘yiniga" zavq bilan qo‘shiling. Birgalikda kulish orangizdagi hissiy rishtani mustahkamlaydi va bolada ijobiy o‘ziga ishonchni shakllantiradi.') WHERE id = '6f7f5c96-a971-4edb-9629-1420d3e51d5d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Piramida va halqalar". Bola endi halqalarni kattasidan kichigiga (yoki aksincha) terishda ancha mohir bo‘lib qolgan. Bu harakat uning o‘lcham haqidagi tushunchasini (katta-kichik) hamda qo‘l-ko‘z muvofiqligini rivojlantiradi. Halqalarni terayotganda ranglarning nomini ham ovoz chiqarib ayting.') WHERE id = '90eaad7f-688e-4fd5-ac4b-58ae26fd12fd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim ichaman". Bola endi ochiq stakandan suvni deyarli to‘kmasdan ichishga juda yaqin. Unga bolalar uchun mo‘ljallangan, ag‘darilmaydigan (tagi og‘ir) plastik stakanlar bering. Suvni mustaqil ichishi uning lab va til mushaklarini nutqqa tayyorlaydi hamda mustaqillik hissini rag‘batlantiradi.') WHERE id = 'ee6a42af-cce1-4d37-af51-df5adf60a403';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurni rivojlantirish: "Ovqat pishirish" o‘yini. Bola o‘yinchoq idishlarda nimanidir "pishirayotgandek" qilishi mumkin. Siz ham uning o‘yiniga qo‘shiling: "Menga ham ozgina ovqat berasizmi?". Bu uning kundalik hayotdagi odatlarni qanchalik chuqur kuzatayotganini va tasavvuri qanday rivojlanayotganini ko‘rsatadi.') WHERE id = 'f1803978-8c6d-4ba6-919b-9d07f71e4f23';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: Bola endi past zinapoyalarga yoki divan chetiga mustaqil chiqishga urinadi. Balandlikni idrok etishi rivojlanayotgan bo‘lsa-da, u xavflarni hali to‘liq anglamaydi. Doimo yonida bo‘lib, uni ehtiyotlang va xavfsiz tushish usullarini (masalan, orqasi bilan tushishni) ko‘rsating.') WHERE id = '992522f4-e329-4100-a785-ed11e118cc9d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hayvonlar va ularning tovushlarini farqlash". Bola endi rasmda ko‘rgan sigir bilan mushukni bir-biridan ajratadi va so‘ramasangiz ham ularning tovushlariga taqlid qila oladi. Kitob o‘qiyotganda "Qani, bu yerda mushuk qayerda?" deb so‘raganingizda, uni barmog‘i bilan ko‘rsatishi ko‘rish xotirasi mustahkamlanayotganini bildiradi.') WHERE id = 'a6dfa03f-81ed-42c6-9520-9c6097e0b191';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar va "Yo‘q". Bola hamma narsani o‘zi qilishni xohlab, uddalay olmaganda to‘satdan jahli chiqishi mumkin. Shunday paytlarda uni quchoqlang va xotirjamlik bilan "Oyoq kiyimingni kiya olmaganing uchun jahling chiqdi, sizni tushunaman" deb, uning his-tuyg‘usini nomlang. Sizning bunday xotirjamligingiz unga his-tuyg‘ularini boshqarishni o‘rgatadigan eng yaxshi namunadir.') WHERE id = 'fe5d769a-36f6-497a-abae-90604ca433b9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi joyida sakrashga urinmoqda. Hozircha ikkala oyog‘i bir vaqtda yerdan uzilmasligi mumkin, ammo tizzalarini bukib, sakrashga hozirlanishi uning yirik motorikasi rivojlanayotganidan dalolat beradi. U bilan birga ritmik musiqa ostida raqsga tushing. Bu nafaqat qiziqarli, balki oyoq mushaklarini jismonan mustahkamlaydigan juda foydali mashqdir.') WHERE id = '11679c4b-f0ae-4e4b-8e36-e62ed51385bb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Meniki" so‘zining kashf etilishi. Bola endi o‘z buyumlarini taniydi va ularni "meniki" deb (yoki o‘z tilidagi biror ishora bilan) himoya qilishga harakat qiladi. Bu xudbinlik emas, balki uning shaxsiy chegaralarini anglay boshlaganidir. Unga o‘z buyumlariga egalik qilish imkonini bering — bu uning o‘ziga bo‘lgan ishonchi va egalik tushunchasini shakllantiradi.') WHERE id = '76f2d8e6-3dab-4534-8a50-e8454558158c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Saralash va mantiq". Bola endi buyumlarni nafaqat rangiga, balki o‘lchamiga ko‘ra ham (katta-kichik) farqlay boshlaydi. Unga turli o‘lchamdagi idishlarni bering va ularni bir-birining ichiga joylashini so‘rang. Bu uning kelajakdagi matematik tafakkurining eng dastlabki poydevoridir.') WHERE id = 'c34d1f9d-7805-4ebe-a5ef-2eba5d6e613a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqillik: "Men o‘zim kiyinaman". Bola endi shimini yuqoriga tortishga, paypog‘ini yechishga yoki kiyish oson bo‘lgan oyoq kiyimini oyog‘iga kiyishga urinadi. Bu jarayonda unga xalaqit bermang va shoshiltirmang. Biror ishni o‘zi uddalaganini ko‘rish uning uchun eng katta mukofotdir. Kichik yutuqlari uchun uni doimo maqtang.') WHERE id = 'e8325a98-332b-4719-b50a-32bc427f8a46';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Navbat kutish". Bola endi o‘yinchoq bilan o‘ynash uchun biroz kutish kerakligini tushunadi. "Hozir mening navbatim, keyin seniki" kabi o‘yinlar orqali unga sabr qilishni o‘rgating. Bu uning bog‘chaga yoki boshqa ijtimoiy muhitlarga moslashishi uchun eng muhim ko‘nikmalardan biridir.') WHERE id = 'fb3f5f38-3ad4-4db7-9933-796ef621c2db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "Qoshiqdan mustaqil foydalanish mahorati". Bola endi qoshiqni ovqat bilan to‘ldirib, uni deyarli to‘kmasdan og‘ziga olib borishni o‘rganmoqda. Unga yogurt yoki pyure kabi quyuq ovqatlar bilan mashq qilish osonroq. Stolning iflos bo‘lishidan qo‘rqmang; uning mustaqil ovqatlanishi ham qo‘l-ko‘z muvofiqligini, ham to‘yganini his qilish qobiliyatini rivojlantiradi.') WHERE id = 'eb358b29-c8ba-43ce-9ec4-901370abee63';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "O‘yinchoqlar bilan muloqot". Farzandingiz endi qo‘g‘irchog‘i yoki ayiqchasi bilan "gaplashadi", ularni "uxlatadi" yoki "tekshiradi". Bu uning hissiy intellekti rivojlanayotganini va kundalik odatlarni qanchalik chuqur o‘zlashtirayotganini ko‘rsatadi. Siz ham u bilan birga ushbu rolli o‘yinlarda qatnashing.') WHERE id = '966e6ab8-7afb-4514-ac61-ac17ed1b3363';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanish: "To‘p tepish". Farzandingiz endi tik turib, muvozanatini yo‘qotmasdan to‘pni tepishga urinadi. Bu murakkab muvofiqlashtirishni talab qiladigan harakatdir. U bilan uyda yoki hovlida yengil to‘p o‘ynang. To‘pni sizga uzatishini so‘rab, birgalikda o‘ynash ko‘nikmasini ham rivojlantiring.') WHERE id = '074c6e28-5574-4dba-9c17-b0a8532eb39d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "Nega?" bosqichining ilk belgilari. Farzandingiz hamma narsani barmog‘i bilan ko‘rsatib, "Bu?" deya sizning tushuntirishingizni kutadi. Siz har bir buyumning nomi va nima uchun ishlatilishini sodda jumlalar bilan tushuntiring. Sizning izohlaringiz uning ongida dunyo xaritasini shakllantiradi. Uning qiziqishini doimo qo‘llab-quvvatlang.') WHERE id = '8bf76af3-3dd5-49ef-bbdd-da6f06260256';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 550 kunni ortda qoldirdik! Farzandingiz endi rasman 1.5 yoshda. Bu davr bola rivojlanishidagi eng muhim va qiziqarli bosqichlardan biridir. U endi oddiy ko‘rsatmalarni to‘liq tushunadi, his-tuyg‘ularini aniq ifodalaydi va dunyoni zabt etishga tayyor kichik "tadqiqotchi"dir. Bu kunni u bilan birga eng sevimli o‘yinini o‘ynab nishonlang!') WHERE id = 'f706bcc8-1266-48d0-82ad-7920a5e14e37';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '19-oyga xush kelibsiz! Farzandingiz endi ko‘zguda o‘zini to‘liq taniydi va aksini "boshqa bola" emas, aynan o‘zi deb qabul qiladi. Bu uning o‘zini anglash (self-awareness) qobiliyati rivojlanishidagi katta qadamdir. U bilan ko‘zgu qarshisida turib, "Qara, bu sening ko‘zlaring, bu esa onangning ko‘zlari" deb tana a’zolarini yanada chuqurroq o‘rgatishda davom eting.') WHERE id = '696f3d72-602f-4dc5-8009-bf57000cd9a2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatdagi "Yon tomonga qadam". Farzandingiz endi faqat oldinga va orqaga emas, balki yon tomonga (crab walk) ham yura oladi. Bu muvozanat va harakatlarni muvofiqlashtirish uchun murakkab mashqdir. Unga musiqa sadolari ostida turli yo‘nalishlarda harakatlanishni ko‘rsating. Bu ham qiziqarli raqs, ham oyoq mushaklarining turli guruhlarini mustahkamlovchi mashqdir.') WHERE id = '29558e25-5ccf-4193-9fb7-c0eb732293d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Buyruqlarni bajarish»: Bola endi ketma-ket ikki bosqichdan iborat topshiriqlarni tushuna oladi. Masalan: «To‘pni ol va qutiga sol». Bu uning nutqni tushunish qobiliyati va operativ xotirasini rivojlantiradi. Unga shunday oddiy, ikki bosqichli «vazifalar» berib, diqqatini mashq qildiring.') WHERE id = 'b9afb514-aca9-4563-b096-907e76f4594a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Kitobga mehr». Bola endi yupqa qog‘oz sahifalarni (nazorat ostida) yirtmasdan varaqlashga harakat qiladi. U sevimli ertaklarini qayta-qayta tinglashni istashi mumkin. Har gal o‘qiganda rasmdagi turli tafsilotlarni ko‘rsating: «Qara, bu yerda kichkina kapalak ham bor». Bu uning ko‘rish orqali diqqatini ham, sabrini ham oshiradi.') WHERE id = 'dd8c337a-acae-4f9f-a64d-1a2e2dbf15fb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil gigiyena». Bola endi qo‘llarini quritishga, yuzini artishga yoki o‘zini gubka bilan «yuvishga» urinadi. Uning gigiyena ko‘nikmalariga bo‘lgan qiziqishini rag‘batlantiring. Unga o‘zining kichkina sochig‘ini bering. O‘ziga g‘amxo‘rlik qilish hissi uning o‘ziga bo‘lgan ishonchi va tanasiga nisbatan hurmatini shakllantiradi.') WHERE id = '31f5c493-87d9-45d8-950b-ce108414919b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Ramziy bo‘lishish». Bola endi sizga o‘yinchog‘ining bir qismini yoki ovqatidan bir luqma «taklif» qilishi mumkin. Hatto uni rostdan bermasa ham, bu imo-ishora bo‘lishish tushunchasining poydevoridir. Uning bu harakatini albatta «Rahmat, juda mehribonsan», deb maqtang.') WHERE id = '10acade6-6a92-4cf8-b728-f33648cdd314';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda «Geometrik shakllar». Bola endi doira, kvadrat va uchburchakni (pazl yoki shakllarni joylashtirish o‘yinchoqlarida) farqlay boshlaydi. Unga bu shakllarning nomlarini ayting. Hozircha ularning nomini ayta olmasa ham, ularni ko‘rib bir-biridan ajratishi geometrik tafakkurining poydevoridir.') WHERE id = '36dfa91f-6b4c-45f4-8057-bfc8dec4de87';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: «Pastga sakrash». Bola endi pastak zinadan (atigi bir necha santimetr balandlikdan) yerga sakrashga urinishi mumkin. Qo‘lidan ushlab, unga yordam bering. Bu harakat uning to‘piqlarini mustahkamlaydi, shuningdek, balandlik va masofani his qilishni amalda o‘rgatadi.') WHERE id = '20c66b93-4f9a-4106-b0f1-86263f239cfe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "His-tuyg‘ularni ifodalash". Bola endi och qolganini, charchaganini yoki nimadandir qo‘rqayotganini o‘ziga xos tovushlar yoki sodda so‘zlar bilan bildiradi. Siz uning bu ishoralarini so‘z bilan tasdiqlang: "Ha, sen charchabsan, kel, biroz dam olaylik". Bu uning kelajakda his-tuyg‘ularini so‘zlar orqali boshqarishi uchun eng katta ko‘makdir.') WHERE id = '402a1eb2-6224-49f3-92d8-6ebdc1c68d75';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "O‘yinchoqlar jonlanadi". Bola endi o‘yinchoq mashinalarini poyga qildiradi yoki qo‘g‘irchoqlarini bir-biri bilan "gaplashtiradi". Bu uning ham ijodkorligi, ham murakkab fikrlash qobiliyati rivojlanayotganini ko‘rsatadi. Siz ham u bilan birga ushbu rolli o‘yinlarda qatnashing va ssenariyni biroz kengaytiring: "Mashina yonilg‘i quyishga ketyaptimi?".') WHERE id = '50b52b0c-f730-4500-a2ea-7d50f4678b25';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "O‘zim qilaman!" davrining eng yuqori bosqichida. U eshikni o‘zi ochishni, tugmani o‘zi bosishni yoki zinadan mustaqil ko‘tarilishni istaydi. Bu qaysarlik emas, balki o‘z imkoniyatlarini sinab ko‘rishdir. Xavfsiz bo‘lgan har qanday vaziyatda unga urinib ko‘rishi uchun bir necha soniya ko‘proq vaqt bering. Biror ishni o‘zi uddalay olishini ko‘rish — uning o‘ziga bo‘lgan ishonchini shakllantiruvchi eng muhim omildir.') WHERE id = '0424ded1-f254-419a-bacc-912b20a6465b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "To‘pni nishonga otish". Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni muayyan yo‘nalishga yoki siz tomonga otishga harakat qiladi. Bu yelka mushaklari va ko‘z-qo‘l muvofiqlashuvi sezilarli darajada rivojlanganini ko‘rsatadi. U bilan "to‘pni savatga tashla" o‘yinini o‘ynab, aniqligini rivojlantiring.') WHERE id = 'd62bdbf3-d7fd-43c8-9cef-8ef0c95e0352';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sifatlarni kashf etish". Bola endi shunchaki narsalarning nomini aytmaydi, balki ularning xususiyatlarini ham tushunadi: "issiq", "sovuq", "katta", "kichkina". Ovqatlanayotganda yoki cho‘milayotganda bu so‘zlarni tez-tez ishlating: "Qara, bu suv iliq". Bu unga dunyoni batafsilroq tasvirlash va mavhum fikrlash qobiliyatini rivojlantirishga yordam beradi.') WHERE id = 'f549d4ea-b5e9-4a79-81eb-61a06771145c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Tartiblash va ipga tizish". Bola endi munchoqlarni ipga tizishga (munchoqlar yirik bo‘lishi va jarayon nazorat ostida o‘tishi kerak) yoki kalitni qulfga solishga urinib ko‘rishi mumkin. Bu harakatlar barmoq mushaklarining juda nozik muvofiqlashuvini talab qiladi. Bunday mashqlar kelajakda qalamni ushlash va yozish ko‘nikmalari uchun muhim poydevor bo‘ladi.') WHERE id = '499eb64f-17b7-4928-a28f-32d77bae69bd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "Tanlab yeyish" va "Nazorat". Bola ba’zan shunchaki "nazorat o‘z qo‘lida bo‘lishi" uchun ovqatdan bosh tortishi mumkin. Uni majburlamang. Buning o‘rniga dasturxonga ikkita foydali variant qo‘ying: "Brokkoli xohlaysanmi yoki sabzi?". Tanlash imkoniyati uning noroziligini kamaytiradi va qarorlari hurmat qilinayotganini his etishiga yordam beradi.') WHERE id = '597fce8a-7564-428a-aa97-6b8b166f2f7c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Fazoviy idrok" va "Balandlik". Bola endi balandlik xavf tug‘dirishini yaxshiroq tushunadi va pastroq joylardan tushayotganda ehtiyot bo‘ladi. Unga divan yoki zinadan orqasi bilan tushishni eslatib turing. Bu uning tana xavfsizligi qoidalarini o‘zlashtirishi uchun muhimdir.') WHERE id = '42d59296-b192-45dd-b455-11502c8aeaec';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvordagi "Taqlid" endi his-tuyg‘ularga ham o‘tadi. Siz kulganingizda u ham kuladi, siz jiddiy bo‘lganingizda u ham jim qoladi. Siz bolaning hissiy ko‘zgusisiz. U bilan o‘ynayotganda turli yuz ifodalarini ko‘rsating va ularni takrorlashini so‘rang. Bu uning hissiy intellekti va boshqalarni tushunish qobiliyati rivojlanishiga yordam beradi.') WHERE id = 'c03e79b5-c416-4e9a-8cda-23ab824d2ea7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil yig‘ishtirish" odati: Bola endi o‘yinchoqlarini qutiga yig‘ishni bir "vazifa" sifatida qabul qilishi mumkin. O‘yin tugagach, unga "Kel, mashinalarni uyiga joylaymiz" deb dalda bering. Bu unda ham tartib-intizomni, ham boshlagan ishini oxiriga yetkazish mas’uliyatini shakllantiradi. Har doim unga yordam bering va uni maqtang.') WHERE id = '4be37208-93a9-4898-b72a-811ae2d7a051';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "Savol-javob" muloqoti murakkablashib boradi. U "Bu nima?" degan savolni endi faqat javobini bilmagani uchun emas, balki siz bilan muloqotni davom ettirish uchun ham beradi. Javob berayotganda gapni biroz kengaytiring: "Bu qizil olma, sen uni yaxshi ko‘rasan". Bu bolaning so‘z boyligini tez oshiradi.') WHERE id = '59968193-d8d9-46a6-bcc6-77f1e1c44a81';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish mahorati". Bola endi yugurayotib, oldidagi to‘pni tepa oladi. Bunda harakat va muvozanat bir vaqtning o‘zida boshqariladi. U bilan uyda yoki hovlida "futbol" o‘ynab, ushbu dinamik muvozanat ko‘nikmasini mustahkamlang. Siz bilan birga harakat qilish uning uchun eng katta zavqdir.') WHERE id = '591884a7-b1fd-4edf-bb0d-3dca04af2ea4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni nafaqat farqlaydi, balki ularning nomlarini aytishga ham harakat qiladi. Unga "Ko‘k mashinani menga ber" deganingizda to‘g‘ri rangni tanlasa, bu uning ko‘rish xotirasi va nutqni tushunish qobiliyatidagi katta yutuqdir. Bu bilim mustahkamlanishi uchun kundalik kiyimlari va o‘yinchoqlarining ranglarini tez-tez ta’kidlab turing.') WHERE id = '1ab53f62-49d6-486d-9a52-ff092cc01b9c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasorat: Bola endi turgan joyida sakrashga (ikkala oyog‘ini bir vaqtda yerdan uzishga) ko‘proq intiladi. Bu oyoq mushaklari va muvozanat hissining puxta muvofiqlashuvini talab qiladi. Yumshoq gilam ustida u bilan "kim ko‘proq sakraydi" o‘yinini o‘ynab, kuch-g‘ayratini sarflashiga imkon yarating.') WHERE id = 'fac02d76-edc4-45d2-ac23-faa60bad4132';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Joyni bildiruvchi so‘zlar". Bola endi "ustida", "ostida", "ichida" kabi so‘zlarning ma’nosini amalda tushunadi. Unga "To‘pni stulning ostiga qo‘y" deb aytib, tekshirib ko‘ring. Bunday topshiriqlar uning ham til, ham makonda mo‘ljal olish ko‘nikmalarini rivojlantiradi. Bu tushunchalarni o‘yinlarga qo‘shib, uning mantiqiy fikrlashini mustahkamlang.') WHERE id = '30c8f80f-c5ad-42c7-a784-1930afcd9e96';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov" va iroda. Bola endi nima kiyishi yoki qaysi idishdan ovqat yeyishi haqida qat’iy fikrga ega. Unga "Bugun ko‘k idishda ovqat yeyishni xohlaysizmi yoki yashil idishdami?" kabi tanlov imkonini berish, o‘zini alohida shaxs sifatida his qilishiga yordam beradi va o‘rinsiz qaysarlikning oldini oladi.') WHERE id = '6f9d4056-a417-4319-83b2-043809df814a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Dizayn va qurish". Bola endi 6-8 ta kubni (blokni) ustma-ust terib, baland minora qura oladi. Bu diqqatni jamlashni hamda qo‘l harakatlarining aniqligini talab qiladi. Minora qulaganida buni quvonch bilan qarshi oling, shunda bola muvaffaqiyatsizlikdan qo‘rqmaydi va qayta urinib ko‘rishga ishtiyoqmand bo‘ladi.') WHERE id = '17f5c5df-ea05-4d59-8a28-32ffc0cbb3e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "G‘amxo‘rlik". Bola endi o‘yinchoq ayiqchasini "ovqatlantirishi", uni "yotog‘iga yotqizishi" yoki yig‘laganida "ovutishi" mumkin. Bu ramziy o‘yinlar rivojlanayotganidan dalolat beradi. Siz bolaga ko‘rsatgan mehr-shafqat endi uning o‘yinlarida namoyon bo‘lmoqda.') WHERE id = 'bc61e4f6-e294-4033-b040-474d57e5f13b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda "Mustaqil suv ichish". Bola endi ochiq stakandan suvni deyarli to‘kmasdan, ishonch bilan ichadi. Bu lab va jag‘ mushaklarining nutqqa qanchalik tayyor ekanini ko‘rsatadi. Bu ko‘nikmani mukammal egallashi uchun unga bolalar o‘lchamidagi, ushlashga qulay stakanlarni berishda davom eting.') WHERE id = 'f0007c08-4f82-470d-976e-b690d945c125';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Yangi qo‘rquvlar: Bola to‘satdan qorong‘ilikdan, baland tovushlardan yoki niqobli qahramonlardan qo‘rqa boshlashi mumkin. Bu uning tasavvuri va atrof-muhitni anglash qobiliyati rivojlanayotgani bilan bog‘liq. Uning qo‘rquvi ustidan kulmang, shunchaki yonida bo‘ling, quchoqlang va xavfsiz ekanini his qildiring. Vaqt o‘tishi bilan bu qo‘rquvlar o‘rnini qiziqish egallaydi.') WHERE id = 'c56b4f54-c6b4-4285-a227-6cdf7c49e75e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Ilk murakkab gaplar". Bola endi "Dada keldi", "Men suv ichdim" kabi sodda o‘tgan zamon tuzilmalaridan foydalanishi mumkin. Uning bu urinishlarini to‘g‘ri grammatik shaklda takrorlab, qo‘llab-quvvatlang. Sizning nutqingiz uning uchun eng asosiy namunadir. U bilan doimo aniq va samimiy tilda muloqot qiling.') WHERE id = 'ec0cb279-7627-42fd-8c4b-82e97e640420';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Orqaga yurish mahorati". Bola endi orqasiga qaramasdan bir necha qadam orqaga yura oladi. Bu uning tanasi fazoda qanday joylashganini his qilishi (proprioseptiv sezgi) uchun muhimdir. Unga "Qisqichbaqa kabi yuramiz" deb, bu harakatni o‘yinga aylantiring. Siz bilan birga harakat qilish uning uchun dunyodagi eng katta zavqdir.') WHERE id = '891890ba-7797-463a-90b9-18dda87b2142';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '20-oyga qadam qo‘yyapmiz! Bolaning endi o‘ziga xos "didi" shakllanmoqda. U kiymoqchi bo‘lgan oyoq kiyimini yoki yemoqchi bo‘lgan taomini qat’iy turib tanlashi mumkin. Bu uning irodasi mustahkamlanayotganidan dalolat beradi. Unga ikkita xavfsiz variant orasidan tanlash imkonini bering: "Bugun olma yeysizmi yoki nok?". Bu uning o‘ziga bo‘lgan ishonchini oshiradi va qaysarlik xurujlarini kamaytiradi.') WHERE id = '9857fafb-dba1-41f5-bd34-455d5b939f6f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirishda "Dinamik muvozanat". Bola endi egilib, yerdan biror narsani olgach, yiqilmasdan yana tik tura oladi. Bu bel va oyoq mushaklari sezilarli darajada kuchayganini ko‘rsatadi. Uning uchun o‘yinchoqlarni polga turli balandliklarda joylashtiring va ularni bir qutiga yig‘ishini so‘rang. Bu mashq uning tanasini boshqarish qobiliyatini takomillashtiradi.') WHERE id = '21286f36-7532-41d3-a58d-4d4ecfb6df25';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "So‘z birikmalari" jadal rivojlanadi. Bola endi istaklarini ikki-uch so‘z bilan ifodalaydi: "Dada, to‘pni bering", "Ona, suv ichaman". U gapirayotganda har bir so‘zini diqqat bilan tinglang va ko‘z bilan aloqa qiling. Lug‘at boyligi yanada oshishi uchun uning gaplarini biroz kengaytirib javob bering.') WHERE id = '4a36674f-0b66-41a0-beba-daa82b8d9f0b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Pazllar va boshqotirmalar". Bola endi 3-4 qismli oddiy pazllarni yig‘ishda yoki shakllarni mos teshiklarga joylashtirishda ancha chaqqon. Bu uning fazoviy idroki va ko‘rib tahlil qilish qobiliyatini rivojlantiradi. Topshiriq qiyin bo‘lsa, qiziqishi so‘nmasligi uchun unga kichik maslahatlar bering.') WHERE id = 'cce26ca5-c2df-4a63-a452-8753ade9a3fe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Ramziy bo‘lishish". Bola endi sizga o‘z o‘yinchog‘ining bir qismini "taklif qilishi" mumkin (yoki darhol qaytarib olishi ham mumkin). Bu bo‘lishish tushunchasi shakllanayotganining ilk belgisidir. Uning bu harakatini albatta maqtang: "O‘yinchog‘ingni menga ko‘rsatganing uchun katta rahmat". Bu unda ijobiy ijtimoiy ko‘nikmalarning poydevorini yaratadi.') WHERE id = '35b68ddd-9074-4a9a-97b7-0fddbf831df1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim tozalayman". Bola sizga taqlid qilib, qo‘llarini quritishga, yuzini artishga yoki stolni o‘yinchoq mato bilan tozalashga intiladi. Uning mustaqil bo‘lish istagini so‘ndirmang. Unga o‘zining kichik sochig‘i yoki cho‘tkasini berib, "uy ishlariga" jalb qiling. Bu unda mas’uliyat hissini shakllantiradi.') WHERE id = '37a69b03-aa17-4bad-982a-11091970591b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Xotira va "Fazoviy xotira" eng yuqori darajada. Bola endi siz yashirgan o‘yinchoqning joyini bir necha soatdan keyin ham eslay oladi. U bilan uyda "xazina qidirish" o‘yinini o‘ynang. Bir o‘yinchoqni yostiq ostiga qo‘ying va uni qanday topishini kuzating. Bu o‘yin uning diqqatini jamlashiga hamda muammolarni hal qilish ko‘nikmasiga ijobiy ta’sir ko‘rsatadi.') WHERE id = '105285fc-eb7a-4111-ad71-74ef8c1d89b9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "O‘yinchoqlar bilan muloqot". Bola qo‘g‘irchog‘i yoki o‘yinchoq ayig‘i bilan "gaplashadi", ularga ovqat beradi yoki ularni uxlatadi. Bu hissiy intellekt rivojlanayotgani va kundalik odatlar o‘zlashtirilayotganining belgisidir. Siz ham bu rolli o‘yinlarga qo‘shiling: "Ayiqcha hozir qayerga ketyapti?". Bu uning ijodiy fikrlashini jadal rivojlantiradi.') WHERE id = '1d1a3072-a955-4f0c-b97e-45be9ab5c292';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqillik: «Men o‘zim kiyinaman». Bola endi paypog‘ini yechish, boshiga qalpog‘ini kiyish yoki oson kiyiladigan oyoq kiyimini oyog‘iga ilishda yanada qat’iyatliroq. Bu jarayon uchun unga bir necha daqiqa qo‘shimcha vaqt bering. Shoshirmasdan, biror ishni mustaqil bajarishiga imkon yaratish uning o‘ziga bo‘lgan ishonchi va mustaqillik tuyg‘usini shakllantiradi.') WHERE id = '947a00f0-f695-4c17-b833-1f7ad19529e3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Navbat kutish». Bola endi bog‘da arg‘imchoq uchish yoki o‘yinchoq bilan o‘ynash uchun biroz kutish kerakligini tushunadi. «Hozir mening navbatim, keyin seniki» o‘yinlari orqali unga sabr qilishni o‘rgating. Bu ko‘nikma uning kelajakda bog‘cha va maktab muhitiga moslashishi uchun eng muhim ijtimoiy asosdir.') WHERE id = 'f555abb8-3ed3-4f14-968a-d2f98f543e71';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ovqatlanishda «Sanchqi va qoshiq mahorati». Bola endi qoshiqni ovqat bilan to‘ldirib, deyarli to‘kmasdan og‘ziga olib borishni o‘rganmoqda. Unga sanchqiga sanchish mumkin bo‘lgan (fork-friendly) kichik sabzavot va meva bo‘laklarini taklif qiling. Mustaqil ovqatlanish unga to‘yganini his qilishni o‘rganish va turli tuzilishdagi taomlarga ko‘proq qiziqish bildirishga yordam beradi.') WHERE id = 'a925547f-11ed-45ce-9474-cab706a5ddda';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: «O‘yinchoqlar bilan muloqot». Bola endi qo‘g‘irchog‘i yoki ayiqchasi bilan «gaplashadi», ularni «ovqatlantiradi» yoki «uxlatadi». Bu uning hissiy intellekti rivojlanayotgani va kundalik odatlarni qanchalik chuqur o‘zlashtirayotganining belgisidir. Bu rolli o‘yinlarda unga qo‘shiling va ssenariyni biroz kengaytiring.') WHERE id = 'a151a89a-61af-4831-b10f-8a215a565721';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanish: «To‘p tepish». Bola endi tik turib, muvozanatini yo‘qotmasdan oldidagi to‘pni tepishga urinadi. Bu murakkab muvofiqlashtirishni va bir oyoqda qisqa muddat muvozanat saqlashni talab qiladigan harakatdir. U bilan uyda yoki hovlida yengil to‘p o‘ynab, ham harakat tezligini, ham aniqligini rivojlantiring.') WHERE id = 'deb4ac24-b3c7-4d6b-a7be-c36edea03c4e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 600 kunni ortda qoldirdik! Farzandingiz 20-oyining yarmini ham o‘tkazdi. U endi oddiy ko‘rsatmalarni to‘liq tushunadi, his-tuyg‘ularini aniq ifodalaydi va dunyoni zabt etishga tayyor mitti «tadqiqotchi»ga aylangan. Bu kunni u bilan sevimli bog‘ida yoki o‘yin xonasida vaqt o‘tkazib nishonlang. Siz ajoyib onasiz!') WHERE id = '1f1a3784-4c01-4fba-825d-ca3fcac15f79';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy dadillik: "Tirmashib chiqish va tushish". Bola endi zinadan tezroq va bir qadamdan (qo‘lidan ushlab turganingizda) ko‘tarila oladi. Balandlikni anglash qobiliyati oshgani sari, unga xavfsiz tushish usullarini (orqasi bilan tushishni) qayta-qayta ko‘rsating. Himoya to‘siqlari hali ham joyida va yopiq ekaniga ishonch hosil qiling.') WHERE id = '3dfce46e-871b-4ff0-b52c-ef4021fb63e3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi "Bo‘lmaydi" degan so‘zga munosabat bildiradi, ammo ba’zan reaksiyangizni sinash uchun qoidalarni buzadi. Xotirjam, ammo qat’iyatli bo‘lish eng muhim shartdir. Agar biror narsaga "yo‘q" degan bo‘lsangiz, buni har safar bir xil tarzda takrorlang. Qoidalarning o‘zgarmasligi bolada ichki tartib va xavfsizlik hissini shakllantiradi.') WHERE id = '3d5db953-53d5-41ac-96c7-0de1abf8d13a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki farqlabgina qolmay, ularni bir-biriga moslashtirishni ham biladi. Unga "Ko‘k to‘pni ko‘k qutiga sol" deganingizda buni to‘g‘ri bajarsa, bu uning vizual mantiqi rivojlanishidagi katta yutuqdir. Kundalik hayotda "qizil olma", "yashil barg" kabi ranglar ta’kidlangan jumlalarni ishlatib, bu bilimlarni mustahkamlang.') WHERE id = '7bf7487b-3d3e-49a7-9bc5-a3a917c3fbbf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Turgan joyida sakrash". Bola endi ikkala oyog‘ini bir vaqtda yerdan uzib, sakrashga harakat qiladi. Buning uchun oyoq mushaklarining kuchi va muvozanatni saqlashga yordam beradigan murakkab muvofiqlashtirish talab etiladi. U bilan birga "Quyondek sakraymiz" o‘yinini o‘ynang. Bu ham qiziqarli, ham jismoniy rivojlanish uchun juda foydali.') WHERE id = '37a6e358-9a9e-40cc-aab7-74b540fd0681';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sifatlarning ko‘payishi". Bola endi buyumlarning nafaqat nomini, balki xususiyatlarini ham (issiq, sovuq, katta, kichik, yumshoq, qattiq) tushunadi. Ovqatlanayotganda "Bu pyure issiq" yoki o‘yinchog‘iga tekkanda "Bu ayiqcha yumshoq" deb, uning sezgilarni ifodalovchi so‘z boyligini oshiring. Bu unga dunyoni batafsilroq tasvirlashga yordam beradi.') WHERE id = 'e5f3d411-7714-4b52-b440-c00913f921c9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qalamni ushlash" ko‘nikmasi takomillashadi. Bola endi rangli qalamni kafti bilan emas, barmoqlariga yaqinroq tutishga harakat qiladi. Qog‘ozda aniqroq doiralar yoki tartibsiz, ammo dadil chiziqlar chizadi. Unga rangli qalamlar va katta qog‘ozlar berib, "ijodkorlik" maydonini kengaytiring.') WHERE id = '286d8a77-5c51-4a8f-96ae-733178c15fb0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '20-oyning so‘nggi o‘n kunligini boshlaymiz. Bola endi tana a’zolarini shunchaki ko‘rsatibgina qolmay, ular nima vazifa bajarishini ham tushuna boshlaydi. "Oyoqlaring bilan nima qilasan?" deb so‘raganingizda, u yugurish yoki oyoq bilan depsinishni ko‘rsatishi mumkin. U bilan "Bu nima uchun kerak?" o‘yinini o‘ynang. Bu uning ham so‘z boyligini, ham funksional fikrlashini rivojlantiradi.') WHERE id = 'dee4db38-d5ad-4ab8-80a6-e91df1c6234f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "To‘siqlar ostidan o‘tish". Bola endi nafaqat tik turishni, balki egilib stol yoki stul ostidan o‘tishni, makonda o‘z tanasining o‘lchamlarini hisobga olishni ham o‘rganadi. Bu uning o‘z tanasini his qilishini (body awareness) kuchaytiradi. Uyda yostiqlar va stullardan "tunnellar" yasab, unga bu ko‘nikmani mashq qilish imkonini bering.') WHERE id = '4db05b48-52f1-4673-a7b9-28436103d6d9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Olmoshlarning ilk belgilari". Bola endi o‘ziga nisbatan "Men", sizga nisbatan esa "Sen" deyishga (yoki o‘z tilida buni boshqa tovushlar bilan ifodalashga) urinadi. Bu uning o‘zini atrofdagi olamdan alohida shaxs sifatida anglay boshlaganidan dalolat beradi. U o‘z ismini aytganida, "Ha, sen, (ismini ayting), shu yerdasan", deb uning o‘zlik hissini mustahkamlang.') WHERE id = '15ef8b0a-68af-41c5-881d-ef1aaddc31ca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Burama qopqoqlarni ochish". Bola endi idish qopqoqlarini burab ochishga yoki yopishga harakat qiladi. Bu harakat bilak mushaklarini aylantirish uchun ajoyib mashqdir. Unga turli o‘lchamdagi xavfsiz idishlarni berib, bu yangi "mahoratini" sinab ko‘rishiga imkon bering.') WHERE id = 'eca36160-9ece-4da0-80c8-687ec7c51745';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Yordam berish istagi". Bola endi xarid xaltasidan biror narsani olish yoki sizga nimanidir olib kelishga intiladi. Unga "Iltimos, bu taglikni menga ber" kabi kichik topshiriqlar bering. Topshiriqni bajarganida, "Menga juda katta yordam berding, rahmat", deng. Bu unda ijtimoiy mas’uliyat va o‘zini foydali his qilish tuyg‘usini shakllantiradi.') WHERE id = 'ee7370f4-6eb2-48da-aebb-00ccc3c2ad1b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil ravishda tish tozalash". Bola endi sizga taqlid qilib, tish cho‘tkasini og‘ziga soladi va harakatlantiradi. Hozircha bu shunchaki o‘yin va uning tishlarini siz tozalashingiz kerak, ammo bu odatga bo‘lgan qiziqishini qo‘llab-quvvatlang. O‘z tish cho‘tkasiga ega bo‘lishi va tishlarini o‘zi tozalashga urinishi gigiyena odatlarini shakllantirish uchun yaxshi zamin yaratadi.') WHERE id = '183dc3b9-e225-46b4-b630-b164f5414528';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Sifatlarni birlashtirish». Bola endi buyumlarni shunchaki nomlamaydi, balki ularning rangi yoki o‘lchamini ham qo‘shib aytadi: «Katta to‘p», «Qizil mashina». Uning bunday urinishlarini rag‘batlantiring va gapini biroz kengaytiring: «Ha, bu sening katta va yumshoq to‘ping».') WHERE id = 'b2c7d131-58dd-486b-9609-a0affe8ae4df';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Tik va yotiq chiziqlar». Bola endi qalamni ishonchliroq ushlaydi va qog‘ozga maqsadli ravishda to‘g‘ri chiziqlar chizishga harakat qiladi. Unga yo‘g‘on rangli qalamlar va katta rasm qog‘ozlarini bering. U chizgan har bir chiziq qo‘l-ko‘z muvofiqligi va kelajakdagi yozish ko‘nikmalarining mustahkamlanishiga xizmat qiladi.') WHERE id = 'cc6fb892-8f1f-42d8-95a3-eba0a72b0349';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil tanlov» va kiyinish. Bola endi qaysi paypoq yoki bosh kiyimni kiyishni xohlashi haqida qat’iy fikrga ega. Unga ikkita xavfsiz variantni taklif qiling: «Bugun yashil bosh kiyimingni kiyasizmi yoki ko‘kini?». Bunday kichik qarorlar bolaga o‘zini muhim his qilishiga yordam beradi va qaysarlik xurujlarini kamaytiradi.') WHERE id = '38af9059-ae27-4644-b4e5-977b53c68250';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Hamkorlik»: Bola endi o‘yinchoqlarini birgalikda yig‘ishtirishdan zavqlanadi. «Kel, mashinalarni birga joyiga qo‘yamiz», desangiz, u sizga yordam beradi. Bu ham tartib-intizom ko‘nikmasi, ham birgalikdagi faoliyat quvonchidir. Har safar yordam berganidan keyin uni maqtashni unutmang.') WHERE id = '49ba697d-2e60-439d-966b-ca621530805d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida «Qismlarni birlashtirish». Bola endi ikki yoki uch qismli oddiy pazllarni (boshqotirmalarni) mustaqil yig‘a oladi. Rasmlarni birlashtirib, yaxlit tasvirni ko‘rish uning ko‘rish-fazoviy tafakkurini rivojlantiradi. Eplay olmasa, unga xotirjamlik bilan ishora bering: «Qara, itning dumi shu yerda». Bu uning muammolarni hal qilishdagi qat’iyatini oshiradi.') WHERE id = '1bcc9149-af08-4bbd-bac4-e8848b1380ea';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlik: «To‘p tepish va yugurish». Bola endi yugurayotganda oldidagi to‘pni tepa oladi. Bunda harakat tezligi va dinamik muvozanat bir vaqtning o‘zida boshqariladi. U bilan uyda yoki bog‘da «futbol» o‘ynab, harakatlarining aniqligini oshiring.') WHERE id = '56be9450-be4f-4da2-bbc6-79d6b2c42f94';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Nega?» savolining ilk belgilari. Bola hamma narsani ko‘rsatib, «Bu nima?» deya sizning izohingizni kutadi. Siz har bir buyumning nomi va nima uchun ishlatilishini sodda jumlalar bilan tushuntiring. Masalan: «Bu tish cho‘tkasi, u tishlarimizni tozalash uchun kerak». Javoblaringiz uning miyasida dunyo haqidagi tasavvurlarni yanada tizimli ravishda guruhlashga yordam beradi.') WHERE id = 'cd8ca16e-d97a-4620-91cf-5f294687b3b5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanishda «O‘zini boshqarishga urinishlar». Bola jahli chiqqanida sizga qarab, munosabatingizni kutishi mumkin. Bunday paytlarda xotirjam bo‘ling va «O‘yinchoq tuzalmagani uchun hozir jahling chiqdi», deb uning his-tuyg‘usini nomlang. Sizning xotirjamligingiz u uchun hissiyotlarini boshqarish bo‘yicha eng yaxshi saboqdir. Siz ajoyib onasiz!') WHERE id = '10a65a4a-b905-4a99-8c90-141b7917fa27';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Farzandingiz qoshiq va sanchqidan foydalanishni ancha yaxshi o‘zlashtirgan. U ovqatning katta qismini to‘kmasdan og‘ziga olib bora oladi. Bu nozik motorika hamda qo‘l-ko‘z muvofiqlashuvi yuqori darajada rivojlanganini ko‘rsatadi. Unga turli tuzilishga ega taomlarni mustaqil yeyishi uchun sharoit yarating. Bunday mustaqillik unga to‘yganini yaxshiroq anglashga yordam beradi.') WHERE id = 'cd235f0e-55bc-496a-a89f-89523cd7e8fe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda «Tirmashib chiqish va tushish». Bola endi divan yoki past zinapoyalarga mustaqil chiqa oladi. Unga balandlikdan doimo orqasi bilan, avval oyoqlarini tushirib tushishni eslatib turing. Bu uning jismoniy xavfsizlik qoidalarini o‘zlashtirishi va xavflarni ko‘z bilan baholashi uchun muhim ko‘nikmadir.') WHERE id = 'b1b72a87-fa8e-4ffe-811e-9806f2ea1d7c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Harakatni bildiruvchi so‘zlar». Bola endi «bor», «kel», «uxla», «ye» kabi fe’llarni tegishli vaziyatlarda to‘g‘ri ishlatadi. Siz uning aytgan fe’llarini kengaytirib javob bering: «Ha, hozir biz bog‘ga ketyapmiz». Bu uning nutqida grammatik tuzilmalar shakllanishini tezlashtiradi.') WHERE id = '275f2048-2ec2-445d-b693-5c34e41e7b83';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nozik motorikada «Terish va qurish». Bola endi 8-10 ta kubikni ustma-ust terib, qulamaydigan minoralar qura oladi. Bu diqqatni jamlashni ham, barmoq uchlarining aniqligini ham talab qiladi. Minora qulaganida buni quvonch bilan qabul qiling, shunda bola yana urinib ko‘rishga ishtiyoqmand bo‘ladi. Bu uning muammolarni hal qilishdagi qat’iyatini mustahkamlaydi.') WHERE id = '97370ca6-2fbc-4894-81aa-9ab979d2d27e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Moslashtirish" (Matching). Bola endi bir xil hayvon yoki buyumning ikki xil rasmini bir-biriga moslashtira oladi. U bilan oddiy kartochkalar yordamida "Bir xilini top" o‘yinini o‘ynang. Bu uning ko‘rish diqqati va xotirasini nihoyatda charxlaydi. To‘g‘ri topganida quvonch bilan maqtang, shunda uning ishtiyoqi so‘nmaydi.') WHERE id = '45e380ad-6559-467d-84f4-eced81427f7d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Zinadan qadamma-qadam tushish". Qo‘lidan ushlaganingizda bola endi zinadan ishonchliroq, qadamma-qadam tushishga harakat qiladi. Pastga tushish yuqoriga ko‘tarilishdan qiyinroq bo‘lib, ko‘proq muvozanatni talab qiladi. Xavfsizligini ta’minlash uchun doimo yonida bo‘ling va zinaning yonidagi tutqichlardan ushlashiga imkon bering.') WHERE id = '9b3b0e2c-c4cd-4d64-a63f-e74713052b56';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Tuyg‘ularni nomlash". Bola jahli chiqqanida, quvonganida yoki uyalganida, bu his-tuyg‘ularni so‘z bilan ifodalang: "Sen hozir juda xursandsan!", "O‘yinchog‘ing yiqilib tushgani uchun biroz xafa bo‘ldingmi?". Tuyg‘ularni nomlash bolaning kelajakda "tantrum" (jahldorlik xurujlari) paytida o‘zini osonroq boshqarishiga yordam beradi.') WHERE id = 'da0fa9b2-9fec-47fb-a56d-5e0c384540ea';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning kuchayishi: "Ramziy o‘yinlar". Bola endi bir buyumni boshqasining o‘rnida ishlata oladi. Masalan, kubikni "telefon" deb qulog‘iga tutishi mumkin. Bu bolaning mavhum tafakkuri va ijodkorligi yuksak darajada rivojlanayotganidan dalolat beradi. U bilan bu o‘yinlarga qo‘shiling va tasavvurini qo‘llab-quvvatlang.') WHERE id = 'f71a9e64-80ca-4672-869a-4b4e2012c4b5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "Men" va "Meniki" so‘zlarini tez-tez ishlatadi. Bu uning shaxsiy chegaralari va o‘zligini anglayotganidan dalolat beradi. Sevimli o‘yinchog‘ini bag‘riga bosib, "Meniki!" deyishi tabiiy holat. Unga o‘z buyumlariga egalik qilish imkonini bering. Bu kelajakda boshqalarning ham shaxsiy chegaralarini hurmat qilishi uchun muhim poydevor bo‘ladi.') WHERE id = 'b7d51937-c7a2-4d6d-b732-4b494fc952b3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Orqaga yurish mahorati". Bola endi ortiga qaramasdan va muvozanatini yo‘qotmasdan bir necha qadam orqaga yura oladi. Bu uning tanasi fazoda qanday joylashganini his qilishi (propriotseptiv sezgi) uchun ajoyib mashqdir. U bilan "Qisqichbaqadek yuramiz" o‘yinini o‘ynang. Bu ham qiziqarli mashg‘ulot, ham oyoq mushaklarini boshqacha tarzda ishlatadi.') WHERE id = '513f1229-f55a-4c5d-a40b-fc0fd9f8ae37';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «ramziy g‘amxo‘rlik». Bola o‘yinchoq ayiqchasiga «suv ichirishi», uning ustini ko‘rpa bilan yopishi yoki u yig‘laganda silab ovutishi mumkin. Bu uning hissiy intellekti va boshqalarning his-tuyg‘ularini tushunish qobiliyati rivojlanayotganidan dalolat beradi. Uning bunday mehribon harakatlarini maqtashni unutmang.') WHERE id = '4c44b890-83ea-41cb-99e6-72cdc0b1bf1f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil yig‘ishtirish» odati: bola endi o‘yinchoqlarini qutiga yig‘ishni o‘yinning yakuni sifatida qabul qila boshlaydi. «Kel, mashinalarni joyiga qo‘yamiz», deb bu jarayonni qiziqarli qiling. Bu unda ham tartib-intizomni, ham mas’uliyat hissini shakllantiradi. Sizga yordam berganda, u o‘zini katta va foydali insondek his qiladi.') WHERE id = 'a363f89b-584e-494b-8c74-513903336560';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida «Bir xil va farqli» tushunchasi. Bola endi bir xil rangdagi yoki bir turdagi buyumlarni guruhlarga ajrata oladi. Unga «Barcha qizil narsalarni bu yerga yig‘amiz», deb sinab ko‘ring. Bunday o‘yinlar uning mantiqiy tafakkuri va ko‘rish orqali tahlil qilish qobiliyatiga poydevor yaratadi.') WHERE id = 'f0afc0a3-b89f-4803-b20f-1fd14e1c84af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Tepalikdan pastga yurish». Qiya joylarda (kichik tepaliklarda) yurish boladan muvozanatni yangicha saqlashni talab qiladi. Bu uning to‘piqlarini hamda tanasining og‘irlik markazini boshqarish qobiliyatini mustahkamlaydi. Bog‘da sayr qilganingizda, shunday kichik jismoniy sinovlar uchun sharoit yarating.') WHERE id = 'c7f6bf36-ec3f-4dad-b529-a2a1c67afd8f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Ot va olmosh o‘rtasidagi bog‘liqlik». Bola endi o‘zini ismi bilan atashdan «Men» deyishga o‘tishi mumkin. Siz undan biror narsa so‘raganingizda «Men» yoki «Meniki» desa, bu uning o‘z shaxsini anglash hissi to‘liq shakllanganidan dalolat beradi. U bilan shu mavzuda suhbatlar quring: «Bu kimning to‘pi? Meniki!».') WHERE id = 'da725a7e-8a5a-4880-b76d-f59275696659';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: «Murakkab taqlid». Bola endi bir necha bosqichdan iborat harakatlarga taqlid qiladi. Masalan, «bozorga boradi», «xarid qiladi» va «ovqat pishiradi». Bu uning xotirasi rivojlanayotganini hamda hodisalar o‘rtasidagi mantiqiy bog‘liqlikni qanchalik chuqur kuzatishini ko‘rsatadi.') WHERE id = '385dd8e9-365e-4aee-b063-18466c68a303';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish qobiliyati rivojida "Pazl va mantiq". Bola endi 4–5 bo‘lakli oddiy pazllarni mustaqil yig‘ishga intiladi. Tasvir bo‘laklarini ko‘z bilan moslashtirib birlashtirish uning diqqatini jamlash va muammolarni hal qilish ko‘nikmalarini rivojlantiradi. Eplay olmasa, unga xotirjamlik bilan yo‘l ko‘rsating, ammo o‘rniga bajarib qo‘ymang. Bu kichik "g‘alabalar" uning bilish qobiliyatini mustahkamlaydi.') WHERE id = '39e90e4b-782c-46d9-9e9f-4cff4dfc1e98';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Orqaga yurish". Bola endi orqaga qarab bir necha qadamni ishonch bilan bosa oladi. Bu muvozanat saqlashning murakkab turi bo‘lib, tananing makondagi harakatlarini muvofiqlashtirishni talab qiladi. U bilan "Qisqichbaqadek yuramiz" o‘yinini o‘ynang. Bu turli mushak guruhlarini ishlatish bilan birga, quvonchli va kulgili lahzalarni ham yaratadi.') WHERE id = 'f9c866fa-1063-46f8-bd49-769efa10ff9a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "Savol-javob" muloqoti murakkablashmoqda. U "Bu nima?" degan savolni faqat narsaning nomini bilish uchun emas, siz bilan suhbatni davom ettirish uchun ham berishi mumkin. Javob berayotganda buyumning vazifasini ham ayting: "Bu taroq, u bilan sochimizni taraymiz". Sizning batafsil tushuntirishlaringiz uning dunyoqarashini tez kengaytiradi.') WHERE id = 'b9cee91c-b40d-4bad-a4d5-c04129fdcf20';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar va "Yo‘q". Bola hamma narsani o‘zi qilishni xohlaganda yoki istagi darhol bajarilmaganda jahli chiqishi mumkin. Bunday paytlarda xotirjam bo‘ling va "Hozir jahling juda chiqyapti, lekin (qoidani ayting) qilish mumkin emas", deb uning his-tuyg‘usini nomlang. Sizning izchilligingiz va xotirjam ohangdagi tushuntirishlaringiz unga his-tuyg‘ularini boshqarishni o‘rgatadigan eng yaxshi saboqdir.') WHERE id = '4c29e86c-55c8-4844-9903-13a58d0c9468';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ikki bosqichli topshiriqlarni bemalol bajara oladi. Masalan: "O‘yinchoqni ol va tokchaga qo‘y". Bu uning ham ishchi xotirasi, ham nutqni tushunish qobiliyati yangi bosqichga ko‘tarilganini ko‘rsatadi. Kun davomida unga shunday kichik "vazifalar" berib, mas’uliyat hissi va diqqatini rivojlantiring.') WHERE id = '63b64ef1-0e7a-45db-8f97-702657621c76';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Zinadan chiqish mahorati". Bola endi bir qo‘lidan ushlab turilganda zinadan har bir pog‘onaga bittadan oyoq qo‘yib chiqishga urinishi mumkin. Bu son va tos mushaklari mustahkamlanayotganini anglatadi. Doimo yonida bo‘lib, uning xavfsizligini ta’minlang va yutuqlarini olqishlang.') WHERE id = '4d704d6f-6be2-478b-b2bb-0363d0dde71b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola 22-oyning o‘rtasiga yetdi va uning lug‘at boyligida "so‘zlar portlashi" davom etmoqda. Endi u nafaqat buyumlarni, balki murakkab his-tuyg‘ular va harakatlarni ham nomlashga urinmoqda. U bilan gaplashayotganda jumlalaringizni biroz murakkablashtiring: "Kel, qizil qalpog‘ingni kiyib, tashqariga chiqamiz". Bu uning eshitish xotirasi va grammatikani anglash qobiliyatini mustahkamlaydi.') WHERE id = '9ec78a78-6722-4c40-af92-d0238d028cd3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Bir joyda sakrash mahorati". Bola endi ikkala oyog‘ini bir vaqtda yerdan uzib sakrashni ancha ishonchli bajara oladi. Bu harakat uning boldir mushaklari va muvozanatni saqlash qobiliyatini rivojlantiradi. U bilan birga musiqa sadolari ostida sakrash musobaqasini o‘tkazing. Bu energiyani chiqarishning eng qiziqarli usulidir.') WHERE id = '43c73105-af4e-4d3a-b15d-a50b903d4d3e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sifatlarning ko‘payishi". Bola endi buyumlarning xususiyatlarini (rang, shakl, ta’m) yaxshiroq farqlaydi. "Nordon limon", "shirin olma", "sovuq suv" kabi iboralarni uning kundalik hayotiga kiriting. Bu unga hissiy idrokini so‘zlar bilan bog‘lash va dunyoni yanada rang-barang tasvirlashga yordam beradi.') WHERE id = '39e55b53-a529-49e6-9321-ad14c32b7c7c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Burama qopqoqlarni ochish". Bola endi turli o‘lchamdagi butilka qopqoqlari yoki idishlarni burab ochishga qiziqish bildirmoqda. Bu harakat bilak mushaklarining aylantirish harakati uchun ajoyib mashqdir. Unga xavfsiz, bo‘sh plastik idishlar berib, bu "mexanik" qiziqishini qo‘llab-quvvatlang.') WHERE id = 'be39779f-3011-4da7-aa56-861a48e906e9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim kiyinaman" degan qat’iylik avjiga chiqdi. Bola endi kiyish oson bo‘lgan shimlarni tortib kiyishga yoki oyoq kiyimini oyog‘iga kiyishga urinmoqda. Bu jarayon uchun unga bir necha daqiqa qo‘shimcha vaqt bering. Shoshirmasdan, biror ishni o‘zi bajarishiga imkon yaratish uning o‘zini qadrlashini (self-esteem) har narsadan ko‘ra ko‘proq oshiradi. Sizning sabringiz uning mustaqilligi uchun eng katta hissadir.') WHERE id = 'f0ed327b-3dc6-4a59-97ba-d4b77cc256ae';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Bo‘lishishning ilk saboqlari". Bola endi o‘yinchoqni bir muddat boshqa birovga berish uni butunlay yo‘qotish degani emasligini tushunadi. Biroq unda "meniki" degan tuyg‘u hali ham juda kuchli. Uni bo‘lishishga majburlamang, buning o‘rniga "navbat bilan o‘ynash" tushunchasini amalda ko‘rsating. Bu ijtimoiy moslashuvni osonlashtiradi.') WHERE id = 'ea8bf74e-874e-47bc-9e0f-7dc3094dfe1c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sabab-oqibat" ifodalari. Bola endi "Chunki" (yoki shunga yaqin tovush) deyishga urinib, nega nimanidir xohlayotganini tushuntira oladi. Siz ham unga sabablarni tushuntiring: "Hozir muzqaymoq yemaymiz, chunki havo sovuq". Bu uning mantiqiy fikrlashi va dalil keltirish qobiliyatining poydevoridir.') WHERE id = 'f2f8883c-9f63-473e-95a0-d34bd2a07048';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Burab ochish va aylantirish". Bola endi butilka qopqoqlari va o‘yinchoq vintlarini ishonch bilan burab ochib-yopa oladi. Bu bilak mushaklarining aylanish harakati uchun eng yaxshi mashqdir. Unga turli o‘lchamdagi plastik idishlar berib, mexanizmlarga bo‘lgan qiziqishini qo‘llab-quvvatlang. Bu ko‘nikma kelajakda qalam ushlash kabi murakkab vazifalar uchun muhimdir.') WHERE id = '691bb5ce-e086-4aaa-85cf-679930593155';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim yuvinaman". Cho‘milayotganda bola sovun yoki gubkani olib, badanini ishqalashga va sizga taqlid qilishga harakat qiladi. Uning gigiyena odatlariga bo‘lgan qiziqishini so‘ndirmang. O‘zini "tozalashi" tana a’zolarini yaxshiroq tanishiga hamda shaxsiy gigiyena uchun mas’uliyatni erta yoshdan o‘zlashtirishiga yordam beradi.') WHERE id = 'd4a78241-9e41-44ca-8bb9-8ed66f07c05f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Bo‘lishishning qiyinligi". Bu yoshda "Meniki!" deb baqirish juda tabiiy. Bola o‘ziga tegishli narsalarni himoya qilishni o‘rganmoqda. Uni bo‘lishishga majburlamang, buning o‘rniga "Navbat bilan o‘ynaymiz" tamoyilini qo‘llang. Bu bolaga o‘zini xavfsiz his qilish imkonini beradi: u o‘yinchog‘ini qaytarib olishini biladi. Sizning bu sabr-toqatingiz uning ijtimoiy intellektini shakllantiradi.') WHERE id = '6ff62ac3-5f68-4753-ac59-118eb1c39c2b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida "Moslashtirish" (Matching). Bola endi bir xil hayvonning turli rasmlarini yoki bir xil rangdagi buyumlarni o‘zaro moslashtira oladi. U bilan oddiy kartochkalardan foydalanib, "Bir xilini top" o‘yinini o‘ynang. Bu uning vizual diqqatini ham, toifalar bo‘yicha fikrlash qobiliyatini ham jadal rivojlantiradi.') WHERE id = '63ba4843-04a1-423b-8338-e5d3a90cedb9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni uzoqqa otish". Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni yelka ustidan (overhand) oldinga otishga harakat qiladi. Bu harakat butun tana muvofiqligini talab qiladi. U bilan bog‘da yoki keng maydonda "Kim to‘pni uzoqroqqa otadi?" o‘yinini o‘ynang. Bu uning qo‘llarini mustahkamlaydi va masofani idrok etish qobiliyatini yaxshilaydi.') WHERE id = '972bc93a-ef8b-4efd-af66-730802aaa073';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zim ichaman". Bola endi ochiq stakandan suvni deyarli to‘kmasdan, ishonch bilan icha oladi. Bu uning lab va jag‘ mushaklari nutqqa qanchalik tayyor ekanini ko‘rsatadi. Bu ko‘nikmani mukammal egallashi uchun unga bolalar o‘lchamidagi, ushlashga qulay stakanlarni berishda davom eting.') WHERE id = '20e5b03d-5d16-4142-97b2-3cffec7b0034';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hazil tuyg‘usi". Bola ataylab biror narsani "noto‘g‘ri" qilib (masalan, bosh kiyimini oyog‘iga kiyib), sizga qarashi va kulishi mumkin. Bu unda hazilni tushunish va boshqalarning munosabatiga ta’sir ko‘rsatish qobiliyati shakllanayotganini bildiradi. Uning bu "o‘yini"ga zavq bilan qo‘shiling. Birgalikda kulish orangizdagi hissiy rishtani yanada mustahkamlaydi.') WHERE id = '0f7fea0c-bb47-4b7d-9391-ab4589f33670';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida "Balandlik va masofa". Bola endi zinadan yoki divandan tushayotganda masofani yaxshiroq chamalaydi. Unga doimo ehtiyot bo‘lishni va xavfsiz tushish usullarini (orqasi bilan) eslatib turing. Bu uning tana xavfsizligi qoidalarini o‘zlashtirishidagi muhim bosqichdir.') WHERE id = '6dd30633-3c9b-4455-9878-c9a89b329928';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Sakrash paytidagi harakat". Bola endi shunchaki bir joyda sakramaydi, balki sakrash vaqtida yo‘nalishini o‘zgartirishga harakat qiladi. Bu yirik motorika mushaklari harakatining yuqori darajada muvofiqlashganini ko‘rsatadi. U bilan birga yumshoq gilam ustida harakatli o‘yinlar o‘ynang. Bu unga ham energiyasini chiqarishga, ham tanasini yaxshiroq boshqarishga yordam beradi.') WHERE id = '85fd0d24-866e-4847-be35-912d99da58df';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hayvonlar va ularning bolalari". Bola hayvonlarning nomlarini allaqachon biladi, endi esa ularni bolalaridan (masalan, mushuk va mushukcha) farqlashga qiziqishi mumkin. Kitob o‘qiyotganda shu tafsilotlarga e’tibor qarating. Bu uning toifalar bo‘yicha fikrlash qobiliyatini ham, tabiatga bo‘lgan qiziqishini ham oshiradi.') WHERE id = 'ce938ec0-b1a1-418d-9c79-f5996a2ee822';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanishda "Iroda va chegaralar". Bola endi "Yo‘q" so‘zining kuchini to‘liq tushunadi va uni tez-tez ishlatadi. Bunday paytlarda xotirjam bo‘ling va unga tanlash imkonini berib, "yo‘q"ni "ha"ga aylantirishga harakat qiling. Sizning qat’iyatingiz va ayni paytdagi muloyim yondashuvingiz unga qoidalar doirasida erkin bo‘lishni o‘rgatadigan eng yaxshi saboqdir.') WHERE id = '699f4641-31b9-4174-a887-f0cb838a43e4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Iltimos qilish". Bola endi biror narsani xohlaganda shunchaki barmog‘i bilan ko‘rsatmaydi, balki "Ber" yoki "Iltimos" (yoki shunga o‘xshash bir undov) deya oladi. Har safar unga xushmuomala so‘zlarni qanday ishlatishni o‘rnak qilib ko‘rsating. Sizdan "Rahmat" yoki "Iltimos" degan so‘zlarni eshitishi uning kelajakdagi muloqot madaniyatiga poydevor yaratadi.') WHERE id = '0ffa5444-e49f-4507-b5e7-cc95f08b1d36';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurning rivojlanishi: "Rolli o‘yinlar murakkablashadi". Bola endi shunchaki ovqat tayyorlamaydi, balki o‘yinchoqlarini mehmonga chaqiradi, ularni "davolaydi" yoki "mashinaga o‘tqazib, ishga olib boradi". Bu uning xotirasidagi voqealarni qanday birlashtirayotganini ko‘rsatadi. U bilan birga bu rolli o‘yinlarda ishtirok eting — bu uning ijodkorligini yanada yuksaltiradi.') WHERE id = '24d4307d-0d0c-428b-a2fb-db25c78400d8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki tanibgina qolmay, ularni bir-biriga moslashtirishni ham puxta egallamoqda. Unga "Qizil paypog‘ingning juftini top" deganingizda buni to‘g‘ri bajarsa, bu uning vizual mantiqi rivojlanayotganidan dalolat beradi. Kundalik kiyinish paytida ranglarni tez-tez ta’kidlang: "Bugun yashil ko‘ylagingni kiyamizmi?". Bu uning lug‘at boyligidagi sifatlarni mustahkamlaydi.') WHERE id = '179a1147-4671-4989-8a35-24a67964487b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Bir oyoqda muvozanat saqlash". Bola endi bir necha soniyaga bo‘lsa-da, bir oyog‘ini yerdan ko‘tarib, muvozanatni saqlashga urinadi. Bu tananing og‘irlik markazini boshqarishni talab qiladigan murakkab muvofiqlashtirishdir. U bilan "Laylak o‘yini"ni o‘ynang. Bu ham maroqli, ham jismoniy rivojlanish uchun juda foydali.') WHERE id = '6a2ac5db-ce06-4c8b-b0f1-21122d14d9a3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt tushunchasining ilk belgilari". Bola "hozir", "keyin" kabi so‘zlar o‘rtasidagi farqni tushuna boshlaydi. Unga "Avval ovqatlanamiz, keyin bog‘ga boramiz" deganingizda kuta olsa, bu katta yutuqdir. Sabr qilish odati shakllanishi uchun harakatlaringiz orqali voqealar ketma-ketligini tushuntirishda davom eting.') WHERE id = '91b2f1d2-b8e0-4586-beb2-1ed7668e668d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Pazl yig‘ish mahorati". Bola endi 5-6 qismli oddiy pazllarni mustaqil yig‘a oladi. Rasmlarni vizual tarzda birlashtirish uning diqqatini jamlash va muammolarni hal qilish qobiliyatini rivojlantiradi. Uddalay olmasa, unga xotirjamlik bilan yo‘l-yo‘riq ko‘rsating, ammo uning o‘rniga bajarib qo‘ymang. Bu kichik "g‘alabalar" uning tafakkurini kuchaytiradi.') WHERE id = 'feada4a3-1665-4491-8ec1-8dc39ef9224c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '23-oyning so‘nggi o‘n kunligini boshlaymiz! Bola endi "Men" olmoshining ma’nosini to‘liq anglab, uni ishlatmoqda. "Men keldim", "Men yedim" kabi gaplar u o‘zini atrofdagilardan alohida shaxs sifatida ko‘rayotganini ko‘rsatadi. Uning mustaqil fikr bildirishini qo‘llab-quvvatlang va suhbatni davom ettiring: "Ha, sen mazali ovqatingni yeding, barakalla!".') WHERE id = '7aacd700-e4fe-464f-89ef-4b8e3945aa5a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Yugurayotganda yo‘nalishni o‘zgartirish". Bola endi tez yugurayotganda to‘satdan yo‘nalishini o‘zgartira yoki to‘siqlarni aylanib o‘ta oladi. Bu ham mushaklar kuchi, ham tez qaror qabul qilish qobiliyati rivojlanayotganidan dalolat beradi. Bog‘da u bilan "meni tut" o‘yinini o‘ynab, chaqqonligini oshiring.') WHERE id = 'a492f1d5-4125-4356-ab32-a3a06c3ae006';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Miqdor tushunchasi". Bola endi "bir" va "ko‘p" o‘rtasidagi farqni tushuna boshlaydi. Unga o‘yinchoqlarini ko‘rsatib, "Bu yerda ko‘p mashina bor" deb ayting va sanash ko‘nikmasiga ilk poydevor qo‘ying. Hozircha raqamlarni ketma-ket ayta olmasa ham, miqdorlar o‘rtasidagi farqni ko‘rib anglashi uning matematik tafakkuri shakllana boshlaganini ko‘rsatadi.') WHERE id = '6541c63d-d78c-444c-93ac-32836d55b462';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "San’at asarlari". Bola endi qalamni aniqroq ushlab, "yopiq chiziqlar" (doiraga o‘xshash shakllar) chizishga harakat qiladi. Unga turli rangdagi qalamlar bering va chizgan har bir shaklini biror narsaga o‘xshatib, uni ruhlantiring: "Qara, bu to‘pga o‘xshaydi!".') WHERE id = 'de8e6a20-ca58-4eb3-bdc2-7db3ed5bcda2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim yordam beraman". Bola sizga uy ishlarida yordam berishdan juda zavqlanadi. Unga "Kiyimlarni savatga solishga yordam ber" kabi haqiqiy vazifalarni topshiring. Bu uning ham motorikasini, ham oiladagi mas’uliyat hissini rivojlantiradi. Yordam berganidan keyin unga "Sen mening eng katta yordamchimsan" deb ayting.') WHERE id = 'f2819b1a-b1cb-4ed8-b546-aae23641438e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Odob qoidalari". Bola endi "Rahmat" va "Iltimos" so‘zlarini o‘rinli ishlata boshlashi mumkin. Albatta, bu sizning unga namuna bo‘lishingizga bog‘liq. Unga har safar biror narsa berganingizda yoki undan olganingizda bu so‘zlarni o‘zingiz ishlatib, namuna ko‘rsating. Bu uning kelajakdagi muloqot madaniyati uchun eng mustahkam poydevordir.') WHERE id = 'eb0307cc-cb5a-49a5-b989-e572cad76794';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda "Fasllar va ob-havo". Bola endi tashqaridagi ob-havo o‘zgarishlarini (yomg‘ir, quyosh, shamol) sezadi va ularga munosabat bildiradi. Derazadan qarab, "Yomg‘ir yog‘yapti", deya hodisalarni nomlang. Bu uning atrof-muhit bilan aloqasini mustahkamlaydi va so‘z boyligiga tabiatga oid yangi atamalarni qo‘shadi.') WHERE id = 'e5dc7560-975f-4493-9ff3-ea6744e46ec0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni nishonga tepish". Bola endi oldidagi to‘pni shunchaki tepmaydi, balki uni muayyan yo‘nalishga (masalan, darvoza tomon) yo‘naltirishga harakat qiladi. Bu ko‘rish diqqati va harakatlar muvofiqligining uyg‘unlashuvidir. Uyda u bilan yumshoq to‘p yordamida kichik "futbol" musobaqasini o‘tkazing.') WHERE id = 'f701f5d4-0488-45fc-bf57-a9b74d61b0af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xotira va ertaklar". Bola sevimli ertagini endi shu qadar yaxshi biladiki, siz gapni tugatmay qo‘ysangiz, u davom ettira oladi. Ertak o‘qiyotganda tanaffus qiling va uning davom ettirishini kuting. Bu uning ham xotirasini, ham voqealar ketma-ketligini tushunish qobiliyatini nihoyatda rivojlantiradi.') WHERE id = 'c61438a5-bdff-4ed0-b914-6e977fdb2bc1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy tayyorgarlik: 2 yoshga to‘lishiga sanoqli kunlar qoldi! Bola endi o‘z his-tuyg‘ularini yanada murakkab tarzda ifodalaydi. U to‘satdan quchoqlashingizni xohlashi yoki mustaqilligini namoyish etish uchun yugurib borib yashirinishi mumkin. Bu davrda u bilan sabr-toqat bilan muloqot qilish va har bir qadamida yonida ekaningizni his qildirish uning hissiy xavfsizligi uchun eng muhim qadamdir.') WHERE id = 'bcd3ac04-2293-413d-8bfd-ba0e21e03fe2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi o‘z didi va tanlovlarini qat’iy namoyish etadi. Qaysi kitobni o‘qishingiz yoki qaysi o‘yinchoq bilan o‘ynashingizni o‘zi hal qilishni xohlaydi. Unga shunday kichik yetakchilik imkoniyatlarini bering. Bu uning qaror qabul qilish qobiliyatini rivojlantiradi va o‘zini qadrli shaxs sifatida his etishiga yordam beradi.') WHERE id = 'b41a09b6-e8fc-4b09-b81c-400b678af920';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Dinamik muvozanat". Bola endi bir chiziq bo‘ylab yurishga yoki past bordyur chetidan (qo‘lidan tutganingizda) qadam tashlashga harakat qiladi. Bu tananing og‘irlik markazini boshqarish uchun ajoyib mashqdir. Bog‘da sayr qilayotganda yerga chizilgan chiziqlar ustidan yurish o‘yinini o‘ynab, uning harakatlar muvofiqligini mustahkamlang.') WHERE id = '5d42a805-244d-4112-9107-40ebc50ef785';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Uch so‘zli gaplar". Bola endi "Ona, suv ber", "Dada, parkka bor" kabi murakkabroq gaplar tuzadi. U o‘z ehtiyojlarini to‘liq ifodalay oladi. Uning gaplarini tasdiqlab, biroz kengaytiring: "Ha, hozir kel, suv ichamiz, keyin parkka boramiz". Bu uning grammatik tushunchasini rivojlantiradi.') WHERE id = '8ba75ebe-7968-4c36-9120-369b2e5d0ec2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Pazl yig‘ish mahorati" oshadi. Bola endi 6-8 bo‘lakli sodda pazllarni mustaqil yig‘a oladi. Buning uchun ham vizual tahlil, ham barmoq mushaklarining aniq harakatlari talab etiladi. Har safar rasmni to‘liq yig‘ganida quvonchingizni ko‘rsating, shunda uning murakkab topshiriqlarga qiziqishi ortadi.') WHERE id = '527f78da-7fbc-42ab-a36c-6bee3afe966e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim yig‘ishtiraman". O‘yinchoqlarni joyiga yig‘ish endi uning uchun shunchaki vazifa emas, balki mas’uliyatdir. Unga "Qani, mashinalarni o‘z joyiga qo‘yaylik" deganingizda sizga yordam bersa, bu tartib-intizomning poydevoridir. Bu odat kelajakda uning ozoda va tartibli bo‘lishi uchun juda muhim.') WHERE id = '4cae5197-2921-4caa-b98c-16f64a7694c8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Bo‘lishish va navbat kutish". Bola endi "hozir sizning navbatingiz" deyilganda biroz kutish kerakligini tushunadi. Sabr qilishni o‘rganish bu yosh uchun katta yutuqdir. Uni navbat bilan o‘ynaladigan o‘yinlarda (masalan, to‘pni bir-biringizga uzatishda) qo‘llab-quvvatlang. Sizning bunday sabrli yondashuvingiz uning jamiyatga moslashishini osonlashtiradi.') WHERE id = 'e3e7be7f-e682-47f1-bdf9-05213d301d28';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Bir xil va farqli". Bola endi bir turdagi buyumlarni (masalan, barcha hayvonlarni bir joyga, barcha mashinalarni boshqa joyga) guruhlay oladi. Unga "Bu yerda qaysi o‘yinchoq boshqalaridan farq qiladi?" kabi savollar berib, uning vizual mantiqini sinab ko‘ring. Toifalar asosida fikrlash uning bilish qobiliyatini yangi bosqichga olib chiqadi.') WHERE id = '9960803a-4e47-4edd-b50d-dc62d848c875';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Joyida sakrash va aylanish". Bola endi shunchaki sakramaydi, balki sakrayotganda tanasini burishga harakat qiladi. Bu yirik motorika mushaklarining yuqori darajadagi muvofiqlashuvidir. U bilan birga musiqa sadolari ostida faol "raqs" vaqtlarini tashkil qiling. Bu ham ko‘ngilochar mashg‘ulot, ham tana egiluvchanligi uchun ajoyib mashqdir.') WHERE id = 'b8a638df-098e-4767-9ebb-0f4df5304a5e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xotira va voqealar". Bola kun davomida yuz bergan oddiy bir voqeani (masalan, "Bog‘da it ko‘rdim") eslab, sizga aytib bera oladi. Uning hikoyalarini diqqat bilan tinglang va "Keyin nima bo‘ldi?" deb, voqealarni izchil bayon qilishiga yordam bering. Bu uning ham xotirasini, ham fikrini ifodalash qobiliyatini mustahkamlaydi.') WHERE id = '9fdcc45e-2b1e-4d3c-95a7-d7f5adca9ccb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy tayyorgarlik: 2 yoshga to‘lishiga atigi 50 kun qoldi! Bola endi o‘z his-tuyg‘ularini yanada chuqurroq namoyon etadi. U sizga bo‘lgan mehrini to‘satdan quchoqlash yoki o‘pish orqali ko‘rsatishi mumkin. Siz ham unga xuddi shunday mehr bilan javob bering. Bu hissiy mehr almashinuvi uning o‘zini xavfsiz va eng muhimi, "sevimli inson" sifatida his qilishi uchun eng katta ozuqadir.') WHERE id = '78317024-ad5b-4a00-86b5-ab43a417337b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki farqlabgina qolmay, ularning ko‘pchiligi nomini to‘g‘ri talaffuz qiladi. Unga "Ko‘k mashinani olib kel" deganingizda adashmasa, bu uning ko‘rish va so‘z xotirasi uyg‘un ishlayotganini ko‘rsatadi. Kundalik sayrlarda "Yashil barg", "Sariq quyosh" kabi ta’riflar bilan uning dunyosini rang-barang qilishda davom eting.') WHERE id = '85496aa4-c911-4bb2-8f2e-3e5a32779858';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Zinapoyada erkinlik". Bola endi bir qo‘lidan ushlaganingizda zinapoyadan har bir pog‘onaga bittadan oyoq qo‘yib (oyoqlarini navbatma-navbat almashtirib) chiqishga urinadi. Bu yirik motorika rivojidagi katta yutuqdir. Har doim yonida bo‘lib, uning xavfsizligini ta’minlang, ammo mustaqil qadam tashlashi uchun unga ishonch bering.') WHERE id = 'e1b72aca-8d9f-4f33-aedd-ed905b733dbf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Joylashuvni bildiruvchi so‘zlar". Bola "ustida", "ostida", "orqasida" kabi tushunchalarni endi harakatlari bilan ko‘rsata oladi. Unga "To‘pni stulning ostiga qo‘y" deb, kichik bir o‘yin o‘ynang. Bu topshiriqlar uning ham nutqni tushunishini, ham makonda mo‘ljal olish qobiliyatini jadal rivojlantiradi.') WHERE id = '455a2119-ac1e-44e4-8b8c-20b0405c50d6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Burash va aylantirish mahorati". Bola butilka qopqoqlari va o‘yinchoq vintlarini ishonch bilan ochib-yopa oladi. Bu bilak mushaklarining chaqqonligi uchun ajoyib mashqdir. Unga turli o‘lchamdagi xavfsiz idishlarni berib, bunday "mexanik" kashfiyotlarga bo‘lgan qiziqishini qo‘llab-quvvatlang.') WHERE id = '61305052-b44e-493c-a6f8-ffe876e0e01e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola 23-oyining oxiriga yaqinlashmoqda. Endi u o‘ziga nafaqat "men" deb murojaat qilinishini, balki ismi bilan chaqirilishini ham to‘liq tushunadi. U bilan suhbatlashayotganda "Buni sen qildingmi?" deb so‘raganingizda, faxr bilan "Ha" desa, bu uning o‘zligini anglash qobiliyati rivojlanayotganidan dalolat beradi. Yutuqlarini ismini aytib maqtang: "Barakalla, (bolaning ismi), sen buni uddalading!".') WHERE id = '9459dc0c-afe8-45b3-b94d-dd65b48126f2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlarda "Erkin yugurish va to‘xtash". Bola endi yugurayotganda yiqilmasdan birdan to‘xtay oladi. Bu uning tormozlanish nazorati (inhibitory control) tizimi va mushaklari qanchalik rivojlanganini ko‘rsatadi. U bilan bog‘da "Yugur va to‘xta!" o‘yinini o‘ynang; bu ham maroqli, ham harakatlarni muvofiqlashtirish uchun foydali.') WHERE id = 'ecf7ae38-688c-4cbe-90a0-7112da130536';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Savol berish davri". Bola ko‘p narsalarning nomini bilganidan so‘ng, endi ular nima uchun ishlatilishini so‘rashga moyil bo‘ladi. U biror buyumni ko‘rsatib, "Bu?" deganida, unga faqat nomini emas, vazifasini ham tushuntiring: "Bu soyabon, u yomg‘irdan himoyalanish uchun kerak". Sizning batafsil javoblaringiz uning dunyoqarashini tez kengaytiradi.') WHERE id = 'cb8ab97b-604a-4728-ac40-ae0675a2ce85';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Tik va yotiq chiziqlar". Bola endi qalamni ishonchliroq ushlaydi va qog‘ozga maqsadli ravishda to‘g‘ri chiziqlar chizadi. Unga turli rangdagi qalamlar va katta qog‘ozlar berib, "rassomlik" mahoratini qo‘llab-quvvatlang. Bu kelajakdagi yozish ko‘nikmalari uchun muhim poydevordir.') WHERE id = 'b5be883e-3ec9-4583-905f-d5eaa6d996f3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov" eng yuqori bosqichda. Bola endi nima yeyishi, qaysi o‘yinchoq bilan o‘ynashi va hatto qaysi yo‘ldan yurishini o‘zi hal qilishni istaydi. Unga cheklangan tanlovlar bering: "Bugun olma yeysanmi yoki banan?". Bu uning qaror qabul qilish qobiliyatini oshiradi hamda o‘zini boshqariladigan emas, balki boshqaruvchi shaxs sifatida his qilishiga yordam beradi.') WHERE id = 'd071c76a-b155-43af-a2a1-de9194ca4c11';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Ramziy taqlid". Bola endi sizning uydagi vazifalaringizga taqlid qiladi: "ovqat pishiradi", "telefonda gaplashadi", "uyni tozalaydi". Bunday taqlid uning dunyoni o‘rganish usulidir. Unga kichik o‘yinchoq supurgi yoki idishlar berib, sizning "yordamchingiz" bo‘lishi uchun sharoit yarating.') WHERE id = 'ee398ccc-6f29-41df-b0a4-1bb95b88b1a5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim kiyinaman" bosqichi murakkablashib bormoqda. Bola endi fermuarni (siz boshlab berganingizdan keyin) tortishga yoki katta tugmalarni yechishga urinadi. Bu jarayonda unga xalaqit bermang, shoshiltirmang. Biror ishni mustaqil bajara olayotganini ko‘rish uning uchun o‘ziga bo‘lgan ishonchning eng katta manbaidir. Kichik yutuqlari uchun uni albatta rag‘batlantiring.') WHERE id = 'f6d69242-03a3-4cc8-a444-aac7bbd07185';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Empatiya" kuchayadi. Bola sizning yoki boshqa bir bolaning xafa bo‘lganini ko‘rsa, yoningizga kelib o‘yinchog‘ini taklif qilishi yoki sizni quchoqlashi mumkin. Bu uning hissiy intellekti (EQ) rivojlanayotganining ajoyib belgisidir. Uning bu g‘amxo‘rligini "Meni qo‘llab-quvvatlaganing uchun katta rahmat" deb qadrlang.') WHERE id = '98c8accf-ca7d-4901-b417-a3bce7f325f2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda "Shakl va o‘lcham". Bola endi bir xil shaklning (masalan, doiraning) katta va kichik variantlarini farqlay oladi. Unga turli o‘lchamdagi idishlarni bir-birining ichiga joylashni ko‘rsating. Bu kelajakdagi matematik tafakkurining asosi bo‘lgan "tartiblash" ko‘nikmasini rivojlantiradi.') WHERE id = 'bfdb17de-cc0d-437c-870c-13801051e507';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va nishonga yo‘naltirish". Bola endi to‘pni shunchaki tepmaydi, balki uni muayyan tomonga yo‘naltirishga harakat qiladi. Bu ko‘rish diqqati va harakatlarni muvofiqlashtirishning uyg‘unlashuvidir. U bilan uyda yoki bog‘da "kichik darvoza" yasab, unga to‘p tepish o‘yinini o‘ynang. Bu uning oyoq mushaklarini mustahkamlaydi va harakatlar aniqligini oshiradi.') WHERE id = 'a17dc9b7-c84f-4802-8431-7aad7b966067';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hikoya qilishga urinishlar". Bola kun davomida ko‘rgan qiziqarli narsasini (masalan, "Katta itni ko‘rdim") sizga aytib berishga oshiqadi. Uning hikoyasini oxirigacha tinglang va savollar bilan davom ettiring: "Itning rangi qanday edi?". Bu uning xotirasini ham, o‘z fikrini ifodalash ko‘nikmasini ham mustahkamlaydi.') WHERE id = 'daff24e3-d7cd-46e0-9c7d-75e6a3417d53';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi "Men xohlamayman" deb o‘z istagini qat’iy bildirishi mumkin. Bunday paytlarda u bilan tortishish o‘rniga, unga tanlash imkonini berib, diqqatini boshqa narsaga qarating. Sizning sabr-toqatingiz va izchil qoidalaringiz bolada xavfsizlik hissini shakllantiradi. 2 yoshga to‘lishiga atigi 40 kun qoldi – siz juda katta ishni uddalayapsiz!') WHERE id = '30c55932-1036-4bc0-a31f-1b927f46a841';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Qismlardan butun shaklni yig‘ish". Bola endi 3-4 qismli oddiy pazllarni (boshqotirmalarni) ko‘rib birlashtira oladi. Bu diqqatni jamlash va muammolarni hal qilish ko‘nikmasini rivojlantiradi. Uddalay olmasa, unga xotirjam ohangda yordam bering: "Qara, bu itning dumi, u qayerda bo‘lishi mumkin?". Bu kichik g‘alabalar uning idrokini mustahkamlaydi.') WHERE id = '6ae9f735-9ae2-46e6-8771-fa1ead2cea34';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va yugurish". Bola endi yugurayotganda oldidagi to‘pni muvozanatini yo‘qotmasdan tepa oladi. Bunda harakat tezligi va dinamik muvozanat bir vaqtning o‘zida boshqariladi. U bilan hovlida yoki bog‘da "futbol" o‘ynab, harakatlarining aniqligini oshiring. Siz bilan birga harakat qilish uning uchun eng katta zavqdir.') WHERE id = '17868f49-652d-4efe-940b-fac27063768e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xotirani ifodalash". Bola kecha ko‘rgan yoki boshidan kechirgan voqeani (masalan, "Bog‘da qush ko‘rdim") eslab, sizga aytib bera oladi. Uning hikoyalarini diqqat bilan tinglang va "Qush nima qilayotgan edi?" deb suhbatni davom ettiring. Bu uning xotirasi va o‘z fikrini ifodalash ko‘nikmasini nihoyatda kuchli rivojlantiradi.') WHERE id = 'd99ef035-085a-4da0-b18e-ddf8dda326d1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 700 kunni yakunladik! 2 yoshga to‘lishiga atigi bir oy (30 kun) qoldi. Farzandingiz endi go‘daklik davridan butunlay chiqib, o‘z fe’l-atvori, istaklari va qobiliyatlariga ega kichik bir "inson"ga aylandi. Bugun u bilan eng sevimli o‘yinini o‘ynab, bosib o‘tilgan bu katta yo‘lni nishonlang. Siz ajoyib yo‘lni bosib o‘tdingiz, Ona!') WHERE id = '0e3a52c6-9f66-42e2-994a-692b5b642618';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '24-oyga, ya’ni bolaning 2 yoshga to‘lishiga tomon so‘nggi qadamlarni boshlaymiz! Bola endi o‘z buyumlari va kiyimlarini juda yaxshi taniydi. Unga "Kiyim javonidan o‘z ko‘ylagingni olib kel" deganingizda, buni bajarsa, bu uning xotirasi hamda o‘ziga tegishlilik hissi mustahkamlanayotganini ko‘rsatadi. Bunday kichik topshiriqlar uning o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = 'f1337afd-8cd4-4800-85b9-83874ec33ec8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Bordyur ustida muvozanat saqlash". Bola endi qo‘lidan ushlaganingizda past bordyurlar ustida yurishga qiziqish bildiradi. Bu uning murakkab muvozanatni saqlash qobiliyatini rivojlantiradi. Xavfsiz joylarda bu qiziqishini qo‘llab-quvvatlang, chunki bu kelajakda yanada murakkab jismoniy harakatlarni bajarish uchun asos bo‘ladi.') WHERE id = '48e8258d-7e1b-417f-861b-84e4a830fb92';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Olmoshlarni to‘g‘ri qo‘llash». Bola endi «Men», «Sen», «U» kabi olmoshlarni gap ichida to‘g‘riroq qo‘llay boshlaydi. Masalan: «Men och qoldim» yoki «Sen kel». Uning bu rivojlanishini qo‘llab-quvvatlash uchun siz ham murojaat qilganingizda olmoshlarga urg‘u bering. Bu uning ijtimoiy muloqot qilish ko‘nikmasini jadal rivojlantiradi.') WHERE id = '6c0e87a6-05f9-4b6b-826c-adb939561dc2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Qurilish mahorati». Bola endi kublarni shunchaki ustma-ust qo‘ymaydi, balki ulardan «uy», «poyezd» yoki «devor» kabi shakllar yasaydi. Bu uning ko‘rish-fazoviy tafakkuri yangi bosqichga o‘tganini ko‘rsatadi. Uning «qurilmalariga» qiziqish bildiring va «Bu yerga kim keladi?» kabi savollar bering.') WHERE id = 'd0a7b08b-aa7f-465e-8cfb-7b1cbe914d24';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Rolli o‘yinlarning murakkablashishi». Bola endi bir nechta ketma-ket harakatdan iborat o‘yinlarni o‘ynaydi: masalan, o‘yinchoq ayiqchasini «yuvadi», «quritadi» va keyin «uxlatadi». Bu uning xotirasidagi kundalik hayot ssenariylarini qanday izchil birlashtirayotganini ko‘rsatadi.') WHERE id = '290cdbcc-b930-4c04-ac8f-c9e9a99f2bd8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil ovqatlanish mahorati». Bola endi ovqatni sanchqi bilan sanchib, og‘ziga olib borishni juda yaxshi uddalaydi. Unga mustaqil ovqatlanish uchun ko‘proq imkoniyat bering. Stolning biroz ifloslanishi uning mayda motorikasi va o‘ziga xizmat qilish mas’uliyatini rivojlantirish uchun kichik bir badaldir.') WHERE id = 'a907e23d-d22f-4f12-8eba-ed2e00af2852';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida «Katta-Kichik-O‘rtacha». Bola endi faqat ikkita emas, uchta turli o‘lchamni ham farqlay boshlashi mumkin. Unga bir xil o‘yinchoqning uch xil o‘lchamdagisini bering va «Eng kattasini menga ber» deb tekshirib ko‘ring. Bu uning matematik taqqoslash ko‘nikmasi uchun asosdir. Har safar to‘g‘ri topganida uni rag‘batlantiring.') WHERE id = '228f5557-8af1-45e0-8eea-dab6d6ab319d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Ikki oyoqda oldinga sakrash». Bola endi faqat turgan joyida emas, biroz oldinga ham sakray oladi. Buning uchun oyoq mushaklarining keskin kuchi va tana harakatlarini muvofiqlashtirish talab etiladi. U bilan bog‘da «Quyonlar maysazorda sakraydi» o‘yinini o‘ynang. Bu ham qiziqarli, ham yirik motorika uchun ajoyib mashqdir.') WHERE id = 'fed4cb8e-d23c-4ef3-9fb0-62697ac89488';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Xulosa chiqarish». Bola endi ayrim voqealarning natijasini oldindan ayta oladi. Masalan, siz oyoq kiyimingizni olayotganingizda: «Tashqariga chiqamizmi?» deb so‘raydi. Bu uning mantiqiy bog‘lanishlarni qanchalik yaxshi tushunayotganini ko‘rsatadi. Uning bunday savollarini tasdiqlang va qo‘shimcha ma’lumot bering: «Ha, borib qushlarga non beramiz».') WHERE id = '0aaeb1eb-0155-44f3-b404-be39c9061780';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy tayyorgarlik: 2 yoshga to‘lishiga atigi 20 kun qoldi! Bola endi o‘z his-tuyg‘ularini yanada aniqroq ifodalaydi va sizga bo‘lgan mehrini «Sizni yaxshi ko‘raman» degan so‘zlar (yoki o‘z tilida shunga o‘xshash ma’nodagi ifoda) va imo-ishoralar bilan ko‘rsatadi. Shu kunlarda u bilan o‘tkazgan har bir lahzangiz uning hissiy olamida o‘chmas iz qoldiradi. Siz ajoyib ona va yo‘l ko‘rsatuvchisiz!') WHERE id = 'f640772a-39c6-4d33-9c3f-64bd16ad5ed0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola hozir «O‘zim kiyinaman» davrining eng qat’iy bosqichida. Shimini kiyish yoki oyoq kiyimini (qiyin bo‘lsa ham) oyog‘iga kiyishga intilishi — uning mustaqillik istagining ifodasidir. Harakat qilib ko‘rishi uchun unga bir necha daqiqa ko‘proq vaqt bering. Bu sabringiz uning kelajakdagi o‘ziga bo‘lgan ishonchi uchun eng katta sarmoyadir.') WHERE id = 'e264db36-ff8b-4ffc-8d0c-2a9a86b8e80e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlarda «Bir joyda aylanish». Bola endi o‘z atrofida aylanishni va buning natijasida paydo bo‘ladigan «bosh aylanishi» hissini qiziqish bilan qabul qiladi. Bu uning vestibulyar (muvozanat) tizimi rivojlanayotganidan dalolat beradi. Xavfsiz va yumshoq joyda u bilan birga raqsga tushib, bu yangi hissiyotni o‘rganishiga imkon yarating.') WHERE id = 'c1b5ac77-3624-4a68-8f84-6255305e6a71';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Ko‘p so‘zli gaplar». Bola endi 3-4 ta so‘zni birlashtirib, murakkab fikrlarini ifodalaydi: «Ona, men katta mashina xohlayman». Uning gaplarini tuzatmang, shunchaki to‘g‘ri variantini takrorlab javob bering: «Ha, sen o‘sha katta qizil mashina bilan o‘ynashni xohlaysanmi?». Bu unga til tuzilishini asta-sekin o‘zlashtirishga yordam beradi.') WHERE id = '4ada0942-f71a-4215-a9a2-e770a9dcbe42';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Badiiy ijod». Bola endi qalamni yanada ishonchli ushlab, qog‘ozga aylana shaklidagi chiziqlar chizishga harakat qiladi. Bu kelajakda yozish uchun zarur bo‘ladigan mushaklar muvofiqlashuvining asosidir. Unga turli rangdagi bo‘yoqlar va katta qog‘ozlar berib, tasavvurini erkin namoyon etishiga imkon yarating.') WHERE id = 'c206267a-2d42-4d2c-8a75-f79f89a1455a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Bo‘lishish va chegara". Bola endi ayrim buyumlar o‘ziga, boshqalari esa boshqa odamlarga tegishli ekanini tushunadi. Unga o‘yinchog‘ini bo‘lishish hali ham qiyin bo‘lishi mumkin. Unga "Bu hozir seniki, birozdan keyin do‘sting o‘ynaydi" deb, navbat tushunchasini singdiring. Bu ijtimoiy moslashuv uchun eng muhim qadamlardan biridir.') WHERE id = '0337bbc8-021f-48c3-b2d6-9d07615b2eb6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men yordam beryapman". Bola sizga uy ishlarida yordam berishdan juda zavqlanadi. Kiyimlarni savatga solish yoki dasturxonga non qo‘yish kabi kichik vazifalar unga o‘zini oilaning "muhim a’zosi"dek his qilishiga yordam beradi. Uning bu ishtiyoqini maqtang: "Sen bo‘lmaganingda, men buni ancha kech tugatardim!".') WHERE id = '176cc57c-d49b-4d93-9ce5-5829f43afd94';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Ranglarning nomi". Bola endi ranglarni shunchaki ajratibgina qolmay, ularning ko‘pchiligi nomini to‘g‘ri talaffuz qiladi. Bog‘da sayr qilayotganda "Qani, bu yerda yashil barg qayerda?" yoki "Menga sariq gulni ko‘rsat" deb, bilimlarini amalda qo‘llashiga yordam bering. Bu uning ko‘rish va so‘z xotirasini o‘zaro bog‘laydi.') WHERE id = 'b1599687-8b9b-4b36-972d-e646da9ca057';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni yelka uzra otish". Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni maqsadli ravishda oldinga yoki siz tomonga otishga harakat qiladi. Bu qo‘l mushaklari va nishonni idrok etish qobiliyati rivojlanayotganini ko‘rsatadi. U bilan "Kim to‘pni savatga tushira oladi?" o‘yinini o‘ynab, aniqligini oshiring.') WHERE id = 'a5dba3a5-d849-43ef-ab12-3acff84027fc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Iltimos va xushmuomalalik". Bola endi biror narsa istaganda shunchaki barmog‘i bilan ko‘rsatmaydi, balki "Ber" yoki "Iltimos" deb aytishga harakat qiladi (hatto o‘zicha aytsa ham). Sizning xushmuomala munosabatingiz uning muloqot uslubini shakllantiradi. Har safar "rahmat" deganingizda, u ham bu odobni tabiiy ravishda o‘zlashtiradi.') WHERE id = 'd8b07d2d-d5ae-44e4-8e83-13117a3ef758';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy tayyorgarlik: 2 yoshga to‘lishiga atigi 10 kun qoldi! Bola endi o‘z his-tuyg‘ularini (quvonch, jahli chiqishi, uyalish) juda aniq namoyon qiladi. Uning bu hislarini sabr bilan qabul qiling va nomlab bering: "Sen hozir xursandsan, chunki bog‘ga ketyapmiz". His-tuyg‘ularni nomlash bolaga o‘z ichki dunyosini anglash va kelajakda o‘zini boshqarishni o‘rganishga yordam beradi.') WHERE id = '5b177d90-0a27-4e2b-8501-6cbcb2351fef';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '2 yoshga to‘lishiga atigi 10 kun qoldi! Bola endi o‘z shaxsiyatini to‘liq anglaydi. Ko‘zguda o‘ziga qarab, ismini aytadi yoki «Bu men!» deb ishora qiladi. O‘zligini anglash uning kelajakdagi o‘ziga ishonchi uchun poydevordir. U bilan ko‘zgu qarshisida turib, qanchalik ulg‘aygani va nimalarni qila olishini birgalikda nishonlang.') WHERE id = '391d8114-3346-495b-b8f3-45861173d919';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda «Murakkab yugurish». Bola endi yugurayotganda yo‘lidagi to‘siqlarni chaqqonlik bilan aylanib o‘ta oladi. Bu jismoniy kuch va tez qaror qabul qilish qobiliyatining uyg‘unligidir. Uyda yoki hovlida uning uchun kichik «to‘siqlar yo‘lagi» yaratib, chaqqonligini sinab ko‘rishiga imkon bering.') WHERE id = '23f145d6-39f1-4e1e-84f1-49d36b707443';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutq rivojlanishida «Hikoyachi» bosqichi. Bola endi kun davomida yuz bergan oddiy voqeani (masalan, «Qush uchib ketdi», «Muzqaymoq yedim») eslab, sizga aytib beradi. Uning bu kichik hikoyalarini diqqat bilan tinglang va savollar bilan to‘ldirishiga yordam bering. Bu uning xotirasini hamda voqealar o‘rtasida mantiqiy izchillik o‘rnatish qobiliyatini mustahkamlaydi.') WHERE id = 'c8794b59-4f44-4d01-9dfd-9f86547c80bb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Kitobga mehr». Bola endi yupqa qog‘ozli sahifalarni yirtmasdan, birma-bir varaqlay oladi. U sevimli ertak kitobini olib kelib, o‘qib berishingiz uchun tizzangiz ustiga qo‘yadi. Bu odat uning til rivoji va siz bilan bo‘lgan hissiy aloqasi uchun beqiyos ahamiyatga ega. O‘qiyotganda rasmlar haqida savollar bering.') WHERE id = '25aab72e-4248-42bb-9009-a3467dd34bf8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Ilk do‘stliklar». Bola endi boshqa bolalar bilan shunchaki yonma-yon o‘ynamaydi, balki ularga o‘yinchoq taklif qiladi yoki birga yuguradi. Bular ijtimoiy hamkorlikning dastlabki haqiqiy qadamlaridir. Uning bunday ijobiy ijtimoiy muloqotlarini rag‘batlantiring va baham ko‘rishga tayyorligi uchun maqtang.') WHERE id = 'fbc5e912-7941-46bd-9137-7aea112e7d13';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil gigiyena». Bola endi qo‘llarini sovunlab yuvishga va sochiq bilan quritishga intiladi. Bu o‘ziga xizmat qilish ko‘nikmalari uning mustaqillik tuyg‘usini rivojlantiradi. Unga bo‘yiga mos sharoit yaratib bering, shunda bu gigiyena odatlari kundalik hayotining tabiiy qismiga aylanadi.') WHERE id = 'e689f8a3-742e-457c-849e-63c06d7af7c0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida «Tartiblash va mantiq». Bola endi 4-5 ta buyumni o‘lchamiga qarab (kattadan kichikka) tartiblay oladi. Bu matematik tafakkurning eng dastlabki poydevoridir. Unga turli o‘lchamdagi kublar yoki idishlar berib, bu tartiblash ko‘nikmasini mashq qildiring. Uning har bir muvaffaqiyatli «tartibi» miyasida yangi neyron aloqalarni hosil qiladi.') WHERE id = 'd3ed6715-8284-423a-bbce-cfe0156fda68';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Ikki oyoqda oldinga sakrash». Bola endi faqat turgan joyida emas, balki bir necha santimetr oldinga ham sakray oladi. Buning uchun oyoq mushaklarining keskin kuchi va mukammal muvozanat talab etiladi. Bog‘da u bilan «Chuqurdan sakrab o‘tish» o‘yinini o‘ynang. Bu ham qiziqarli o‘yin, ham o‘z tanasini boshqarish mashqidir.') WHERE id = '710d761b-996a-4661-a9e2-1515ed31c7a0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Men kimman?». Bola endi o‘z ismini, yoshini (hatto barmoqlari bilan bo‘lsa ham) va jinsini ayta oladi. Bu uning o‘zligini anglashidagi eng yuqori bosqichdir. U bilan ertangi katta kun haqida gaplashing: «Ertaga sen 2 yoshli katta bola bo‘lasan!».') WHERE id = 'ee27a56e-6e80-46b6-8a93-8ee183712978';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz! Bugun bolangiz roppa-rosa 2 yoshga to‘ldi! Siz 730 kun davomida beqiyos sabr-toqat, mehr va mehnat ko‘rsatdingiz. Farzandingiz endi chaqaloqlik davridan chiqib, dunyoni kashf etishga tayyor mitti shaxsga aylandi. Bu katta kunni u bilan birga sevimli o‘yinlarini o‘ynab nishonlang. Barakalla sizga, Onajon!') WHERE id = '493d8af7-6247-4790-9dba-5fe6ecd538f7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hayotining uchinchi yilidagi ilk kunga xush kelibsiz! Bola endi 2 yoshga to‘ldi va o‘zini «katta» his qilmoqda. Bu davrda u o‘z buyumlari va o‘yinchoqlariga egalik hissini kuchliroq namoyon qila boshlaydi. Unga o‘z xonasida yoki o‘yin burchagida kichik tartib-qoidalar yaratishiga ruxsat bering. Bu uning mas’uliyat hissini shakllantiradi.') WHERE id = 'e1193c8b-9caf-42cc-b0d1-380bfd68848e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlanishda «Zinadan erkin chiqish». Bola endi zinadan har bir pog‘onada oyoqlarini navbat bilan almashtirib va faqat bir qo‘lidan ushlab turilganda ko‘tarila oladi. Bu uning son mushaklari va muvozanat markazi qanchalik kuchayganini ko‘rsatadi. Xavfsizlik qoidalarini eslatib, unga ishonch bag‘ishlang.') WHERE id = '23cbdeb8-6ec7-49eb-b8f0-c4ae1a3cb46c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "So‘z boyligining jadal o‘sishi". Bola endi har kuni bir nechta yangi so‘zni o‘rganadi va 3-4 so‘zdan iborat mazmunli gaplar tuzadi. Masalan: "Men parkka borishni xohlayman". U bilan suhbatlashganda ochiq savollar bering: "Parkda nima qilishni xohlaysan?". Bu uning ham tasavvurini, ham fikrini ifodalash qobiliyatini rivojlantiradi.') WHERE id = 'c49d7f6c-cef1-458f-99cb-da68585b7ac5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Doira chizish". Bola endi qalamni ishonchliroq ushlab, qog‘ozga taxminan doira shakllarini chizishga urinadi. Bu uning qo‘l va ko‘z muvofiqlashuvi yangi bosqichga ko‘tarilganini ko‘rsatadi. Unga rang-barang qalamlar va katta qog‘ozlar berib, "ilk rasmlarini" chizishi uchun sharoit yarating.') WHERE id = '448009d5-07ef-4006-89f4-993bbe989179';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mustaqillik: "Men o‘zim kiyinaman". Bola endi paypoqlarini yechishdan tashqari, ularni kiyishga yoki kiyish oson bo‘lgan shimini yuqoriga tortishga harakat qiladi. Bu jarayon uzoq davom etsa ham, uni shoshirmang. Biror ishni o‘zi uddalashi uning uchun eng katta "mukofotdir". Sizning sabr-toqatingiz uning o‘ziga bo‘lgan ishonchini mustahkamlaydi.') WHERE id = 'ae5217ae-ff5f-4178-a4dd-001e8d391224';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Navbat tushunchasi". Bola endi arg‘imchoqda yoki sirpanma tepaligida navbat kutish kerakligini tushunadi. "Hozir sening navbating, keyin do‘stingniki" degan jumla endi uning uchun aniqroq ma’no kasb etadi. Bu ijtimoiy moslashuv va sabr qilishni o‘rganishning eng muhim bosqichlaridan biridir.') WHERE id = 'fd888eb3-7169-4c50-bc0d-f0696ed103ff';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda "Ranglarni guruhlash". Bola endi 4-5 xil rangni bir-biridan aniq ajratadi va ularning ko‘pchiligi nomini biladi. Undan "Barcha ko‘k o‘yinchoqlarni menga ber" deb so‘rab, kichik sinov o‘tkazing. Bunday o‘yinlar uning ko‘rish orqali tahlil qilish qobiliyati va xotirasini mustahkamlaydi.') WHERE id = '6aeca11f-b490-4362-b41c-539703e28816';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashuv: "To‘p tepish". Bola endi yugurayotganda oldidagi to‘pni muvozanatini yo‘qotmay, mo‘ljal tomon tepa oladi. Bunda harakat va diqqatni bir nuqtaga jamlash birlashadi. U bilan hovlida kichik "futbol" musobaqasi o‘tkazib, chaqqonligini oshiring.') WHERE id = 'da17a594-1250-4f85-98b1-50f0b6588294';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Nega?" savolining boshlanishi. Bola atrofidagi barcha narsalarning sababiga qiziqa boshlaydi. "Bu nega bunday?" degan savolga sodda va rost javoblar bering. Sizning tushuntirishlaringiz uning ongida dunyoning mantiqiy xaritasini yaratadi. Uning savollarini hech qachon javobsiz qoldirmang — bu uning o‘rganishga bo‘lgan ishtiyoqini oshiradi.') WHERE id = 'f3d92e61-3d30-4ede-90d4-27478dd2115f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanish: "Mustaqillik va chegaralar". Bola ba’zan hamma narsani o‘zi qilishni xohlaganida, ammo uddalay olmaganida keskin munosabat bildirishi mumkin. Bunday paytlarda xotirjam bo‘ling va "Tushunaman, sen buni o‘zing qilishni xohlaysan", deb uning his-tuyg‘usini ifodalab bering. Sizning tushunishingiz unda his-tuyg‘ularini boshqarish qobiliyatini shakllantiradi.') WHERE id = '1f37d9cd-995a-4d88-97e4-8b7fdb37e3d8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "Men" olmoshining ma’nosini to‘liq anglagan holda ishlatadi. "Men keldim", "Men yedim" kabi gaplar uning o‘zini atrofdagilardan alohida shaxs sifatida ko‘rayotganini ko‘rsatadi. Uning bunday mustaqil ifodalarini qo‘llab-quvvatlang va suhbatni kengaytiring: "Ha, sen mazali ovqatingni yeding, barakalla!".') WHERE id = 'bf78ea68-2a1f-4194-9ef3-62146ea4799d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Ikki oyoqda oldinga sakrash". Bola endi nafaqat turgan joyida, balki biroz oldinga ham sakray oladi. Bu tana koordinatsiyasining yuqori darajasidir. U bilan bog‘da "Quyonchalar maysazorda sakraydi" o‘yinini o‘ynang. Bu yirik motorika uchun ajoyib mashqdir.') WHERE id = 'ce99df1c-1b81-4d41-b95d-9180c49c6d9f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sabab-oqibat" bog‘lanishlari. Bola endi hodisalar o‘rtasidagi bog‘liqlikni tushunadi: "Yomg‘ir yog‘yapti, ho‘l bo‘ldim" yoki "Ovqat issiq, pufla". Uning bunday mantiqiy fikrlarini maqtang. Bu uning ham nutqi, ham mavhum fikrlash qobiliyati qanchalik rivojlanganini ko‘rsatadi.') WHERE id = 'bcee9d16-cb48-4f63-9295-23b44110e7d6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Burash va aylantirish mahorati". Bola butilka qopqoqlari va o‘yinchoq vintlarini ishonch bilan ochib-yopa oladi. Bu bilak mushaklarining chaqqonligi uchun ajoyib mashqdir. Unga turli o‘lchamdagi xavfsiz idishlarni berib, bu kashf qilishga bo‘lgan qiziqishini qo‘llab-quvvatlang.') WHERE id = 'bff29c40-0fa8-45dd-982c-f35a2f18ac52';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Rolli o‘yinlarning murakkablashuvi". Bola endi bir nechta ketma-ket harakatlardan iborat o‘yinlarni tashkil qila oladi: masalan, o‘yinchoq ayiqchasini "yuvadi", "quritadi" va keyin "uxlatadi". Bu uning xotirasidagi kundalik hayot ssenariylarini qanday izchil birlashtirayotganini ko‘rsatadi.') WHERE id = 'd343f65f-f46a-44dd-a5fc-a51c1510c094';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil ovqatlanish". Bola endi sanchqi va qoshiqdan shu qadar mohirona foydalanadiki, deyarli hech narsani to‘kib yubormaydi. Unga ovqatini o‘zi boshqarishi uchun to‘liq imkoniyat yarating. Bu uning to‘yganini anglab yetishi va o‘ziga bo‘lgan ishonchi uchun juda muhim.') WHERE id = '61ba4f1e-aa7b-426a-97ad-a9a4240347af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Qismlardan butunni yig‘ish". Bola endi 4-6 qismli oddiy pazllarni (boshqotirmalarni) tasvirga qarab birlashtira oladi. Bu diqqatni jamlash va muammolarni hal qilish ko‘nikmasini rivojlantiradi. Uddalay olmasa, unga xotirjam ohangda yordam bering: "Qara, bu itning dumi, u qayerda bo‘lishi mumkin?".') WHERE id = 'd008eb87-e4b7-4791-98e4-80774b7e5fc4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni yelka ustidan otish". Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni yelka ustidan (overhand) oldinga otishga harakat qiladi. Bu harakat butun tana muvofiqligini talab qiladi. U bilan bog‘da "Kim to‘pni uzoqroqqa otadi?" o‘yinini o‘ynang.') WHERE id = '018d47a4-b94c-4bab-a923-24c091f9e302';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Iltimos va xushmuomalalik". Bola endi biror narsa xohlaganda shunchaki barmog‘i bilan ko‘rsatmaydi, balki "Ber" yoki "Iltimos" (hatto o‘z tilida bo‘lsa ham) deyishga harakat qiladi. Sizning xushmuomala munosabatingiz uning muloqot uslubini shakllantiradi. Har safar "rahmat" deganingizda, u ham bu odobni tabiiy ravishda o‘zlashtiradi.') WHERE id = '11cb7320-ce82-47a0-a231-8d9923b30f4a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy tayyorgarlik: "Qo‘rquv va tasavvur". Bu yoshda bolalar ba’zan qorong‘ilikdan yoki ayrim tovushlardan qo‘rqa boshlashi mumkin. Bu tasavvur rivojlanayotganining belgisidir. Uning qo‘rquvi ustidan kulmang, shunchaki yonida bo‘ling, bag‘ringizga bosing va o‘zini xavfsiz his qilishiga yordam bering. Sizning qo‘llab-quvvatlashingiz uning hissiy barqarorligini oshiradi.') WHERE id = '4edde2f0-76ee-4d3a-a2af-2d7d71d87764';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki tanibgina qolmay, ularni bir-biriga moslashtirishni ham puxta o‘zlashtirmoqda. Unga "Qizil paypog‘ingning juftini top" deganingizda buni to‘g‘ri bajarsa, bu uning vizual mantiqi rivojlanayotganidan dalolat beradi. Kundalik kiyimlarida ranglarni tez-tez ta’kidlang: "Bugun yashil ko‘ylagingni kiyamizmi?". Bu uning lug‘atidagi sifatlarni mustahkamlaydi.') WHERE id = 'f4611a68-9983-4caf-808b-4616cf4c60d5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Bir oyoqda muvozanat saqlash". Bola endi bir necha soniyaga bo‘lsa ham, bir oyog‘ini yerdan ko‘tarib, muvozanatni saqlashga urinadi. Bu tananing og‘irlik markazini boshqarishni talab qiladigan murakkab koordinatsiyadir. U bilan "Laylak o‘yini"ni o‘ynang. Bu ham maroqli, ham jismoniy rivojlanish uchun juda foydali.') WHERE id = 'c7634c82-b4b5-450c-9811-7e5cbdc218af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt tushunchasining ilk belgilari". Bola "hozir", "keyin" kabi so‘zlar o‘rtasidagi farqni tushuna boshlaydi. Unga "Avval ovqatlanamiz, keyin bog‘ga boramiz" deganingizda kutishni uddalasa, bu katta yutuqdir. Unda sabr bilan kutish odati shakllanishi uchun vaqt ketma-ketligini harakatlaringiz orqali tushuntirishda davom eting.') WHERE id = '2c927604-0f3e-4615-94c5-86dc48b7896a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Aniq biriktirish". Bola endi konstruktorning kichik qismlari yoki kublarni bir-biriga yanada aniq va tartibli biriktiradi. Bu diqqatni jamlashni ham, barmoq uchlarining aniq harakatlarini ham talab qiladi. Uning "muhandislik" urinishlarini olqishlang va "Bu kimning uyi?" deb so‘rang.') WHERE id = '92d8aec4-818c-4b3a-abd3-dd724c129df5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil suv ichish". Bola endi ochiq stakandan suvni deyarli to‘kmasdan, ishonch bilan ichadi. Bu uning lab va jag‘ mushaklari nutqqa qay darajada tayyor ekanini ko‘rsatadi. Bu ko‘nikmani mukammal egallashi uchun unga bolalar o‘lchamidagi, ushlashga qulay stakanlarni berishda davom eting.') WHERE id = '659e2094-8141-4a5a-bed6-c6f715c75799';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hazil va mutoyiba". Bola ataylab biror narsani "noto‘g‘ri" qilib (masalan, bosh kiyimini qo‘liga kiyib), sizga qarashi va kulishi mumkin. Bu unda hazilni tushunish va ijtimoiy ta’sir ko‘rsatish qobiliyati shakllanayotganini bildiradi. Uning bu "o‘yini"ga zavq bilan qo‘shiling. Birgalikda kulish orangizdagi hissiy rishtani yanada mustahkamlaydi.') WHERE id = 'c1045492-8f8e-491f-a86f-8a5ceb126f15';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Balandlik va masofa". Bola endi zinapoya yoki divandan tushayotganda masofani yaxshiroq chamalaydi. Unga doimo ehtiyot bo‘lishni va xavfsiz tushish usullarini (orqasi bilan) eslatib turing. Bu uning tana xavfsizligi qoidalarini o‘zlashtirishi uchun muhim bosqichdir.') WHERE id = 'c7630ee3-1695-4062-9e13-7540975aa465';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Orqaga yurish mahorati". Bola endi qaramasdan orqaga bir necha qadam tashlay oladi. Bu uning tanasi fazoda qanday joylashganini his qilishi (proprioseptiv sezgi) uchun muhimdir. Unga "Qisqichbaqa kabi yuramiz" deb, bu harakatni o‘yinga aylantiring. Siz bilan birga harakat qilish uning uchun dunyodagi eng katta zavqdir.') WHERE id = 'e1577858-a1db-40b1-bd39-0ce8d678ff7a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Ot-olmosh aloqasi". Bola endi o‘z ismini aytishdan "Men" deyishga to‘liq o‘tmoqda. Siz undan biror narsa so‘raganingizda "Men" yoki "Meniki" desa, bu uning o‘z shaxsini anglash hissi to‘liq shakllanganini ko‘rsatadi. U bilan shu mavzuda suhbatlar quring: "Bu kimning to‘pi? Meniki!".') WHERE id = 'a37651fe-7cc3-4f59-bbce-f7763c1637a8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi "Mumkin emas" degan so‘zga munosabat bildiradi, ammo ba’zida sizning reaksiyangizni sinab ko‘rish uchun qoidalarni baribir buzadi. Xotirjam, ammo qat’iyatli bo‘lib qolish eng muhim shartdir. Agar biror narsaga "yo‘q" degan bo‘lsangiz, buni har safar bir xil tarzda takrorlang. Qoidalarning barqarorligi bolada ichki tartib va xavfsizlik hissini shakllantiradi.') WHERE id = '8f5c35ba-05d9-40e2-a687-7bfe8146f1ee';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '26-oyga qadam qo‘ymoqdamiz! Bola endi ikki xil topshiriqni ketma-ket bajarishga mohir. Masalan: "O‘yinchoqni ol va tokchaga qo‘y". Bu uning xotirasi hamda nutqni tushunish qobiliyati yangi bosqichga ko‘tarilganini ko‘rsatadi. Kun davomida unga shunday kichik "vazifalar" berib, o‘zini foydali his qilishiga imkon yarating.') WHERE id = '86c6ccb4-326d-41d5-81c5-ea4c8d0faf13';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Tezkor manyovr". Bola endi yugurayotganda birdan yo‘nalishini o‘zgartira yoki to‘siqlarni chaqqonlik bilan aylanib o‘ta oladi. Bu ham mushaklar kuchi, ham tez qaror qabul qilish qobiliyatining belgisidir. Bog‘da u bilan "quvlashmachoq" o‘ynab, tanasini boshqarish qobiliyatini mustahkamlang.') WHERE id = 'eb8969ec-bb8d-48c5-8dfb-f818249bf8e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sabab izlash". Bola hali to‘liq "Nega?" deb so‘ramasa-da, harakatlari orqali voqealarning sababini bilishga urinadi. Siz unga tushuntiring: "Kurtkani kiyamiz, chunki tashqarida shamol bor". Voqealar o‘rtasidagi mantiqiy bog‘liqlikni ko‘rsatish kelajakda uning mantiqiy fikr yuritishi uchun eng muhim poydevordir.') WHERE id = 'f63d183c-6b97-43da-8c82-1a87c629cc0d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Burash va aylantirish mahorati". Bola endi butilka qopqoqlari yoki o‘yinchoq vintlarini ishonch bilan ochib-yopa oladi. Bu harakat bilak mushaklarining chaqqonligi uchun ajoyib mashqdir. Unga turli o‘lchamdagi xavfsiz idishlarni berib, mexanizmlarni o‘rganishga bo‘lgan qiziqishini qo‘llab-quvvatlang.') WHERE id = '583cd090-6bc1-4438-afd7-8703fd352e08';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov" va iroda. Bola endi nima kiyishi yoki qaysi idishdan ovqat yeyishi haqida qat’iy fikrga ega. Unga "Bugun ko‘k ko‘ylakni kiyasizmi yoki yashilini?" kabi tanlov imkonini berish, o‘zini alohida shaxs sifatida his qilishiga yordam beradi va qaysarlik xurujlarini kamaytiradi.') WHERE id = '5377658a-72e7-437d-b697-abdb7c76bfcd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hamkorlik". Bola endi sizga yordam berishdan katta zavq oladi. "Kel, xarid xaltasidan nonni olaylik", deganingizda sizga qo‘shilishi uning oiladagi o‘z rolini anglayotganini bildiradi. Bu ham mas’uliyat hissini shakllantiradi, ham orangizdagi rishtani mustahkamlaydi.') WHERE id = '57201085-ec92-4795-8598-90d9a04fb33a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Toifalar". Bola endi bir turdagi buyumlarni (masalan, barcha hayvonlarni bir joyga, barcha mashinalarni boshqa joyga) guruhlay oladi. Unga "Bu yerda qaysi o‘yinchoq boshqalaridan farq qiladi?" kabi savollar berib, vizual mantiqini sinab ko‘ring. Toifalar asosida fikrlash uning bilish qobiliyatini yangi bosqichga olib chiqadi.') WHERE id = 'ffdc805c-2aad-4971-afc7-9cb3c0053b5c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Ikki oyoqda sakrash mahorati". Bola endi turgan joyida balandroq yoki biroz oldinga ishonch bilan sakray oladi. Bu harakat oyoq mushaklari kuchayayotganini anglatadi. U bilan "Quyonlar maysazorda" o‘yinini o‘ynang; bu ham qiziqarli, ham yirik motorika uchun foydalidir.') WHERE id = 'dcd7700f-4c1a-40e7-9469-0739827e396d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Hikoya qilishga urinishlar». Bola kun davomida ko‘rgan qiziqarli voqeani (masalan, «Bog‘da katta itni ko‘rdim») sizga aytib berishga oshiqadi. Uning hikoyasini oxirigacha tinglang va savollar bilan kengaytiring: «It nima qilayotgan edi?». Bu uning xotirasini ham, o‘z fikrini ifodalash qobiliyatini ham mustahkamlaydi.') WHERE id = 'e7fba00d-ba92-45d4-9c39-8a2e6decdc8c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanish: «O‘zini boshqarish». Bola jahli chiqqanida sizga qarab, munosabatingizni kutishi mumkin. Bunday paytlarda xotirjam bo‘ling va «Hozir jahling chiqdi, chunki kublar qulab tushdi, men seni tushunaman», deb uning his-tuyg‘usini nomlang. Sizning xotirjamligingiz bola uchun hissiyotlarni boshqarish bo‘yicha eng yaxshi saboqdir. Siz ajoyib onasiz!') WHERE id = '4a2f0d04-3378-4296-a224-feb8d41e9254';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki farqlabgina qolmay, ko‘pchiligining nomini ham to‘g‘ri talaffuz qiladi. «Ko‘k mashinani olib kel», deganingizda adashmasa, bu uning ko‘rish va so‘z xotirasi uyg‘unlashganini ko‘rsatadi. Kundalik sayrlarda «Yashil barg», «Sariq quyosh» kabi ta’riflar bilan uning dunyosiga rang berishda davom eting.') WHERE id = '57505a63-7f8c-48f6-bce2-90daca2c8189';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda «Zinadan mustaqil chiqish». Bola endi bir qo‘lidan ushlaganingizda zinaning har bir pog‘onasiga navbatma-navbat bir oyog‘ini qo‘yib chiqishga urinadi. Bu yirik motorika rivojidagi katta yutuqdir. Har doim yaqinida bo‘lib, uni ehtiyot qiling, ammo mustaqil qadam tashlashi uchun unga ishonch bering.') WHERE id = 'e9641593-3c91-4cf3-a6cc-b86c93ef50be';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Joylashuvni bildiruvchi so‘zlar». Bola «ustida», «ostida», «orqasida» kabi tushunchalarni endi harakatlari bilan ko‘rsata oladi. U bilan «To‘pni stulning ostiga qo‘y» deb kichik o‘yin o‘ynang. Bu topshiriqlar uning tilni tushunishi va makonda yo‘nalish olish qobiliyatini jadal rivojlantiradi.') WHERE id = '2ff11d89-9e65-4caa-b39f-98e5298d4503';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Saralash va mantiq». Bola endi buyumlarni nafaqat rangiga, balki o‘lchamiga ko‘ra ham (katta-kichik) farqlay boshlaydi. Unga turli o‘lchamdagi idishlarni bering va ularni bir-birining ichiga joylashini so‘rang. Bu uning kelajakdagi matematik tafakkuri uchun poydevordir.') WHERE id = 'cd04a6bc-1fab-4d68-920a-3fa77ebf8503';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zim kiyinaman" bosqichi murakkablashib bormoqda. Bola endi fermuar uchini joyiga kiritib berganingizdan so‘ng uni tortishga yoki katta tugmalarni yechishga urinadi. Bu jarayonda unga xalaqit bermang va shoshiltirmang. Biror ishni o‘zi uddalay olishini ko‘rish — uning o‘ziga bo‘lgan ishonchining eng katta manbaidir. Kichik yutuqlari uchun uni albatta rag‘batlantiring.') WHERE id = '701a4eec-68f9-49ca-9e96-f1cb4b81484e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Empatiya" kuchayadi. Bola sizning yoki boshqa bir bolaning xafa bo‘lganini ko‘rsa, yoningizga kelib o‘yinchog‘ini berishi yoki sizni quchoqlashi mumkin. Bu uning emotsional intellekti (EQ) rivojlanayotganining ajoyib belgisidir. Uning bunday g‘amxo‘rligini "Meni qo‘llab-quvvatlaganing uchun katta rahmat" deb qadrlang.') WHERE id = 'db3deaea-d927-47d7-b65e-09bbf47b377f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida "Shakl va o‘lcham". Bola endi bir xil shaklning (masalan, doiraning) katta va kichik ko‘rinishlarini farqlay oladi. Unga turli o‘lchamdagi idishlarni bir-birining ichiga joylashni ko‘rsating. Bu kelajakdagi matematik tafakkurining asosi bo‘lgan "tartiblash" ko‘nikmasini rivojlantiradi.') WHERE id = '1317ee1d-1c19-4d58-ab70-d9a1fa691c6f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va nishonga yo‘naltirish". Bola endi to‘pni shunchaki tepmaydi, balki uni muayyan yo‘nalishga yo‘naltirishga harakat qiladi. Bu ko‘rish diqqati va harakatlar muvofiqligining uyg‘unlashuvidir. Uyda yoki bog‘da "kichik darvoza" yasab, u bilan to‘pni darvozaga tepish o‘yinini o‘ynang. Bu uning oyoq mushaklarini mustahkamlaydi va harakatlar aniqligini oshiradi.') WHERE id = 'c1e87167-2300-4b17-9def-ab985555b55e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hikoya qilishga urinishlar". Bola kun davomida ko‘rgan qiziqarli narsasini (masalan, "Katta itni ko‘rdim") sizga aytib berishga oshiqadi. Uning hikoyasini oxirigacha tinglang va savollar bilan davom ettirishga undang: "It nima qilayotgan edi?". Bu uning xotirasini ham, o‘z fikrini ifodalash ko‘nikmasini ham mustahkamlaydi.') WHERE id = '404203bc-920b-47d3-b584-2989b01e93ee';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi "Men istamayman" deb o‘z xohishini qat’iy bildirishi mumkin. Bunday paytlarda u bilan tortishish o‘rniga, unga tanlash imkonini berib, diqqatini boshqa narsaga qarating. Sizning sabr-toqatingiz va izchil qoidalaringiz bolada xavfsizlik hissini shakllantiradi. Siz ajoyib ishni uddalayapsiz!') WHERE id = '17f5e755-5dec-4458-9be1-0d08e0586eaf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "Men" olmoshining ma’nosini to‘liq anglab, undan foydalana oladi. "Men keldim", "Men yedim" kabi gaplar u o‘zini atrofdagilardan alohida shaxs sifatida ko‘rayotganini ko‘rsatadi. Uning mustaqil fikrlarini qo‘llab-quvvatlang va suhbatni kengaytiring: "Ha, sen mazali ovqatingni yeding, barakalla!".') WHERE id = '12f036fb-3726-4e17-bff9-217ad09dba7b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Yo‘lak cheti bo‘ylab yurish". Bola endi qo‘lidan ushlaganingizda past bordyurlar ustida yurishga qiziqish bildirmoqda. Bu uning murakkab muvozanat saqlash qobiliyatini rivojlantiradi. Xavfsiz joylarda bu qiziqishini qo‘llab-quvvatlang, chunki bu kelajakda yanada murakkab jismoniy harakatlarni bajarish uchun asos bo‘ladi.') WHERE id = '292c2a9d-2b19-4e22-9095-add20bbbeaf5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Uch so‘zli gaplarning ko‘payishi". Bola endi "Ona, suv bering", "Dada, parkka boramiz" kabi murakkabroq gaplarni tuzadi. U o‘z ehtiyojlarini to‘liq ifodalay oladi. Uning gaplarini tasdiqlab, biroz kengaytiring: "Ha, hozir kel, suv ichamiz, keyin parkka boramiz". Bu uning grammatikani anglash qobiliyatini mustahkamlaydi.') WHERE id = '7132fa94-7590-4b27-b006-e5936aaf0907';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Pazl yig‘ish mahorati" oshadi. Bola endi 6-8 bo‘lakli oddiy pazllarni mustaqil yig‘a oladi. Buning uchun ham vizual tahlil, ham barmoq mushaklarining aniq harakati talab etiladi. Har safar rasmni to‘liq yig‘ganida quvonchingizni ko‘rsating, shunda uning murakkab topshiriqlarga qiziqishi ortadi.') WHERE id = 'd4e00b50-79ce-485c-9a88-f514c156f1f6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim yig‘ishtiraman". O‘yinchoqlarni joyiga qo‘yish endi uning uchun shunchaki topshiriq emas, balki mas’uliyatdir. Unga "Qani, mashinalarni o‘z joyiga qo‘yaylik" deganingizda sizga yordam bersa, bu intizomning poydevoridir. Bu odat kelajakda uning shaxsiy tartibliligi uchun juda muhim.') WHERE id = '03327c5a-8698-4e34-8b71-2d0914f0f88b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Navbat kutish". Bola endi parkda arg‘imchoq uchish yoki o‘yinchoq bilan o‘ynash uchun biroz kutish kerakligini tushunadi. "Hozir mening navbatim, keyin seniki" kabi o‘yinlar orqali unga sabr bilan kutishni o‘rgating. Bu ko‘nikma uning kelajakda bog‘cha va maktab muhitiga moslashishi uchun eng muhim ijtimoiy asoslardan biridir.') WHERE id = '3ea5aca0-7734-4b06-864f-00aa21361675';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Bir xil va farqli". Bola endi bir turdagi buyumlarni (masalan, barcha hayvonlarni bir joyga, barcha mashinalarni boshqa joyga) guruhlay oladi. Unga "Bu yerda qaysi o‘yinchoq boshqalaridan farq qiladi?" kabi savollar berib, vizual mantiqini sinab ko‘ring. Toifalar asosida fikrlash uning idrokini yangi bosqichga olib chiqadi.') WHERE id = '09d14134-1ab9-423c-86bd-46c0a52d2f86';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va yugurish". Bola endi yugurayotganda muvozanatini yo‘qotmasdan oldidagi to‘pni tepa oladi. Bu ham maroqli, ham jismoniy rivojlanish uchun juda foydali. U bilan uyda yoki hovlida yengil to‘p o‘ynab, ham harakat tezligini, ham aniqligini rivojlantiring.') WHERE id = '39fb4064-3e7d-4aa6-b4d5-c75b564c92cc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xotirani ifodalash". Bola kun davomida yuz bergan oddiy voqeani (masalan, "Bog‘da it ko‘rdim") eslab, sizga aytib bera oladi. Uning hikoyalarini diqqat bilan tinglang va "Keyin nima bo‘ldi?" deb, voqealarni izchil bayon qilishiga yordam bering. Bu uning ham xotirasini, ham fikrini ifodalash qobiliyatini mustahkamlaydi.') WHERE id = '109cbe57-dd82-4d85-b381-3ebd329772ab';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanish: "O‘zini boshqarishga urinishlar". Bola jahli chiqqanda sizga qarab, munosabatingizni kutishi mumkin. Bunday paytlarda xotirjam bo‘ling va "O‘yinchoq tuzalmagani uchun hozir jahling chiqdi" deb, uning his-tuyg‘usini nomlang. Sizning xotirjamligingiz uning uchun hissiyotlarni boshqarish borasidagi eng yaxshi saboqdir. Siz ajoyib onasiz!') WHERE id = 'cbb6c494-b75d-458c-b798-2ddf1bf9e334';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '27-oyga xush kelibsiz! Bola endi "ikki bosqichli" ko‘rsatmalarni eslab qolishni to‘liq o‘zlashtirmoqda. "O‘yinchog‘ingni ol va qutiga sol" deganingizda, har ikkala harakatni ketma-ket bajaradi. Bu miya prefrontal korteksining rivojlanayotganini ko‘rsatadi. Unga kun davomida kichik va mantiqiy topshiriqlar berib, bu ko‘nikmasini takomillashtiring.') WHERE id = '0b872b3f-49b7-446a-bc7c-dfae010fe461';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlanishda "Zinadan tushish mahorati". Bola endi qo‘lidan tutganingizda zinadan ishonchliroq, birma-bir qadam tashlab tushishga harakat qiladi. Zinadan tushish chiqishdan qiyinroq, chunki buning uchun ko‘proq muvozanat talab etiladi. Har doim yaqinida bo‘lib, uning xavfsizligini ta’minlang va yutug‘ini olqishlang.') WHERE id = '912ef746-569e-455d-af72-84d6cc3f170e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Savol-javob dialogi». Bola endi sizga oddiy savollar bera oladi: «Dada qani?», «Bu nima?». Javob berayotganda kengroq jumlalar tuzing: «Dada ishga ketdi, kechqurun keladi». Sizning batafsil tushuntirishlaringiz uning miyasida voqealar o‘rtasidagi mantiqiy bog‘lanishlarni mustahkamlaydi.') WHERE id = 'e0d072d6-3ce1-4139-b80e-a94b53d2fc54';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 800 kunni qarshi oldik! Bola 2 yoshdan ancha oshdi va har kuni yangi narsalarni kashf etmoqda. U endi oddiy qoidalarni tushunadi, his-tuyg‘ularini aniq ifodalaydi va siz bilan to‘laqonli muloqot qiladi. Bu kunni u bilan birga sevimli bog‘ida o‘tkazib, nishonlang. Siz ajoyib onasiz!') WHERE id = '1df3c116-f7da-4df5-8d7e-4570b51bb9eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '27-oyning o‘rtalariga yaqinlashmoqdamiz. Bola endi «avval» va «keyin» ketma-ketligini yanada chuqurroq his qiladi. «Kiyimingni kiy, keyin tashqariga chiqamiz» desangiz, u ikkinchi harakat mukofot ekanini tushunadi. Bu bolada sabr-toqat va rejalashtirish ko‘nikmalarining ilk kurtaklaridir. Kundalik odatlarda unga bu ketma-ketliklarni tez-tez eslatib turing.') WHERE id = 'bf2725f4-a91c-46df-b906-cbe0eca9ab09';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda «Tirmashib chiqish mahorati». Bola endi bog‘dagi kichik narvonlarga yoki uydagi xavfsiz balandliklarga ishonch bilan chiqadi. Bunda qo‘l va oyoq mushaklari bir maromda ishlaydi. Doimo yaqinida bo‘ling, ammo unga o‘z kuchini sinab ko‘rish imkonini bering.') WHERE id = '03ce58c6-bf39-4cb2-86c0-fb921289cb85';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Mantiqiy bog‘lanishlar». Bola endi ikki hodisani bitta gapda birlashtiradi: «Havo sovuq, kurtka kiy». Bu uning shunchaki taqlid qilmayotganini, balki fikrlayotganini ham ko‘rsatadi. O‘z fikrlarini ifodalashga yanada ko‘proq intilishi uchun uning bunday mantiqiy mulohazalarini «Ha, to‘g‘ri aytyapsan» deb tasdiqlang.') WHERE id = '70d20b90-08cb-4a3d-b635-39b5e961b0df';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Qog‘oz bilan ishlash». Bola endi qog‘ozni buklashga yoki uni oddiy usulda kesishga (bolalar uchun mo‘ljallangan katta qaychi bilan va nazorat ostida) qiziqish bildirishi mumkin. Bu harakatlar barmoq mushaklarini boshqarish qobiliyatini yangi bosqichga olib chiqadi. Unga rangli qog‘ozlar bilan ishlash uchun sharoit yarating.') WHERE id = '1867a29d-cdef-4c25-9fb4-31fe661ffbe5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sifat va ravishlardan birgalikda foydalanish". Bola endi shunchaki "mashina" emas, balki "tez yuradigan qizil mashina" deb ayta oladi. U dunyoni tasvirlash uchun ko‘proq tafsilotlardan foydalanadi. U bilan suhbatlashayotganda buyumlarning xususiyatlarini ta’kidlang: "Bu og‘ir tosh", "Bu yumshoq yostiq". Bu uning lug‘at boyligini sifat jihatdan oshiradi.') WHERE id = 'c940fb90-c1d6-4fa5-8baf-334e41b324f8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Ijodkorlik va muvofiqlashtirish". Bola endi qog‘ozga aniqroq maqsad bilan doiralar yoki tartibsiz, ammo qalin chiziqlar chizadi. Unga rangli qalamlar va katta qog‘ozlar berib, erkin ijod qilishi uchun sharoit yarating. Bu kelajakda yozish uchun zarur bo‘ladigan mushak xotirasini shakllantiradi.') WHERE id = 'c40de8f9-d507-4cfb-810d-f904e8901ddd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinishga urinishlar". Bola endi paypog‘ini yechishdan tashqari, boshiga qalpog‘ini kiyishga yoki oyoq kiyimini oyoqlariga kiydirishga astoydil urinadi. Bu jarayonda unga bir necha daqiqa qo‘shimcha vaqt bering. Shoshirmasdan, biror ishni o‘zi bajarishiga imkon yaratish uning o‘ziga bo‘lgan ishonchini va mustaqillik hissini mustahkamlaydi.') WHERE id = 'c38e076c-fc5e-4ef7-ba82-49913f3b0c34';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Ramziy g‘amxo‘rlik". Bola o‘yinchoq ayiqchasiga "suv ichirishi", uni adyol bilan yopishi yoki u yig‘laganda silab qo‘yishi mumkin. Bu uning hissiy intellekti va boshqalarning his-tuyg‘ularini tushunish qobiliyati rivojlanayotganini ko‘rsatadi. Uning bunday mehribon harakatlarini maqtashni unutmang.') WHERE id = 'cbccdb44-553a-4ef8-8729-9f35675d89bf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Sanash asoslari". Bola hali raqamlarni ketma-ket sanay olmasa ham, "bir" va "ikki" o‘rtasidagi miqdor farqini ko‘rib tushuna boshlaydi. Unga ikkita olma berib, "Biri seniki, biri meniki" deb, bo‘lishish va sanashni birgalikda ko‘rsating. Bu uning matematik tafakkurining eng dastlabki poydevoridir.') WHERE id = '1953c2df-b74a-440f-aeda-02c40c3b1d9f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Ikki oyoqda oldinga sakrash". Bola endi faqat joyida emas, balki biroz oldinga ham sakray oladi. Bu oyoq mushaklarining kuchi va tana harakatlarini muvofiqlashtirishni talab qiladi. U bilan "Quyonchalar maysazorda sakraydi" o‘yinini o‘ynang. Bu ham qiziqarli, ham yirik motorika uchun ajoyib mashqdir.') WHERE id = '9999afba-b8a0-474d-b26c-6136ec804e12';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Rolli o‘yinlarning murakkablashuvi". Bola endi "shifokor", "oshpaz" yoki "haydovchi" roliga kira oladi. Bu o‘yinlar orqali u atrofidagi insonlarning vazifalarini o‘rganadi va ularga hamdard bo‘lishni o‘zlashtiradi. Uning o‘yinlariga qo‘shiling va u sizga bergan "rolga" mos harakat qiling.') WHERE id = '09d954dd-f762-40e1-8030-11d38ef87b47';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tozalik" ko‘nikmasi. Bola endi qo‘llarini yuvayotganda ularni sovunlab, chayishni deyarli mustaqil bajara oladi. Bu yoshda gigiyena ko‘nikmalarini mustahkamlash juda muhim. Bu jarayon unga zavq bag‘ishlashi uchun bo‘yiga mos tagkursi (step stool) olib bering.') WHERE id = '8f3c97e4-28e2-4575-994c-03b54f2a86ed';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish qobiliyatining rivojlanishida "Farqlisini top". Bola endi bir guruh buyumlar orasidan farq qiladiganini (masalan, mashinalar orasidagi olmani) ko‘rib ajrata oladi. Bu uning tahlil qilish qobiliyatini rivojlantiradi. Uyda u bilan oddiy "Qaysi biri ortiqcha?" o‘yinlarini o‘ynang. Bu kelajakdagi matematik va mantiqiy topshiriqlar uchun ajoyib tayyorgarlikdir.') WHERE id = '0c2d9534-6a6b-4045-844a-9433e0a69d75';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Bir oyoqda turishga urinishlar". Bola endi bir necha soniyaga bo‘lsa ham, bir oyog‘ini yerdan ko‘tarib, muvozanatni saqlashga harakat qiladi. Bu tananing og‘irlik markazini his qilish uchun muhimdir. U bilan "Laylak o‘yini"ni o‘ynang va kim uzoqroq tura olishini sinab ko‘ring.') WHERE id = '5d944b43-095b-4d92-b030-b834a56949f2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "His-tuyg‘ularni ifodalash". Bola endi xafa, xursand yoki qo‘rqqanini so‘z bilan ayta oladi: "Men qo‘rqdim" yoki "Men xursandman". His-tuyg‘ularni nomlash bolada hissiy intellektning asosini yaratadi. U his-tuyg‘usini aytganda, uni tinglang va "Ha, sizni tushunaman" deb, hislarini tan oling.') WHERE id = 'cb48e516-3844-4090-848b-2afd50d005de';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvur kuchi: "Ko‘rinmas do‘stlar va buyumlar". Bola tayoqni "ot" deb tasavvur qilib, uni minib chopgandek yurishi mumkin. Bu ramziy tafakkurning eng yuqori ko‘rinishidir – bir buyum boshqa narsani ifodalashini anglash. Bu ko‘nikma kelajakda o‘qish va matematika (ramzlarni tushunish) uchun juda muhimdir.') WHERE id = '76d9591a-d7e3-4913-96a8-5d2c420ccc81';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Balandlik va masofa". Bola endi zinadan yoki divandan tushayotganda masofani yaxshiroq chamalaydi. Unga doimo ehtiyot bo‘lishni va xavfsiz tushish usullarini (orqasi bilan) eslatib turing. Bu uning tana xavfsizligi qoidalarini o‘zlashtirishi uchun muhim bosqichdir.') WHERE id = '0f7477b8-a1ff-4761-b386-ffe1e44a9a7a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va nishon". Bola endi to‘pni shunchaki tepib yubormaydi, balki uni muayyan yo‘nalishga yo‘llashga harakat qiladi. Bu ko‘rish diqqati va harakatlar muvofiqligining uyg‘unlashuvidir. U bilan uyda yoki bog‘da "kichik darvoza" yasab, unga to‘p tepish o‘yinini o‘ynang.') WHERE id = '050cfb5f-db53-4311-8b9f-fbb09f54e915';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hikoya qilishga urinishlar". Bola kun davomida ko‘rgan qiziqarli narsasini (masalan, "Katta itni ko‘rdim") sizga aytib berishga oshiqadi. Uning hikoyasini oxirigacha tinglang va savollar bilan davom ettirishga undang: "It qanday rangda edi?". Bu uning xotirasi va o‘z fikrini ifodalash ko‘nikmasini mustahkamlaydi.') WHERE id = 'd7af8a5b-1016-4dc8-921f-52af71c3d954';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi "Men xohlamayman" deb o‘z istagini qat’iy bildirishi mumkin. Bunday paytlarda u bilan o‘jarlashish o‘rniga, tanlash imkonini berib, e’tiborini boshqa tomonga qarating. Sizning sabr-toqatingiz va izchil qoidalaringiz bolada xavfsizlik hissini shakllantiradi. Siz ajoyib ishni uddalayapsiz!') WHERE id = '80c062ac-b271-45ec-b67c-016fb884ca5b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '28-oyga qadam qo‘yyapmiz! Bola endi "ikki bosqichli" topshiriqlarni bemalol bajara oladi. Masalan: "O‘yinchog‘ingni ol va tokchaga qo‘y". Bu uning xotirasi hamda nutqni tushunish qobiliyati yangi bosqichga ko‘tarilganini ko‘rsatadi. Kun davomida unga kichik va mantiqiy "vazifalar" berib, mas’uliyat hissini shakllantiring.') WHERE id = 'a1060bb5-066a-438b-aafd-d9c5d706c7bc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Zinadan tushish mahorati". Bola endi qo‘lidan ushlab turganingizda zinadan yanada ishonch bilan, har bir pog‘onaga bittadan oyog‘ini qo‘yib tushishga harakat qiladi. Tushish ko‘tarilishdan qiyinroq, chunki u ko‘proq muvozanatni talab qiladi. Doimo yaqinida bo‘lib, uni ehtiyotlang va muvaffaqiyatini olqishlang.') WHERE id = '05b34d22-95f5-4000-aee3-08f747372e4d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '27-oyning so‘nggi o‘n kunligini boshlayapmiz! Bola endi ranglarni shunchaki tanibgina qolmay, ularni bir-biriga moslashtirishni ham yaxshi uddalaydi. Unga "Qizil paypog‘ingning juftini top" deganingizda buni to‘g‘ri bajarsa, bu uning vizual tafakkuri rivojlanayotganidan dalolat beradi. Kundalik kiyimlarini tanlashda ranglarni tez-tez ta’kidlab turing.') WHERE id = '5063e9dc-6139-4c88-93fd-950678f58bde';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Zinadan erkin chiqish" bosqichi. Bola endi bir qo‘lidan ushlab turganingizda zinaning har bir pog‘onasiga navbatma-navbat bir oyog‘ini qo‘yib chiqishga urinadi. Bu yirik motorika rivojidagi katta yutuqdir. Har doim yonida bo‘lib, uni ehtiyot qiling, ammo mustaqil qadam tashlashi uchun unga ishonch bildiring.') WHERE id = 'd4f943d2-bf71-4b16-b7d0-f1be4b723a37';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Payt ravishlarining ilk belgilari". Bola "hozir", "keyin", "birozdan so‘ng" kabi so‘zlar o‘rtasidagi farqni yaxshiroq tushuna boshlaydi. Unga "Avval ovqatlanamiz, keyin parkka boramiz" deganingizda kuta olsa, bu uning iroda kuchi mustahkamlanayotganidan dalolat beradi. Vaqt ketma-ketligini harakatlaringiz orqali tushuntirishda davom eting.') WHERE id = 'ad12a2ff-a0f6-446e-a287-18ac0e3ed236';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Pazl yig‘ish mahorati". Bola endi 6-9 qismli oddiy pazllarni mustaqil yig‘a oladi. Tasvir qismlarini ko‘rib birlashtirish uning diqqatini jamlash va muammolarni hal qilish ko‘nikmalarini rivojlantiradi. Uddalay olmasa, xotirjam ohangda yordamchi ishoralar bering.') WHERE id = 'ca532b10-de2c-4db5-9614-e001b1908ea1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov" eng yuqori bosqichda. Bola endi nima kiyishi yoki qaysi o‘yinchoq bilan o‘ynashi haqida qat’iy fikrga ega. Unga "Bugun ko‘k qalpog‘ingni kiyasanmi yoki yashilini?" kabi tanlov imkonini berish o‘zini alohida shaxs sifatida his qilishiga yordam beradi va qaysarlik xurujlarini imkon qadar kamaytiradi.') WHERE id = 'fb9fc561-26c7-41b4-bbe1-31eada18c85f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Navbat kutish". Bola endi parkda arg‘imchoq uchish uchun biroz kutish kerakligini tushunadi. "Hozir uning navbati, keyin seniki" kabi o‘yinlar orqali unga sabr bilan kutishni o‘rgating. Bu ko‘nikma ijtimoiy moslashuv uchun eng muhim poydevordir.') WHERE id = '9df47b2e-3d86-40c8-a4bd-0d995655814b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sifat va ravishlarni birgalikda qo‘llash". Bola endi shunchaki "mashina" emas, balki "tez yuradigan qizil mashina" deb ayta oladi. U dunyoni tasvirlash uchun ko‘proq tafsilotlardan foydalanadi. U bilan suhbatlashganda buyumlarning xususiyatlarini ta’kidlang: "Bu og‘ir tosh", "Bu yumshoq yostiq". Bu uning so‘z boyligini sifat jihatidan oshiradi.') WHERE id = '5838f818-d4e0-42c7-ba01-7e6420078ed2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Terish va qurish". Bola endi kublardan shunchaki minora emas, balki "devor", "poyezd" yoki "uy" kabi maqsadli shakllarni yasaydi. Bu uning ko‘rish-fazoviy tafakkuri va tasavvuri uyg‘unlashayotganini ko‘rsatadi. Uning qurgan narsalari haqida savollar bering: "Bu yerda kim yashaydi?".') WHERE id = '46a64e62-d979-410f-9a15-a2c7bbeb1ba9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov" va iroda. Bola endi nima kiyishi yoki qaysi idishdan ovqat yeyishi haqida qat’iy fikrga ega. Unga "Bugun ko‘k ko‘ylakni kiyasizmi yoki yashilini?" kabi tanlov imkoniyatini berish o‘zini alohida shaxs sifatida his qilishiga yordam beradi va qaysarlik xurujlarini kamaytiradi.') WHERE id = 'f2f6cbfc-bdac-4534-9233-ecd8a693e212';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Ramziy g‘amxo‘rlik". Bola o‘yinchoq ayiqchaga "suv ichirishi", uni ko‘rpa bilan yopishi yoki "davolashi" mumkin. Bu uning hissiy intellekti va boshqalarning his-tuyg‘ularini tushunish qobiliyati rivojlanayotganini ko‘rsatadi. Uning bunday mehribon harakatlarini albatta maqtang.') WHERE id = '8ddc104a-ab8a-4e5a-943d-543dc807df66';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Farqli narsani top". Bola endi buyumlar guruhi ichidan boshqalaridan farq qiladiganini (masalan, mashinalar orasidagi olmani) ko‘rib ajrata oladi. Bu uning tahlil qilish qobiliyatini charxlaydi. Uyda u bilan oddiy "Qaysi biri ortiqcha?" o‘yinlarini o‘ynang. Bu kelajakdagi mantiqiy topshiriqlar uchun ajoyib tayyorgarlikdir.') WHERE id = 'a2b9980c-2bf2-401b-8655-ae5a31b2d842';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Ikki oyoqda oldinga sakrash". Bola endi faqat turgan joyida emas, balki biroz oldinga ham sakray oladi. Buning uchun oyoq mushaklarining kuchi va tana harakatlarini muvofiqlashtirish talab etiladi. U bilan "Quyonchalar maysazorda sakraydi" o‘yinini o‘ynang. Bu ham qiziqarli, ham yirik motorika uchun ajoyib mashqdir.') WHERE id = '3b71e4fe-1f75-478c-bb70-76e4d5347b3d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Savol-javob dialogi». Bola endi sizga oddiy savollar bera oladi: «Dada qani?», «Bu nima?». Javob berayotganda kengroq jumlalar tuzing: «Dada ishga ketdi, kechqurun keladi». Sizning batafsil tushuntirishlaringiz uning miyasida voqealar o‘rtasidagi mantiqiy bog‘lanishlarni mustahkamlaydi.') WHERE id = '12f65b1a-8cde-4d4d-842d-5197bc6d6352';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvur kuchi: «Rollar almashinuvi». Bola sizga taqlid qilib «ona» bo‘lishi yoki o‘yinchoqlarini «ishga olib borishi» mumkin. Bu uning xotirasi qanchalik rivojlanayotganini hamda voqealar o‘rtasidagi mantiqiy bog‘lanishni qanchalik teran kuzatayotganini ko‘rsatadi. Siz ajoyib onasiz!') WHERE id = '1d0c6c5d-a275-43bf-bb3b-a961c2f6805e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki tanibgina qolmay, kamida 3-4 ta asosiy rangni (qizil, ko‘k, yashil, sariq) ayta boshlaydi. Undan «Bu qanday rang?» deb so‘raganingizda, to‘g‘ri javob olish ehtimolingiz yuqori. Sayr paytida mashinalar yoki gullarning ranglarini so‘rab, bu bilimini mustahkamlang.') WHERE id = '44e5c106-bbab-44d6-a4ac-bc4a1418e1eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda «Bir oyoqda muvozanat saqlash». Bola endi bir necha soniyaga bo‘lsa ham, bir oyog‘ini yerdan ko‘tarib, muvozanatni saqlashga urinadi. Bu tananing og‘irlik markazini boshqarishni talab qiladigan murakkab koordinatsiyadir. U bilan «Laylak o‘yini»ni o‘ynang. Bu ham qiziqarli, ham jismoniy rivojlanish uchun juda foydali.') WHERE id = 'fbfbb0b9-9b09-4a23-9066-c80337eab4d6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Vaqt tushunchasining ilk belgilari». Bola «kecha», «ertaga» so‘zlarini hali to‘liq tushunmasa-da, «hozir», «keyin», «birozdan so‘ng» kabi so‘zlarning farqini anglaydi. Unga «Avval qo‘llarimizni yuvamiz, keyin non yeymiz» deganingizda kuta olsa, bu uning iroda kuchi mustahkamlanayotganini bildiradi. Vaqt ketma-ketligini harakatlaringiz orqali tushuntirishda davom eting.') WHERE id = 'a4ffacc2-0d5e-4231-a5d0-f90a33b4d6f5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Doira va chiziq chizish mahorati». Bola endi qog‘ozda aniqroq maqsad bilan doiralar yoki tartibsiz, ammo dadil to‘g‘ri chiziqlar chizadi. Unga rangli qalamlar va katta qog‘ozlar berib, «ilk rasmlarini» chizishi uchun sharoit yarating. Bu kelajakdagi yozish ko‘nikmalari uchun eng muhim mashqdir.') WHERE id = 'efd8c509-5660-43d7-a555-e496a390e478';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish" istagi. Bola endi nafaqat paypog‘ini yechishga, balki boshiga qalpog‘ini kiyishga yoki kiyish oson bo‘lgan oyoq kiyimlarini oyog‘iga kiyib olishga ham urinadi. Bu jarayon uchun unga bir necha daqiqa qo‘shimcha vaqt bering. Shoshirmasdan, biror ishni o‘zi bajarishiga imkon yaratish uning o‘ziga bo‘lgan ishonchi va mustaqillik tuyg‘usini shakllantiradi.') WHERE id = 'ea6058fd-22cb-454f-b6df-36b6c6f564fd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hazil va mutoyiba". Bola ataylab biror ishni "noto‘g‘ri" bajarib (masalan, qalpog‘ini qo‘liga kiyib), sizga qarashi va kulishi mumkin. Bu unda hazilni tushunish va ijtimoiy ta’sir ko‘rsatish qobiliyati shakllanayotganini bildiradi. Uning bu "o‘yiniga" zavq bilan qo‘shiling. Birgalikda kulish orangizdagi hissiy rishtani yanada mustahkamlaydi.') WHERE id = '90539d1c-30bc-43ec-8cb5-e89edef1568e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Balandlik va masofa". Bola endi zinadan yoki divandan tushayotganda masofani yaxshiroq chamalaydi. Unga doimo ehtiyot bo‘lishni va xavfsiz tushish usullarini (orqasi bilan) eslatib turing. Bu uning tana xavfsizligi qoidalarini o‘zlashtirishi va xavflarni ko‘rib tahlil qilishi uchun muhim bosqichdir.') WHERE id = '00eb14eb-16c9-4d20-9af4-97c177dc49f5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Orqaga yurish". Bola endi orqasiga qaramasdan bir necha qadam orqaga yura oladi. Bu uning tanasi fazoda qanday joylashganini his qilishi (proprioseptiv sezgi) uchun muhimdir. Unga "Qisqichbaqadek yuramiz" deb, bu harakatni o‘yinga aylantiring. Bu oyoq mushaklarini boshqacha tarzda ishlatadi.') WHERE id = '2b4f1496-5d34-4f25-9ad5-91b67ba2967b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Ot va olmosh o‘rtasidagi bog‘liqlik". Bola endi o‘z ismini aytishdan "Men" deyishga to‘liq o‘tmoqda. Siz undan biror narsa so‘raganingizda "Men" yoki "Meniki" desa, bu uning o‘zligini anglash hissi to‘liq shakllanganidan dalolat beradi. U bilan shu mavzuda suhbatlashing: "Bu kimning to‘pi? Meniki!". Siz ajoyib yo‘l ko‘rsatuvchisiz!') WHERE id = '61b67af6-b8e7-43c0-aeec-e2ba32964d5a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi "Men istamayman" deb o‘z xohishini qat’iy ifodalashi mumkin. Bunday paytlarda u bilan tortishish o‘rniga, unga tanlash imkonini berib, e’tiborini boshqa narsaga qarating. Sizning sabringiz va izchil qoidalaringiz bolada xavfsizlik hissini shakllantiradi. 840 kunni muvaffaqiyatli yakunladik – siz barcha yaxshiliklarga loyiqsiz!') WHERE id = 'f92d1e9f-889d-441d-90aa-ab2a51e762a4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '28-oyning so‘nggi o‘n kunligini boshlaymiz! Bola endi ikki bosqichli topshiriqlarni bemalol bajara oladi. Masalan: "O‘yinchoqni ol va tokchaga qo‘y". Bu uning ham operativ xotirasi, ham nutqni tushunish qobiliyati yangi bosqichga ko‘tarilganini ko‘rsatadi. Kun davomida unga shunday kichik "vazifalar" berib, mas’uliyat hissi va diqqatini rivojlantiring.') WHERE id = '1fed649f-83be-432e-bf3b-958f939d1d57';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Zinadan chiqish mahorati". Bola endi bir qo‘lidan ushlab turilganda zinadan har bir pog‘onaga bir oyoq qo‘yib chiqishga urinishi mumkin. Bu son va tos mushaklari mustahkamlanayotganini anglatadi. Doimo yonida bo‘lib, uning xavfsizligini ta’minlang va yutuqlarini olqishlang.') WHERE id = '2104ca19-971d-4ad2-bad2-4fb0d5fce478';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sabab-oqibat" ifodalari. Bola endi "Chunki" (yoki unga o‘xshash tovush) deyishga urinib, nega nimanidir xohlayotganini tushuntirishi mumkin. Siz ham unga sabablarni izohlang: "Hozir muzqaymoq yemaymiz, chunki havo sovuq". Bu uning mantiqiy tafakkuri va o‘z fikrini asoslash qobiliyatining poydevoridir.') WHERE id = '9a1ea5be-b73b-4171-a8a3-6f9f06ff6d11';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Burash va aylantirish". Bola endi butilka qopqoqlari va o‘yinchoq vintlarini ishonch bilan burab ochib-yopa oladi. Bu harakat bilak mushaklarining aylanish harakati uchun ajoyib mashqdir. Unga turli o‘lchamdagi xavfsiz idishlarni berib, mexanizmlarga bo‘lgan qiziqishini qo‘llab-quvvatlang.') WHERE id = '326af733-89d5-4b18-a86d-69d50b560d32';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim yuvinaman". Cho‘milayotganda bola sovun yoki gubkani olib, badanini ishqalashga va sizga taqlid qilishga urinadi. Uning gigiyena odatlariga bo‘lgan qiziqishini so‘ndirmang. O‘zini "tozalashi" unga tana a’zolarini yaxshiroq bilib olishga hamda shaxsiy gigiyena mas’uliyatini erta yoshdan o‘zlashtirishga yordam beradi.') WHERE id = '059ef4bc-ae23-4023-aa71-ac7bfd7a180d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Bo‘lishishning qiyinligi". Bu yoshda "Meniki!" degan hayqiriqlar mutlaqo tabiiy. Bola o‘ziga tegishli narsalarni himoya qilishni o‘rganmoqda. Uni bo‘lishishga majburlamang, buning o‘rniga "Navbat bilan o‘ynaymiz" tamoyilini qo‘llang. Sizning bu sabringiz uning ijtimoiy intellektini shakllantiradi.') WHERE id = '89f6ed5e-1781-4f77-8a89-eea339ecb1d6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Moslashtirish" (Matching). Bola endi bir xil hayvonning turli rasmlarini yoki bir xil rangdagi buyumlarni o‘zaro moslashtira oladi. U bilan oddiy kartochkalar yordamida "Bir xilini top" o‘yinini o‘ynang. Bu uning ko‘rish orqali diqqatini hamda toifalar bo‘yicha fikrlash qobiliyatini jadal rivojlantiradi.') WHERE id = '1b1a5af3-541e-4a8b-826b-94504ae0251e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni uzoqqa otish". Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni yelkasidan oshirib (overhand) oldinga otishga harakat qiladi. Bu harakat butun tana muvofiqligini talab qiladi. U bilan bog‘da "Kim to‘pni uzoqroqqa otadi?" o‘yinini o‘ynang. Bu uning qo‘llarini mustahkamlaydi va masofani his qilish qobiliyatini oshiradi.') WHERE id = '985bce91-74bc-40ac-bdc4-be9aa7dbfeab';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Iltimos qilish". Bola endi biror narsani xohlaganda shunchaki barmog‘i bilan ko‘rsatmaydi, balki "Ber" yoki "Iltimos" (yoki shunga o‘xshash bir ibora) deya oladi. Har safar unga odobli so‘zlarni qanday ishlatishni namuna qilib ko‘rsating. Sizdan "Rahmat" yoki "Iltimos" so‘zlarini eshitishi uning kelajakdagi muloqot madaniyatiga poydevor yaratadi.') WHERE id = 'edefb696-9b37-48b2-bf5d-42c196545bf4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvur kuchayishi: "Rolli o‘yinlar murakkablashadi". Bola endi shunchaki ovqat tayyorlamaydi, balki o‘yinchoqlarini mehmonga chaqiradi, ularni "davolaydi" yoki "mashinaga mindirib ishga olib boradi". Bu uning xotirasidagi voqealarni qanday birlashtirayotganini ko‘rsatadi. Uning bu rolli o‘yinlariga qo‘shiling — bu ijodkorligini yanada yuksaltiradi.') WHERE id = '22acecd0-67df-4601-b0d7-23a57c3444c3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '29-oyga xush kelibsiz! Bola endi "ha" va "yo‘q"dan ko‘ra murakkabroq javoblar bera boshlaydi. "Nega buni xohlaysan?" degan savolga "Chunki mazali" yoki "Chunki qizil" kabi javoblar berishi mumkin. Bu uning ichki istak va sabablarini so‘zlar bilan ifodalash qobiliyatining boshlanishidir. Uning har bir "chunki"sini diqqat bilan tinglang.') WHERE id = '0e94d08f-2dfb-49bd-b8dc-5b547bbc54de';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatda "Dinamik muvozanat". Bola endi past chiziq yoki yerga qo‘yilgan arqon ustidan "dorboz" kabi yurishga qiziqish bildiradi. Bu uning o‘z tanasini his qilish qobiliyatini (proprioception) rivojlantiradi. Uyda rangli tasmalar bilan yo‘lakchalar yasab, uning bu ko‘nikmasini qo‘llab-quvvatlang.') WHERE id = '82c3b72a-274b-4062-9adf-7e5cce134bd3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Ko‘plik qo‘shimchalari". Bola endi "olma" bilan "olmalar" o‘rtasidagi farqni tushunadi va nutqida qo‘llashga harakat qiladi. Unga o‘yinchoqlarini ko‘rsatib, "Qara, bu yerda ko‘p mashinalar bor", deb ko‘plik tushunchasini mustahkamlang. Bu uning grammatik tuzilishi yanada murakkablashib borayotganidan dalolat beradi.') WHERE id = '64529c1d-caa7-4ac1-a772-2e82ed067453';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Barmoq kuchi". Bola endi kiyim qisqichlarini siqib ochishi yoki plastilin bilan ishlayotganda undan yanada kichikroq bo‘laklarni uzib olishi mumkin. Bu harakatlar barmoqlarning mayda mushaklarini mustahkamlaydi va kelajakda qalamni to‘g‘ri ushlashga tayyorlaydi.') WHERE id = 'e1008078-204c-4a5c-bac1-d07adf97ca32';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Ramziy baham ko‘rish". Bola endi boshqa bolaning qo‘lidan o‘yinchoqni darhol tortib olmasdan, "ber" deb kutishga harakat qiladi. Bu o‘zini boshqarish (self-regulation) ko‘nikmasining ilk kurtaklaridir. Uning bunday sabrli xatti-harakatini ko‘rganingizda, albatta, "Navbatingni kutganing uchun katta rahmat", deb maqtang.') WHERE id = '7f709f10-5a18-4150-b7b4-fa822721b9c8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men o‘zim tayyorlayman". Bola oshxonada sizga yordam berishdan juda zavqlanadi: xamirni ezish, sabzavotlarni (xavfsiz pichoq bilan) kesish yoki dasturxonga qoshiq qo‘yish. Bu uning motorikasini rivojlantirish bilan birga, oziq-ovqatlarga bo‘lgan qiziqishini ham oshiradi.') WHERE id = '53d5b167-fe89-4403-8e4d-0684f94ae9c5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida "Izchillik va xotira". Bola endi sevimli ertagi yoki multfilmidagi voqealar ketma-ketligini biladi. Siz voqeani noto‘g‘ri aytib bersangiz, "Yo‘q, ayiq keldi!" deb sizni tuzatishi mumkin. Bu uning uzoq muddatli xotirasi va voqealar rivojini tushunish qobiliyati yuqori ekanini ko‘rsatadi.') WHERE id = '51d45576-0732-4e17-9d1f-994a457d540c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Joyida sakrash va aylanish". Bola endi shunchaki yuqoriga sakramaydi, balki sakrayotganda havoda tanasini burishga harakat qiladi. Bu murakkab vestibulyar muvofiqlashtirishni talab etadi. U bilan yumshoq gilam ustida "akrobatika" o‘yinlarini o‘ynang.') WHERE id = '9536e69d-203e-4017-ae80-dbe2f9eab99b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «O‘zini tasvirlash». Bola endi sizga «Men katta bo‘ldim», «Men yuguryapman» kabi o‘z holati haqida ma’lumot bera oladi. U bilan ko‘zgu qarshisida turib, «Ko‘zlaring qanday rangda?», «Buruning qayerda?» kabi savollar berish orqali o‘zini anglash jarayonini qiziqarli qiling.') WHERE id = 'eca2c14e-98c5-475b-94e6-e55601d2febb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy rivojlanish: «Mustaqillik inqirozlari». Bola hamma narsani o‘zi qilishni xohlab, uddalay olmasa, qattiq jahli chiqishi mumkin. Bunday paytlarda xotirjam bo‘ling va «Hozir jahling chiqdi, chunki bu qiyin, kel, birga qilamiz», deb uni qo‘llab-quvvatlang. Sizning xotirjamligingiz — uning hissiy bo‘ronlarini tinchlantiradigan eng ishonchli panohdir.') WHERE id = '9fa6b04b-2e13-4b5c-ba62-6d1e0398948e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki «qizil» yoki «ko‘k» sifatida emas, balki ularning bir-biriga yaqin tuslarini ham ko‘rib farqlay oladi. Unga yashil rangning turli tuslaridagi barglarni ko‘rsating va «Qaysi biri to‘qroq?» deb so‘rang. Bu uning vizual tahlil qilish qobiliyatini rivojlantiradi.') WHERE id = '1d89cf33-54f4-473a-9dbf-869b4e96ac30';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda «Bir oyoqda sakrashga urinishlar». Bola endi bir oyog‘ida yengil sakrashga harakat qiladi. Bu to‘piq kuchi va muvozanatni saqlashni talab qiladigan juda murakkab harakatdir. Uning bu jasoratli urinishlarini olqishlang, yiqilib tushsa ham tushkunlikka tushmasligi uchun uni qo‘llab-quvvatlang.') WHERE id = 'c09edac9-8b37-4347-a8dd-3e14699e7139';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «O‘tgan zamonning ilk belgilari». Bola endi «bordim», «ko‘rdim», «yedim» kabi fe’llarni sodir bo‘lgan voqealarni ifodalash uchun ishlatadi. Kechqurun u bilan «Bugun nima qildik?» mavzusida suhbatlashing. Bu uning xotirasini ham, vaqt haqidagi tushunchasini ham mustahkamlaydi.') WHERE id = '5e30771f-35e9-43cb-9e6c-1bfc3d0ea335';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Maqsadli bo‘yash». Bola endi qog‘ozdagi katta shaklning (masalan, doiraning) ichini bo‘yashga va chegaralaridan imkon qadar chiqmaslikka harakat qiladi. Bu qo‘l mushaklarini boshqarishda katta yutuqdir. Unga sodda va yirik konturli bo‘yash varaqlarini taklif qiling.') WHERE id = '30b62203-ae1a-48ab-82d9-d252856f8bcb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '“Men yordamchiman”. Bola endi uydagi kichik tozalash ishlariga (chang artish, o‘yinchoqlarini qutiga joylash) o‘yin emas, vazifa sifatida yondasha boshlaydi. Unga o‘ziga tegishli kichik tozalash matosini bering. Bu unda oiladagi mas’uliyat va daxldorlik hissini nihoyatda kuchaytiradi.') WHERE id = '75e40c4f-895e-4725-bab2-0bb5ec9f1edc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda “Do‘stlikning ilk belgilari”. Bola endi bog‘da tanish bolani ko‘rsa, quvonadi va unga o‘z o‘yinchog‘ini taklif qiladi. Bu shunchaki yonma-yon o‘ynashdan birgalikda o‘ynashga (interaktiv o‘yin) o‘tish bosqichidir. Uning bu ijtimoiy qadamlarini ijobiy so‘zlar bilan qo‘llab-quvvatlang.') WHERE id = '73a7095e-32dd-413f-b911-0ace0be7e88d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida “Balandlik va hajm”. Bola endi qaysi stakanga ko‘proq suv sig‘ishini yoki qaysi minora balandroq ekanini ko‘z bilan taqqoslay oladi. Cho‘milish paytida turli o‘lchamdagi idishlar bilan suvli o‘yin o‘ynang. “Qaysi idish tezroq to‘ladi?” degan savol uning moddiy olam haqidagi bilimlarini oshiradi.') WHERE id = '3cf32da0-166e-4863-bf9c-f4ea80d66e98';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: “Yugurayotganda to‘pni boshqarish”. Bola endi yugurib ketayotib, to‘pni oyog‘i bilan oldinga surishga (dribling) urinadi. Bunda harakat tezligi va oyoq harakatining aniqligi uyg‘unlashadi. U bilan ochiq havoda harakatli futbol o‘yinlarini o‘ynab, energiyasini foydali tarzda sarflashiga yordam bering.') WHERE id = 'c300bf1e-a81a-4d08-9bfb-583735c02aab';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda “Mavhum savollar”. Bola endi shunchaki “Bu nima?” deb emas, balki “Qush qayerga uchib ketdi?” yoki “Quyosh qayerga ketdi?” kabi ko‘zga ko‘rinmaydigan hodisalar haqida savollar beradi. Javoblaringizga tasavvur kuchini ham qo‘shing: “Quyosh uxlagani ketdi”. Bu uning tasavvuri va voqealarni anglash darajasi chuqurlashayotganini ko‘rsatadi.') WHERE id = '5d13e772-b0dc-414e-be1a-eb306de1058d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: Bola endi “Yo‘q” degan javobni eshitganda, avvalgidek darhol yig‘lamaydi, balki sababini tushunishga harakat qiladi. Unga qoidalarni xotirjam ohangda tushuntiring: “Hozir konfet yemaymiz, chunki kechki ovqat vaqti bo‘ldi”. Sizning izchil va mantiqli munosabatingiz bolada o‘zini boshqarish va sabr qilish ko‘nikmalarini shakllantiradi.') WHERE id = 'd426c7f4-84e8-442d-bd5f-c6c23fc0839f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '29-oyning so‘nggi o‘n kunligini boshlaymiz! Bola endi "men" va "sen" olmoshlarini deyarli adashtirmay ishlatadi. Suhbat davomida u o‘z istaklarini "Men buni xohlayman" deb qat’iy ifodalaydi. Undagi o‘zlikni anglash hissini qo‘llab-quvvatlang va qarorlarini hurmat qilishingizni ko‘rsating; bu sog‘lom o‘ziga ishonchning poydevoridir.') WHERE id = '4a584dfd-3b1f-4ba7-b2c3-765c25e1ca50';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Sakrash va yerga tushish". Bola endi pastroq joydan (masalan, yo‘l chetidagi bordyurdan) ikki oyog‘i bilan bir vaqtda yerga sakrashga jur’at etadi. Bu oyoq mushaklarining kuchi va fazoda muvozanatni his qilish uchun katta yutuqdir. Doimo yaqinida bo‘lib, uning xavfsizligini ta’minlang.') WHERE id = '55d65f2d-a7aa-455b-9e97-2b3375627fc7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Bog‘lovchilardan foydalanish". Bola endi "va", "ammo", "chunki" kabi so‘zlar yordamida ikkita fikrni birlashtiradi: "Men yugurdim va yiqildim". Bu uning fikrlari yanada tizimli va o‘zaro bog‘liq bo‘lib borayotganini ko‘rsatadi. U bilan gaplashganda siz ham shu bog‘lovchilardan foydalanib, jumlalaringizni biroz murakkablashtiring.') WHERE id = 'a1740f48-0bf0-4597-985c-859e4a235e6b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Tugun va bog‘lashga qiziqish". Bola endi oyoq kiyim bog‘ichlarini tortishga, tugmalarni yechishga yoki yirik munchoqlarni ipga tizishga urinadi. Bu harakatlar barmoqlar muvofiqligini juda yaxshi rivojlantiradi. Unga turli tuzilishdagi iplar va teshikli o‘yinchoqlar berib, bu qiziqishini qo‘llab-quvvatlang.') WHERE id = '17adcdf9-4e22-4431-92cb-4bcd0b67e350';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish" mahorati. Bola endi shimini yuqoriga tortish yoki oddiy ko‘ylagini (boshidan o‘tkazgandan keyin) kiyishda ancha mohir. Uni "Qani, endi paypoqlaringni kiyishga urinib ko‘r" deb rag‘batlantiring. Mustaqillik sari qo‘yilgan bu kichik qadamlar unga kundalik hayotda o‘zini qobiliyatli shaxs sifatida his qilishiga yordam beradi.') WHERE id = '306f738c-086a-4ef8-9272-59796c9176d7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Qoidalarni tushunish". Bola endi uyda yoki bog‘dagi ayrim qoidalarni ("ovqatdan oldin qo‘l yuvish", "sirpanchiqda navbat kutish") tushunadi. Ba’zan bu qoidalarni buzishni istasa ham, sizning izchilligingiz unga ijtimoiy me’yorlarni ichki intizomga aylantirishni o‘rgatadi.') WHERE id = '4a18c5ac-a958-4970-b854-89448eb42394';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda «Tartiblash va taqqoslash». Bola endi 3-4 ta buyumni kattaligiga qarab tartib bilan joylashtira oladi. Unga turli o‘lchamdagi kublarni bering va «Eng kichigini eng ustiga qo‘y», deb ayting. Bu mashg‘ulot vizual tahlil qilish qobiliyatini ham, dastlabki matematik mantiqni ham rivojlantiradi. Har bir to‘g‘ri harakatidan so‘ng «Qanday ham e’tiborlisan!» deb uni ruhlantiring.') WHERE id = '4204844b-c0b2-424d-bc6a-7ddffcbc310c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «To‘pni uzoqdagi nishonga otish». Bola endi to‘pni shunchaki otmaydi, balki uni muayyan nuqtaga (masalan, savatga yoki siz tomonga) aniqroq yo‘naltiradi. Bu ko‘z va qo‘l muvofiqligi bilan masofani idrok etish qobiliyatining uyg‘unlashuvidir.') WHERE id = '2d64c34e-bf0d-4efe-9c0e-d67a9a461b59';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Savol-javob zanjiri». Bola endi savollaringizga shunchaki «ha/yo‘q» deb emas, to‘liq jumlalar bilan javob beradi. «Bugun nimani ko‘rding?» degan savolga «Katta bir daraxtni ko‘rdim», deb javob berishi mumkin. U bilan suhbatlashayotganda «U qanday rangda edi?», «U qayerda edi?» kabi qo‘shimcha savollar berib, nutqining rivojlanishini rag‘batlantiring.') WHERE id = 'e8d19883-dd1e-49e0-bcde-510b73e5bdc1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '880 kunni ortda qoldirdik! Bola endi 2 yarim yoshga (30 oylikka) yaqinlashmoqda. Hozir u ham jismonan, ham hissiy jihatdan ancha kuchli. U o‘z his-tuyg‘ularini ifodalay oladi («men xursandman», «men jahlim chiqdi»). Bugun u bilan birga o‘tkazgan har bir oningiz uning xotirasida o‘chmas ijobiy iz qoldiradi. Siz ajoyib onasiz!') WHERE id = '6218d94c-c601-40e6-8296-e74639caa069';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '30-oyga, ya’ni bolangizning 2 yarim yoshiga xush kelibsiz! Bu davrda bola o‘zini to‘laqonli shaxs sifatida namoyon eta boshlaydi. U «Bu meniki» yoki «O‘zim qilaman» deb, o‘z chegaralarini belgilaydi. Uning mustaqil bo‘lishga qaratilgan bu urinishlarini sabr bilan qabul qiling; bu uning fe’l-atvori shakllanishi uchun juda muhim.') WHERE id = '8c2026bd-7655-4fc6-8c90-c09af022e3d7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda «Dinamik muvozanat». Bola endi bir oyog‘ida bir necha soniya (3-5 soniya) mustaqil tura oladi. Bu uning miyachasi rivojlanayotgani va mushaklar muvofiqlashuvining ko‘rsatkichidir. U bilan «Laylak o‘yini»ni o‘ynang va kim uzoqroq tura olishini tekshiring.') WHERE id = '59136234-e72e-461f-a081-2d86fdd6b1f1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «mavhum tushunchalar». Bola endi «sevgi», «baxt» yoki «qo‘rquv» kabi hislarni nomlay boshlaydi. Uning «Sizni yaxshi ko‘raman» deyishi yoki «Men qo‘rqib ketdim» deb quchog‘ingizga kelishi hissiy intellekti (EQ) jadal rivojlanayotganini ko‘rsatadi. Uning hislarini doimo tan oling va tushunishingizni bildiring.') WHERE id = '2c9c993e-8ed6-4bde-970b-e837e161f321';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «tik va yotiq chiziqlar». Bola endi qalamni ishonchliroq ushlab, qog‘ozga bir-birining ustiga tushadigan tartibsiz chiziqlar o‘rniga aniqroq yo‘nalishdagi to‘g‘ri chiziqlar chizadi. Unga turli rangdagi bo‘yoqlar berib, «yo‘llar» yoki «narvonlar» chizishni taklif qiling.') WHERE id = '2e6c20d2-ff7f-4e05-b377-0a03f81606ea';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil gigiyena». Bola endi tishlarini tozalashga (sizning nazoratingiz ostida), qo‘llarini sovunlab, yaxshilab chayishga intiladi. Bu odatlarni shu yoshda o‘yin shaklida mustahkamlash kelajakda uning shaxsiy gigiyenaga mas’uliyat bilan yondashishiga yordam beradi.') WHERE id = '9f592616-f0c7-4018-8751-de7b0540a2d9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «rolli o‘yinlar». Bola endi o‘z «ssenariysi»ni tuzadi: o‘yinchoqlarini mehmonga chaqiradi, ularga «choy beradi» yoki ularni «uxlatadi». Bu o‘yinlar orqali u kattalar dunyosiga taqlid qilib, ijtimoiy rollar va qoidalarni chuqurroq o‘rganadi.') WHERE id = 'b497facf-4e33-44ce-bb8d-95b34db2194a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida «turli shakllarni tanish». Bola endi doira, kvadrat va uchburchak o‘rtasidagi farqni biladi hamda ularni tegishli bo‘shliqlarga joylashtiradi. «Menga kvadratni ber» deganingizda adashmasa, bu uning ko‘rish-fazoviy tafakkuri yaxshi rivojlanayotganini ko‘rsatadi.') WHERE id = 'e423f075-63ff-4c05-92b5-4ab5ac29b6be';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «orqaga yurish». Bola endi ortiga qaramasdan bir necha qadam orqaga yura oladi. Bu harakat uning tanasi fazoda qanday joylashganini his qilishi (propriosepsiya) uchun muhim. «Keling, qisqichbaqadek yuramiz», deb bu harakatni o‘yinga aylantiring; bu oyoq mushaklarini boshqacha tarzda ishlatadi.') WHERE id = '4e7bdd0e-7517-4dbe-a3fb-4614d6b6754f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Ko‘p so‘zli gaplar». Bola endi 4-5 so‘zdan iborat murakkab gaplar tuzadi: «Ona, men parkka borishni va o‘ynashni xohlayman». Uning gaplarida bog‘lovchilar va zamon qo‘shimchalari tobora ko‘proq uchraydi. U bilan suhbatlashganda, ko‘proq gapirishga undash uchun ochiq savollar bering.') WHERE id = 'd51c61a3-3310-47cc-be33-4e2fc01a2f12';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy chegaralar: Bola endi ayrim xatti-harakatlari sizga qanday ta’sir qilishini tushuna boshlaydi. U yuzingizdagi qayg‘u yoki quvonchni anglaydi. Unga «Sen baham ko‘rganingda, men juda xursand bo‘laman», deb hissiyotlar o‘rtasidagi sabab-oqibat bog‘liqligini tushuntiring. Bu uning g‘amxo‘r va ta’sirchan inson bo‘lib ulg‘ayishiga yordam beradi.') WHERE id = '00079201-58ca-47e2-bd9f-428f9b22aea3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '900 kunlik katta marraga atigi 10 kun qoldi! Bola endi «men» markazidagi fikrlashdan biroz uzoqlashib, boshqalarning ehtiyojlarini ham tushuna boshlaydi. Masalan, u sizdan «Suv xohlaysizmi?» deb so‘rashi mumkin. Uning bunday g‘amxo‘rlik harakatlarini albatta maqtang; bu uning ijtimoiy intellekti (EQ) rivojlanib borayotganidan dalolat beradi.') WHERE id = '54cacacb-5f6d-4f6a-b6ea-082797db1faf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlarda «Oyoqlarni navbatlashtirib zinadan tushish». Bola endi zinadan har bir pog‘onada oyog‘ini almashtirib tushishga harakat qiladi. Bu harakat yuqoriga ko‘tarilishdan ko‘ra qiyinroq bo‘lib, yaxshi muvozanatni talab qiladi. Sabr bilan kuting va unga ishonayotganingizni his qildiring.') WHERE id = 'ce4fa5fc-7dc5-4de0-b4e5-b9c6bb215fb4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Murakkab savollar davri». Bola endi shunchaki «Bu nima?» deb emas, balki «Nega bunday?», «Qayerga ketyapmiz?» kabi savollarni ham beradi. Javoblaringiz sodda va rostgo‘y bo‘lsin. Sizning tushuntirishlaringiz uning ongida dunyoning mantiqiy xaritasini shakllantiradi. Uning qiziqishini doimo rag‘batlantiring: «Sizningcha, nega bunday?».') WHERE id = 'b47ac63c-a31b-4cfe-b3d9-64f08edba2f8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Doira va xoch chizish». Bola endi qalamni ko‘proq «kattalardek» (uch barmog‘i bilan) ushlay boshlaydi hamda qog‘ozga doira va xoch kabi shakllarni chizishga urinadi. Bu kelajakdagi yozish ko‘nikmalari uchun eng muhim harakat qobiliyatlaridan biridir. Unga rangli bo‘rlar bering.') WHERE id = '4c756f1e-f764-4f55-8535-6552dafc167f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil ovqatlanish va tanlov". Bola endi dasturxon atrofida qancha ovqat yeyishini o‘zi hal qilishni xohlaydi. Uni majburlab ovqatlantirishdan saqlaning. O‘ziga xizmat qilish ko‘nikmasi rivojlangani sari, unga o‘z likopchasini (agar xavfsiz bo‘lsa) oshxonaga olib borishni taklif qiling. Bu unda oila ichidagi mas’uliyat hissini shakllantiradi.') WHERE id = '04c3f7db-69bb-44ed-8348-5d4d92cb8c92';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Xayoliy o‘yin do‘stlari". Bola endi o‘yinchoqlari bilan gaplashadi, ularga topshiriqlar beradi va xuddi ular tirikdek munosabatda bo‘ladi. Bu uning tasavvuri qanchalik boyligi va voqealar o‘rtasidagi mavhum bog‘liqliklarni qanchalik yaxshi shakllantira olishining belgisidir.') WHERE id = '2c67e108-3cf8-4072-89be-1ff519eaddcc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Rang tuslarini farqlash". Bola endi shunchaki "yashil" rangni emas, balki och va to‘q yashil ranglarni ham ko‘rish orqali farqlay oladi. Unga turli rang tuslaridagi barglar yoki qalamlarni ko‘rsatib, "Qaysi biri to‘qroq?" o‘yinini o‘ynang. Bu uning vizual tahlil qilish qobiliyatini rivojlantiradi.') WHERE id = 'dcddf5f8-faa5-4048-a797-208e9715f0bf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Uch g‘ildirakli velosipedga qiziqish". Bola endi pedallarni aylantirishga yoki oyoqlarini yerga tirab, o‘zini oldinga itarishga harakat qiladi. Bu harakat oyoq mushaklarini mustahkamlash bilan birga, makonda yo‘nalishni boshqarish ko‘nikmasini ham rivojlantiradi.') WHERE id = 'a4633b77-b5aa-45ed-9da1-475ae9482abc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "O‘tgan va kelasi zamon". Bola endi "Ertaga boramiz" yoki "Kecha bordik" kabi zamon farqlarini (hali to‘liq aniq bo‘lmasa-da) nutqida qo‘llashga harakat qiladi. Kun oxirida u bilan "Bugun nima qildik?" va "Ertaga nima qilamiz?" mavzularida suhbatlashing. Bu uning xotirasi va rejalashtirish ko‘nikmasini mustahkamlaydi.') WHERE id = '3e7a62e8-608e-4fd7-88f9-177ba74dcb48';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tabriklaymiz, 900 kunni ortda qoldirdik! Bola endi 2 yarim yoshga (30 oyga) yetdi. U hozir ham jismonan, ham hissiy jihatdan yanada kuchli, mustaqil va ijodkor. Shu 900 kun davomida ko‘rsatgan mehringiz va fidoyiligingiz uning butun kelajak hayoti uchun poydevor bo‘ldi. Siz ajoyib ishni uddaladingiz, Ona!') WHERE id = '3d5a9ac6-ec3e-4630-b503-91b84d5fef32';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '900 kunlik katta marrani ortda qoldirib, yangi bosqichni boshlayapmiz! Bola endi 31-oyga qadam qo‘ymoqda. U hozir o‘z ismini ham, oila a’zolarining ismlarini ham aniq ayta oladi. U bilan oilaviy albomni tomosha qilib, «Bu kim?» o‘yinini o‘ynang. Bu uning oilaga mansublik hissini ham, og‘zaki xotirasini ham mustahkamlaydi.') WHERE id = '5482dfbc-7126-4e7c-8510-4a2cfbf55aee';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda «Bir oyoqda sakrash». Bola endi bir oyog‘ida juda oz bo‘lsa-da, sakrashga urinadi. Bu to‘piq va boldir mushaklari ancha rivojlanganidan dalolat beradi. Bog‘da u bilan «quyoncha bo‘lib sakrash» musobaqasini o‘tkazib, bu ko‘nikmasini qo‘llab-quvvatlang.') WHERE id = '2840aa13-bbb5-476f-ad1f-11685bbcd555';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Fikrini asoslash». Bola endi istaklarini shunchaki bildirmaydi, balki ularni asoslaydi: «Men bu qo‘g‘irchoqni xohlayman, chunki u chiroyli». Uning «chunki» bilan boshlanadigan izohlarini diqqat bilan tinglang. Bu uning mantiqiy tafakkuri va o‘z fikrini ifodalash qobiliyati qay darajada rivojlanganini ko‘rsatadi.') WHERE id = 'dd18fee0-7070-455b-a654-1c5450138cd5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Maqsadli bo‘yash». Bola endi qog‘ozdagi yirik shakllarning (masalan, katta olma rasmining) chegaralarini anglaydi va bo‘yash paytida chiziqdan chiqmaslikka harakat qiladi. Bu qo‘l mushaklarini boshqarishda katta qadamdir. Unga konturlari yirik bo‘lgan bo‘yash varaqlarini bering.') WHERE id = '25d06f6c-6efb-491d-ac80-8bbd8fa74917';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil kiyinish» va tugmalar. Bola endi katta tugmalarni yechishga yoki fermuarni (uchi biriktirib berilgach) yuqoriga tortishga qiziqish bildirmoqda. Unga «Qani, o‘zing sinab ko‘r» deb, buni mustaqil bajarish imkonini bering. O‘zi kiyina olishi bolada «men buni uddalay olaman» degan tuyg‘u va o‘ziga ishonchni nihoyatda oshiradi.') WHERE id = 'e6e7a26c-5b45-4894-8a1d-19ed6e362c71';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Hamkorlik va bo‘lishish». Bola endi o‘yinchog‘ini boshqalar bilan bo‘lishganda, bu vaqtinchalik ekanini tushunadi. Uni «Avval biroz sen o‘yna, keyin men» tamoyili bilan tanishtirish vaqti keldi. Bu uning sabrini ham, ijtimoiy hamdardlik tuyg‘usini ham shakllantiradi.') WHERE id = '79abc2a4-51b0-4f9f-8334-d1eb1d4ea6eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida «Hajmni anglash». Bola katta qutiga kichik quti sig‘ishini, aksincha esa buning iloji yo‘qligini ko‘rib tushunadi. Unga turli o‘lchamdagi idishlarni berib, «Qaysi biri buning ichiga sig‘adi?» deb so‘rang. Bu kelajakdagi matematik va geometrik tafakkurning asosi bo‘lgan fazoviy idrokdir.') WHERE id = '615744e3-fb18-42f6-8110-3e9a2d54709c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «To‘pni nishonga otish». Bola endi to‘pni shunchaki otmaydi, balki uni siz tomonga yoki muayyan quti (savat) ichiga aniq yo‘naltiradi. Bu qo‘l va ko‘z muvofiqlashuvi bilan masofani his qilish qobiliyatining uyg‘unlashuvidir. U bilan «kichik basketbol» o‘ynang.') WHERE id = '8fa193ab-3d15-4b10-9608-9e3d2bd116d1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Mavhum tushunchalar». Bola endi «sevgi», «xafa bo‘lmoq», «sog‘inmoq» kabi so‘zlarni o‘rinli ishlatadi. Uning «Sizni sog‘indim» deyishi hissiy intellekti yuksak rivojlanayotganidan dalolat beradi. Uning bu hislarini albatta e’tirof eting va siz ham o‘z hislaringizni ifodalang: «Men ham seni ko‘rganimdan juda xursandman».') WHERE id = '13cc3bef-f498-4191-9d8c-212c97c4c3e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvur kuchi: «Ko‘rinmas mehmonlar». Bola endi o‘yinchoqlarini mehmonga chaqirib, ularga xayoliy taomlar taklif qiladi. Bunday «xuddi rostdagidek» o‘yinlar uning xotirasidagi ijtimoiy vaziyatlarni amalda sinab ko‘rish usulidir. Siz ham uning xayoliy dunyosiga mehmon sifatida qo‘shiling!') WHERE id = 'a44149c1-0e64-49a3-936a-9d1d3a595e97';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki «qizil» yoki «ko‘k» deb ajratibgina qolmay, ularning to‘q va och tuslarini ham ko‘rib farqlay boshlaydi. Unga turli rangdagi qalamlarni berib, «Eng to‘q ranglisini menga ber» deb, ko‘rish orqali tahlil qilish qobiliyatini tekshiring. Bu uning diqqatini ham, estetik idrokini ham rivojlantiradi.') WHERE id = '5bd4135a-236e-4d8e-8be3-3ebc28e05d9e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda «Orqaga yurish». Bola endi muvozanatini yo‘qotmasdan orqaga bir necha qadam yura oladi. Bu harakat uning o‘z tanasini his qilishini (propriosepsiya) va fazoda mo‘ljal olish qobiliyatini mustahkamlaydi. U bilan «Qisqichbaqa kabi yuramiz» o‘yinini o‘ynang.') WHERE id = '54996f87-c947-4849-9084-027fb47fcd81';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qofiyali so‘zlar va qo‘shiqlar". Bola avval eshitgan qo‘shiqlarining oxirgi so‘zlarini qofiyaga mos tarzda aytib tugatishni juda yaxshi ko‘radi. Bu uning fonematik eshitish qobiliyati rivojlanayotganidan dalolat beradi. U bilan birga she’rlar o‘qing va oxirini o‘zi davom ettirishi uchun to‘xtang. Bu uning ham xotirasini, ham nutq sur’atini tartibga soladi.') WHERE id = 'acf4d772-adf5-4683-b12b-56ef67f21202';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Munchoqlardan ip o‘tkazish". Bola endi katta teshikli munchoqlar yoki makaron donalaridan ip o‘tkazishni yaxshi uddalaydi. Bu harakat sabrni ham, barmoqlarning nozik muvofiqlashuvini ham talab qiladi. Shu tariqa u kelajakdagi yozish ko‘nikmalari uchun mushak xotirasini shakllantiradi.') WHERE id = 'acfd54f8-89c0-45e8-b646-d1e1362647ed';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil gigiyena"dagi taraqqiyot. Bola endi qo‘llarini yuvgach, ularni mustaqil ravishda sochiq bilan quritishni va sochiqni joyiga osishni biladi. Bunday kichik "yakunlash" harakatlari uning o‘ziga xizmat qilish mas’uliyatini oshiradi. Uning bu tartibli xatti-harakatini "Qarang, qanday ozoda ekansiz!" deb maqtang.') WHERE id = 'd2072154-6990-473d-aae5-34ace20cbb48';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Boshqalarning his-tuyg‘ularini tushunish". Bola endi yuzingizdagi qayg‘u yoki charchoqni ko‘rib, "Nima bo‘ldi?" deb so‘rashi mumkin. Bu hamdardlikning eng sof ko‘rinishidir. Unga his-tuyg‘ularingizni sodda tilda tushuntiring: "Biroz charchadim, kel, birga dam olaylik". Bu uning hissiy intellektini (EQ) rivojlantiradi.') WHERE id = '146ce216-737a-480c-9a11-95c561e541a4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Tartiblash va taqqoslash". Bola endi 3-4 ta o‘yinchog‘ini o‘lchamiga qarab (kichikdan kattaga) tartiblay oladi. Bu dastlabki matematik mantiqning asosidir. Unga "Eng katta ayiqchani eng oldinga qo‘y" kabi topshiriqlar bering. Bu vizual tahlil qilishni ham, diqqatni jamlashni ham o‘rgatadi.') WHERE id = 'a0704d4b-bb47-4a9f-8d8c-90add9dfed0e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashuv: "Dinamik muvozanat". Bola endi past tortilgan arqon yoki yerga chizilgan chiziq ustidan "dorboz" kabi yurishga qiziqish bildirmoqda. Bu uning vestibulyar tizimi (muvozanat markazi) yetilayotganidan dalolat beradi. Bog‘da bordyurlar ustida yurganida qo‘lidan ushlab, uning bu jasoratini qo‘llab-quvvatlang.') WHERE id = '536458a4-4f3e-423b-9a13-cba42297d147';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Vaqt tushunchasi: kecha va ertaga». Bola bu so‘zlarni hali aniq vaqtni ifodalash uchun ishlatmasa-da, o‘tmish va kelajakdagi voqealarni farqlashga harakat qiladi. Kun oxirida u bilan «Ertaga qayerga boramiz?» mavzusida suhbatlashing. Bu uning rejalashtirish ko‘nikmasini rivojlantiradi va voqealar o‘rtasidagi vaqt bog‘liqligini tushunishiga yordam beradi.') WHERE id = '6849680a-6227-4b9c-ad36-2d8926dfdf15';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: bola biror ishni uddalay olmaganida (masalan, kublar qulab tushganda) darhol yig‘lamasdan, qaytadan urinib ko‘rishi mumkin. Bu «kurashuvchanlik ruhi» uning kelajakda muvaffaqiyatli o‘rganishi uchun juda muhim. Unga «Juda harakat qilayotganingni ko‘ryapman», deb natijani emas, sa’y-harakatini maqtang.') WHERE id = '86a0403c-8de6-429b-885d-6a2141aa02c8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '31-oyning so‘nggi o‘n kunligini boshlaymiz! Bola endi «men» va «meniki» so‘zlarini kuchli egalik hissi bilan ishlatadi. Bu davrda uning egalik hissini hurmat qilish muhim. Unga «Bu sening o‘yinchog‘ing, ammo kel, do‘sting bilan navbatma-navbat o‘ynab ko‘ramiz», deb bo‘lishish tanlov ekanini ko‘rsating.') WHERE id = '84330770-7540-4b55-849d-a1cc950ead4d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda «Ikki oyoqda oldinga sakrash mahorati». Bola endi faqat turgan joyida emas, balki biroz oldinga (taxminan 10-20 sm) ham sakray oladi. Bu oyoq mushaklarining keskin kuch hosil qilish qobiliyati ortganini ko‘rsatadi. Yerga kichik «to‘siqlar» (masalan, rangli tasmalar) qo‘yib, u bilan sakrash o‘yinini o‘ynang.') WHERE id = '5741e7d1-1ed4-44c7-a88a-391b61cdae5d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Murakkab gap tuzilmalari». Bola endi ikki xil fikrni bog‘lovchilar yordamida birlashtiradi: «Men parkka borishni va arg‘imchoqda uchishni xohlayman». Uning gaplarida maqsad va niyat yanada aniqroq namoyon bo‘ladi. U bilan suhbatlashayotganda «Nega?» deb so‘rab, batafsilroq tushuntirish berishga undang.') WHERE id = '1e35c889-6f4c-4fd3-ae21-e3389ec8548d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Saranjom buklash». Bola endi sizga taqlid qilib, qog‘oz yoki kichik sochiqni buklashga harakat qiladi. Bu harakat qo‘l-ko‘z muvofiqligini hamda vizual simmetriya hissini rivojlantiradi. Kiyimlarni yig‘ayotganda unga kichik ro‘molchalarini buklashni topshiring.') WHERE id = '3690ca7a-82f5-4004-93ab-5126e1011625';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil ovqatlanish va dasturxon odobi". Bola endi qoshiq va sanchqidan foydalanganda deyarli hech narsani to‘kib yubormaydi. U "Yoqimli ishtaha" yoki "Rahmat" kabi dasturxon atrofida ishlatiladigan iboralarni o‘rnida ayta boshlaydi. Uning bunday odobli muomalasini doimo maqtang — bu kelajakdagi muloqot madaniyatining poydevoridir.') WHERE id = '43e9a2b0-67bf-44dc-b37a-1d4a9e1b3e86';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Rolli o‘yinlarning murakkablashuvi". Bola endi o‘zini o‘qituvchi, shifokor yoki ota-ona kabi tutib, sizga "ko‘rsatmalar" berishi mumkin. Bu o‘yinlar orqali u ijtimoiy rollarni o‘zlashtiradi. Uning "darslarida" ishtirok eting — bu uning yetakchilik qobiliyatini rivojlantiradi.') WHERE id = 'd218ecc4-3eae-4f6a-ba4c-e1f3fc1576d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Son va miqdor o‘rtasidagi ilk bog‘liqlik". Bola 1-dan 5-gacha sanashni yoddan bilishi bilan birga, endi "ikkita olma" deyilganda miqdorni ham tushuna boshlaydi. Undan "Menga ikkita qalam ber" deb, sonni miqdor bilan moslashtirishini so‘rang. Bu matematik tafakkur rivojining eng muhim bosqichlaridan biridir.') WHERE id = 'e77c9dc0-0ffc-4afa-af6f-98372ac9412c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish harakatlari". Bola endi yugurayotganda oldidagi to‘pni muvozanatini yo‘qotmasdan tepishi va yo‘nalishini o‘zgartirishi mumkin. Bu dinamik muvozanat takomillashganini ko‘rsatadi. U bilan ochiq havoda "futbol" o‘ynash uchun ayni muddao.') WHERE id = 'f27d93f9-9b8c-4331-9608-1f9403361289';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Yangi lug‘at: Sifatlarning ko‘payishi". Bola endi buyumlarni tasvirlashda "yumshoq", "qattiq", "issiq", "sovuq", "og‘ir" kabi so‘zlardan foydalanadi. Unga turli tuzilishga ega buyumlarni bering va "Bu qanday tuyuladi?" deb so‘rang. Sifatlar zaxirasining boyishi unga dunyoni yanada batafsil idrok etishga yordam beradi.') WHERE id = '2a117057-8af9-4f1a-8e6e-3d0291275ec5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy yetuklik: Bola endi ba’zan o‘zining jahli chiqqanini anglaydi va "Jahlim chiqdi" deb ayta oladi. Bu hissiy o‘zini anglash yo‘lidagi katta yutuqdir. Bunday paytlarda uni quchoqlab, "Tushunaman, kel, birga tinchlanamiz" deng. 930 kunlik yo‘lni muvaffaqiyatli yakunladik — siz ajoyib hamrohsiz!') WHERE id = '9e7e7732-10aa-4ec3-9e8d-653645d590eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi «oldin» va «keyin» ketma-ketligini yanada chuqurroq anglaydi. «Kiyimingni kiy, keyin tashqariga chiqamiz» deganingizda, u ikkinchi harakat mukofot ekanini tushunadi. Bu bolada sabr-toqat va rejalashtirish ko‘nikmalarining ilk kurtaklaridir. Kundalik odatlarda bu ketma-ketliklarni unga tez-tez eslatib turing.') WHERE id = '97310562-0cc9-4922-aab5-bb0de93781d6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda «Tirmashib chiqish mahorati». Bola endi bog‘dagi zinapoyalarga yoki uydagi xavfsiz balandliklarga yanada ishonch bilan chiqadi. Bunda qo‘l va oyoq mushaklari uyg‘unlikda ishlaydi. Doimo yaqinida bo‘ling, ammo unga o‘z kuchini sinab ko‘rish imkonini bering.') WHERE id = '5e669269-1aa2-4602-9a6d-be602f929f7a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Mantiqiy bog‘lanishlar». Bola endi ikki hodisani bitta gapda bog‘laydi: «Havo sovuq, kurtkangni kiy». Bu uning shunchaki taqlid qilmayotganini, balki fikrlayotganini ham ko‘rsatadi. O‘z fikrlarini ifodalashga yanada ko‘proq intilishi uchun uning bunday mantiqiy mulohazalarini «Ha, to‘g‘ri aytyapsan» deb tasdiqlang.') WHERE id = 'c578b6d7-6027-41d3-bcb5-015328604f79';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Qog‘oz bilan ishlash». Bola endi qog‘ozni buklashga yoki oddiy shaklda kesishga (bolalar uchun katta qaychi bilan va nazorat ostida) qiziqish bildirishi mumkin. Bu harakatlar barmoq mushaklarini boshqarish qobiliyatini yangi bosqichga olib chiqadi. Unga rangli qog‘ozlar bilan ishlash uchun sharoit yarating.') WHERE id = '369aa3fa-b6a2-4869-aff0-584c7cb30be3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Rolli o‘yinlarning murakkablashishi». Bola endi «shifokor», «oshpaz» yoki «haydovchi» roliga kiradi. Bu o‘yinlar orqali u atrofidagi odamlarning vazifalarini o‘rganadi va hamdardlik qilishni o‘zlashtiradi. Uning bu o‘yinlariga qo‘shiling va u sizga bergan «rol»ga muvofiq harakat qiling.') WHERE id = '71802808-c37b-439f-8b0c-227ce432a07a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil tozalik» odati. Bola endi qo‘llarini yuvayotganda sovunlash va chayishni deyarli mustaqil bajara oladi. Bu yoshda gigiyena odatlarining mustahkamlanishi juda muhim. Bu jarayondan zavqlanishi uchun unga bo‘yiga mos zinapoyacha (step stool) olib bering.') WHERE id = '916356ea-060f-4a2e-8be7-98dcab3ad0ee';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida «Farqlisini top» bosqichi. Bola endi bir guruh buyumlar orasidan boshqacha bo‘lganini (masalan, mashinalar orasidagi olmani) ko‘rib ajrata oladi. Bu uning tahlil qilish qobiliyatini rivojlantiradi. Uyda u bilan «Qaysi biri ortiqcha?» kabi oddiy o‘yinlarni o‘ynang. Bu kelajakdagi matematik va mantiqiy topshiriqlar uchun ajoyib tayyorgarlikdir.') WHERE id = '9c6d24fc-1a56-41e1-93ca-e94c8c830e4f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Bir oyoqda turishga urinishlar». Bola endi bir necha soniyaga bo‘lsa ham, bir oyog‘ini yerdan ko‘tarib, muvozanatni saqlashga harakat qiladi. Bu tanasining og‘irlik markazini his qilishi uchun muhimdir. U bilan «Laylak» o‘yinini o‘ynang va kim uzoqroq tura olishini sinab ko‘ring.') WHERE id = '1769bf32-48e2-40a7-b480-c6f396b19e4b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «His-tuyg‘ularni ifodalash». Bola endi xafa, xursand yoki qo‘rqayotganini so‘z bilan ayta oladi: «Men qo‘rqdim» yoki «Men xursandman». His-tuyg‘ularni nomlash bolada emotsional intellekt shakllanishining asosidir. U o‘z hissini aytganida, uni tinglang va «Ha, sizni tushunaman» deb, his-tuyg‘ularini tan olganingizni ko‘rsating.') WHERE id = '7f6f2c0c-ef35-4291-8d3c-3c98cbe7cfa1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvur kuchi: «Ramziy fikrlash». Bola tayoqni «ot» deb tasavvur qilib, uni minib chopgandek yurishi mumkin. Bu bir buyum boshqa narsaning timsoli bo‘la olishini tushunish qobiliyatidir. Bu ko‘nikma kelajakda o‘qish va matematikani o‘rganish (ramzlarni tushunish) uchun juda muhim. Siz ajoyib yo‘l-yo‘riq ko‘rsatyapsiz!') WHERE id = 'b4910186-9bb2-4fc8-898b-364f4deeed97';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '32-oyning so‘nggi o‘n kunligini boshlaymiz! Bola endi «biz» tushunchasini anglay boshlaydi. «Biz bog‘ga ketyapmizmi?» deb, o‘zini oilaning ajralmas qismi sifatida namoyon etadi. U bilan suhbatlashayotganda oilaviy rejalaringizni ayting: «Bugun biz buvingnikiga boramiz». Bu bolada tegishlilik va xavfsizlik hissini kuchaytiradi.') WHERE id = '1b278c24-eef1-4629-acd4-d211ef0e2e61';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlanishda «Zinadan erkin chiqish». Bola endi zinadan har bir pog‘onaga bittadan qadam bosib (oyoqlarini navbatlashtirib) va faqat bir qo‘lidan ushlagan holda ishonch bilan ko‘tarila oladi. Bu uning yirik motorikasi yaxshi rivojlanganini ko‘rsatadi. Siz shunchaki yonida bo‘lib, unga ma’naviy dalda bering.') WHERE id = '275df927-814f-46e6-87b1-244d3e43ae78';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hikoya tuzish". Bola endi rasmlarga qarab oddiy hikoyalar o‘ylab topadi. "Mushuk keldi, sut ichdi, uxladi" kabi izchil gaplar uning xotirasi va tasavvuri uyg‘unligidan dalolat beradi. Unga qiziqarli rasmlari bor kitoblar bering va "Bu yerda nima bo‘lyapti?" deb so‘rang. Bu uning ijodiy fikrlashini yanada rivojlantiradi.') WHERE id = '904512e9-992f-4497-b856-79751b10de80';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Aniq joylashtirish". Bola endi kichik o‘yinchoq shakllarini joylashtirish yoki munchoqlarni ipga tizishni kamroq xato bilan bajara oladi. Bu davrda barmoq uchlarining sezgirligi ortadi. Unga turli tuzilishga ega kichik buyumlar bilan o‘ynashni taklif qiling (albatta, nazoratingiz ostida).') WHERE id = 'd9171a51-69d8-4d0a-829c-7db5c26a601f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish" istagi. Bola endi tugmasiz ko‘ylaklari yoki shimini o‘zi kiyishga qat’iy turib oladi. "O‘zim!" degan paytlarida unga vaqt bering. Mustaqil bo‘lishga qaratilgan bu urinishlar kelajakdagi o‘ziga ishonch va shaxsiy mas’uliyatning eng mustahkam poydevoridir. Uning kichik yutuqlarini "Qarang, o‘zing uddalading!" deb e’tirof eting.') WHERE id = 'b1c5306b-77bb-4136-8d44-3c944e44a9e3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Odob qoidalari". Bola endi "Iltimos", "Rahmat", "Marhamat" kabi so‘zlarni shunchaki takrorlamaydi, balki maqsadga muvofiq ishlatadi. Sizning xushmuomala xatti-harakatingiz uning uchun eng yaxshi namunadir. Bunday xatti-harakatlarini maqtash orqali uning muloqot madaniyatini mustahkamlang.') WHERE id = '9e1b06c8-d4a2-4b28-b3bc-ad2c39ab7cb0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Payt ravishlari". Bola "keyin", "birozdan so‘ng", "hozir" so‘zlarini o‘z o‘rnida ishlata boshlaydi. "Birozdan so‘ng kelaman" deganingizda, u vaqt o‘tishini tushunadi. Bu bolada kutish va o‘zini boshqarish ko‘nikmasini rivojlantiradi. Kundalik odatlaringizda bu so‘zlardan tez-tez foydalaning.') WHERE id = '6f964b8f-02b2-4bed-adce-f35ba0656a6a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va nishon". Bola endi to‘pni shunchaki tepib yubormaydi, balki uni muayyan yo‘nalishga — masalan, ikkita o‘yinchoq orasidan o‘tkazishga harakat qiladi. Bu qo‘l-ko‘z va oyoq-ko‘z muvofiqlashuvining uyg‘un ishlashidir. U bilan uyda "mini futbol" turnirini o‘tkazing.') WHERE id = '61ba305a-b8ae-4528-9ce2-bd394666ba9a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Mavhum savollar». Bola «Bulut qayerdan keladi?», «Oy qayerga ketdi?» kabi savollar berishi mumkin. Javob berayotganda xayoliy va haqiqiy ma’lumotlarni uyg‘unlashtiring: «Bulutlar uzoqdan kelib, bizga yomg‘ir olib keladi». Bunday suhbatlar uning dunyoqarashi va o‘rganishga bo‘lgan qiziqishini nihoyatda kengaytiradi.') WHERE id = 'a8a1120b-b774-4f04-89b0-c124a8cbf647';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: bola endi muvaffaqiyatsizlikka nisbatan chidamliroq. Kublari qulab tushganda darhol yig‘lamaydi, «Qaytadan quraman», deya oladi. Undagi bu qat’iyatni qo‘llab-quvvatlang. 950 kunlik yo‘lni bosib o‘tdik, 1000 kunga juda oz qoldi! Siz bu yo‘lda ham ustoz, ham eng yaqin do‘stsiz!') WHERE id = 'c5fe4618-aa8a-4004-b14e-8472a1232fc2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni nafaqat turiga, balki rang tuslariga qarab ham guruhlay oladi. Unga yashil rangning turli tuslaridagi o‘yinchoqlarni berib, «Och rangdan to‘q rangga qarab terib chiqamiz», deng va ko‘rish orqali tahlil qilish qobiliyatini rivojlantiring. Bu uning estetik idroki va diqqatini yanada o‘tkirlashtiradi.') WHERE id = '4cccdb9f-0090-4953-be45-4aac0e3ecdc0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda «Bir oyoqda sakrash». Bola endi bir oyog‘ida juda kichik sakrashga urinadi. Bu to‘piq kuchi va vestibulyar tizimning (muvozanatning) yaxshi rivojlanganidan dalolat beradi. U bilan «Quyoncha» o‘yinini o‘ynang. Yiqilishdan qo‘rqmay, erkin harakat qilishi uchun doimo yonida bo‘ling.') WHERE id = '611c7f89-d565-4c80-b60a-401386c94dd3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Qarama-qarshi ma’noli so‘zlar». Bola endi «katta-kichik», «issiq-sovuq», «og‘ir-yengil» kabi qarama-qarshiliklarni to‘liq anglaydi va nutqida qo‘llaydi. Unga «Bu tosh og‘ir, paxta-chi, u qanday?» kabi savollar bering. Bu uning lug‘at boyligini sifat jihatdan oshiradi va qiyosiy fikrlashini kuchaytiradi.') WHERE id = '8c5fde41-64b4-4f6a-8c4b-9b0a4470f2ce';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Murakkabroq konstruksiyalar». Bola endi kublardan shunchaki minora emas, balki «zinapoya», «to‘siq» yoki «darvoza» kabi oraliqli shakllarni ham yasaydi. Bu uning fazoviy tafakkuri va muhandislik intuitsiyasining ilk haqiqiy belgilaridir.') WHERE id = '8323ecc8-fdd4-4a47-acab-de738c3b3b74';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov: Ob-havo va kiyim". Bola tashqarida havo sovuq bo‘lsa, qalinroq kiyinish kerakligini endi tushunadi. Unga "Bugun tashqarida havo sovuq, qaysi kurtkani kiyishni xohlaysan?" deb, ikkita variant taklif qiling. O‘z tanloviga ko‘ra kiyinish bolada mas’uliyat hissi va qaror qabul qilish ko‘nikmasini rivojlantiradi.') WHERE id = 'b6331bb4-9640-46b8-a4de-673e4569b48f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Ramziy bo‘lishish". Bola endi o‘zi uchun unchalik qadrli bo‘lmagan o‘yinchoqni do‘stiga ixtiyoriy ravishda berishi mumkin. Bu egotsentrik davrdan (hamma narsa meniki) chiqish va ijtimoiy hamkorlikning boshlanishidir. Uning bu saxiyligini albatta "Qanday g‘amxo‘rsan!" deb maqtang.') WHERE id = '7a5cc16d-c4e3-465c-94b4-27327272c867';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Tartiblash va sanash". Bola 1-dan 10-gacha yoddan sanashdan tashqari, buyumlarni barmog‘i bilan ko‘rsatib, "bir, ikki, uch" deya ularning miqdorini sanay boshlaydi. Unga "Bu yerda nechta mashina bor?" deb savol bering. Bu mavhum raqamlar real dunyo bilan ilk bor jiddiy bog‘lanadigan bosqichdir.') WHERE id = '27d58f54-7d91-4fc1-9abe-0e7741238b0e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlik: "Orqaga yurish va yugurish". Bola endi orqasiga qaramay, ishonch bilan orqaga yura oladi va hatto bir necha qadam yugura oladi. Bu harakat uning tana muvofiqligi qay darajada rivojlanganini ko‘rsatadi. U bilan "Qisqichbaqa poygasi" o‘yinini o‘ynab, birga zavqlaning va mushaklarini boshqacha usulda ishlating.') WHERE id = '5835a9f7-31b7-47bc-af3b-fbaf1eae167a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Bog‘lovchilardan foydalanish". Bola "va", "ammo", "chunki" so‘zlarini gapga qo‘shib, fikrini yanada to‘liqroq ifodalaydi: "Men ochman, ammo ovqat yeyishni xohlamayman". Uning gaplarini tinglang va siz ham shunga o‘xshash murakkab gaplar bilan javob bering. Bu uning grammatikani anglash qobiliyatini yanada takomillashtiradi.') WHERE id = 'e679f00c-7a2a-4673-af5d-88a6f4d8128e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: Bolaning biror ishi o‘xshamasa, endi darhol sizdan yordam so‘ramaydi, balki o‘zi bir necha marta urinib ko‘radi. Uning bu qat’iyatini (yaxshi ma’noda) qo‘llab-quvvatlang. "Juda ko‘p harakat qilayotganingni ko‘ryapman" deyish unga natijadan ko‘ra jarayonni ko‘proq sevishga yordam beradi. 1000 kunga atigi 40 kun qoldi!') WHERE id = '73811b23-1334-47b6-aa32-fe16ca9f7dfe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "men", "sen" va "biz" olmoshlarini o‘z o‘rnida to‘g‘ri ishlatadi. "Biz hozir ovqat yeymizmi?" deb, o‘zini oilaning faol a’zosi sifatida his qiladi. U bilan suhbatlashayotganda uni ham rejalaringizga qo‘shing: "Kel, birga dasturxon tuzaylik". Bu uning daxldorlik va mas’uliyat hissini kuchaytiradi.') WHERE id = '0088ee7c-73a0-42ed-a073-c3d4d5a577af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlanishda "Zinadan erkin chiqish". Bola endi zinadan oyoqlarini navbatma-navbat qo‘yib va faqat bir qo‘lidan ushlab turilganda ishonch bilan ko‘tariladi. Bu uning yirik motorikasi to‘liq shakllanganini ko‘rsatadi. Siz shunchaki yonida bo‘lib, unga ma’naviy dalda bering.') WHERE id = 'bf415e92-93fc-4c0c-8e41-d0e69018f7ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hikoya tuzish". Bola endi rasmlarga qarab oddiy hikoyalar to‘qiydi. "Mushuk keldi, sut ichdi, uxladi" kabi izchil gaplar uning xotirasi va tasavvuri uyg‘unlashganini ko‘rsatadi. Unga qiziqarli rasmlari bor kitoblarni bering va "Bu yerda nima bo‘lyapti?" deb so‘rang. Bu uning ijodiy fikrlashini rivojlantiradi.') WHERE id = 'e900e935-8ccc-4908-bf87-10603eb74cda';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Aniq joylashtirish". Bola endi kichik o‘yinchoq shakllarini joylashtirish yoki munchoqlarni ipga tizishni kamroq xato bilan bajara oladi. Bu davrda barmoq uchlarining sezgirligi ortadi. Unga turli tuzilishga ega kichik buyumlar bilan o‘ynashni taklif qiling (albatta, nazorat ostida).') WHERE id = '6c732ec0-7e78-45c4-a464-029d46e20701';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish" istagi. Bola endi tugmasiz ko‘ylaklari yoki shimini o‘zi kiyishga qat’iy turib oladi. "O‘zim!" degan paytlarida unga vaqt bering. Mustaqillikka bo‘lgan bu urinishlar kelajakdagi o‘ziga ishonch va shaxsiy mas’uliyatning eng mustahkam poydevoridir. Uning kichik yutuqlarini "Qara, o‘zing uddalading!" deb e’tirof eting.') WHERE id = '3fe4a18c-cebd-45f6-88ed-6acbe7109fd0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Odob qoidalari". Bola endi "Iltimos", "Rahmat", "Marhamat" kabi so‘zlarni shunchaki takrorlamaydi, balki maqsadli ravishda ishlatadi. Sizning xushmuomala munosabatingiz uning uchun eng yaxshi namunadir. Uning bunday xatti-harakatlarini maqtash orqali muloqot madaniyatini mustahkamlang.') WHERE id = 'e6b8bd35-5e9c-4328-a121-a6fecf7c7d62';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Payt ravishlari". Bola "keyin", "birozdan so‘ng", "hozir" so‘zlarini o‘z o‘rnida ishlata boshlaydi. "Birozdan so‘ng kelaman" desangiz, u vaqt o‘tishini tushunadi. Bu bolada kutish va o‘zini boshqarish ko‘nikmalarini rivojlantiradi. Kundalik odatlaringizda bu so‘zlardan tez-tez foydalaning.') WHERE id = 'eac1461c-042b-436c-8d00-465739e12f49';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va nishon". Bola endi to‘pni shunchaki tepmaydi, balki uni muayyan yo‘nalishga — masalan, ikkita o‘yinchoq orasidan o‘tkazishga harakat qiladi. Bunda qo‘l-ko‘z va oyoq-ko‘z muvofiqligi bir vaqtda ishlaydi. U bilan uyda "mini futbol" musobaqasini o‘tkazing.') WHERE id = '3ddf5bfb-d5a6-4b94-8ee2-f4ce76892d43';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum savollar". Bola "Bulut qayerdan keladi?", "Oy qayerga ketdi?" kabi savollar berishi mumkin. Javob berayotganda tasavvur va haqiqiy ma’lumot o‘rtasidagi muvozanatni saqlang: "Bulutlar uzoqdan kelib, bizga yomg‘ir olib keladi". Bunday suhbatlar uning dunyoqarashi va o‘rganishga bo‘lgan ishtiyoqini nihoyatda kengaytiradi.') WHERE id = '1a341992-7717-4fca-abe1-d703ab6a7a2f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: Bola endi muvaffaqiyatsizlikka nisbatan chidamliroq. Kublari qulab tushganda darhol yig‘lamaydi, "Yana qaytadan quraman" deya oladi. Undagi bu kurashuvchanlik ruhini qo‘llab-quvvatlang. 970 kunlik yo‘lni ortda qoldirdik, 1000 kungacha atigi 30 kun qoldi! Siz bu yo‘lda ham ustoz, ham eng yaqin do‘stsiz!') WHERE id = 'e1da111f-ccec-436b-a492-b6e924de37bf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglarni shunchaki "qizil" yoki "ko‘k" deb emas, balki ularning to‘q va och tuslarini ham ko‘rib farqlay boshlaydi. Unga turli rangdagi qalamlarni berib, "Menga eng to‘q ranglisini ber" deya vizual tahlil qilish qobiliyatini sinab ko‘ring. Bu uning diqqatini ham, estetik idrokini ham rivojlantiradi.') WHERE id = '1fa9d3d6-a970-457d-af04-c009e72b5e1b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlarda "Orqaga yurish". Bola endi muvozanatini yo‘qotmasdan orqaga bir necha qadam tashlay oladi. Bu harakat uning o‘z tanasini his qilishi va makonda mo‘ljal olish ko‘nikmasini mustahkamlaydi. U bilan "Qisqichbaqa kabi yuramiz" o‘yinini o‘ynang.') WHERE id = '21db9a7e-7c35-47c7-9f2e-7e03f72a88a3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt tushunchasi: kecha va ertaga". Bola bu so‘zlarni hali aniq vaqtni ifodalash uchun ishlatmasa-da, o‘tgan va kelajakdagi voqealarni farqlashga harakat qiladi. Kun oxirida u bilan "Ertaga qayerga boramiz?" mavzusida suhbatlashing. Bu uning rejalashtirish ko‘nikmasini va voqealar o‘rtasidagi vaqt bog‘liqligini anglashini mustahkamlaydi.') WHERE id = 'a8b25b83-9fde-45e1-b976-1cd3459165f2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: bolaning biror ishi o‘xshamasa (masalan, kublar qulab tushsa), u darhol yig‘lamasdan, yana urinib ko‘rishi mumkin. Bu "kurashuvchanlik ruhi" uning kelajakda muvaffaqiyatli o‘rganishi uchun juda muhim. Unga "Juda ko‘p harakat qilayotganingni ko‘ryapman" deb, natijani emas, sa’y-harakatini maqtang.') WHERE id = '0db561dc-233c-4544-804a-8f5b95ba51b9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "Biz" tushunchasini anglay boshlaydi. "Biz hozir bog‘ga boramizmi?" deb, o‘zini oilaning ajralmas bir qismi sifatida his qiladi. U bilan suhbatlashayotganda oilaviy rejalaringizni aytib turing: "Bugun biz buvingnikiga boramiz". Bu bolada daxldorlik va xavfsizlik hissini kuchaytiradi.') WHERE id = 'cb75068e-4a47-4582-8cce-0e1abcdf18e0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Zinadan erkin chiqish". Bola endi zinadan har bir pog‘onaga bittadan qadam qo‘yib, faqat bir qo‘lidan ushlab turilganda ham ishonch bilan ko‘tarila oladi. Bu uning yirik motorikasi to‘liq rivojlanganini ko‘rsatadi. Siz shunchaki yonida bo‘lib, unga ma’naviy dalda bering.') WHERE id = 'c4f997be-e1af-4807-8fcf-d6afc3087197';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hikoya tuzish". Bola endi rasmlarga qarab oddiy hikoyalar to‘qiydi. "Mushuk keldi, sut ichdi, uxladi" kabi izchil gaplar uning xotirasi va tasavvuri uyg‘unligining natijasidir. Unga qiziqarli rasmlari bor kitoblarni bering va "Bu yerda nima bo‘lyapti?" deb so‘rang. Bu uning ijodiy fikrlashini rag‘batlantiradi.') WHERE id = '8a750939-d6ea-4327-ae01-fe2febf3e561';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Aniq joylashtirish". Bola endi kichik o‘yinchoq shakllarini joylashtirish yoki munchoqlarni ipga tizishni kamroq xato bilan uddalaydi. Bu davrda barmoq uchlarining sezgirligi ortadi. Unga turli tuzilishga ega mayda buyumlar bilan o‘ynashni taklif qiling (albatta, nazorat ostida).') WHERE id = 'b81dacf6-43a1-47b5-b976-b04cc72c15b8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qofiyali so‘zlar va qo‘shiqlar". Bola endi avval eshitgan qo‘shiqlarining oxirgi so‘zlarini qofiyaga mos tarzda aytib tugatishni juda yaxshi ko‘radi. Bu uning fonematik eshitish qobiliyati rivojlanayotganini ko‘rsatadi. U bilan birga she’rlar o‘qing va oxirini o‘zi davom ettirishi uchun to‘xtab turing. Bu uning xotirasini ham, nutq sur’atini ham tartibga soladi.') WHERE id = '6ee138fb-22b9-41f6-a232-d405003097d3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Munchoqlarga ip o‘tkazish". Bola endi teshigi katta munchoqlar yoki makaronlarga ip o‘tkazishni yaxshi uddalaydi. Bu harakat sabrni ham, barmoqlarning nozik muvofiqligini ham talab qiladi. Shu tariqa u kelajakdagi yozish ko‘nikmalari uchun mushak xotirasini shakllantiradi.') WHERE id = 'e27670af-3f91-498b-a727-68765b4a34c6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil gigiyena"dagi rivojlanish. Bola endi qo‘llarini yuvgach, mustaqil ravishda sochiq bilan artinishni va sochiqni joyiga osishni biladi. Bu kichik "yakunlash" harakatlari uning o‘ziga xizmat qilish mas’uliyatini oshiradi. Uning bunday tartibli xatti-harakatini "Qanday ozodasan!" deb maqtang.') WHERE id = '41467e61-a2ce-4e56-9659-81bc3b54b05e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Boshqalarning his-tuyg‘ularini tushunish". Bola endi yuzingizdagi qayg‘u yoki charchoqni ko‘rib, "Nima bo‘ldi?" deb so‘rashi mumkin. Bu empatiyaning eng sof ko‘rinishidir. Unga his-tuyg‘ularingizni sodda qilib tushuntiring: "Biroz charchadim, kel, birga dam olaylik". Bu uning hissiy intellektini rivojlantiradi.') WHERE id = '639f97f3-6003-448b-9622-c5dde4b5cec4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Tartiblash va taqqoslash". Bola endi 3-4 ta o‘yinchog‘ini o‘lchamiga qarab (kichigidan kattasiga) terib chiqa oladi. Bu dastlabki matematik mantiqning asosidir. Unga "Eng katta ayiqchani eng oldinga qo‘y" kabi topshiriqlar bering. Bu vizual tahlil qilishni ham, diqqatni jamlashni ham o‘rgatadi.') WHERE id = '370bff62-25e0-4406-b269-39b56f69516b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlik: "Dinamik muvozanat". Bola endi past tortilgan arqon yoki yerga chizilgan chiziq ustidan "dorboz" kabi yurishga qiziqadi. Bu uning vestibulyar tizimi yetilayotganini ko‘rsatadi. Bog‘da bordyurlar ustidan yurganida qo‘lidan tutib, uning bu jasoratini qo‘llab-quvvatlang.') WHERE id = '7d0f18e8-75ea-46a5-ae28-0011a1c178d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish" qat’iyati. Bola endi tugmasiz ko‘ylagi yoki shimini o‘zi kiyishga astoydil urinadi. "O‘zim!" degan paytlarida unga vaqt bering. Mustaqil bo‘lishga qaratilgan bu urinishlar kelajakdagi o‘ziga ishonch va shaxsiy mas’uliyatning eng mustahkam poydevoridir. Uning kichik yutuqlarini "Qarang, buni o‘zing uddalading!" deb e’tirof eting.') WHERE id = '5b370f66-ddd3-45df-8b72-80322e3b54c6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Odob qoidalari". Bola endi "Iltimos", "Katta rahmat", "Marhamat" kabi so‘zlarni shunchaki takrorlamaydi, balki maqsadli ravishda ishlatadi. Sizning odobli muomalangiz uning uchun eng yaxshi namunadir. Bunday xatti-harakatlarini maqtash orqali uning muloqot madaniyatini mustahkamlang.') WHERE id = 'fb257145-0061-4b1c-8bd6-415874362912';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Payt ravishlari". Bola "keyin", "birozdan so‘ng", "hozir" so‘zlarini o‘z o‘rnida ishlata boshlaydi. "Birozdan keyin kelaman" deganingizda, u vaqt o‘tishini tushunadi. Bu bolada kutish va o‘zini boshqarish ko‘nikmalarini rivojlantiradi. Kundalik odatlaringizda bu so‘zlardan tez-tez foydalaning.') WHERE id = '2d2fd92a-c54e-421a-b575-674a4add6e64';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va nishon". Bola endi to‘pni shunchaki tepibgina qolmay, uni muayyan yo‘nalishga - masalan, ikkita o‘yinchoq orasidan o‘tkazishga harakat qiladi. Bu qo‘l-ko‘z va oyoq-ko‘z muvofiqlashuvining uyg‘un ishlashidir. U bilan uyda "mini futbol" turnirini o‘tkazing.') WHERE id = '4639b4f7-f878-413c-9ed9-f5c72fb301e3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum savollar". Bola "Bulut qayerdan keladi?", "Oy qayerga ketdi?" kabi savollar berishi mumkin. Javob berayotganda tasavvur va haqiqiy ma’lumotlar o‘rtasida muvozanatni saqlang: "Bulutlar uzoqdan kelib, bizga yomg‘ir olib keladi". Bunday suhbatlar uning dunyoqarashi va o‘rganishga bo‘lgan ishtiyoqini nihoyatda kengaytiradi.') WHERE id = 'bc37e242-95d7-44a8-8a20-2eacd0325914';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: Bola endi muvaffaqiyatsizlikka nisbatan bardoshliroq. Kublari qulab tushganda darhol yig‘lamaydi, "Qaytadan quraman" deya oladi. Uning bu qat’iyatini qo‘llab-quvvatlang. 1000 kunga atigi 10 kun qoldi! Siz bu ajoyib yo‘lni farzandingiz bilan qo‘l ushlashib bosib o‘tdingiz. Barakalla sizga!') WHERE id = 'a124273d-b639-4f61-aa7d-a589a92dd962';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashuv: "Mustaqillik cho‘qqisida". Bola endi velosiped haydash, arg‘imchoqda o‘zi uchish yoki baland sirpanchiqlardan sirpanish uchun yetarlicha jasur. Uning xavfsizligini ta’minlang, ammo to‘sqinlik qilmang. O‘z kuchiga ishonishi uning xarakterini mustahkamlaydi.') WHERE id = '27b9a0e5-6b83-4460-8a15-0df9cab1dff0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt teranligi". Bola endi "Men chaqaloq bo‘lganimda..." yoki "Katta bo‘lganimda..." kabi jumlalar tuzib, vaqt oqimidagi o‘z o‘rnini anglay boshlaydi. Unga chaqaloqlikdagi suratlarini ko‘rsating va shu paytgacha qanchalik ulg‘aygani haqida gapirib bering. Bu bolada shaxsiy tarix va o‘zlikni anglashni (self-identity) to‘liq shakllantiradi.') WHERE id = '3439184d-c674-4353-b4d8-24d477730a8a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Katta marraga 1 kun qoldi! Bugun ortga nazar tashlang va o‘zingiz bilan faxrlaning. Farzandingiz miyasi rivojlanishining 80% qismi dastlabki 1000 kun ichida yakunlandi. Siz unga gapirishni, sevishni, ishonishni va dunyoni kashf etishni o‘rgatdingiz. Ertaga farzandingiz hayotida yangi va yorqin sahifa ochiladi. Siz ajoyib ONASIZ!') WHERE id = '6f7bcab0-f835-4b32-baa1-c34bfb4bf5a9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'TABRIKLAYMIZ! Dastlabki 1000 kunni muvaffaqiyatli yakunladingiz! 🌟 Bu inson hayotidagi eng muhim rivojlanish bosqichidir. Bola endi chaqaloqlik davridan chiqib, dunyoni zabt etishga tayyor kichik qahramonga aylandi. Anacan oilasi sifatida har qadamda yoningizda bo‘ldik va bu yutuqni siz bilan baham ko‘ramiz. Bugun katta bayram — farzandingiz va sizning g‘alaba bayramingiz!') WHERE id = 'df76a0b6-eddc-484e-b6f0-24845f214e66';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1000 kunlik katta marafondan keyingi ilk kunimiz! Bola endi hayotining 4-yiliga qadam qo‘ymoqda. Bu davrda "Nega?" degan savollar yangi mazmun kasb etadi. U shunchaki ma’lumotni emas, hodisalar o‘rtasidagi mantiqiy bog‘liqlikni izlaydi. Sabr bilan javob bering, chunki bu savollar uning intellektual poydevorini yaratadi.') WHERE id = '458401f2-485d-418a-8b89-143f552eb250';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Dinamik harakatlar". Bola endi yugurayotganda keskin burila yoki to‘siqlarni tezlik bilan aylanib o‘ta oladi. Bu uning o‘z tanasini boshqarish qobiliyati yuqori darajada ekanini ko‘rsatadi. U uchun hovlida kichik to‘siqlar poygasini tashkil qiling.') WHERE id = '1242feeb-5e2f-4d55-aa93-952aedfbe568';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1000 kunlik ulkan marafonning so‘nggi o‘n kunligiga xush kelibsiz! Bola endi o‘zligini to‘liq anglaydi va «Men katta bo‘ldim» degan tuyg‘u bilan harakat qiladi. U bilan o‘tkazgan 991 kuningizni birma-bir eslang: ilk qadami, ilk so‘zi... Endi u ham jismonan, ham aqlan to‘laqonli shaxsdir. Sizning mehringiz bu binoning eng mustahkam poydevoridir.') WHERE id = 'b5b8d286-f3be-458e-9da0-f739ba54a527';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda «Murakkab harakatlar». Bola endi yugurayotganda birdan to‘xtashi, yo‘nalishini o‘zgartirishi yoki to‘siq ustidan sakrab o‘tishi mumkin. Bu uning asab tizimi va mushaklar koordinatsiyasi yetilganini ko‘rsatadi. U bilan ochiq havoda faol o‘yinlar o‘ynashda davom eting.') WHERE id = '40ef129f-5b1b-4e7a-8bf0-78a6953a2417';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Mantiqiy muloqot». Bola endi siz bilan bahslasha oladi: «Men uxlashni xohlamayman, chunki o‘yinim hali tugamadi». Bu shunchaki qaysarlik emas, balki o‘z fikrini asoslash qobiliyatidir. Unga «To‘g‘ri aytyapsan, ammo birozdan keyin havo qorong‘i bo‘ladi» kabi mantiqiy tushuntirishlar berib, o‘zaro hurmatni singdiring.') WHERE id = 'b9aae384-2df5-41c3-b46c-488d1b02a6ae';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Ijodiy rasmlar». Bola endi shunchaki chiziqlar emas, balki «odam» (odatda doira va chiziqlardan iborat tayoqcha odam), «uy» yoki «quyosh» chizishga urinadi. Bu rasmlar uning ongidagi timsollarning qog‘ozga ko‘chirilishidir. Bu «san’at asarlari»ni albatta saqlab qo‘ying.') WHERE id = '28f47857-a1db-40ef-a9e2-553a55c8a841';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «G‘amxo‘rlik». Bola endi sizning charchaganingizni yoki do‘stlaridan biri yig‘layotganini ko‘rsa, uning yoniga borib, tasalli berishga harakat qiladi. Bu emotsional intellektning (EQ) eng yuksak ko‘rinishidir. Uning bu beg‘ubor qalbi siz bergan mehr-shafqatning aksidir.') WHERE id = 'ad204761-7be7-4b3d-9813-46b7f3ddfbf5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida «Son va ramz sintezi». Bola endi raqam belgilarini (1, 2, 3) ko‘rib taniy oladi va ularni miqdor bilan moslashtira oladi. Unga «Bu yerda 3 ta olma bor, menga ''3'' raqamini ko‘rsat» kabi kichik topshiriqlar bering. Bu maktabgacha tayyorgarlikning eng qiziqarli va muhim bosqichidir.') WHERE id = '277f876e-8768-4106-82f9-f67a9aa287de';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Murakkab zamonlar". Bola endi "men qilgan edim", "men qilaman" kabi murakkab zamon shakllarini nutqida qo‘llay boshlaydi. U bilan o‘tgan voqealarni muhokama qiling: "Kecha buvinikiga borganimizda nima bo‘ldi?". Bu uning xotirasini ham, nutqining grammatik aniqligini ham mustahkamlaydi.') WHERE id = '5e199122-f8a1-4104-82fd-2c91af60c12f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Simmetriyaga urinishlar". Bola qog‘ozni qoq o‘rtasidan buklashga yoki chizgan rasmidagi tafsilotlarni (masalan, odamning ikki ko‘zi va ikki qo‘lini) aniqroq joylashtirishga harakat qiladi. Uning bu vizual e’tiborini "Qara, ikkala qo‘lini ham chizibsan!" deb ta’kidlang.') WHERE id = '9dfe80c5-1c6a-4ec4-852c-1433440d5b52';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Qoidalarning ichki odatga aylanishi". Bola endi siz aytmasangiz ham ayrim qoidalarni eslaydi: "Ovqatdan oldin qo‘llarimni yuvaymi?". Bu tashqi intizomning ichki intizomga aylanishi boshlanganidan dalolat beradi. Uning bunday mustaqil mas’uliyatini albatta maqtang; bu xarakter shakllanishidagi katta qadamdir.') WHERE id = '5760ce33-81a1-4f8c-a7a0-f30c320a688a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Men va do‘stim". Bola endi boshqa bolalar bilan shunchaki yonma-yon emas, balki umumiy ssenariy asosida o‘ynay boshlaydi (masalan, "Sen ona bo‘l, men bola bo‘laman"). Bular ijtimoiy hamkorlik va rollarni taqsimlash borasidagi dastlabki jiddiy tajribalardir.') WHERE id = 'e6c24a0b-d760-47b5-90b8-f6d05b42625b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Tasniflash mahorati". Bola buyumlarni bir vaqtning o‘zida ikkita xususiyatiga ko‘ra guruhlashi mumkin: "ham qizil, ham kichik bo‘lganlari". Unga aralash o‘yinchoqlarni bering va "Barcha kichkina mashinalarni bu yerga yig‘" deng. Bu uning miyasidagi mantiqiy saralash tizimini rivojlantiradi.') WHERE id = '083c5f31-3fe0-44d9-b65b-c4b92bb36ae4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlik: "Uch g‘ildirakli velosipedda mustaqillik". Bola endi rulni boshqarish bilan bir vaqtda pedallarni ham bir maromda aylantira oladi. Bu tananing yuqori va quyi qismlari muvofiqligining mukammal uyg‘unligidir. Bog‘dagi sayrlarni yanada faolroq o‘tkazish vaqti keldi.') WHERE id = 'e81ab935-f108-46cd-a88f-e53e09ed924f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Xayoliy o‘yin sheriklari". Bola endi yolg‘iz o‘ynaganda ham baland ovozda gapiradi, o‘yinchoqlariga turli rollar beradi. Bu "Egotsentrik nutq" bo‘lib, bolaga o‘z harakatlarini so‘zlar yordamida boshqarishga ko‘maklashadi. Uning bunday "monologlarini" tinglab, ichki dunyosida nimalar kechayotganini tushunishingiz mumkin.') WHERE id = '9f4b387f-964e-4bb9-856d-1ac035b357f4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov: Qaror qabul qilish". Bola endi nima yeyishni yoki qaysi o‘yinni o‘ynashni xohlashini aniq biladi. Unga har kuni ikkita variant taklif qiling: "Olma xohlaysizmi yoki banan?". Bu unga o‘z hayotini nazorat qilish hissini beradi va o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = '7022c99f-3026-41d3-8d24-5d2da8ff257d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida "Hajm va miqdorning saqlanishi". Bola hozircha kichik, baland idishdagi suv keng idishdagi suvdan ko‘proq deb o‘ylashi mumkin. Bu "Piaget" bosqichiga mos keladigan tabiiy holat. U bilan suvli o‘yinlar o‘ynab, suvni turli idishlarga quying. Bu tajriba orqali mantiqiy tushunishni tezlashtiradi.') WHERE id = '63894550-7c88-4d80-827d-abe697cce597';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Ikki oyoqda oldinga sakrash". Bola endi to‘siqlardan (masalan, yerdagi arqondan) ikki oyog‘i bilan bir vaqtda sakrab o‘ta oladi. Buning uchun butun tana harakatlarini muvofiqlashtirish va keskin kuch talab etiladi. U uchun xavfsiz joylarda kichik to‘siqlar yo‘lakchasini tashkil qiling.') WHERE id = 'cab49b1b-46a8-46fe-9575-6cef46f13add';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum vaqt tushunchasi". Bola endi "Ertalab", "Tush payti" va "Kechqurun" o‘rtasidagi farqlarni kundalik odatlar orqali anglaydi. "Kechqurun dada kelganda..." desangiz, u kunning shu vaqtini xayolida gavdalantiradi. Kundalik tartibga rioya qilishingiz uning vaqt haqidagi bu tushunchasini xavfsizlik hissi bilan bog‘laydi.') WHERE id = '50a38f0a-e830-42a7-9b23-0d529496ee7f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy yetuklik: "Kechirasiz" so‘zining ma’nosi. Bola endi bilib yoki bilmay kimnidir ranjitganida "Kechirasiz" deyishning ijtimoiy ahamiyatini tushunadi. Unga doimo o‘rnak bo‘ling; xato qilganingizda undan kechirim so‘rang, shunda u ham bunday xatti-harakatni zaiflik emas, balki kuch deb qabul qiladi.') WHERE id = 'f7b6ee04-7015-4382-abaa-03462e452408';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Joy ravishlari». Bola «yonida», «orqasida», «tagida», «ustida» tushunchalarini aniq tushunadi va qo‘llaydi. Agar u «To‘p divanning tagida» desa, demak, uning makonda mo‘ljal olish qobiliyati to‘liq shakllangan. U bilan «Bekinmachoq» o‘ynab, bu tushunchalarni yanada mustahkamlang.') WHERE id = '64ca65c7-1a28-48d4-beca-77b3f217471c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: «Sabr sinovi». Bola endi istagan narsasini olish uchun bir necha daqiqa kutish kerakligini tushunadi va darhol yig‘lay boshlamaydi. Bunday paytlarda unga: «Kutganing uchun katta rahmat, bu ulg‘ayayotganingning belgisidir», deb ayting. Siz ajoyib hamrohsiz!') WHERE id = 'd29729c2-dd1d-4552-9d6e-3a6745ad9680';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglar va shakllarni birlashtirib, atrofdagi dunyoni tasvirlaydi. Agar u «Menga ana u sariq kvadrat shaklidagi kubikni bering» desa, bu uning miyasi bir vaqtning o‘zida bir nechta xususiyatni qayta ishlayotganini ko‘rsatadi. Bu ko‘nikmasini kundalik hayotda kichik topshiriqlar bilan (masalan, «ko‘k paypoqlaringni top») qo‘llab-quvvatlang.') WHERE id = '6e9a3917-235a-4638-821e-7544b6f6fd44';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda «Dinamik muvozanat». Bola endi bir oyog‘ida 5 soniyagacha tura oladi. Bu vestibulyar tizim (muvozanat markazi) va oyoq mushaklari mustahkamlanayotganidan dalolat beradi. U bilan «Laylak» o‘yinini o‘ynab, kim uzoqroq tura olishini sinab ko‘ring.') WHERE id = 'bf8d8f80-94a0-4e9e-beaa-a9027d0e8ae4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Sabab-oqibat bog‘lanishlari». Bola endi «Agar... unda...» shaklidagi gaplarni tushuna boshlaydi. «Agar o‘yinchoqlaringni yig‘ishtirsang, multfilm ko‘rishimiz mumkin» desangiz, u shartni tushunadi. Bu ham mantiqiy fikrlash, ham o‘zini boshqarish (self-discipline) ko‘nikmasi shakllanishi uchun muhim qadamdir.') WHERE id = 'b1f57847-eeec-4119-b2fc-2905b91fb26b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Qaychi bilan ilk tajribalar». Bola endi qog‘ozni (xavfsiz qaychi bilan) to‘g‘ri chiziq bo‘ylab kesishga qiziqish bildira boshlaydi. Bu harakat qo‘l-ko‘z muvofiqligini ham, barmoqlarning mayda motorikasini ham sezilarli darajada rivojlantiradi. Uni nazoratsiz qoldirmang, ammo mustaqil harakat qilishiga to‘sqinlik qilmang.') WHERE id = 'bc3bff7e-368e-485f-8abd-ee144e6a6477';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi rasmlarga qarab oddiy hikoyalar to‘qiydi. "Ayiq o‘rmonga bordi, qorni ochdi va asal yedi" kabi izchil gaplar uning mantiqiy ketma-ketlikni tushunayotganini ko‘rsatadi. Unga qiziqarli rasmlari bor kitoblarni bering va "Sizningcha, bundan keyin nima bo‘ladi?" deb so‘rang. Bu uning ijodiy tasavvurini yanada rivojlantiradi.') WHERE id = '5b5539ed-db72-44da-bf5f-8b147bfb9b43';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlanishda "Zinadan mustaqil tushish". Bola endi zinadan har bir pog‘onaga bittadan qadam qo‘yib, oyoqlarini navbatma-navbat almashtirgan holda va faqat bir qo‘lidan ushlaganda (yoki umuman ushlamasdan) ishonch bilan tushadi. Bu uning yirik motorikasi to‘liq rivojlanganini ko‘rsatadi. Siz shunchaki yonida bo‘lib, unga ma’naviy dalda bering.') WHERE id = 'e1ab27cc-4713-481c-b52f-32935f62d3d2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Savol-javob zanjiri". Bola endi savollaringizga shunchaki "ha/yo‘q" deb emas, to‘liq gaplar bilan javob beradi. "Bugun bog‘da kim bilan o‘ynading?" degan savolga batafsil javob berishi mumkin. U bilan suhbatlashganda "U qanday rangda edi?", "Nima qildingiz?" kabi davom ettiruvchi savollar berib, nutqini rivojlantiring.') WHERE id = '7d186d1a-0812-440c-b07e-ee9ed0da127d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Yanada aniq bo‘yash". Bola endi kichik shakllarning chegaralarini ham his qiladi va bo‘yashda chiziqdan ko‘p chiqmaslikka harakat qiladi. Bu qo‘l mushaklarini boshqarishda katta yutuqdir. Unga turli qalinlikdagi rangli qalamlarni berib, sinab ko‘rishi uchun sharoit yarating.') WHERE id = 'a7b0a891-2fdb-4521-b60b-98a992dcf545';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish: fermuar va tugma". Bola endi yirik tugmalarni yechishni va fermuarni (siz uchini biriktirib berganingizdan so‘ng) yuqoriga tortishni yaxshi uddalaydi. Unga "Qani, o‘zingiz sinab ko‘ring" deb, sabr bilan kuting. Mustaqil kiyina olishi bolada "men buni uddalay olaman" degan tuyg‘u va o‘ziga bo‘lgan ishonchni nihoyatda oshiradi.') WHERE id = '9893a146-5d99-48e6-ae6a-1f46520795f5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Baham ko‘rish mantig‘i". Bola endi boshqa bolaning qo‘lidan o‘yinchoqni darhol tortib olmasdan, "ber" deb kutishga harakat qiladi. Bu o‘zini boshqarish (self-regulation) ko‘nikmasi mustahkamlanayotganini ko‘rsatadi. Uning bunday sabrli xatti-harakatini ko‘rganingizda, albatta, "Navbatingizni kutganingiz uchun katta rahmat" deb maqtang.') WHERE id = '71a96327-cfe2-4ab5-bb79-d332a1ff5de4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Umumiy va xususiy". Bola endi olma, nok va bananning barchasi "meva" ekanini tushunadi. Unga turli xil buyumlarni aralashtirib ko‘rsating va "Bularning barchasini bir so‘z bilan nima deb ataymiz?" deb so‘rang. Toifalar asosida fikrlash uning miyasidagi ma’lumotlarni saqlash tizimini yanada tartibli qiladi.') WHERE id = 'f440da85-66a5-444d-9191-5dceb0b51d20';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni yelka ustidan otish". Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni yelka ustidan oldinga, muayyan nishon tomon ota oladi. Bu butun tana harakatlarini muvofiqlashtirishni talab qiladi. U bilan bog‘da "nishonga otish" o‘yinlarini o‘ynang.') WHERE id = '5a9ea9e5-b06c-4aa9-b965-a6664f7442e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Makon va yo‘nalish". Bola "o‘ng" va "chap" tushunchalarini hali to‘liq farqlay olmasa-da, "oldinga", "orqaga", "yuqoriga" va "pastga" buyruqlarini aniq bajaradi. U bilan "Robot o‘yini"ni o‘ynang: "Ikki qadam oldinga, bir qadam orqaga!". Bu ham qiziqarli, ham makonda yo‘nalishni aniqlash qobiliyatini mustahkamlaydi.') WHERE id = '6ef1e101-45d4-451a-8710-b32b9878cd2e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Muvaffaqiyatsizlikni yengib o‘tish". Bola endi kublari qulab tushganda darhol yig‘lamaydi, balki "Yana qayta quraman" deya oladi. Uning bu qat’iyatini qo‘llab-quvvatlang. 1030 kunni ortda qoldirdik – farzandingiz endi kichkina qahramon!') WHERE id = '1293c75f-beda-4513-88cc-b7951ec10777';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni bir vaqtning o‘zida ikkita xususiyatiga ko‘ra (masalan, ham rangi, ham shakliga qarab) ajrata oladi. Unga "Menga barcha kichkina qizil mashinalarni ber" deganingizda buni bajara olsa, bu uning kognitiv rivojlanishidagi yangi bosqichdir. Kundalik uy ishlarida unga shunday kichik "tanlash" topshiriqlarini bering.') WHERE id = 'fa3d103a-9bc8-44ef-b8d5-cab5337e7b60';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Nishonga sakrash". Bola endi yerga chizilgan doira yoki rangli nishonning markaziga sakrashga harakat qiladi. Bu ham muvozanatni, ham makondagi masofani chamalash qobiliyatini rivojlantiradi. U bilan bog‘da "toshdan toshga sakrash" o‘yinini o‘ynang.') WHERE id = '4bbc0ebb-e4d4-4fb1-9a60-923e8fae76b3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Qarama-qarshi ma’noli so‘zlar doirasining kengayishi». Bola endi «tez-sekin», «qorong‘i-yorug‘», «bo‘sh-to‘la» kabi mavhum qarama-qarshiliklarni tushunadi. Unga bo‘sh va to‘la stakanni ko‘rsatib, farqini so‘rang. Bu uning atrofdagi olamni taqqoslab tahlil qilish qobiliyatini mustahkamlaydi.') WHERE id = 'a89f9de3-ed84-4cfa-95a8-cf4c5d345de7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Pazl ustaligi». Bola endi 10-12 bo‘lakli murakkab pazllarni (rasmning chetlari va markazini ajrata olgan holda) yig‘a oladi. Bu ham ko‘rish xotirasini, ham barmoqlarning nozik harakat qilish qobiliyatini rivojlantiradi. Eplay olmasa, unga xotirjam ohangda maslahatlar bering.') WHERE id = '81c4bfcb-e5df-4929-b621-91e622f18ac6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil tozalash va yordam berish». Bola endi dasturxonni yig‘ishtirishda o‘z likopchasini olib borish, ushoqlarni artish kabi ishlarni katta ishtiyoq bilan bajaradi. Unga bo‘yiga mos tozalash anjomlarini bering. Bu oiladagi mas’uliyat va daxldorlik hissini mustahkamlaydi. O‘z mehnatining natijasini ko‘rish uni juda quvontiradi.') WHERE id = '9ef3f34d-a63f-4f49-9005-c854d4303909';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Qoidalar va chegaralar». Bola endi «yo‘q» so‘zining ortidagi mantiqni biroz yaxshiroq tushunadi, ammo baribir chegaralarni sinab ko‘rishni yoqtiradi. Sizning sabrli va izchil bo‘lishingiz unga xavfsizlik hissini beradi. Qoidalarni doimo bir xil tarzda qo‘llashga harakat qiling.') WHERE id = 'c4d24c3e-4601-4235-8cdc-f39b3aa35149';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida «Tartib sonlar». Bola endi «birinchi», «ikkinchi», «oxirgi» tushunchalarini anglaydi. Mashinalarni ketma-ket terib, «Qaysi mashina birinchi?» deb so‘rang. Bu uning ketma-ketlikni tushunishi va matematik tafakkurini rivojlantiradi. Musobaqalarda «Birinchi bo‘lib siz keldingiz!» deyish unga katta motivatsiya beradi.') WHERE id = 'b0d3eed0-e639-4528-9c81-8601b70e54bd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Orqaga va yonlama yurish». Bola endi turli yo‘nalishlarda chaqqon harakatlana oladi. U bilan «Ko‘zgu o‘yini»ni o‘ynang: siz yon tomonga qadam tashlang, u ham harakatingizni takrorlasin. Bu ham maroqli, ham tana harakatlarini muvofiqlashtirish qobiliyatini yangi bosqichga olib chiqadi.') WHERE id = 'da0e2216-17ef-49f2-83ad-1599f6a6e332';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum savollarning chuqurlashuvi". Bola "Bulutlar qayerga ketadi?", "Nega yulduzlar kechasi chiqadi?" kabi savollar bilan sizni hayratda qoldirishi mumkin. Javob berayotganda uning tasavvurini ham ishga soling: "Seningcha, yulduzlar hozir nima qilyapti?". Bu uning ijodiy fikrlashini rivojlantiradi.') WHERE id = '1f153d5c-5da7-4c69-b731-2dc34e06cb4f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "Baham ko‘rish quvonchi". Bola endi o‘yinchog‘i yoki shirinligini o‘z xohishi bilan baham ko‘rganida sizning quvonchingizni sezadi va buni yana takrorlashni istaydi. Uning bu saxiyligini "Do‘stingni xursand qilganing uchun katta rahmat" deb alohida ta’kidlang. 1040 kunni muvaffaqiyatli yakunladik — siz ajoyib onasiz!') WHERE id = '3c9e08eb-1969-4283-90ec-97d2de26fd19';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '35-oyga qadam qo‘yyapmiz! Bola endi "ikki bosqichli" fikrlashdan "uch bosqichli" topshiriqlarga o‘tadi. "O‘yinchoqni ol, qutiga sol va qopqog‘ini yop" deganingizda bularni ketma-ketlikni buzmasdan bajarsa, bu uning ishchi xotirasi (working memory) uchun katta yutuqdir. Kun davomida unga kichik, mantiqan bog‘langan zanjirli topshiriqlar berib, bu ko‘nikmasini rivojlantiring.') WHERE id = 'b4ed41fc-fc60-439e-82df-81e0242123d3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Tez yugurish va manyovr qilish". Bola endi yugurayotganda oldidagi to‘siqni ko‘rsa, tezligini kamaytirmasdan uni aylanib o‘ta oladi. Bu uning o‘z tanasini his qilish qobiliyati (propriosepsiya) to‘liq shakllanganini ko‘rsatadi. Parkda "to‘siqlar osha yugurish" musobaqalarini o‘tkazib, uning energiyasini foydali tomonga yo‘naltiring.') WHERE id = '140764ec-2a00-4bc6-b514-5e093357430f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qiyoslash darajalari". Bola endi "kattaroq", "eng kichik", "juda mazali" kabi iboralarni o‘rinli ishlatadi. Buyumlarni taqqoslab, u bilan suhbatlashing: "Bu olma shirinroqmi yoki unisimi?". Sifat darajalarini o‘zlashtirish uning tasviriy nutqini boyitadi va fikrlarini aniqroq ifodalashiga yordam beradi.') WHERE id = '5868f762-ea68-431f-855d-54c5a04efe50';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Haykaltaroshlik". Bola endi plastilin yoki kinetik qum bilan o‘ynaganda ularni shunchaki siqmaydi, balki ulardan "koptok", "ilon" yoki "non" kabi tanish shakllar yasaydi. Bu ham ijodiy tafakkurni rivojlantirish, ham barmoq uchlaridagi mayda mushaklarni mustahkamlash uchun ajoyib mashqdir.') WHERE id = '060a9ae6-7e66-446f-800a-a74eb2d502d9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "avval" va "keyin" ketma-ketligini yanada chuqurroq tushunadi. "Kiyimingni kiy, keyin tashqariga chiqamiz" deganingizda, u ikkinchi harakat mukofot ekanini anglaydi. Bu bolada sabr-toqat va rejalashtirish ko‘nikmalarining ilk kurtaklaridir. Kundalik odatlar davomida unga bu ketma-ketliklarni tez-tez eslatib turing.') WHERE id = '2add65f7-d33c-4b48-a1e7-f388a5549421';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Tirmashib chiqish mahorati". Bola endi bog‘dagi narvonlarga yoki uydagi xavfsiz balandliklarga yanada ishonch bilan chiqadi. Bunda qo‘l va oyoq mushaklari bir vaqtda muvofiq ishlaydi. Doimo uning yonida bo‘ling, ammo o‘z kuchini sinab ko‘rishiga imkon bering.') WHERE id = '25d5eedf-59a2-4e4e-8131-39a811d36fe6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mantiqiy bog‘lanishlar". Bola endi ikkita hodisani bitta gapda bog‘laydi: "Havo sovuq, kurtkangni kiy". Bu uning shunchaki taqlid qilmayotganini, balki fikrlayotganini ham ko‘rsatadi. O‘z fikrlarini yanada ishtiyoq bilan ifodalashi uchun uning bunday mantiqiy mulohazalarini "Ha, to‘g‘ri aytyapsan" deb tasdiqlang.') WHERE id = '90469c76-8fc0-41db-a7e9-3862f12f4d6b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qog‘oz bilan ishlash". Bola endi qog‘ozni buklashga yoki oddiy shaklda kesishga (bolalar uchun mo‘ljallangan katta qaychi bilan, nazorat ostida) qiziqish bildirishi mumkin. Bu harakatlar barmoq mushaklarini boshqarish qobiliyatini yangi bosqichga olib chiqadi. Unga rangli qog‘ozlar bilan ishlashi uchun sharoit yarating.') WHERE id = '8f149cc4-a06e-4928-a8cb-2b953480c3af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Rolli o‘yinlarning murakkablashuvi". Bola endi "shifokor", "oshpaz" yoki "haydovchi" roliga kiradi. Bu o‘yinlar orqali u atrofidagi odamlarning vazifalarini o‘rganadi va hamdardlik tuyg‘usini rivojlantiradi. Uning bu o‘yinlariga qo‘shiling va sizga bergan "roliga" mos harakat qiling.') WHERE id = 'c9bd395e-c3c2-46e2-abf3-1f924d619000';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tozalik" odati. Bola endi qo‘llarini yuvayotganda sovunlab, chayishni deyarli mustaqil bajara oladi. Bu yoshda gigiyena odatlarining mustahkamlanishi juda muhim. Bu jarayondan zavq olishi uchun unga bo‘yiga mos oyoqosti kursichasini (step stool) taqdim eting.') WHERE id = 'dd1b7d3a-2552-45df-81c5-cf8e1914b882';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish: Kiyimning o‘ngi va teskarisi". Bola endi ko‘ylak yoki shimning o‘ngi va teskarisini, oyoq kiyimning o‘ng va chap poyini (ba’zan adashsa ham) ajratishga harakat qiladi. Unga kichik maslahatlar bering: "Qara, rasmli tomoni oldinda bo‘ladi". Bu uning diqqatini tafsilotlarga jamlashiga va o‘ziga xizmat ko‘rsatish ko‘nikmalarini rivojlantirishiga yordam beradi.') WHERE id = 'a1a89564-b6bb-483a-bd10-bb44b24484a4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Jamoaviy ruh". Bola endi boshqa bolalar bilan birgalikda umumiy maqsad yo‘lida (masalan, katta qal’a qurish uchun) o‘ynay oladi. Bu "Parallel o‘yin"dan "Hamkorlikdagi o‘yin"ga o‘tishdir. Uning boshqa bolalar bilan qanday til topishayotganini kuzating va murakkab vaziyatlarda ijtimoiy "ko‘prik" qurishiga yordam bering.') WHERE id = '999ddf88-03eb-4dd0-856d-79ce3e7385df';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Raqam va miqdor muvofiqligi". Bola 1-dan 5-gacha sanashni biladi, endi esa "3" raqamini ko‘rganida 3 ta o‘yinchoqni ajratib qo‘ya oladi. Bu matematik tafakkur rivojlanishining eng muhim bosqichlaridan biridir. Kundalik hayotda "Menga 2 ta qoshiq ber" kabi topshiriqlar orqali bu bog‘liqlikni mustahkamlang.') WHERE id = '8193ed91-5f04-4955-a4b1-522d5a941870';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Yuqoridan otilgan to‘pni tutish". Bola endi o‘ziga tomon sekin otilgan katta to‘pni ikki qo‘li bilan tutishga harakat qiladi. Bu harakat ham qo‘l-ko‘z muvofiqligini, ham tezkor reaksiya qilishni talab etadi. U bilan yaqin masofadan "to‘pni tut" o‘yinini o‘ynang.') WHERE id = '575cf871-23de-446e-8398-4dd4c0ff6773';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum savollar cho‘qqisi". Bola endi "Nega shamol esadi?", "Quyosh qayerga uxlashga ketadi?" kabi borliq va tabiat hodisalari haqida savollar beradi. Javob berayotganda tasavvur kuchini ham ishga soling: "Quyosh charchadi, ertaga bizni yana uyg‘otish uchun dam olishga ketyapti". Bu uning dunyoqarashi va o‘rganishga bo‘lgan ishtiyoqini oshiradi.') WHERE id = 'fdfb7732-94cf-4e6c-8519-4e6877b4ad89';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy yetuklik: "Boshqalarning his-tuyg‘ularini tan olish". Bola endi sizning charchaganingizni yoki boshqa bir bolaning xafa bo‘lganini ko‘rganida "Nima bo‘ldi?" deb so‘raydi va tasalli berishga harakat qiladi. Bu uning mehr-shafqatli inson bo‘lib shakllanayotganini ko‘rsatadi. Siz ajoyib onasiz!') WHERE id = '9721a15c-607b-4236-9999-231bdd0b4e99';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Farqlisini topish". Bola endi bir guruh buyumlar orasidan farq qiladiganini (masalan, mashinalar orasidagi olmani) ko‘rib ajrata oladi. Bu uning tahlil qilish qobiliyatini charxlaydi. Uyda u bilan oddiy "Qaysi biri ortiqcha?" o‘yinlarini o‘ynang. Bu kelajakdagi matematik va mantiqiy topshiriqlar uchun ajoyib tayyorgarlikdir.') WHERE id = 'f8163db2-8f81-44fa-bc05-1057d8b42f15';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Bir oyoqda turishga urinishlar". Bola endi bir necha soniyaga bo‘lsa ham, bir oyog‘ini yerdan ko‘tarib, muvozanatni saqlashga harakat qiladi. Bu tanasining og‘irlik markazini his qilishi uchun muhimdir. U bilan "Laylak o‘yini"ni o‘ynang va kim uzoqroq tura olishini sinab ko‘ring.') WHERE id = '0dbea1ae-3808-4d99-b129-68ed1447a173';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "His-tuyg‘ularni ifodalash". Bola endi xafa, xursand yoki qo‘rqib ketganini so‘z bilan ayta oladi: "Men qo‘rqib ketdim" yoki "Men xursandman". His-tuyg‘ularni nomlash boladagi emotsional intellektning asosidir. U his-tuyg‘ularini aytganda, uni tinglang va "Ha, sizni tushunaman" deb, hislarini tan oling.') WHERE id = '384f5938-24c1-4dc2-8691-403780565471';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvur kuchi: "Ramziy tafakkur". Bola tayoqni "ot" deb tasavvur qilib, uni minib chopgandek yurishi mumkin. Bu bir buyum boshqa narsani ifodalashini tushunish qobiliyatidir. Bu ko‘nikma kelajakda o‘qish va matematika (ramzlarni tushunish) uchun juda muhimdir. Siz ajoyib yo‘l-yo‘riq ko‘rsatuvchisiz!') WHERE id = '94697180-1105-4fe0-9d68-ffdaab53705e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "men", "siz" va "biz" olmoshlarini o‘z o‘rnida to‘g‘ri ishlatadi. "Biz hozir ovqatlanyapmizmi?" deb, o‘zini oilaning faol a’zosi sifatida his qiladi. U bilan suhbatlashayotganda, uni ham rejalaringizga qo‘shing: "Kel, dasturxonni birga yozamiz". Bu uning daxldorlik va mas’uliyat hissini kuchaytiradi.') WHERE id = '38010093-f42b-4818-a3db-81219f590eee';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Zinadan mustaqil chiqish". Bola endi zinadan har bir pog‘onaga bittadan qadam qo‘yib, oyoqlarini navbatma-navbat almashtirgan holda va faqat bir qo‘lidan ushlaganda ishonch bilan ko‘tariladi. Bu uning yirik motorikasi to‘liq shakllanganini ko‘rsatadi. Siz shunchaki yonida bo‘lib, unga ma’naviy dalda bering.') WHERE id = '8503d4e9-2c78-4879-9d8c-ef7c6d2a467c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi «Mavhum savollar». Bola «Bulut qayerdan keladi?», «Oy qayerga ketdi?» kabi savollar berishi mumkin. Javob berayotganda xayoliy va haqiqiy ma’lumotlarni uyg‘unlashtiring: «Bulutlar uzoqdan kelib, bizga yomg‘ir olib keladi». Bunday suhbatlar uning dunyoqarashi va o‘rganishga bo‘lgan qiziqishini nihoyatda kengaytiradi.') WHERE id = 'fe4cb6a5-1e61-4aaa-9066-7165c1ab72dd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: bola endi muvaffaqiyatsizlikka nisbatan bardoshliroq. Kublari qulab tushganda darrov yig‘lamaydi, «Yana qaytadan quraman», deya oladi. Uning bu qat’iyatini qo‘llab-quvvatlang. 1070 kunni ortda qoldirdik, 3 yoshga to‘lishiga juda oz qoldi! Siz bu yo‘lda ham ustoz, ham eng yaqin do‘stsiz!') WHERE id = '39f0d5e2-0187-4785-9bb9-453ef9250d3e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi o‘zini boshqa bolalar bilan taqqoslay boshlaydi: «Men undan tezroq yuguraman». Bu raqobat hissi emas, balki o‘z imkoniyatlarini anglash shaklidir. Unga har kimning qobiliyati turlicha ekanini sodda tilda tushuntiring. Bu unda o‘zini hurmat qilishni ham, boshqalarga nisbatan bag‘rikenglikni ham shakllantiradi.') WHERE id = 'b9b4b281-d07d-4b24-8be3-a13d61d2de12';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikdagi «Tez to‘xtash». Bola yugurayotganda sizning «To‘xta!» degan buyrug‘ingiz bilan darhol to‘xtay oladi. Bu uning mushaklarini jismonan boshqara olishini ham, miyadagi impulslarni nazorat qilish (inhibitory control) qobiliyatini ham ko‘rsatadi. Bog‘da «Qizil chiroq, yashil chiroq» o‘yinini o‘ynash uchun ayni vaqt.') WHERE id = '36d86d2b-43c1-4460-afbb-45a783701a53';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi «Murakkab dialoglar». Bola endi sizga biror voqeani ketma-ketlikda aytib bera oladi. «Avval bog‘ga bordik, keyin muzqaymoq yedik, so‘ng mushukni ko‘rdik». Uning bunday hikoya tuzish qobiliyati xotira va nutq uyg‘unligining natijasidir. «Keyin nima bo‘ldi?» deb, uni hikoyani davom ettirishga undang.') WHERE id = '62cbc2dc-4d91-48c4-8b87-f71ac5555a0a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikadagi «Geometrik shakllarni ko‘chirish». Bola endi siz chizgan doira yoki xoch shaklini takrorlay oladi. Bu uning ko‘zi bilan ko‘rgan shaklni qo‘li bilan takrorlash (vizual-motor integratsiya) qobiliyati rivojlanayotganini ko‘rsatadi. Unga turli rangli qalamlar bilan shakllar chizishni o‘rgating.') WHERE id = 'c219d541-0794-4388-b19c-1b3296bc6f1a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hikoya tuzish". Bola endi rasmlarga qarab oddiy hikoyalar o‘ylab topadi. "Mushuk keldi, sut ichdi, uxladi" kabi izchil gaplar uning xotirasi va tasavvuri uyg‘unligidan dalolat beradi. Unga qiziqarli rasmlari bor kitoblarni bering va "Bu yerda nima bo‘lyapti?" deb so‘rang. Bu uning ijodiy fikrlashini rivojlantiradi.') WHERE id = 'ebe63eb5-d3b9-410d-8ddc-267b97751075';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Aniq joylashtirish". Bola endi kichik o‘yinchoq shakllarini joylashtirish yoki munchoqlarni ipga tizishni kamroq xato bilan bajara oladi. Bu davrda barmoq uchlarining sezgirligi ortadi. Unga turli tuzilishga ega kichik buyumlar bilan o‘ynashni taklif qiling (nazorat ostida).') WHERE id = '9acc3fd3-37ec-4b80-9709-ac31444a2801';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish" istagi. Bola endi tugmasiz ko‘ylagi yoki shimini o‘zi kiyishga qat’iy turib oladi. "O‘zim!" degan paytlarida unga vaqt bering. Mustaqil bo‘lishga qaratilgan bu urinishlar kelajakdagi o‘ziga ishonch va shaxsiy mas’uliyatning eng mustahkam poydevoridir. Uning kichik yutuqlarini "Qarang, o‘zing uddalading!" deb e’tirof eting.') WHERE id = '48d41fa6-6f48-4a84-a2b6-f82cae4ce209';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Odob qoidalari". Bola endi "Iltimos", "Rahmat", "Marhamat" kabi so‘zlarni shunchaki takrorlamaydi, balki maqsadli ravishda ishlatadi. Sizning xushmuomala munosabatingiz uning uchun eng yaxshi namunadir. Bolaning bunday xatti-harakatlarini maqtash orqali uning muloqot madaniyatini mustahkamlang.') WHERE id = 'fe3ec85d-8b47-408d-a0ad-870b3b58db94';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Payt ravishlari". Bola "keyin", "birozdan so‘ng", "hozir" so‘zlarini o‘z o‘rnida ishlata boshlaydi. "Birozdan so‘ng kelaman" deganingizda, u vaqt o‘tishini tushunadi. Bu bolaning kutish va o‘zini boshqarish qobiliyatini rivojlantiradi. Kundalik odatlaringizda bu so‘zlardan tez-tez foydalaning.') WHERE id = 'df8b2f32-9f00-4805-8e4c-c754c399be31';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘p tepish va nishon". Bola endi to‘pni shunchaki tepib yubormaydi, balki uni muayyan yo‘nalishga — masalan, ikkita o‘yinchoq orasidan o‘tkazishga harakat qiladi. Bu qo‘l-ko‘z va oyoq-ko‘z muvofiqlashuvining bir vaqtda ishlashidir. U bilan uyda "mini futbol" turnirini o‘tkazing.') WHERE id = '852439ac-fd00-4ba1-aa13-d519b9407d5f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi o‘zini shunchaki "men" deb emas, balki muayyan qobiliyat egasi sifatida ko‘radi. U "Men tez yuguraman" yoki "Men rasm chizaman" kabi ta’riflardan foydalanadi. Uning o‘zi haqidagi bu ijobiy tasavvurini qo‘llab-quvvatlang. O‘zini qanday ta’riflashiga e’tibor bering — bu uning kelajakdagi o‘ziga ishonchining ovozidir.') WHERE id = '24b05457-5c55-4e7e-93bd-e8e2e24e7b8c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy jasoratda "Balandlik qo‘rquvini yengish". Bola endi bog‘dagi balandroq sirpanchiqlar yoki narvonlarni sinab ko‘rishni istaydi. Uning jismoniy imkoniyatlari ongidagi "men buni uddalay olaman" degan fikr bilan to‘liq uyg‘unlashadi. Siz esa shunchaki "ko‘rinmas himoya" sifatida yonida turing.') WHERE id = 'a48cb007-600a-438e-b8fd-ac64a32480ba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Nega?" savolining falsafasi. Endi u "nega" deb faqat javob olish uchun emas, siz bilan suhbatni davom ettirish uchun ham so‘raydi. Javobingiz tugagach, u yana "nega?" desa, savolni o‘ziga qaytaring: "Sizningcha-chi?". Uning xayoliy izohlari sizni ham kuldiradi, ham hayratga soladi.') WHERE id = 'a7f2070c-4631-4744-b176-d7bba5b19ea6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Ramzlarning tug‘ilishi". Bola endi qog‘ozga "yopiq shakllar" chizadi. U chizgan bitta doira ham quyosh, ham to‘p, ham ona bo‘lishi mumkin. Bu mavhum tafakkurning yuksak ko‘rinishidir: bitta ramz hamma narsani ifodalashi mumkin. Uning bu ilk "san’at asarlarini" sanasini yozib, albatta saqlab qo‘ying.') WHERE id = '8291f627-bff8-4ae0-9fda-966d1f2e80ac';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Chegaralarni sinovchi". Bola siz qilma degan ishni ataylab bajarib, munosabatingizni kuzatishi mumkin. Bu uning "yomon" ekanini anglatmaydi — u sizning hissiy chegaralaringizni va qoidalar o‘zgarmasligini sinab ko‘rmoqda. Xotirjam va qat’iy bo‘lishingiz unga eng muhim xavfsizlik xabarini beradi: "Dunyo hamon barqaror va xavfsiz".') WHERE id = 'a9bf7bd3-b390-48c2-b220-67d40659de03';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy zakovatda "O‘yin qoidalari". Bola endi o‘yin davom etishi uchun qoidalarga rioya qilish kerakligini tushunadi. Masalan, bekinmachoq o‘ynaganda ko‘zlarini yumish muhimligini biladi. Bular uning jamiyatdagi ilk "ijtimoiy kelishuvlari"dir. U bilan sodda qoidalarga ega stol o‘yinlarini o‘ynashni boshlang.') WHERE id = '6de77e4c-02d9-4646-a638-e1f9881237a4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil qarorlar". Bola endi qaysi o‘yinchoq bilan o‘ynashini yoki qaysi kitobni o‘qishini qat’iy tanlaydi. Unga bu tanlovlarni amalga oshirish imkonini bering. O‘z tanlovi hurmat qilinayotganini ko‘rish bolaning o‘ziga bo‘lgan ishonchini oshiradi va uning ichki dunyosi boyishiga yordam beradi.') WHERE id = '064446a8-f711-4f01-89fb-101964123929';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Navbat kutish". Bola endi hamma bir vaqtda arg‘imchoqda ucha olmasligini tushunadi. Uning "Hozir u uchyapti, keyin men" deya olishi ijtimoiy intellekt rivojidagi katta qadamdir. Bu xatti-harakat odatga aylanishi uchun uning sabrini albatta maqtang.') WHERE id = '9280edaf-2356-4dce-a273-2cd4a5d6fd57';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Tartiblash va toifalash". Bola endi buyumlarni nafaqat rangiga, balki vazifasiga ko‘ra ham guruhlaydi: "Bular oziq-ovqatlar, bular esa o‘yinchoqlar". Unga aralash buyumlarni bering va "Oshxonaga tegishli buyumlarni top" deng. Bu uning miyasidagi ma’lumotlarni tizimlashtirishga yordam beradi.') WHERE id = '55b33de4-6e1b-4815-985d-641594c12f05';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni yelka ustidan otish". Bola endi to‘pni faqat pastdan emas, balki yelka balandligidan oldinga ham ota oladi. Bu qo‘l va yelka mushaklari kuchayganini hamda u harakat trayektoriyasini rejalashtira olishini ko‘rsatadi. U bilan bog‘da kichik "nishonga otish" o‘yinlarini o‘ynang.') WHERE id = 'eb04363a-ab4d-4a94-888d-e7e2e5211e9c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Olmoshlarni to‘g‘ri qo‘llash". Bola endi "men", "sen", "u", "biz" olmoshlarini deyarli hech qachon adashtirmaydi. Bu uning ijtimoiy muhitdagi o‘z o‘rnini va boshqalar bilan munosabatlarini to‘liq anglayotganini bildiradi. U bilan suhbatlashayotganda murakkab gaplarni ishlatishdan tortinmang.') WHERE id = '4705908e-12af-4329-ab11-ab69b76d1be9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Xatolardan o‘rganish". Bola biror ishni uddalay olmasa, darhol yig‘lamaydi, sizga qarab "Bo‘lmadi, yana bir bor urinib ko‘raymi?" deb so‘rashi mumkin. Bu uning hissiy bardoshliligi ortayotganini ko‘rsatadi. Unga "Hamma xato qilishi mumkin, eng muhimi — yana bir bor urinib ko‘rish" deb dalda bering. Siz ajoyib yo‘l-yo‘riq ko‘rsatuvchisiz!') WHERE id = 'cb464c9f-f6c4-48c0-ab1a-62c435d01c32';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrokdagi "Vaqt marosimlari". Bola "kecha", "bugun" va "ertaga" tushunchalarini hali to‘liq anglamasa-da, kundalik odatlarni biladi. "Ovqatdan keyin parkka borish" yoki "Uyqudan oldin ertak". Bu ketma-ketliklar uning ongida vaqt chizig‘ini shakllantiradi. Voqealarni unga izchil tartibda aytib berish orqali yordam bering.') WHERE id = '3677e8d8-da75-4da9-b002-0343f54de7f8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirishdagi "Nozik harakatlar". Bola endi suyuqlik to‘ldirilgan stakanni deyarli to‘kmasdan olib bora yoki tor so‘qmoq bo‘ylab yura oladi. Bu uning ko‘rish va harakat muvofiqligi qanchalik takomillashganini ko‘rsatadi. Unga uyda "kichik ofitsiant" vazifalarini bering.') WHERE id = '24b745fb-d8d2-4191-b523-51bef737292f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "Tuyg‘ular lug‘ati". Bola endi shunchaki "yomonman" yoki "yaxshiman" demaydi. "Jahlim chiqdi", "zerikdim", "xursandman" kabi so‘zlarni o‘rnida ishlatadi. Uning his-tuyg‘ularini tan oling va tasdiqlang: "Zerikkaning uchun yig‘lashing tabiiy". Bu uning hissiy salomatligining eng katta kafolatidir.') WHERE id = 'e9c2314b-a8e3-4e87-93f6-fa6cd95e6e36';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '3 yosh (1095 kun) ostonasida. Bola endi "go‘daklik" sohilidan uzoqlashib, "bolalik" ummoniga chiqmoqda. U endi nafaqat sizning harakatlaringizni, balki hissiy holatingizni ham takrorlaydi. Siz uning uchun eng katta ko‘zgusiz. O‘zingiz bilan faxrlaning, 1090 kundan beri ajoyib bir insonni voyaga yetkazyapsiz!') WHERE id = '6d3a16a2-1643-4f5c-be11-40251b29e16d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '3 yoshga to‘lishiga (1095 kun) atigi 5 kun qoldi! Bola endi "Men" tushunchasini to‘liq o‘zlashtirgan va o‘z chegaralarini qat’iyat bilan himoya qilmoqda. Shu kunlarda duch kelayotgan "yo‘q"lar uning sizga qarshi ekanini emas, balki o‘z shaxsiyatini tasdiqlayotganini anglatadi. Unga tanlash imkoniyatini berib, bu o‘tish davrini yengillashtiring.') WHERE id = '1dacdad0-c90b-4399-810b-283d367d437c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishdagi "To‘liq mustaqillik". Bola endi ikki oyog‘i bilan bir vaqtda yuqoriga sakray, zinadan yordamsiz tushib-chiqa va uch g‘ildirakli velosipedni boshqara oladi. Uning jismoniy quvvati endi muvofiqlashtirilgan harakatlarga aylangan.') WHERE id = '0788e284-3cae-46fe-a730-5b0adb5d2052';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Mavhum tafakkur». Bola endi yonida bo‘lmagan buyumlar yoki o‘tmishda sodir bo‘lgan voqealar haqida uzoq gapira oladi. «Eslaysizmi, biz u yerga borgandik?» kabi jumlalar uning uzoq muddatli xotirasi va nutq qobiliyati mukammal uyg‘unlashganini ko‘rsatadi. U bilan eski xotiralarni tez-tez yodga oling.') WHERE id = 'f3f07ee7-1804-4733-8e04-f58c824d1ef9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Yozishga tayyorgarlik ko‘nikmalari». Bola endi qalamni kafti bilan emas, barmoqlari bilan ushlaydi hamda yopiq doiralar, xochlar va hatto ayrim harflarga o‘xshash chiziqlar chizadi. Bu uning kelajakdagi yozish ko‘nikmalari uchun eng muhim jismoniy bosqichdir.') WHERE id = '1e35d34e-147e-430a-a51b-7c615ecdd852';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'TUG‘ILGAN KUNING MUBORAK! Naq 3 yil, ya’ni 1095 kun! Bola endi rasman «go‘daklik» qirg‘og‘ini tark etdi. U hozir gapiradigan, fikrlaydigan, hazillashadigan va o‘z dunyosiga ega kichkina inson. Ushbu 1095 kun davomida siz uning qalbida mustahkam ishonch va mehr poydevorini yaratdingiz. Barakalla sizga, Ona!') WHERE id = '94af9664-3a01-40cf-b485-6d92b46dd312';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '4-yoshning ilk kuni! Bolada «Mas’uliyat» hissi uyg‘onmoqda. Endi u o‘yinchoqlarini yig‘ishtirish ham o‘yinning bir qismi ekanini tushuna oladi. Unga kichik uy yumushlarini topshiring (masalan, dasturxonga salfetka qo‘yish). Bu unda oilaning foydali bir a’zosi ekanligi haqidagi tuyg‘uni mustahkamlaydi.') WHERE id = '8a58846e-740c-494e-b055-cca0e1dee700';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Empatiyaning rivojlanishi». Bola endi nafaqat o‘z hislarini, balki boshqalar ham xafa bo‘lishi mumkinligini tushunadi. «U bola nega yig‘layapti?» degan savol uning dunyoni boshqalarning nigohi bilan ko‘ra boshlaganidan dalolat beradi.') WHERE id = '3be5dfbf-e6fa-4586-9735-23266743fb18';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrokda «Mantiqiy ketma-ketlik». Bola endi 3-4 qismdan iborat voqealarni to‘g‘ri ketma-ketlikda joylashtira oladi: «Avval qo‘limni yuvdim, keyin non yedim, so‘ng o‘ynadim». Unga kuningizni birgalikda rejalashtirishni taklif qiling. Bu uning ongidagi «tartibsizlik»ni izchil «vaqt chizig‘i»ga aylantiradi.') WHERE id = 'cce49adb-3f97-4be9-9435-40b81895ee05';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Tasavvurdagi "Murakkab rolli o‘yinlar". Endi o‘yinlar yanada batafsil tus oladi. U shunchaki "shifokor" bo‘lib qolmay, sizga "retsept yozadi", "ukol qiladi". Bunday o‘yinlar bolaning stressni yengish va jamiyatni anglash usulidir. Uning o‘yin dunyosiga hurmat bilan qo‘shiling.') WHERE id = '63c35556-85c7-4de4-956c-b06072fe14e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1100 kunlik yo‘lning so‘nggi bekati. Bola endi o‘zini "katta" deb his qiladi. Uning o‘ziga xosligi, didi va xarakteri allaqachon to‘liq shakllangan. Siz bu yo‘lni sabr, bilim va eng muhimi, cheksiz mehr bilan bosib o‘tdingiz. "Anacan" ilovasi doimo siz va jajji qahramoningiz yonida!') WHERE id = 'b3b1d154-d59c-44d1-8bf7-a6ef75357962';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '3 yoshning dastlabki o‘n kunligiga xush kelibsiz! Bu davrda bolaning lug‘at boyligi 1000 ga yaqin so‘zdan iborat bo‘ladi. Endi u nafaqat ehtiyojlari, balki orzularini ham siz bilan bo‘lishadi. U bilan suhbatlashayotganda "Sizningcha, nega?" degan savolni tez-tez berib, mantiqiy fikr yuritishini rag‘batlantiring.') WHERE id = 'a79f70f3-f350-4b22-984a-7f58dfd4b7fb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Aniq sakrash". Bola endi turgan joyidan ham yuqoriga, ham muayyan nishon tomon (masalan, yerdagi rangli gilamcha ustiga) sakray oladi. Bu uning muvozanatni saqlash hamda fazodagi masofani hisoblay olish qobiliyatini ko‘rsatadi. Bog‘da "toshdan toshga sakrash" o‘yini uning uchun ajoyib mashqdir.') WHERE id = '05ceca15-09f0-41f4-a54b-99db2b828cc8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Olmosh va jins kategoriyalari". Bola endi "men", "sen", "u" olmoshlarini to‘g‘ri ishlatadi. Agar u hali ham ba’zan o‘zini ismi bilan uchinchi shaxsda atasa (masalan, "Ali suv xohlaydi"), uni muloyimlik bilan to‘g‘rilang: "Ha, SEN suv xohlaysan".') WHERE id = '03d396dd-e487-41b7-9885-73235271ea53';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nozik motorikada "Pazl va konstruksiya". Bola endi 8-12 qismli pazllarni mustaqil yig‘adi hamda kubiklardan murakkab minoralar va ko‘priklar quradi. Bu vizual tahlil qilishni ham, barmoqlarning nozik harakat qobiliyatini ham rivojlantiradi. U uddalay olmasa, tayyor yechimni berib qo‘ymang, shunchaki yo‘l-yo‘riq ko‘rsating.') WHERE id = 'ca591a5d-4734-459d-be9b-3eaadeddb81b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish: fermuar va tugma". Bola endi katta tugmalarni yechishga yoki fermuarni ulab berganingizdan so‘ng uni yuqoriga tortishga juda qiziqadi. Unga "Qani, o‘zing urinib ko‘r" deb, sabr bilan kuting. Mustaqil kiyina olishi bolada "men uddalay olaman" degan tuyg‘u va o‘ziga bo‘lgan ishonchni nihoyatda oshiradi.') WHERE id = '9a464aa6-3d95-421a-948d-be4bbc442bbe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Baham ko‘rish mohiyatini anglash". Bola endi o‘yinchog‘ini do‘stiga berish uni butunlay yo‘qotish emas, shunchaki "navbat bilan o‘ynash" ekanini tushunadi. Bu — hamdardlikning ilk urug‘lari. Uning bunday xatti-harakatini albatta "Do‘sting bilan baham ko‘rganing uchun rahmat" deb mustahkamlang.') WHERE id = '7f75fc5d-eb6e-4e7a-abdd-f9659116f406';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Son va miqdor o‘rtasidagi bog‘liqlik". Bola endi 1 dan 10 gacha yoddan sanash bilan birga, buyumlarni barmog‘i bilan ko‘rsatib, "bir, ikki, uch" deya ularning haqiqiy miqdorini sanay boshlaydi. Unga "Dasturxonga 3 ta qoshiq qo‘yaylik" kabi topshiriqlar bering. Bu mavhum sonlar real hayot bilan ilk bor jiddiy bog‘lanadigan bosqichdir.') WHERE id = '6bc8719d-b139-4ea0-af7e-596754bfb254';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Orqaga yurish". Bola endi ortiga qaramasdan, ishonch bilan bir necha qadam orqaga yura oladi. Bu harakat uning o‘z tanasini his qilishini (propriosepsiya) va makonda mo‘ljal olish qobiliyatini mustahkamlaydi. U bilan "Qisqichbaqalar poygasi" o‘yinini o‘ynab, ham zavqlaning, ham uning mushaklarini chiniqtiring.') WHERE id = '2fce926c-604e-40c3-aff1-959bf3574903';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum savollar". Bola endi "Nega?", "Qanday?" kabi savollar orqali dunyoni kashf etadi. "Bulut qayerga ketyapti?", "Chumoli qayerga yuguryapti?" kabi savollar uning qiziquvchanligini hamda atrofdagi olam bilan o‘rnatayotgan mantiqiy bog‘liqliklarini ko‘rsatadi. Javoblar sodda va bola tushunadigan tilda bo‘lishi muhim.') WHERE id = '5eb5c186-69a6-483f-9ba1-b6f471501a76';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "Sabr sinovi". Bola endi istagan narsasi uchun bir necha daqiqa kutishi kerakligini tushunadi. "Hozir emas, birozdan keyin" deganingizda darhol yig‘lamasa, bu uning his-tuyg‘ularini boshqarish qobiliyati rivojlanayotganidan dalolat beradi. Uning sabr qilganini ko‘rsangiz, "Kutganing uchun rahmat" deb ruhlantiring.') WHERE id = '6751f01f-eb8d-4bf5-bdeb-fec3d11483e8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ranglar va shakllarni birlashtirib, dunyoni tasvirlaydi. Agar u: "Menga o‘sha sariq kvadrat blokni bering", desa, bu uning miyasi bir vaqtning o‘zida bir nechta xususiyatni qayta ishlayotganini ko‘rsatadi. Bu qobiliyatini kundalik hayotdagi kichik topshiriqlar (masalan, "Ko‘k paypoqlaringni top") orqali qo‘llab-quvvatlang.') WHERE id = 'd8ae8173-4cc7-42b0-8737-2bedce267dcb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Dinamik muvozanat". Bola endi bir oyog‘ida 5 soniyagacha tura oladi. Bu vestibulyar tizim va oyoq mushaklari mustahkamlanayotganini ko‘rsatadi. U bilan "Laylak" o‘yinini o‘ynab, kim uzoqroq tura olishini sinab ko‘ring.') WHERE id = '071b03c5-b7b5-42d1-a970-a44e8e806595';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sabab-oqibat aloqalari". Bola endi "Agar... unda..." shaklidagi gaplarni tushuna boshlaydi. "Agar o‘yinchoqlaringni yig‘ishtirsang, multfilm ko‘rishimiz mumkin", deganingizda, u shartni tushunadi. Bu ham mantiqiy tafakkur, ham ichki intizom shakllanishi uchun muhim qadamdir.') WHERE id = 'a7ceb34f-04f4-4303-a5f6-fca236e067db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qaychi bilan ilk tajribalar". Bola endi qog‘ozni (xavfsiz qaychi bilan) to‘g‘ri chiziq bo‘ylab kesishga qiziqish bildiradi. Bu harakat qo‘l-ko‘z muvofiqligini ham, barmoqlarning mayda motorikasini ham rivojlantiradi. Uni nazoratsiz qoldirmang, lekin mustaqil harakat qilishiga to‘sqinlik qilmang.') WHERE id = '42cc6ea9-d4af-4873-a31f-be87ca7ae22d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Xayoliy o‘yin sheriklari". Bola endi yolg‘iz o‘ynayotganida ham baland ovozda gapiradi, o‘yinchoqlariga turli rollar beradi. Bu bolaga o‘z harakatlarini so‘zlar orqali boshqarishga yordam beradi. Uning bunday "monologlarini" tinglab, ichki dunyosida nimalar kechayotganini tushunishingiz mumkin.') WHERE id = 'b9a0516e-a5fd-46ab-abb8-4e16e305575b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tanlov: Qaror qabul qilish". Bola endi nima yeyishni yoki qaysi o‘yinni o‘ynashni istashini aniq biladi. Unga har kuni ikkita variant taklif qiling: "Olma xohlaysanmi yoki banan?". Bu unga o‘z hayotini boshqarish hissini beradi va o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = 'd2594413-54bc-4a0b-857c-1959a2b007b2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Hajm va miqdorning saqlanishi". Bola hozircha baland va tor idishdagi suvni keng idishdagi suvdan ko‘proq deb o‘ylashi mumkin. Bu yoshda bunday fikrlash tabiiy. U bilan suvli o‘yinlar o‘ynab, suvni turli idishlarga quyib ko‘ring. Bu uning mantiqni tajriba orqali tezroq anglashiga yordam beradi.') WHERE id = 'c2c7f4f2-7e4e-4f22-9785-bdddbd705503';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Ikki oyoqda oldinga sakrash". Bola endi to‘siqlar (masalan, yerdagi arqon) ustidan ikkala oyog‘i bilan bir vaqtda sakrab o‘ta oladi. Bu butun tana harakatlarini muvofiqlashtirishni talab qiladi. U uchun xavfsiz joylarda kichik to‘siqlar yo‘lakchasini tashkil qiling.') WHERE id = '3c4e0869-e516-493c-90a9-df3b2f2e738b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum vaqt tushunchasi". Bola endi "Ertalab", "Tush payti" va "Kechqurun" o‘rtasidagi farqni kundalik odatlar orqali anglaydi. "Kechqurun dada kelganida..." desangiz, u kunning shu vaqtini xayolida tasavvur qiladi. Kundalik tartibga rioya qilishingiz uning vaqt haqidagi tushunchasini xavfsizlik hissi bilan bog‘laydi.') WHERE id = 'd719015d-011e-40f6-8ffa-5cdcb4302e71';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy yetuklik: "Kechirasiz" so‘zining ma’nosi. Bola endi birovni ataylab yoki bilmasdan xafa qilganida "Kechirasiz" deyishning ijtimoiy ahamiyatini tushunadi. Unga doimo o‘rnak bo‘ling: xato qilganingizda undan kechirim so‘rang, shunda u ham bu xatti-harakatni kuchli fe’l-atvor belgisi sifatida qabul qiladi.') WHERE id = 'c8c25e23-7ba2-4ee9-a363-3be20d076417';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi rasmlarga qarab sodda hikoyalar to‘qiydi. "Ayiq o‘rmonga bordi, qorni ochdi va asal yedi" kabi izchil gaplar uning mantiqiy ketma-ketlikni anglayotganini ko‘rsatadi. Unga qiziqarli rasmlari bor kitoblar bering va "Sizningcha, keyin nima bo‘ladi?" deb so‘rang. Bu uning ijodiy tasavvurini yanada rivojlantiradi.') WHERE id = 'd67be23e-c203-4809-a7a3-cbfd66266b55';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Zinadan mustaqil tushish". Bola endi zinadan oyoqlarini navbatma-navbat har bir pog‘onaga qo‘yib, faqat bir qo‘lidan ushlagan holda (yoki umuman ushlamasdan) ishonch bilan tusha oladi. Bu uning yirik motorikasi to‘liq rivojlanganini ko‘rsatadi. Siz shunchaki yonida bo‘lib, unga ma’naviy dalda bering.') WHERE id = '7b344d73-ef09-40bc-8962-14de04d0a9d1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Savol-javob zanjiri». Bola endi savollaringizga shunchaki «ha/yo‘q» deb emas, to‘liq gaplar bilan javob beradi. «Bugun bog‘da kim bilan o‘ynading?» degan savolga batafsil javob bera oladi. U bilan suhbatlashganda «U qanday rangda edi?», «Nima qildingiz?» kabi davom ettiruvchi savollar berib, nutqini rivojlantiring.') WHERE id = '728c62de-e9bd-4825-a015-839c4ef09ac4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Yanada aniqroq bo‘yash». Bola endi kichik shakllarning chegaralarini ham his qiladi va bo‘yayotganda chiziqdan ko‘p chiqmaslikka harakat qiladi. Bu qo‘l mushaklarini boshqarishdagi katta yutuqdir. Unga turli qalinlikdagi rangli qalamlarni berib, sinab ko‘rishi uchun imkon yarating.') WHERE id = '1e2db868-b348-4ed1-a7d7-4e1b235065d6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Mustaqil kiyinish: fermuar va tugma». Bola endi katta tugmalarni yechishni va fermuar uchini joylashtirib berganingizdan so‘ng uni yuqoriga tortishni yaxshi uddalaydi. Unga «Qani, o‘zing sinab ko‘r» deb, sabr bilan kuting. Mustaqil kiyina olishi bolada «men buni uddalay olaman» degan tuyg‘u va o‘ziga bo‘lgan ishonchni nihoyatda oshiradi.') WHERE id = 'd0289832-2e1f-4c80-bf6f-025f04fde8c3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Bo‘lishish mantig‘i». Bola endi boshqa bolaning qo‘lidan o‘yinchoqni darhol tortib olmasdan, «ber» deb kutishga harakat qiladi. Bu o‘zini boshqarish (self-regulation) ko‘nikmasi mustahkamlanayotganini ko‘rsatadi. Uning bunday sabrli xatti-harakatini ko‘rganingizda, albatta: «Navbatingni kutganing uchun katta rahmat», deb maqtang.') WHERE id = '8b0e05af-2727-418a-b763-3601d197e7d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish qobiliyatining rivojlanishida «Umumiy va xususiy». Bola endi olma, nok va bananning barchasi «meva» ekanini tushunadi. Unga aralash buyumlarni ko‘rsating va «Bularning barchasini bir so‘z bilan nima deb ataymiz?» deb so‘rang. Toifalar asosida fikrlash uning miyasidagi ma’lumotlarni saqlash tizimini yanada tartibli qiladi.') WHERE id = 'cfa7be75-1286-4575-9a59-47547f98434d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «To‘pni yelka ustidan otish». Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni yelka ustidan oldinga, muayyan nishon tomon ota oladi. Bu butun tananing muvofiqlashgan harakatini talab qiladi. U bilan bog‘da «nishonga otish» o‘yinlarini o‘ynang.') WHERE id = '7ccd147e-b878-45ff-a8c8-f2d12fac2b06';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Makon va yo‘nalish". Bola "o‘ng" va "chap" tushunchalarini hali to‘liq farqlay olmasa-da, "oldinga", "orqaga", "yuqoriga" va "pastga" buyruqlarini aniq bajaradi. U bilan "Robot o‘yini"ni o‘ynang: "Ikki qadam oldinga, bir qadam orqaga!". Bu ham qiziqarli, ham makonda mo‘ljal olish qobiliyatini mustahkamlaydi.') WHERE id = 'd6a03598-2471-4b13-a839-fb2c51010318';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Muvaffaqiyatsizlikni yengib o‘tish". Bola endi kublari qulab tushganda darhol yig‘lamaydi, "Qaytadan quraman" deya oladi. Uning bu qat’iyatini qo‘llab-quvvatlang. 1130 kunni ortda qoldirdik — farzandingiz endi kichkina qahramon!') WHERE id = 'b7ab015d-a4e4-4c1d-a9a5-7f26c5798a69';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni bir vaqtning o‘zida ikkita xususiyatiga ko‘ra (masalan, ham rangi, ham shakliga qarab) ajrata oladi. Unga "Menga barcha kichik qizil mashinalarni ber" deganingizda buni bajara olsa, bu uning kognitiv rivojlanishidagi yangi bosqichdir. Kundalik uy ishlarida unga shunday kichik "tanlash" topshiriqlarini bering.') WHERE id = 'ff1dcdb3-fd81-4345-80ce-058e6b7a0d6b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Nishonga sakrash". Bola endi yerga chizilgan doira yoki rangli nishonning markaziga sakrashga harakat qiladi. Bu ham muvozanatni, ham makondagi masofani hisoblash qobiliyatini rivojlantiradi. Bog‘da u bilan "toshdan toshga sakrash" o‘yinini o‘ynang.') WHERE id = '5d8b4009-8971-48b6-aa55-75a96a823d2d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qarama-qarshi ma’noli so‘zlar doirasining kengayishi". Bola endi "erta-kech", "qorong‘i-yorug‘", "bo‘sh-to‘la" kabi mavhum qarama-qarshiliklarni tushunadi. Unga bo‘sh va to‘la stakanni ko‘rsatib, farqini so‘rang. Bu uning atrofdagi olamni qiyosiy tahlil qilish qobiliyatini mustahkamlaydi.') WHERE id = '18232b0a-482a-40e1-90c7-8a04a56dc3b9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Pazl mahorati". Bola endi 10-12 bo‘lakli murakkab pazllarni (rasmning chetlari va markazini ajrata olgan holda) to‘liq yig‘a oladi. Bu ham ko‘rish xotirasini, ham barmoqlarning nozik harakatlanish qobiliyatini rivojlantiradi. Uddalay olmasa, unga xotirjam ohangda maslahatlar bering.') WHERE id = '3045e148-b927-4872-8354-b9edb5116d18';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil tozalash va yordam berish". Bola endi dasturxonni yig‘ishtirishda o‘z likopchasini olib borish, ushoqlarni artish kabi ishlarni katta ishtiyoq bilan bajaradi. Unga bo‘yiga mos tozalash anjomlarini bering. Bu oiladagi mas’uliyat va daxldorlik hissini mustahkamlaydi. O‘z mehnatining natijasini ko‘rish uni juda xursand qiladi.') WHERE id = '5fed215f-7140-471a-887f-855f666792ab';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Qoidalar va chegaralar". Bola endi "yo‘q" so‘zining ortidagi mantiqni biroz yaxshiroq tushunadi, ammo baribir chegaralarni sinab ko‘rishni yoqtiradi. Sizning sabrli va izchil bo‘lishingiz unga xavfsizlik hissini beradi. Qoidalarni har doim bir xil tarzda qo‘llashga harakat qiling.') WHERE id = 'ad322e7c-2c29-48c7-ba0d-376889e0bc86';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Tartib sonlar". Bola endi "birinchi", "ikkinchi", "oxirgi" tushunchalarini anglaydi. Mashinalarni ketma-ket joylashtirib, "Qaysi mashina birinchi?" deb so‘rang. Bu uning ketma-ketlikni tushunishi va matematik tafakkurini rivojlantiradi. Musobaqalarda "Birinchi bo‘lib siz keldingiz!" deyish unga katta rag‘bat beradi.') WHERE id = 'ccdeb036-ba4e-49c8-960c-f4271e0fc740';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Orqaga va yonlama yurish". Bola endi turli yo‘nalishlarda chaqqon harakatlana oladi. U bilan "Ko‘zgu o‘yini"ni o‘ynang: siz yon tomonga qadam tashlang, u esa harakatingizni takrorlasin. Bu ham maroqli, ham tana harakatlarini muvofiqlashtirish qobiliyatini yangi bosqichga olib chiqadi.') WHERE id = '53f08fbe-8240-4c06-91f5-3a6645fa77af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum savollarning chuqurlashishi". Bola "Bulutlar qayerga ketyapti?", "Nega yulduzlar tunda chiqadi?" kabi savollari bilan sizni hayratda qoldirishi mumkin. Javob berayotganda uning tasavvurini ham ishga soling: "Sizningcha, yulduzlar hozir nima qilyapti?". Bu uning ijodiy tafakkurini rivojlantiradi.') WHERE id = 'ca368c4f-966b-4846-b9ca-ff68822b1eca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Baham ko‘rish quvonchi". Bola endi o‘yinchog‘i yoki shirinligini o‘z xohishi bilan baham ko‘rganida sizning quvonchingizni ko‘radi va buni yana takrorlashni istaydi. Uning bu saxiyligini "Do‘stingizni xursand qilganingiz uchun katta rahmat" deb alohida ta’kidlang. 1140 kunni muvaffaqiyatli yakunladik – siz ajoyib onasiz!') WHERE id = '706c863b-0328-4280-9ae2-b61f0dddff18';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '39-oyga qadam qo‘yyapmiz! Bola endi "ikki bosqichli" fikrlashdan "uch bosqichli" topshiriqlarga o‘tmoqda. "O‘yinchoqni ol, qutiga sol va qopqog‘ini yop" deganingizda ketma-ketlikni buzmay bajarsa, bu uning operativ xotirasi (working memory) uchun katta yutuqdir. Kun davomida unga kichik va mantiqan bir-biriga bog‘langan topshiriqlar berib, bu ko‘nikmasini rivojlantiring.') WHERE id = '0f30e0b2-fa18-4fe2-8164-072ae2911569';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Tez yugurish va manyovr qilish". Bola endi yugurayotganda oldidagi to‘siqni ko‘rsa, tezligini pasaytirmasdan uni aylanib o‘ta oladi. Bu uning tana sezgisi (proprioception) to‘liq shakllanganini ko‘rsatadi. Bog‘da "to‘siqlar osha yugurish" musobaqalarini tashkil qilib, uning energiyasini foydali tomonga yo‘naltiring.') WHERE id = 'c69b10fa-3ecf-43fd-9d25-d70589994cb8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qiyoslash darajalari". Bola endi "kattaroq", "eng kichik", "juda mazali" kabi iboralarni o‘rinli ishlatadi. Buyumlarni taqqoslab, u bilan suhbatlashing: "Bu olma shirinroqmi yoki unisimi?". Sifat darajalarini o‘zlashtirish uning tasviriy nutqini boyitadi va fikrlarini aniqroq ifodalashiga yordam beradi.') WHERE id = '10874a8b-618a-44ed-9a23-9c2c3bcf6530';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Haykaltaroshlik". Bola endi plastilin yoki kinetik qum bilan ishlaganda ularni shunchaki siqib qolmay, ulardan "to‘p", "ilon" yoki "non" kabi tanish shakllarni yasaydi. Bu ham ijodiy tafakkurni rivojlantirish, ham barmoq uchlaridagi mayda mushaklarni mustahkamlash uchun ajoyib mashqdir.') WHERE id = '8ef81138-3a54-4c5e-ab33-5ab135be888d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish: Teskari va o‘ngini farqlash". Bola endi ko‘ylak yoki shimning teskari va o‘ngini, poyabzalning o‘ng va chapini (ba’zan adashsa ham) farqlashga harakat qiladi. Unga kichik maslahatlar bering: "Qara, rasmli tomoni oldinga qarashi kerak". Bu uning diqqatini tafsilotlarga qaratish va o‘ziga xizmat ko‘rsatish ko‘nikmalarini takomillashtiradi.') WHERE id = '0d252040-b7cf-42d1-8e5c-b4a1ea436608';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Jamoaviy ruh". Bola endi boshqa bolalar bilan birgalikda umumiy maqsad yo‘lida (masalan, katta qal’a qurish uchun) o‘ynay oladi. Bu "Parallel o‘yin"dan "Hamkorlikdagi o‘yin"ga o‘tishdir. Uning boshqa bolalar bilan qanday til topishayotganini kuzating va murakkab vaziyatlarda unga ijtimoiy "ko‘prik" qurishga yordam bering.') WHERE id = 'b59f81d2-048d-48f5-8c51-231cd1498118';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Raqam va miqdor mosligi". Bola 1 dan 5 gacha sanashni biladi, endi esa "3" raqamini ko‘rganda 3 ta o‘yinchoqni ajratib qo‘ya oladi. Bu matematik tafakkur rivojlanishining eng muhim bosqichlaridan biridir. Kundalik hayotda "Menga 2 ta qoshiq ber" kabi topshiriqlar bilan bu bog‘liqlikni mustahkamlang.') WHERE id = '5b8b658c-3ba9-46dd-b7e1-a329bde32c59';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Yuqoridan otilgan to‘pni tutish". Bola endi o‘ziga qarab sekin otilgan katta to‘pni ikki qo‘li bilan tutishga harakat qiladi. Bu harakat qo‘l va ko‘z muvofiqligini hamda tezkor reaksiya qilishni talab etadi. U bilan yaqin masofadan "to‘pni tut" o‘yinini o‘ynang.') WHERE id = '9cbfafe8-e2d3-4b4c-a7dd-a7d50a0d73a4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum savollarning cho‘qqisi". Bola endi "Nega shamol esadi?", "Quyosh uxlash uchun qayerga ketadi?" kabi borliq va tabiat hodisalari haqida savollar beradi. Javob berayotganda tasavvur kuchini ham ishga soling: "Quyosh charchadi, ertaga bizni yana uyg‘otish uchun dam olgani ketyapti". Bu uning dunyoqarashi va bilim olishga bo‘lgan ishtiyoqini kuchaytiradi.') WHERE id = 'be40f099-56c3-42b3-90d0-8aec32c8e2ca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy yetuklik: "Boshqalarning his-tuyg‘ularini tan olish". Bola endi sizning charchaganingizni yoki boshqa bolaning xafa bo‘lganini ko‘rsa, "Nima bo‘ldi?" deb so‘raydi va tasalli berishga harakat qiladi. Bu uning mehr-shafqatli inson bo‘lib shakllanayotganini ko‘rsatadi. Siz ajoyib onasiz!') WHERE id = '28850826-f8da-4cde-a0f3-c10d2981e7f4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "men" va "meniki" tushunchalarini ijtimoiy munosabatlarda sinab ko‘rmoqda. O‘yinchog‘ini bo‘lishishni istamasligi xudbinlikdan ko‘ra ko‘proq o‘z chegaralarini belgilashga urinishdir. Unga "Bu sening o‘yinchog‘ing, tayyor bo‘lganingda uni do‘stingga berishing mumkin" deb, uning egalik hissini hurmat qilishingizni ko‘rsating. Bu kelajakda unda boshqalarning chegaralarini ham hurmat qilish qobiliyatini shakllantiradi.') WHERE id = '3d0a961f-8311-4c15-82e4-3b93885267b5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Yuqoridan sakrash". Bola endi pastak zina yoki mato ustidan ikki oyog‘i bilan bir vaqtda yerga sakrashni yaxshi ko‘radi. Bu harakat uning vestibulyar tizimi rivojlanishi uchun muhimdir. Yerga yumshoq to‘shakcha qo‘yib, uning bu jasoratini xavfsiz tarzda qo‘llab-quvvatlang.') WHERE id = '0680b361-8e77-46ad-a0ea-0e96e9759bdc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Sifatlar boyligi». Bola buyumlarni tasvirlashda «yumshoq», «tikanli», «silliq», «yaltiroq» kabi so‘zlardan foydalana boshlaydi. U bilan «Tegin va top» o‘yinini o‘ynang: ko‘zlarini yumib, buyum ushlaganda qanday tuyulishini aytishini so‘rang.') WHERE id = '0b5835ed-17d3-46e9-b2cd-eb9c92154c53';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: «Boshqalarga yordam berish». Bola endi biror ishda qiynalayotganingizni yoki nimanidir qidirayotganingizni ko‘rib, sizga yordam taklif qilishi mumkin. Bu uning egotsentrik davrdan chiqib, haqiqiy «ijtimoiy hamkor»ga aylanayotganini ko‘rsatadi. Uning yordamini «Sen bo‘lmaganingda, men buni topa olmasdim», deb alohida e’tirof eting.') WHERE id = '95ef23e6-3a1e-4eb7-bed7-103fc452a1e2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi «oqibat»ni hisobga olib fikrlay boshlaydi. Masalan, sizning eslatishingiz yordamida «Agar shirinlik yesam, tishlarim og‘rishi mumkin» kabi sabab-oqibat bog‘liqliklarini tushunishga harakat qiladi. Bu davrda unga qoidalarning sabablarini tushuntirish juda muhim. Bu unda ko‘r-ko‘rona bo‘ysunishni emas, balki ichki mantiqqa asoslangan intizomni shakllantiradi.') WHERE id = '602eea29-96df-4d75-b3f3-a89b088efbe3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda «Dinamik muvozanat». Bola endi yerga chizilgan to‘g‘ri chiziq yoki arqon ustidan muvozanatini yo‘qotmay, «dorboz» kabi yura oladi. Bu vestibulyar tizimning to‘liq yetilganini ko‘rsatadi. U bilan bog‘da bordyurlar ustidan (qo‘lidan ushlab) yurish bu ko‘nikmasini yanada takomillashtiradi.') WHERE id = '5465b5ac-4749-433f-99e1-222fda8c10bf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Voqealarni batafsil bayon qilish». Bola endi kun davomida boshidan kechirgan biror voqeani 4-5 ta ketma-ket gap bilan aytib bera oladi. «Bugun bog‘ga bordik, Elchinni ko‘rdim, biz qum o‘ynadik». Uning hikoyalarini diqqat bilan tinglang va «Keyin nima bo‘ldi?» deb suhbatni davom ettiring. Bu uning og‘zaki xotirasi va nutq ravonligini yaxshilaydi.') WHERE id = '7607f78f-a199-4155-af72-552bbd09b140';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Doiradan ramzlarga». Bola endi yopiq doiralar chizadi va ularni «odam» (tayoqcha odam) ko‘rinishida tasvirlash uchun pastiga chiziqlar qo‘shadi. Bu vizual ramzlashtirishning boshlanishidir. Unga rangli qalamlar berib, «Bugun kimning rasmini chizyapsan?» deb so‘rang va tasavvurini rag‘batlantiring.') WHERE id = 'ead2dac9-db7b-47ae-9b92-23aa29cddd39';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Kelasi zamonni aniqlashtirish". Bola endi shunchaki "boramiz" demaydi, balki "Ertaga buvimnikiga borib, mushuk bilan o‘ynaymiz" kabi izchil rejalar tuzadi. Kun oxirida u bilan ertangi rejalarni muhokama qiling. Bu uning voqealarni oldindan tasavvur qilish va rejalashtirish (ijro funksiyasi) ko‘nikmasini rivojlantiradi.') WHERE id = 'e7723585-78f9-489b-95f6-9d306c6417b7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Murakkabroq shakllar". Bola endi qalamni mohirona (uch barmoqli usulda) ushlaydi va qog‘ozga uchburchak yoki kesishuvchi chiziqlar chizishga harakat qiladi. Bu uning qo‘l mushaklari yozishga deyarli tayyor ekanini ko‘rsatadi. Unga "Keling, nuqtalarni birlashtiramiz" o‘yinini taklif qiling.') WHERE id = '23c81011-ddf7-4cf3-aec3-f115d29c3f5e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil gigiyena: Tishlarni tozalash". Bola endi tishlarini tozalash ketma-ketligini biladi. Siz hali ham oxirida "tekshirishingiz" kerak bo‘lsa-da, unga bu ishni mustaqil bajarish imkonini bering. Bu odat uning o‘z tanasiga g‘amxo‘rlik qilish mas’uliyatini oshiradi.') WHERE id = '94615e85-6da2-44c7-a201-6901c2a92ddf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Xayoliy hikoyalar va yolg‘on". Bola ba’zan haqiqatda bo‘lmagan narsalarni aytishi mumkin (masalan, "Men osmonda uchdim"). Bu aldash emas, balki tasavvur va nutqning uyg‘unlashuvidir. Unga "Qanday qiziq hikoya!" deb, tasavvur kuchini maqtang, ammo haqiqat va xayol o‘rtasidagi nozik farqni ham muloyimlik bilan tushuntiring.') WHERE id = 'd70b5fda-77b6-4fb1-bc69-d894fe21ca89';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Toifalarning chuqurlashuvi". Bola endi buyumlarni shunchaki "mashina" deb emas, balki "tez yuradigan mashina", "yuk mashinasi" kabi kichik guruhlarga ajratadi. Unga "Qaysi buyumlar suvda suzadi, qaysilari cho‘kadi?" tajribasini taklif qiling. Bu uning ilmiy kuzatish ko‘nikmasi uchun poydevordir.') WHERE id = '164e0d4f-5849-466c-88ec-e6961c6d0680';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni oyoq bilan boshqarish". Bola endi to‘pni shunchaki tepmaydi, balki uni oyog‘i bilan biroz oldinga surib, harakatlantirishga urinadi. Bu dinamik muvozanat uchun ajoyib mashqdir. U bilan bog‘da kichik bir "futbol yo‘lakchasi" yarating.') WHERE id = 'c019ed6e-efde-47c2-b2ac-37c3fbd433b5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil kiyinish: tugma va fermuar". Bola endi katta tugmalarni qadashga va fermuarni mustaqil yopishga intiladi. Bu barmoqlarning nozik harakatlarini muvofiqlashtirishni talab qiladi. Ertalab kiyinish paytida bu jarayonni o‘zi yakunlashi uchun unga 5 daqiqa qo‘shimcha vaqt bering. Buni mustaqil uddalaganida tuyadigan faxr hissi bebahodir.') WHERE id = '24f54158-6d74-423e-b96c-5270e549d121';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Navbat kutish va sabr". Bola endi arg‘imchoqda uchish uchun boshqa bolaning tushishini kutish kerakligini tushunadi. "Navbat sizniki" va "Navbat meniki" tushunchalari ijtimoiy muhitdagi kelishmovchiliklarni kamaytiradi. Uning bu sabrini albatta "Navbatingni kutganing uchun katta rahmat" deb maqtang.') WHERE id = '97f18e0c-30d0-42a5-aa90-ac6015233d99';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Miqdorni anglash". Bola 1-dan 10-gacha sanashdan tashqari, endi 3 yoki 4 ta buyumni sanamasdan, bir qarashdayoq aniqlay oladi (subitizing). Undan "Bu yerda nechta olma bor?" deb so‘rang va barmog‘i bilan ko‘rsatib sanashini iltimos qiling. Bu kelajakdagi matematik tafakkurning poydevoridir.') WHERE id = '6e61f63b-18f2-4f84-b98e-0d07b524e3e9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni ikki qo‘l bilan tutish". Bola endi o‘ziga qarab sekin otilgan to‘pni qo‘llarini bukib, kaftlarini ko‘kragi oldida birlashtirgan holda tuta boshlaydi. Bu reaksiya tezligi va qo‘l-ko‘z muvofiqligining rivojlanishidir. U bilan uyda yumshoq to‘p yordamida qisqa "to‘pni tut" mashg‘ulotlarini o‘tkazing.') WHERE id = 'eb5816aa-f53e-4699-abf2-d1ff0b98f5f9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum tushunchalar: vaqt". Bola hali "Soat necha bo‘ldi?" degan savolni tushunmasa-da, "ertaga", "kecha", "keyin" kabi so‘zlarni o‘rnida ishlatishga harakat qiladi. Unga vaqtni kundalik odatlar orqali tushuntiring: "Uyqudan uyg‘onganingda ertaga bo‘ladi". Bu unga dunyoni yanada tartibli va oldindan bilish mumkin bo‘lgan tarzda tasavvur qilishga yordam beradi.') WHERE id = '6c159ac6-63d6-41de-9c9e-e48fdddeeaef';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Muvaffaqiyatsizlikdan qo‘rqmaslik". Bola endi biror ishni (masalan, kublardan qal’a qurishni) uddalay olmasa, darhol yig‘lamaydi, sizga qarab "Yana bir marta qilib ko‘raymi?" deyishi mumkin. Natijasini emas, harakatini maqtang: "Sen juda ko‘p harakat qilding va yana urinib ko‘rding, barakalla!". Siz ajoyib yo‘l-yo‘ldoshsiz!') WHERE id = '487ce40e-d1a5-42bb-ab35-fd94c37e1b74';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi o‘z his-tuyg‘ularini murakkabroq tarzda ifodalaydi: "O‘yinchog‘im singani uchun xafaman". Bu — hissiy intellekt rivojidagi katta sakrash. Uning hislarini shunchaki qabul qilibgina qolmay, yechim topishiga ham imkon bering: "Seningcha, uni qanday tuzatsak bo‘ladi?". Bu bolada bardoshlilikni (resilience) ham rivojlantiradi.') WHERE id = '72c6a670-175e-4e59-a40a-08a5b3924e43';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Yon tomonga sakrash". Bola endi faqat oldinga emas, yon tomonga ham sakray oladi. Buning uchun son va oyoq mushaklari turli yo‘nalishlarda muvofiqlashgan holda ishlashi kerak. U bilan yerga chizilgan chiziqlar ustidan "yon tomonga sakrash" musobaqasini o‘tkazing.') WHERE id = '7ad7a096-5914-4eed-80cb-8089f672c249';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Olmoshlarni to‘liq o‘zlashtirish". Bola endi "meniki", "seniki", "uniki" tushunchalarini hech qachon chalkashtirmaydi. "Bu mening o‘yinchog‘im, unisi esa seniki", deb ijtimoiy egalik chegaralarini belgilaydi. Bu davr unga umumiy foydalaniladigan buyumlar (masalan, oilaviy kitob) bilan shaxsiy buyumlar o‘rtasidagi farqni tushuntirish uchun ayni muddao.') WHERE id = '2b8c7b62-f908-41ef-8972-07466c4a7bd0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Simmetriyaga urinishlar". Bola qog‘ozni buklashga yoki chizgan rasmidagi detallarni simmetrik joylashtirishga harakat qiladi. Masalan, chizgan odamining ikki tomoniga ham quloq yoki qo‘l qo‘shadi. Bu miya ikkala yarimsharining muvofiqlashgan holda rivojlanayotganidan dalolat beradi.') WHERE id = 'bd356611-73c3-4619-9883-1f920ac53fa9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Mustaqil ovqatlanish odobi". Bola endi sanchqidan mohirona foydalanadi va pichoq (bolalar uchun xavfsiz pichoq) bilan yumshoq mahsulotlarni (masalan, banan yoki omletni) kesishga urinadi. Unga bunday mustaqillikni bering. O‘ziga o‘zi xizmat qilish hissi uning o‘ziga bo‘lgan ishonchini ichdan mustahkamlaydi.') WHERE id = 'a07fbd02-0c2f-49de-ba5e-43f31c0bcc20';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Qoidali o‘yinlar". Bola endi "Bekinmachoq" yoki "Quvlashmachoq" kabi oddiy qoidalarga ega o‘yinlarni qoidalarni buzmasdan o‘ynashga qiziqish bildiradi. Bu — ijtimoiy moslashuvning muhim bosqichi. Qoidalarga rioya qilganida uni albatta "Halol o‘ynaganing uchun barakalla", deb maqtang.') WHERE id = 'e172dbdc-63ea-4b2b-afac-30588be411eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Bo‘y va uzunlikni taqqoslash". Bola endi buyumlarni balandligiga qarab tartib bilan joylashtira oladi. Unga 3-4 xil o‘lchamdagi o‘yinchoq bering va "Eng balandidan eng pastigacha terib chiq" deng. Bu uning vizual idroki va mantiqiy tartiblash ko‘nikmasini rivojlantiradi.') WHERE id = '3281647e-af83-48c8-9e0e-9deebd826a8f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Uch g‘ildirakli velosipedda manevr qilish". Bola endi velosiped haydayotganda oldidagi to‘siqni ko‘rib, rulni burish orqali uni chetlab o‘ta oladi. Bu pedallarni aylantirish (jismoniy) va yo‘lni kuzatish (vizual) ko‘nikmalarining uyg‘unlashuvidir. Parkda uning uchun xavfsiz "haydash yo‘lakchasi" tayyorlab, bu ko‘nikmasini qo‘llab-quvvatlang.') WHERE id = 'cccc4e73-bd8f-49ce-ac37-8b06ba255913';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt va ketma-ketlik". Bola endi "Ertaga buvimnikiga boramiz, keyin men parkka boraman" kabi kelajak rejalarini tuzadi. Bu uning miyasida voqealarni oldindan ko‘z oldiga keltirish (vizualizatsiya) qobiliyati rivojlanayotganini ko‘rsatadi. Kun oxirida u bilan ertangi rejalarni "ertak" kabi so‘zlab, uyquga yoting.') WHERE id = '533647bf-c77f-434e-8420-bd22239f3086';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Sabr va kutish". Bola endi navbatda bir necha daqiqa kutish "hammasi tugadi" degani emasligini, bu shunchaki vaqtinchalik holat ekanini tushunadi. Bu uning o‘zini boshqarish (ijro funksiyasi) ko‘nikmasi rivojlanayotganini ko‘rsatadi. 1180 kun – farzandingiz endi dunyoni anglaydigan va unga moslashadigan jajji bir shaxsdir. Siz ajoyib yo‘l hamrohisiz!') WHERE id = 'fe96ce06-9654-4a3f-8b50-d93363f0cbca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi o‘zini jismoniy xususiyatlari orqali ta’riflaydi: "Men tez yuguraman" yoki "Men baland bo‘yliman". Bu o‘zini anglash bosqichining yangi darajasidir. Uning o‘zi haqidagi ijobiy tasavvurini qo‘llab-quvvatlang. O‘zini qanday ko‘rishi haqida savollar bering: "Seningcha, yana nimalarni yaxshi bajara olasan?".') WHERE id = '4f2b9702-c295-43cf-9776-2d9fd4b98c79';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Dinamik sakrash". Bola endi yugurayotganda yo‘lida uchragan kichik to‘siq (masalan, yerdagi arqon) ustidan tezligini pasaytirmasdan sakrab o‘ta oladi. Bu miyada harakatni oldindan rejalashtirish (motorli rejalashtirish) ko‘nikmasi rivojlanayotganini ko‘rsatadi.') WHERE id = '63d363dc-9356-4fa8-bbd3-57a0c8ed1083';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Maqsadli savollar". U endi shunchaki "bu nima?" deb emas, "bu qanday ishlaydi?" deb so‘raydi. Buyumlarning ichki mexanizmiga qiziqish bildiradi. Javob berayotganda ortiqcha murakkablashtirmang, ammo mantiqiy izchillikni saqlang. Bu savollar kelajakdagi ilmiy tafakkurning ilk uchqunlaridir.') WHERE id = 'fda8c637-494b-4891-b635-d2a91f4dbd7b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Shakllar kombinatsiyasi". Bola endi shunchaki doira chizmaydi, balki doiralarni birlashtirib, "qurtcha" yoki "qorbobo" yasaydi. Bu uning vizual belgilarni birlashtirib, yangi ma’nolar yaratish qobiliyatini ko‘rsatadi.') WHERE id = 'c2392a7c-85eb-4d9e-aff3-15371b541a80';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Siyosiy" muzokaralar. Bola endi siz bilan "savdolashadi": "Agar o‘yinchoqlarimni yig‘ishtirsam, menga yana bitta ertak o‘qib berasizmi?". Bu uning ijtimoiy ta’sir mexanizmlarini o‘rganayotganini ko‘rsatadi. Bunday "muzokaralarda" adolatli bo‘ling, ammo asosiy qoidalaringizga rioya qiling.') WHERE id = '1c3607b2-8132-49bc-b9ba-d3f310a2378b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Xayoliy ssenariylar". Endi o‘yinlar murakkabroq: "Men oshpazman, siz esa mijozsiz, menga pul berishingiz kerak". Bunday o‘yinlarda u jamiyatdagi rollar va iqtisodiy munosabatlarni sinab ko‘radi. Uning ssenariylariga moslashib, bu ijodiy jarayonni rag‘batlantiring.') WHERE id = '74c3e2b6-b59d-47f7-ac39-b3a6571a3f4e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Buyumlarning vazifasi". Bola endi buyumlarni faqat tashqi ko‘rinishiga qarab emas, vazifasiga ko‘ra ham guruhlaydi. "Bular kesuvchi asboblar (qaychi, pichoq)", "Bular esa yozish uchun ishlatiladigan vositalar". Bu uning miyasidagi ma’lumotlar tizimliroq va funksionalroq bo‘lib borayotganini ko‘rsatadi.') WHERE id = '78693b6d-347d-4486-94dc-37e920221a4d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Zinadan mustaqil chiqish". Bola endi zinadan oyoqlarini navbatma-navbat har bir pog‘onaga qo‘yib va deyarli hech narsaga tegmasdan ishonch bilan ko‘tariladi. Bu muvozanat va oyoq mushaklari kuchi yuqori darajada rivojlanganini ko‘rsatadi.') WHERE id = 'cc0be0ea-ed32-4ad7-a00e-446a9d717d47';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Chunki» davri. U o‘z harakatlarini asoslashga urinadi: «Men buni kiymayman, chunki bu menga botyapti». Uning «chunki»larini tinglang. Bu uning o‘z ehtiyojlari va noqulayliklarini mantiqan ifodalash qobiliyatini mustahkamlaydi.') WHERE id = '1172f061-c7e1-4517-8b34-e51a76cdf51e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: «Boshqalarning yutug‘idan quvonish». Bola endi sizning yoki do‘stining yutug‘ini (masalan, o‘yinda g‘alaba qozonganini) ko‘rganda «Barakalla!» deya oladi. Bu egotsentrizmning (faqat o‘zini o‘ylashning) kamayishi va boshqalar bilan birga quvonishning boshlanishidir. Siz ajoyib insonni voyaga yetkazyapsiz!') WHERE id = 'e58983bd-cd78-4d0a-8590-e07b73fa9e05';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi «Nega?» degan savollarni shunchaki javob olish uchun emas, balki sabab-oqibat bog‘liqligini tushunish uchun beradi. Uning «Nega barglar yerga to‘kiladi?» kabi tabiat hodisalariga qiziqishi ortadi. Unga sodda va ilmiy dalillarga asoslangan javoblar bering. Bu uning atrofdagi olamga tahliliy qarashini shakllantiradi.') WHERE id = '8335f345-0d57-482d-b821-779e730295ca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda «Muvozanat ustasi». Bola endi tor yo‘lakcha yoki yerga qo‘yilgan arqon ustida muvozanatini saqlab, ishonch bilan yura oladi. Bu vestibulyar tizim rivojlanishining yuqori bosqichidir. Uyda u bilan «Dorboz» o‘yinini o‘ynab, harakatlarining aniqligini oshiring.') WHERE id = '00cce1f4-ca47-462d-b84a-6205502d4f13';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «O‘tmish va kelajak uyg‘unligi». Bola «Kecha men parkka bordim, ertaga esa buvimnikiga boraman» kabi gaplarda zamon farqlarini to‘g‘ri qo‘llaydi. Vaqt tushunchasini mustahkamlash uchun unga kundalik ishlarni «avval, hozir, keyin» ketma-ketligida eslatishda davom eting.') WHERE id = '10538e9b-c203-4dd2-8b24-d807c72fa3fb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Insonning batafsil tasviri». Bola endi «cho‘p odam» rasmini chizganda unga barmoqlar, sochlar yoki ko‘zlar kabi ko‘proq tafsilotlarni qo‘shadi. Bu uning vizual kuzatuvchanligi va qo‘l-miya muvofiqlashuvi qay darajada takomillashganini ko‘rsatadi.') WHERE id = 'e534e280-1b5b-4f3e-b1db-79a0cf64e3af';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Shaxsiy chegaralarni himoya qilish". Bola endi "Mening xonam", "Mening stolim" deya o‘z shaxsiy makonini belgilaydi. Uning shaxsiy makon haqidagi tuyg‘usini hurmat qiling. "Xonangizga kirsam maylimi?" deb so‘rash orqali siz unga shaxsiy chegaralarni hurmat qilishni va kelajakda boshqalarning ham chegaralarini tan olishni o‘rgatasiz.') WHERE id = '19704700-4f78-4a2f-8063-e34e01705522';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Adolat hissi". Bola endi o‘yinlarda qoidalar buzilishiga munosabat bildiradi: "U navbatni buzdi!". Bu uning ijtimoiy adolat va qoidalar haqidagi tushunchasi rivojlanayotganini ko‘rsatadi. Unga qoidalar nima uchun muhimligini (masalan, o‘yin qiziqarli bo‘lishi uchun) tushuntirish orqali ijtimoiy odob-axloq asoslarini shakllantiring.') WHERE id = 'bb50baca-3306-43e8-84f0-8ecfe4ce2ed7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda "Miqdor va raqam uyg‘unligi". Bola 10 gacha sanay oladi, endi esa raqamlarni miqdor bilan bog‘laydi. "Bu yerga 5 dona funduq qo‘ydim" deganingizda, u miqdorni ko‘z bilan chamalay oladi. Kundalik yumushlarda unga "Menga 4 dona qoshiq ber" kabi topshiriqlar bering.') WHERE id = '3b180a00-84f2-4ef7-b180-bb007866d4c3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashuv: "Uch g‘ildirakli velosipedda tezlik". Bola endi velosipedni tezroq boshqaradi va to‘siqlar orasidan mohirlik bilan o‘tadi. Bu oyoq mushaklarining kuchi hamda ko‘rish va harakat muvofiqlashuvi yuqori darajada rivojlanganini ko‘rsatadi. Parkda uning tezligini sinab ko‘rishi uchun xavfsiz "velosiped yo‘laklari"ni belgilab bering.') WHERE id = 'cf35973e-cf99-454b-b4d7-5058e5466945';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hazil va yumor". Bola endi so‘zlarni o‘ynatishga, "g‘alati" gaplar tuzib, sizni kuldirishga harakat qiladi. Masalan, "It miyov dedi" deb kulishi mumkin. Bu uning til qoidalarini bilishini va hazil yaratish uchun ularni ataylab buzayotganini ko‘rsatadi. U bilan birga kuling va yumor tuyg‘usini rivojlantiring.') WHERE id = '7856919f-0f1f-4c55-9554-5d9226e933f6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1200 kunlik ulkan sayohat! Bola allaqachon 40 oyni ortda qoldirdi. Endi u o‘z fikrlari, hazillari va orzulariga ega bo‘lgan kichkina, ammo mustaqil shaxs. Siz shu 1200 kun davomida uning dunyosini bunyod etdingiz. Uning o‘ziga ishonch bilan boqishida sizning mehringiz izi bor. Siz ajoyib onasiz!') WHERE id = '1104a81e-20a0-469a-b38d-bffb8442b875';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '41-oyga xush kelibsiz! Bu davrda bolada "niyat" tushunchasi shakllanadi. U endi voqealar tasodifan yoki ataylab sodir bo‘lganini farqlay boshlaydi. Masalan, kimdir unga tegib ketsa, "Buni ataylab qildingmi?" deb so‘rashi mumkin. Bu ijtimoiy munosabatlarda halollik va niyatni tushunish uchun muhim bosqichdir.') WHERE id = 'be82050e-9ad6-486e-9d98-a2c2c31a243e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Bir oyoqda sakrash". Bola endi bir oyog‘ida ketma-ket bir necha marta sakrashga urinadi. Buning uchun ham kuch, ham yuqori darajadagi muvozanat talab etiladi. U bilan bog‘da "bir oyoqda sakrash musobaqasi"ni o‘ynab, bu ko‘nikmasini qo‘llab-quvvatlang.') WHERE id = '59f9bda8-ddf4-49be-ad49-7ae815287273';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mantiqiy bog‘lovchilar". Bola endi "ammo", "chunki", "agar" bog‘lovchilarini gaplarida mohirlik bilan qo‘llaydi. "Men bog‘ga borishni xohlayman, ammo yomg‘ir yog‘yapti". Bu uning ongidagi qarama-qarshi fikrlarni birlashtira olish qobiliyatini ko‘rsatadi. U bilan suhbatlashganda ushbu bog‘lovchilardan foydalanib, muloqotni davom ettiring.') WHERE id = 'b5dc9cdd-e5bc-4c21-ba9e-2e9fe7dbdaee';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qog‘ozni kesish". Bola endi xavfsiz qaychi yordamida qog‘ozdagi to‘g‘ri chiziq bo‘ylab kesishni uddalaydi. Bu qo‘l va ko‘z muvofiqlashuvining yuqori darajasidir. Unga kesib-yopishtirish (applikatsiya) ishlari uchun rangli qog‘ozlar va andozalar bering.') WHERE id = '93689350-75d1-4dc3-befa-2516fff9cb92';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish (Self-regulation)". Bola endi jahli chiqqanda yoki xafa bo‘lganda o‘zini tinchlantirish uchun siz taklif qilgan usullardan (masalan, chuqur nafas olish yoki o‘yinchog‘ini quchoqlash) foydalanishi mumkin. Bu — hissiy intellekt bilan bog‘liq eng muhim hayotiy ko‘nikmalardan biridir.') WHERE id = 'cad2a6f6-14d3-4ac8-a455-240edf668e56';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Qoidali jamoaviy o‘yinlar". Bola endi guruhda bir xil qoidalarga rioya qilib o‘ynashga qiziqish bildiradi. "Endi hammamiz quyon kabi sakraymiz" desangiz, u jamoaga moslashadi. Bu maktab muhiti uchun muhim bo‘lgan "guruhda harakat qilish" ko‘nikmasining asosidir.') WHERE id = '6f7c2344-f4ee-4701-9810-594e0c930fc0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Vaqtni vizuallashtirish". Bola endi "Kecha nima qildik?" degan savolga izchil javob beradi. Unga kun davomidagi voqealarni rasmlar bilan ko‘rsatadigan "kunlik reja" tuzing. Bu uning vaqt haqidagi mavhum tushunchasini aniqlashtiradi.') WHERE id = 'ecad2493-1c0b-4ab4-b089-7a992488d7c5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni nishonga otish". Bola endi to‘pni shunchaki otmaydi, balki uni muayyan quti ichiga yoki nishonga tushirishga harakat qiladi. Bu fazoda masofa va kuchni to‘g‘ri baholash (fazoviy baholash) qobiliyatini rivojlantiradi.') WHERE id = '6f552613-227f-4085-940c-f293c42bd5f1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Savollarning chuqurlashishi". Bola "O‘lim nima?", "Biz qayerdan kelganmiz?" kabi hayot va mavjudlikka oid murakkab savollar berishi mumkin. Javob berayotganda doimo rostgo‘y bo‘ling, ammo uning yoshiga mos sodda va tinchlantiruvchi izohlarni tanlang. Bu savollar uning dunyoni anglashga bo‘lgan urinishidir.') WHERE id = '5eb1ed63-47a4-4170-b1fc-b58d4507160b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "Ijod orqali o‘zini ifodalash". Bola endi kayfiyati bo‘lmaganda rasm chizib yoki o‘yinchoqlari bilan "dardlashib", o‘zini yengil his qiladi. U chizgan rasmlarga e’tibor bering; ranglar va shakllar uning ichki dunyosini aks ettiradi. Siz uning eng ishonchli panohisiz, sizga bo‘lgan ishonchi esa uning eng katta kuchidir.') WHERE id = '48efdb3a-063c-40d5-837a-9373492693c6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi atrofidagi yozuvlarga qiziqish bildira boshlaydi. Do‘kon nomlari yoki kitob sarlavhalarida o‘zi taniydigan harflarni (masalan, ismining bosh harfini) ko‘rib quvonishi mumkin. Bu "dastlabki savodxonlik" bosqichidir. Unga harflarni majburan o‘rgatmang, shunchaki qiziqishini rag‘batlantiring.') WHERE id = '4c700caf-0287-4ea7-8bd0-73ca97292800';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Oyoqlarni navbatma-navbat qo‘yib tushish". Bola endi zinadan tushayotganda har bir pog‘onaga bir oyog‘ini qo‘yib, ya’ni oyoqlarini navbatma-navbat almashtirib tusha boshlaydi. Bu zinadan chiqishga qaraganda qiyinroq bo‘lib, yaxshi muvozanatni talab qiladi. Siz shunchaki yaqinida turib, unga xavfsizlik hissini bering.') WHERE id = '970cfec9-666d-4324-ad8a-2d2689753b64';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «So‘z o‘yinlari va qofiya». Bola o‘xshash jaranglaydigan so‘zlarni topishdan zavqlanadi: «to‘p-po‘p», «olma-solma». Bu fonetik idrokning (tovushlarni farqlash qobiliyatining) rivojlanishidir. U bilan qofiyali kichik she’rlar o‘qing yoki so‘z o‘yinlarini o‘ynang. Bu kelajakda o‘qish ko‘nikmasi uchun mustahkam poydevor yaratadi.') WHERE id = '2fa13e97-2173-4c5c-afa8-90f8eaedaa8a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Tugun va ilmoq». Bola endi poyabzal bog‘ichi yoki iplarga qiziqib, ularni bir-biriga o‘rashga harakat qiladi. Unga teshiklari katta munchoqlar yoki maxsus «bog‘lash o‘yinchoqlari» bering. Bu barmoqlarning mayda mushaklarini yozishga va murakkabroq ishlarni bajarishga tayyorlaydi.') WHERE id = '5b2e2766-e73a-4ec2-b386-7bdc27e2bf73';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Xayoliy qo‘rquvlar». Bu davrda bolaning tasavvuri shu qadar kuchli bo‘ladiki, u qorong‘ilikdan yoki xayoliy «mahluqlar»dan qo‘rqishi mumkin. Uning qo‘rquvi ustidan kulmang, «bu yolg‘on» demang. Buning o‘rniga: «Men shu yerdaman, seni himoya qilaman», deb unga hissiy tayanch bo‘ling. Bu uning sizga bo‘lgan ishonchini mustahkamlaydi.') WHERE id = 'b420b26f-d658-40bc-93d9-fcbe9a159330';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Diplomatiyaga urinishlar». Bola endi kelishmovchiliklarni «Sen menga buni ber, men ham senga uni beraman» kabi takliflar bilan hal qilishga urinadi. Bu ijtimoiy intellektning eng yorqin ko‘rsatkichlaridan biridir. Uning bu «muzokarachi» jihatini maqtang va adolatli yechimlarni qo‘llab-quvvatlang.') WHERE id = '4ee1a693-af27-4c8f-b294-06b8239d80b9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida «Miqdorning saqlanishi tajribalari». Bir xil miqdordagi suvni turli shakldagi idishlarga quysangiz, bola hali ham baland idishda suv ko‘proq deb o‘ylashi mumkin. U bilan suv yoki qum o‘yinlarini o‘ynab, miqdor idish shakliga qarab o‘zgarmasligini amalda kashf etishiga imkon yarating.') WHERE id = '13a54bb2-22dc-4956-ad40-80e7f13eda7c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Tez to‘xtash va burilish». Bola endi yugurayotganida sizning «To‘xta!» buyrug‘ingiz bilan darhol to‘xtay yoki keskin burila oladi. Bu mushaklar va asab tizimining hamkorlikda ishlashi natijasidir. U bilan bog‘da «Qizil chiroq, yashil chiroq» o‘yinini o‘ynang; bu uning o‘zini boshqarish (tormozlovchi nazorat) ko‘nikmasini rivojlantiradi.') WHERE id = '29ee5396-69c9-428e-9152-0052da7ababd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Xayoliy o‘yin hamrohi". Ba’zi bolalar bu davrda xayoliy do‘stlar o‘ylab topishi mumkin. Bu bolaning ijodkorligi va hissiy olami boyligidan dalolat beradi. Uni koyimang yoki "bu yolg‘on" demang. Bola bu do‘sti orqali o‘z qo‘rquvlari yoki orzu-istaklarini sinab ko‘radi. Sabr va qiziqish bilan kuzating.') WHERE id = '9ce75a82-fd02-47a8-adbb-96eadd2b8653';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Yetakchilik va bo‘ysunish". Bola endi o‘yinlarda ba’zan qoidalarni o‘zi belgilaydi, ba’zan esa boshqalarning qoidalariga moslashadi. Bu ijtimoiy moslashuvchanlikning asosidir. Uyda u bilan rollarni almashtirib o‘ynang: "Endi sen o‘qituvchi bo‘l, men esa o‘quvchi".') WHERE id = 'd0b4ac9e-9bd0-4b78-83ac-e932a23bb3ff';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish jarayonining rivojlanishida "Sabab-oqibat zanjiri". Bola endi "Agar yomg‘ir yog‘sa, biz parkka bora olmaymiz" kabi mantiqiy fikrlar yuritadi. U bilan voqealarning oqibatlari haqida suhbatlashing. Bu bolada kelajakda o‘z xatti-harakatlari uchun javobgarlikni anglash qobiliyatini (mantiqiy oqibatlarni tushunishni) shakllantiradi.') WHERE id = '44001e8a-e9dc-4edd-96dc-e3baba2b5ba4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlik: "Uch g‘ildirakli velosipedda mustaqil harakatlanish". Bola endi rulni boshqarish bilan bir vaqtda pedallarni bir maromda aylantirishni va kerak bo‘lganda tormozdan foydalanishni biladi. Bunda tananing ham quyi, ham yuqori qismi harakatlari o‘zaro uyg‘unlashadi. Parkda kichik bir "velosiped yo‘lagi"ni belgilab bering.') WHERE id = 'ec14848a-2298-473c-80f2-13859ca28476';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Muloyim iltimoslar". Bola endi istagan narsasiga erishish uchun "mumkinmi?", "iltimos" kabi iboralarni maqsadli ravishda ishlatadi. Sizning muloyim muomalangiz uning uchun eng yaxshi namuna hisoblanadi. U muloyimlik bilan iltimos qilganida, buni albatta ta’kidlang: "Shunday chiroyli iltimos qilganing uchun senga yordam berishdan juda xursandman".') WHERE id = 'c89c5c28-c3bd-46e0-93e1-c16bc60a714b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "O‘zini boshqarish". Bola biror ishni uddalay olmasa (masalan, o‘yinchog‘i qismlarga ajralib ketsa), darhol yig‘lamaydi, sizga qarab yordam so‘raydi yoki yana urinib ko‘radi. Bu hissiy yetuklik sari qo‘yilgan katta qadamdir. Siz uning eng ishonchli tayanchisiz!') WHERE id = 'a0873db2-259d-4791-a8af-c5e115589858';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xushmuomalalik va nozik jihatlar". Bola endi ovoz ohangi va so‘zlarini kim bilan gaplashayotganiga qarab moslashtira boshlaydi (masalan, chaqaloq bilan yumshoqroq, kattalar bilan esa jiddiyroq gaplashadi). Bu sotsiolingvistikaning boshlanishidir. Sizning nutq madaniyatingiz uning uchun eng asosiy va mukammal namunadir.') WHERE id = '3eaa8096-e288-4159-9aa2-8223399dd023';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "O‘zini maqtash". Bola biror ishni uddalaganida: "Qarang, men buni qanday chiroyli bajardim!" deb, sizdan tasdiq kutadi. Uning ichki faxr tuyg‘usiga: "Ha, sen juda ko‘p harakat qilding", deb javob bering. Sizning qo‘llab-quvvatlashingiz uning kelajakdagi o‘ziga bo‘lgan ishonchini shakllantiradi!') WHERE id = '97ef6f09-4fed-4fcd-abbe-7756d8045e1e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni bir vaqtning o‘zida bir nechta belgisiga ko‘ra guruhlay oladi: "ham katta, ham ko‘k o‘yinchoqlar". Bu kognitiv moslashuvchanlik (cognitive flexibility) belgisidir. Unga: "Kel, barcha yumshoq va qizil buyumlarni topamiz", kabi qiziqarli qidiruv topshiriqlarini bering.') WHERE id = '0d946fb4-d148-46c8-80fc-f0a7b324c07f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Erkin yugurish va to‘xtash". Bola endi bor tezlikda yugurayotganda sizning "To‘xta!" buyrug‘ingiz bilan muvozanatini yo‘qotmasdan darhol to‘xtay oladi. Bu uning asab-mushak nazorati qanchalik rivojlanganini ko‘rsatadi. Parkda "Qizil chiroq, yashil chiroq" o‘yini ham qiziqarli, ham foydali mashqdir.') WHERE id = '824aa9f8-040c-4665-a6d8-64a894fd7261';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qarama-qarshi ma’noli so‘zlar". Bola endi "issiq-sovuq", "baland-past", "og‘ir-yengil" kabi qarama-qarshiliklarni nafaqat tushunadi, balki suhbatida ham ishlatadi. Unga qarama-qarshiliklarga oid topishmoqlar ayting: "Fil katta, sichqon-chi?". Bu uning lug‘at boyligi va qiyosiy tafakkurini rivojlantiradi.') WHERE id = '56f799be-0231-4113-94ee-9fbaa18f177f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Inson tasviridagi tafsilotlar". Bola endi chizgan odamiga qo‘llar, oyoqlar va hatto barmoqlarni ham qo‘shishga harakat qiladi. Bu rasmlar uning o‘z tanasi va atrofidagilarni qanday idrok etishining ko‘rsatkichidir. Uning har bir "asarini" kichik bir hikoyadek tinglang.') WHERE id = '0006f22d-7d35-4a7c-abab-057194f6402c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni nafaqat rangiga, balki vazifasiga qarab ham guruhlaydi. "Bular ovqatlanish uchun", "Bular kiyish uchun". U bilan uyda "Qaysi biri ortiqcha?" o‘yinini o‘ynang (masalan, 3 ta meva va 1 ta o‘yinchoq qo‘ying). Bu uning mantiqiy fikrlash qobiliyatini rivojlantiradi.') WHERE id = 'c4b0066e-1d1d-4a2d-b280-39f147e134fe';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlarda "Tezkor manyovr". Bola endi bor tezligida yugurayotganda oldidagi to‘siqni ko‘rib, yiqilmasdan uni aylanib o‘ta oladi. Bu miyadagi "harakatni rejalashtirish" qobiliyatining eng yuqori bosqichidir. Bog‘da uning uchun kichik to‘siqlar yo‘lagini tashkil qiling. Bu uning tana nazorati va chaqqonligini oshiradi.') WHERE id = 'b1971b1f-63a0-40cf-bb46-3ba6bb8689b2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "O‘tmish tafsilotlari". Bola endi "Kecha buvimnikiga borganimizda muzqaymoq yedik" kabi murakkab xotiralarini aytib bera oladi. U bilan o‘tgan kun haqida suhbatlashish epizodik xotirasini mustahkamlaydi. "Yana nimalarni eslaysan?" degan savol bilan hikoyani kengaytiring.') WHERE id = 'f5184b0f-58ef-4b72-af3f-546cec7ec971';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Rasmni ko‘chirish". Bola endi siz chizgan qo‘shuv belgisi (+), doira (O) yoki ayrim harflarni takrorlashga urinadi. Bu ko‘z va qo‘lning muvofiq ishlashidir (vizual-motor integratsiya). Unga rangli qalamlar bering va turli geometrik shakllarni chizishga undang.') WHERE id = '5ee5e247-d8bd-4375-9669-ceda6b1b0a73';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Adolat va qoidalar". Bola endi o‘yinlarda qoidalar buzilishiga munosabat bildiradi: "U navbatni buzdi!". Bu ijtimoiy o‘zlikning rivojlanishidir. Unga qoidalar hamma uchun bir xil ekanini tushuntirish orqali ichki adolat tuyg‘usi va ijtimoiy intizomini mustahkamlaysiz.') WHERE id = 'd1358d5f-b48d-4121-a736-887203ecfc67';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Yetakchilikka urinishlar". Bola endi o‘yin ssenariysini o‘zi tuzishni xohlaydi: "Men shifokor bo‘laman, siz esa bemor". Bunday rolli o‘yinlar orqali u dunyoni anglaydi va qaror qabul qilishni o‘rganadi. Ba’zan uning ssenariysiga amal qiling; bu unda yetakchilik va mas’uliyat tuyg‘usini shakllantiradi.') WHERE id = 'd27742a4-8533-4759-aff4-185d7dbf081f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Maqsadli savollar". U endi shunchaki "bu nima?" deb emas, balki "bu qanday ishlaydi?" deb so‘raydi. Buyumlarning ichki mexanizmi, soatlar va o‘yinchoqlarning g‘ildiraklariga qiziqish bildiradi. Javob berayotganda mantiqiy izchillikni saqlang; bu savollar kelajakdagi ilmiy tafakkurning ilk uchqunlaridir.') WHERE id = 'd2e255d4-c4cb-4992-b207-917bc8c7e987';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Simmetriyaga urinishlar". Bola qog‘ozni buklashga yoki chizgan rasmidagi detallarni (masalan, odamning ikki ko‘zi, ikki qo‘lini) yanada simmetrik joylashtirishga harakat qiladi. Bu uning ko‘rish-fazoviy idroki (visual-spatial awareness) qanchalik rivojlanganini ko‘rsatadi.') WHERE id = 'b4315b1b-9d62-41cc-a063-b3b09c4c589a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Siyosiy" muzokaralar. Bola endi siz bilan "savdolashadi": "Agar men sabzavot yesam, keyin parkda ko‘proq qolsak bo‘ladimi?". Bu uning boshqalarga ijtimoiy ta’sir ko‘rsatish usullarini o‘rganayotganini anglatadi. Bunday "muzokaralarda" halol va izchil bo‘ling; u shu yo‘l orqali chegaralarni o‘rganadi.') WHERE id = '431cd610-a165-475a-8f4f-464196e237c1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Xayoliy ssenariylar". Endi o‘yinlar murakkabroq: "Men sotuvchiman, siz kelib mendan non sotib oling". Bu o‘yinlarda u jamiyatdagi rollarni sinab ko‘radi. Uning ssenariylariga qo‘shilib, bu ijodiy jarayonni rag‘batlantiring.') WHERE id = '81128f46-ecb8-47f0-aa0b-337c398b3230';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Vaqt marosimlari". Bola "kecha", "bugun" va "ertaga" tushunchalarini hali to‘liq farqlay olmasa-da, odatiy tartiblarni biladi. "Ovqatdan keyin park" yoki "Uyqudan oldin ertak". Bu ketma-ketliklar uning ongida vaqt chizig‘ini shakllantiradi.') WHERE id = '5cb6d50d-147c-44f7-91b0-1d67f401019b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirishda "Nozik harakatlar". Bola endi suyuqlik solingan stakanni deyarli to‘kmasdan olib bora yoki tor yo‘lakdan yura oladi. Bu uning ko‘rish-harakat muvofiqlashuvi qanchalik takomillashganini ko‘rsatadi. Uyda unga "kichik yordamchi" vazifalarini berib, bu diqqatini yanada mustahkamlang.') WHERE id = 'efc83589-a712-4c32-9e12-c9ee0f9cee01';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida "Miqdor va raqam mosligi". Bola 5 gacha sanash bilan birga, endi "3" raqamini ko‘rganda 3 ta o‘yinchoqni ajratib qo‘ya oladi. Bu kelajakdagi matematik savodxonlikning poydevoridir. Kundalik yumushlarda unga "menga 4 ta olma ber" kabi topshiriqlar bering.') WHERE id = '0f53eb59-1dad-4d39-84e5-43e97150561c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Ikki oyoqda sakrash". Bola endi to‘siqlar ustidan ikkala oyog‘i bilan bir vaqtda bemalol sakrab o‘ta oladi. Buning uchun tananing pastki qismi kuchli bo‘lishi va harakatlar uyg‘unligi talab etiladi. Uyda polga arqon qo‘yib, uning ustidan sakrash orqali bolangiz bilan "Daryodan o‘tish" o‘yinini o‘ynang.') WHERE id = '080c3ee9-a0ea-4062-9f79-5fba44d2d0e4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hazil va yumor". Bola endi so‘zlarni ataylab noto‘g‘ri aytib yoki kulgili tovushlar chiqarib, sizni kuldirishga harakat qiladi. Bu til me’yorlarini anglashning bir ko‘rinishidir. Uning hazillariga kuling va u bilan birga yumor tuyg‘usini rivojlantiring.') WHERE id = '9fb34927-219f-4b2d-bb9f-dda7da92c634';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Xatosini tan olish". Bola endi biror narsani sindirsa yoki sochib yuborsa, buni darhol yashirishga urinmay, "men qildim" deb ayta oladi. Bunday rostgo‘ylik paytida uni jazolamang; buning o‘rniga birgalikda yig‘ishtirishni taklif qiling. Siz uning uchun ishonchli panohsiz!') WHERE id = 'c4b6f5da-e09e-4e7a-8e0a-9a60747fa087';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni bir vaqtning o‘zida ham rangi, ham shakliga qarab guruhlay oladi. "Bu ham qizil, ham doira shaklida" deb, belgilarni birlashtiradi. Bu kognitiv moslashuvchanlikning muhim ko‘rsatkichidir. Unga turli geometrik shakllardan iborat o‘yinlarni taklif qiling.') WHERE id = '2b4289d9-5b1f-4994-a054-e4727135705c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Dinamik sakrash". Bola endi yugurayotganda yo‘lida uchragan kichik to‘siq ustidan tezligini pasaytirmay sakrab o‘ta oladi. Bu miyada harakatni oldindan rejalashtirish (motor planning) qobiliyati rivojlanayotganini ko‘rsatadi. Istirohat bog‘ida unga kichik to‘siqlar o‘rnatib berishingiz mumkin.') WHERE id = 'ae389307-05d6-4296-90e1-0a21e776e282';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "His-tuyg‘ular lug‘ati". Bola endi shunchaki "yomonman" yoki "yaxshiman" demaydi. U "jahlim chiqdi", "sog‘indim", "xursandman" kabi so‘zlarni o‘rnida ishlatadi. Uning his-tuyg‘ularini tan oling va tasdiqlang: "Sog‘inganing uchun yig‘lashing tabiiy". Bu uning hissiy salomatligi uchun eng mustahkam kafolatdir.') WHERE id = 'e498f733-de85-4e45-8875-b886111a89f8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Uch yarim yoshning eng qizg‘in pallasi! Bola endi go‘daklik davridan butunlay chiqib, "ilk bolalik" bosqichining eng faol davriga kirdi. Hozir u ham jismonan, ham hissiy jihatdan mustaqil bir shaxsdir. Siz shu 1250 kun davomida uning olamida mustahkam ishonch poydevorini yaratdingiz. O‘zingiz bilan faxrlaning!') WHERE id = 'a45a87d4-253c-4fea-ac32-9cea3f5b1168';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi atrofidagi yozuvlarga qiziqa boshlaydi. U do‘kon nomlari yoki kitob sarlavhalarida o‘zi taniydigan harflarni (masalan, ismining bosh harfini) ko‘rib quvonishi mumkin. Bu "dastlabki savodxonlik" bosqichidir. Unga harflarni majburan o‘rgatmang, shunchaki qiziqishini rag‘batlantiring.') WHERE id = '0aedbd42-1452-4a3e-aa54-4adb1ad4a556';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy rivojlanishda "Oyoqlarni navbatma-navbat qo‘yib tushish". Bola endi zinadan tushayotganda har bir pog‘onaga oyoqlarini navbatma-navbat qo‘yib tusha boshlaydi. Bu zinadan chiqishga qaraganda qiyinroq bo‘lib, yaxshi muvozanatni talab qiladi. Siz shunchaki yaqinida turib, unga xavfsizlik hissini bering.') WHERE id = '4a1598de-455f-4bae-a8b3-0f5696c065c6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqdagi "So‘z o‘yinlari va qofiya". Bola ohangdosh so‘zlarni topishdan zavqlanadi: "to‘p-ko‘p", "olma-solma". Bu fonetik idrokning (tovushlarni farqlash qobiliyatining) rivojlanishidir. U bilan qofiyali kichik she’rlar o‘qing yoki so‘z o‘yinlarini o‘ynang. Bu kelajakda o‘qish ko‘nikmasi uchun mustahkam poydevor yaratadi.') WHERE id = '3f6a6fa9-4e7a-4539-93e7-6da1070ea997';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Tugun va halqa". Bola endi poyabzal bog‘ichi yoki iplarga qiziqib, ularni bir-biriga o‘rashga harakat qiladi. Unga teshiklari katta munchoqlar yoki maxsus "ip o‘tkazish o‘yinchoqlari"ni bering. Bu barmoqlarning mayda mushaklarini yozishga va murakkabroq ishlarni bajarishga tayyorlaydi.') WHERE id = 'cf6a8a3d-c742-40b0-a3c1-38fd2db89aec';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi «avval, hozir, keyin» ketma-ketligini murakkab voqealarga ham qo‘llay oladi. «Avval qo‘limni yuvaman, keyin ovqatlanaman, oxirida esa o‘ynayman». Bu uning miyasida faoliyatni rejalashtirish qobiliyati (ijro funksiyasi) rivojlanayotganini ko‘rsatadi. Unga kun davomida kichik rejalar tuzishni topshiring. Bu undagi tartib-intizom hissini mustahkamlaydi.') WHERE id = 'c4e864cd-f8ff-486c-994b-11d240e723ca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda «Uch g‘ildirakli velosipedda manyovr qilish». Bola endi velosiped haydayotganda yo‘lida uchragan to‘siqlarni ko‘rib, rulni o‘z vaqtida bura oladi. Bu pedallarni aylantirish (jismoniy) va yo‘lni kuzatish (vizual) ko‘nikmalarining mukammal uyg‘unligidir.') WHERE id = '63226ba2-0699-459a-be66-a4c9af97d876';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Sabab-oqibat dialoglari». U endi siz qabul qilgan qarorlarning sababini so‘raydi: «Nega men uxlashim kerak?». Javob berayotganda mantiqan tushuntiring: «Chunki tanang dam olishi kerak, shunda ertaga yana kuchga to‘lib o‘ynay olasan». Bunday yondashuv bolada ko‘r-ko‘rona itoatkorlikni emas, balki ongli intizomni shakllantiradi.') WHERE id = 'aba02008-e74d-4081-9df9-4e23bad078b6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Qog‘oz qirqish». Bola endi xavfsiz qaychi bilan qog‘ozni to‘g‘ri chiziq bo‘ylab (yoki oddiy doira shaklida) qirqishga urinadi. Bu qo‘l-ko‘z muvofiqlashuvining eng muhim sinovlaridan biridir. Unga rangli qog‘ozlar va qirqish uchun andozalar berib, mushaklarini mashq qildiring.') WHERE id = 'd337c2b8-8f8a-4037-8a7a-e030f9920b04';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Chegaralar va baham ko‘rish». Bola endi ayrim narsalar hammaga tegishli ekanini (masalan, bog‘dagi arg‘imchoq), boshqalari esa faqat o‘ziniki ekanini tushunadi. Unga «Bu sening o‘yinchog‘ing, uni baham ko‘rish yoki ko‘rmaslik — o‘z tanloving» deb, egalik hissini hurmat qiling. Shaxsiy buyumlariga hurmat bilan munosabatda bo‘lingan bola boshqalarning buyumlarini ham osonroq hurmat qiladi.') WHERE id = '9f384019-50a1-4540-baab-8643e931568a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Murakkab rolli o‘yinlar». Endi o‘yinlarda voqealar rivoji bor: «Sen kasalsan, men shifokorman, senga ukol qilaman». Bu o‘yinlar orqali u haqiqiy hayotdagi qo‘rquvlarini (masalan, shifokordan qo‘rqishini) qayta ishlaydi. Uning ssenariysida faol ishtirok eting.') WHERE id = '9206ce15-0a76-4431-b07b-049bdcbed6b0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Xayoliy qo‘rquvlar". Bu davrda bolaning tasavvuri shu qadar kuchli bo‘ladiki, u qorong‘ilikdan yoki xayoliy "maxluqlar"dan qo‘rqishi mumkin. Uning qo‘rquvi ustidan kulmang, "bu yolg‘on" demang. Buning o‘rniga: "Men shu yerdaman, seni himoya qilaman", deb unga hissiy tayanch bo‘ling. Bu uning sizga bo‘lgan ishonchini yanada mustahkamlaydi.') WHERE id = '09cee55c-899d-468c-bef9-66eb86e868c6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Diplomatiyaga urinishlar". Bola endi kelishmovchiliklarni "Sen menga buni ber, men ham senga uni beraman" kabi takliflar bilan hal qilishga urinadi. Bu ijtimoiy intellektning eng yorqin ko‘rsatkichlaridan biridir. Uning bu "muzokarachi" jihatini olqishlang va adolatli yechimlarni qo‘llab-quvvatlang.') WHERE id = '1f6c2927-0b20-482c-b17f-a447f8fef25d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Miqdorning saqlanishi tajribalari". Bir xil miqdordagi suvni shakli turlicha idishlarga quysangiz, bola hali ham baland idishda suv ko‘proq deb o‘ylashi mumkin. U bilan suv yoki qum o‘yinlarini o‘ynab, miqdor idish shakliga qarab o‘zgarmasligini tajriba orqali kashf etishiga imkon yarating.') WHERE id = '73557d3a-6c9c-4c6a-a67f-c5d4bc801f0d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Tez to‘xtash va Burilish". Bola endi yugurayotganda sizning "To‘xta!" buyrug‘ingiz bilan darhol to‘xtay yoki keskin burila oladi. Bu mushaklar va asab tizimining birgalikdagi faoliyati natijasidir. U bilan bog‘da "Qizil chiroq, Yashil chiroq" o‘yinini o‘ynang; bu uning o‘zini boshqarish ko‘nikmasini rivojlantiradi.') WHERE id = '2c94b5e7-3f3c-4f5a-97ae-e15891e8c592';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xushmuomalalik va Nozik jihatlar". Bola endi ovoz ohangi va so‘zlarini kim bilan gaplashayotganiga qarab moslashtira boshlaydi (masalan, chaqaloq bilan yumshoqroq, kattalar bilan esa jiddiyroq). Bu ijtimoiy tilshunoslikning boshlanishidir. Sizning nutq madaniyatingiz uning uchun eng asosiy va mukammal namunadir.') WHERE id = '708f00c5-3974-4a48-b57b-7ac187203dd5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "O‘zini maqtash". Bola biror ishni uddalaganida "Qarang, men buni qanday chiroyli qildim!" deb sizdan ma’qullashni kutadi. Uning ichki faxr tuyg‘usiga "Ha, sen juda ko‘p harakat qilding", deb javob bering. Sizning qo‘llab-quvvatlashingiz uning kelajakdagi o‘ziga bo‘lgan ishonchining bunyodkoridir!') WHERE id = '1eae35d0-6f20-4979-87f2-c88eacf3b104';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sifatlar boyligi". Bola buyumlarni tasvirlar ekan, shunchaki rangini aytib qolmay, "yumshoq", "tikanli", "silliq" kabi so‘zlardan ham foydalanadi. U bilan "Tegin va top" o‘yinini o‘ynang: ko‘zlarini yumib, buyum teginganda qanday tuyulishini aytishini so‘rang.') WHERE id = '6a7056fe-a7e8-4d7e-91b2-4d5b5277e537';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Belgilarni kashf etish". Bola allaqachon ayrim harflarni (ayniqsa, ismining bosh harfini) yoki raqamlarni ko‘chirib yozishga harakat qiladi. Bu uning vizual belgilar bilan tovush yoki ma’no o‘rtasidagi bog‘liqlikni anglayotganini ko‘rsatadi. Unga qum ustida yoki rangli qalamlar bilan "yozish" mashqlarini bajartiring.') WHERE id = 'b57332a7-c381-44a7-bdb8-aef8d6820036';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish va sabr". Bola endi istagan narsasini olish uchun 5-10 daqiqa kutish kerakligini (masalan, ovqat tayyor bo‘lguncha) xotirjamroq qabul qiladi. Sizning "biroz kut" degan so‘zingizni jazo emas, vaqt talab qiladigan zarurat sifatida tushunadi. Uning sabr qilayotganini ko‘rganingizda, albatta, "Kutganing uchun katta rahmat" deb ruhlantiring.') WHERE id = '7374ce80-a74f-4d7f-bb0f-135ec7c6d431';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Hamdardlik va tasalli". Bola endi sizning charchaganingizni yoki do‘stining xafa bo‘lganini ko‘rsa, unga o‘yinchog‘ini olib kelishi yoki mehr bilan silab qo‘yishi mumkin. Bu uning ichki dunyosi qanchalik boyib borayotganini hamda "men" doirasidan chiqib, "biz" tushunchasiga yo‘nalayotganini ko‘rsatadi.') WHERE id = '62ab0290-ec13-4b50-86f2-b4a69aba6dda';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Hajmni idrok etish". Endi u katta qutiga nechta kichik o‘yinchoq sig‘ishini taxmin qilishga urinadi. Unga turli o‘lchamdagi idishlarni bering va "Sizningcha, bu suv ana u idishga sig‘adimi?" deb so‘rang. Bunday tajribalar kelajakdagi matematik va fizik tushunchalarga poydevor yaratadi.') WHERE id = 'd68476f5-47bc-4622-82c1-31e6c34eeecd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Orqaga yurish". Bola endi orqaga qarab, muvozanatini yo‘qotmasdan ishonch bilan bir necha qadam tashlay oladi. Bu harakat uning o‘z tanasini his qilish qobiliyatini (propriotsepsiyani) mustahkamlaydi. U bilan bog‘da "qisqichbaqalar poygasi" o‘yinini o‘ynab, ham zavqlaning, ham mushaklarini chiniqtiring.') WHERE id = 'ff4d4dbc-967a-48e5-b6f7-ae29e0a5390d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Miqdor va son mosligi". Bola endi 5 gacha sanashni biladi, shuningdek, "3" deyilganda 3 ta buyumni ko‘z bilan ajrata oladi. Unga "Menga 4 ta qoshiq ber" kabi topshiriqlar bering. Bu mavhum sonlar real dunyo bilan ilk bor jiddiy bog‘lanadigan bosqichdir.') WHERE id = 'eaf2d09d-f792-4b9d-ab37-65dbbde32f39';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Ikki oyoqda sakrash". Bola endi to‘siqlar (masalan, yerdagi arqon) ustidan ikki oyog‘i bilan bir vaqtda bemalol sakrab o‘ta oladi. Buning uchun tananing pastki qismi kuchi va harakatlarning uyg‘unligi talab etiladi. U bilan uyda "Daryodan o‘tish" o‘yinini o‘ynab, jismoniy faolligini oshiring.') WHERE id = '9a61025f-abc9-4c98-bf07-819847137992';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hazil va yumor". Bola ataylab so‘zlarni noto‘g‘ri aytish yoki kulgili tovushlar chiqarish orqali sizni kuldirishga harakat qiladi. Bu uning til qoidalarini bilishi va hazil yaratish uchun ularni ataylab buzayotganini ko‘rsatadi. Uning hazillariga kulishingiz o‘ziga bo‘lgan ishonchi va ijtimoiy intellektini rivojlantiradi.') WHERE id = 'b25c4c56-1f97-4223-b20b-689b5e94d1d3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Muvaffaqiyatsizlikni yengish". Bola endi biror ish (masalan, kubiklardan minora qurish) o‘xshamay qolsa, darhol yig‘lamaydi, sizga qarab "Yana urinib ko‘raymi?" deyishi mumkin. Uning natijasini emas, harakatini maqtang: "Juda ko‘p harakat qilding, barakalla!". Siz uning eng katta motivatsiya manbaisiz!') WHERE id = 'f9148bba-3642-4b13-ad48-62db8da7ed80';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni nafaqat tashqi ko‘rinishiga, balki materialiga qarab ham farqlaydi: "Bu plastik, bunisi esa temir". Unga turli tuzilishga ega buyumlarni bering va ular orasidagi farqlarni so‘rang. Bu uning atrofdagi olamni yanada batafsil tahlil qilishiga va jismoniy dunyo haqidagi bilimlarini tizimlashtirishiga yordam beradi.') WHERE id = '80e00e5a-2a93-4c1b-a710-db553822e4ae';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Bir oyoqda muvozanat saqlash". Bola endi bir oyog‘ida 5 soniyadan ko‘proq tura oladi. Bu miyacha va mushaklar muvofiqlashuvining yetilganini ko‘rsatadi. U bilan "laylak o‘yini"ni o‘ynab, kim uzoqroq tura olishini sinab ko‘ring.') WHERE id = '18ab2c20-2470-41d2-b5e5-3121b8d7e0c1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Nazokat va nozik jihatlar". Bola endi ovoz ohangini kim bilan gaplashayotganiga qarab moslashtira boshlaydi (masalan, chaqaloq bilan yumshoqroq, kattalar bilan jiddiyroq gaplashadi). Bu sotsiolingvistikaning boshlanishidir. Sizning nutq madaniyatingiz uning uchun eng asosiy va mukammal namunadir.') WHERE id = '3f691af2-a53f-4e9e-bda8-73c25f9784e5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1280 kunlik ulkan rivojlanish! Bola hozir "ilk bolalik" davrining eng sermahsul pallasida. Endi u o‘z didi, qo‘rquvlari va cheksiz savollariga ega bo‘lgan mustaqil shaxs – mitti bir inson. Siz bu yo‘lni ilm va mehr bilan bosib o‘tdingiz. "Anacan" har doim sizning yoningizda!') WHERE id = 'cb9230b0-c04d-4749-92fd-37201aec8ecd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni faqat bitta emas, balki ikkita xususiyatiga ko‘ra guruhlay oladi: "ham qizil, ham kichkina mashinalar". Bu kognitiv moslashuvchanlikning muhim bosqichidir. Unga turli o‘yinchoqlarni aralashtirib bering va "Barcha yumshoq va ko‘k rangli o‘yinchoqlarni top" deb, miyasini mashq qildiring.') WHERE id = '7f3f7af2-f05b-47b3-bb9a-bf661d551477';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Aniq sakrash". Bola endi turgan joyidan ham balandlikka, ham muayyan nishon tomon (masalan, yerdagi doira ichiga) sakray oladi. Bu uning muvozanatni saqlash va fazodagi masofani hisoblash qobiliyatini ko‘rsatadi. Bog‘dagi "toshdan toshga sakrash" o‘yini uning uchun ajoyib mashqdir.') WHERE id = 'b66ed3bb-08b0-48a9-9270-0f8d21791b6b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt ketma-ketligi". U endi "avval, hozir, keyin" tushunchalarini aniqroq qo‘llaydi: "Avval qo‘limni yuvaman, keyin non yeyman". U bilan kun rejasini muhokama qilish unda tartib-intizom va xavfsizlik hissini shakllantiradi. Uning "hozir nima qilamiz?" degan savollariga doim voqealar ketma-ketligini tushuntirgan holda javob bering.') WHERE id = '4a19271e-0252-465e-a5b6-220dfc833dfa';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Shaklni ko‘chirish: uchburchak va xoch". Bola endi to‘g‘ri chiziqlarni kesishgan holda chizib, xoch (+) hosil qila oladi va uchburchakka o‘xshash shakllarni chizishga urinadi. Bular yozish ko‘nikmasining dastlabki poydevoridir. Unga rangli qalamlar va toza qog‘ozlar berib, bu "geometrik kashfiyotlarini" qo‘llab-quvvatlang.') WHERE id = '5e0bb7b8-fe4c-40a9-87b2-d5ec3dff9314';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish va his-tuyg‘ular". Bola jahli chiqqanda yoki xafa bo‘lganda, ba’zan o‘zini tinchlantirish uchun siz taklif qilgan usullardan (masalan, chuqur nafas olishdan) foydalanishi mumkin. Bu — emotsional intellektning eng muhim hayotiy ko‘nikmalaridan biridir. U tinchlangach, bu harakatini albatta maqtang.') WHERE id = 'cab1e84e-d4d4-48e6-a7cb-8122f2485764';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Jamoaviy o‘yinlar". Bola endi boshqa bir bola bilan umumiy maqsad yo‘lida (masalan, katta qum qal’asini qurish uchun) hamkorlik qila oladi. Bu — "parallel o‘yin"dan "ijtimoiy o‘yin"ga to‘liq o‘tishdir. Uning do‘stlari bilan til topishishga bo‘lgan urinishlarini kuzating va qo‘llab-quvvatlang.') WHERE id = '35da39d6-0c56-4410-8592-5e1cbd4b1e03';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda "Son va miqdor muvofiqligi". Bola 10 gacha sanay oladi, endi esa "3" raqamini ko‘rganda 3 dona o‘yinchoqni ajratib qo‘ya oladi. Bu — matematik tafakkur rivojlanishining eng muhim bosqichidir. Kundalik hayotda "menga 2 dona qoshiq ber" kabi topshiriqlar orqali bu bog‘liqlikni mustahkamlang.') WHERE id = '4397b751-5eff-493f-b5d9-774c99d1ca07';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni ikki qo‘llab ushlash". Bola endi o‘ziga qarab sekin otilgan katta to‘pni ikki qo‘li bilan (ba’zan ko‘ksiga bosib) tutishga harakat qiladi. Bu harakat ham qo‘l-ko‘z muvofiqligini, ham tezkor reaksiya qilishni talab etadi. U bilan yaqin masofadan o‘ynang.') WHERE id = '416872cb-a02b-4d4e-ac74-f040d4ce096b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Odobli iltimoslar". Bola endi istagan narsasiga erishish uchun "mumkinmi?", "iltimos" kabi iboralarni maqsadli ravishda ishlatadi. Sizning odobli muomalangiz uning uchun eng yaxshi namunadir. U odob bilan so‘raganda, buni albatta ta’kidlang: "Shunday chiroyli iltimos qilganing uchun senga yordam berish menga juda yoqadi".') WHERE id = 'eb838920-fe5c-415a-a9ba-0dabdeaffb4e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "Xatosini tan olish". Bola endi biror narsani to‘kib-sochib yuborganda darhol yashirishga urinmaydi, "men qildim" deb ayta oladi. Bunday halollik paytida uni jazolamang; buning o‘rniga birgalikda tozalashni taklif qiling. Bu unda mas’uliyat hissini shakllantiradi. 1290 kunlik yo‘lning har bir lahzasi qadrlidir!') WHERE id = 'fba8e58a-849a-4502-b3b8-829b5d503078';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "agar... unda..." mantiqini to‘liq o‘zlashtirmoqda. "Agar o‘yinchoqni sindirsam, u boshqa ishlamaydi". Bu kelajakni oldindan ko‘ra bilish qobiliyatining boshlanishidir. Unga o‘z harakatlarining oqibatlarini oldindan o‘ylab ko‘rishni taklif qiling: "Sizningcha, stakanni chetga qo‘ysak, nima bo‘ladi?". Bu mas’uliyat hissini shakllantiradi.') WHERE id = '98264d01-8080-47ff-9743-5076f3c1e9fb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Statik muvozanat cho‘qqisi". Bola endi bir oyog‘ida hech narsaga tegmasdan 5-10 soniya tura oladi. Bu ichki quloqdagi muvozanat markazi, shuningdek, bel va oyoq mushaklari mustahkamlanganini ko‘rsatadi. U bilan "qotib qolamiz" o‘yinini o‘ynab, bu ko‘nikmani qiziqarli mashg‘ulotga aylantiring.') WHERE id = 'e5ea1656-41df-45ea-937c-07b3a21bce4f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Murakkab hikoya tuzish". U endi rasmli kitobni ko‘rayotganda shunchaki buyumlarni emas, voqealar o‘rtasidagi bog‘liqlikni ham tushuntiradi: "Quyon qochyapti, chunki tulki kelyapti". Uning tasavvurini rag‘batlantirish uchun "Sizningcha, tulki nima deydi?" kabi savollar bering. Bu uning kognitiv moslashuvchanligini oshiradi.') WHERE id = '991395b5-cce5-4484-973b-52ea93850c86';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Barmoqlarning mustaqil harakati". Bola endi barmoqlarini bir-biriga tekkizish yoki barmoq uchlari bilan mayda munchoqlarni ipga tizish kabi murakkab ishlarni bajara oladi. Bu miyaning ikkala yarimshari o‘zaro muvofiq ishlashini talab qiladi. Unga tugma qadash yoki halqalarni yechish o‘yinlarini taklif qiling.') WHERE id = '7718afa5-181a-4995-b727-92bfdea228d9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Xayoliy qo‘rquvlarni boshqarish". Bu yoshda bolalar ba’zan qorong‘ilikdan yoki "mahluqlardan" qo‘rqishi mumkin. Uning qo‘rquvini inkor etmang, aksincha, "mahluqni quvib yuboradigan sehrli fonar" kabi o‘yinlar o‘ylab toping. Hissiy ko‘magingiz unga bu qo‘rquvlar vaqtinchalik ekanini anglatadi.') WHERE id = '5da5688a-9254-4a8e-94a4-a6cdb8624f11';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Natijaga yo‘naltirilgan hamkorlik". Bola endi boshqa bir do‘sti bilan birgalikda katta minora qurish uchun "g‘ishtchalarni" bo‘lisha oladi. Bu endi shunchaki yonma-yon emas, balki umumiy maqsad yo‘lida o‘ynashdir (hamkorlikdagi o‘yin). Uning bu ijtimoiy diplomatiya qobiliyatini "Juda ajoyib jamoa bo‘ldingiz!" deb maqtang.') WHERE id = '12a2b82c-6975-4312-a2f7-fbbdcf5d9909';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Miqdorning saqlanishi sinovi". Bola hali ham yassilangan plastilin sharchadan kattaroq deb o‘ylashi mumkin. U bilan shunday tajribalar o‘tkazing: sharchani yoying, keyin yana sharcha shakliga keltiring. Bu unga jismoniy olamning o‘zgarmas qonunlarini anglashga yordam beradi.') WHERE id = 'ae824ed0-4f75-4515-b7bf-83483a6c043d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni oyoq bilan boshqarish". Bola endi to‘pni shunchaki tepmaydi, balki uni oyog‘i bilan biroz oldinga surib, olib yurishga (dribling) harakat qiladi. Bu dinamik muvozanat va oyoq-ko‘z muvofiqligini talab qiladi. Bog‘da uning uchun kichik "futbol yo‘lakchasi" yarating va to‘pni nishon tomon olib borishini so‘rang.') WHERE id = '6f891729-8e3d-4c9f-bdb3-588b6de557c3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xushmuomalalik va odob". Bola endi "kechirasiz", "iltimos" so‘zlarini shunchaki yoddan emas, maqsadli ravishda ishlatadi. Boshqalar bilan gaplashayotganda siz qo‘llaydigan ohang uning uchun eng muhim darslikdir. U xushmuomala bo‘lganida, bu xatti-harakat atrofdagilarda qanday ijobiy taassurot uyg‘otishini his qilishiga yordam bering.') WHERE id = '8553307b-a429-4fdd-a8d5-b4776f0fb3d5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1300 kunlik ajoyib yo‘l! Bola endi chaqaloqlik odatlarini butunlay ortda qoldirib, maktabgacha davrning eng faol bosqichiga o‘tmoqda. U endi o‘zini alohida "men" sifatida anglaydi va dunyoni o‘zgartirishga tayyor. Siz shu 1300 kun davomida uning eng ishonchli yo‘lko‘rsatuvchisi bo‘ldingiz. Mehringiz va sabringiz uchun o‘zingizga minnatdorlik bildiring!') WHERE id = '7883dc4b-dac2-42dc-8a35-51e8d5b489b1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '44-oyga xush kelibsiz! Bola endi "men katta bo‘ldim" degan tuyg‘uni chuqur his qilmoqda. Bu davrda unga kiyimini o‘zi tanlash yoki dasturxon yozish kabi kichik mas’uliyatlarni bering. Bu uning mustaqil bo‘lish istagini ijobiy tomonga yo‘naltiradi va o‘ziga bo‘lgan ishonchini oshiradi.') WHERE id = 'aad2ad75-5a11-4a2d-9c7c-2bc5d48aa312';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Ravon manyovr qilish". Bola endi bor tezlikda yugurayotib, oldidagi to‘siqni ko‘rsa, yiqilmasdan uni aylanib o‘ta oladi. Bu miyadagi "harakatni rejalashtirish" ko‘nikmasining eng yuqori bosqichidir. Bog‘da uning uchun kichik to‘siqlar yo‘lagini yarating. Bu uning tanani boshqarish qobiliyatini ham, chaqqonligini ham oshiradi.') WHERE id = '5ff72db7-e0be-4353-a758-f27d398fc0b7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Savollar sifati». Endi u shunchaki «bu nima?» deb emas, «nega bunday?» deb so‘raydi. U hodisalarning ichki mantiqini tushunishga harakat qilmoqda. Javob berayotganda uning tasavvurini ham ishga soling: «Seningcha, nega yomg‘ir yog‘adi?». Bu uning ijodiy va ilmiy tafakkurini rag‘batlantiradi.') WHERE id = '104d37cc-f454-4cee-bc62-45a7dd638317';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Shakldan nusxa chizish: kvadrat va uchburchak». Bola endi burchakli shakllarni chizishga urinmoqda. Bu doira chizishdan qiyinroq, chunki qalamni muayyan nuqtada to‘xtatib, yo‘nalishini o‘zgartirish talab etiladi. Unga burchakli shakllarni birlashtirib, «uy» yoki «mashina» chizishni ko‘rsating.') WHERE id = '72c3574b-2a9a-4755-8727-8d01b439e56e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«Adolat va qoidalar». Bola endi o‘yinlarda qoidalar buzilishiga keskin munosabat bildiradi: «U navbatni buzdi!». Bu ijtimoiy o‘zlik va axloqiy tushunchalar rivojlanayotganidan dalolat beradi. Unga qoidalar hamma uchun bir xil ekanini tushuntirish orqali ichki adolat hissi va ijtimoiy intizomini mustahkamlaysiz.') WHERE id = '6e14d59c-92a1-4b52-9746-19ec45e3a240';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Murosaga kelish urinishlari». Bola nizolarni «Sen menga buni ber, men esa senga anavi narsani beraman» kabi takliflar bilan hal qilishga urinmoqda. Bu ijtimoiy intellektning eng yorqin ko‘rsatkichlaridan biridir. Uning bu «muzokarachi» jihatini maqtang va adolatli yechimlarni qo‘llab-quvvatlang.') WHERE id = '1bc59678-d965-4c53-ad57-e91ac3a6bece';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda «Miqdorni bir qarashda aniqlash (subitizatsiya)». Bola endi 3 yoki 4 ta buyumni sanamasdan, shunchaki qarab, nechta ekanini anglay oladi. Unga turli miqdordagi nuqtalar tushirilgan kartalarni ko‘rsating va darhol nechta ekanini aytishini so‘rang. Bu kelajakda tezkor matematik hisoblash ko‘nikmasining poydevori bo‘ladi.') WHERE id = '9268aa12-9e8f-498d-a13c-fd38e4e68957';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «To‘pni yelka ustidan otish». Bola endi to‘pni shunchaki yerga tashlamaydi, balki uni yelka balandligidan uzoqqa va muayyan nishon tomon ota oladi. Bu butun tana harakatlarini muvofiqlashtirish va kuchni boshqarishni talab qiladi. U bilan bog‘da nishonga to‘p otish o‘yinlarini o‘ynang.') WHERE id = 'dbdc7993-c5ce-4ff8-a2f5-69daf1b98fea';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Hazil va yumorning chuqurlashuvi". Bola endi so‘zlarning ma’nosini o‘zgartirib, hazil qiladi. Masalan, sizni "Bobo" deb atab kulishi mumkin. Bu uning til me’yorlarini yaxshi bilishi va hazil yaratish uchun ularni ataylab buzishini ko‘rsatadi. U bilan birga zavqlaning.') WHERE id = '8c83e3c0-4591-49c2-a059-525f584c28d3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "Sabr sinovi". Bola endi xohlagan narsasini olish uchun bir necha daqiqa (masalan, siz telefonda gaplashayotganingizda) jim kutib tura oladi. Bu uning o‘zini boshqarish qobiliyati mustahkamlanayotganini ko‘rsatadi. Kutganidan keyin unga albatta "Meni kutganing uchun katta rahmat" deb minnatdorlik bildiring.') WHERE id = '75df2db1-9a5a-4048-99dc-80b484b6d396';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi atrofdagi logotiplar va yozuvlarni taniy oladi. Masalan, sevimli muzqaymoq brendi yoki do‘kon logotipini ko‘rganda uning nomini aytadi. Bu ramziy tafakkurning rivojlanishidir. Unga turli yo‘l belgilari yoki oddiy piktogrammalarni ko‘rsatib, ularning ma’nosini so‘rang. Bu kelajakdagi o‘qish ko‘nikmasining vizual poydevoridir.') WHERE id = 'bb1f5dc6-7300-4f63-9d44-40f2e54dfb71';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Orqaga sakrash". Bola endi orqaga qarab kichik sakrashlar qila oladi. Bu muvozanatni saqlash va makonda o‘z tanasini boshqarish qobiliyatining yangi bosqichidir. U bilan "Qisqichbaqa va qurbaqa" poygasini o‘ynab, faolligini rag‘batlantiring.') WHERE id = '2c74b1f3-a8fd-4086-88da-377857855b8c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qarama-qarshiliklarni taqqoslash". Bola endi "eng katta", "kichikroq", "juda og‘ir" kabi daraja va taqqoslashlarni gapda o‘rinli qo‘llaydi. Unga 3 xil o‘lchamdagi o‘yinchoq bering va "Qaysi biri eng katta?" deb so‘rang. Bu uning lug‘at boyligi miqdor va sifat jihatidan ortib borayotganini ko‘rsatadi.') WHERE id = 'f9bd7f70-01bc-46e8-8391-e80ede82d1cc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Inson tasviridagi mutanosiblik". Bola endi odam rasmini chizayotganda tana a’zolarini mantiqan to‘g‘riroq joylashtiradi; ko‘zlar yuzning o‘rtasida, qo‘llar esa tananing yon tomonlarida bo‘ladi. Bu rasmlar uning o‘z tanasi haqidagi tasavvuri (body image) rivojlanayotganini aks ettiradi.') WHERE id = 'b857a3b6-e216-49cf-a9c0-e7adabf3fdba';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini ta’riflash". Bola endi o‘zini tavsiflay oladi: "Men sarg‘ish sochliman", "Men tez yuguraman". Bu uning shaxsiy o‘zligi mustahkamlanayotganini ko‘rsatadi. Unga "Sen yana nimalarni yoqtirasan?" kabi savollar berib, o‘zini anglashiga yordam bering. Uning o‘zi haqida ijobiy fikrda bo‘lishi kelajakdagi o‘ziga ishonchining poydevoridir.') WHERE id = '9ca9132e-1f05-4086-b977-373ac1739718';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Diplomatiya va muzokara". Bola endi biror narsaga erishish uchun "Agar sen menga buni bersang, men ham senga buni beraman" kabi takliflar qiladi. Bu ijtimoiy intellekt va muammolarni hal qilish ko‘nikmasining yuqori bosqichidir. Uning adolatli "savdolashish" urinishlarini qo‘llab-quvvatlang va ijobiy qabul qiling.') WHERE id = '68e14866-1913-4e48-a5b0-15a89d136783';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Vaqtni kundalik odatlar orqali anglash". Bola "Ertalab uyg‘onganda", "Kechqurun uxlashga yotganda" kabi iboralar yordamida kunning vaqtlarini bir-biridan ajratadi. U bilan ertangi rejalarni "avval, keyin, oxirida" tartibida muhokama qiling. Bu unda xavfsizlik va tartib hissini shakllantiradi.') WHERE id = 'fc45f60c-b22c-4712-b519-43e1ec159d0a';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni oyoq bilan boshqarish". Bola endi to‘pni shunchaki tepmaydi, balki uni oyog‘i bilan biroz oldinga surib, harakatlantirishga (dribling qilishga) urinadi. Bu dinamik muvozanat va diqqatni talab qiladi. U uchun bog‘da kichik "futbol yo‘lagi" yarating va to‘pni belgilangan nishon tomon olib borishini so‘rang.') WHERE id = '27b3b770-0010-4e27-a15b-7e39df48e572';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xushmuomalalik va ijtimoiy odob". Bola endi "kechirasiz", "mumkinmi?" kabi iboralarni vaziyatga mos ravishda ishlatadi. Sizning boshqalar bilan muloqotingiz uning uchun eng asosiy namunadir. U xushmuomala bo‘lganida, bu xatti-harakat boshqalarda qanday yoqimli taassurot uyg‘otganini his qilishiga yordam bering: "Shunday xushmuomala bo‘lganing uchun hamma senga tabassum qilyapti".') WHERE id = 'eddeff81-68cf-4451-8b49-9db4335c7821';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Muvaffaqiyatsizlikni qabul qilish". Bola endi biror ishni uddalay olmaganida (masalan, pazlni yig‘a olmaganida) darhol jahli chiqmaydi, balki yana urinib ko‘radi yoki yordam so‘raydi. Uning natijasini emas, sa’y-harakatini maqtang: "Sen juda ko‘p harakat qilding va taslim bo‘lmading, barakalla!".') WHERE id = '3c009bb9-dfc9-4682-a20a-9afa3ba74f26';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni bir vaqtning o‘zida ham rangi, ham materialiga qarab guruhlay oladi: "Bu ham ko‘k, ham yumshoq". Bu kognitiv moslashuvchanlikning muhim ko‘rsatkichidir. Unga turli teksturadagi buyumlar (yog‘och, mato, plastmassa) bilan o‘ynaladigan o‘yinlarni taklif qiling.') WHERE id = 'b98d1c0b-fdd1-4aeb-a1f1-d636c58ba6b7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatda "Dinamik sakrash". Bola endi yugurayotganda yo‘lida uchragan kichik to‘siq ustidan tezligini pasaytirmasdan sakrab o‘ta oladi. Bu miyada harakatni oldindan rejalashtirish (motor planning) qobiliyati rivojlanayotganini ko‘rsatadi. Bog‘da uning uchun kichik to‘siqlar yasashingiz mumkin.') WHERE id = '60d3fdb2-caa2-4bc5-bc84-452616921b80';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt marosimlari". Bola "kecha", "bugun" va "ertaga" tushunchalarini hali to‘liq farqlay olmasa-da, kundalik odatlarni biladi. "Ovqatdan keyin bog‘ga boramiz" yoki "Uyqudan oldin ertak". Bu ketma-ketliklar uning ongida vaqt tushunchasini shakllantiradi.') WHERE id = '95122e91-e077-4e38-a3b4-27a4e9e756f1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Simmetriyaga urinishlar". Bola qog‘ozni buklashga yoki chizgan rasmlaridagi detallarni (masalan, odamning ikki ko‘zi, ikki qo‘li) simmetrikroq joylashtirishga harakat qiladi. Bu uning ko‘rish-fazoviy idroki qanchalik rivojlanganini ko‘rsatadi.') WHERE id = '27b05f17-57a4-4b79-9091-f702b81309dd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Siyosiy" muzokaralar. Bola endi siz bilan "savdolashadi": "Agar men sabzavot yesam, keyin bog‘da uzoqroq qolsak bo‘ladimi?". Bu uning ijtimoiy ta’sir mexanizmlarini o‘rganayotganini ko‘rsatadi. Bunday "muzokaralarda" halol va izchil bo‘ling; u chegaralarni shu yo‘l bilan o‘rganadi.') WHERE id = '0875811d-7343-4ba3-a29e-c235cba78b04';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Xayoliy ssenariylar". Endi o‘yinlar yanada murakkablashadi: "Men sotuvchiman, siz kelib mendan non sotib oling". Bu o‘yinlarda bola jamiyatdagi rollarni sinab ko‘radi. Uning ssenariylariga moslashib, ushbu ijodiy jarayonni rag‘batlantiring.') WHERE id = 'c35d44af-1b5b-4a3a-b44c-143278463e37';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojida «Buyumlarning vazifasi». Bola endi buyumlarni faqat ko‘rinishiga qarab emas, balki vazifasiga ko‘ra ham guruhlaydi. «Bular kesuvchi asboblar», «Bular esa yozish uchun mo‘ljallangan vositalar». Bu uning miyasidagi ma’lumotlar bazasi yanada tizimli va funksional bo‘lib borayotganini ko‘rsatadi.') WHERE id = '52b43fec-3fc9-4135-bc89-1ca56d2c89c9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirishda «Nozik harakatlar». Bola endi suyuqlik to‘ldirilgan stakanni deyarli to‘kmasdan olib bora oladi yoki tor yo‘lakdan yura oladi. Bu uning ko‘rish va harakat muvofiqligi qanchalik takomillashganini ko‘rsatadi. Uyda unga «kichik yordamchi» vazifalarini berib, bu diqqatini yanada mustahkamlang.') WHERE id = 'b2a95188-79e5-4c80-963a-2302704140ca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Tuyg‘ular lug‘ati». Bola endi shunchaki «yomonman» yoki «yaxshiman» demaydi. U «jahlim chiqdi», «zerikdim», «xursandman» kabi so‘zlarni o‘rnida ishlatadi. Uning his-tuyg‘ularini tan oling va tasdiqlang: «Zerikkaningiz uchun yig‘lashingiz tabiiy». Bu uning hissiy salomatligining eng katta kafolatidir.') WHERE id = '8d118e2f-9e48-4f84-bdd9-4688744f285c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1330 kunlik cho‘qqi! Bola endi rasman «ilk bolalik» bosqichining eng faol va idrokli davrida. U hozir ham jismonan, ham hissiy jihatdan to‘laqonli shaxsdir. Siz bu yo‘lni ilm va mehr bilan bosib o‘tdingiz. «Anacan» har doim yoningizda!') WHERE id = 'ee7d4f4f-acca-4792-810c-9ebdc339da81';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '45-oyga xush kelibsiz! Bola endi atrofidagi yozuvlardan tanish harflarni izlay boshlaydi. Ayniqsa, ismining bosh harfini hamma joyda taniy olishi mumkin. Bu o‘qish ko‘nikmasi shakllanishining dastlabki bosqichidir. Unga harflarni majburan o‘rgatmang, shunchaki ko‘rgan harflarining nomi va tovushini o‘yin orqali ayting.') WHERE id = 'c1854d46-26a3-452c-9eb7-697ec5a92d6c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatda «Uch g‘ildirakli velosipedni to‘liq boshqarish». Bola endi pedal bosishni to‘xtatmay, rulni burib, tor burilishlardan o‘ta oladi. Bu ham tananing pastki qismi kuchi, ham ko‘rish-fazoviy muvofiqlikning eng yuqori darajasidir.') WHERE id = 'ee3c0b22-95f2-4059-93bc-287ff0eb00cf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Bashorat qilish ko‘nikmasi". Ertak o‘qiyotganda bola endi "Seningcha, keyin nima bo‘ladi?" degan savolga mantiqli javoblar bera oladi. Bu uning voqealar orasidagi yashirin bog‘liqliklarni tushuna boshlaganini ko‘rsatadi. "Sen bo‘lganingda nima qilarding?" degan savol bilan uning tasavvurini rivojlantiring.') WHERE id = '8651dfdb-b093-4f7c-b25e-9846200e12c4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qog‘ozni kesish: Shakl qirqib olish". Bola endi xavfsiz qaychi yordamida oddiy doira yoki kvadratni chetlari bo‘ylab qirqib olishga harakat qiladi. Bu qo‘lning mayda mushaklarini yuqori darajada boshqarishni talab etadi.') WHERE id = '9727b126-febe-431d-a82a-db6a6416efff';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Adolat va qoidalar posboni". Bola endi nafaqat o‘zi, balki boshqalar qoidani buzganida ham bunga munosabat bildiradi: "Dada, siz navbatni buzdingiz!". Bu ichki vijdon va ijtimoiy adolat hissi shakllanayotganidan dalolat beradi. Unga nima uchun qoidalar hamma uchun bir xil ekanini tushuntiring.') WHERE id = 'a0bdfa22-2c16-417c-bc41-62353716c069';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Diplomatik yechimlar". Kelishmovchilik paytida bola endi "Kel, navbat bilan o‘ynaymiz" kabi takliflarni bera oladi. Bu ijtimoiy intellektning eng yorqin ko‘rsatkichlaridan biridir. Uning bunday tinchliksevar yondashuvini albatta "Juda yaxshi yechim topding" deb maqtang.') WHERE id = '1c1d5af4-d669-4eee-8938-97dcf06fd2d8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Kognitiv rivojlanishda "Miqdor saqlanishiga oid tajribalar". U bilan qum yoki suv o‘ynang. Bir xil miqdordagi suvni turli idishlarga quying. U hali ham baland idishda suv ko‘proq deb o‘ylashi mumkin. Bunday tajribalar uning miyasini jismoniy voqelikni anglashga tayyorlaydi.') WHERE id = '32e16fdb-1a45-43a1-8bb5-fea77db311d2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni yelka ustidan otish". Bola endi to‘pni nishon tomon kuchliroq va aniqroq ota oladi. Bu qo‘l va yelka mushaklarining muvofiqlashgan faoliyatidir. U bilan bog‘da kichik "to‘pni savatga tashlash" o‘yinlarini o‘ynang. Bu ham maroqli, ham tanani boshqarish qobiliyatini mustahkamlaydi.') WHERE id = '5eff2db7-b37a-4ebb-9335-292fea3a6331';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Mavhum tushunchalar: O‘ng va chap". Bola "o‘ng qo‘l" va "chap oyoq" tushunchalarini o‘rganishga qiziqish bildirmoqda. Hozircha ularni adashtirishi mumkin, bu normal holat. Unga paypoq kiydirayotganda, "Endi o‘ng oyog‘ingni uzat" deb, bu tushunchalarni kundalik hayotga kiriting.') WHERE id = 'dcd74d19-3308-4446-89b6-05aecfc53aed';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy barqarorlik: "O‘zini boshqarish (Self-regulation)". Bolaning biror ishi o‘xshamasa, endi darhol jahli chiqmaydi, sizga qarab: "Yana bir bor urinib ko‘raymi?" deya oladi. Bu hissiy yetuklikning eng muhim bosqichlaridan biridir. Uni natijasi uchun emas, balki ko‘rsatgan sabri va sa’y-harakati uchun maqtang. Siz ajoyib onasiz!') WHERE id = 'b36ad394-fd9c-40bc-963f-954848c1c743';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "avval, hozir, keyin" ketma-ketligini murakkab faoliyatlarga ham qo‘llay oladi. "Avval o‘yinchoqlarni yig‘aman, keyin qo‘limni yuvib, ovqatlanaman". Bu miyada strategik rejalashtirish (executive function) ko‘nikmasi rivojlanayotganidan dalolat beradi. Unga kun rejasini tuzishda faol ishtirok etish imkonini bering; bu uning ichki intizomini mustahkamlaydi.') WHERE id = 'a41e3209-8dbf-44ce-98bb-5a5b64b4268c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlarda "Statik va dinamik muvozanat". Bola endi bir oyog‘ida 5-10 soniya tura oladi yoki tor bordyur ustida muvozanatini yo‘qotmay yura oladi. Bu vestibulyar tizimning to‘liq yetilganini ko‘rsatadi. U bilan "Dorboz" o‘yinini o‘ynashning ayni vaqti.') WHERE id = '696cb686-c625-440d-93fe-4e04eee0ca77';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sabab-oqibat zanjiri". U endi sizning taqiqlaringizga mantiqiy izoh izlaydi: "Nega hozir shirinlik yeyish mumkin emas?". Javob berayotganda, "Chunki men shunday dedim" deyish o‘rniga, "Chunki hozir shirinlik yesang, qorning to‘yib qoladi va foydali tushlikni yeya olmaysan" kabi izohlar bering. Bu uning mantiqiy tafakkurini charxlaydi.') WHERE id = '1bdc4f44-d5e0-42ee-9d67-dc1beca39c22';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Inson tasviridagi tafsilotlar". Bola endi odam rasmini chizayotganda barmoqlar, kipriklar, tugmalar yoki bosh kiyim kabi mayda tafsilotlarni ham qo‘shadi. Bu rasmlar uning atrofdagi olamni qanchalik diqqat bilan kuzatishi va qo‘l-ko‘z muvofiqlashuvi rivojlanganining natijasidir.') WHERE id = 'dd86234a-f54a-432f-bcb2-f0fc25c1a9f2';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Xayoliy qo‘rquvlar va jasorat". Bu yoshda tasavvur shu qadar kuchli bo‘ladiki, bola qorong‘ida "maxluqlarni" ko‘rishi mumkin. Uning qo‘rquvini inkor etmang, birgalikda "qo‘rquvni haydovchi" odatlarni (masalan, sehrli yostiq yoki fonar) yarating. Bu uning o‘zini hissiy jihatdan xavfsiz his qilishini kuchaytiradi.') WHERE id = '30d373fa-79f5-41e2-b2ee-ce7f265298c1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Yetakchilik va hamkorlik". Bola endi o‘yin ssenariysini o‘zi tuzadi va do‘stlariga rollarni taqsimlaydi: "Sen mushuk bo‘l, men esa sening egang bo‘laman". Bu uning ijtimoiy ierarxiya va rollarni anglayotganini ko‘rsatadi. Ba’zan uning ssenariysiga qo‘shilib, ijodiy yetakchilik qilishga bo‘lgan bu urinishini qo‘llab-quvvatlang.') WHERE id = 'ec5ff997-3ed4-4645-be9c-2d361314cc2f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Miqdor va son ramzi". Bola endi "4" raqami 4 ta olmani, "1" raqami esa bitta buyumni anglatishini to‘liq tushunadi. Unga "Menga 5 ta qalam ber" kabi topshiriqlar berib, mavhum sonlar bilan haqiqiy miqdor o‘rtasidagi bog‘liqlikni mustahkamlang.') WHERE id = 'c8eb9b80-1c81-4e02-86f3-e8fdf448ffb9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni ikki qo‘l bilan tutish". Bola endi unga tomon sekin otilgan to‘pni qo‘llarini bukib, kaftlarini ko‘kragi oldida birlashtirgan holda (ba’zan esa to‘g‘ridan-to‘g‘ri kaftlari bilan) tuta boshlaydi. Bu reaksiya tezligi va ko‘z bilan kuzatish ko‘nikmasi rivojlanayotganini ko‘rsatadi. U bilan yaqin masofadan yumshoq to‘p yordamida mashq qiling.') WHERE id = 'e3704303-d02a-47ea-9a47-f1164a3046e0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqt tushunchalari". Bola "kecha", "bugun" va "ertaga" tushunchalarini endi o‘rinliroq qo‘llaydi. "Ertaga buvimnikiga boraman" deganida, u vaqt ketma-ketligini xayolida gavdalantiradi. Kun oxirida u bilan ertangi rejalarni "ertak" kabi so‘zlab, uyquga keting. Bu uning kelasi zamon haqidagi tushunchasini ham shakllantiradi.') WHERE id = '58a4bd7b-b429-45cf-92c2-f503f4e7d474';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1350 kunlik ulkan rivojlanish! Bola endi rasman "go‘daklik" sohilidan uzoqlashib, "ilk bolalik" okeanida erkin suzmoqda. Uning o‘ziga xosligi, hazil tuyg‘usi va fe’l-atvori endi siz uchun eng katta qiziqish manbaidir. Siz shu 1350 kun davomida uning dunyosidagi eng ishonchli qo‘rg‘on bo‘ldingiz. Barakalla sizga, Ona!') WHERE id = '647eb338-5057-4cf4-a29d-e4970189abc1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi ijtimoiy o‘yinlarda "men" va "biz" o‘rtasidagi farqni qo‘llay oladi. Agar u "Kel, birga uy quramiz: sen g‘ishtlarni olib kel, men esa teraman" kabi vazifalarni taqsimlasa, bu hamkorlik qobiliyati juda yaxshi rivojlanganini ko‘rsatadi. Unga guruh ishlarida yetakchi yoki yordamchi rolini sinab ko‘rish imkonini yarating. Bu uning kelajakdagi jamoada ishlash ko‘nikmalarini shakllantiradi.') WHERE id = '56b16411-749d-48ab-a1c9-aec6ee4d3f2b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatlarda "Tez yugurish va keskin burilish". Bola endi yugurayotganda muvozanatini yo‘qotmay, keskin burila oladi. Bu uning tana holatini sezish qobiliyati (propriosepsiya) va mushaklarni boshqarishi qanchalik takomillashganini ko‘rsatadi. Parkdagi "Zigzag yugurish" o‘yini u uchun ajoyib mashqdir.') WHERE id = '3acf9991-6e18-469c-8243-5255e3b47e73';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Nega" savollarining mantiqiy zanjiri. Endi u sizning javobingiz bilan kifoyalanmay, "Unda nega u bunday?" deb ketma-ket savollar beradi. Javob berayotganda uni ham o‘ylashga undang: "Seningcha, quyosh qayerga ketadi?". Bu uning tasavvurini ilmiy qiziqish bilan uyg‘unlashtiradi. Uning qiziqish olamini kichik ensiklopediyalar yordamida kengaytiring.') WHERE id = '09e33fb1-46b4-4ad6-a2f6-bb3ee2d41636';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qog‘oz buklash (origami asoslari)". Bola endi qog‘ozni qoq o‘rtasidan buklashga va burchaklarini birlashtirishga urinadi. Bu harakat qo‘l mushaklarini mustahkamlash bilan birga, geometrik simmetriya tushunchasini ham uning ongiga singdiradi. Unga rangli qog‘ozlardan oddiy shakllar yasashni o‘rgating.') WHERE id = 'b9689a6f-2bcb-421e-acea-f03b1095905f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish va his-tuyg‘ularni ifodalash". Bola jahli chiqqanda shunchaki baqirmaydi, balki "Hozir juda jahlim chiqdi!" deb his-tuyg‘usini so‘z bilan ifodalay oladi. Uning his-tuyg‘ularini tan oling va tasdiqlang: "Seni tushunaman, jahling chiqishi tabiiy". Bu uning hissiy yetukligini oshiradi.') WHERE id = '7a0c1e64-9ecb-47f6-83f4-aa32390210cd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Diplomatik muzokaralar". Bola biror narsaga erishish uchun "Agar sen menga bu mashinani bersang, men ham senga shokolad beraman" kabi "savdolashadi". Bu ijtimoiy ta’sir ko‘rsatish va diplomatiya ko‘nikmalarining boshlanishidir. U bilan adolatli "kelishuv" qoidalarini o‘yin shaklida sinab ko‘ring.') WHERE id = '2dd70517-4599-4775-b1e7-2b11f39244da';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Miqdorning saqlanishi (Hajm)" tushunchasi. U bilan oshxonada tajriba o‘tkazing: bir xil miqdordagi suvni bittasi keng, ikkinchisi esa uzun va ingichka bo‘lgan ikkita idishga quying. U hali ham uzun idishda suv ko‘proq deb aytishi mumkin. Bunday tajribalar uning vizual idroki va mantiqiy tafakkuri o‘rtasidagi ziddiyatni anglash qobiliyatini rivojlantiradi.') WHERE id = 'eb9fac33-252a-4cde-bb98-95be1aaf831f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni oyoq bilan boshqarish". Bola endi to‘pni shunchaki tepibgina qolmay, uni oyog‘i bilan biroz oldinga surib, harakatlantirishga (dribling) urinadi. Bu dinamik muvozanat va diqqatni talab qiladi. U bilan bog‘da kichik "futbol yo‘lakchasi" yarating va to‘pni belgilangan nishon tomon olib borishini so‘rang.') WHERE id = 'f40621db-c962-42bd-85b1-429800b2b4ef';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xushmuomalalik va ijtimoiy me’yorlar". Bola endi "kechirasiz", "mumkinmi?" kabi iboralarni shunchaki yoddan emas, vaziyatga mos ravishda ishlatadi. Sizning boshqalar bilan muloqotingiz uning uchun eng asosiy namuna hisoblanadi. U xushmuomala bo‘lganida, bu xatti-harakat atrofdagilarda qanday yoqimli taassurot uyg‘otganini unga albatta his qildiring.') WHERE id = '3804d992-5f37-4fb4-bfb6-18ad143039e9';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1360 kunlik ulkan sayohat! Bola allaqachon 45 oyni ortda qoldirdi. Endi u o‘z fikrlari, hazillari va orzulariga ega bo‘lgan mitti bir shaxsdir. Siz shu 1360 kun davomida uning dunyosini bunyod etdingiz. Uning o‘ziga ishonch bilan boqishida sizning mehringiz izi bor. Siz ajoyib onasiz!') WHERE id = '333176ec-4bc6-4177-b76d-921996ec28d4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni nafaqat tashqi ko‘rinishiga, balki qanday materialdan yasalganiga qarab ham farqlaydi: "Bu plastik, bunisi esa temir". Unga turli tuzilishga ega buyumlarni bering va ular orasidagi farqlarni so‘rang. Bu uning atrofdagi olamni yanada batafsil tahlil qilishi va moddiy dunyo haqidagi bilimlarini tizimlashtirishiga yordam beradi.') WHERE id = '657efc38-ed5e-4e3a-9572-7dbdb9184154';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Statik muvozanat cho‘qqisi". Bola endi bir oyog‘ida hech narsaga tegmasdan 5-10 soniya tura oladi. Bu ichki quloqdagi muvozanat markazi, shuningdek, bel va oyoq mushaklari mustahkamlanganini ko‘rsatadi. U bilan "qotib qoldik" o‘yinini o‘ynab, bu ko‘nikmani qiziqarli mashg‘ulotga aylantiring.') WHERE id = '2f039b11-24db-4020-90d7-1c5f7a16c171';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Xushmuomalalik va odob". Bola endi "kechirasiz", "iltimos" so‘zlarini shunchaki yoddan emas, maqsadli ravishda ishlatadi. Sizning boshqalar bilan gaplashganda ishlatadigan ohangingiz uning uchun eng muhim namuna hisoblanadi. U xushmuomala bo‘lganida, bu xatti-harakat atrofdagilarga qanday ijobiy ta’sir ko‘rsatishini his qilishiga yordam bering.') WHERE id = '81b527f9-bc6c-4fa6-a384-bfac0dbe1b99';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1370 kunlik ajoyib yo‘l! Bola endi chaqaloqlik odatlarini butunlay ortda qoldirib, maktabgacha bo‘lgan davrning eng faol bosqichiga o‘tmoqda. U endi o‘zini alohida "men" sifatida anglaydi va dunyoni o‘zgartirishga tayyor. Siz shu 1370 kun davomida uning eng ishonchli yo‘lko‘rsatuvchisi bo‘ldingiz. Mehringiz va sabringiz uchun o‘zingizga minnatdorlik bildiring!') WHERE id = '7f1e62d7-6f8c-466a-917b-3acd9000a197';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi atrofidagi yozuvlardan tanish harflarni (ayniqsa, ismining bosh harfini) izlay boshlaydi. Bu "vizual o‘qish" bosqichidir. Unga harflarni majburan o‘rgatmang, shunchaki ko‘rgan belgisi qaysi tovushni ifodalashini qiziqarli kashfiyot sifatida tushuntiring.') WHERE id = '395ee563-1ee4-4a29-8a28-f145933f9a6e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Dinamik manyovr". Bola endi yugurayotganda oldidagi to‘siqni osongina chetlab o‘tishi yoki yo‘nalishini birdan o‘zgartirishi mumkin. Bu miyadagi harakatlarni rejalashtirish qobiliyati takomillashayotganini ko‘rsatadi. Bog‘da u bilan "Zigzag poygasi"ni o‘ynab, chaqqonligini oshiring.') WHERE id = 'cad61f20-8263-4b3a-bfc8-ed14fb447f18';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Taxmin qilish va mantiq". Unga ertak o‘qib berayotganda "Sizningcha, keyin nima bo‘ladi?" deb so‘rang. Bola endi voqealar rivojiga mos mantiqiy taxminlar qila oladi. Bu uning ham tasavvurini, ham sabab-oqibat bog‘liqliklarini tushunish qobiliyatini rivojlantiradi.') WHERE id = '9337ce82-dd36-4b6f-a92e-336053ee8590';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Shakldan nusxa olish: kvadrat". Doiradan farqli ravishda, kvadrat chizish qalamni burchaklarda to‘xtatib, yo‘nalishini o‘zgartirishni talab qiladi. Bu yozishga o‘tish uchun muhim jismoniy tayyorgarlikdir. Unga turli geometrik shakllarni birlashtirib, uy yoki mashina chizishni ko‘rsating.') WHERE id = '90518b08-497d-4de6-998e-df3fea30a1f5';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Sabab-oqibat zanjiri". U endi sizning taqiqlaringizga mantiqiy izoh izlaydi: "Nega hozir shirinlik yeyish mumkin emas?". Javob berayotganda "Chunki men shunday dedim" deyish o‘rniga, "Chunki hozir shirinlik yesang, qorning to‘yadi va foydali tushligingni yeya olmaysan" kabi izohlar bering. Bu uning mantiqiy tafakkurini rivojlantiradi.') WHERE id = 'c914eb21-6b42-48f0-8ec0-5b93a47ae392';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Inson tasviridagi detallar". Bola endi odam rasmini chizayotganda unga barmoqlar, kipriklar, tugmalar yoki bosh kiyim kabi mayda detallarni qo‘shadi. Bu rasmlar uning atrofdagi olamni qanchalik diqqat bilan kuzatishi va qo‘l-ko‘z muvofiqlashuvi natijasidir.') WHERE id = 'fdd8b340-0697-4aeb-8d02-8988eb7da642';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"Xayoliy qo‘rquvlarni boshqarish". Bu yoshda bolalar ba’zan qorong‘ilikdan yoki "mahluqlar"dan qo‘rqishi mumkin. Uning qo‘rquvini inkor etmang, aksincha, "mahluqni quvib yuboradigan sehrli fonar" kabi o‘yinlar o‘ylab toping. Sizning hissiy qo‘llab-quvvatlashingiz unga bu qo‘rquvlar vaqtinchalik ekanini anglatadi.') WHERE id = 'd0348641-27c7-4875-b24e-5d2722f25676';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Natijaga yo‘naltirilgan hamkorlik". Bola endi boshqa bir do‘sti bilan birgalikda katta minora qurish uchun "toshlar"ni bo‘lisha oladi. Bu endi shunchaki yonma-yon emas, balki umumiy maqsad yo‘lida o‘ynashdir (hamkorlikdagi o‘yin). Uning bu ijtimoiy diplomatik jihatini "Siz juda ajoyib jamoa bo‘ldingiz!" deb maqtang.') WHERE id = 'bd3e5f00-1925-4d9d-bea8-7fc43abbb171';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Miqdorning saqlanishi sinovi". Bola hali ham yassilangan plastilin bo‘lagi plastilin sharchasidan kattaroq deb o‘ylashi mumkin. U bilan shunday tajribalar o‘tkazing: plastilin sharchasini yoying, so‘ng uni yana sharcha holiga keltiring. Bu unga jismoniy olamning o‘zgarmas qonunlarini tushunishga yordam beradi.') WHERE id = '34ed2954-3007-40b2-9228-8e5bbced6cd6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashuv: "To‘pni oyoq bilan boshqarish". Bola endi to‘pni shunchaki tepmaydi, balki uni oyog‘i bilan biroz oldinga surib (dribbling), harakatlantirishga urinadi. Bu dinamik muvozanat va oyoq-ko‘z muvofiqlashuvini talab qiladi. Bog‘da uning uchun kichik "futbol yo‘lakchasi" yarating va undan to‘pni nishon tomon olib borishini so‘rang.') WHERE id = 'f67ac937-be10-4065-8ce0-71169b977a25';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish va sabr". Bola endi navbat kutish yoki istagi darhol bajarilmasligi "dunyoning oxiri" emasligini tushunadi. Sizning "5 daqiqa kut" degan gapingizni xotirjamroq qabul qiladi. Kutganidan keyin unga albatta "Sabr qilganing uchun rahmat" deb, bu ijobiy xatti-harakatini mustahkamlang.') WHERE id = '24183c71-3661-48ff-a107-410bfbd38523';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Qoidali jamoaviy o‘yinlar". Bola endi boshqa bolalar bilan birgalikda qoidalari bor o‘yinlarni (masalan, "Bekinmachoq") o‘ynashga qiziqish bildiradi. Bu ijtimoiy moslashuvning muhim bosqichidir. Qoidalarga rioya qilganida, uni "Halol o‘ynaganing uchun barakalla" deb maqtang.') WHERE id = '04f3027e-9e30-43e8-bafb-f6c237c97831';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Miqdorni bir qarashda aniqlash (subitizatsiya)". Bola endi 4-5 ta buyumni sanamasdan, shunchaki qarab, nechta ekanini tushuna oladi. Unga turli miqdordagi nuqtalar tushirilgan kartalarni ko‘rsating va "Bu yerda nechta?" deb so‘rang. Bu kelajakda tezkor matematik hisob-kitob qilish uchun poydevor yaratadi.') WHERE id = '494bf11b-00d7-4571-8a96-04e2a73dc57c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Bir oyoqda sakrash". Bola endi bir oyog‘ida ketma-ket bir necha marta sakrashga urinadi. Bu ham kuch, ham yuqori darajadagi muvozanatni talab qiladi. U bilan uyda "Izlar bo‘ylab sakrash" o‘yinini o‘ynab, oyoq mushaklari va muvozanatini mustahkamlang.') WHERE id = 'e519a6cc-28f9-4dbb-80e3-d4aaf6533df1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqtni tasavvur qilish". Bola endi kunning qismlari va ularning ketma-ketligini yaxshi biladi. "Ertalab uyg‘onganda quyosh chiqadi, kechqurun esa oy chiqadi". U bilan ertangi rejalarni "avval, keyin, oxirida" shaklida muhokama qilishingiz unda xavfsizlik hissini ham shakllantiradi.') WHERE id = '22058766-30d2-4299-8138-dbe3e33f7a99';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Murosa va yechimlar". Nizo paytida bola endi shunchaki yig‘lamaydi, balki "Kel, o‘yinchoqni bo‘lishib o‘ynaymiz" yoki "Menga buni ber, men ham senga buni beraman" kabi takliflar qiladi. Bu ijtimoiy intellektning eng yuqori bosqichidir. Uning bunday tinchliksevar yondashuvini doimo qo‘llab-quvvatlang. Siz ajoyib insonni tarbiyalayapsiz!') WHERE id = '29c7e41f-162a-440d-ad79-c662956e2e8e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni bir vaqtning o‘zida ham rangi, ham o‘lchamiga qarab guruhlay oladi: "Barcha kichik va yashil kublarni bu yerga yig‘amiz". Bu kognitiv moslashuvchanlikning muhim ko‘rsatkichidir. Unga turli mezonlarga asoslangan "Izla va top" o‘yinlarini taklif qilib, diqqatini rivojlantiring.') WHERE id = '428720ac-8db6-44a9-825f-ab25eee4d54f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Aniq otish". Bola endi to‘p yoki kichik xaltachani muayyan nishonga (masalan, savatga) aniqroq ota oladi. Bu fazodagi masofani baholash (spatial estimation) va kuchni boshqarish ko‘nikmasi rivojlanayotganini ko‘rsatadi. U bilan uyda "Nishonga ur" musobaqasini tashkil qiling; bu qo‘l va ko‘z muvofiqligini ham mustahkamlaydi.') WHERE id = '5a34a884-0d1a-4ecc-8aaf-0538071d5d58';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Nega"dan "Qanday"ga o‘tish. Endi u hodisalarning nafaqat sababini, balki qanday sodir bo‘lishini ham so‘raydi: "Mashina qanday yuradi?", "Yomg‘ir qanday yog‘adi?". Javob berayotganda oddiy fizik qonunlarni (masalan, "g‘ildiraklar aylanadi") tushuntirish orqali uning ilmiy qiziqishini rag‘batlantiring.') WHERE id = '43f973d1-c670-48fb-b082-c963d974b2cb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Kompozitsiya yaratish". Bola rasm chizayotganda endi bir-biriga bog‘liq bo‘lgan bir nechta obyektni bitta qog‘ozda tasvirlaydi: "Bu uy, bu esa uning yonidagi daraxt". Bu uning atrofdagi olamni yaxlit va tizimli tarzda anglay boshlaganini ko‘rsatadi.') WHERE id = '4fc62a39-6aec-4659-8e0d-de5a572b7f58';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish (Self-regulation)". Bola endi jahli chiqqanda "Jahlim chiqdi!" deb, jismoniy reaksiyani (masalan, urishni) so‘z bilan almashtirishga harakat qiladi. Bu hissiy intellekt rivojidagi eng katta sakrashlardan biridir. U his-tuyg‘ularini ifodalaganda, uni tinglang va "His-tuyg‘ularingni so‘z bilan aytganing uchun sen bilan faxrlanaman" deb qo‘llab-quvvatlang.') WHERE id = '2e78bbc8-d3e0-46e9-b6f4-fd06f0ff0e92';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Rolli o‘yinlardagi muloqot". Endi bola o‘yinlarda uzun suhbatlar tuzadi: "Sen do‘konga kelding, mendan non so‘rayapsan...". Bu o‘yinlar orqali u ijtimoiy me’yorlar va muloqot odobini sinab ko‘radi. Uning ssenariysiga ergashib, bu ijodiy jarayonda ishtirok eting.') WHERE id = 'c878d5a6-c839-4863-9ea6-c1e45caf4ee6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida "Qarama-qarshiliklarni tasniflash". Bola endi "issiq-sovuq", "baland-past", "og‘ir-yengil" tushunchalarini to‘liq farqlay oladi. U bilan "Teskarisini top" o‘yinini o‘ynang: siz "katta" deng, u esa "kichik" desin. Bu uning ham so‘z boyligini, ham mavhum qiyosiy fikrlashini rivojlantiradi.') WHERE id = '96a1b8b4-4a53-4821-8a70-36e9af7db4b1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Zinada harakatlanish". Bola endi zinadan ishonch bilan tushib-chiqadi va ba’zan qo‘lida o‘yinchoq bo‘lsa ham muvozanatini saqlay oladi. Bu dinamik muvozanatning yuqori darajasidir. Har doim uning yaqinida bo‘ling, ammo erkin harakatlanishi uchun unga ishonch bering.') WHERE id = 'e31518b3-755f-43f6-a042-c5c881774776';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Tasavvur va hikoya". Bola sizga o‘zi to‘qigan kichik ertaklarni aytib berishi mumkin. Bu ertaklarda haqiqat va xayol bir-biriga qorishib ketadi. Uning hikoyalarini "Rostdanmi?" yoki "Keyin nima bo‘ldi?" kabi qiziqish bildiruvchi savollar bilan qo‘llab-quvvatlang. Bu kelajakda uning ravon va ifodali nutqini rivojlantirishga yordam beradi.') WHERE id = '1285abea-7296-4d22-a83f-6877ea839c11';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "G‘alaba va mag‘lubiyat". Bola endi o‘yinlarda yutqazishni (har doim bo‘lmasa-da) xotirjamroq qabul qiladi. "Keling, yana bir marta o‘ynaymiz" deb qayta urinishi uning irodasi shakllanayotganidan dalolat beradi. "Asosiysi — o‘ynash" deb, bu muhim hayotiy ko‘nikmani doimo ta’kidlang.') WHERE id = 'ab47da7b-7dd4-423e-bf69-3500dd83cc2f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "agar... unda..." mantiqini murakkab ijtimoiy vaziyatlarda qo‘llaydi: "Agar men unga o‘yinchog‘imni bersam, u ham menga o‘yinchog‘ini beradi". Bu o‘zaro munosabatlarning asosidir. U bilan "Natijasi nima bo‘ladi?" o‘yinini o‘ynang (masalan, "Gulga suv quymasak, nima bo‘ladi?"). Bu uning oldindan ko‘ra bilish qobiliyatini rivojlantiradi.') WHERE id = 'd6bf3a90-b7f5-4d81-9101-4bd23f1bc25d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Balandlikdan sakrash". Bola endi muayyan balandlikdan (masalan, pastak zinapoyadan) muvozanatini yo‘qotmasdan ikki oyog‘i bilan sakrab tusha oladi. Bu tizza va to‘piq bo‘g‘imlari mustahkamlanayotganidan dalolat beradi. Unga "yumshoq qo‘nish"ni (tizzalarini biroz bukib) o‘rgating.') WHERE id = '2795a26f-4a85-42cd-9860-03afd8411f60';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Vaqtga oid mavhum tushunchalar". Bola endi "hafta oxiri", "bayramda", "tug‘ilgan kunda" kabi kengroq vaqt oraliqlarini tushunadi. U bilan yaqinlashib kelayotgan muhim voqea (masalan, sayr) haqida gaplashayotganda "3 kundan keyin" kabi iboralardan foydalanib, vaqt haqidagi tasavvurini chuqurlashtiring.') WHERE id = '4dbdf376-fb0e-469f-bb2e-b3be32d8d1c8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Harflardan nusxa ko‘chirish". Bola endi ayrim oddiy harflarni (masalan, A, O, T) ko‘rganidek ko‘chirib yozishga harakat qiladi. Bu belgilarni ham ko‘rish, ham harakat xotirasiga o‘tkazish jarayonidir. Unga qum solingan patnis yoki barmoq bo‘yog‘i yordamida harflarni "yozishni" taklif qiling.') WHERE id = '83f43947-4f06-425b-801a-dd053a64d6b1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish: istakni kechiktirish". Bola endi biror mukofot uchun biroz ko‘proq kutish kerakligini (masalan, "ovqatdan keyin shirinlik") qabul qila oladi. Bu iroda kuchi va o‘zini boshqarish (kechiktirilgan qoniqish) qobiliyatining rivojlanishidir. Uning bu sabrini albatta e’tirof eting va maqtang; bu kelajakdagi muvaffaqiyatli ta’limning kalitidir.') WHERE id = '51891c5d-a6e3-40d4-8ba5-38112ce2f223';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Guruh birdamligi". Bola endi do‘sti yig‘layotganida shunchaki qarab turmaydi, balki "Nima bo‘ldi?" deb so‘raydi yoki sizga xabar beradi. Bu hamdardlikning faol bosqichidir. Uning g‘amxo‘rligini "Sen juda mehribon do‘stsan" deb qo‘llab-quvvatlang.') WHERE id = '9932ed27-e891-4fec-aac9-e64c5a418a49';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Qo‘shish asoslari". Bola endi 2 ta o‘yinchoq yoniga yana 1 tasi qo‘yilsa, jami 3 ta bo‘lishini sanamasdan (yoki tezda sanab) tushuna oladi. Kundalik yumushlar davomida "Senda 2 ta olma bor edi, men yana 1 ta berdim, endi nechta bo‘ldi?" kabi kichik matematik topishmoqlar tuzing.') WHERE id = '5f9e5aa3-02e0-4bd3-85bf-ad954730aed0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Bir oyoqda sakrash (Hop-stop)". Bola endi bir oyog‘ida ketma-ket 2-3 marta sakray oladi. Bu yuqori darajadagi muvozanatni ham, oyoq mushaklarining kuchini ham talab qiladi. U bilan uyda "Klassik" o‘yinini o‘ynab, harakatlarini muvofiqlashtirish qobiliyatini yanada rivojlantiring.') WHERE id = '5d319604-f8fa-4e75-83e3-e78cf306cb47';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Tasviriy hikoya". Bola o‘zi chizgan rasm yoki ko‘rgan voqeani izchil gaplar bilan aytib beradi. "Bu yerda bir it bor edi, u yugurdi, keyin daraxtga chiqdi...". Uning nutqidagi izchillikka e’tibor bering. Bu uning miyasida voqealarni mantiqiy tartibda qanday joylashtirayotganini ko‘rsatadi.') WHERE id = '5e32473e-0836-4d23-8816-7e98014c394b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1400 kunlik ulkan g‘alaba! Farzandingiz 46 oylik bo‘ldi. Endi u o‘zligini anglaydigan, boshqalarning his-tuyg‘ulariga hamdard bo‘ladigan va dunyoni mantiqan o‘rganadigan kichkina "olim"dir. Siz shu 1400 kun davomida farzandingiz uchun eng ishonchli qo‘rg‘on va eng yaxshi ustoz bo‘ldingiz. Siz ajoyib onasiz!') WHERE id = 'af7c9867-8fc8-42cc-b62a-1044c801bdef';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '47-oyga xush kelibsiz! Bola endi "mas’uliyat" tushunchasini yaxshiroq anglaydi. Unga uyda kichik "vazifalar" bering (masalan, gullarga suv quyish yoki dasturxonga salfetka qo‘yish). Bu uning o‘zini oilaning muhim va foydali a’zosi sifatida his qilishiga yordam beradi. Uning bu sa’y-harakatlarini albatta e’tirof eting va minnatdorlik bildiring.') WHERE id = '13b68bb4-0e80-4802-bd12-f626258d3f54';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Almashlab qadam tashlab yugurish". Bola endi yugurayotganda zinapoyalar yoki to‘siqlardan ritmik ravishda, har bir qadamda oyoqlarini almashtirib o‘ta oladi. Bu gavdaning pastki qismi kuchi hamda ko‘rish-harakatni rejalashtirish qobiliyati qanchalik rivojlanganini ko‘rsatadi.') WHERE id = '8fba68a9-4860-41c9-9d6a-0aabd4a4dc7d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Fonetika va harflar". Bola endi so‘zlar qaysi tovush bilan boshlanishini farqlay oladi: "Olma ''O'' bilan boshlanadi". U bilan "Tovush ovi" o‘yinini o‘ynang; xonadan muayyan tovush bilan boshlanadigan buyumlarni topishini so‘rang. Bu kelajakda o‘qish va yozish ko‘nikmalari uchun eng muhim poydevordir.') WHERE id = '4c5fdac9-9874-4896-80d4-6960b6675b1b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qalamni to‘g‘ri ushlash (Tripod)". Bola endi qalamni bosh, ko‘rsatkich va o‘rta barmoqlari bilan ("uch oyoqli" usulda) yanada ishonchli ushlaydi. Bu unga batafsilroq rasmlar chizish va harflardan nusxa ko‘chirish imkonini beradi. Unga turli qalinlikdagi qalamlar berib, barmoq mushaklarini mashq qildiring.') WHERE id = '01cf8b7d-9668-4ab1-a360-d6968cb99749';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish: qoidalar mantig‘i". Bola endi qoidalarga shunchaki siz aytganingiz uchun emas, balki ularning mantig‘ini tushungani uchun amal qilishga harakat qiladi. "Yo‘lda ketayotganda qo‘lingdan ushlayman, chunki mashinalar bor". Unga qoidalar xavfsizlik va tartib uchun muhimligini tushuntirishda davom eting; bu ichki intizomning asosidir.') WHERE id = 'd91c45ef-c67b-4312-9a1e-572e86ed0a0e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Adolatli taqsimlash". Bola endi o‘yinchoqlar yoki shirinliklarni do‘stlari o‘rtasida teng taqsimlashga qiziqish bildirmoqda: "Bittasi senga, bittasi menga". Bu ham ijtimoiy empatiya, ham dastlabki matematik tushunchalarning (bo‘lish amalining) uyg‘unlashuvidir.') WHERE id = '2a9fd489-5479-4444-9ad0-d9ca9e6d37c8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojlanishida "Buyumlarni tasniflash". Bola endi buyumlarni ham turiga, ham ishlatiladigan joyiga qarab guruhlarga ajratadi: "Bular oshxona uchun, bular yotoqxona uchun". Bu uning miyasidagi ma’lumotlar qanday tizimli va iyerarxik tarzda tuzilganini ko‘rsatadi.') WHERE id = 'b49a3e45-1e44-429c-b3ab-7432f30a4a37';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "To‘pni tutish va otish (integratsiya)". Bola endi to‘pni tutishi bilan uni darhol nishonga ota oladi. Bu ketma-ket harakatlarning bir-biriga uyg‘un tarzda o‘tishidir. U bilan bog‘da "Otib-tutish" musobaqasini o‘tkazib, reaksiya tezligi va chaqqonligini oshiring.') WHERE id = 'b2cee277-0949-412e-af09-df96b2fd9cfd';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Murakkab gap tuzilishi". Bola endi "agar", "chunki", "lekin" kabi bog‘lovchilardan foydalanib, uzun va mantiqiy gaplar tuzadi. Uning gapini bo‘lmasdan tinglang va "Demak, sen shunday deb o‘ylaysan..." deya fikrini kengaytirishga yordam bering. Bu uning o‘z fikrini ifodalash qobiliyatini va faol lug‘at boyligini oshiradi.') WHERE id = 'eaf98320-82a4-46ba-81fe-43fd023e6b82';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "O‘zini ovutish". Bola endi yengil yiqilish yoki kichik muvaffaqiyatsizlikdan so‘ng darhol yig‘lamasligi, o‘ziga "Hech narsa bo‘lmadi" deb, o‘rnidan turishi mumkin. Bu hissiy bardoshlilikning muhim ko‘rsatkichidir. Siz uning bu jasoratini har doim "Sen juda kuchlisan!" deb qo‘llab-quvvatlang.') WHERE id = 'c0cb0b02-4a51-4012-b51b-53868aad0bf0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi "soat" tushunchasiga qiziqa boshlaydi. U "Soat necha bo‘ldi?" deb so‘rashi mumkin. Unga vaqtni daqiqalar bilan emas, voqealar orqali tushuntiring: "Katta strelka bu yerga kelganda, biz sayrga chiqamiz". Bu unga vaqtni o‘lchash mumkin bo‘lgan tushuncha ekanini anglashga yordam beradi.') WHERE id = '3a58737c-1dc5-47f3-86ee-31c959892712';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Kross-lateral koordinatsiya". Bola endi joyida qadam tashlar ekan, o‘ng qo‘lini chap tizzasiga va aksincha tekkiza oladi. Bu harakat miyaning ikkala yarimshari bir vaqtda ishlashini talab qiladi hamda kelajakda o‘qish va yozishni o‘rganishni osonlashtiradi.') WHERE id = '86960e2f-7035-4c14-a9a6-baeb23c3ea3d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "O‘tmish tafsilotlari". Bola bir necha kun oldin sodir bo‘lgan voqeani izchil hikoya qilib bera oladi. "Buvimnikiga borganimizda, u yerda mushukni ko‘rgandik, u daraxtga chiqib ketgandi". Uning bu "epizodik xotirasini" mustahkamlash uchun kun oxirida: "Bugun eng qiziqarli nima bo‘ldi?" deb so‘rang.') WHERE id = '6caf0def-6055-4b83-9a80-442193cfb9e1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qog‘oz qirqish: Murakkab shakllar". Bola endi qaychi bilan faqat to‘g‘ri chiziq bo‘ylab emas, balki to‘lqinsimon chiziqlar yoki katta doirani ham qirqib olishga harakat qiladi. Bu qo‘l va ko‘z muvofiqligi juda yuqori darajada rivojlanganini ko‘rsatadi.') WHERE id = '64c3b0ce-8c21-4147-b606-f32ae65475bf';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘ng va chap tushunchasi". Bola endi o‘ng va chap qo‘lini, hali to‘liq aniq bo‘lmasa-da, ajrata oladi. Unga "Qoshiqni o‘ng qo‘ling bilan ushla" yoki "Paypog‘ingni chap oyog‘ingga kiy" deb, makonda mo‘ljal olish qobiliyatini mustahkamlang. Bu ko‘nikma kelajakda harflarning yo‘nalishini adashtirmaslik uchun muhimdir.') WHERE id = '51c70f08-e08e-4a17-97ca-6373b3c435eb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Guruhda yetakchilik". O‘yin paytida bola endi boshqa bolalarga "Sen bu yerga o‘t, sen buni qil" deb rollarni taqsimlaydi. Shu tariqa u ijtimoiy ierarxiya va tashkilotchilik qobiliyatini sinab ko‘radi. Uning yetakchilik qilishga urinishlarini kuzating va adolatli bo‘lishiga yordam bering.') WHERE id = 'ed221959-c928-4692-880d-29170d62352e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Idrok rivojlanishida «Miqdorning saqlanishi: son». Bir xil miqdordagi toshlarni bir tomonda zich, ikkinchi tomonda esa keng yoyib qo‘ysangiz, bola har ikki tomondagi toshlar soni bir xil ekanini tushuna boshlaydi. Bu — ko‘zga ko‘rinadigan aldanishdan mantiqiy xulosaga o‘tish bosqichidir.') WHERE id = '55c3f5e4-d3a4-465e-b035-b83e41b450d4';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Bir oyoqda sakrash». Bola endi bir oyog‘ida oldinga qarab bir necha marta sakray oladi. Buning uchun ham muvozanat, ham oyoqlarning keskin kuch ishlata olish qobiliyati kerak. U bilan uyda «Klassik» o‘yinini o‘ynash uchun ayni muddao.') WHERE id = 'ddfca79d-8eb7-4cbd-84fd-61e54d7153db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «So‘z ichidagi tovushlar». Bola endi so‘z oxiridagi tovushlarni ham ajrata oladi (masalan, «olma» so‘zi «a» tovushi bilan tugashini ayta oladi). Bu fonematik eshitishning eng yuqori bosqichidir. U bilan «Oxirgi harfdan so‘z top» (so‘z zanjiri) o‘yinini o‘ynab, lug‘at boyligi va eshitish diqqatini rivojlantiring.') WHERE id = '3863c552-322d-4dc8-a917-02d61270f313';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: «Muvaffaqiyatsizlik va strategiya». Bolaning biror ishi o‘xshamasa, u darhol yig‘lamaydi, balki «Boshqa usulda sinab ko‘rsam-chi?» deb o‘ylaydi. Bu «rivojlanishga yo‘naltirilgan fikrlash» (growth mindset) asosidir. Uni natijasi uchun emas, yangi yo‘l izlagani uchun albatta maqtang.') WHERE id = 'da0d4f8a-08c6-45ad-9022-933f9025eb01';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni nafaqat tashqi ko‘rinishiga, balki qanday materialdan tayyorlanganiga qarab ham farqlaydi: «Bu plastik, bunisi esa temir». Unga turli teksturadagi buyumlarni bering va ular orasidagi farqlarni so‘rang. Bu unga atrofdagi olamni batafsilroq tahlil qilishga va moddiy dunyo haqidagi bilimlarini tizimlashtirishga yordam beradi.') WHERE id = 'ec9b72ac-4600-4d72-8d5e-3a0bc232d29c';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda «Aniq sakrash». Bola endi muayyan nishon tomon (masalan, yerdagi doira ichiga) sakray oladi. Bu ham muvozanatni, ham fazodagi masofani chamalash qobiliyatini ko‘rsatadi. Bog‘da «toshdan toshga sakrash» o‘yini uning uchun ajoyib mashq bo‘ladi.') WHERE id = 'f6611b06-b8bc-42ff-84b4-2e17ea2e10d6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Qarama-qarshi tushunchalarni tasniflash». Bola endi «issiq-sovuq», «baland-past», «og‘ir-yengil» tushunchalarini bir-biridan to‘liq farqlay oladi. U bilan «Teskarisini top» o‘yinini o‘ynang: siz «katta» deng, u esa «kichik» desin. Bu uning ham so‘z boyligini, ham mavhum va qiyosiy fikrlash qobiliyatini rivojlantiradi.') WHERE id = '00735398-0d89-4428-a943-f4a27fc19021';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Shaklni ko‘chirish: uchburchak va xoch». Bola endi to‘g‘ri chiziqlarni kesishgan holda chizib, xoch (+) hosil qila oladi va uchburchakka o‘xshash shakllar chizishga harakat qiladi. Bular yozish ko‘nikmasining dastlabki poydevoridir. Unga rangli qalamlar va toza qog‘ozlar berib, bu «geometrik kashfiyotlarini» qo‘llab-quvvatlang.') WHERE id = '1b117df4-43a4-4780-a2e3-365c2acc3518';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«O‘zini boshqarish: istakni kechiktirish». Bola endi biror mukofotga erishish uchun biroz ko‘proq kutish kerakligini (masalan, «ovqatdan keyin shirinlik») qabul qila oladi. Bu iroda kuchi va o‘zini boshqarishning (kechiktirilgan qoniqish) rivojlanishidir. Uning bunday sabrini albatta e’tirof eting; bu kelajakdagi muvaffaqiyatli ta’limning kalitidir.') WHERE id = '93c7b1b4-9941-4328-bd03-c48ffc7f605f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Guruh hamjihatligi». Bola endi do‘sti yig‘laganda shunchaki qarab turmaydi, «Nima bo‘ldi?» deb so‘raydi yoki sizga xabar beradi. Bu hamdardlikning faol bosqichidir. Uning g‘amxo‘rligini «Sen juda mehribon do‘stsan» deb qo‘llab-quvvatlang.') WHERE id = 'e9a7f349-2186-4929-ba3f-64f7d951af57';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish qobiliyatining rivojlanishida «Qo‘shish asoslari». Bola endi 2 ta o‘yinchoq yoniga yana 1 tasi qo‘yilsa, jami 3 ta bo‘lishini sanamasdan (yoki tezda sanab) tushuna oladi. Kundalik ishlar davomida «Senda 2 ta olma bor edi, men yana 1 ta berdim, endi nechta bo‘ldi?» kabi kichik matematik topishmoqlar tuzing.') WHERE id = '6d1eeaa2-0164-4cca-94b4-9c14e8d79d60';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «Zinapoyada harakatlanish». Bola endi zinapoyadan ishonch bilan tushib-chiqadi va ba’zan qo‘lida o‘yinchoq bo‘lsa ham muvozanatini saqlay oladi. Bu dinamik muvozanatning yuqori darajasidir. Har doim uning yaqinida bo‘ling, ammo mustaqil harakatlanishi uchun unga ishonch bering.') WHERE id = '28cfd5f7-ecbc-4133-9e9d-cc5c82140054';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish: hissiy diplomatiya". Bola istagi amalga oshmaganda endi baqirish o‘rniga sizga sababini tushuntirishi mumkin: "Ammo men buni juda xohlagandim, chunki...". Uning muloqot qilishga bo‘lgan bu urinishini qadrlang. His-tuyg‘ularini tan oling, ammo qoidalar nega o‘zgarmasligini ham sabr bilan tushuntiring.') WHERE id = 'd8f54a1a-d4b0-4c91-b361-1e6376bfa2db';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Qoidalarga rioya qilish". Bola endi stol o‘yinlarida (masalan, domino yoki oddiy raqamli o‘yinlarda) qoidalarni buzmay o‘ynashga alohida ahamiyat beradi. Bu — ijtimoiy moslashuvning muhim bosqichi. Qoidalarga rioya qilganida, uni "Juda halol va sabr bilan o‘ynading" deb ruhlantiring.') WHERE id = '111e7db0-d36d-44a0-97d8-10b28cd566ca';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bilish rivojida "Miqdorning saqlanishi: hajm sinovi". Bir xil miqdordagi plastilinning birini dumaloq, ikkinchisini esa uzun "ilon" shakliga keltirsangiz, bola endi ularning miqdori bir xil qolganini anglay boshlaydi. Bu — ko‘rish orqali aldanishdan mantiqiy xulosa chiqarishga o‘tish bosqichi. Bu tajribalarni birgalikda sinab ko‘ring.') WHERE id = '0655a03a-60b9-48e1-b285-1d3c83082836';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Bir oyoqda sakrash". Bola endi bir oyog‘ida oldinga qarab bir necha marta sakray oladi. Buning uchun ham muvozanat, ham oyoqlarning kuchli harakati talab etiladi. U bilan uyda "Izlar" o‘yinini o‘ynash uchun ayni payt; bu o‘yinning makonda mo‘ljal olish qobiliyatini ham rivojlantiradi.') WHERE id = 'c5a0358e-6841-4ba2-8c21-cb976413e324';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Tasavvur va mantiq uyg‘unligi". Bola sizga o‘zi to‘qigan, ammo mantiqiy izchillikka ega ertaklarni aytib berishi mumkin. "Bir bor ekan, bir robot bor ekan, batareyasi tugagani uchun u to‘xtab qolibdi...". Uning hikoyalarini "Keyin nima bo‘ldi?" kabi savollar bilan qo‘llab-quvvatlang. Bu kelajakda uning nutqi ravon va ifodali bo‘lishiga yordam beradi.') WHERE id = '5fe788e8-9a0a-4448-9455-65cf7a8679b1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Hissiy bardoshlilik: "Muvaffaqiyatsizlikka qarshi yangi strategiya". Bolaning biror ishi (masalan, pazl yig‘ish) o‘xshamasa, u darhol jahli chiqmay, "Balki buni bunday qo‘yib ko‘rarman?" deb yangi yo‘llarni izlaydi. Bu — "rivojlanishga yo‘naltirilgan fikrlash tarzi"ning (growth mindset) asosidir. Uning natijasini emas, yangi yo‘l topishga qilgan harakatini albatta maqtang.') WHERE id = '19cb7d19-f480-4e1f-805a-267dba1df2a8';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni nafaqat tashqi ko‘rinishiga, balki qanday materialdan yasalganiga qarab ham farqlaydi: "Bu plastik, bunisi esa temir". Unga turli tuzilishga ega buyumlarni bering va ular orasidagi farqlarni so‘rang. Bu unga atrofdagi olamni yanada batafsil tahlil qilish va moddiy dunyo haqidagi bilimlarini tizimlashtirishga yordam beradi.') WHERE id = '0ec14802-bab2-45c4-8cbf-788bdfa85e13';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Aniq sakrash". Bola endi muayyan nishonga qarab (masalan, yerdagi doira ichiga) sakray oladi. Bu ham muvozanatni saqlash, ham fazodagi masofani hisoblay olish qobiliyatini ko‘rsatadi. Bog‘da "toshdan toshga sakrash" o‘yini uning uchun ajoyib mashq bo‘ladi.') WHERE id = '0ddedeb7-e832-48ca-923d-05838885cdc1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Qarama-qarshi tushunchalarni tasniflash". Bola endi "issiq-sovuq", "baland-past", "og‘ir-yengil" tushunchalarini to‘liq farqlaydi. U bilan "Teskarisini top" o‘yinini o‘ynang: siz "katta" deng, u esa "kichik" desin. Bu uning ham so‘z boyligini, ham mavhum va qiyosiy fikrlash qobiliyatini rivojlantiradi.') WHERE id = '3810cfc8-49ab-40fa-b90d-2edf9dc84fae';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Shakldan nusxa ko‘chirish: uchburchak va xoch". Bola endi to‘g‘ri chiziqlarni kesishgan holda chizib, xoch (+) hosil qila oladi va uchburchakka o‘xshash shakllarni chizishga urinadi. Bular yozish ko‘nikmasining dastlabki asoslaridir. Unga rangli qalamlar va oq qog‘ozlar berib, ushbu "geometrik kashfiyotlarini" qo‘llab-quvvatlang.') WHERE id = 'dfeb7b05-cea8-4a6f-b41b-005f3d3c488e';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '"O‘zini boshqarish: istakni kechiktirish". Bola endi mukofotga erishish uchun biroz ko‘proq kutish kerakligini (masalan, "ovqatdan keyin shirinlik") qabul qiladi. Bu iroda kuchi va o‘zini boshqarish (delayed gratification) qobiliyatining rivojlanishidir. Uning bu sabrini albatta e’tirof eting; bu kelajakdagi muvaffaqiyatli ta’limning kalitidir.') WHERE id = '988ae101-5f2f-4a86-a365-28a27e843965';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda "Guruh birdamligi". Bola endi do‘sti yig‘layotganida shunchaki qarab turmaydi, balki "Nima bo‘ldi?" deb so‘raydi yoki sizga xabar beradi. Bu hamdardlik faol namoyon bo‘ladigan bosqichdir. Uning bu g‘amxo‘r jihatini "Siz juda mehribon do‘stsiz" deb qo‘llab-quvvatlang.') WHERE id = 'ed4539aa-f1cf-4dd1-97f9-a5cf3f6b499d';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Tasavvur va hikoya". Bola sizga o‘zi to‘qigan kichik ertaklarni aytib berishi mumkin. Bu ertaklarda haqiqat va xayol bir-biriga qorishib ketadi. Uning hikoyalarini "Rostdanmi?" yoki "Keyin nima bo‘ldi?" kabi qiziqish bildiruvchi savollar bilan qo‘llab-quvvatlang. Bu kelajakda uning nutqi ravon va ifodali bo‘lishiga yordam beradi.') WHERE id = 'c414dc79-8944-48c3-a5d5-e50145e600bc';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '1430 kunlik zafar! Bola 47 oylik bo‘ldi. Endi u o‘zini anglaydigan, boshqalarning his-tuyg‘ulariga hamdard bo‘ladigan va dunyoni mantiq orqali kashf etadigan jajji "olim"dir. Siz shu 1430 kun davomida farzandingiz uchun eng ishonchli panoh va eng yaxshi ustoz bo‘ldingiz. Siz ajoyib onasiz!') WHERE id = '8f2e9299-bb7b-4d28-9fbc-c07c7ba2a262';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '48-oyga (4 yoshga) sanoq boshlandi! Bola endi ijtimoiy o‘yinlarda "men" va "biz" o‘rtasidagi farqni to‘liq tushunib, amalda qo‘llaydi. Agar u "Kel, birga kema yasaymiz, sen yelkanni ushla, men esa rulni boshqaraman" deb vazifalarni taqsimlayotgan bo‘lsa, bu hamkorlik qobiliyatining eng yuqori bosqichidir. Uning jamoaviy ruhini qo‘llab-quvvatlang; bu kelajakdagi maktab hayoti uchun muhimdir.') WHERE id = 'b940be7d-ee82-4c09-8760-e2ce9294193f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy harakatchanlikda "Aniq burilishlar". Bola endi bor tezligida yugurayotganda to‘satdan to‘xtay yoki muvozanatini yo‘qotmasdan keskin burila oladi. Bu vestibulyar tizim va mushaklar nazoratining to‘liq muvofiqlashgan holda ishlayotganini ko‘rsatadi. Istirohat bog‘ida uning uchun kichik "to‘siqlar yo‘lagi"ni tashkil qiling.') WHERE id = 'ce453995-5119-4943-ace6-1439bc5d5820';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Tovushlarni tahlil qilish". U endi so‘zlarning nafaqat boshidagi, balki oxiridagi tovushlarni ham ajrata boshlaydi: "Stol ''L'' bilan tugaydi". Bu fonematik eshitish qobiliyatining rivojlanishidir. U bilan "Oxirgi tovushdan boshlanadigan yangi so‘z top" o‘yinini o‘ynab, tilni his qilish qobiliyatini charxlang.') WHERE id = 'e258838d-b844-4e68-840e-2eb0ef520682';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada "Qog‘oz qirqish: murakkab shakllar". Bola endi qaychi bilan murakkab shakllarni (masalan, yulduz yoki kichik hayvon siluetini) chetlari bo‘ylab qirqib olishga harakat qiladi. Bu qo‘l va ko‘z muvofiqlashuvi qanchalik takomillashganini ko‘rsatadi. Unga turli rangdagi qog‘ozlar bering.') WHERE id = '619d1623-d881-46f6-a718-4a537172efc7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Murakkab hikoya tuzish". Bola endi o‘zi to‘qigan ertaklarda "chunki", "lekin", "shuning uchun" kabi bog‘lovchilardan foydalanib, syujet yaratadi. Uning hikoyalarini diqqat bilan tinglang va "Sizningcha, qahramon keyin nima qildi?" kabi savollar bilan uni yangi tafsilotlar qo‘shishga undang.') WHERE id = '24dad4d0-2c9d-4d1c-bb0a-41d9b402e0e7';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '4 yoshga to‘lishiga atigi 20 kun qoldi! Bola endi go‘daklik odatlarini butunlay ortda qoldirib, o‘ziga xos fe’l-atvorga ega jajji shaxsga aylandi. Siz shu 1460 kun davomida uning rivojlanish yo‘lidagi eng yorqin nur bo‘ldingiz. Uning yutuqlari — sizning mehringiz samarasidir. Siz ajoyibsiz!') WHERE id = 'd76fe554-fd7b-4db0-9296-a5ba3be690d0';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda «Muloyim muhokama». Bola endi istagan narsasiga erishish uchun «Iltimos, maylimi?» deyish bilan birga, sababini ham tushuntiradi: «Chunki men uni juda yaxshi ko‘raman». Sizning muloyim javobingiz uning ijtimoiy muloqot tilini shakllantiradi. Uning har bir muloyim iltimosini «Buni shunday chiroyli aytganing uchun senga javob berish menga yoqimli» deb qadrlang.') WHERE id = '0bfff590-18d1-438c-bef2-c5dac59fc7e3';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Mayda motorikada «Harflar va raqamlarni ko‘rib ko‘chirish». Bola endi o‘z ismidagi harflarni yoki «1, 2, 3» kabi raqamlarni qog‘ozga tushirishga urinadi. Bu — harakat va ko‘rish xotirasining uyg‘unlashuvidir. Unga turli rangdagi qalamlar bering va «yozuvlarini» uyning ko‘zga ko‘rinadigan joyiga osib qo‘ying.') WHERE id = '65fb665a-a079-4bde-be1e-8536275e5fd6';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '«O‘zini boshqarish: hissiy mustaqillik». Bola endi kichik bir muammoga duch kelganda (masalan, o‘yinchog‘i buzilib ketganda) darhol sizning oldingizga yugurib kelmaydi, avval uni o‘zi tuzatishga harakat qiladi. Bu «men buni uddalay olaman» degan tuyg‘uning mustahkamlanishidir. Uning mustaqil urinishlarini kuzating va faqat yordamga muhtoj bo‘lgandagina aralashing.') WHERE id = '5a2e55ce-3f97-41a9-965d-b857b33a020f';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Ijtimoiy xulq-atvorda «Qoidalarni tushuntirish». U endi kichik yoshdagi bolalarga yoki o‘yinchoqlariga o‘yin qoidalarini tushuntiradi: «Avval men, keyin sen». Bu ichki intizom va yetakchilik qobiliyatining belgisidir. Uning bu «o‘qituvchilik» jihatini qo‘llab-quvvatlang.') WHERE id = '1e4b1da3-fa3d-4b83-9554-7fdd901b9dfb';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda «Vaqt taqvimi». Bola endi «3 kun qoldi» yoki «Dam olish kunlari boramiz» kabi iboralarni tushunadi. Tug‘ilgan kuniga oz qolganida «teskari sanoq taqvimi» tuzing. Har bir o‘tgan kunni belgilab borish unga vaqtning o‘tishini aniqroq tasavvur qilishga yordam beradi.') WHERE id = 'e9a169de-bc44-43dd-b6f0-9adaff7e3796';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: «To‘pni oyoq bilan nishonga yo‘llash». Bola endi to‘pni shunchaki tepib yubormaydi, balki uni muayyan nishonga (masalan, ikkita tosh orasiga) kiritishga harakat qiladi. Bu fazodagi masofani hisoblashni va oyoq mushaklarining aniq ishlashini talab qiladi.') WHERE id = '1c5a132d-9357-46a5-b5fe-17d6baae9cac';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Aqliy rivojlanishda "Qo‘shish asoslari". Bola endi 2 ta o‘yinchoq yoniga yana 1 tasini qo‘yganda, jami 3 ta bo‘lganini sanamasdan (yoki tezda sanab) tushuna oladi. Kundalik mashg‘ulotlarda "Sizda 2 ta olma bor edi, men yana 1 ta berdim, endi nechta bo‘ldi?" kabi kichik matematik topishmoqlar tuzing.') WHERE id = '321e201a-5cd6-485a-a700-1c1f11885a2b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy muvofiqlashtirish: "Zinapoyada harakatlanish". Bola endi zinapoyadan ishonch bilan tushib-chiqadi va ba’zan qo‘lida o‘yinchoq bo‘lsa ham muvozanatini saqlay oladi. Bu dinamik muvozanatning yuqori darajasidir. Har doim yaqinida bo‘ling, ammo unga erkin harakatlanishi uchun ishonch bering.') WHERE id = '26b9ae52-0022-4e15-934b-ad179ba90589';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Nutqda "Tasavvur va hikoya qilish". Bola sizga o‘zi to‘qigan kichik ertaklarni aytib berishi mumkin. Bu ertaklarda haqiqat va xayol qorishib ketadi. Uning hikoyalarini "Rostdanmi?" yoki "Keyin nima bo‘ldi?" kabi qiziqish bildiruvchi savollar bilan qo‘llab-quvvatlang. Bu kelajakda uning nutqi ravon va ifodali bo‘lishiga yordam beradi.') WHERE id = 'e96b1dc7-ba0c-47d3-b15a-cb6918e2bc9b';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, '4 yoshga to‘lishiga atigi 30 kun qoldi! Bola hozir maktabgacha davrning eng samarali bosqichida. Endi u o‘z didi, qo‘rquvlari va cheksiz savollariga ega bo‘lgan kichkina, ammo to‘laqonli shaxsdir. Siz bu yo‘lni ilm va mehr bilan bosib o‘tdingiz. "Anacan" doimo yoningizda!') WHERE id = '34fd4a41-2c8b-49b5-b2b0-6911f5bb04ab';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Bola endi buyumlarni nafaqat tashqi ko‘rinishiga, balki qaysi guruhga mansubligiga qarab ham ajratadi. "Bular dengiz hayvonlari, bular esa o‘rmon hayvonlari". Bu uning miyasidagi ma’lumotlar allaqachon ilmiy toifalarga ajratilayotganini ko‘rsatadi. U bilan "Kim qayerda yashaydi?" o‘yinini o‘ynang.') WHERE id = 'bacec645-5384-4fc1-94d1-94b2914a27a1';
UPDATE public.mommy_daily_messages SET message_uz = COALESCE(message_uz, 'Jismoniy faollikda "Tez yugurish va muvofiqlashgan holda to‘xtash". Bola endi bor tezligida yugurayotganida sizning "To‘xta!" buyrug‘ingiz bilan yiqilmasdan yoki oldinga qoqilmasdan darhol to‘xtay oladi. Bu mushaklarni boshqarish hamda eshitish-harakat reaksiyasining eng yuqori darajasidir. Bog‘da bu o‘yinni muntazam takrorlab turing.') WHERE id = 'ea737131-3977-4085-b4c4-94dd4ae125f1';

