UPDATE public.nutrition_tips SET title_uz = COALESCE(title_uz, 'Folatga boy oziq-ovqatlar'), content_uz = COALESCE(content_uz, 'Homiladorlikning birinchi trimestrida folat juda muhim. To‘q yashil bargli sabzavotlar, sitrus mevalar va dukkaklilar uning yaxshi manbalaridir.') WHERE id = '3cd9d02f-2306-400b-bf13-48f59e00d6e0';
