UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Oyna bilan qorin ustida mashq'), description_uz = COALESCE(description_uz, 'Chaqaloqning o‘zini oynada ko‘rishi uning rivojlanishini rag‘batlantiradi'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqni qorni bilan yostiq ustiga yotqizing. Uning oldiga oyna qo‘ying. Oynada o‘zini ko‘rsating.') WHERE id = '20e1c63e-791f-43a8-bb33-84ebfe166368';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Oshxona orkestri'), description_uz = COALESCE(description_uz, 'Qozon va tovachalar yordamida ritmni rivojlantirish'), instructions_uz = COALESCE(instructions_uz, 'Yog‘och qoshiq va qozonlarni chaqaloqning oldiga qo‘ying. Ularni qanday urishni ko‘rsating. Birgalikda ritm yarating.') WHERE id = '5a6d5c7d-3489-4b3d-8210-fbeed43d3536';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Qutidan tunnel'), description_uz = COALESCE(description_uz, 'Emaklash va kashf etish ko‘nikmalari'), instructions_uz = COALESCE(instructions_uz, 'Katta karton qutining har ikki tomonini oching. Chaqaloqni bir tomondan emaklab kirishga undang. Uni boshqa tomondan chaqiring.') WHERE id = '8266c528-ae95-47fa-b7f4-28400410ebc2';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Paypoq qo‘g‘irchoqlar'), description_uz = COALESCE(description_uz, 'Muloqot va ijodkorlikni rivojlantirish'), instructions_uz = COALESCE(instructions_uz, 'Eski paypoqdan qo‘g‘irchoq yasang. Chaqaloq bilan "gaplashing". Turli tovushlar chiqaring.') WHERE id = 'fc6ee2c8-0599-4677-994a-dc1385d83024';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Turli teksturalar bo‘ylab sayr'), description_uz = COALESCE(description_uz, 'Turli teksturalar yordamida sezgi rivojlanishi'), instructions_uz = COALESCE(instructions_uz, 'Turli teksturali materiallarni (ko‘rpa, sharf, qog‘oz) yerga yoying. Chaqaloqqa ular ustidan emaklashga imkon bering.') WHERE id = '3b19cf38-0d12-4b49-81d4-69a60f7b3cc2';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Yuqori kontrastli kartochkalar'), description_uz = COALESCE(description_uz, 'Ko‘rish qobiliyatini rivojlantirish uchun oq-qora naqshli kartochkalar'), instructions_uz = COALESCE(instructions_uz, '1. Kartochkani chaqaloqning yuzidan 20-30cm masofada tuting\n2. Uni sekin chapdan o‘ngga siljiting\n3. Chaqaloq kartochkani ko‘zlari bilan kuzatishini kuzating') WHERE id = '16373dad-486f-490c-bc14-144cfd354f5f';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Mato bilan «Ku-ku» o‘yini'), description_uz = COALESCE(description_uz, 'Klassik «Ku-ku» o‘yini'), instructions_uz = COALESCE(instructions_uz, '1. Yuzingizni mato bilan yoping\n2. «Men qayerdaman?» deb ayting\n3. Matoni olib, «Ku-ku!» deb ayting\n4. Chaqaloqning yuzini ohista yoping va takrorlang') WHERE id = '58d3e4f3-7256-4eaa-901e-ce192a8aca44';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Oq-qora osma o‘yinchoq'), description_uz = COALESCE(description_uz, 'Chaqaloqning tepasiga kontrastli tasvirlarni osing'), instructions_uz = COALESCE(instructions_uz, 'Qog‘ozdan oddiy shakllarni kesib, ularni chaqaloqdan 20-30cm balandlikda osing. Chaqaloq harakatni ko‘zlari bilan kuzatsin.') WHERE id = '8c2f484b-326a-4dac-b7a4-7eb528aff395';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Stakanchalarni taxlash'), description_uz = COALESCE(description_uz, 'Stakanchalardan minoralar qurish'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloqqa stakanchalarni qanday taxlashni ko‘rsating\n2. Chaqaloq ularni yiqitsin\n3. Qayta quring va takrorlang\n4. Taxlayotganda ranglarni ayting') WHERE id = '6145784f-e184-4ae7-8691-ff33671cc7d0';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Rasmli kitob o‘qish'), description_uz = COALESCE(description_uz, 'Rasmli kitoblarni birgalikda faol o‘qish'), instructions_uz = COALESCE(instructions_uz, '1. Yorqin rasmlari bor kitoblarni tanlang\n2. Rasmlarni ko‘rsatib, ularning nomini ayting\n3. Chaqaloq sahifalarni varaqlasin\n4. Hayvonlarning ovozlariga taqlid qiling') WHERE id = '68d82e2b-fe11-4b41-af57-aa141f8eb6cc';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Shakllarni saralash o‘yini'), description_uz = COALESCE(description_uz, 'Shakllarni mos teshiklarga joylash'), instructions_uz = COALESCE(instructions_uz, '1. Shakllarni mos teshiklarga qanday joylashni ko‘rsating\n2. Avvaliga chaqaloqning qo‘lini yo‘naltiring\n3. Muvaffaqiyatini quvonch bilan olqishlang\n4. O‘ynayotganda shakllarning nomini ayting') WHERE id = '60e5d3d1-5587-48f5-99df-4e806c62490a';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Raqs kechasi'), description_uz = COALESCE(description_uz, 'Musiqa ostida birga raqsga tushish'), instructions_uz = COALESCE(instructions_uz, '1. Quvnoq musiqa qo‘ying\n2. Chaqaloqni qo‘lingizga olib raqsga tushing\n3. Chaqaloqni yerga qo‘yib, birga raqsga tushing\n4. Qarsak chaling va aylaning') WHERE id = '52245d35-3235-4e80-b73d-af4fe323ed93';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Ko‘zgu bilan qorincha mashqi'), description_uz = COALESCE(description_uz, 'Chaqaloqni qiziqtirish uchun ko‘zgu yordamida qorin bilan yotish mashqi'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloqni yumshoq joyga qorni bilan yotqizing\n2. Uning qarshisiga ko‘zgu qo‘ying\n3. Chaqaloq bilan gaplashing va boshini ko‘tarib qarashga undang') WHERE id = 'c1e1e351-1af5-4816-8f2c-de374135c16b';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Mayin massaj vaqti'), description_uz = COALESCE(description_uz, 'Chaqaloq bilan mehr rishtalarini mustahkamlash va uning rivojlanishi uchun massaj'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloqlar uchun xavfsiz moydan foydalaning\n2. Qo‘llari, oyoqlari va qornini ohista massaj qiling\n3. Massaj paytida qo‘shiq ayting yoki chaqaloq bilan gaplashing') WHERE id = 'ea46fd4e-7a05-4463-bf0d-2b9e8add8866';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Sovun pufakchalarini kuzatish'), description_uz = COALESCE(description_uz, 'Ko‘z bilan kuzatish qobiliyatini rivojlantirish uchun sovun pufakchalarini tomosha qilish'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloq yaqinida sovun pufakchalarini puflang\n2. Pufakchalarni ko‘rsatib, ularni tasvirlab bering\n3. Pufakchalar chaqaloqning terisiga tegib, ohista yorilishiga imkon bering') WHERE id = '449a2aa8-5640-4e79-b7fa-0c92027bb12c';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Turli yuzalarni o‘rganish'), description_uz = COALESCE(description_uz, 'Turli tuzilishga ega yuzalarni o‘rganish'), instructions_uz = COALESCE(instructions_uz, '1. Turli tuzilishga ega buyumlarni to‘plang\n2. Chaqaloqqa har bir buyumni ushlab ko‘rishga imkon bering\n3. Ularning tuzilishini ta’riflang: yumshoq, dag‘al, silliq') WHERE id = 'e257be70-2380-44c1-91be-9e079d4879b7';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Idish bilan o‘ynash'), description_uz = COALESCE(description_uz, 'Buyumlarni idishga solish va undan chiqarish'), instructions_uz = COALESCE(instructions_uz, '1. Xavfsiz idish va yumshoq o‘yinchoqlardan foydalaning\n2. Chaqaloqqa buyumlarni idishga qanday solishni ko‘rsating\n3. Chaqaloqni buyumlarni idishdan chiqarishga undang\n4. Qarsak chalib, uni olqishlang') WHERE id = '4d841e68-97b6-4186-be6e-26bef3df65df';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'To‘pni dumalatish'), description_uz = COALESCE(description_uz, 'To‘pni bir-biringizga dumalatish'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloqning qarshisiga o‘tiring\n2. Yumshoq to‘pni chaqaloq tomon dumalating\n3. Chaqaloqni to‘pni sizga qaytarib dumalatishga undang\n4. Chaqaloq o‘yinda qatnashganda uni olqishlang') WHERE id = '073a2084-da2c-4ef3-8a93-22136a2c77a5';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Shiqildoqni kuzatish'), description_uz = COALESCE(description_uz, 'Shiqildoqni ko‘z va quloq bilan kuzatish'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloqning e’tiborini jalb qilish uchun shiqildoqni silkiting\n2. Uni turli yo‘nalishlarda sekin harakatlantiring\n3. Chaqaloqqa uni ushlashga harakat qilishiga imkon bering') WHERE id = 'ea96ae3c-ed32-4118-b146-ecbb3a3bb763';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Telefon orqali soxta suhbat'), description_uz = COALESCE(description_uz, 'Telefon bilan rolli o‘yin'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloqqa o‘yinchoq telefon bering\n2. Unga qo‘ng‘iroq qilayotgandek bo‘ling\n3. Chaqaloqni «gapirishga» undang\n4. Navbatma-navbat gapiring') WHERE id = 'e08ba272-48b6-4a5f-b44b-0ba7da5cb808';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Mayin kuylash'), description_uz = COALESCE(description_uz, 'Chaqalog‘ingizga mayin ovozda qo‘shiq kuylang'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqni bag‘ringizga bosib, mayin alla yoki oddiy qo‘shiqlar kuylang. Chaqaloq ovozingizga qanday javob berayotganini kuzating.') WHERE id = 'a3c29297-6e01-48c7-9b34-d7d9d3af361a';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'O‘yinchoqlar bilan qorincha vaqti'), description_uz = COALESCE(description_uz, 'Qorincha vaqtida oldiga rang-barang o‘yinchoqlar qo‘ying'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqni qorni bilan yotqizing. Qo‘l uzatishi va boshini ko‘tarishiga undash uchun rang-barang o‘yinchoqlarni qo‘li yetmaydigan masofaga qo‘ying.') WHERE id = 'e0e77763-f782-46a8-bcfe-1cf276ba2cce';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Suvni sachratish vaqti'), description_uz = COALESCE(description_uz, 'Chaqaloqqa suvni qo‘llari bilan sachratishiga imkon bering'), instructions_uz = COALESCE(instructions_uz, 'Sayoz idishni iliq suv bilan to‘ldiring. Chaqaloqqa suvga tegib, uni sachratishiga imkon bering. Uni doimo diqqat bilan kuzatib turing.') WHERE id = '5cea30c3-38d1-4326-b521-b5428eba62a1';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Uchayotgan chaqaloq'), description_uz = COALESCE(description_uz, 'Chaqaloqni ehtiyotkorlik bilan havoga ko‘taring'), instructions_uz = COALESCE(instructions_uz, 'Chalqancha yoting, chaqaloqni mahkam ushlab, uchayotgandek ehtiyotkorlik bilan yuqoriga ko‘taring. Bu o‘zaro mehr rishtalarini mustahkamlash uchun juda foydali.') WHERE id = 'eb368346-4c28-48f4-acc2-82c3747e66bf';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Xazinalar savati'), description_uz = COALESCE(description_uz, 'Savatni xavfsiz uy-ro‘zg‘or buyumlari bilan to‘ldiring'), instructions_uz = COALESCE(instructions_uz, 'Turli tuzilish va shakldagi 5-10 ta xavfsiz buyumni to‘plang. Har bir buyumning nomini aytib, chaqaloqqa ularni erkin o‘rganishiga imkon bering.') WHERE id = 'ebc79f1e-7d23-4c5a-b28e-dda90e096b3a';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Qarsak qo‘shig‘i'), description_uz = COALESCE(description_uz, 'Birgalikda qo‘shiq aytib, qarsak chaling'), instructions_uz = COALESCE(instructions_uz, 'Qarsak chalib aytiladigan sodda qo‘shiqlarni kuylang. Chaqaloqqa kaftlarini bir-biriga urib, qarsak chalishga yordam bering. Bu ritmni his qilish va harakatlarni muvofiqlashtirish uchun juda foydali.') WHERE id = 'a4aa194b-9d64-4f72-8ba4-90ae6e12f0c5';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Qoshiq tashlash o‘yini'), description_uz = COALESCE(description_uz, 'Qoshiqlarni qozonga tashlang'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqqa yog‘och qoshiqlarni qozonga qanday tashlashni ko‘rsating. Unga chiqayotgan tovushni eshitib, harakatni takrorlashiga imkon bering.') WHERE id = 'b99f62da-0ba0-4a8c-a136-3eae65f486ee';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Paxta bo‘laklarini ko‘chirish'), description_uz = COALESCE(description_uz, 'Paxta bo‘laklarini bir idishdan boshqasiga ko‘chiring'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqqa ikkita kosa va paxta bo‘laklarini bering. Ularni qanday olib, bir kosadan boshqasiga ko‘chirishni ko‘rsating. Bu mayda motorikani rivojlantirish uchun juda foydali.') WHERE id = 'bf6bdf5d-9977-460c-978a-4df325af6d86';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Qog‘oz yirtish'), description_uz = COALESCE(description_uz, 'Qog‘ozni bo‘laklarga yirting'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqqa yirtish uchun yumshoq qog‘oz bering. Uning tovushi va qo‘lda sezilishi hissiy idrokni rivojlantirib, qo‘llarni mustahkamlaydi.') WHERE id = 'c80230e8-6d2c-459b-9557-6ff0795bbec7';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Karton naychali tunnel'), description_uz = COALESCE(description_uz, 'Karton naycha ichidan koptokni dumalating'), instructions_uz = COALESCE(instructions_uz, 'Karton naychani ushlab, chaqaloqqa kichik koptokni uning ichidan qanday dumalatishni ko‘rsating. So‘ng koptokning ortidan birga quving.') WHERE id = '977ee460-5cf3-4eaa-878a-9d316320f9a5';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Gubkani siqish'), description_uz = COALESCE(description_uz, 'Ho‘l gubkalarni siqib, suvini idishlarga tushiring'), instructions_uz = COALESCE(instructions_uz, 'Gubkalarni ho‘llang va chaqaloqqa suvini idishga qanday siqib tushirishni ko‘rsating. Bu qo‘l mushaklarini mustahkamlash uchun juda foydali.') WHERE id = 'df24840d-33ce-4c49-b093-3e0206c89ed5';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Patlarni puflash'), description_uz = COALESCE(description_uz, 'Patlarni puflang va ularning havoda suzishini kuzating'), instructions_uz = COALESCE(instructions_uz, 'Patlarni tekis yuzaga qo‘ying. Ularni ohista puflang va chaqaloqqa ham tutib olish yoki puflashga urinib ko‘rishiga imkon bering.') WHERE id = 'efd51de1-efff-48a2-a2e9-f6a4a3d7a2ee';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Qum bilan o‘ynash'), description_uz = COALESCE(description_uz, 'Qumni kavlang va bir idishdan boshqasiga soling'), instructions_uz = COALESCE(instructions_uz, 'Patnisni qum bilan to‘ldiring. Stakanlar va qoshiqlar bering. Chaqaloqqa qumni kavlash, bir idishdan boshqasiga solish va uning tuzilishini his qilishiga imkon bering.') WHERE id = '53ef4599-988b-4a29-8f82-c3c78d48283b';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'O‘yin xamirini ezish'), description_uz = COALESCE(description_uz, 'O‘yin xamirini ezing, dumalating va shakl bering'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqqa o‘yin xamiri bering. Uni ezish, dumalatish va barmoq bilan bosishni ko‘rsating. Shakllar yasash uchun pechenye qoliplaridan foydalaning.') WHERE id = '9a13c43a-a835-47cf-99fe-bd97a0f1562c';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Kublardan minora'), description_uz = COALESCE(description_uz, 'Kublarni imkon qadar baland taxlang'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqqa kublarni qanday taxlashni ko‘rsating. Har bir kubni sanang. Minora qulaganda birgalikda quvoning! Uni birga qayta quring.') WHERE id = '5c63d4c6-a28a-488e-84cb-86ad690cd854';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Sharflarni tortib chiqarish'), description_uz = COALESCE(description_uz, 'Sharflarni idishdan tortib chiqaring'), instructions_uz = COALESCE(instructions_uz, 'Sharflarni teshigi bor qutiga joylang. Chaqaloqqa ularni birma-bir tortib chiqarishga imkon bering. Har birining rangini ayting.') WHERE id = '00ca6e21-d67f-4f0a-a874-ef5c64e2e91a';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Suv quyish'), description_uz = COALESCE(description_uz, 'Suvni bir stakandan boshqasiga quying'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqqa ikkita stakan va suv bering. Suvni biridan boshqasiga qanday quyishni ko‘rsating. Bu harakatlarni muvofiqlashtirish uchun juda foydali.') WHERE id = '94152e25-5d19-43e0-9c7f-26f0205d234e';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Yashirilgan o‘yinchoqni topish'), description_uz = COALESCE(description_uz, 'O‘yinchoqni stakanlardan birining ostiga yashirib, toping'), instructions_uz = COALESCE(instructions_uz, '2-3 ta stakanni teskari qo‘ying. Ulardan birining ostiga kichik o‘yinchoqni yashiring. Chaqaloqdan uni topishini so‘rang.') WHERE id = '18e16dc8-b896-4c03-8b0c-c7052e294b98';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Ranglar bo‘yicha saralash'), description_uz = COALESCE(description_uz, 'Buyumlarni rangiga qarab idishlarga ajrating'), instructions_uz = COALESCE(instructions_uz, 'Turli rangdagi buyumlardan (kublar, to‘plar, qopqoqlar) foydalaning. Idishlarni qo‘yib, boladan buyumlarni rangiga qarab saralashini so‘rang.') WHERE id = 'a9054a6e-ef97-45fa-aea0-e0e0cc640bc3';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Tana qismlari o‘yini'), description_uz = COALESCE(description_uz, 'Tana qismlarini ko‘rsating va nomini ayting'), instructions_uz = COALESCE(instructions_uz, 'Burun, quloq va ko‘zlaringizga tegib, ularning nomini ayting. Boladan sizga taqlid qilishini so‘rang. Bosh, yelka va tizzalar haqidagi qo‘shiqni birga kuylang.') WHERE id = '07108cc6-ef41-4d92-ad52-d3d9ab5b5c1a';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Menga ergashing'), description_uz = COALESCE(description_uz, 'Harakatlarni birgalikda takrorlang'), instructions_uz = COALESCE(instructions_uz, 'Oddiy harakatlarni bajaring: sakrang, qarsak chaling, aylaning, oyoqlaringizni yerga uring. Boladan sizga ergashishini so‘rang. Keyin unga boshchilik qilishga imkon bering.') WHERE id = '61ed8f13-2ee8-4bf5-b395-427c971b2b93';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Pazl vaqti'), description_uz = COALESCE(description_uz, 'Shakllardan iborat oddiy pazllar'), instructions_uz = COALESCE(instructions_uz, 'Bolaga 3-5 bo‘lakli oddiy pazl bering. Shakllarni moslashtirishiga yordam bering. Har bir bo‘lakni to‘g‘ri joylashtirganida uni maqtang.') WHERE id = '407aee71-093f-47d5-be98-f518ebc93883';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Stikerlar bilan o‘yin'), description_uz = COALESCE(description_uz, 'Stikerlarni qog‘ozga yopishtirish'), instructions_uz = COALESCE(instructions_uz, 'Bolaga stikerlar va qog‘oz bering. Stikerlarni ajratib olish mayda motorikani rivojlantiradi. Birgalikda rasm yarating.') WHERE id = 'ab3c62c3-5d7c-4ac6-ad8b-ac7d714a3ea7';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Tabiat qo‘ynida sayr'), description_uz = COALESCE(description_uz, 'Barglar va toshlarni yig‘ish'), instructions_uz = COALESCE(instructions_uz, 'Qisqa sayrga chiqing. Barglar, toshlar va gullarni yig‘ing. Ularning ranglari, shakllari va tuzilishi haqida suhbatlashing.') WHERE id = '62e05487-3056-4592-b1ea-0b4cac9e8f41';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Nog‘ora chalish'), description_uz = COALESCE(description_uz, 'Idishlar va qoshiqlar yordamida ritm yaratish'), instructions_uz = COALESCE(instructions_uz, 'Idishlarni teskari qo‘yib, nog‘ora sifatida ishlating. Yog‘och qoshiqlardan nog‘ora tayoqchalari sifatida foydalaning. Birgalikda turli ritmlar yarating.') WHERE id = '55dd9c21-79eb-44fa-92b7-7a1329f2835d';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Guruchli sensor quti'), description_uz = COALESCE(description_uz, 'Guruchni qo‘llar va turli vositalar yordamida o‘rganish'), instructions_uz = COALESCE(instructions_uz, 'Idishni guruch bilan to‘ldiring. Stakanchalar, qoshiqlar va kichik o‘yinchoqlar qo‘shing. Bolaga guruchni olib solish, quyish va ichidan narsalarni izlashga imkon bering.') WHERE id = '1edc1365-0580-41a0-86fb-6e413cd251cc';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Adyolda tebratish'), description_uz = COALESCE(description_uz, 'Chaqaloqni adyolda ohista tebratish'), instructions_uz = COALESCE(instructions_uz, 'Ikki katta odam ichida chaqaloq yotgan adyolning burchaklaridan ushlaydi. Qo‘shiq aytib, uni ohista yon tomondan yon tomonga tebrating.') WHERE id = '8055a758-49ff-45d1-880c-15da141896b2';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Musiqa asboblari'), description_uz = COALESCE(description_uz, 'Oddiy asboblar yordamida musiqa yaratish'), instructions_uz = COALESCE(instructions_uz, '1. Chaqaloqqa shaqildoq kabi xavfsiz musiqa asboblarini bering\n2. Musiqa qo‘yib, unga mos ravishda asbobni silkiting\n3. Birgalikda qo‘shiqlar kuylang\n4. Chaqaloqqa turli tovushlarni o‘rganishga imkon bering') WHERE id = '23d036b7-20b9-4a05-a223-49a6d472d380';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Sensorli shisha'), description_uz = COALESCE(description_uz, 'Rangli suyuqlik bilan to‘ldirilgan shisha chaqaloqning diqqatini jalb qiladi'), instructions_uz = COALESCE(instructions_uz, 'Plastik shishaga rangli suv yoki yaltiroq materiallar soling. Qopqog‘ini mahkam yoping. Chaqaloqqa ko‘rsating va dumalatishiga ruxsat bering.') WHERE id = '75be8860-ac3f-4a9e-87c7-5122de70d0a6';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Qo‘ldan ushlash va changallash'), description_uz = COALESCE(description_uz, 'Chaqaloq barmoqlaringizni changallashni mashq qilsin'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloq changallashi uchun barmoqlaringizni uzating. Changallash kuchini rivojlantirish uchun sekin o‘zingizga torting.') WHERE id = 'f5161cf6-25f1-4eda-b672-91e0dc7075f4';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Matolarni his qilish'), description_uz = COALESCE(description_uz, 'Chaqaloq turli matolarga tegib ko‘rsin'), instructions_uz = COALESCE(instructions_uz, 'Yumshoq, dag‘al, silliq va momiq matolarni to‘plang. Har birining tuzilishini aytib, chaqaloqqa ularni ushlab, his qilishiga imkon bering.') WHERE id = 'd62cf27d-4570-4976-85c1-ea88d0004a93';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Shaqildoqni silkitish'), description_uz = COALESCE(description_uz, 'Chaqaloq tovush chiqarish uchun shaqildoqni silkitadi'), instructions_uz = COALESCE(instructions_uz, 'Chaqaloqqa shaqildoq bering va uni qanday silkitishni ko‘rsating. Chaqaloq sizni takrorlaganida uni maqtang. Turli ritmlarni sinab ko‘ring.') WHERE id = 'b0958c0b-1439-4e5e-8443-a1ae673d0845';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Muz bo‘lakchalari bilan rasm chizish'), description_uz = COALESCE(description_uz, 'Qog‘ozga rangli muz bo‘lakchalari bilan rasm chizing'), instructions_uz = COALESCE(instructions_uz, 'Oziq-ovqat bo‘yog‘i qo‘shilgan suvni muzlatib qo‘ying. Chaqaloq rang-barang naqshlar yaratishi uchun muzni qog‘oz ustida yurgizishiga ruxsat bering.') WHERE id = '2fb728ab-9f62-4c72-8288-051a6eb7e14e';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Tuxum qutisi bilan saralash'), description_uz = COALESCE(description_uz, 'Kichik buyumlarni tuxum qutisining kataklariga saralang'), instructions_uz = COALESCE(instructions_uz, 'Xavfsiz kichik buyumlarni yaqinroqqa qo‘ying. Chaqaloqqa tuxum qutisining har bir katagiga bittadan buyum solishni ko‘rsating. Joylashtirish davomida sanab boring.') WHERE id = '4b4383db-2e14-4720-b060-17d8ff1704ee';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Karton uycha'), description_uz = COALESCE(description_uz, 'Katta qutidan o‘yin uychasi yasang'), instructions_uz = COALESCE(instructions_uz, 'Katta qutining deraza va eshiklarini kesib oching. Uni birgalikda bezating. Bolaga uycha ichida o‘ynashiga imkon bering.') WHERE id = '25a4322e-633e-4a3e-9979-250fedcd62b2';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Tunneldan emaklab o‘tish'), description_uz = COALESCE(description_uz, 'Ko‘rpachadan yasalgan tunneldan emaklab o‘ting'), instructions_uz = COALESCE(instructions_uz, 'Tunnel yasash uchun stullar ustiga ko‘rpachalarni yoping. Bolani tunneldan emaklab o‘tishga undang. Oxiriga o‘yinchoqlar qo‘ying.') WHERE id = 'ae4fecd1-f9d4-4188-aac6-c77af614920c';
