UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Barmoqlar bilan rasm chizish'), description_uz = COALESCE(description_uz, 'Qog‘ozga barmoqlar bilan rasm chizing'), instructions_uz = COALESCE(instructions_uz, 'Qog‘ozga xavfsiz bo‘yoq surting. Bolaga barmoqlari va qo‘llari bilan rasm yaratishiga imkon bering. Ranglar haqida suhbatlashing.') WHERE id = '48b54a1e-5f01-444e-ac3a-7700916922cc';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Kir yuvishda yordamchi'), description_uz = COALESCE(description_uz, 'Paypoqlarni rangiga qarab ajrating'), instructions_uz = COALESCE(instructions_uz, 'Turli rangdagi paypoqlarni aralashtirib qo‘ying. Chaqaloqdan rangiga qarab mos juftlarini topishini so‘rang.') WHERE id = 'c6f840ec-4a7f-4cab-a710-22e0769b14e1';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Soyalar o‘yini'), description_uz = COALESCE(description_uz, 'Devorda soya shakllarini yarating'), instructions_uz = COALESCE(instructions_uz, 'Qorong‘i xonada fonar yordamida devorda qo‘l soyalarini hosil qiling. Hayvonlar va buyumlar shaklini yarating.') WHERE id = '236f386f-6b5f-4108-a856-812efa52e5d0';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'O‘yinchoqlarni yuvish'), description_uz = COALESCE(description_uz, 'O‘yinchoqlarni sovunli suvda yuving'), instructions_uz = COALESCE(instructions_uz, 'Tog‘orani iliq sovunli suv bilan to‘ldiring. Chaqaloqqa gubka va yuvish uchun o‘yinchoqlar bering. Yuvish paytida har bir o‘yinchoqning nomini ayting.') WHERE id = '3bde9afc-8036-426d-ae82-c76b546162fc';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Sanash o‘yini'), description_uz = COALESCE(description_uz, 'Buyumlarni birgalikda sanang'), instructions_uz = COALESCE(instructions_uz, 'Kubiklar kabi kichik buyumlarni to‘plang. Ularni birgalikda birma-bir sanang. 2, 3, 4 tadan guruhlarga ajrating.') WHERE id = '97af70f2-c634-4bfa-bd72-86e31f80ae2a';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Hayvonlarning ovozlari'), description_uz = COALESCE(description_uz, 'Hayvonlarning ovozlariga birgalikda taqlid qiling'), instructions_uz = COALESCE(instructions_uz, 'Kitobdagi hayvonlar rasmlarini ko‘rsating. Har bir hayvonning ovoziga taqlid qiling. Chaqaloqni sizga taqlid qilishga undang.') WHERE id = 'ff72da83-28a7-4824-919d-7d40add23a69';
UPDATE public.play_activities SET title_uz = COALESCE(title_uz, 'Yostiqlar tog‘i'), description_uz = COALESCE(description_uz, 'Yostiqli to‘siqlardan oshib o‘ting'), instructions_uz = COALESCE(instructions_uz, 'Yostiq va bolishlardan to‘siqlar yo‘lagini yasang. Chaqaloqni ularning ustidan oshib va orasidan o‘tishga undang.') WHERE id = '7a752652-ca03-444b-9521-72269d1948b7';

