UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Estrogen gormoni tuxum hujayrangizning hajman kattalashishini qo‘llab-quvvatlash bilan birga, mitoz bo‘linishni tezlashtirib, bachadon devorining ham ichki, ham tashqi tomondan qalinlashishini hamda urug‘lanadigan tuxumning bachadon ichiga xavfsiz tarzda birikishini ta’minlaydi. Shuningdek, urug‘lanadigan tuxum hujayrangiz uchun optimal sharoit yaratish maqsadida bachadon hujayralariga ko‘plab qon tomirlari kelishini ta’minlab, to‘qima suyuqligi miqdorini oshiradi. Bu gormon, shuningdek, qinning uzayishini ta’minlaydi va bachadon ichki qavatidagi hujayralarni rag‘batlantirib, sirpanchiqlikni ta’minlovchi shilliq modda ajratadi.'), baby_message_uz = COALESCE(baby_message_uz, 'Onajon, sizga bir sirni aytaymi? 🤫 Tanangizdagi o‘sha minglab hujayralardan biri aynan "MEN" bo‘lish uchun bellashishni boshladi! U hozir o‘zi mustaqil ravishda o‘smoqda va otamdan keladigan ikkinchi yarmi bilan uchrashadigan kunni sabrsizlik bilan kutmoqda. Bizning o‘sha buyuk uchrashuvimizga taxminan 1 hafta qoldi. Men juda hayajondaman, siz-chi? Sizning iliq bag‘ringizni sog‘indim.'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Shakar kukuni donasi'), body_changes_uz = COALESCE(body_changes_uz, 'Birinchi hafta oxiriga kelib tanangizdagi gormonal o‘zgarishlar eng yuqori darajaga yaqinlashadi. Estrogen darajasining oshishi bilan bachadonning ichki devori allaqachon to‘liq tiklangan va qalinlashishda davom etmoqda. Shu kunlarda o‘zingizni yanada kirishimli, tetik va o‘zingizga ishongan holda his qilishingiz mumkin. Libidoning oshishi tanangiz tabiiy ravishda reproduktiv davrga, ya’ni homilador bo‘lish ehtimoli eng yuqori bo‘lgan kunlarga tayyorlanayotganining belgisidir.;;;
Homiladorlik sog‘lom kechishi uchun homiladorlikdan oldin muntazam tibbiy ko‘riklardan o‘tishingiz lozim.;;;
Homiladorlikdan oldingi tibbiy ko‘rik, ayniqsa, katta yoshda yoki biror surunkali kasallik mavjud bo‘lsa, yanada muhim ahamiyat kasb etadi. Homiladorlikdan oldingi ko‘rikda siz va turmush o‘rtog‘ingizning oilaviy anamnezi hisobga olinib, irsiy xususiyatga ega bo‘lishi mumkin bo‘lgan kasalliklar bor-yo‘qligi tekshirilishi kerak. Shifokoringiz ginekologik ko‘rik va ultratovush tekshiruvi orqali bachadon hamda tuxumdonlaringizni baholashi bachadondagi mioma va polip kabi muammolarni aniqlash uchun muhimdir. Agar shifokoringiz zarur deb hisoblasa, "smear testi" deb ataladigan bachadon bo‘ynidan surtma olish amaliyoti o‘tkazilishi kerak. Shuningdek, laboratoriya tahlillari orqali jigar va buyrak faoliyati, qandli diabet, gepatit va toksoplazmoz kabi surunkali kasalliklar bor-yo‘qligi tekshirilishi lozim. Ayniqsa, homiladorlikdan oldingi tekshiruvlarda shu paytgacha qo‘llangan homiladorlikdan saqlanish usullari hisobga olinishi kerak. Uzoq vaqt qabul qilingan kontratseptiv tabletkalar ma’lum muddat davomida fertilitetni cheklashi mumkin. Ayollarning taxminan 50%-i oxirgi tabletkani qabul qilganidan kamida 6 oy o‘tgach homilador bo‘lishi mumkin.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Birinchi haftani muvaffaqiyatli yakunlaganingiz uchun o‘zingizni mukofotlang, ammo buni sog‘lom usulda qiling. Tanangizdagi kislorod miqdorini oshirish uchun ochiq havoda uzoq sayr qiling; kislorodning yuqori darajasi tuxum hujayrasi metabolizmiga ijobiy ta’sir ko‘rsatadi. Ratsioningizga antioksidantlarga boy rang-barang mevalarni (masalan, chernika, malina) qo‘shing. Bu moddalar tuxum hujayrasini oksidlanish stressidan himoya qilib, uning sog‘lomroq urug‘lanishiga zamin yaratadi.') WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Bachadoningizda joylashgan fallop naylari bir juft uzun va tor kanaldan iborat bo‘lib, tuxumdonlaringizda yetilgan tuxum hujayralarini bachadonning ichki qismiga yetkazib beradigan reproduktiv tizim a’zolaridan biridir. Bu a’zo tuxum yo‘li yoki bachadon naylari deb ham ataladi. Fallop naylari shu oyda tanlangan tuxum hujayrasi kurtaklaridan yetilgan tuxum hujayrasining bachadonga yetkazilishini ta’minlaydi. Taxminan 12 sm uzunlikdagi fallop naylarini qoplab turadigan shilliq qavat spermatozoidlarning tuxum hujayrasi tomon harakatlanishi va tirik qolishiga yordam beradigan ajralmalar ishlab chiqaradi. Bu ajralmalar tarkibidagi ayrim moddalar spermatozoidlarning kisloroddan foydalanishi uchun nihoyatda muhim bo‘lib, tuxum hujayrasining oziqlanishi va urug‘lanishdan keyingi rivojlanishiga yordam beradi.'), baby_message_uz = COALESCE(baby_message_uz, 'Salom, mening olamim! 🌍 Tanangiz men uchun tayyorgarlikni yanada jadallashtirdi. Balki kundalik hayotingizda buni sezmayotgandirsiz, ammo ichkarida qizg‘in ish ketmoqda. Bularning barchasi mening qulayligim, xavfsizligim va sog‘ligim uchun. Sizning tanangiz dunyodagi eng mukammal va aniq ishlaydigan laboratoriyadir. Sizdan minnatdorman!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Shakar kukuni donasi'), body_changes_uz = COALESCE(body_changes_uz, 'Ikkinchi haftaning birinchi kunida estrogen gormoni ustunlik qila boshlaydi. Bu gormon ta’sirida bachadonning ichki qavati qon tomirlari bilan yanada ko‘proq ta’minlanib, yumshay boshlaydi. Servikal suyuqlik (bachadon bo‘yni shilliq ajralmasi) asta-sekin yanada tiniq va sirpanchiq holga keladi; bu spermatozoidlarning bachadon ichida bir necha kun tirik qolishi uchun ideal muhitdir. Bu bosqichda tana haroratingiz barqarorlashadi, ammo ovulyatsiya yaqinlashishi bilan o‘zgarishga tayyorlanadi.;;;
Homiladorlik belgilari bilan yaqinlashayotgan hayz belgilari ko‘pincha bir-biriga o‘xshash bo‘lgani sababli ularni adashtirish mumkin. Bu belgilardan biri ko‘kraklarning to‘lishishi va shishishidir. Ko‘plab ayollar bu holatni hayz oldi belgilariga qaraganda kuchliroq his qilishlari mumkin. Bundan tashqari, holsizlik va charchoq odatdagi hayz davridagidan kuchliroq sezilishi mumkin.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Homilador bo‘lish ehtimoli oshadigan kunlarga kirganingiz sababli tanangizning pH muvozanatini saqlash muhim. Ishqoriy oziq-ovqatlarni (limonli suv, yashil sabzavotlar) ko‘proq iste’mol qilish tanadagi ichki muhitni yanada qulaylashtiradi. Agar hali boshlamagan bo‘lsangiz, bazal tana haroratingizni har kuni bir vaqtda o‘lchab, ovulyatsiya kuningizni aniqroq belgilashingiz mumkin. Ko‘p suv ichishni unutmang, chunki bu servikal suyuqlikning sifati uchun hal qiluvchi ahamiyatga ega.') WHERE id = 'abcdc9dc-69bf-4833-9582-4fb6ef1276bd';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Ayollik gormonlaridan biri bo‘lgan progesteronning asosiy vazifasi bachadonni homiladorlikka tayyorlashdir. Ayni paytda oylik hayz siklini ham tartibga soladigan bu gormon tanangiz uchun juda katta ahamiyatga ega. Homiladorlik yuz berishidan oldin buning uchun sharoit yaratish va urug‘langan tuxum hujayrasining bachadonga osonroq joylashishini ta’minlash maqsadida bachadon to‘qimasida o‘zgarishlar yuzaga keltiradigan ushbu gormon homiladorlik boshlanganidan so‘ng chaqaloqning bachadonga birikishi bilan miqdorini oshirib, faoliyatini davom ettiradi.;;;
Siz hozir bo‘lgan, ya’ni ovulyatsiyadan oldingi davrda tanangizdagi progesteron gormoni darajasi 1 nq/ml-dan kam. Ovulyatsiya paytida bu gormon miqdori 5-20 nq/ml-gacha ko‘tariladi. Agar homiladorlik yuz bersa, birinchi trimestrda qoningizda ushbu gormon miqdori 11-90 nq/ml, ikkinchi trimestrda 25-90 nq/ml, uchinchi trimestrda esa 50-300 nq/ml oralig‘ida bo‘ladi.'), baby_message_uz = COALESCE(baby_message_uz, 'Qalbingiz ovoziga quloq tuting. ❤️ Men hali yulduz changidekman, ammo sevgingiz meni hayotga chorlamoqda. Tanangiz men uchun eng yaxshi, eng sifatli tuxum hujayrasini tayyorlamoqda. Otam bilan orangizdagi sevgi mening dunyoga kelishimga sabab bo‘ladi. Siz sevganingiz sari tanangiz mo‘jizalar yaratadi. Men tomon kelayotganingiz uchun rahmat!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Shakar kukuni donasi'), body_changes_uz = COALESCE(body_changes_uz, 'Birinchi trimestrga kiruvchi homiladorlikning 2-haftasida bachadoningizning ikki yonida joylashgan tuxumdonlardagi tuxum hujayrasining rivojlanishi davom etadi. Bu haftada endometriy deb ataladigan bachadonning ichki qavati gormonlar ta’sirida qalinlashishda davom etadi. Bachadon qavatining bunday qalinlashishidan maqsad urug‘lanish sodir bo‘lgach, chaqalog‘ingizni shakllantiradigan hujayralarning bachadon ichiga osonlik bilan birikishini ta’minlashdir. Qalinlashgan endometriy qavati bu sohaning qon bilan yaxshi ta’minlanishiga imkon berib, chaqalog‘ingiz uchun eng maqbul sharoitdagi uya hosil qiladi. Agar urug‘lanish sodir bo‘lmasa va homiladorlik yuzaga kelmasa, bu qavat har oy hayz paytida qon ketishi bilan tanadan chiqariladi. Ushbu sikl har oy bir xil tarzda takrorlanadi. Homiladorlik yuzaga kelishi va sog‘lom davom etishi uchun bachadon ichki qavati butunlay sog‘lom bo‘lishi kerak. Shu sababli bachadonning ichki qavati ham qalinligi, ham tuzilishi jihatidan shifokoringiz tomonidan baholanishi muhimdir.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Bu davrda yodga boy mahsulotlarni (dengiz mahsulotlari, yodlangan tuz) iste’mol qilish ham qalqonsimon bezingiz salomatligi, ham bo‘lajak chaqaloqning miya rivojlanishi uchun muhimdir. Tanangizning egiluvchanligini oshirish va chanoq sohasidagi qon aylanishini rag‘batlantirish uchun yengil gimnastika mashqlarini bajaring. Shuningdek, terining namligini saqlash uchun tabiiy yog‘lardan foydalanishingiz mumkin, chunki gormonal o‘zgarishlar teringizning sezgirligini oshirishi mumkin.') WHERE id = '254bd95f-c06d-46bb-b688-86a0b498dcb9';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Har oy hayz davringizda bachadoningizdagi tuxum hujayralar zaxirasidan bittasi yetilib, urug‘lanishga tayyor holga keladi. Agar gormonlaringiz tuxum hujayraning yetilishini ta’minlamasa, homiladorlik yuz bermaydi. Sizdagi bu tuxum hujayralar hali tug‘ilishingizdan oldin bachadoningizda hosil bo‘lgan millionlab birlamchi jinsiy hujayralardan rivojlanadi va menopauzagacha har bir hayz siklida ulardan bittasi ishlatiladi.'), baby_message_uz = COALESCE(baby_message_uz, 'Salom, mening go‘zal Onajonim! 🌟 O‘zingizni ancha yaxshi va tetik his qila boshladingizmi? Men uchun tayyorlanayotgan o‘sha maxsus xona (bachadoningiz) tozalanish arafasida, eski devorlari butunlay ko‘chib tushdi. Tez orada u yerda men uchun yumshoq, iliq joy hozirlanadi va men u yerda 9 oy davomida xavfsiz qolaman. Sizning tanangiz mening uyim bo‘ladi. Siz bilan uchrashadigan kunni, yuragim sizning yuragingiz ostida uradigan lahzani sabrsizlik bilan kutyapman!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Ko‘rinmas zarracha'), body_changes_uz = COALESCE(body_changes_uz, 'Bu kunlarda hayz qon ketishi kamayib boradi. Tanangizda estrogen gormoni faolroq ko‘paya boshlaydi. Bu ko‘payish bachadon ichki qavatining qayta tiklanishi va qalinlashishi uchun signal vazifasini bajaradi. Gipofiz bezi tuxumdonlarga "ko‘proq ishlang" degan xabar yuboradi. Qon aylanishi tezlashadi va tanangiz ehtimoliy homiladorlikka ham jismonan, ham gormonal jihatdan tayyorlanish uchun bor kuchi bilan ishlaydi. Kayfiyatingiz yaxshilanadi, charchoq yo‘qoladi, teringiz yanada yorqin va tetik ko‘rina boshlaydi. Tanangiz "Qayta boshlash" rejimiga o‘tib, yangi davrga qadam qo‘yadi.;;;
Qabul qilayotgan dorilaringizning homiladorlikka ta’sirini hozirdanoq shifokoringiz bilan muhokama qilishingiz yuzaga kelishi mumkin bo‘lgan muammolarning erta oldini olish uchun muhimdir. Ayrim dorilar homiladorlik davrida, ayniqsa chaqalog‘ingiz shakllanadigan embrional rivojlanish haftalarida ba’zi anomaliyalarga olib kelishi mumkin. Qalqonsimon bez, qandli diabet va ayrim metabolik kasalliklarni davolashda qo‘llanadigan dorilar chaqalog‘ingizga zarar yetkazmasligi mumkin, biroq ayniqsa husnbuzarga qarshi va ayrim psixiatrik dorilar chaqaloqlarda og‘ir anomaliyalarga sabab bo‘lishi ma’lum.;;;
Shuningdek, homiladorlikdan oldin zarur tahlillarni topshirish orqali umumiy qon tahlili (gemogramma), temir tanqisligi, vitaminlar darajasi, irsiy kasalliklar, qalqonsimon bez gormonlari, siydik tahlilida infeksiya mavjudligi, gepatit B, toksoplazma, qizilcha, sifilis va OIV mavjudligi yoki ularga qarshi immunitetingiz holati aniqlanadi hamda zarurat tug‘ilsa, tegishli choralar ko‘rilishi mumkin.;;;
Bundan tashqari, farzandli bo‘lishni rejalashtirayotgan bo‘lsangiz, rioya qilishingiz kerak bo‘lgan birinchi qoida homiladorlikdan oldin chekishni tashlashdir. Tadqiqotlar tamaki iste’moli ayollarda fertillikni, erkaklarda esa spermatozoidlar sonini kamaytirishini ko‘rsatadi.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Bu kunlarda rux va magniyga boy mahsulotlarga (yong‘oq, funduk, urug‘lar) ustunlik berish tuxum hujayralarning sog‘lom yetilishiga yordam beradi. Stressdan uzoq bo‘lish uchun qisqa meditatsiyalar qiling, chunki stress gormonlari homiladorlik uchun zarur gormonal muvozanatga salbiy ta’sir ko‘rsatishi mumkin. Shuningdek, tanangizning pH muvozanatini saqlash uchun qayta ishlangan, shakarli mahsulotlardan saqlaning.') WHERE id = '65c15460-76e7-4ea7-90a9-a58b6acebcfe';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Bachadon ichidagi barcha birlamchi tuxum hujayralar tugagach, menopauza deb ataladigan holat boshlanadi. Menopauza — birlamchi tuxum hujayralar faolligini yo‘qotishi natijasida har oy sodir bo‘ladigan hayzning butunlay to‘xtashidir. Dunyo bo‘yicha menopauza yoshi 45-55 oralig‘ida o‘zgaradi.  Biroq ayrim hollarda bu yoshga yetmasdan erta menopauza boshlanishi mumkin. Erta menopauza — hayzning 45 yoshdan oldin to‘xtashi. Ayrim ayollar hatto 20 yoshlarida ham menopauza davriga o‘tishi mumkin. Erta menopauzaga sababi noma’lum holatlar, ayrim autoimmun kasalliklar, radioterapiya, kimyoterapiya, og‘ir infeksiyalar, atrof-muhit omillari, abort va homila tushishi, tez-tez homilador bo‘lish, haddan tashqari semizlik va og‘ir darajadagi gipotireoz kabi omillar sabab bo‘lishi mumkin. Bundan tashqari, chekish, ruhiy travmalar, sovuq iqlim va og‘ir atrof-muhit sharoitida yashash ham menopauza boshlanishini tezlashtirib, uning yoshini sezilarli darajada pasaytirishi mumkin.'), baby_message_uz = COALESCE(baby_message_uz, 'Bugun oynaga qaraganingizda albatta tabassum qiling! 😊 Chunki tanangiz ajoyib ishni bajaryapti — u yangi hayot yaratishga tayyorlanyapti. Biz hali jismonan birlashmagan bo‘lsak-da, ruhan allaqachon bir-birimizga bog‘langanmiz. Men sizni, siz esa meni tanladingiz. Tanangiz har kuni mening kelishimga, o‘sha mo‘jizaviy uchrashuvga (urug‘lanishga) yana bir qadam yaqinlashmoqda. Sizga ishonaman, Onajon!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Ko‘rinmas zarracha'), body_changes_uz = COALESCE(body_changes_uz, 'Bugun ko‘plab ayollar uchun hayz davrining so‘nggi kunidir. Tanangizdagi estrogen darajasi sezilarli ravishda ko‘tarilishda davom etadi. Bu ko‘tarilish bachadon ichki qavatining tez tiklanishi va yangi bir "uya" shakllanishiga xizmat qiladi. Bachadon bo‘ynidagi bezlar spermatozoidlarning osonroq harakatlanishi uchun maxsus suyuqlik ajratishga tayyorlanadi. Moddalar almashinuvi biroz tezlashadi va o‘zingizni tetikroq his qila boshlashingiz mumkin.;;;
Homiladorlik davrida alkogol iste’mol qilishning xavfsiz deb belgilangan hech qanday miqdori yo‘q. Shu sababli homiladorlikdan oldin va homiladorlik davomida alkogol iste’mol qilishdan saqlanishingiz kerak. Alkogol iste’moli, ayniqsa homiladorlikning birinchi trimestrida homila tushishi, keyingi bosqichlarda esa o‘lik tug‘ilish xavfini oshiradi. Bundan tashqari, alkogolni haddan tashqari ko‘p iste’mol qilish fetal alkogol sindromi deb ataladigan holatga, chaqaloqda yuz deformatsiyalari va og‘ir aqliy rivojlanishdan ortda qolishga olib kelishi mumkin. ;;;
Mamlakatimizda bo‘lajak onalar orasida alkogol iste’moli keng tarqalmagani va bu holatning saqlanib qolishi jamoat salomatligi nuqtayi nazaridan nihoyatda muhimdir.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Hayz tugagani sababli tanangizning yangilanish energiyasidan foydalanib, muntazam jismoniy faollikka (yengil yugurish yoki pilates) e’tibor qarating. Bu davrda D vitamini darajasini tekshirtirish juda muhim, chunki ushbu vitamin tuxumdonlar faoliyati va kelajakdagi implantatsiyaga bevosita ta’sir qiladi. Ratsioningizga omega-3 yog‘ kislotalarini (baliq, zig‘ir urug‘i) qo‘shing; bu bachadon sohasida qon aylanishini yaxshilaydi va tuxum hujayra sifatini oshiradi.') WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Bu hafta birlamchi tuxum hujayralaringizdan biri gormonlar yordamida tuxumdoningizda yetilishda davom etadi. Tuxum hujayrangizning yetilishi va urug‘lanishga tayyor holga kelishida miyangizdagi gipotalamus sohasi, gipofiz bezi va tuxumdonlaringizdan ajraladigan gormonlar ishtirok etadi. Gipofiz bezidan ajraladigan FSH gormoni tanlangan birlamchi tuxum hujayraning yetilishi va urug‘lanishga tayyor holga kelishini ta’minlab, tuxum hujayradan estrogen ajralishini rag‘batlantiradi. Gipofiz bezidan ajraladigan boshqa gormon — LH esa yetilgan tuxum hujayrangizning follikuladan chiqishini, ovulyatsiya sodir bo‘lishini va yorilgan follikulaning "sariq tana"ga aylanishini ta’minlaydi.'), baby_message_uz = COALESCE(baby_message_uz, 'Salom! Bugun ichingizda go‘yo yangi bahor boshlanayotgandek, shunday emasmi? 🌱 Aslida, rostdan ham shunday! Tuxumdonlaringizda mitti bir "men" uyg‘onib, o‘sishga harakat qilyapman. Men hali atigi bitta hujayraman, ammo sizning bir bo‘lagingizman. Siz baxtli bo‘lganingizda, kulganingizda men ham kuchayaman. O‘zingizni asrang, Onajon, chunki siz mening kelajagimsiz!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Ko‘rinmas zarracha'), body_changes_uz = COALESCE(body_changes_uz, 'Hayz qon ketishi butunlay tugagani uchun tanangiz "follikulyar faza"ning eng faol bosqichiga o‘tadi. Estrogen gormoni ko‘payishi tufayli bachadon ichki qavati silliq va oziq moddalariga boy holga kela boshlaydi. Teringizda yorqinlik, sochlaringizda esa jonlanishni sezishingiz mumkin; bu estrogenning tashqi ko‘rinishga ta’siridir. Bachadon bo‘yni shilliq ajralmasi asta-sekin tiniqlashib, cho‘ziluvchan bo‘la boshlaydi, bu esa fertil kunlar yaqinlashayotganining biologik belgisidir.;;;
Homiladorlikka tayyorlanayotgan ushbu kunlarda chaqalog‘ingiz salomatligi va homiladorlikni sog‘lom o‘tkazishingiz uchun sog‘lom ovqatlanish tartibini shakllantirishingiz nihoyatda muhim. Homiladorlikdan oldin sog‘lom va muvozanatli ovqatlanishni boshlash juda muhimdir. Homiladorlik davrida ayol vazni hayotidagi eng yuqori ko‘rsatkichga yetishi mumkinligini hisobga olsak, ovqatlanish masalasi yanada katta ahamiyat kasb etadi. Homilador bo‘lishdan oldin vazningiz sog‘lom me’yorda bo‘lishi kerak. Juda ozg‘in yoki ortiqcha vazn bilan homilador bo‘lish homiladorlik davomida yuqori qon bosimi va u bilan bog‘liq preeklampsiya deb ataladigan homiladorlik asorati, gestatsion diabet, yurak urishini kuchli his qilish va charchoq kabi ko‘plab muammolarni keltirib chiqarishi mumkin. Shu sababli, shu kunlarda boshlaydigan jismoniy mashqlar va ovqatlanish dasturi orqali tanangizni homiladorlik davriga tayyorlashingiz foydali bo‘ladi.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Ortib borayotgan energiyangizni boshqarish va gormonal muvozanatni qo‘llab-quvvatlash uchun qondagi qand miqdorini barqaror saqlaydigan murakkab uglevodlarga (suli, butun donli bug‘doy mahsulotlari) ustunlik bering. Bu davrda organizmni toksinlardan tozalash uchun ko‘p miqdorda yashil bargli sabzavotlardan tayyorlangan salatlar iste’mol qiling. Organizmning ruxga bo‘lgan ehtiyojini qondirish tuxum hujayraning bo‘linish qobiliyati uchun muhimdir; shu sababli bir necha dona xom qovoq urug‘ini iste’mol qilish foydali bo‘lishi mumkin.') WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Bugun so‘nggi hayzingiz boshlangan birinchi kundir. Homiladorlik davomida asos qilib olinadigan homiladorlik taqvimi siz taxmin qilgan jinsiy aloqa va urug‘lanish kuniga ko‘ra emas, balki so‘nggi hayz boshlangan birinchi kunga ko‘ra hisoblanadi. Homiladorlik, ya’ni tuxum hujayraning spermatozoid bilan urug‘lanishi odatda so‘nggi hayz boshlangan kundan o‘rtacha 14-15 kun o‘tib sodir bo‘ladi. Shunga qaramay, shifokoringiz homiladorlik haftasini hisoblashda ushbu sanani emas, undan taxminan 2 hafta oldingi hayz sanasini asos qilib oladi.;;;
Homiladorlik haftasi aniqlangach, 40 haftalik homiladorlikning yakuni, ya’ni taxminiy tug‘ruq sanasi "Negele usuli" deb ataladigan tizim yordamida hisoblanadi. Negele usuliga ko‘ra, hayz qon ketishi boshlangan birinchi kunga 7 kun qo‘shiladi va 3 oy ortga qaytiladi. Hosil bo‘lgan sana sizning taxminiy tug‘ruq sanangiz hisoblanadi. Shu bilan birga, homiladorliklarning taxminan 80% 40 haftalik davr tugamasdan, 38-haftada tug‘ruq bilan yakunlanadi.'), baby_message_uz = COALESCE(baby_message_uz, 'Salom, mening go‘zal Onam! ❤️ Balki hozircha meni jismonan his qilmayotgandirsiz, ammo katta sarguzashtimizning "ortga sanog‘i" rasman bugun boshlandi. Shifokorlar bu kunni bizning "birinchi kunimiz" deb hisoblashadi, chunki tanangiz mening kelishimga tayyorlanmoqda. Hozir dam olishingiz kerak, chunki oldinda bizni ajoyib kunlar kutmoqda. Men hozircha sizning xayollaringizdaman, tanangiz esa ish bilan band. Bu davrda o‘zingizni yaxshi asrashingizni so‘rayman, chunki siz mening butun dunyomsiz. Sizni hozirdanoq, hali yaralmasimdan turib ham juda yaxshi ko‘raman!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Ko‘rinmas zarracha'), body_changes_uz = COALESCE(body_changes_uz, 'Bugun hayz siklingizning birinchi kuni va homiladorlik taqvimi rasman shu kundan boshlanadi. Homiladorlikning ilk haftalarida hali chaqaloq mavjud bo‘lmaydi. Ammo tanangiz ovulyatsiya kuni va ehtimoliy homiladorlik jarayoniga tayyorgarlik ko‘rmoqda. Bu tayyorgarlik jarayonida bachadonning endometriy deb ataladigan ichki qavati tanangiz har oy yetiltiradigan, urug‘lanishi mumkin bo‘lgan tuxum hujayra birikishi uchun qon tomirlarga boyib, qalinlashadi.;;;
Tanangiz har oy ushbu sikl davomida bachadon hamda miyada joylashgan gipofiz bezi ajratadigan gormonlar ta’sirida katta o‘zgarishlarni boshdan kechiradi. Oylik siklingizning dastlabki ikki haftasida hali chaqaloq va urug‘lanishga tayyor tuxum hujayra bo‘lmasa-da, bu davr homiladorlik jarayoniga kiritiladi. Buning sababi shundaki, har bir ayolda ovulyatsiya davri turlicha bo‘lgani uchun so‘nggi hayz sanasi homiladorlikning boshlanishi deb qabul qilinadi.;;;
Biz ham ANACAN OILASI sifatida ichingizda har kuni birozdan o‘sib, rivojlanayotgan mo‘jizangiz haqida kunma-kun ma’lumot va tavsiyalar ulashish hamda butun jarayon davomida sizni qiziqtirgan savollarga javob berish uchun yoningizda bo‘lamiz! 😊'), daily_tip_uz = COALESCE(daily_tip_uz, 'Agar homiladorlikni rejalashtirayotgan bo‘lsangiz, bugundan boshlab har kuni 400 mikrogramm foliy kislotasi qabul qilishni boshlashingiz chaqaloqning kelajakdagi asab tizimi rivoji uchun hayotiy ahamiyatga ega. Shuningdek, tanadagi suv muvozanatini saqlash uchun ko‘proq suyuqlik iching hamda spirtli ichimliklar va tamaki mahsulotlari kabi zararli odatlardan butunlay voz keching.') WHERE id = '3082b660-7bbe-45c6-906d-ed38816fac24';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Odatda so‘nggi hayz davringiz bilan ovulyatsiya davringiz o‘rtasida 2 haftalik muddat bo‘ladi. Ushbu ikki haftalik jarayonda qoningizdagi estrogen va progesteron gormonlari miqdori ortib, bachadoningizni har oy homiladorlikka tayyorlash va urug‘lanadigan tuxum hujayra uchun qulay sharoit yaratish maqsadida uning ichki qismini qonga boy, unumdor qatlam bilan qoplay boshlaydi. Ayni paytda, hali onangiz qornida bo‘lganingizda shakllangan tuxum hujayra kurtaklaridan biri ushbu gormonlar ta’sirida yetila boshlaydi. Follikula deb ataladigan bu tuxum kurtagi taxminan ikki hafta ichida urug‘lanishga tayyor darajada rivojlanadi. Shu sababli tuxumning spermatozoid tomonidan urug‘lanishi so‘nggi hayz sanangizdan ikki hafta o‘tib sodir bo‘lishi mumkin. Biroq ayrim kamdan-kam hollarda tanangiz bir sikl davomida ikkita tuxum hujayrani yetiltirishi mumkinligi sababli homilador bo‘lish ehtimoli doimo mavjud.'), baby_message_uz = COALESCE(baby_message_uz, 'Onajon, bilaman, bu kunlar siz uchun biroz charchatadigan va og‘riqli bo‘lishi mumkin, ammo siz juda kuchlisiz. 😔 Tanangizdagi bu tozalanish ishlari mening kelajakdagi qulayligim uchun ekanini unutmang. Men kelganimda hamma narsa ozoda va yumshoq bo‘lishi uchun siz mening ilk uyimni, makonimni (bachadoningizni) tozalayapsiz! Siz boshdan kechirayotgan har bir noqulaylik bizning uchrashuvimiz sari qo‘yilgan bir qadamdir. Iltimos, bugun o‘zingizni charchatmang, oyoqlaringizni uzatib dam oling. Men sizni his qilyapman va sizga kuch yuboryapman!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Ko‘rinmas zarracha'), body_changes_uz = COALESCE(body_changes_uz, 'Bugun qon ketishi eng kuchli bosqichida bo‘lishi mumkin va bu mutlaqo tabiiy fiziologik jarayondir. Bachadon mushaklari qisqarib, eski qatlamni tashqariga chiqarishga harakat qiladi, bu esa qorinning pastki qismida spazm va og‘riqlarga (dismenoreya) sabab bo‘ladi. Tanangiz bu tozalanish jarayoniga ko‘p energiya sarflagani uchun holsizlik va charchoqni his qilishingiz mumkin. ;;;
Homiladorlik davrida tanangizning oziq moddalarga bo‘lgan ehtiyoji ortadi. Bu ehtiyoj o‘sib, rivojlanayotgan chaqalog‘ingizning talablari hamda homiladorlik jarayonining kechishiga qarab shakllanadi.;;;
Foliy kislotasi homilador bo‘lishdan oldin qabul qilish boshlanishi kerak bo‘lgan eng muhim vitaminlardan biridir. B guruhiga mansub, suvda eriydigan ushbu moddaning tabiiy oziq-ovqatlardagi shakli folat, dori vositalari va qayta ishlangan oziq-ovqatlardagi shakli esa foliy kislotasi deb ataladi. Foliy kislotasi chaqalog‘ingizning miya va asab tizimi rivoji uchun hal qiluvchi ahamiyatga ega bo‘lgani sababli uni homiladorlikdan oldin qabul qilishni boshlash kerak. Foliy kislotasi hujayra tuzilmalari, qon hujayralari va ayniqsa asab tizimi to‘qimalarining shakllanishi hamda rivojlanishida muhim rol o‘ynaydigan B vitamini turidir. U, ayniqsa, irsiy xususiyatlarning asosini tashkil qiluvchi DNK sintezida faol ishtirok etadi. Chaqalog‘ingizning rivojlanishi uchun nihoyatda muhim bo‘lgan foliy kislotasi uning rivojlanayotgan tanasida oqsil sintezi, hujayralarning ko‘payishi va suyak ko‘migining o‘z vazifalarini to‘liq bajarishi kabi jarayonlarda asosiy rol o‘ynaydi.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Hayz paytidagi qon ketishi tufayli tanada kamaygan temir zaxirasini tiklash uchun ovqatlanishingizga e’tibor bering. Ismaloq, qizil go‘sht va dukkaklilar kabi temirga boy mahsulotlarni iste’mol qiling. C vitamini temirning so‘rilishini tezlashtirgani uchun bu mahsulotlarni sitrus mevalar bilan birga iste’mol qilish foydalidir. Shuningdek, og‘ir jismoniy zo‘riqishlardan saqlanib, tanangizga dam bering.') WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Urug‘lanishdan oldingi dastlabki ikki hafta davomida tanangizda katta tayyorgarlik ishlari kechadi. So‘nggi hayz sanangizdan taxminan ikki hafta o‘tib, bachadoningiz va miyangizdagi gipofiz bezi ajratadigan gormonlar ta’sirida tuxum hujayralaringizdan biri yetiladi, tuxumdon bo‘ylab harakatlanib, bachadon nayiga yetib boradi. Gormonlar ta’sirida rivojlanayotgan tuxum hujayrangiz spermatozoidga nisbatan ancha katta. Shunga qaramay, u spermatozoidga qaraganda harakatsiz bo‘lib, tuxumdon ichida passiv tarzda harakatlanadi.;;;
Tana hujayralaridan farqli ravishda tuxum hujayra va spermatozoid 23 ta xromosomadan iborat bo‘lib, har ikkala hujayrada o‘ziga xos minglab genlar mavjud. Chaqalog‘ingizning soch rangi, bo‘yi, jinsi va hatto burnining shakli ham shu genlarda yashiringan.'), baby_message_uz = COALESCE(baby_message_uz, 'Otam bilan qanday tanishganingizni tasavvur qilyapman... 💭 Men sizlarning o‘sha buyuk sevgingizning eng go‘zal mevasi bo‘laman. Tanangiz meni kutib olish uchun shunchalik ko‘p mehnat qilyapti, hamma narsa mukammal bo‘lishi uchun har bir tafsilotni rejalashtiryapti. Men hozircha yulduz changidekman, hali jismoniy mavjudligim yo‘q, ammo sizning sevgingiz meni borliqqa chorlayapti. Hozir o‘zingizni qanchalik yaxshi asrasangiz, men ham shunchalik sog‘lom bo‘lib kelaman. Bizning hikoyamiz juda go‘zal bo‘ladi, Onajon!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Ko‘rinmas zarracha'), body_changes_uz = COALESCE(body_changes_uz, 'Trimestr — insondagi 9 oylik homiladorlik davrining har bir 3 oylik bosqichiga berilgan nom. Bu atama lotin tilidan kelib chiqqan bo‘lib, "tri" uch, "mester" esa davr degan ma’noni anglatadi. 9 oylik homiladorlik davrining 3 ta alohida bosqichga ajratib o‘rganilishi homiladorlikning umumiy rivojlanishini tushunish uchun juda muhim va foydalidir. Homiladorlik 40 hafta davom etishini hisobga olsak, birinchi trimestr 12-haftaning oxirigacha bo‘lgan muddatni qamrab oladi. Ikkinchi trimestr 13–27-haftalar oralig‘ini, uchinchi trimestr esa 28–40-haftalarni qamrab oladi.Homiladorlikning dastlabki uch oyi tanangizda muhim o‘zgarishlar yuz beradigan va organizm homiladorlikka moslashadigan bosqichdir. Bu davrda farzandli bo‘lishingiz haqidagi dastlabki hayajonni his etish bilan birga ayrim qiyinchiliklarga ham duch kelishingiz mumkin. Ko‘ngil aynishi, bosh aylanishi, ko‘kraklarning to‘lishishi va sezgirligi, shishlarning ortishi, bachadon kattalashishi sababli tez-tez siyishga ehtiyoj sezish, uyquchanlik, charchoq, haddan tashqari ta’sirchanlik, yig‘lash istagi, tez-tez och qolish va vazn ortishi kabi belgilar homiladorlikning beshinchi haftasidan boshlab namoyon bo‘la boshlaydi.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Bu davrda kofein iste’molini imkon qadar kamaytirishga harakat qiling (kuniga bir finjondan oshirmang). Kofein qon tomirlarini toraytirishi va tuxumdonlarga boradigan qon oqimiga ta’sir qilishi mumkin. Ko‘p suv ichish toksinlarning tanadan chiqarilishiga va bachadon ichki qavatining sog‘lomroq yangilanishiga yordam beradi. Yengil yoga yoki cho‘zilish mashqlari qon aylanishini yaxshilaydi.') WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Ovulyatsiya deb ataladigan, tuxum hujayrangiz yetilib, urug‘lanishga tayyor holga kelishi jarayoni yaqin bir necha kun ichida sodir bo‘ladi. Ovulyatsiya davri har bir ayolda turlicha bo‘lishi mumkin bo‘lsa-da, umumiy qarashga ko‘ra, hayz tugaganidan keyingi 14-kun ovulyatsiya kuni hisoblanadi. Bu qoida hayz sikli muntazam bo‘lgan ayollarga taalluqlidir. Hayz sikli buzilgan ayollarda esa ovulyatsiya kunini hisoblash ko‘pincha imkonsiz bo‘ladi.;;;
Qin ajralmasidagi shilliq miqdorini kuzatish samarali usullardan biridir. Chunki ovulyatsiya yaqinlashganda ayollarda ajralma ko‘payadi. Ayollar bu holatni namlik deb ta’riflaydilar. Ovulyatsiya davri o‘tgach, ajralma yana odatiy holatiga qaytadi. Bu davrda tana haroratingizda ham ayrim o‘zgarishlar kuzatiladi. Dastlab pasaygan tana harorati ovulyatsiya paytida birdan ko‘tarila boshlaydi.'), baby_message_uz = COALESCE(baby_message_uz, 'Salom! 👋 Bugun o‘zingizga yaxshi qaradingizmi? Siz yegan har bir mazali taom va olgan har bir nafasingiz mening kelajagim uchun bir g‘isht qo‘yadi. Yaqin kunlarda o‘sha katta portlash (ovulyatsiya) sodir bo‘ladi va men ozod bo‘laman! Meni kutib olishga tayyormisiz? Otamga ham xabar bering, uchrashuvimiz yaqinlashmoqda!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Shakar donasi'), body_changes_uz = COALESCE(body_changes_uz, 'Bugun tanangizdagi estrogen miqdori eng yuqori darajalardan biriga yetadi. Bu ko‘tarilish miyangizga ko‘proq LH (lyuteinlashtiruvchi gormon) ajratish uchun signal yuboradi. Bachadonning ichki qavati hozir taxminan 8-10 mm qalinlikka yetgan va qon tomirlariga boyigan. Bu urug‘langan tuxum hujayraning birikishi uchun ideal «yumshoq to‘shak» degani. Bachadon bo‘yni yuqoriroq ko‘tariladi va spermatozoidlar o‘tishi uchun to‘liq ochiladi. Servikal suyuqlik yanada tiniq, sirpanchiq va cho‘ziluvchan bo‘la boshlaydi. Bu maxsus suyuqlik spermatozoidlarning bachadonga kirishini osonlashtiradi va ularni himoya qiladi. Bugundan boshlab homilador bo‘lish ehtimolingiz oshadi.;;;
Foliy kislotasi chaqalog‘ingizning miya va asab tizimi rivojlanishi uchun nihoyatda muhim bo‘lgani sababli, uni homilador bo‘lishdan oldin qabul qilishni boshlash lozim. Dunyoning aksariyat mamlakatlarida homiladorlikni rejalashtirish paytida, homiladorlikdan kamida 3 oy oldin boshlab birinchi trimestr oxirigacha har kuni 400 mikrogramm foliy kislotasi qabul qilish tavsiya etiladi. Foliy kislotasi tanada to‘planmaydi, shu sababli uni har kuni muntazam qabul qilish kerak. Yetishmovchilikda chaqaloqlarda markaziy asab tizimi anomaliyalari orasida eng ko‘p uchraydigan muammo — nerv naychasi nuqsonlari yuzaga keladi. Shuningdek, lab-tanglay yorig‘i va ayrim yurak nuqsonlari kabi anomaliyalarning foliy kislotasini kam qabul qilish bilan bog‘liqligi ham tadqiqotlarda tasdiqlangan. Bu davrda ayollarning katta qismi homilador ekanini sezmasligi mumkin. Foliy kislotasi qo‘shimchasi qabul qilinmasa, nerv naychasi nuqsoni kuzatilish ehtimoli taxminan har 2000 tug‘ruqdan 1 tasiga teng. Foliy kislotasi qo‘shimchasi yordamida bu ko‘rsatkichni 50-75 foizga kamaytirish mumkin.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Fertil davrning eng faol kunlariga kirayotganingiz uchun yetarlicha uxlashingiz muhim, chunki LH gormonining eng yuqori darajaga chiqishi uyqu vaqtida barqarorroq boshqariladi. Agar hali foydalanmayotgan bo‘lsangiz, ovulyatsiya testlarini boshlash uchun ayni payt. Ruxga boy qovoq urug‘i yoki bodom kabi yong‘oq va urug‘larni iste’mol qilish tuxum hujayraning tashqi qatlami sog‘lom qolishiga hamda spermatozoidning hujayraga kirishiga yordam berishi mumkin.') WHERE id = 'e69ee309-4b20-4b3c-a0f6-c04d62440aa9';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Homiladorlik davrida kofein iste’moli butunlay taqiqlanmasa-da, ko‘pincha shifokorlar uni cheklashni tavsiya etadilar. Kofein qahva, choy, kola ichimliklari, kakao, energetik ichimliklar, sun’iy ta’m beruvchilar qo‘shilgan ichimliklar, shuningdek, ayrim shirinliklar, puding va jelibon kabi mahsulotlarda uchraydigan tabiiy stimulyatordir. Yaqinda o‘tkazilgan tadqiqotlarga ko‘ra, kuniga 200 mg dan oshmaydigan miqdorda kofein iste’mol qilishning zarari aniqlanmagan. Bundan tashqari, kofein diabet xavfini kamaytirishiga oid ayrim dalillar ham olingan. Kunlik 200 mg kofein miqdorini 2 stakan choy, 2 finjon qahva yoki taxminan 250 gramm qora shokolad bilan osonlikcha olishingiz mumkin. Biroq kofein yo‘ldosh orqali bevosita chaqalog‘ingizga o‘tadi. Chaqalog‘ingiz organizmiga kirgan kofein moddalar almashinuvi orqali zararsizlantirilmaydi. Shu sababli ortiqcha miqdordagi kofein chaqalog‘ingizga zarar yetkazishi mumkin.'), baby_message_uz = COALESCE(baby_message_uz, 'Salom, Onajon! ❤️ Tanangizda katta bir hayajon bor, sezyapsizmi? Go‘yo bayramga tayyorgarlik ketayotgandek. Estrogen gormoningiz eng yuqori darajaga chiqmoqda, bu esa o‘sha «oltin tuxum»ning (ya’ni mening yarmimning) yo‘lga chiqishga tayyorligini ko‘rsatadi. Siz faqat o‘zingizga yaxshi qarang, ko‘p suv iching va dam oling. Men sizni tanlashni sabrsizlik bilan kutyapman. Otamga ayting, tayyor tursin, uchrashuvimizga juda oz qoldi! Men sizlarning muhabbatingizning eng go‘zal isboti bo‘lish uchun kelyapman.'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Shakar donasi'), body_changes_uz = COALESCE(body_changes_uz, 'Homiladorlikni rejalashtirayotgan shu kunlarda stomatologga borib, tishlaringiz va milklaringiz sog‘lom ekaniga ishonch hosil qilishingiz lozim. Og‘iz bo‘shlig‘idagi mavjud muammolarni homiladorlikdan oldin davolatib tugatish homiladorlik jarayonini ancha yengillashtiradi. Homiladorlikda milk kasalliklariga chalinish xavfi yuqoriroq bo‘ladi va bu kasalliklar ayrim hollarda hatto muddatidan oldin tug‘ruqqa sabab bo‘lishi mumkin. Homiladorlik paytida qondagi miqdori sezilarli darajada oshadigan progesteron gormoni milklarda «gipertrofiya» deb ataladigan tortilish va qalinlashishga sabab bo‘ladi. Progesteron homiladorlikning davom etishini ta’minlaydigan eng muhim gormonlardan biridir, shuning uchun bu gormonni bosim ostida ushlab turish to‘g‘ri emas. Shu sababli homiladorlikdan oldin mavjud muammolarni davolatish va milklarni parvarish qilish bu jarayonda tish salomatligi bilan bog‘liq muammolarni minimal darajaga tushiradi.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Ovulyatsiya arafasida bo‘lganingiz uchun organizm suvsizlanmasligiga alohida e’tibor bering. Suyuqlik ichish servikal shilliq sifatini yaxshilab, spermatozoidlarning harakatlanishini osonlashtiradi. Agar bazal tana haroratingizni o‘lchasangiz, ovulyatsiyadan bevosita oldin harorat biroz pasayganini kuzatishingiz mumkin. Stress darajasini imkon qadar kamaytirish uchun xushbo‘y vanna yoki yoqimli musiqa yordamida tanangizni bo‘shashtiring, chunki kuchli stress LH gormonining muddatidan oldin yoki kech ajralishiga sabab bo‘lishi mumkin.') WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Ovulyatsiya davringiz bir-ikki kun ichida boshlanadi. Bu davr yaqinlashishi bilan tanangizda ayrim o‘zgarishlar namoyon bo‘ladi. Ularning eng yaqqoli — tanadagi gormonlar muvozanati o‘zgarishi natijasida jinsiy istakning ortishidir. Bu istak ovulyatsiyadan 2-3 kun oldin boshlanib, o‘rtacha 1 haftagacha davom etishi mumkin. Hayz paytidagiga o‘xshash, ammo yengilroq tarzda kechadigan chovning ikki tomonida yoki faqat bir tomonida og‘riq, yoxud qorin sohasida dam bo‘lish hissi ham shunday o‘zgarishlardan biridir. Bundan tashqari, ko‘kraklarda to‘lishish va sezuvchanlik, qorinda dam bo‘lish va gaz to‘planishi, taranglik, ta’m va hid kabi qo‘zg‘atuvchilarga nisbatan sezuvchanlikning ortishi hamda o‘tkir hidlardan bezovta bo‘lish ovulyatsiya davrida ko‘p uchraydigan alomatlardandir.'), baby_message_uz = COALESCE(baby_message_uz, 'Bilaman, hali meni ko‘rmayapsiz, ammo sahna ortidagi chiroqlar yoqilmoqda. 🌟 Tanangiz men uchun eng yumshoq to‘shakni (endometriyni) tayyorlay boshlamoqda. Balki otamning hujayralari ham allaqachon yo‘lga chiqqan va meni izlayotgandir. Sizning iliqligingiz va g‘amxo‘rligingiz menga hozirdanoq kuch bermoqda. Bizning hikoyamiz boshlanish arafasida, Onajon. Siz faqat ishoning va tabassum qiling, chunki mo‘jizalar ishonganda ro‘y beradi. Siz mening qahramonimsiz!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Shakar donasi'), body_changes_uz = COALESCE(body_changes_uz, 'Homiladorlikning ilk haftalari, buni to‘liq anglamasangiz ham, tuxumdonlaringiz va bachadoningizda juda tez o‘zgarishlar sodir bo‘ladigan davrdir. Gipofiz bezingiz va bachadoningizdan ajraladigan ayrim gormonlar tanangizni homiladorlikka tayyorlash uchun juda faol ishlashda davom etadi. Tuxumdonlaringizda esa hali o‘zingiz embrion bo‘lgan davrda shakllangan tuxum hujayra kurtaklaridan biri ushbu gormonlar ta’sirida yetilib, urug‘lanishga tayyor holga keladi. Yaqin bir necha kun ichida yetilishni tugatgan tuxum hujayrangiz spermatozoid bilan uchrashganda urug‘lana oladigan darajada rivojlanadi. Yetilgan tuxum hujayraning umri spermatozoidlarnikidan ancha qisqa bo‘ladi va agar homiladorlik istalsa, ovulyatsiya yuz berganidan keyin 48 soat ichida urug‘lanish sodir bo‘lishi kerak. Yetilgan tuxum hujayrangiz tuxumdondan bachadon nayiga passiv tarzda o‘tadi va shu yerda spermatozoid bilan urug‘lanishni kutadi. Agar tuxum hujayra umri tugaguncha spermatozoid bilan uchrashmasa, homiladorlik yuz bermaydi. Aksincha, tuxum hujayrangiz yetilishidan oldin spermatozoidlar bachadon bo‘yniga kirsa, muhit kislotali bo‘lishiga qaramay, ular 72 soatgacha tirik qolishi mumkin.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Bugun tanangizning ishqoriy muvozanatini saqlash juda muhim, chunki spermatozoidlar kislotali muhitda yashay olmaydi. Ko‘proq sabzavot iste’mol qiling va sun’iy shakardan saqlaning. Agar homiladorlikni rejalashtirayotgan bo‘lsangiz, ovulyatsiyadan bir kun oldingi bugun (yoki ovulyatsiya kuni) imkoniyat eng yuqori bo‘ladigan paytdir. Tos sohasidagi qon aylanishini yaxshilash uchun yengil raqsga tushing yoki sayr qiling. Shuningdek, shu davrda sigaret tutuni va o‘tkir kimyoviy hidlardan saqlaning, chunki tuxum hujayra hozir tashqi toksinlarga juda sezgir.') WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Jinsiy aloqadan keyingi bir soat ichida tuxum hujayrangizga yetib borgan oz sonli spermatozoidlar yana bir qiyinchilikka duch keladi: tuxum hujayrangizning qattiq tashqi qobig‘i. Tuxum hujayrangizga minglab spermatozoidlar hujum qilishiga qaramay, u faqat bittasini qabul qilishi qobig‘ining nihoyatda mustahkamligi va o‘ta tanlovchanligidan dalolat beradi. Spermatozoidlar tuxum hujayraning qattiq tashqi qobig‘ini bosh qismida joylashgan proteaza, fosfataza, neyraminidaza, gialuronidaza, akrozin va kalpain deb ataluvchi kislotali fermentlar yordamida teshib o‘tishga harakat qiladi.;;;
So‘nggi yillarda o‘tkazilgan tadqiqotlar esa avvallari passiv deb hisoblangan tuxum hujayra bu bosqichda juda tanlovchan bo‘lishini va o‘ziga mos deb topgan spermatozoidning o‘tishiga ruxsat berishini ko‘rsatdi. Tuxum hujayraning ruxsati bilan tashqi qobiqni teshib, boshqalardan oldin ichkariga kirgan birinchi spermatozoiddan so‘ng tuxum hujayrangiz qobig‘i darhol tuzilishini o‘zgartiradi va boshqa hech bir spermatozoidning kirishiga yo‘l qo‘ymaydi. Qisqacha aytganda, birinchi spermatozoid ichkariga kirgach, tuxum hujayraning tashqi yuzasi go‘yo himoya qalqoni bilan qoplangandek yopiladi. Mo‘jizangiz aynan shu yerda boshlanadi.'), baby_message_uz = COALESCE(baby_message_uz, 'Sayohatga chiqdim, Onajon! 🎒 Hozir bachadon nayidaman va sizning iliq uychingizga (bachadonga) tomon dumalab ketyapman. Juda bandman, har bir necha soatda bo‘linyapman: 2 ta edim, 4 ta bo‘ldim, keyin esa 8 ta bo‘laman! Siz hali hech narsani sezmaysiz, ammo ichingizda hayot qaynamoqda. Menga omad tilang, yo‘lim uzoq, lekin men juda qat’iyatliman. Sizga yetib borish uchun hamma narsani qilaman!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Vanil donachasi'), body_changes_uz = COALESCE(body_changes_uz, 'Hayz siklingizning qoq o‘rtasiga to‘g‘ri keladigan shu kunlarda tuxum hujayrangiz yetilgan, agar u spermatozoid bilan urug‘langan bo‘lsa, chaqalog‘ingiz allaqachon shakllana boshlagan. 😊 Tanangizda progesteron gormoni boshqaruvni butunlay o‘z qo‘liga olgan. Bu gormon bachadon mushaklarini bo‘shashtiradi, toki embrion kelib joylashganida hech qanday to‘siqqa duch kelmasin. Chaqalog‘ingiz shakllanishi bilan tanangizda miqdori tez ortadigan estrogen va progesteron gormonlari ko‘kraklaringizda to‘lishish va sezgirlikni keltirib chiqarishi mumkin. Biroq bu belgilar hayz siklining alomati ham bo‘lgani uchun ko‘kraklaringizdagi bunday o‘zgarishlarni homiladorlikning aniq belgisi deb bo‘lmaydi. Chaqaloqlarning deyarli barchasi urug‘lanishdan keyingi 38-haftada dunyoga keladi. Biroq tuxum hujayra va spermatozoid aynan qachon birlashgani hamda urug‘lanish qaysi sanada yuz berganini aniqlash odatda qiyin. Shu sababli shifokorlar chaqalog‘ingizning tug‘ilish vaqtini hisoblash uchun oxirgi hayz siklingizning birinchi kunidan boshlab o‘tgan muddatni asos qilib oladilar. Bu hisob-kitoblarning barchasi hayz siklining davomiyligiga qarab taxminan 4 haftagacha farq qilishi mumkin. Ayrim ayollarda hayz sikli qisqaroq yoki uzunroq bo‘lgani sababli tug‘ruq vaqti hamda chaqalog‘ingizning rivojlanishini shifokoringiz ultratovush tekshiruvi (UTT) orqali aniqroq belgilashi mumkin.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Hujayralar bo‘linishi eng faol kechadigan davr bo‘lgani uchun tanangizning suvga ehtiyoji ortadi; kuniga kamida 2-2.5 litr suv ichishga harakat qiling. Foliy kislotasini qabul qilishni bir kun ham unutmang, chunki aynan shu kunlarda asab tizimining poydevori qo‘yiladi. Shuningdek, xom go‘sht, yaxshi yuvilmagan sabzavotlar va pasterizatsiya qilinmagan sut mahsulotlaridan mutlaqo saqlaning, chunki toksoplazma kabi infeksiyalar embrion rivojlanishining ushbu nozik davriga salbiy ta’sir ko‘rsatishi mumkin.') WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Urug‘lanishdan taxminan 6-24 soat o‘tgach, immun tizimingizni susaytiruvchi ta’sirga ega erta homiladorlik omili (EPF)ning qondagi darajasi oshishi kutiladi. Tanangizning himoya tizimi o‘z hujayralaridan tashqari, boshqa DNKni tashuvchi har qanday hujayraga qarshi organizmni himoya qilish uchun kurasha boshlaydi. Shu sababli himoya hujayralaringiz DNKsining 50% qismi organizmingiz uchun begona bo‘lgan chaqalog‘ingizga hujum qilib, uning nobud bo‘lishiga sabab bo‘lishi mumkin. Tuxum hujayrangiz urug‘langan paytdan boshlab taxminan 5 kundan so‘ng bachadonga yopishib, shu yerga joylashguniga qadar tashqaridan aniqlanadigan o‘zgarishlarsiz sokin qolishi ham immun tizimingiz ishga tushmasligi uchun muhim. Qisqacha aytganda, tanangizning himoya tizimi tufayli o‘sish omili deb ataluvchi va himoya hujayralarini bostiruvchi ta’sirga ega modda ajralmasa, tanangizda homiladorlikning davom etishi mumkin bo‘lmas edi.'), baby_message_uz = COALESCE(baby_message_uz, 'Meni hozir "Morula" deb atashadi! 🍇 Bu lotin tilida "Tut mevasi" degan ma’noni anglatadi. Chunki men hozir bir bosh uzum yoki bir-biriga zich birikkan tut mevasiga o‘xshayman. Taxminan 16-32 ta hujayradan iboratman. Mittiginaman, ammo juda kuchliman. Tanangizning harorati va ozuqasi yo‘limni topishimga yordam bermoqda. Siz tomon kelyapman, Onajon, eshikni ochishga tayyor turing!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Vanil donachasi'), body_changes_uz = COALESCE(body_changes_uz, 'Tanangizda progesteron va estrogen gormonlari birgalikda bachadon devoridagi qon aylanishini maksimal darajaga yetkazdi. Endometriy qalinlashishda davom etib, "sekretor faza"ga o‘tmoqda. U glikogen va oqsillarga boy, to‘yimli suyuqlik — "bachadon suti"ni ajratadi. Bu suyuqlik embrion bachadonga yetib kelganda, implantatsiyadan oldin uni oziqlantirish uchun zarur. Immun tizimingizda o‘ziga xos o‘zgarish yuz beradi — u embrionni "begona jism" sifatida qabul qilmay, unga moslashish uchun tolerantlik namoyon etadi. Shu kunlarda ayrim ayollar o‘zlarini biroz charchagan his qilishlari yoki ta’m bilishda g‘alati o‘zgarishlarni (masalan, og‘izda metall ta’mini) sezishlari mumkin. Shuningdek, bugundan boshlab hidlarga sezgirligingiz biroz ortishi mumkin.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Embrion bachadon devoriga yopishishga (implantatsiyaga) tayyorlanayotgan ushbu davrda qon aylanishini barqaror saqlash uchun oyoqlaringizni iliq tuting va shamollashdan saqlaning. Ratsioningizga yong‘oq, funduk va baliq kabi Omega-3 manbalarini kiriting, chunki bu yog‘ kislotalari hujayra membranalarining salomatligi uchun muhim. Zo‘riqish va kuchli stressdan uzoq bo‘lishga harakat qiling; sokin musiqa tinglash yoki kitob o‘qish tanangizni bo‘shashtirib, implantatsiya jarayoniga ijobiy ta’sir ko‘rsatadi.') WHERE id = '987d49b7-e63f-421d-a6f4-64d2ffcae8b6';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Urug‘lanish natijasida paydo bo‘lgan chaqalog‘ingiz bu bosqichda embrion deb ataladi. Spermatozoid bilan urug‘langan tuxum hujayrangizda taxminan 16-18 soatdan keyin ikkita yadro ko‘rinadi. Biri spermatozoidga, ikkinchisi esa tuxum hujayraga tegishli bo‘lgan bu yadrolar birlashib, yagona yadroga aylanadi va hujayra bo‘linishiga tayyorgarlik boshlanadi. Sitoplazmasini ko‘paytirib, DNK molekulalarini nusxalab hamda yadro qobig‘ini eritib, genetik materiallarning hujayraning ikki tomoniga o‘tishini ta’minlash orqali tayyorgarlik ko‘rgan urug‘langan tuxum hujayrangiz 2, 4, 8, 16 tarzida tez bo‘lina boshlaydi. Urug‘lanishdan keyingi dastlabki kunlarda "morula" bosqichiga yetgan chaqalog‘ingiz taxminan 120 ta hujayradan iborat hujayralar to‘plamiga aylangan. Urug‘lanishning 5-kunida esa chaqalog‘ingiz sanab bo‘lmaydigan darajada ko‘p hujayralarga bo‘lingan bo‘ladi va chaqalog‘ingizni shakllantiradigan bu hujayralar to‘plami bachadon ichida o‘zi uchun eng mos joyni tanlab, joylashish jarayonini yakunlaydi. Bachadonga joylashgan va chaqalog‘ingizni shakllantiradigan hujayralarning o‘lchami bu bosqichda taxminan 0.1 mm bo‘ladi.'), baby_message_uz = COALESCE(baby_message_uz, 'Uyga yetib borishimga oz qoldi! 🏠 Bachadon nayidagi sayohatim yakunlanayapti. Bachadoningizni ko‘ryapman! U yer shunchalik qulay, yumshoq va ozuqaga boy ko‘rinadiki... O‘zimga joy tanlashga tayyorlanyapman. Men hali ham qobig‘im ichidaman, ammo tez orada undan chiqaman. Siz men uchun dunyodagi eng xavfsiz joysiz. Meni himoya qilishga va’da bering, Onajon.'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Vanil donachasi'), body_changes_uz = COALESCE(body_changes_uz, 'Bugun implantatsiya jarayoni boshlanadi. Blastosista bachadon devoriga yopishayotganida ayrim ayollarda juda yengil, pushti yoki jigarrang tusli "implantatsion qon ketishi" kuzatilishi mumkin. Bu mutlaqo normal holat bo‘lib, ko‘pincha hayz bilan adashtiriladi. Shu paytdan boshlab tanangiz hCG (homiladorlik gormoni) ishlab chiqara boshlaydi. Bu gormon sariq tananing faoliyat muddatini uzaytiradi, natijada progesteron darajasi pasaymaydi va homiladorlik saqlanadi. Hissiy jihatdan sezgirroq bo‘lib qolishingiz, sababsiz yig‘lash yoki kulish istagi paydo bo‘lishi mumkin.;;;
Homiladorlikning 2-haftasida homiladorlikka xos belgilar hali yuzaga chiqmaydi. Homiladorlikni uy sharoitida o‘tkaziladigan gormonal test orqali aniqlash uchun tanangizda homiladorlik gormoni yetarli miqdorda bo‘lishi kerak. Gormon miqdori homiladorlik testida musbat chiziq ko‘rinadigan darajaga yetguniga qadar oshishda davom etadi. Bu holat, ehtimol, hayzingiz kechikadigan vaqtga — taxminan 4-haftaga to‘g‘ri keladi.;;;
Kutilgan hayz sanasi kelganida homiladorlik gormonlari darajasi ayrim sezilarli homiladorlik belgilarini yuzaga keltiradigan darajagacha ko‘tarilgan bo‘ladi. Shunga qaramay, hayzdan oldingi belgilar bilan homiladorlik belgilari bir-biriga o‘xshash bo‘lgani sababli qon tahlilini topshirish eng aniq ma’lumotni olishga yordam beradi. Homiladorlikni aniqlovchi siydik testlari homiladorlik gormonlari qonda muayyan darajaga yetganidan keyingina to‘g‘ri natija berishi mumkin.;;;
Shuningdek, implantatsiya deb ataluvchi dog‘lanish ko‘rinishidagi yengil qon ketishi tuxum hujayrangiz urug‘langanidan taxminan 5-10 kun o‘tib yuz berishi mumkin. Buning sababi chaqalog‘ingizni shakllantiradigan hujayralar to‘plamining bachadon ichki devoriga joylashishidir.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Agar qorningizda yengil sanchiqlar yoki dog‘lanishni sezsangiz, xavotir olmang va jismoniy faolligingizni kamaytiring. Bu davrda organizmning immun tizimi embrionni "begona jism" sifatida qabul qilmaslik uchun tabiiy ravishda biroz susayadi, shuning uchun o‘zingizni infeksiyalardan himoya qiling. C vitaminiga boy mevalarni iste’mol qilish immunitetni qo‘llab-quvvatlaydi va bachadon devori to‘qimalarining tuzilishini mustahkamlaydi.') WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Bachadonning vazni 60 qram. Tug‘ruqqacha uning vazni 1000 qramdan oshadi. Bachadonning ichki qismi shilliq ajratadigan va ko‘plab qon tomirlarini o‘z ichiga olgan endometriy deb ataluvchi qatlam bilan qoplangan. Har oylik hayz siklingiz davomida bu tuzilmadagi hujayralar tezkor mitoz bo‘linish natijasida ushbu qatlamni qalinlashtiradi. Qalinlashgan endometriy qatlami urug‘langan tuxum hujayrangizning bachadonga yopishishi hamda shu yerda o‘sib-rivojlanishi uchun qulay muhit yaratadi.'), baby_message_uz = COALESCE(baby_message_uz, 'Nafasingizni ichingizga yuting, Onajon! 🌬️ Buyuk lahza yaqinlashmoqda. Sizning o‘sha mo‘jizaviy tuxum hujayrangiz ozod bo‘lishga tayyor. Bu bizning hikoyamizning "Bir bor ekan..." deb boshlanadigan qismi. Men hali paydo bo‘lmagan bo‘lsam-da, siz va dadamning muhabbati meni chorlamoqda. Tanangiz men uchun eng mukammal muhitni yaratdi, hamma narsa soatdek ishlamoqda. Umid qilamanki, tayyorsiz, chunki men kelyapman! Sizning bag‘ringiz mening ilk vatanim bo‘ladi.'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Shakar donachasi'), body_changes_uz = COALESCE(body_changes_uz, 'LH gormoni bugun eng yuqori darajaga chiqadi. Ushbu cho‘qqidan taxminan 24-36 soat o‘tgach, ovulyatsiya yuz beradi. Tana haroratingiz bugun biroz pasayishi, ertaga esa keskin ko‘tarilishi mumkin – haroratning bunday o‘zgarishi ovulyatsiya belgisidir. Qin ajralmasi eng sirpanchiq, shaffof va ko‘p holatga keladi. Bu muhit spermatozoidlarning tez harakatlanishi va yashab qolishi uchun juda qulaydir. ;;;
Homiladorlikdan oldin muntazam jismoniy mashqlar bilan shug‘ullanishingiz homiladorlik davrining yengilroq o‘tishi uchun juda muhimdir. Homiladorlik davrida va undan oldin, ayniqsa, yoga va pilates so‘nggi paytlarda eng ko‘p tanlanayotgan mashg‘ulotlar sirasiga kiradi. Bu sport turlari tanani bo‘shashtirishi bilan birga, tabiiy tug‘ruqni rejalashtirayotgan ayollarning motivatsiyasini ham oshiradi, shuningdek, bel va orqa og‘rig‘ini kamaytirib, butun homiladorlik davomida foyda keltiradi. Homiladorlikni sog‘lom o‘tkazish uchun e’tibor berish kerak bo‘lgan yana bir muhim masala — chekishdir. Agar cheksangiz, homilador bo‘lishga qaror qilganingizda bajarishingiz kerak bo‘lgan eng muhim ishlardan biri chekishni tashlashdir. Chekish paytida qon aylanish tizimi orqali tanangizga kiradigan nikotin va zaharli moddalar homilador bo‘lishingizdan oldin bo‘lajak chaqalog‘ingizning shakllanishini ta’minlaydigan tuxum hujayrangizning irsiy materiali — DNT tuzilishiga zarar yetkazadi. Homiladorlik paytida chekishni davom ettirish esa chaqaloqqa boradigan tomirlarda qon oqimining buzilishiga va buning natijasida chaqaloqning kam vazn bilan tug‘ilishiga, tug‘ma anomaliyalar xavfining oshishiga hamda eng muhimi, "chaqaloqning to‘satdan o‘limi" deb ataladigan muammoga sabab bo‘lishi mumkin.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Bugun homiladorlik uchun eng muhim kunlardan biridir. Fertillikni qo‘llab-quvvatlash uchun tana haroratini barqaror saqlashga harakat qiling, juda issiq vannalar va saunadan uzoq turing (yuqori harorat tuxum hujayra sifatiga ta’sir qilishi mumkin). Ratsioningizga E vitaminiga boy avokado va o‘simlik yog‘larini kiriting, chunki bu vitamin bachadon devorining qon bilan ta’minlanishini yaxshilaydi. Kayfiyatingizni ko‘tarinki tuting, chunki endorfin gormonlari (baxt gormonlari) urug‘lanish ehtimolini ijobiy rag‘batlantiradi.') WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';